let UPSTREAM_TIMEOUT_FIND_PRODUCTS_MULTI_MS = Math.max(
  1500,
  Math.min(configuredFindProductsMultiTimeoutMs, FIND_PRODUCTS_MULTI_TIMEOUT_HARD_CEILING_MS),
);
if (
  !FIND_PRODUCTS_MULTI_TIMEOUT_ALLOW_UNSAFE_LOWER &&
  UPSTREAM_TIMEOUT_FIND_PRODUCTS_MULTI_MS < FIND_PRODUCTS_MULTI_TIMEOUT_SAFE_MIN_MS
) {
  logger.warn(
    {
      configured_timeout_ms: configuredFindProductsMultiTimeoutMs,
      enforced_timeout_ms: FIND_PRODUCTS_MULTI_TIMEOUT_SAFE_MIN_MS,
      hint: 'Set UPSTREAM_TIMEOUT_FIND_PRODUCTS_MULTI_ALLOW_UNSAFE_LOWER=true to bypass this floor.',
    },
    'UPSTREAM_TIMEOUT_FIND_PRODUCTS_MULTI_MS is below safe floor; clamping to reduce timeout-induced empty results',
  );
  UPSTREAM_TIMEOUT_FIND_PRODUCTS_MULTI_MS = FIND_PRODUCTS_MULTI_TIMEOUT_SAFE_MIN_MS;
}
const UPSTREAM_TIMEOUT_FIND_PRODUCTS_RETRY_MS = parseTimeoutMs(
  process.env.UPSTREAM_TIMEOUT_FIND_PRODUCTS_RETRY_MS,
  Math.min(
    UPSTREAM_TIMEOUT_SLOW_MS,
    Math.max(UPSTREAM_TIMEOUT_FIND_PRODUCTS_MS * 2, 9000),
  ),
);
const UPSTREAM_TIMEOUT_FIND_PRODUCTS_MULTI_RETRY_MS = parseTimeoutMs(
  process.env.UPSTREAM_TIMEOUT_FIND_PRODUCTS_MULTI_RETRY_MS,
  Math.min(
    UPSTREAM_TIMEOUT_SLOW_MS,
    Math.max(
      UPSTREAM_TIMEOUT_FIND_PRODUCTS_MULTI_MS + 1800,
      FIND_PRODUCTS_MULTI_TIMEOUT_SAFE_MIN_MS + 1000,
      8000,
    ),
  ),
);
const UPSTREAM_RETRY_FIND_PRODUCTS_MULTI_ON_TIMEOUT =
  String(process.env.UPSTREAM_RETRY_FIND_PRODUCTS_MULTI_ON_TIMEOUT || '').toLowerCase() === 'true';
const CHECKOUT_RETRY_MAX_ATTEMPTS = parsePositiveInt(
  process.env.CHECKOUT_RETRY_MAX_ATTEMPTS,
  2,
  { min: 1, max: 5 },
);
const CHECKOUT_RETRY_BASE_MS = parsePositiveInt(
  process.env.CHECKOUT_RETRY_BASE_MS,
  140,
  { min: 50, max: 1000 },
);
const CHECKOUT_RETRY_MAX_MS = parsePositiveInt(
  process.env.CHECKOUT_RETRY_MAX_MS,
  500,
  { min: 100, max: 5000 },
);
const BACKEND_OWNED_PAYMENT_STATUSES = new Set([
  'processing',
  'paid',
  'completed',
  'succeeded',
]);
const CLIENT_OWNED_PAYMENT_STATUSES = new Set([
  'requires_action',
]);

const TERMINAL_FAILURE_PAYMENT_STATUSES = new Set([
  'payment_failed',
  'cancelled',
  'refunded',
  'partially_refunded',
]);
const PROTOTYPE_POLLUTION_KEYS = new Set(['__proto__', 'prototype', 'constructor']);
const DIRECT_MERCHANT_PSP_PAYMENT_METHOD_TYPES = new Set([
  'card',
  'credit_card',
  'debit_card',
  // Despite the name of this set, this route goes to the backend's PSP-initiation
  // endpoint. `stripe_checkout` must stay here so pure MCP can request a hosted
  // Stripe Checkout redirect instead of the Pivota-hosted checkout-intent route.
  'stripe_checkout',
  'stripe_checkout_session',
]);
const SUBMIT_PAYMENT_CARD_METHOD_SAFE_FIELDS = [
  'type',
  'payment_method_type',
  'paymentMethodType',
  'payment_method_id',
  'paymentMethodId',
  'payment_method_token',
  'paymentMethodToken',
  'card_token',
  'cardToken',
  'card_id',
  'cardId',
  'token',
  'nonce',
  'source',
  'source_id',
  'sourceId',
  'brand',
  'network',
  'last4',
  'exp_month',
  'expMonth',
  'exp_year',
  'expYear',
  'expiry_month',
  'expiryMonth',
  'expiry_year',
  'expiryYear',
  'cardholder_name',
  'cardholderName',
  'name',
  'billing_details',
  'billingDetails',
  'billing_address',
  'billingAddress',
];
const ADYEN_RESULT_CODE_PAYMENT_STATUSES = Object.freeze({
  authorised: 'paid',
  refused: 'payment_failed',
  error: 'payment_failed',
  cancelled: 'payment_failed',
  received: 'processing',
  pending: 'processing',
  identifyshopper: 'requires_action',
  challengeshopper: 'requires_action',
  redirectshopper: 'requires_action',
  presenttoshopper: 'requires_action',
});

function normalizeSubmitOwner(rawValue) {
  const token =
    typeof rawValue === 'string'
      ? rawValue.trim().toLowerCase()
      : rawValue != null
      ? String(rawValue).trim().toLowerCase()
      : '';
  if (!token) return null;
  if (
    token === 'external_button' ||
    token === 'component' ||
    token === 'redirect' ||
    token === 'unsupported'
  ) {
    return token;
  }
  return null;
}

function inferSubmitOwnerFromActionType(actionType) {
  if (actionType === 'stripe_client_secret') return 'external_button';
  if (actionType === 'adyen_session') return 'component';
  if (actionType === 'redirect_url') return 'redirect';
  if (actionType === 'checkout_session') return 'unsupported';
  return null;
}

function inferComponentKindFromActionType(actionType) {
  if (actionType === 'stripe_client_secret') return 'stripe_payment_element';
  if (actionType === 'adyen_session') return 'adyen_dropin';
  if (actionType === 'checkout_session') return 'checkout_embedded';
  return null;
}

function normalizeSubmitPaymentAction(paymentAction) {
  if (!isPlainObject(paymentAction)) return paymentAction || null;
  const submitOwner = normalizeSubmitOwner(paymentAction.submit_owner);
  const componentKind = firstNonEmptyString(paymentAction.component_kind);
  const supportedInShoppingUi =
    typeof paymentAction.supported_in_shopping_ui === 'boolean'
      ? paymentAction.supported_in_shopping_ui
      : undefined;

  return {
    ...paymentAction,
    ...(submitOwner ? { submit_owner: submitOwner } : {}),
    ...(componentKind ? { component_kind: componentKind } : {}),
    ...(typeof supportedInShoppingUi === 'boolean'
      ? { supported_in_shopping_ui: supportedInShoppingUi }
      : {}),
  };
}

function normalizeSubmitPaymentStatus(rawStatus) {
  const statusString =
    typeof rawStatus === 'string'
      ? rawStatus.trim()
      : rawStatus != null
      ? String(rawStatus).trim()
      : '';
  if (!statusString) {
    return {
      payment_status: 'unknown',
      payment_status_raw: null,
    };
  }
  const normalized = statusString.toLowerCase();
  const aliases = {
    requires_payment_method: 'requires_action',
    requires_confirmation: 'requires_action',
    completed: 'paid',
    succeeded: 'paid',
    success: 'paid',
    settled: 'paid',
    failed: 'payment_failed',
    canceled: 'cancelled',
  };
  const canonical = aliases[normalized] || normalized;
  if (
    BACKEND_OWNED_PAYMENT_STATUSES.has(canonical) ||
    CLIENT_OWNED_PAYMENT_STATUSES.has(canonical) ||
    TERMINAL_FAILURE_PAYMENT_STATUSES.has(canonical)
  ) {
    return {
      payment_status: canonical,
      payment_status_raw: null,
    };
  }
  return {
    payment_status: 'unknown',
    payment_status_raw: statusString,
  };
}

function resolveSubmitPaymentStatusCandidate(upstreamPayload = {}) {
  const topLevelStatus =
    upstreamPayload.payment_status != null
      ? upstreamPayload.payment_status
      : upstreamPayload.status;
  const nestedStatus =
    upstreamPayload?.payment?.payment_status != null
      ? upstreamPayload.payment.payment_status
      : upstreamPayload?.payment?.status;
  return topLevelStatus != null ? topLevelStatus : nestedStatus;
}

function normalizeAdyenResultCodePaymentStatus(resultCode) {
  const token =
    typeof resultCode === 'string'
      ? resultCode.trim().toLowerCase()
      : resultCode != null
      ? String(resultCode).trim().toLowerCase()
      : '';
  if (!token) return null;
  return ADYEN_RESULT_CODE_PAYMENT_STATUSES[token] || 'requires_action';
}

function applyAuthoritativeAdyenPaymentStatus(upstreamPayload = {}, resultCode = null) {
  const adyenPaymentStatus = normalizeAdyenResultCodePaymentStatus(resultCode);
  if (!adyenPaymentStatus) return upstreamPayload;

  const existingStatus = normalizeSubmitPaymentStatus(
    resolveSubmitPaymentStatusCandidate(upstreamPayload),
  );
  const paymentStatus =
    adyenPaymentStatus === 'paid' &&
    TERMINAL_FAILURE_PAYMENT_STATUSES.has(existingStatus.payment_status)
      ? existingStatus.payment_status
      : adyenPaymentStatus;
  const nestedPayment = isPlainObject(upstreamPayload?.payment)
    ? {
        ...upstreamPayload.payment,
        status: paymentStatus,
        payment_status: paymentStatus,
      }
    : upstreamPayload?.payment;

  return {
    ...upstreamPayload,
    status: paymentStatus,
    payment_status: paymentStatus,
    ...(nestedPayment ? { payment: nestedPayment } : {}),
  };
}

function pickOwnFields(source = {}, fields = []) {
  const output = {};
  if (!isPlainObject(source)) return output;
  for (const field of fields) {
    if (Object.prototype.hasOwnProperty.call(source, field)) {
      output[field] = source[field];
    }
  }
  return pruneEmptyFields(output);
}

function buildSafeAdyenRawForClient({
  raw = {},
  pspReference = null,
  resultCode = null,
  action = null,
  sessionData = null,
  clientKey = null,
} = {}) {
  const safeRaw = pickOwnFields(raw, [
    'pspReference',
    'psp_reference',
    'resultCode',
    'result_code',
    'action',
    'sessionData',
    'session_data',
    'clientKey',
    'client_key',
  ]);
  return pruneEmptyFields({
    ...safeRaw,
    ...(pspReference ? { pspReference } : {}),
    ...(resultCode ? { resultCode } : {}),
    ...(action ? { action } : {}),
    ...(sessionData ? { sessionData } : {}),
    ...(clientKey ? { clientKey } : {}),
  });
}

function sanitizeAdyenPaymentActionForClient(paymentAction, extracted = {}) {
  if (!isPlainObject(paymentAction)) return paymentAction || null;
  const sessionData = firstNonEmptyString(
    paymentAction.session_data,
    paymentAction.sessionData,
    extracted.sessionData,
  );
  const clientKey = firstNonEmptyString(
    paymentAction.client_key,
    paymentAction.clientKey,
    extracted.clientKey,
  );
  const pspReference = firstNonEmptyString(
    paymentAction.pspReference,
    paymentAction.psp_reference,
    extracted.pspReference,
  );
  const resultCode = firstNonEmptyString(
    paymentAction.resultCode,
    paymentAction.result_code,
    extracted.resultCode,
  );
  const action = isPlainObject(paymentAction.action)
    ? paymentAction.action
    : isPlainObject(extracted.action)
    ? extracted.action
    : null;
  const raw = buildSafeAdyenRawForClient({
    raw: paymentAction.raw,
    pspReference,
    resultCode,
    action,
    sessionData,
    clientKey,
  });

  return pruneEmptyFields({
    type: firstNonEmptyString(paymentAction.type, 'adyen_session'),
    ...(sessionData ? { session_data: sessionData } : {}),
    ...(clientKey ? { client_key: clientKey } : {}),
    ...(pspReference ? { pspReference } : {}),
    action: action || undefined,
    ...(resultCode ? { resultCode } : {}),
    url: firstNonEmptyString(paymentAction.url),
    submit_owner: paymentAction.submit_owner,
    component_kind: paymentAction.component_kind,
    supported_in_shopping_ui:
      typeof paymentAction.supported_in_shopping_ui === 'boolean'
        ? paymentAction.supported_in_shopping_ui
        : undefined,
    raw,
  });
}

function resolveSubmitPaymentContract(upstreamPayload = {}, paymentAction = null) {
  const statusCandidate = resolveSubmitPaymentStatusCandidate(upstreamPayload);
  const normalizedStatus = normalizeSubmitPaymentStatus(statusCandidate);
  const explicitRequires =
    typeof upstreamPayload.requires_client_confirmation === 'boolean'
      ? upstreamPayload.requires_client_confirmation
      : typeof upstreamPayload?.payment?.requires_client_confirmation === 'boolean'
      ? upstreamPayload.payment.requires_client_confirmation
      : null;
  const explicitOwner = ['client', 'backend'].includes(upstreamPayload.confirmation_owner)
    ? upstreamPayload.confirmation_owner
    : ['client', 'backend'].includes(upstreamPayload?.payment?.confirmation_owner)
    ? upstreamPayload.payment.confirmation_owner
    : null;
  const normalizedAction = normalizeSubmitPaymentAction(paymentAction);
  const actionType = normalizedAction?.type
    ? String(normalizedAction.type).trim().toLowerCase()
    : null;
  const explicitSubmitOwner = normalizeSubmitOwner(normalizedAction?.submit_owner);
  const explicitComponentKind = firstNonEmptyString(normalizedAction?.component_kind);
  const explicitSupported =
    typeof normalizedAction?.supported_in_shopping_ui === 'boolean'
      ? normalizedAction.supported_in_shopping_ui
      : null;
  const hasExplicitContractFields =
    explicitRequires != null ||
    explicitOwner != null ||
    explicitSubmitOwner != null ||
    explicitComponentKind != null ||
    explicitSupported != null;

  if (
    BACKEND_OWNED_PAYMENT_STATUSES.has(normalizedStatus.payment_status) ||
    TERMINAL_FAILURE_PAYMENT_STATUSES.has(normalizedStatus.payment_status)
  ) {
    return {
      payment_status: normalizedStatus.payment_status,
      payment_status_raw: normalizedStatus.payment_status_raw,
      confirmation_owner: 'backend',
      requires_client_confirmation: false,
      submit_owner: null,
      component_kind: null,
      supported_in_shopping_ui: true,
    };
  }

  if (hasExplicitContractFields) {
    const confirmationOwner =
      explicitOwner || (explicitRequires ? 'client' : 'backend');
    const requiresClientConfirmation =
      explicitRequires != null ? explicitRequires : confirmationOwner === 'client';
    const hasExplicitOwnershipFields =
      explicitRequires != null || explicitOwner != null;
    const submitOwner = hasExplicitOwnershipFields
      ? explicitSubmitOwner ||
        (requiresClientConfirmation || actionType ? 'unsupported' : null)
      : actionType
      ? 'unsupported'
      : null;
    const componentKind =
      hasExplicitOwnershipFields && explicitSubmitOwner ? explicitComponentKind : null;
    const supportedInShoppingUi =
      explicitSupported != null
        ? explicitSupported
        : submitOwner === 'unsupported'
        ? false
        : true;

    return {
      payment_status: normalizedStatus.payment_status,
      payment_status_raw: normalizedStatus.payment_status_raw,
      confirmation_owner: confirmationOwner,
      requires_client_confirmation: requiresClientConfirmation,
      submit_owner: submitOwner,
      component_kind: componentKind,
      supported_in_shopping_ui: supportedInShoppingUi,
    };
  }

  const inferredSubmitOwner = inferSubmitOwnerFromActionType(actionType);
  const supportedInShoppingUi =
    inferredSubmitOwner === 'unsupported'
      ? false
      : true;
  const isClientOwned =
    Boolean(inferredSubmitOwner) ||
    CLIENT_OWNED_PAYMENT_STATUSES.has(normalizedStatus.payment_status);
  return {
    payment_status: normalizedStatus.payment_status,
    payment_status_raw: normalizedStatus.payment_status_raw,
    confirmation_owner:
      explicitOwner || (isClientOwned ? 'client' : 'backend'),
    requires_client_confirmation: isClientOwned,
    submit_owner: inferredSubmitOwner,
    component_kind: inferredSubmitOwner
      ? inferComponentKindFromActionType(actionType)
      : null,
    supported_in_shopping_ui: supportedInShoppingUi,
  };
}

function isPlainObject(value) {
  return Boolean(value) && typeof value === 'object' && !Array.isArray(value);
}

function firstNonEmptyString(...values) {
  for (const value of values) {
    if (typeof value === 'string') {
      const trimmed = value.trim();
      if (trimmed) return trimmed;
      continue;
    }
    if (value != null) {
      const normalized = String(value).trim();
      if (normalized) return normalized;
    }
  }
  return null;
}

function hasExternalSeedRowPdpText(row) {
  if (!isPlainObject(row)) return false;
  const seedData = isPlainObject(row.seed_data) ? row.seed_data : {};
  const snapshot = isPlainObject(seedData.snapshot) ? seedData.snapshot : {};
  if (
    firstNonEmptyString(
      seedData.description,
      seedData.description_text,
      seedData.pdp_description,
      seedData.pdp_description_raw,
      seedData.overview,
      seedData.summary,
      snapshot.description,
      snapshot.description_text,
      snapshot.pdp_description,
      snapshot.pdp_description_raw,
      snapshot.overview,
      snapshot.summary,
    )
  ) {
    return true;
  }
  return [seedData.pdp_details_sections, snapshot.pdp_details_sections]
    .some((sections) => Array.isArray(sections) && sections.length > 0);
}

function collectAttachedCatalogContentFallbacks(attachedRow) {
  const payload = parseCanonicalCatalogPayload(attachedRow?.product_payload);
  const seedData = isPlainObject(payload.seed_data) ? payload.seed_data : {};
  const snapshot = isPlainObject(seedData.snapshot) ? seedData.snapshot : {};
  const externalSeed = isPlainObject(payload.external_seed) ? payload.external_seed : {};
  const externalSnapshot = isPlainObject(externalSeed.snapshot) ? externalSeed.snapshot : {};
  const enrichmentMeta = isPlainObject(payload.enrichment_meta) ? payload.enrichment_meta : {};

  return {
    description: firstNonEmptyString(
      attachedRow?.product_description,
      payload.description,
      payload.description_text,
      payload.pdp_description,
      payload.pdp_description_raw,
      payload.overview,
      payload.summary,
      externalSeed.description,
      externalSeed.description_text,
      externalSeed.pdp_description,
      externalSeed.pdp_description_raw,
      externalSeed.overview,
      externalSeed.summary,
      externalSnapshot.description,
      externalSnapshot.description_text,
      externalSnapshot.pdp_description,
      externalSnapshot.pdp_description_raw,
      seedData.description,
      seedData.description_text,
      seedData.pdp_description,
      seedData.pdp_description_raw,
      seedData.overview,
      seedData.summary,
      snapshot.description,
      snapshot.description_text,
      snapshot.pdp_description,
      snapshot.pdp_description_raw,
      snapshot.overview,
      snapshot.summary,
      enrichmentMeta.product_description,
      enrichmentMeta.description,
      enrichmentMeta.overview,
      enrichmentMeta.summary,
      enrichmentMeta.candidate_attribute_summary,
    ),
    imageUrl: firstCatalogPayloadString(
      attachedRow?.product_image_url,
      payload.image_url,
      payload.imageUrl,
      payload.images,
      payload.image_urls,
      externalSeed.image_url,
      externalSeed.imageUrl,
      externalSeed.images,
      externalSeed.image_urls,
      externalSnapshot.image_url,
      externalSnapshot.images,
      seedData.image_url,
      seedData.imageUrl,
      seedData.images,
      seedData.image_urls,
      snapshot.image_url,
      snapshot.images,
      snapshot.image_urls,
    ),
    brand: firstNonEmptyString(
      attachedRow?.brand,
      payload.brand,
      payload.vendor,
      externalSeed.brand,
      externalSeed.vendor,
      seedData.brand,
      seedData.vendor,
      snapshot.brand,
      snapshot.vendor,
    ),
    category: firstNonEmptyString(
      attachedRow?.category,
      attachedRow?.product_type,
      payload.category,
      payload.product_type,
      externalSeed.category,
      externalSeed.product_type,
      seedData.category,
      seedData.product_type,
      snapshot.category,
      snapshot.product_type,
    ),
    categoryPath: firstCatalogPayloadString(
      attachedRow?.category_path,
      payload.category_path,
      payload.catalog_category_path,
      externalSeed.category_path,
      seedData.category_path,
      seedData.catalog_category_path,
      snapshot.category_path,
      snapshot.catalog_category_path,
    ),
    sourceProductId: firstNonEmptyString(attachedRow?.source_product_id, seedData.external_product_id, externalSeed.external_product_id),
  };
}

function mergeAttachedCatalogContentIntoExternalSeedRow(row, attachedRow) {
  if (!isPlainObject(row) || !isPlainObject(attachedRow)) return row;
  const attachedProductKey = firstNonEmptyString(row.attached_product_key, attachedRow.product_key);
  if (!attachedProductKey) return row;

  const seedData = isPlainObject(row.seed_data) ? { ...row.seed_data } : {};
  const snapshot = isPlainObject(seedData.snapshot) ? { ...seedData.snapshot } : {};
  const fallbacks = collectAttachedCatalogContentFallbacks(attachedRow);
  const nextRow = { ...row };
  const inheritedFields = [];

  if (!hasExternalSeedRowPdpText(row) && fallbacks.description) {
    seedData.description = fallbacks.description;
    snapshot.description = snapshot.description || fallbacks.description;
    seedData.seed_description_origin = seedData.seed_description_origin || 'attached_catalog_product';
    inheritedFields.push('description');
  }

  if (!firstNonEmptyString(nextRow.image_url, seedData.image_url, snapshot.image_url) && fallbacks.imageUrl) {
    nextRow.image_url = fallbacks.imageUrl;
    seedData.image_url = seedData.image_url || fallbacks.imageUrl;
    inheritedFields.push('image_url');
  }

  if (!firstNonEmptyString(seedData.brand, seedData.vendor, snapshot.brand, snapshot.vendor) && fallbacks.brand) {
    seedData.brand = fallbacks.brand;
    inheritedFields.push('brand');
  }

  if (!firstNonEmptyString(seedData.category, seedData.product_type, snapshot.category, snapshot.product_type) && fallbacks.category) {
    seedData.product_type = fallbacks.category;
    seedData.category = seedData.category || fallbacks.category;
    inheritedFields.push('category');
  }

  if (!firstCatalogPayloadString(seedData.category_path, seedData.catalog_category_path, snapshot.category_path) && fallbacks.categoryPath) {
    seedData.category_path = fallbacks.categoryPath;
    inheritedFields.push('category_path');
  }

  if (inheritedFields.length > 0) {
    seedData.snapshot = snapshot;
    seedData.attached_catalog_content_source = {
      source: 'catalog_products',
      product_key: attachedProductKey,
      ...(fallbacks.sourceProductId ? { source_product_id: fallbacks.sourceProductId } : {}),
      inherited_fields: inheritedFields,
    };
    nextRow.seed_data = seedData;
  }

  return nextRow;
}

async function maybeHydrateExternalSeedRowFromAttachedCatalogProduct(row) {
  if (!isPlainObject(row)) return row;
  const attachedProductKey = firstNonEmptyString(row.attached_product_key);
  if (!attachedProductKey || hasExternalSeedRowPdpText(row)) return row;

  try {
    const res = await query(
      `
        SELECT
          product_key,
          source_product_id,
          title AS product_title,
          description AS product_description,
          brand,
          category,
          product_type,
          category_path,
          image_url AS product_image_url,
          product_payload
        FROM catalog_products
        WHERE product_key = $1
        LIMIT 1
      `,
      [attachedProductKey],
    );
    const attachedRow = Array.isArray(res?.rows) ? res.rows[0] : null;
    if (!attachedRow) return row;
    return mergeAttachedCatalogContentIntoExternalSeedRow(row, attachedRow);
  } catch (err) {
    logger.warn(
      { err: err?.message || String(err), attachedProductKey, externalSeedId: row.id || null },
      'Failed to hydrate attached catalog content for external seed PDP',
    );
    return row;
  }
}

const RESPONSE_OWNED_PDP_CANONICAL_MODULE_TYPES = new Set([
  'product_intel',
  'recommendations',
  'reviews_preview',
  'similar',
]);

function stripResponseOwnedPdpModulesFromCanonicalPayload(pdpPayload) {
  if (!pdpPayload || typeof pdpPayload !== 'object') return pdpPayload;
  return {
    ...pdpPayload,
    modules: Array.isArray(pdpPayload.modules)
      ? pdpPayload.modules.filter((module) => {
          const type = String(module?.type || '').trim();
          return !RESPONSE_OWNED_PDP_CANONICAL_MODULE_TYPES.has(type);
        })
      : [],
  };
}

function looksLikeMerchantId(value) {
  return /^merch_[a-z0-9_]+$/i.test(String(value || '').trim());
}

function normalizeOfferSellerNameCandidate(value, merchantId = '') {
  const text = firstNonEmptyString(value);
  if (!text) return null;
  const normalized = text.toLowerCase();
  const normalizedMerchantId = String(merchantId || '').trim().toLowerCase();
  if (normalizedMerchantId && normalized === normalizedMerchantId) return null;
  if (normalized === 'external_seed' || normalized === 'external seed') return null;
  if (looksLikeMerchantId(normalized)) return null;
  return text;
}

const OFFER_SELLER_HOST_LABELS = new Map([
  ['sephora.com', 'Sephora'],
  ['ulta.com', 'Ulta Beauty'],
  ['theordinary.com', 'The Ordinary'],
  ['theordinary.deciem.com', 'The Ordinary'],
  ['tomfordbeauty.com', 'Tom Ford Beauty'],
  ['beautyofjoseon.com', 'Beauty of Joseon'],
  ['ohlolly.com', 'Ohlolly'],
  ['fentybeauty.com', 'Fenty Beauty'],
  ['kyliecosmetics.com', 'Kylie Cosmetics'],
]);

function buildCatalogSourceQuarantineAntiJoinSql(alias = 'cp_offer') {
  return buildQuarantineAntiJoinSql({
    domainExpr: `${alias}.source_domain`,
    merchantExpr: `${alias}.merchant_id`,
    platformExpr: `${alias}.platform`,
    sourceSystemExpr: `${alias}.source_system`,
    sourceRefExpr: `${alias}.source_ref`,
  });
}

function normalizeOfferSellerComparable(value) {
  return String(firstNonEmptyString(value) || '')
    .toLowerCase()
    .replace(/&/g, ' and ')
    .replace(/[^a-z0-9]+/g, '')
    .trim();
}

function readOfferSellerHost(value) {
  const raw = firstNonEmptyString(value);
  if (!raw) return '';
  const candidate = /^https?:\/\//i.test(raw) ? raw : `https://${raw}`;
  try {
    return String(new URL(candidate).hostname || '').toLowerCase().replace(/^www\./, '');
  } catch (_err) {
    return '';
  }
}

function formatOfferSellerHostLabel(host) {
  const normalizedHost = readOfferSellerHost(host);
  if (!normalizedHost) return '';
  const mapped = OFFER_SELLER_HOST_LABELS.get(normalizedHost);
  if (mapped) return mapped;
  const base = normalizedHost.split('.').filter(Boolean)[0] || '';
  return base
    .split(/[-_]+/)
    .filter(Boolean)
    .map((part) => `${part.slice(0, 1).toUpperCase()}${part.slice(1)}`)
    .join(' ');
}

function resolveExternalSeedOfferSellerHostLabel(product, member) {
  const payload = member?.source_payload && typeof member.source_payload === 'object'
    ? member.source_payload
    : member?.sourcePayload && typeof member.sourcePayload === 'object'
      ? member.sourcePayload
      : {};
  const candidates = [
    product?.merchant_checkout_url,
    product?.external_redirect_url,
    product?.source_url,
    product?.destination_url,
    product?.canonical_url,
    product?.url,
    payload.merchant_checkout_url,
    payload.external_redirect_url,
    payload.source_url,
    payload.destination_url,
    payload.canonical_url,
    payload.url,
  ];
  for (const candidate of candidates) {
    const label = formatOfferSellerHostLabel(candidate);
    if (label) return label;
  }
  return '';
}

function offerSellerNameLooksHostLike(value) {
  return /(^|\s)(www\.)?[a-z0-9-]+\.[a-z]{2,}(\s|$)/i.test(firstNonEmptyString(value));
}

function offerSellerNameLooksLikeProductBrand(value, product, member) {
  const seller = normalizeOfferSellerComparable(value);
  if (!seller) return false;
  const payload = member?.source_payload && typeof member.source_payload === 'object'
    ? member.source_payload
    : member?.sourcePayload && typeof member.sourcePayload === 'object'
      ? member.sourcePayload
      : {};
  return [
    product?.brand,
    product?.vendor,
    payload.brand,
    payload.vendor,
  ].some((candidate) => {
    const brand = normalizeOfferSellerComparable(candidate);
    return brand && seller === brand;
  });
}

// ADR-009 D2: crawl-onboarded external seeds now live on per-brand observed
// sellers (`merch_obs_<hash>`) instead of the legacy shared `external_seed`
// bucket (#1770 re-keyed pdp_identity_listing to the observed seller). Both are
// external-seed SUPPLY — crawl-sourced, with no upstream merchant checkout/API.
// Serving-path branches that ask "is this external-seed supply?" (skip upstream
// fetch, serve straight from the identity payload) must therefore treat the two
// alike. Use this when only a merchant_id is in hand.
// Delegates: externalSeedLane owns this test. Keeping a twin here is how the
// class regressed in the first place — two copies of a prefix nothing watches.
function isExternalSeedListingMerchantId(merchantId) {
  return isExternalSeedSupplyMerchantId(merchantId);
}

// Member/listing-aware variant: prefer the durable `source_kind` discriminator
// (surfaced from pdp_identity_listing.source_kind) when the row carries it,
// otherwise fall back to the merchant-id shape. Connected merchants carry
// neither signal, so they are unaffected.
function memberIsExternalSeedSupply(member) {
  if (!member || typeof member !== 'object') return false;
  const sourceKind = String(member.source_kind || member.sourceKind || '').trim();
  if (sourceKind === EXTERNAL_SEED_MERCHANT_ID) return true;
  return isExternalSeedListingMerchantId(member.merchant_id || member.merchantId);
}

function resolveOfferSellerDisplayName({ product, member, merchantId }) {
  const mid = String(merchantId || product?.merchant_id || member?.merchant_id || '').trim();
  // ADR-009: observed sellers (merch_obs_) are external-seed supply too — their
  // seed payloads carry raw host strings ("mojawa.com") in the seller fields.
  // Without the host-label pass those leak through verbatim (the merchant-name
  // candidates below skip brand-equal names, and an observed brand seller's
  // catalog_merchants name IS the brand), so the offer shows the bare domain
  // instead of the seller of record.
  const externalSeedHostLabel =
    isExternalSeedListingMerchantId(mid)
      ? resolveExternalSeedOfferSellerHostLabel(product, member)
      : '';
  const explicitCandidates = [
    product?.seller_of_record,
    product?.sellerOfRecord,
    product?.seller_name,
    product?.sellerName,
    product?.store_name,
    product?.storeName,
    member?.seller_of_record,
    member?.sellerOfRecord,
    member?.seller_name,
    member?.sellerName,
    member?.store_name,
    member?.storeName,
  ];
  for (const candidate of explicitCandidates) {
    const sellerName = normalizeOfferSellerNameCandidate(candidate, mid);
    if (!sellerName) continue;
    if (offerSellerNameLooksHostLike(sellerName) && externalSeedHostLabel) {
      // Legacy anonymous lump: the formatted host label is the best name on
      // offer. Observed sellers have a real catalog_merchants name — keep
      // scanning so it wins over a host string; the label stays the fallback.
      if (mid === EXTERNAL_SEED_MERCHANT_ID) return externalSeedHostLabel;
      continue;
    }
    return sellerName;
  }

  const merchantCandidates = [
    product?.merchant_name,
    product?.merchantName,
    member?.merchant_name,
    member?.merchantName,
  ];
  for (const candidate of merchantCandidates) {
    const sellerName = normalizeOfferSellerNameCandidate(candidate, mid);
    if (!sellerName) continue;
    if (externalSeedHostLabel && offerSellerNameLooksHostLike(sellerName)) {
      continue;
    }
    // Brand-equal merchant names are fabricated on the legacy anonymous lump,
    // but an observed brand seller's catalog_merchants name legitimately IS
    // the brand ("Mojawa" sells Mojawa) — suppress only for the legacy bucket.
    if (
      externalSeedHostLabel &&
      mid === EXTERNAL_SEED_MERCHANT_ID &&
      offerSellerNameLooksLikeProductBrand(sellerName, product, member)
    ) {
      continue;
    }
    return sellerName;
  }
  if (externalSeedHostLabel) return externalSeedHostLabel;
  return undefined;
}

async function fetchMerchantDisplayNamesByIds(merchantIds) {
  if (!process.env.DATABASE_URL) return new Map();
  const ids = Array.from(
    new Set(
      (Array.isArray(merchantIds) ? merchantIds : [])
        .map((value) => String(value || '').trim())
        .filter((value) => value && value !== EXTERNAL_SEED_MERCHANT_ID),
    ),
  );
  if (!ids.length) return new Map();

  try {
    const res = await query(
      `
        SELECT DISTINCT ON (merchant_id)
          merchant_id,
          merchant_name
        FROM (
          SELECT
            merchant_id,
            merchant_name,
            0 AS priority,
            NULL::timestamptz AS connected_at
          FROM catalog_merchants
          WHERE merchant_id = ANY($1::text[])
            AND COALESCE(NULLIF(trim(merchant_name), ''), '') <> ''
          UNION ALL
          SELECT
            merchant_id,
            name AS merchant_name,
            1 AS priority,
            connected_at
          FROM merchant_stores
          WHERE merchant_id = ANY($1::text[])
            AND COALESCE(NULLIF(trim(name), ''), '') <> ''
            AND lower(COALESCE(platform, '')) = 'shopify'
            AND lower(COALESCE(status, '')) IN ('active', 'connected')
          UNION ALL
          SELECT
            merchant_id,
            business_name AS merchant_name,
            2 AS priority,
            NULL::timestamptz AS connected_at
          FROM merchant_onboarding
          WHERE merchant_id = ANY($1::text[])
            AND COALESCE(NULLIF(trim(business_name), ''), '') <> ''
            AND COALESCE(status, '') NOT IN ('deleted', 'rejected')
        ) candidates
        ORDER BY merchant_id, priority ASC, connected_at DESC NULLS LAST
      `,
      [ids],
    );
    return new Map(
      (Array.isArray(res?.rows) ? res.rows : [])
        .map((row) => [
          String(row?.merchant_id || '').trim(),
          normalizeOfferSellerNameCandidate(row?.merchant_name, row?.merchant_id),
        ])
        .filter(([merchantId, merchantName]) => Boolean(merchantId) && Boolean(merchantName)),
    );
  } catch (err) {
    logger.warn(
      { err: err?.message || String(err), merchant_count: ids.length },
      'Failed to load merchant display names for PDP offers',
    );
    return new Map();
  }
}

async function fetchMerchantDisplayNameById(merchantId) {
  const mid = String(merchantId || '').trim();
  if (!mid || mid === EXTERNAL_SEED_MERCHANT_ID) return undefined;
  return (await fetchMerchantDisplayNamesByIds([mid])).get(mid) || undefined;
}

function pruneEmptyFields(input = {}) {
  const output = {};
  for (const [key, value] of Object.entries(input || {})) {
    if (PROTOTYPE_POLLUTION_KEYS.has(key)) continue;
    if (value == null) continue;
    if (typeof value === 'string' && !value.trim()) continue;
    if (Array.isArray(value) && value.length === 0) continue;
    if (isPlainObject(value) && Object.keys(value).length === 0) continue;
    output[key] = value;
  }
  return output;
}

function getInvokeScopedBuyerRef(payload = {}) {
  // SECURITY: buyer identity must not be derived from model-controlled tool payload.
  // The legacy upstream X-Buyer-Ref forwarder can only use the request-scoped auth context.
  const store = getInvokeAuthContext();
  return firstNonEmptyString(store?.buyer_ref);
}

function buildInvokeRequestContext({
  payload = {},
  metadata = {},
  clientChannel = 'shop',
  gatewayRequestId = null,
  fallbackCurrency = null,
} = {}) {
  const context = isPlainObject(payload?.context) ? payload.context : {};
  const creatorCheckoutSource = resolveCanonicalCreatorCheckoutSource({
    payload,
    metadata,
    clientChannel,
  });
  return pruneEmptyFields({
    tenant_id: firstNonEmptyString(payload?.tenant_id, context?.tenant_id, metadata?.tenant_id),
    request_id: firstNonEmptyString(context?.request_id, gatewayRequestId),
    channel:
      creatorCheckoutSource ||
      firstNonEmptyString(context?.channel, metadata?.source, clientChannel),
    locale: firstNonEmptyString(payload?.locale, context?.locale, context?.language),
    currency: firstNonEmptyString(
      payload?.currency,
      payload?.payment?.currency,
      payload?.order?.currency,
      payload?.quote?.currency,
      context?.currency,
      fallbackCurrency,
    ),
    country: firstNonEmptyString(payload?.market, context?.country, context?.market),
    delivery_region: firstNonEmptyString(
      payload?.delivery_region,
      context?.delivery_region,
      context?.deliveryRegion,
      context?.region,
    ),
    user_constraints: isPlainObject(context?.user_constraints)
      ? context.user_constraints
      : isPlainObject(payload?.user_constraints)
        ? payload.user_constraints
        : undefined,
    consent_context: isPlainObject(context?.consent_context)
      ? context.consent_context
      : isPlainObject(payload?.consent_context)
        ? payload.consent_context
        : undefined,
  });
}

function buildInvokeBuyerContext({ source = {}, payload = {} } = {}) {
  const shippingAddress = isPlainObject(source?.shipping_address)
    ? source.shipping_address
    : isPlainObject(payload?.shipping_address)
      ? payload.shipping_address
      : undefined;
  const normalizedShippingAddress = shippingAddress
    ? pruneEmptyFields({
        ...shippingAddress,
        name: firstNonEmptyString(
          shippingAddress.name,
          shippingAddress.recipient_name,
          shippingAddress.recipientName,
        ),
      })
    : undefined;
  return pruneEmptyFields({
    customer_email: firstNonEmptyString(
      source?.customer_email,
      source?.customerEmail,
      payload?.customer_email,
      payload?.customerEmail,
    ),
    customer_name: firstNonEmptyString(
      source?.customer_name,
      source?.customerName,
      normalizedShippingAddress?.recipient_name,
      normalizedShippingAddress?.name,
    ),
    shipping_address: normalizedShippingAddress,
    buyer_ref: getInvokeScopedBuyerRef(payload),
  });
}

function buildQuotePreviewV2Body({
  payload = {},
  quote = {},
  merchantId = null,
  offerId = null,
  metadata = {},
  clientChannel = 'shop',
  gatewayRequestId = null,
} = {}) {
  const offerRefs = Array.isArray(quote?.items)
    ? quote.items
        .map((item) => {
          const productId = firstNonEmptyString(item?.product_id, item?.productId);
          const variantId = firstNonEmptyString(
            item?.variant_id,
            item?.variantId,
            item?.sku,
            item?.product_id,
            item?.productId,
          );
          const quantity = Math.max(1, Number(item?.quantity || 1) || 1);
          if (!productId || !variantId) return null;
          return pruneEmptyFields({
            offer_id: firstNonEmptyString(item?.offer_id, item?.offerId, offerId),
            product_id: productId,
            variant_id: variantId,
            quantity,
          });
        })
        .filter(Boolean)
    : [];

  return pruneEmptyFields({
    merchant_id: merchantId,
    offer_refs: offerRefs,
    discount_codes: Array.isArray(quote?.discount_codes) ? quote.discount_codes : undefined,
    buyer_context: buildInvokeBuyerContext({ source: quote, payload }),
    selected_delivery_option: isPlainObject(quote?.selected_delivery_option)
      ? quote.selected_delivery_option
      : undefined,
    request_context: buildInvokeRequestContext({
      payload,
      metadata,
      clientChannel,
      gatewayRequestId,
      fallbackCurrency: quote?.currency,
    }),
  });
}

function buildCreateOrderV2Body({
  payload = {},
  order = {},
  metadata = {},
  clientChannel = 'shop',
  gatewayRequestId = null,
} = {}) {
  return pruneEmptyFields({
    quote_id: firstNonEmptyString(order?.quote_id, order?.quoteId),
    buyer_context: buildInvokeBuyerContext({ source: order, payload }),
    request_context: buildInvokeRequestContext({
      payload,
      metadata,
      clientChannel,
      gatewayRequestId,
      fallbackCurrency: order?.currency,
    }),
    metadata: isPlainObject(order?.metadata) ? order.metadata : undefined,
    preferred_psp: firstNonEmptyString(order?.preferred_psp, payload?.preferred_psp),
    idempotency_key: firstNonEmptyString(
      order?.idempotency_key,
      order?.idempotencyKey,
      payload?.idempotency_key,
      payload?.idempotencyKey,
    ),
  });
}

function normalizeCurrencyCode(value) {
  const currency = firstNonEmptyString(value);
  return currency ? currency.toUpperCase() : null;
}

function resolveCheckoutQuoteId({ payload = {}, payment = {} } = {}) {
  return firstNonEmptyString(
    payment?.quote_id,
    payment?.quoteId,
    payload?.quote_id,
    payload?.quoteId,
    payload?.quote?.quote_id,
    payload?.quote?.quoteId,
  );
}

function getFirstDefinedValue(...values) {
  for (const value of values) {
    if (value !== undefined && value !== null) return value;
  }
  return undefined;
}

function normalizeExplicitMinorAmount(value) {
  const raw =
    typeof value === 'string' && value.trim()
      ? Number(value)
      : typeof value === 'number'
        ? value
        : null;
  if (!Number.isFinite(raw) || raw < 0 || Math.trunc(raw) !== raw) return null;
  return raw;
}

function decimalQuoteAmountToMinorUnits(value, currency) {
  const raw =
    typeof value === 'string' && value.trim()
      ? Number(value.replace(/,/g, ''))
      : typeof value === 'number'
        ? value
        : null;
  if (!Number.isFinite(raw) || raw < 0) return null;
  const multiplier = new Set(['JPY', 'KRW']).has(normalizeCurrencyCode(currency)) ? 1 : 100;
  return Math.round(raw * multiplier);
}

function resolveCheckoutCurrency({ payload = {}, payment = {} } = {}) {
  const quote = isPlainObject(payload?.quote) ? payload.quote : {};
  const priceBreakdown = isPlainObject(quote?.price_breakdown) ? quote.price_breakdown : {};
  const amounts = isPlainObject(quote?.amounts) ? quote.amounts : {};
  return normalizeCurrencyCode(
    firstNonEmptyString(
      payment?.currency,
      quote?.currency,
      priceBreakdown?.currency,
      amounts?.currency,
      payload?.currency,
      payload?.context?.currency,
    ),
  );
}

function resolveCheckoutExpectedAmount({ payload = {}, payment = {}, quoteId = null, currency = null } = {}) {
  const quote = isPlainObject(payload?.quote) ? payload.quote : null;
  const quoteMatches =
    quote &&
    quoteId &&
    firstNonEmptyString(quote.quote_id, quote.quoteId, payload?.quote_id, payload?.quoteId) === quoteId;
  if (quoteMatches) {
    const priceBreakdown = isPlainObject(quote.price_breakdown) ? quote.price_breakdown : {};
    const amounts = isPlainObject(quote.amounts) ? quote.amounts : {};
    const quoteTotal = getFirstDefinedValue(
      priceBreakdown.total,
      quote.total,
      quote.total_amount,
      quote.amount_total,
      amounts.total,
    );
    const quoteCurrency = normalizeCurrencyCode(
      firstNonEmptyString(priceBreakdown.currency, quote.currency, amounts.currency, currency),
    );
    const quoteExpectedAmount = decimalQuoteAmountToMinorUnits(quoteTotal, quoteCurrency);
    if (quoteExpectedAmount != null) return quoteExpectedAmount;
  }

  return normalizeExplicitMinorAmount(
    getFirstDefinedValue(
      payment?.expected_amount,
      payment?.expectedAmount,
      payload?.expected_amount,
      payload?.expectedAmount,
    ),
  );
}

function buildCheckoutSessionV2Body({
  payload = {},
  payment = {},
  metadata = {},
  clientChannel = 'shop',
  gatewayRequestId = null,
} = {}) {
  const buyerContext = buildInvokeBuyerContext({ source: payment, payload });
  const quoteId = resolveCheckoutQuoteId({ payload, payment });
  const currency = resolveCheckoutCurrency({ payload, payment });
  const expectedAmount = resolveCheckoutExpectedAmount({
    payload,
    payment,
    quoteId,
    currency,
  });
  const creatorCheckoutSource = resolveCanonicalCreatorCheckoutSource({
    payload,
    payment,
    metadata,
    clientChannel,
  });
  return pruneEmptyFields({
    order_id: firstNonEmptyString(payment?.order_id, payment?.orderId),
    quote_id: quoteId,
    expected_amount: expectedAmount,
    currency,
    payment_method_hint: firstNonEmptyString(
      payment?.payment_method_hint,
      payment?.paymentMethodHint,
      payload?.payment_method_hint,
      payload?.paymentMethodHint,
    ),
    payment_handler_id: firstNonEmptyString(
      payment?.payment_handler_id,
      payment?.paymentHandlerId,
      payload?.payment_handler_id,
      payload?.paymentHandlerId,
    ),
    payment_handler_type: firstNonEmptyString(
      payment?.payment_handler_type,
      payment?.paymentHandlerType,
      payload?.payment_handler_type,
      payload?.paymentHandlerType,
    ),
    return_url: firstNonEmptyString(
      payment?.return_url,
      payment?.returnUrl,
      payment?.redirect_url,
      payment?.redirectUrl,
      payload?.return_url,
      payload?.returnUrl,
    ),
    buyer_ref: getInvokeScopedBuyerRef(payload),
    requested_scopes: Array.isArray(payment?.requested_scopes) ? payment.requested_scopes : undefined,
    market: firstNonEmptyString(payment?.market, payload?.market),
    locale: firstNonEmptyString(payment?.locale, payload?.locale, payload?.context?.locale),
    source:
      creatorCheckoutSource ||
      firstNonEmptyString(payment?.source, metadata?.source, clientChannel),
    customer_email: buyerContext.customer_email,
    shipping_address: buyerContext.shipping_address,
    request_context: buildInvokeRequestContext({
      payload,
      metadata,
      clientChannel,
      gatewayRequestId,
      fallbackCurrency: currency,
    }),
  });
}

function resolveSubmitPaymentExplicitPaymentMethod(payment = {}) {
  if (isPlainObject(payment?.payment_method)) return payment.payment_method;
  if (isPlainObject(payment?.paymentMethod)) return payment.paymentMethod;
  return {};
}

function resolveSubmitPaymentMethodType({
  payload = {},
  payment = {},
  fallback = null,
} = {}) {
  const explicitPaymentMethod = resolveSubmitPaymentExplicitPaymentMethod(payment);
  return firstNonEmptyString(
    explicitPaymentMethod.type,
    explicitPaymentMethod.payment_method_type,
    explicitPaymentMethod.paymentMethodType,
    payment?.payment_method_hint,
    payment?.paymentMethodHint,
    payload?.payment_method_hint,
    payload?.paymentMethodHint,
    fallback,
  );
}

function buildSafeSubmitPaymentMethodForV1(explicitPaymentMethod = {}, paymentMethodType = 'card') {
  const safePaymentMethod = {};
  if (isPlainObject(explicitPaymentMethod)) {
    for (const field of SUBMIT_PAYMENT_CARD_METHOD_SAFE_FIELDS) {
      if (Object.prototype.hasOwnProperty.call(explicitPaymentMethod, field)) {
        safePaymentMethod[field] = explicitPaymentMethod[field];
      }
    }
  }
  safePaymentMethod.type = paymentMethodType;
  return pruneEmptyFields(safePaymentMethod);
}

function buildSubmitPaymentV1Body({
  payload = {},
  payment = {},
  checkoutSessionBody = {},
} = {}) {
  const explicitPaymentMethod = resolveSubmitPaymentExplicitPaymentMethod(payment);
  const paymentMethodType =
    resolveSubmitPaymentMethodType({ payload, payment, fallback: 'card' }) || 'card';

  return pruneEmptyFields({
    order_id: firstNonEmptyString(
      checkoutSessionBody?.order_id,
      payment?.order_id,
      payment?.orderId,
      payload?.order_id,
      payload?.orderId,
    ),
    payment_method: buildSafeSubmitPaymentMethodForV1(explicitPaymentMethod, paymentMethodType),
    idempotency_key: firstNonEmptyString(
      payment?.idempotency_key,
      payment?.idempotencyKey,
      payload?.idempotency_key,
      payload?.idempotencyKey,
    ),
    save_payment_method:
      payment?.save_payment_method === true || payment?.savePaymentMethod === true ? true : undefined,
    return_url: firstNonEmptyString(
      payment?.return_url,
      payment?.returnUrl,
      payment?.redirect_url,
      payment?.redirectUrl,
      checkoutSessionBody?.return_url,
    ),
  });
}

// The DELEGATED-PSP-TOKEN charge body for POST /agent/v1/payments.
//
// That endpoint dispatches through the backend's off-session gate → off-session payment → capture, i.e. the
// lane that knows how to charge a Stripe SharedPaymentToken on the MERCHANT's own key. It is deliberately NOT
// /agent/v2/payments/checkout-sessions: that mints a HOSTED checkout page a buyer clicks, which cannot take a
// delegated token and cannot complete off-session.
//
// Amount and currency are NOT sent. The backend prices the charge from the order it created from our quote —
// re-asserting an amount here would introduce a second, forgeable source for the figure the buyer's token
// allowance was sized against. `order_id` is the binding.
//
// The token value never appears in a log line: this builder only places it in the request body, and neither
// callUpstreamWithOptionalRetry nor throwCommerceKernelUpstreamError logs the request body.
function buildDelegatedPaymentV1Body({ order_id = null, token = null, idempotency_key = null } = {}) {
  const delegatedToken = firstNonEmptyString(token);
  return pruneEmptyFields({
    order_id: firstNonEmptyString(order_id),
    // Emitted ONLY with a token. A bare `{type:'card'}` on a money endpoint is a request to charge with no
    // instrument — the backend would refuse it, but this lane should not be the thing that asks.
    payment_method: delegatedToken ? { type: 'card', token: delegatedToken } : undefined,
    idempotency_key: firstNonEmptyString(idempotency_key),
  });
}

function shouldSubmitPaymentUseExistingOrderMerchantPspSurface({
  payload = {},
  payment = {},
  checkoutSessionBody = {},
} = {}) {
  const paymentMethodType = resolveSubmitPaymentMethodType({ payload, payment });
  const normalizedPaymentMethodType = paymentMethodType
    ? String(paymentMethodType).trim().toLowerCase()
    : '';
  return (
    !firstNonEmptyString(checkoutSessionBody?.payment_handler_id) &&
    !firstNonEmptyString(checkoutSessionBody?.payment_handler_type) &&
    (!normalizedPaymentMethodType ||
      DIRECT_MERCHANT_PSP_PAYMENT_METHOD_TYPES.has(normalizedPaymentMethodType))
  );
}

function buildSearchProductsV2Body({
  payload = {},
  search = {},
  metadata = {},
  clientChannel = 'shop',
  gatewayRequestId = null,
  defaultSearchAllMerchants = false,
} = {}) {
  const page = Math.max(1, Number(search?.page || 1) || 1);
  const limit = Math.min(
    Math.max(1, Number(search?.page_size || search?.limit || 20) || 20),
    SEARCH_LIMIT_MAX,
  );
  const offset = (page - 1) * limit;
  const merchantId = firstNonEmptyString(search?.merchant_id, search?.merchantId);
  const merchantIdsRaw = Array.isArray(search?.merchant_ids)
    ? search.merchant_ids
    : Array.isArray(search?.merchantIds)
      ? search.merchantIds
      : [];
  const merchantIds = uniqueStrings(
    merchantIdsRaw.map((value) => String(value || '').trim()).filter(Boolean),
  );
  const explicitSearchAllMerchants =
    search?.search_all_merchants === true || search?.searchAllMerchants === true;
  const searchAllMerchants =
    explicitSearchAllMerchants ||
    (!merchantId && merchantIds.length === 0 && Boolean(defaultSearchAllMerchants));

  return pruneEmptyFields({
    merchant_id: merchantId,
    merchant_ids: !merchantId && merchantIds.length > 0 ? merchantIds : undefined,
    search_all_merchants: searchAllMerchants,
    query: search?.query != null ? String(search.query || '') : undefined,
    category: firstNonEmptyString(search?.category),
    catalog_surface: firstNonEmptyString(search?.catalog_surface, search?.catalogSurface),
    min_price: search?.price_min ?? search?.min_price,
    max_price: search?.price_max ?? search?.max_price,
    in_stock_only: search?.in_stock_only !== false,
    limit,
    offset,
    allow_external_seed: search?.allow_external_seed,
    external_seed_only: search?.external_seed_only,
    allow_stale_cache: search?.allow_stale_cache,
    external_seed_strategy: firstNonEmptyString(search?.external_seed_strategy),
    fast_mode: search?.fast_mode,
    request_context: buildInvokeRequestContext({
      payload,
      metadata,
      clientChannel,
      gatewayRequestId,
      fallbackCurrency: firstNonEmptyString(search?.currency, payload?.currency),
    }),
  });
}

function getRequestedCatalogSurface({ search = {}, metadata = {} } = {}) {
  return String(
    firstNonEmptyString(
      search?.catalog_surface,
      search?.catalogSurface,
      metadata?.catalog_surface,
      metadata?.catalogSurface,
    ) || '',
  )
    .trim()
    .toLowerCase();
}

const STRICT_FIND_PRODUCTS_MULTI_INGREDIENT_ALIASES = Object.freeze({
  'ascorbic acid': 'ascorbic_acid',
  'azelaic acid': 'azelaic_acid',
  'benzoyl peroxide': 'benzoyl_peroxide',
  ceramide: 'ceramide_np',
  ceramides: 'ceramide_np',
  'ceramide np': 'ceramide_np',
  glycerin: 'glycerin',
  glycerine: 'glycerin',
  'hyaluronic acid': 'hyaluronic_acid',
  niacinamide: 'niacinamide',
  panthenol: 'panthenol',
  retinol: 'retinol',
  'salicylic acid': 'salicylic_acid',
  'vitamin c': 'ascorbic_acid',
  'zinc pca': 'zinc_pca',
});

const STRICT_FIND_PRODUCTS_MULTI_SHADE_CATEGORY_TERMS = Object.freeze([
  'foundation',
  'lipstick',
  'blush',
  'gloss',
]);

const STRICT_FIND_PRODUCTS_MULTI_VISIBLE_ATTRIBUTE_TERMS = Object.freeze([
  'fragrance free',
  'sensitive skin',
  'hydrating',
  'brightening',
]);

// Vocabulary lives in the shared relevance gate (Class 2 consolidation);
// this alias keeps the existing references stable.
const STRICT_FIND_PRODUCTS_MULTI_SKINCARE_CATEGORY_TERMS =
  beautyRelevanceGate.SKINCARE_FORM_TERMS;

const STRICT_FIND_PRODUCTS_MULTI_EXTERNAL_PREFETCH_LIMIT = Math.max(
  1,
  Math.min(Number(process.env.STRICT_FIND_PRODUCTS_MULTI_EXTERNAL_PREFETCH_LIMIT || 12) || 12, 50),
);

function isStrictCommerceCatalogSurface(surface) {
  return ['agent_api', 'acp', 'ucp'].includes(String(surface || '').trim().toLowerCase());
}

function extractStrictFindProductsMultiIngredientIntents(queryText, beautyQueryProfile = null) {
  const normalizedQuery = normalizeSearchTextForMatch(String(queryText || ''));
  if (!normalizedQuery) return [];
  const beautyBucket = String(beautyQueryProfile?.bucket || '').trim().toLowerCase();
  const isBeautyQuery = Boolean(beautyQueryProfile?.isBeautyQuery);
  if (isBeautyQuery && beautyBucket && beautyBucket !== 'skincare') {
    return [];
  }
  const intents = [];
  for (const [term, ingredientId] of Object.entries(STRICT_FIND_PRODUCTS_MULTI_INGREDIENT_ALIASES)) {
    if (!normalizedQuery.includes(normalizeSearchTextForMatch(term))) continue;
    if (!intents.includes(ingredientId)) intents.push(ingredientId);
  }
  return intents;
}

function resolveStrictFindProductsMultiIngredientIntentTerms(ingredientId) {
  const normalizedIngredientId = String(ingredientId || '').trim().toLowerCase();
  if (!normalizedIngredientId) return [];
  const out = [normalizedIngredientId.replace(/_/g, ' ')];
  for (const [term, mappedIngredientId] of Object.entries(STRICT_FIND_PRODUCTS_MULTI_INGREDIENT_ALIASES)) {
    if (mappedIngredientId !== normalizedIngredientId) continue;
    const normalizedTerm = normalizeSearchTextForMatch(term);
    if (normalizedTerm && !out.includes(normalizedTerm)) out.push(normalizedTerm);
  }
  if (normalizedIngredientId === 'ascorbic_acid') {
    for (const term of ['ascorbic', 'vitamin']) {
      if (!out.includes(term)) out.push(term);
    }
  }
  return out;
}

function extractStrictFindProductsMultiShadeOptionIntents(queryText, beautyQueryProfile = null) {
  const normalizedQuery = normalizeSearchTextForMatch(String(queryText || ''));
  if (!normalizedQuery) return [];
  const beautyBucket = String(beautyQueryProfile?.bucket || '').trim().toLowerCase();
  const isBeautyQuery = Boolean(beautyQueryProfile?.isBeautyQuery);
  if (isBeautyQuery && !['general', 'base_makeup', 'lip_makeup'].includes(beautyBucket)) {
    return [];
  }
  if (!STRICT_FIND_PRODUCTS_MULTI_SHADE_CATEGORY_TERMS.some((term) => normalizedQuery.includes(term))) {
    return [];
  }
  const intents = [];
  const shadePattern = /\bshade\s+([a-z0-9][a-z0-9 ]{0,30})\b/g;
  for (const match of normalizedQuery.matchAll(shadePattern)) {
    const rawValue = normalizeSearchTextForMatch(match[1] || '');
    if (!rawValue) continue;
    const label = `shade_${rawValue.replace(/\s+/g, '_')}`;
    if (!intents.includes(label)) intents.push(label);
  }
  return intents;
}

function hasStrictFindProductsMultiBudgetConstraint(queryText) {
  const normalizedQuery = normalizeSearchTextForMatch(String(queryText || ''));
  if (!normalizedQuery) return false;
  return (
    /\b(under|below|over|above|less than|more than)\s+\d+\b/.test(normalizedQuery) ||
    /\b\d+\s*(usd|eur|gbp|cny)\b/.test(normalizedQuery) ||
    /(?:€|\$|£)\s*\d+/.test(String(queryText || ''))
  );
}

function extractStrictFindProductsMultiVisibleAttributeIntents(queryText) {
  const normalizedQuery = normalizeSearchTextForMatch(String(queryText || ''));
  if (!normalizedQuery) return [];
  return STRICT_FIND_PRODUCTS_MULTI_VISIBLE_ATTRIBUTE_TERMS.filter((term) =>
    normalizedQuery.includes(normalizeSearchTextForMatch(term)),
  );
}

function getStrictFindProductsMultiConstraintDecision({ search = {}, metadata = {} } = {}) {
  const requestedCatalogSurface = getRequestedCatalogSurface({ search, metadata });
  const rawQuery = String(search?.query || '').trim();
  if (!rawQuery && isStrictCommerceCatalogSurface(requestedCatalogSurface)) {
    return {
      enabled: true,
      catalogSurface: requestedCatalogSurface,
      strictConstraintQuery: false,
      strictConstraintReason: null,
      ingredientIntents: [],
      shadeOptionIntents: [],
    };
  }
  if (!rawQuery) {
    return {
      enabled: false,
      catalogSurface: null,
      strictConstraintQuery: false,
      strictConstraintReason: null,
      ingredientIntents: [],
      shadeOptionIntents: [],
    };
  }

  const beautyQueryProfile = buildBeautyQueryProfile({ rawQuery });
  const ingredientIntents = extractStrictFindProductsMultiIngredientIntents(
    rawQuery,
    beautyQueryProfile,
  );
  const shadeOptionIntents = extractStrictFindProductsMultiShadeOptionIntents(
    rawQuery,
    beautyQueryProfile,
  );
  const hasIngredientConstraint = ingredientIntents.length > 0;
  const hasShadeConstraint = shadeOptionIntents.length > 0;
  if (!hasIngredientConstraint && !hasShadeConstraint) {
    return {
      enabled: false,
      catalogSurface: null,
      strictConstraintQuery: false,
      strictConstraintReason: null,
      ingredientIntents,
      shadeOptionIntents,
    };
  }

  const visibleAttributeIntents = extractStrictFindProductsMultiVisibleAttributeIntents(rawQuery);
  const hasBudgetConstraint = hasStrictFindProductsMultiBudgetConstraint(rawQuery);
  const hasAdditionalConstraint =
    visibleAttributeIntents.length > 0 ||
    hasBudgetConstraint ||
    (hasIngredientConstraint && hasShadeConstraint);
  const strictConstraintReason = hasAdditionalConstraint
    ? 'multi_constraint'
    : hasIngredientConstraint
      ? 'ingredient'
      : 'shade';

  return {
    enabled: isStrictCommerceCatalogSurface(requestedCatalogSurface) || hasIngredientConstraint || hasShadeConstraint,
    catalogSurface: isStrictCommerceCatalogSurface(requestedCatalogSurface)
      ? requestedCatalogSurface
      : 'agent_api',
    strictConstraintQuery: hasIngredientConstraint || hasShadeConstraint,
    strictConstraintReason,
    ingredientIntents,
    shadeOptionIntents,
  };
}

function shouldUseStrictFindProductsMultiInvoke({ search = {}, metadata = {} } = {}) {
  return getStrictFindProductsMultiConstraintDecision({ search, metadata }).enabled;
}

// Thin delegate — implementation consolidated in services/beautyRelevanceGate
// (Class 2). Same for the two matchers below and the category-path helpers:
// keep the local names so the ~50 call sites and their tests stay untouched,
// while the vocabulary itself has exactly one home.
function extractStrictFindProductsMultiSkincareCategoryIntents(queryText) {
  return beautyRelevanceGate.extractSkincareFormIntents(queryText);
}

function productMatchesStrictIngredientPrefetch(product, { ingredientIntents = [], categoryIntents = [], inStockOnly = true } = {}) {
  if (!product || typeof product !== 'object') return false;
  const productIngredientIds = Array.isArray(product.ingredient_ids)
    ? product.ingredient_ids.map((value) => String(value || '').trim().toLowerCase()).filter(Boolean)
    : [];
  const productIngredientText = normalizeSearchTextForMatch(
    [
      ...(Array.isArray(product.ingredient_tokens) ? product.ingredient_tokens : []),
      ...(Array.isArray(product.key_ingredients) ? product.key_ingredients : []),
      ...(Array.isArray(product.active_ingredients) ? product.active_ingredients : []),
      ...(Array.isArray(product.external_seed_recall?.ingredient_tokens)
        ? product.external_seed_recall.ingredient_tokens
        : []),
    ]
      .filter(Boolean)
      .join(' '),
  );
  if (ingredientIntents.length > 0) {
    const hasEveryIngredientIntent = ingredientIntents.every((intent) => {
      if (productIngredientIds.includes(intent)) return true;
      return resolveStrictFindProductsMultiIngredientIntentTerms(intent).some((term) =>
        productIngredientText.includes(term),
      );
    });
    if (!hasEveryIngredientIntent) return false;
  }

  const visibilityHaystack = normalizeSearchTextForMatch(
    [
      product.title,
      product.product_type,
      product.category,
      product.description,
      product.canonical_url,
      product.destination_url,
    ]
      .filter(Boolean)
      .join(' '),
  );
  if (
    categoryIntents.length > 0 &&
    !categoryIntents.every((intent) => visibilityHaystack.includes(normalizeSearchTextForMatch(intent)))
  ) {
    return false;
  }

  if (inStockOnly && product.in_stock !== true) {
    return false;
  }

  return true;
}

function productMatchesStrictSkincareCategoryIntent(product = {}, categoryIntent = '') {
  return beautyRelevanceGate.productMatchesSkincareFormIntent(product, categoryIntent);
}

function filterStrictIngredientProductsByCategoryIntents(products = [], categoryIntents = []) {
  return beautyRelevanceGate.filterProductsBySkincareFormIntents(products, categoryIntents);
}

async function prefetchStrictIngredientExternalSeedCandidates({
  search = {},
  strictInvokeDecision = null,
  rawQueryText = null,
} = {}) {
  if (!process.env.DATABASE_URL) return [];

  const decision =
    strictInvokeDecision && typeof strictInvokeDecision === 'object'
      ? strictInvokeDecision
      : getStrictFindProductsMultiConstraintDecision({ search, metadata: {} });
  const ingredientIntents = Array.isArray(decision?.ingredientIntents)
    ? decision.ingredientIntents.map((value) => String(value || '').trim().toLowerCase()).filter(Boolean)
    : [];
  if (!decision?.strictConstraintQuery || ingredientIntents.length === 0) {
    return [];
  }

  const queryText = String(rawQueryText || search?.query || '').trim();
  const categoryIntents = extractStrictFindProductsMultiSkincareCategoryIntents(queryText);
  const ingredientTerms = ingredientIntents.flatMap((value) =>
    resolveStrictFindProductsMultiIngredientIntentTerms(value),
  );
  const textTerms = [
    ...ingredientTerms,
    ...(categoryIntents.length > 0 ? categoryIntents : STRICT_FIND_PRODUCTS_MULTI_SKINCARE_CATEGORY_TERMS),
  ];

  const buildPatterns = (values) =>
    Array.from(
      new Set(
        (Array.isArray(values) ? values : [])
          .map((value) => `%${String(value || '').trim().toLowerCase()}%`)
          .filter((value) => value.length > 2),
      ),
    );
  const ingredientPatterns = buildPatterns(ingredientTerms.length > 0 ? ingredientTerms : textTerms);
  const recallPatterns = buildPatterns(textTerms);
  if (ingredientPatterns.length === 0 && recallPatterns.length === 0) {
    return [];
  }

  const primaryStageLimit = Math.min(
    240,
    Math.max(STRICT_FIND_PRODUCTS_MULTI_EXTERNAL_PREFETCH_LIMIT * 17, 160),
  );
  const fallbackStageLimit = Math.min(
    160,
    Math.max(STRICT_FIND_PRODUCTS_MULTI_EXTERNAL_PREFETCH_LIMIT * 4, 48),
  );
  const structuredIngredientEvidenceClauses = [
    "COALESCE(jsonb_array_length(CASE WHEN jsonb_typeof(COALESCE(seed_data, '{}'::jsonb)->'reviewed_ingredient_ids') = 'array' THEN COALESCE(seed_data, '{}'::jsonb)->'reviewed_ingredient_ids' ELSE '[]'::jsonb END), 0) > 0",
    "COALESCE(jsonb_array_length(CASE WHEN jsonb_typeof(COALESCE(seed_data, '{}'::jsonb)->'ingredient_ids') = 'array' THEN COALESCE(seed_data, '{}'::jsonb)->'ingredient_ids' ELSE '[]'::jsonb END), 0) > 0",
    "COALESCE(jsonb_array_length(CASE WHEN jsonb_typeof(COALESCE(seed_data, '{}'::jsonb)->'snapshot'->'reviewed_ingredient_ids') = 'array' THEN COALESCE(seed_data, '{}'::jsonb)->'snapshot'->'reviewed_ingredient_ids' ELSE '[]'::jsonb END), 0) > 0",
    "COALESCE(jsonb_array_length(CASE WHEN jsonb_typeof(COALESCE(seed_data, '{}'::jsonb)->'snapshot'->'ingredient_ids') = 'array' THEN COALESCE(seed_data, '{}'::jsonb)->'snapshot'->'ingredient_ids' ELSE '[]'::jsonb END), 0) > 0",
    "length(coalesce(seed_data#>>'{derived,recall,ingredient_tokens}', '')) > 0",
  ];
  const seedDataProjection = `
      jsonb_strip_nulls(jsonb_build_object(
        'title', coalesce(seed_data#>>'{derived,recall,retrieval_title}', seed_data#>>'{snapshot,title}', seed_data->>'title', title),
        'description', coalesce(seed_data#>>'{derived,recall,retrieval_summary}', seed_data#>>'{snapshot,description}', seed_data->>'description'),
        'category', coalesce(seed_data#>>'{derived,recall,category}', seed_data#>>'{snapshot,category}', seed_data->>'category'),
        'brand', coalesce(seed_data#>>'{derived,recall,brand_name}', seed_data#>>'{snapshot,brand}', seed_data->>'brand', seed_data->>'vendor'),
        'canonical_url', coalesce(seed_data#>>'{snapshot,canonical_url}', seed_data->>'canonical_url', canonical_url),
        'destination_url', coalesce(seed_data#>>'{snapshot,destination_url}', seed_data->>'destination_url', destination_url),
        'image_url', coalesce(seed_data#>>'{snapshot,image_url}', seed_data->>'image_url', image_url),
        'price_amount', coalesce(seed_data#>>'{snapshot,price_amount}', seed_data->>'price_amount', price_amount::text),
        'price_currency', coalesce(seed_data#>>'{snapshot,price_currency}', seed_data->>'price_currency', price_currency),
        'availability', coalesce(seed_data#>>'{snapshot,availability}', seed_data->>'availability', availability),
        'reviewed_ingredient_ids', CASE WHEN jsonb_typeof(coalesce(seed_data, '{}'::jsonb)->'reviewed_ingredient_ids') = 'array' THEN coalesce(seed_data, '{}'::jsonb)->'reviewed_ingredient_ids' ELSE NULL END,
        'ingredient_ids', CASE WHEN jsonb_typeof(coalesce(seed_data, '{}'::jsonb)->'ingredient_ids') = 'array' THEN coalesce(seed_data, '{}'::jsonb)->'ingredient_ids' ELSE NULL END,
        'ingredient_tokens', CASE WHEN jsonb_typeof(coalesce(seed_data, '{}'::jsonb)#>'{derived,recall,ingredient_tokens}') = 'array' THEN coalesce(seed_data, '{}'::jsonb)#>'{derived,recall,ingredient_tokens}' ELSE NULL END,
        'derived', jsonb_build_object(
          'recall', jsonb_strip_nulls(jsonb_build_object(
            'retrieval_title', seed_data#>>'{derived,recall,retrieval_title}',
            'retrieval_summary', seed_data#>>'{derived,recall,retrieval_summary}',
            'category', seed_data#>>'{derived,recall,category}',
            'brand_name', seed_data#>>'{derived,recall,brand_name}',
            'ingredient_tokens', CASE WHEN jsonb_typeof(coalesce(seed_data, '{}'::jsonb)#>'{derived,recall,ingredient_tokens}') = 'array' THEN coalesce(seed_data, '{}'::jsonb)#>'{derived,recall,ingredient_tokens}' ELSE NULL END
          ))
        ),
        'snapshot', jsonb_strip_nulls(jsonb_build_object(
          'title', seed_data#>>'{snapshot,title}',
          'description', seed_data#>>'{snapshot,description}',
          'category', seed_data#>>'{snapshot,category}',
          'brand', seed_data#>>'{snapshot,brand}',
          'canonical_url', seed_data#>>'{snapshot,canonical_url}',
          'destination_url', seed_data#>>'{snapshot,destination_url}',
          'image_url', seed_data#>>'{snapshot,image_url}',
          'price_amount', seed_data#>>'{snapshot,price_amount}',
          'price_currency', seed_data#>>'{snapshot,price_currency}',
          'availability', seed_data#>>'{snapshot,availability}'
        ))
      )) AS seed_data,
  `;
  const selectColumns = `
      id,
      external_product_id,
      market,
      tool,
      destination_url,
      canonical_url,
      domain,
      title,
      image_url,
      price_amount,
      price_currency,
      availability,
${seedDataProjection}
      status,
      attached_product_key,
      created_at,
      updated_at
  `;
  const buildStageSql = (matchSql) => `
    SELECT
${selectColumns}
    FROM external_product_seeds
    WHERE status = 'active'
      AND attached_product_key IS NULL
      AND market = $1
      AND (
        ${structuredIngredientEvidenceClauses.join(' OR ')}
      )
      AND (${matchSql})
    ORDER BY updated_at DESC NULLS LAST, created_at DESC NULLS LAST
    LIMIT $3
  `;

  const stages = [
    {
      name: 'ingredient_tokens',
      patterns: ingredientPatterns,
      limit: primaryStageLimit,
      matchSql: `${EXTERNAL_SEED_RECALL_SQL_FIELDS.ingredientTokens} LIKE ANY($2::text[])`,
    },
    {
      name: 'recall_title',
      patterns: recallPatterns,
      limit: fallbackStageLimit,
      matchSql: `${EXTERNAL_SEED_RECALL_SQL_FIELDS.retrievalTitle} LIKE ANY($2::text[])`,
    },
    {
      name: 'title',
      patterns: recallPatterns,
      limit: fallbackStageLimit,
      matchSql: "lower(coalesce(title, '')) LIKE ANY($2::text[])",
    },
    {
      name: 'recall_summary',
      patterns: recallPatterns,
      limit: fallbackStageLimit,
      matchSql: `${EXTERNAL_SEED_RECALL_SQL_FIELDS.retrievalSummary} LIKE ANY($2::text[])`,
    },
    {
      name: 'alias_tokens',
      patterns: recallPatterns,
      limit: fallbackStageLimit,
      matchSql: "lower(coalesce(seed_data#>>'{derived,recall,alias_tokens}', '')) LIKE ANY($2::text[])",
    },
    {
      name: 'canonical_url',
      patterns: recallPatterns,
      limit: fallbackStageLimit,
      matchSql: "lower(coalesce(canonical_url, '')) LIKE ANY($2::text[])",
    },
    {
      name: 'destination_url',
      patterns: recallPatterns,
      limit: fallbackStageLimit,
      matchSql: "lower(coalesce(destination_url, '')) LIKE ANY($2::text[])",
    },
  ].filter((stage) => Array.isArray(stage.patterns) && stage.patterns.length > 0);

  try {
    const candidates = [];
    const seen = new Set();
    for (const stage of stages) {
      const result = await query(buildStageSql(stage.matchSql), ['US', stage.patterns, stage.limit]);
      for (const row of result?.rows || []) {
        const product = buildExternalSeedProduct(row);
        if (!product) continue;
        product.market = row.market || 'US';
        product.tool = row.tool || '*';
        product.external_seed_id = product.external_seed_id || row.id || null;
        if (!productMatchesStrictIngredientPrefetch(product, {
          ingredientIntents,
          categoryIntents,
          inStockOnly: search?.in_stock_only !== false,
        })) {
          continue;
        }
        const dedupeKey = String(product.product_id || product.id || '').trim();
        if (!dedupeKey || seen.has(dedupeKey)) continue;
        seen.add(dedupeKey);
        candidates.push(product);
        if (candidates.length >= STRICT_FIND_PRODUCTS_MULTI_EXTERNAL_PREFETCH_LIMIT) break;
      }
      if (
        candidates.length >= STRICT_FIND_PRODUCTS_MULTI_EXTERNAL_PREFETCH_LIMIT ||
        candidates.length > 0
      ) {
        break;
      }
    }
    return candidates;
  } catch (err) {
    logger.warn(
      { err: err?.message || String(err), queryText, ingredientIntents, categoryIntents },
      'strict ingredient external seed prefetch failed',
    );
    return [];
  }
}

async function buildFindProductsMultiInvokeBody({
  payload = {},
  search = {},
  metadata = {},
  clientChannel = 'shop',
  gatewayRequestId = null,
  defaultSearchAllMerchants = false,
  strictInvokeDecision = null,
  rawQueryText = null,
} = {}) {
  const resolvedStrictInvokeDecision =
    strictInvokeDecision && typeof strictInvokeDecision === 'object'
      ? strictInvokeDecision
      : getStrictFindProductsMultiConstraintDecision({ search, metadata });
  const requestedCatalogSurface =
    String(resolvedStrictInvokeDecision?.catalogSurface || '').trim().toLowerCase() ||
    getRequestedCatalogSurface({ search, metadata });
  const normalizedSearch = {
    ...(search && typeof search === 'object' ? search : {}),
    ...(requestedCatalogSurface ? { catalog_surface: requestedCatalogSurface } : {}),
    ...(
      resolvedStrictInvokeDecision?.strictConstraintQuery && String(rawQueryText || '').trim()
        ? { query: String(rawQueryText || '').trim() }
        : {}
    ),
  };
  const prefetchedExternalSeedCandidates = await prefetchStrictIngredientExternalSeedCandidates({
    search: normalizedSearch,
    strictInvokeDecision: resolvedStrictInvokeDecision,
    rawQueryText,
  });
  return {
    operation: 'find_products_multi',
    payload: {
      search: buildSearchProductsV2Body({
        payload,
        search: normalizedSearch,
        metadata,
        clientChannel,
        gatewayRequestId,
        defaultSearchAllMerchants,
      }),
    },
    metadata: pruneEmptyFields({
      ...(metadata && typeof metadata === 'object' ? metadata : {}),
      catalog_surface: requestedCatalogSurface || undefined,
      ...(prefetchedExternalSeedCandidates.length > 0
        ? {
            external_seed_candidates: prefetchedExternalSeedCandidates,
            external_seed_prefetch_source: 'agent_strict_ingredient_prefetch',
          }
        : {}),
    }),
  };
}

function isCanonicalSearchProduct(product) {
  return Boolean(product) && typeof product === 'object' && !Array.isArray(product) && (
    Array.isArray(product.offers) ||
    Array.isArray(product.variants) ||
    typeof product.canonical_title === 'string' ||
    (product.provenance && typeof product.provenance === 'object' && !Array.isArray(product.provenance))
  );
}

function getCanonicalSearchFallbackReason(err) {
  const status = Number(err?.response?.status || 0) || 0;
  if ([404, 405, 415, 422].includes(status)) return `status_${status}`;
  const message = String(err?.message || '').toLowerCase();
  if (message.includes('nock: no match for request')) return 'contract_not_mocked';
  return null;
}

function normalizeCanonicalSearchVariant(variant) {
  if (!isPlainObject(variant)) return null;
  const attrs = isPlainObject(variant.variant_attributes) ? variant.variant_attributes : {};
  return pruneEmptyFields({
    ...variant,
    id: firstNonEmptyString(variant.id, variant.variant_id),
    variant_id: firstNonEmptyString(variant.variant_id, variant.id),
    title: firstNonEmptyString(attrs.title, variant.title),
    sku: firstNonEmptyString(attrs.sku, variant.sku),
    option1: firstNonEmptyString(attrs.option1, variant.option1),
    option2: firstNonEmptyString(attrs.option2, variant.option2),
    option3: firstNonEmptyString(attrs.option3, variant.option3),
    selected_options: Array.isArray(attrs.selected_options) ? attrs.selected_options : undefined,
  });
}

function normalizeCanonicalSearchProductCompat(product) {
  if (!isCanonicalSearchProduct(product)) return product;
  const provenance = isPlainObject(product.provenance) ? product.provenance : {};
  const primaryOffer =
    Array.isArray(product.offers) && product.offers.length > 0 && isPlainObject(product.offers[0])
      ? product.offers[0]
      : {};
  const availability = isPlainObject(primaryOffer.availability) ? primaryOffer.availability : {};
  const shippingSummary = isPlainObject(primaryOffer.shipping_summary) ? primaryOffer.shipping_summary : {};
  const imageRefs = Array.isArray(product.image_refs)
    ? product.image_refs.map((value) => String(value || '').trim()).filter(Boolean)
    : [];
  const normalizedVariants = Array.isArray(product.variants)
    ? product.variants.map((variant) => normalizeCanonicalSearchVariant(variant)).filter(Boolean)
    : [];

  return pruneEmptyFields({
    ...product,
    id: firstNonEmptyString(product.id, product.product_id),
    product_id: firstNonEmptyString(product.product_id, product.id),
    merchant_id: firstNonEmptyString(
      product.merchant_id,
      provenance.merchant_id,
      primaryOffer.merchant_id,
    ),
    merchant_name: firstNonEmptyString(product.merchant_name, provenance.merchant_name),
    title: firstNonEmptyString(product.title, product.canonical_title, product.name),
    name: firstNonEmptyString(product.name, product.canonical_title, product.title),
    category: firstNonEmptyString(product.category, product.canonical_category, product.product_type),
    product_type: firstNonEmptyString(
      product.product_type,
      product.canonical_category,
      product.category,
    ),
    brand: firstNonEmptyString(product.brand, product.vendor),
    vendor: firstNonEmptyString(product.vendor, product.brand),
    offer_id: firstNonEmptyString(product.offer_id, primaryOffer.offer_id),
    merchant_sku: firstNonEmptyString(product.sku, primaryOffer.merchant_sku),
    price: primaryOffer.price != null ? primaryOffer.price : product.price,
    currency: firstNonEmptyString(product.currency, primaryOffer.currency),
    in_stock:
      typeof availability.in_stock === 'boolean'
        ? availability.in_stock
        : product.in_stock,
    inventory_quantity:
      availability.inventory_quantity != null
        ? availability.inventory_quantity
        : product.inventory_quantity,
    shipping: Object.keys(shippingSummary).length > 0 ? shippingSummary : product.shipping,
    estimated_delivery: firstNonEmptyString(
      product.estimated_delivery,
      shippingSummary.estimated_delivery,
    ),
    shipping_fee:
      shippingSummary.shipping_fee != null ? shippingSummary.shipping_fee : product.shipping_fee,
    source: firstNonEmptyString(product.source, provenance.source_type, primaryOffer.source_type),
    platform: firstNonEmptyString(
      product.platform,
      provenance.connector,
      primaryOffer.connector,
    ),
    cached_at: firstNonEmptyString(
      product.cached_at,
      provenance.freshness_ts,
      primaryOffer.freshness_ts,
    ),
    updated_at: firstNonEmptyString(
      product.updated_at,
      provenance.freshness_ts,
      primaryOffer.freshness_ts,
    ),
    score:
      product.score != null
        ? product.score
        : primaryOffer.confidence != null
          ? primaryOffer.confidence
          : product.confidence,
    confidence:
      product.confidence != null ? product.confidence : primaryOffer.confidence,
    image_url: firstNonEmptyString(product.image_url, imageRefs[0]),
    images: imageRefs.length > 0 ? imageRefs : product.images,
    variants: normalizedVariants.length > 0 ? normalizedVariants : product.variants,
  });
}

function extractCanonicalQuoteId(payload = {}) {
  if (!isPlainObject(payload)) return null;
  if (isPlainObject(payload.quote)) {
    return firstNonEmptyString(payload.quote.quote_id, payload.quote.quoteId, payload.quote_id);
  }
  return firstNonEmptyString(payload.quote_id, payload.quoteId);
}

function normalizePreviewQuoteCompat(upstreamPayload = {}) {
  if (!isPlainObject(upstreamPayload) || !isPlainObject(upstreamPayload.quote)) {
    return upstreamPayload;
  }
  const quote = upstreamPayload.quote;
  const priceBreakdown = isPlainObject(quote.price_breakdown) ? quote.price_breakdown : {};
  const shippingBreakdown = isPlainObject(quote.shipping_breakdown) ? quote.shipping_breakdown : {};
  const taxBreakdown = isPlainObject(quote.tax_breakdown) ? quote.tax_breakdown : {};
  return {
    ...upstreamPayload,
    ...quote,
    pricing: pruneEmptyFields({
      subtotal: priceBreakdown.subtotal,
      discount_total: priceBreakdown.discount_total,
      shipping_fee: shippingBreakdown.shipping_fee,
      tax: taxBreakdown.tax,
      total: priceBreakdown.total,
      currency: firstNonEmptyString(priceBreakdown.currency, quote.currency),
    }),
    delivery_options: Array.isArray(shippingBreakdown.delivery_options)
      ? shippingBreakdown.delivery_options
      : [],
    engine: firstNonEmptyString(quote?.provenance?.engine, quote?.policy_snapshot?.engine),
    engine_ref: firstNonEmptyString(quote?.provenance?.engine_ref, quote?.policy_snapshot?.engine_ref),
    quote,
  };
}

function normalizeCreateOrderCompat(upstreamPayload = {}) {
  if (!isPlainObject(upstreamPayload) || !isPlainObject(upstreamPayload.order)) {
    return upstreamPayload;
  }
  const order = upstreamPayload.order;
  const amounts = isPlainObject(order.amounts) ? order.amounts : {};
  const fulfillmentSummary = isPlainObject(order.fulfillment_summary) ? order.fulfillment_summary : {};
  const paymentSummary = isPlainObject(upstreamPayload.payment)
    ? upstreamPayload.payment
    : isPlainObject(order.payment_summary)
      ? order.payment_summary
      : {};
  return {
    ...upstreamPayload,
    ...order,
    total_amount: amounts.total != null ? amounts.total : upstreamPayload.total_amount,
    subtotal: amounts.subtotal != null ? amounts.subtotal : upstreamPayload.subtotal,
    discount_total:
      amounts.discount_total != null ? amounts.discount_total : upstreamPayload.discount_total,
    shipping_fee: amounts.shipping_fee != null ? amounts.shipping_fee : upstreamPayload.shipping_fee,
    tax: amounts.tax != null ? amounts.tax : upstreamPayload.tax,
    currency: firstNonEmptyString(amounts.currency, upstreamPayload.currency),
    payment_status: firstNonEmptyString(order.payment_status, upstreamPayload.payment_status),
    payment: paymentSummary,
    tracking: Object.keys(fulfillmentSummary).length ? fulfillmentSummary : upstreamPayload.tracking,
    ...(Object.prototype.hasOwnProperty.call(upstreamPayload, 'order_lines')
      ? { order_lines: upstreamPayload.order_lines }
      : {}),
    order,
  };
}

function normalizeGetOrderStatusCompat(upstreamPayload = {}) {
  if (!isPlainObject(upstreamPayload)) {
    return upstreamPayload;
  }
  const tracking = isPlainObject(upstreamPayload.tracking) ? upstreamPayload.tracking : {};
  const order = isPlainObject(upstreamPayload.order) ? upstreamPayload.order : {};
  const amounts = isPlainObject(order.amounts) ? order.amounts : {};
  const pricing = isPlainObject(tracking.pricing)
    ? tracking.pricing
    : isPlainObject(upstreamPayload.pricing)
      ? upstreamPayload.pricing
      : {};

  const normalizedPricing = pruneEmptyFields({
    subtotal:
      pricing.subtotal != null
        ? pricing.subtotal
        : tracking.subtotal != null
          ? tracking.subtotal
          : amounts.subtotal,
    discount_total:
      pricing.discount_total != null
        ? pricing.discount_total
        : tracking.discount_total != null
          ? tracking.discount_total
          : amounts.discount_total,
    shipping_fee:
      pricing.shipping_fee != null
        ? pricing.shipping_fee
        : tracking.shipping_fee != null
          ? tracking.shipping_fee
          : amounts.shipping_fee,
    tax:
      pricing.tax != null ? pricing.tax : tracking.tax != null ? tracking.tax : amounts.tax,
    total:
      pricing.total != null
        ? pricing.total
        : tracking.total != null
          ? tracking.total
          : amounts.total,
    currency: firstNonEmptyString(
      pricing.currency,
      tracking.currency,
      amounts.currency,
      upstreamPayload.currency,
      order.currency,
    ),
  });

  return {
    ...upstreamPayload,
    ...tracking,
    subtotal:
      normalizedPricing.subtotal != null ? normalizedPricing.subtotal : upstreamPayload.subtotal,
    discount_total:
      normalizedPricing.discount_total != null
        ? normalizedPricing.discount_total
        : upstreamPayload.discount_total,
    shipping_fee:
      normalizedPricing.shipping_fee != null
        ? normalizedPricing.shipping_fee
        : upstreamPayload.shipping_fee,
    tax: normalizedPricing.tax != null ? normalizedPricing.tax : upstreamPayload.tax,
    total: normalizedPricing.total != null ? normalizedPricing.total : upstreamPayload.total,
    currency: firstNonEmptyString(
      normalizedPricing.currency,
      upstreamPayload.currency,
      order.currency,
    ),
    pricing: normalizedPricing,
    order:
      Object.keys(order).length > 0
        ? {
            ...order,
            pricing: normalizedPricing,
          }
        : upstreamPayload.order,
  };
}
