// Resolve-product candidates cache (Phase 2 perf: avoid repeated slow scans).
const RESOLVE_PRODUCT_CANDIDATES_CACHE_ENABLED =
  process.env.RESOLVE_PRODUCT_CANDIDATES_CACHE_ENABLED !== 'false';
const RESOLVE_PRODUCT_CANDIDATES_CACHE = new Map(); // cacheKey -> { value, storedAtMs, expiresAtMs }
const RESOLVE_PRODUCT_CANDIDATES_CACHE_METRICS = {
  hits: 0,
  misses: 0,
  sets: 0,
  bypasses: 0,
};
const RESOLVE_PRODUCT_CANDIDATES_TTL_MS = parseTimeoutMs(
  process.env.RESOLVE_PRODUCT_CANDIDATES_TTL_MS,
  60 * 1000,
);

function getResolveProductCandidatesCacheEntry(cacheKey) {
  const key = String(cacheKey || '');
  if (!key) return null;
  const hit = RESOLVE_PRODUCT_CANDIDATES_CACHE.get(key);
  if (!hit) {
    RESOLVE_PRODUCT_CANDIDATES_CACHE_METRICS.misses += 1;
    return null;
  }
  if (hit.expiresAtMs && hit.expiresAtMs < Date.now()) {
    RESOLVE_PRODUCT_CANDIDATES_CACHE.delete(key);
    RESOLVE_PRODUCT_CANDIDATES_CACHE_METRICS.misses += 1;
    return null;
  }
  RESOLVE_PRODUCT_CANDIDATES_CACHE_METRICS.hits += 1;
  return hit;
}

function setResolveProductCandidatesCache(
  cacheKey,
  value,
  ttlMs = RESOLVE_PRODUCT_CANDIDATES_TTL_MS,
) {
  const key = String(cacheKey || '');
  if (!key) return;
  const ttl = Number(ttlMs) || RESOLVE_PRODUCT_CANDIDATES_TTL_MS;
  RESOLVE_PRODUCT_CANDIDATES_CACHE_METRICS.sets += 1;
  RESOLVE_PRODUCT_CANDIDATES_CACHE.set(key, {
    value,
    storedAtMs: Date.now(),
    expiresAtMs: Date.now() + Math.max(5_000, ttl),
  });
}

function snapshotResolveProductCandidatesCacheStats() {
  return {
    enabled: RESOLVE_PRODUCT_CANDIDATES_CACHE_ENABLED,
    ttl_ms: RESOLVE_PRODUCT_CANDIDATES_TTL_MS,
    size: RESOLVE_PRODUCT_CANDIDATES_CACHE.size,
    ...RESOLVE_PRODUCT_CANDIDATES_CACHE_METRICS,
  };
}

function safeCloneJson(value) {
  if (value == null) return value;
  try {
    return JSON.parse(JSON.stringify(value));
  } catch {
    return value;
  }
}

function parsePdpCorePrewarmTargets(raw, defaultMerchantId) {
  const source = String(raw || '').trim();
  if (!source) return [];

  const fallbackMerchantId = String(defaultMerchantId || '').trim();
  const seen = new Set();
  const out = [];

  for (const tokenRaw of source.split(/[,\n]/g)) {
    const token = String(tokenRaw || '').trim();
    if (!token) continue;

    let merchantId = fallbackMerchantId;
    let productId = token;
    const sepIdx = token.indexOf(':');
    if (sepIdx > 0) {
      merchantId = String(token.slice(0, sepIdx)).trim() || fallbackMerchantId;
      productId = String(token.slice(sepIdx + 1)).trim();
    }
    if (!merchantId || !productId) continue;

    const dedupeKey = `${merchantId}:${productId}`;
    if (seen.has(dedupeKey)) continue;
    seen.add(dedupeKey);
    out.push({ merchant_id: merchantId, product_id: productId });
  }

  return out;
}

const PROXY_SEARCH_RESOLVER_CACHE = new Map(); // key -> { value, expiresAtMs }

function buildProxySearchResolverCacheKey({
  queryText,
  lang,
  preferMerchants,
  searchAllMerchants,
  fetchDetail,
  resolverTimeoutMs,
}) {
  const timeoutBucket = Number.isFinite(Number(resolverTimeoutMs))
    ? Math.max(100, Math.round(Number(resolverTimeoutMs) / 50) * 50)
    : null;
  return JSON.stringify({
    q: String(queryText || '').trim().toLowerCase(),
    lang: String(lang || '').trim().toLowerCase() || 'en',
    prefer_merchants: Array.isArray(preferMerchants)
      ? preferMerchants.map((item) => String(item || '').trim()).filter(Boolean)
      : [],
    search_all_merchants: searchAllMerchants === true ? true : false,
    fetch_detail: fetchDetail === true,
    resolver_timeout_ms_bucket: timeoutBucket,
  });
}

function getProxySearchResolverCacheEntry(cacheKey) {
  const key = String(cacheKey || '');
  if (!key) return null;
  const hit = PROXY_SEARCH_RESOLVER_CACHE.get(key);
  if (!hit) return null;
  if (hit.expiresAtMs && hit.expiresAtMs < Date.now()) {
    PROXY_SEARCH_RESOLVER_CACHE.delete(key);
    return null;
  }
  return safeCloneJson(hit.value);
}

function setProxySearchResolverCacheEntry(cacheKey, value, ttlMs = PROXY_SEARCH_RESOLVER_CACHE_TTL_MS) {
  const key = String(cacheKey || '');
  if (!key) return;
  const ttl = Math.max(500, Number(ttlMs) || PROXY_SEARCH_RESOLVER_CACHE_TTL_MS);
  while (PROXY_SEARCH_RESOLVER_CACHE.size >= PROXY_SEARCH_RESOLVER_CACHE_MAX_ENTRIES) {
    const firstKey = PROXY_SEARCH_RESOLVER_CACHE.keys().next().value;
    if (!firstKey) break;
    PROXY_SEARCH_RESOLVER_CACHE.delete(firstKey);
  }
  PROXY_SEARCH_RESOLVER_CACHE.set(key, {
    value: safeCloneJson(value),
    expiresAtMs: Date.now() + ttl,
  });
}

// Product-detail cache (avoid repeated slow upstream product fetches).
const PRODUCT_DETAIL_CACHE_ENABLED =
  process.env.PRODUCT_DETAIL_CACHE_ENABLED !== 'false';
const PRODUCT_DETAIL_CACHE = new Map(); // cacheKey -> { value, storedAtMs, expiresAtMs }
const PRODUCT_DETAIL_INFLIGHT = new Map(); // cacheKey -> Promise<product|null>
// Backstop budget for the offer-detail load.
//
// `totalTimeoutMs` is opt-in and defaults to 0, and only a minority of call
// sites pass one — so most loads ran with NO deadline at all. Combined with the
// in-flight map (which hands its stored promise to every concurrent caller for
// the same key and evicts it only when that promise settles), an upstream that
// never responds poisoned that cacheKey for the life of the process. That is
// the same failure mode that made three sitemap PDPs return zero bytes
// indefinitely — see resolveCatalogProductRefFromPivotaSignature.
//
// Deliberately generous: this exists to stop a wedged load from becoming a
// permanent outage, NOT to enforce a latency budget. Callers that want a tight
// deadline still pass `totalTimeoutMs`, and the smaller of the two wins.
const PRODUCT_DETAIL_MAX_LOAD_MS = Math.max(
  1000,
  Number(process.env.PRODUCT_DETAIL_MAX_LOAD_MS || 30000) || 30000,
);
const PRODUCT_DETAIL_INFLIGHT_MAX_ENTRIES = Math.max(
  50,
  Number(process.env.PRODUCT_DETAIL_INFLIGHT_MAX_ENTRIES || 300) || 300,
);
const PRODUCT_DETAIL_CACHE_METRICS = {
  hits: 0,
  misses: 0,
  sets: 0,
  bypasses: 0,
  evictions: 0,
  db_hits: 0,
};
const PRODUCT_DETAIL_CACHE_TTL_MS = parseTimeoutMs(
  process.env.PRODUCT_DETAIL_CACHE_TTL_MS,
  10 * 60 * 1000,
);
const PRODUCT_DETAIL_CACHE_MAX_ENTRIES = Math.max(
  50,
  Number(process.env.PRODUCT_DETAIL_CACHE_MAX_ENTRIES || 2000) || 2000,
);

// Per-merchant TTL overrides for the product-detail in-memory cache.
//
// Freshness contract:
//   - PRODUCT_DETAIL_CACHE_TTL_MS sets the default TTL (10 min) for all merchants.
//   - For known special-cases, override via named env var (resolved name = merchantId
//     uppercased + non-alnum -> '_'). Example: external_seed -> EXTERNAL_SEED.
//   - For ad-hoc/per-tenant overrides, set PRODUCT_DETAIL_CACHE_TTL_MS_OVERRIDES
//     as a JSON object: {"merch_x": 120000, "merch_y": 30000}.
//   - A resolved TTL <= 0 disables in-memory caching for that merchant (bypass).
//
// external_seed defaults to 0 (bypass) to preserve the contract from commit
// aa04f68f / regression test tests/external_seed_product_detail_fetch.test.js:362
// ("does not reuse in-memory cache for external_seed detail reads"). Operators can
// opt in to external_seed caching via PRODUCT_DETAIL_CACHE_TTL_MS_EXTERNAL_SEED=60000
// after validating no staleness regression in staging.
const PRODUCT_DETAIL_CACHE_TTL_MS_OVERRIDES = (() => {
  const raw = String(process.env.PRODUCT_DETAIL_CACHE_TTL_MS_OVERRIDES || '').trim();
  if (!raw) return {};
  try {
    const parsed = JSON.parse(raw);
    if (parsed && typeof parsed === 'object' && !Array.isArray(parsed)) {
      const out = {};
      for (const [k, v] of Object.entries(parsed)) {
        const n = Number(v);
        if (Number.isFinite(n)) out[String(k)] = Math.max(0, Math.trunc(n));
      }
      return out;
    }
  } catch {
    // Invalid JSON -> ignore, fall through to defaults.
  }
  return {};
})();

function merchantIdToEnvSuffix(merchantId) {
  return String(merchantId || '')
    .trim()
    .toUpperCase()
    .replace(/[^A-Z0-9]+/g, '_')
    .replace(/^_+|_+$/g, '');
}

function resolveProductDetailCacheTtlMs(merchantId) {
  const normalizedId = String(merchantId || '').trim();
  if (!normalizedId) return PRODUCT_DETAIL_CACHE_TTL_MS;

  if (Object.prototype.hasOwnProperty.call(PRODUCT_DETAIL_CACHE_TTL_MS_OVERRIDES, normalizedId)) {
    return PRODUCT_DETAIL_CACHE_TTL_MS_OVERRIDES[normalizedId];
  }

  const suffix = merchantIdToEnvSuffix(normalizedId);
  if (suffix) {
    const namedEnv = process.env[`PRODUCT_DETAIL_CACHE_TTL_MS_${suffix}`];
    if (namedEnv !== undefined && namedEnv !== '') {
      const n = Number(namedEnv);
      if (Number.isFinite(n)) return Math.max(0, Math.trunc(n));
    }
  }

  // Known historical special-case: external_seed defaults to bypass.
  // See freshness contract comment above.
  if (normalizedId === EXTERNAL_SEED_MERCHANT_ID) return 0;

  return PRODUCT_DETAIL_CACHE_TTL_MS;
}
const PRODUCT_DETAIL_STALE_LOOKUP_ENABLED =
  String(process.env.PRODUCT_DETAIL_STALE_LOOKUP_ENABLED || 'true').toLowerCase() === 'true';
const PRODUCT_DETAIL_STALE_MAX_AGE_HOURS = parsePositiveInt(
  process.env.PRODUCT_DETAIL_STALE_MAX_AGE_HOURS,
  30 * 24,
  { min: 1, max: 24 * 90 },
);
const PRODUCT_DETAIL_AUTHORITATIVE_INVOKE_ENABLED =
  String(process.env.PRODUCT_DETAIL_AUTHORITATIVE_INVOKE_ENABLED || 'true').toLowerCase() !== 'false';

function getProductDetailCacheEntry(cacheKey) {
  const key = String(cacheKey || '');
  if (!key) return null;
  const hit = PRODUCT_DETAIL_CACHE.get(key);
  if (!hit) {
    PRODUCT_DETAIL_CACHE_METRICS.misses += 1;
    return null;
  }
  if (hit.expiresAtMs && hit.expiresAtMs < Date.now()) {
    PRODUCT_DETAIL_CACHE.delete(key);
    PRODUCT_DETAIL_CACHE_METRICS.misses += 1;
    return null;
  }
  PRODUCT_DETAIL_CACHE_METRICS.hits += 1;
  return hit;
}

function setProductDetailCache(
  cacheKey,
  value,
  ttlMs = PRODUCT_DETAIL_CACHE_TTL_MS,
) {
  const key = String(cacheKey || '');
  if (!key) return;

  const ttl = Number(ttlMs) || PRODUCT_DETAIL_CACHE_TTL_MS;
  const now = Date.now();

  // Simple eviction (insertion order = oldest first).
  if (PRODUCT_DETAIL_CACHE.size >= PRODUCT_DETAIL_CACHE_MAX_ENTRIES) {
    const overflow = PRODUCT_DETAIL_CACHE.size - PRODUCT_DETAIL_CACHE_MAX_ENTRIES + 1;
    let removed = 0;
    for (const k of PRODUCT_DETAIL_CACHE.keys()) {
      PRODUCT_DETAIL_CACHE.delete(k);
      removed += 1;
      if (removed >= overflow) break;
    }
    if (removed > 0) PRODUCT_DETAIL_CACHE_METRICS.evictions += removed;
  }

  PRODUCT_DETAIL_CACHE_METRICS.sets += 1;
  PRODUCT_DETAIL_CACHE.set(key, {
    value: safeCloneJson(value),
    storedAtMs: now,
    expiresAtMs: now + Math.max(5_000, ttl),
  });
}

function snapshotProductDetailCacheStats() {
  // Resolved per-merchant TTLs so ops can verify env-var overrides loaded.
  // Includes the known external_seed default (0 = bypass) plus anything from
  // PRODUCT_DETAIL_CACHE_TTL_MS_OVERRIDES (JSON) plus any named overrides
  // discovered via PRODUCT_DETAIL_CACHE_TTL_MS_<MERCHANT_ID_UPPER>.
  const ttlByMerchant = { default: PRODUCT_DETAIL_CACHE_TTL_MS };
  const knownIds = new Set([EXTERNAL_SEED_MERCHANT_ID]);
  for (const id of Object.keys(PRODUCT_DETAIL_CACHE_TTL_MS_OVERRIDES)) knownIds.add(id);
  for (const id of knownIds) {
    ttlByMerchant[id] = resolveProductDetailCacheTtlMs(id);
  }
  return {
    enabled: PRODUCT_DETAIL_CACHE_ENABLED,
    ttl_ms: PRODUCT_DETAIL_CACHE_TTL_MS,
    ttl_ms_by_merchant: ttlByMerchant,
    max_entries: PRODUCT_DETAIL_CACHE_MAX_ENTRIES,
    size: PRODUCT_DETAIL_CACHE.size,
    ...PRODUCT_DETAIL_CACHE_METRICS,
  };
}

function buildProductDetailCacheKey({ merchantId, productId, checkoutToken } = {}) {
  return JSON.stringify({
    merchantId,
    productId,
    hasCheckoutToken: Boolean(checkoutToken),
  });
}

function cacheProductDetailForOffers({
  merchantId,
  productId,
  checkoutToken,
  product,
  source = 'upstream',
  metadata = {},
  ttlMs,
} = {}) {
  const mid = String(merchantId || '').trim();
  const pid = String(productId || '').trim();
  if (!PRODUCT_DETAIL_CACHE_ENABLED || !mid || !pid || !product || typeof product !== 'object') {
    return;
  }
  const resolvedTtlMs = Number.isFinite(Number(ttlMs))
    ? Number(ttlMs)
    : resolveProductDetailCacheTtlMs(mid);
  if (resolvedTtlMs <= 0) return;
  setProductDetailCache(
    buildProductDetailCacheKey({ merchantId: mid, productId: pid, checkoutToken }),
    {
      status: 'success',
      success: true,
      product,
      metadata: {
        query_source: source,
        ...metadata,
      },
    },
    resolvedTtlMs,
  );
}

// Resolve-product-group cache (avoid repeated slow upstream group lookups).
const RESOLVE_PRODUCT_GROUP_CACHE_ENABLED =
  process.env.RESOLVE_PRODUCT_GROUP_CACHE_ENABLED !== 'false';
const RESOLVE_PRODUCT_GROUP_CACHE = new Map(); // cacheKey -> { value, storedAtMs, expiresAtMs }
const RESOLVE_PRODUCT_GROUP_CACHE_METRICS = {
  hits: 0,
  misses: 0,
  sets: 0,
  bypasses: 0,
};
const RESOLVE_PRODUCT_GROUP_CACHE_TTL_MS = parseTimeoutMs(
  process.env.RESOLVE_PRODUCT_GROUP_CACHE_TTL_MS,
  10 * 60 * 1000,
);

function getResolveProductGroupCacheEntry(cacheKey) {
  const key = String(cacheKey || '');
  if (!key) return null;
  const hit = RESOLVE_PRODUCT_GROUP_CACHE.get(key);
  if (!hit) {
    RESOLVE_PRODUCT_GROUP_CACHE_METRICS.misses += 1;
    return null;
  }
  if (hit.expiresAtMs && hit.expiresAtMs < Date.now()) {
    RESOLVE_PRODUCT_GROUP_CACHE.delete(key);
    RESOLVE_PRODUCT_GROUP_CACHE_METRICS.misses += 1;
    return null;
  }
  RESOLVE_PRODUCT_GROUP_CACHE_METRICS.hits += 1;
  return hit;
}

function setResolveProductGroupCache(
  cacheKey,
  value,
  ttlMs = RESOLVE_PRODUCT_GROUP_CACHE_TTL_MS,
) {
  const key = String(cacheKey || '');
  if (!key) return;
  const ttl = Number(ttlMs) || RESOLVE_PRODUCT_GROUP_CACHE_TTL_MS;
  RESOLVE_PRODUCT_GROUP_CACHE_METRICS.sets += 1;
  RESOLVE_PRODUCT_GROUP_CACHE.set(key, {
    value: safeCloneJson(value),
    storedAtMs: Date.now(),
    expiresAtMs: Date.now() + Math.max(5_000, ttl),
  });
}

function snapshotResolveProductGroupCacheStats() {
  return {
    enabled: RESOLVE_PRODUCT_GROUP_CACHE_ENABLED,
    ttl_ms: RESOLVE_PRODUCT_GROUP_CACHE_TTL_MS,
    size: RESOLVE_PRODUCT_GROUP_CACHE.size,
    ...RESOLVE_PRODUCT_GROUP_CACHE_METRICS,
  };
}

function snapshotPdpV2PrefetchStateStats() {
  if (!getAuroraPdpPrefetchStateSnapshot) {
    return {
      available: false,
      reason: 'aurora_bff_prefetch_snapshot_not_exported',
    };
  }

  try {
    const snapshot = getAuroraPdpPrefetchStateSnapshot();
    if (snapshot && typeof snapshot === 'object' && !Array.isArray(snapshot)) {
      return {
        available: true,
        ...snapshot,
      };
    }
    return {
      available: true,
      snapshot: snapshot == null ? null : snapshot,
    };
  } catch (err) {
    return {
      available: false,
      reason: 'aurora_bff_prefetch_snapshot_failed',
      error: String(err && err.message ? err.message : err || 'unknown_error'),
    };
  }
}

// PDP optional-module cache/singleflight (reviews + similar):
// reduces repeated upstream fan-out when clients quickly reopen/switch PDPs.
const PDP_REVIEW_SUMMARY_CACHE_ENABLED =
  process.env.PDP_REVIEW_SUMMARY_CACHE_ENABLED !== 'false';
const PDP_REVIEW_SUMMARY_CACHE = new Map(); // key -> { value, expiresAtMs }
const PDP_REVIEW_SUMMARY_INFLIGHT = new Map(); // key -> Promise<object|null>
const PDP_REVIEW_SUMMARY_CACHE_TTL_MS = parseTimeoutMs(
  process.env.PDP_REVIEW_SUMMARY_CACHE_TTL_MS,
  90 * 1000,
);
const PDP_REVIEW_SUMMARY_NEGATIVE_TTL_MS = Math.max(
  3_000,
  parseTimeoutMs(process.env.PDP_REVIEW_SUMMARY_NEGATIVE_TTL_MS, 20 * 1000),
);
const PDP_REVIEW_SUMMARY_CACHE_MAX_ENTRIES = Math.max(
  50,
  Number(process.env.PDP_REVIEW_SUMMARY_CACHE_MAX_ENTRIES || 800) || 800,
);
const PDP_REVIEW_SUMMARY_INFLIGHT_MAX_ENTRIES = Math.max(
  20,
  Number(process.env.PDP_REVIEW_SUMMARY_INFLIGHT_MAX_ENTRIES || 300) || 300,
);

const PDP_SIMILAR_INFLIGHT = new Map(); // key -> Promise<any>
const PDP_SIMILAR_INFLIGHT_MAX_ENTRIES = Math.max(
  20,
  Number(process.env.PDP_SIMILAR_INFLIGHT_MAX_ENTRIES || 300) || 300,
);

function buildPdpReviewSummaryCacheKey({ merchantId, platform, platformProductId }) {
  const mid = String(merchantId || '').trim();
  const pf = String(platform || '').trim().toLowerCase();
  const pid = String(platformProductId || '').trim();
  if (!mid || !pf || !pid) return '';
  return `${mid}::${pf}::${pid}`;
}

function getPdpReviewSummaryCacheEntry(cacheKey) {
  const key = String(cacheKey || '');
  if (!key) return { found: false, value: null };
  const hit = PDP_REVIEW_SUMMARY_CACHE.get(key);
  if (!hit) return { found: false, value: null };
  if (hit.expiresAtMs && hit.expiresAtMs < Date.now()) {
    PDP_REVIEW_SUMMARY_CACHE.delete(key);
    return { found: false, value: null };
  }
  return { found: true, value: safeCloneJson(hit.value) };
}

function setPdpReviewSummaryCacheEntry(cacheKey, value, ttlMs) {
  const key = String(cacheKey || '');
  if (!key) return;
  const ttl = Math.max(1_000, Number(ttlMs) || PDP_REVIEW_SUMMARY_CACHE_TTL_MS);

  if (PDP_REVIEW_SUMMARY_CACHE.size >= PDP_REVIEW_SUMMARY_CACHE_MAX_ENTRIES) {
    const overflow = PDP_REVIEW_SUMMARY_CACHE.size - PDP_REVIEW_SUMMARY_CACHE_MAX_ENTRIES + 1;
    let removed = 0;
    for (const k of PDP_REVIEW_SUMMARY_CACHE.keys()) {
      PDP_REVIEW_SUMMARY_CACHE.delete(k);
      removed += 1;
      if (removed >= overflow) break;
    }
  }

  PDP_REVIEW_SUMMARY_CACHE.set(key, {
    value: safeCloneJson(value),
    expiresAtMs: Date.now() + ttl,
  });
}

function buildPdpSimilarInflightKey(args = {}) {
  const product = args?.pdp_product && typeof args.pdp_product === 'object' ? args.pdp_product : {};
  const merchantId = String(
    product.merchant_id || product.merchantId || product.merchant?.id || '',
  ).trim();
  const productId = String(product.product_id || product.productId || product.id || '').trim();
  if (!merchantId || !productId) return '';
  const limit = Math.max(1, Math.min(24, Number(args?.k || 6) || 6));
  const locale = String(args?.locale || 'en-US').trim().toLowerCase();
  const currency = String(args?.currency || product.currency || 'USD').trim().toUpperCase();
  const bypass = Boolean(
    args?.options?.no_cache || args?.options?.cache_bypass || args?.options?.bypass_cache,
  );
  const excludeKey = collectPdpSimilarExcludeKeyTokens(args?.options).join(',');
  return `${merchantId}::${productId}::${limit}::${locale}::${currency}::${bypass ? '1' : '0'}::${excludeKey}`;
}

function collectPdpSimilarExcludeKeyTokens(options = {}) {
  const tokens = new Set();
  const addProduct = (item) => {
    if (!item || typeof item !== 'object' || Array.isArray(item)) return;
    const merchantId = firstNonEmptyString(item.merchant_id, item.merchantId) || EXTERNAL_SEED_MERCHANT_ID;
    const productId = firstNonEmptyString(
      item.product_id,
      item.productId,
      item.id,
      item.external_product_id,
      item.externalProductId,
      item.source_product_id,
      item.sourceProductId,
      item.platform_product_id,
      item.platformProductId,
    );
    if (!productId) return;
    tokens.add(`${merchantId}::${productId}`);
  };
  for (const item of Array.isArray(options?.exclude_items) ? options.exclude_items : []) {
    addProduct(item);
  }
  for (const productId of Array.isArray(options?.exclude_ids) ? options.exclude_ids : []) {
    const normalized = firstNonEmptyString(productId);
    if (normalized) tokens.add(`${EXTERNAL_SEED_MERCHANT_ID}::${normalized}`);
  }
  return Array.from(tokens).sort();
}

function resolvePdpSimilarDisplayLimit(payload = {}) {
  const rawLimit =
    payload?.similar?.limit ||
    payload?.recommendations?.limit ||
    PDP_SIMILAR_DEFAULT_DISPLAY_LIMIT;
  const numericLimit = Number(rawLimit);
  const limit = Number.isFinite(numericLimit) ? Math.trunc(numericLimit) : PDP_SIMILAR_DEFAULT_DISPLAY_LIMIT;
  return Math.max(1, Math.min(PDP_SIMILAR_MAX_DISPLAY_LIMIT, limit || PDP_SIMILAR_DEFAULT_DISPLAY_LIMIT));
}

function resolvePdpSimilarCandidateLimit(displayLimit) {
  const limit = Math.max(1, Math.min(PDP_SIMILAR_MAX_DISPLAY_LIMIT, Number(displayLimit) || PDP_SIMILAR_DEFAULT_DISPLAY_LIMIT));
  const expanded = Math.max(limit + 12, limit * 3);
  return Math.max(limit, Math.min(PDP_SIMILAR_MAX_CANDIDATE_LIMIT, expanded));
}

function resolvePdpSimilarCardEnrichmentLimit(displayLimit, candidateLimit) {
  const visibleLimit = Math.max(
    1,
    Math.min(PDP_SIMILAR_MAX_DISPLAY_LIMIT, Number(displayLimit) || PDP_SIMILAR_DEFAULT_DISPLAY_LIMIT),
  );
  const maxCandidateLimit = Math.max(visibleLimit, Number(candidateLimit) || visibleLimit);
  return Math.max(visibleLimit, Math.min(maxCandidateLimit, visibleLimit + 6));
}

function resolvePdpSimilarCatalogFetchLimit(displayLimit, candidateLimit) {
  const visibleLimit = Math.max(
    1,
    Math.min(PDP_SIMILAR_MAX_DISPLAY_LIMIT, Number(displayLimit) || PDP_SIMILAR_DEFAULT_DISPLAY_LIMIT),
  );
  const maxCandidateLimit = Math.max(visibleLimit, Number(candidateLimit) || visibleLimit);
  return Math.max(visibleLimit, Math.min(PDP_SIMILAR_MAX_CANDIDATE_LIMIT, maxCandidateLimit));
}

function isTruthyCacheBypassFlag(value) {
  if (value === true) return true;
  if (typeof value === 'string') {
    const normalized = value.trim().toLowerCase();
    return normalized === 'true' || normalized === '1' || normalized === 'yes';
  }
  return false;
}

function hasExplicitCacheBypassFlag(...sources) {
  for (const source of sources) {
    if (!source || typeof source !== 'object') continue;
    if (
      isTruthyCacheBypassFlag(source.no_cache) ||
      isTruthyCacheBypassFlag(source.cache_bypass) ||
      isTruthyCacheBypassFlag(source.bypass_cache)
    ) {
      return true;
    }
  }
  return false;
}

function resolvePdpSimilarCacheBypass(payload = {}) {
  const options = payload?.options && typeof payload.options === 'object' ? payload.options : {};
  const similar = payload?.similar && typeof payload.similar === 'object' ? payload.similar : {};
  const similarOptions = similar?.options && typeof similar.options === 'object' ? similar.options : {};
  const recommendations =
    payload?.recommendations && typeof payload.recommendations === 'object'
      ? payload.recommendations
      : {};
  const recommendationsOptions =
    recommendations?.options && typeof recommendations.options === 'object'
      ? recommendations.options
      : {};

  return (
    isTruthyCacheBypassFlag(options.no_cache) ||
    isTruthyCacheBypassFlag(options.cache_bypass) ||
    isTruthyCacheBypassFlag(options.bypass_cache) ||
    isTruthyCacheBypassFlag(options.similar_cache_bypass) ||
    isTruthyCacheBypassFlag(options.similar_no_cache) ||
    hasExplicitCacheBypassFlag(
      similar,
      similarOptions,
      recommendations,
      recommendationsOptions,
    )
  );
}

function buildPdpSimilarBaseProduct({
  payload = {},
  entryProductRef = null,
  canonicalProductForPdp = {},
  canonicalProductRef = {},
  canonicalProduct = {},
} = {}) {
  const canonicalRefMerchantId = String(canonicalProductRef?.merchant_id || '').trim();
  const canonicalRefProductId = String(canonicalProductRef?.product_id || '').trim();
  const entryRequestedProduct =
    entryProductRef && typeof entryProductRef === 'object' && !Array.isArray(entryProductRef)
      ? entryProductRef
      : null;
  const requestedProduct =
    entryRequestedProduct ||
    (payload?.product_ref && typeof payload.product_ref === 'object'
      ? payload.product_ref
      : payload?.productRef && typeof payload.productRef === 'object'
        ? payload.productRef
        : payload?.product && typeof payload.product === 'object'
          ? payload.product
          : {});
  const requestedProductId = firstNonEmptyString(
    requestedProduct.product_id,
    requestedProduct.productId,
    payload?.product_id,
    payload?.productId,
  );
  const requestedExternalProductId = isExternalSeedProductId(requestedProductId)
    ? requestedProductId
    : '';
  const sourceProduct =
    canonicalProductForPdp && typeof canonicalProductForPdp === 'object'
      ? canonicalProductForPdp
      : {};
  const sourceExternalProductId = firstNonEmptyString(
    sourceProduct.external_product_id,
    sourceProduct.external_seed_product_id,
    sourceProduct.source_product_id,
    sourceProduct.platform_product_id,
    canonicalProduct?.external_product_id,
    canonicalProduct?.source_product_id,
    requestedExternalProductId,
  );
  if (canonicalRefMerchantId === EXTERNAL_SEED_MERCHANT_ID && canonicalRefProductId) {
    const baseProductId =
      isPivotaSignatureProductId(canonicalRefProductId) && isExternalSeedProductId(sourceExternalProductId)
        ? sourceExternalProductId
        : canonicalRefProductId;
    return {
      merchant_id: EXTERNAL_SEED_MERCHANT_ID,
      product_id: baseProductId,
      external_product_id: isExternalSeedProductId(baseProductId)
        ? baseProductId
        : sourceExternalProductId || baseProductId,
      source: 'external_seed',
      ...(isPivotaSignatureProductId(canonicalRefProductId)
        ? {
            pivota_signature_id: canonicalRefProductId,
            signature_id: canonicalRefProductId,
          }
        : {}),
      ...(baseProductId !== canonicalRefProductId
        ? { requested_product_id: canonicalRefProductId }
        : {}),
      ...(requestedExternalProductId && requestedExternalProductId !== baseProductId
        ? { requested_product_id: requestedExternalProductId }
        : {}),
      ...(sourceProduct.currency ? { currency: sourceProduct.currency } : {}),
      ...(sourceProduct.market ? { market: sourceProduct.market } : {}),
    };
  }
  const baseProduct = {
    ...sourceProduct,
    merchant_id:
      sourceProduct.merchant_id ||
      sourceProduct.merchantId ||
      canonicalRefMerchantId,
    product_id:
      sourceProduct.product_id ||
      sourceProduct.productId ||
      sourceProduct.id ||
      canonicalProduct?.product_id ||
      canonicalProduct?.id,
  };
  if (requestedExternalProductId) {
    const existingExternalId = firstNonEmptyString(
      baseProduct.external_product_id,
      baseProduct.externalProductId,
      baseProduct.external_seed_product_id,
      baseProduct.externalSeedProductId,
      baseProduct.source_product_id,
      baseProduct.sourceProductId,
      baseProduct.platform_product_id,
      baseProduct.platformProductId,
    );
    if (!existingExternalId) {
      baseProduct.external_product_id = requestedExternalProductId;
      baseProduct.source_product_id = requestedExternalProductId;
    }
    if (requestedExternalProductId !== firstNonEmptyString(baseProduct.product_id, baseProduct.productId, baseProduct.id)) {
      baseProduct.requested_product_id = requestedExternalProductId;
    }
  }
  return baseProduct;
}

function buildPdpSimilarBaseProductHintsFromSignatureRef(resolvedSignatureRef = {}) {
  if (!resolvedSignatureRef || typeof resolvedSignatureRef !== 'object') return {};
  const title = firstNonEmptyString(resolvedSignatureRef.title, resolvedSignatureRef.catalog_title);
  const brand = firstNonEmptyString(resolvedSignatureRef.brand, resolvedSignatureRef.catalog_brand);
  const category = firstNonEmptyString(resolvedSignatureRef.category);
  const productType = firstNonEmptyString(resolvedSignatureRef.product_type, resolvedSignatureRef.productType);
  const categoryPath = firstNonEmptyString(
    resolvedSignatureRef.category_path,
    resolvedSignatureRef.catalog_category_path,
  );
  const imageUrl = firstNonEmptyString(resolvedSignatureRef.image_url, resolvedSignatureRef.catalog_image_url);
  const canonicalUrl = firstNonEmptyString(
    resolvedSignatureRef.canonical_url,
    resolvedSignatureRef.catalog_canonical_url,
  );
  return {
    ...(title ? { title } : {}),
    ...(brand ? { brand } : {}),
    ...(category ? { category } : {}),
    ...(productType ? { product_type: productType } : {}),
    ...(categoryPath ? { category_path: categoryPath } : {}),
    ...(imageUrl ? { image_url: imageUrl } : {}),
    ...(canonicalUrl ? { canonical_url: canonicalUrl } : {}),
  };
}

function buildPdpSimilarFetchArgs({
  payload = {},
  entryProductRef = null,
  canonicalProductForPdp = {},
  canonicalProductRef = {},
  canonicalProduct = {},
  bypassCache = false,
  debug = false,
  candidateLimit = null,
  excludeItems = [],
  excludeIds = [],
  requestMode = 'first_paint',
} = {}) {
  const limit = resolvePdpSimilarDisplayLimit(payload);
  const resolvedCandidateLimit =
    candidateLimit == null ? resolvePdpSimilarCandidateLimit(limit) : Number(candidateLimit) || limit;
  const similarBaseProduct = buildPdpSimilarBaseProduct({
    payload,
    entryProductRef,
    canonicalProductForPdp,
    canonicalProductRef,
    canonicalProduct,
  });
  const normalizedRequestMode = String(requestMode || '').trim().toLowerCase();
  const externalFetchBudgetMs =
    normalizedRequestMode === 'background' || normalizedRequestMode === 'post_core'
      ? PDP_SIMILAR_BACKGROUND_EXTERNAL_FETCH_BUDGET_MS
      : PDP_SIMILAR_EXTERNAL_FETCH_BUDGET_MS;
  const catalogFetchLimit = resolvePdpSimilarCatalogFetchLimit(limit, resolvedCandidateLimit);
  const normalizedExcludeItems = dedupeSimilarCandidatesByMerchantProductId(excludeItems);
  const normalizedExcludeIds = Array.from(
    new Set((Array.isArray(excludeIds) ? excludeIds : []).map((value) => firstNonEmptyString(value)).filter(Boolean)),
  );
  return {
    displayLimit: limit,
    candidateLimit: resolvedCandidateLimit,
    similarBaseProduct,
    fetchArgs: {
      pdp_product: similarBaseProduct,
      k: resolvedCandidateLimit,
      locale:
        payload?.context?.locale ||
        payload?.context?.language ||
        payload?.locale ||
        'en-US',
      currency:
        similarBaseProduct.currency ||
        canonicalProductForPdp?.currency ||
        canonicalProduct?.currency ||
        'USD',
      options: {
        debug,
        candidate_limit: resolvedCandidateLimit,
        no_cache: bypassCache,
        cache_bypass: bypassCache,
        bypass_cache: bypassCache,
        external_fetch_timeout_ms: externalFetchBudgetMs,
        catalog_fetch_limit: catalogFetchLimit,
        catalog_fetch_overfetch_multiplier: 1,
        identity_dedupe_timeout_ms: PDP_SIMILAR_IDENTITY_DEDUPE_BUDGET_MS,
        hydrate_product_intel_cards: false,
        ...(normalizedExcludeItems.length > 0 ? { exclude_items: normalizedExcludeItems } : {}),
        ...(normalizedExcludeIds.length > 0 ? { exclude_ids: normalizedExcludeIds } : {}),
      },
    },
  };
}

const PDP_CORE_BLOCKING_INCLUDE_SET = new Set([
  'offers',
  'variant_selector',
  'variants',
  'product_overview',
  'product_details',
  'product_facts',
  'supplemental_details',
  'active_ingredients',
  'ingredients_inci',
  'how_to_use',
  'reviews_preview',
  'product_intel',
  'all',
]);

const PDP_V2_INCLUDE_ALIASES = Object.freeze({
  review: 'reviews_preview',
  reviews: 'reviews_preview',
  ingredients: 'ingredients_inci',
  ingredient: 'ingredients_inci',
  inci: 'ingredients_inci',
  full_ingredients: 'ingredients_inci',
});

function normalizePdpV2IncludeToken(value) {
  const token = String(value || '')
    .trim()
    .toLowerCase()
    .replace(/[-\s]+/g, '_');
  if (!token) return '';
  return PDP_V2_INCLUDE_ALIASES[token] || token;
}

function normalizePdpV2IncludeList(values) {
  const rawValues = Array.isArray(values) ? values : [];
  const out = [];
  const seen = new Set();
  for (const value of rawValues) {
    const token = normalizePdpV2IncludeToken(value);
    if (!token || seen.has(token)) continue;
    seen.add(token);
    out.push(token);
  }
  return out;
}

function parsePdpV2IncludeList(includeRaw) {
  const rawValues = Array.isArray(includeRaw)
    ? includeRaw
    : typeof includeRaw === 'string'
      ? includeRaw.split(',')
      : [];
  return normalizePdpV2IncludeList(rawValues);
}

function resolvePdpSimilarRequestMode({ payload = {}, options = {}, includeList = [] } = {}) {
  const rawMode = String(
    options.similar_mode ||
      options.similarMode ||
      options.similar_request_mode ||
      options.similarRequestMode ||
      options.module_context ||
      options.moduleContext ||
      payload?.similar?.mode ||
      payload?.similar?.request_mode ||
      '',
  )
    .trim()
    .toLowerCase();

  if (['post_core', 'post-core', 'background', 'module', 'retry', 'deferred_retry'].includes(rawMode)) {
    return 'background';
  }
  if (['first_paint', 'first-paint', 'inline', 'sync'].includes(rawMode)) {
    return 'first_paint';
  }

  const normalizedInclude = normalizePdpV2IncludeList(includeList);
  const asksForSimilar = normalizedInclude.some((value) => value === 'similar' || value === 'recommendations');
  const asksForBlockingCore = normalizedInclude.some((value) => PDP_CORE_BLOCKING_INCLUDE_SET.has(value));
  if (asksForSimilar && !asksForBlockingCore) {
    return 'background';
  }
  return 'first_paint';
}

function trimOldestInflightEntries(map, maxEntries) {
  while (map.size >= maxEntries) {
    const firstKey = map.keys().next().value;
    if (!firstKey) break;
    map.delete(firstKey);
  }
}

function readPriceAmountForNormalization(value) {
  if (value === null || value === undefined) return null;
  if (typeof value === 'number') return Number.isFinite(value) ? value : null;
  if (typeof value === 'string') {
    const parsed = Number(value.replace(/[^0-9.-]+/g, ''));
    return Number.isFinite(parsed) ? parsed : null;
  }
  if (value && typeof value === 'object' && !Array.isArray(value)) {
    return readPriceAmountForNormalization(
      value.amount ??
        value.current?.amount ??
        value.price_amount ??
        value.priceAmount ??
        value.price ??
        value.value,
    );
  }
  return null;
}

function firstCatalogPayloadMoney(...values) {
  for (const value of values) {
    if (value === null || value === undefined || value === '') continue;
    if (typeof value === 'number') {
      if (Number.isFinite(value)) return value;
      continue;
    }
    if (typeof value === 'string') {
      const trimmed = value.trim();
      if (trimmed) return trimmed;
      continue;
    }
    if (value && typeof value === 'object' && !Array.isArray(value)) {
      const amount = readPriceAmountForNormalization(value);
      if (amount !== null) return value;
    }
  }
  return null;
}

function buildProductDetailPriceContext(product, currencyOverride = '') {
  const productRecord = product && typeof product === 'object' ? product : {};
  return {
    currency: firstNonEmptyString(
      currencyOverride,
      productRecord.currency,
      productRecord.price_currency,
      productRecord.priceCurrency,
      productRecord.price?.currency,
      productRecord.price?.current?.currency,
      'USD',
    ),
    title: firstNonEmptyString(productRecord.title, productRecord.name),
    description: firstNonEmptyString(
      productRecord.description,
      productRecord.summary,
      productRecord.body,
    ),
    category: firstNonEmptyString(
      productRecord.category,
      productRecord.product_type,
      productRecord.productType,
      Array.isArray(productRecord.category_path) ? productRecord.category_path.join(' ') : productRecord.category_path,
      productRecord.catalog_category_path,
    ),
    canonicalUrl: firstNonEmptyString(
      productRecord.canonical_url,
      productRecord.canonicalUrl,
      productRecord.url,
      productRecord.product_url,
    ),
    destinationUrl: firstNonEmptyString(
      productRecord.destination_url,
      productRecord.destinationUrl,
      productRecord.external_redirect_url,
      productRecord.externalRedirectUrl,
      productRecord.source_url,
      productRecord.sourceUrl,
    ),
  };
}

function normalizeNullableProductDetailPrice(value, context = {}) {
  if (value === null || value === undefined || value === '') return null;
  const normalized = normalizeExternalSeedPrice(value, context);
  return Number.isFinite(Number(normalized)) ? Number(normalized) : null;
}

function normalizeProductDetailVariantPrice(variant, productContext = {}) {
  if (!variant || typeof variant !== 'object') return variant;
  const currency = firstNonEmptyString(
    variant.currency,
    variant.price_currency,
    variant.priceCurrency,
    variant.price?.currency,
    variant.price?.current?.currency,
    productContext.currency,
    'USD',
  );
  const context = {
    ...productContext,
    currency,
    title: [productContext.title, variant.title, variant.name, variant.sku]
      .map((value) => String(value || '').trim())
      .filter(Boolean)
      .join(' '),
    description: firstNonEmptyString(variant.description, productContext.description),
  };
  const rawPrice = variant.price ?? variant.price_amount ?? variant.priceAmount ?? variant.amount ?? variant.value;
  const rawAmount = readPriceAmountForNormalization(rawPrice);
  const normalizedAmount = normalizeNullableProductDetailPrice(rawPrice, context);
  if (
    normalizedAmount === null ||
    rawAmount === null ||
    Math.abs(normalizedAmount - rawAmount) < 0.000001
  ) {
    return variant;
  }

  const next = { ...variant };
  if (next.price && typeof next.price === 'object' && !Array.isArray(next.price)) {
    next.price = {
      ...next.price,
      amount: next.price.amount !== undefined ? normalizedAmount : next.price.amount,
      current:
        next.price.current && typeof next.price.current === 'object'
          ? { ...next.price.current, amount: normalizedAmount, currency }
          : next.price.current,
    };
    if (next.price.amount === undefined && !next.price.current) {
      next.price.amount = normalizedAmount;
      next.price.currency = currency;
    }
  } else if (next.price !== undefined) {
    next.price = normalizedAmount;
  }
  if (next.price_amount !== undefined) next.price_amount = normalizedAmount;
  if (next.priceAmount !== undefined) next.priceAmount = normalizedAmount;
  if (next.amount !== undefined) next.amount = normalizedAmount;
  if (next.value !== undefined) next.value = normalizedAmount;
  if (!next.currency) next.currency = currency;
  return next;
}

function normalizeProductDetailPrice(product) {
  if (!product || typeof product !== 'object') return product;
  const normalized = { ...product };
  const priceContext = buildProductDetailPriceContext(normalized);

  if (Array.isArray(normalized.variants)) {
    normalized.variants = normalized.variants.map((variant) =>
      normalizeProductDetailVariantPrice(variant, priceContext),
    );
  }

  let resolvedPrice = normalizeNullableProductDetailPrice(normalized.price, priceContext);
  if (resolvedPrice === null && Array.isArray(normalized.variants)) {
    for (const variant of normalized.variants) {
      if (!variant || typeof variant !== 'object') continue;
      const variantContext = buildProductDetailPriceContext(
        {
          ...normalized,
          title: [priceContext.title, variant.title, variant.name, variant.sku]
            .map((value) => String(value || '').trim())
            .filter(Boolean)
            .join(' '),
          description: firstNonEmptyString(variant.description, priceContext.description),
        },
        firstNonEmptyString(
          variant.currency,
          variant.price_currency,
          variant.priceCurrency,
          variant.price?.currency,
          variant.price?.current?.currency,
          priceContext.currency,
        ),
      );
      const candidate =
        normalizeNullableProductDetailPrice(variant.price, variantContext) ??
        normalizeNullableProductDetailPrice(variant.price_amount, variantContext) ??
        normalizeNullableProductDetailPrice(variant.amount, variantContext) ??
        normalizeNullableProductDetailPrice(variant.value, variantContext);
      if (candidate !== null) {
        resolvedPrice = candidate;
        break;
      }
    }
  }

  normalized.price = resolvedPrice;
  return normalized;
}

async function fetchProductDetailFromProductsCache(args) {
  if (!process.env.DATABASE_URL) return null;
  const merchantId = String(args?.merchantId || '').trim();
  const productId = String(args?.productId || '').trim();
  if (!merchantId || !productId) return null;
  const includeExpired = args?.includeExpired === true;
  const staleMaxAgeHours = Math.max(
    1,
    Math.min(
      24 * 90,
      Number.isFinite(Number(args?.staleMaxAgeHours))
        ? Number(args?.staleMaxAgeHours)
        : PRODUCT_DETAIL_STALE_MAX_AGE_HOURS,
    ),
  );

  try {
    const fetchFresh = async () => {
      const res = await query(
        `
          SELECT product_data, cached_at
          FROM products_cache
          WHERE merchant_id = $1
            AND (expires_at IS NULL OR expires_at > now())
            AND ${activeProductsCacheSourceWhere('products_cache')}
            AND (
              platform_product_id = $2
              OR product_data->>'id' = $2
              OR product_data->>'product_id' = $2
              OR product_data->>'productId' = $2
            )
          ORDER BY cached_at DESC
          LIMIT 1
        `,
        [merchantId, productId],
      );
      return res?.rows && res.rows[0] ? res.rows[0] : null;
    };

    const fetchStale = async () => {
      if (!PRODUCT_DETAIL_STALE_LOOKUP_ENABLED) return null;
      const res = await query(
        `
          SELECT product_data, cached_at
          FROM products_cache
          WHERE merchant_id = $1
            AND (cached_at IS NULL OR cached_at >= now() - ($3 * interval '1 hour'))
            AND ${activeProductsCacheSourceWhere('products_cache')}
            AND (
              platform_product_id = $2
              OR product_data->>'id' = $2
              OR product_data->>'product_id' = $2
              OR product_data->>'productId' = $2
            )
          ORDER BY cached_at DESC
          LIMIT 1
        `,
        [merchantId, productId, staleMaxAgeHours],
      );
      return res?.rows && res.rows[0] ? res.rows[0] : null;
    };

    let row = await fetchFresh();
    let staleFallbackUsed = false;
    if (!row && includeExpired) {
      row = await fetchStale();
      staleFallbackUsed = Boolean(row);
    }

    const productData = row?.product_data;
    if (!productData || typeof productData !== 'object') return null;

    const normalized = {
      ...productData,
      merchant_id: merchantId,
      product_id: String(productData.product_id || productData.id || productId).trim() || productId,
    };
    const withPrice = normalizeProductDetailPrice(normalized);
    return {
      product: withPrice,
      cached_at: row?.cached_at || null,
      stale_fallback_used: staleFallbackUsed,
      stale_max_age_hours: staleFallbackUsed ? staleMaxAgeHours : null,
    };
  } catch (err) {
    logger.warn(
      { err: err.message, merchantId, productId },
      'Failed to load product detail from products_cache',
    );
    return null;
  }
}

async function fetchExternalSeedProductDetailFromDb(args) {
  if (!process.env.DATABASE_URL) return null;
  const productId = String(args?.productId || '').trim();
  if (!productId) return null;

  const limitedSeedImagesSql = (pathSql) => `
    CASE
      WHEN jsonb_typeof(${pathSql}) = 'array'
      THEN (
        SELECT coalesce(jsonb_agg(value), '[]'::jsonb)
        FROM (
          SELECT value
          FROM jsonb_array_elements(${pathSql}) WITH ORDINALITY AS image(value, ord)
          WHERE ord <= 24
        ) limited_images
      )
      ELSE NULL
    END
  `;
  const limitedVariantImagesSql = (pathSql) => `
    CASE
      WHEN jsonb_typeof(${pathSql}) = 'array'
      THEN (
        SELECT coalesce(jsonb_agg(value), '[]'::jsonb)
        FROM (
          SELECT value
          FROM jsonb_array_elements(${pathSql}) WITH ORDINALITY AS image(value, ord)
          WHERE ord <= 3
        ) limited_variant_images
      )
      ELSE NULL
    END
  `;
  const limitedVariantsSql = (pathSql) => `
    CASE
      WHEN jsonb_typeof(${pathSql}) = 'array'
      THEN (
        SELECT coalesce(
          jsonb_agg(
            jsonb_strip_nulls(
              jsonb_build_object(
                'id', variant.value->>'id',
                'variant_id', coalesce(variant.value->>'variant_id', variant.value->>'id'),
                'sku', coalesce(variant.value->>'sku', variant.value->>'sku_id', variant.value->>'variant_sku'),
                'sku_id', coalesce(variant.value->>'sku_id', variant.value->>'sku'),
                'title', variant.value->>'title',
                'name', variant.value->>'name',
                'option_name', variant.value->>'option_name',
                'option_value', variant.value->>'option_value',
                'display_label', coalesce(variant.value->>'display_label', variant.value->>'displayLabel'),
                'displayLabel', coalesce(variant.value->>'displayLabel', variant.value->>'display_label'),
                'axis_kind', coalesce(variant.value->>'axis_kind', variant.value->>'axisKind'),
                'axisKind', coalesce(variant.value->>'axisKind', variant.value->>'axis_kind'),
                'source_quality_status', coalesce(variant.value->>'source_quality_status', variant.value->>'sourceQualityStatus'),
                'sourceQualityStatus', coalesce(variant.value->>'sourceQualityStatus', variant.value->>'source_quality_status'),
                'option1', variant.value->>'option1',
                'option2', variant.value->>'option2',
                'option3', variant.value->>'option3',
                'options', variant.value->'options',
                'price', coalesce(variant.value->'price', variant.value->'price_amount', variant.value->'pricing'->'current'->'amount'),
                'price_amount', coalesce(variant.value->'price_amount', variant.value->'price'),
                'currency', coalesce(variant.value->>'currency', variant.value->>'price_currency', variant.value->'pricing'->'current'->>'currency'),
                'price_currency', coalesce(variant.value->>'price_currency', variant.value->>'currency'),
                'availability', variant.value->>'availability',
                'available', variant.value->'available',
                'in_stock', variant.value->'in_stock',
                'inventory_quantity', coalesce(variant.value->'inventory_quantity', variant.value->'available_quantity'),
                'available_quantity', coalesce(variant.value->'available_quantity', variant.value->'inventory_quantity'),
                'image_url', coalesce(variant.value->>'image_url', variant.value->>'image', variant.value->'featured_image'->>'src'),
                'image', coalesce(variant.value->>'image', variant.value->>'image_url', variant.value->'featured_image'->>'src'),
                'label_image_url', coalesce(variant.value->>'label_image_url', variant.value->>'labelImageUrl'),
                'labelImageUrl', coalesce(variant.value->>'labelImageUrl', variant.value->>'label_image_url'),
                'swatch_image_url', coalesce(variant.value->>'swatch_image_url', variant.value->>'swatchImageUrl'),
                'swatchImageUrl', coalesce(variant.value->>'swatchImageUrl', variant.value->>'swatch_image_url'),
                'thumbnail_url', coalesce(variant.value->>'thumbnail_url', variant.value->>'thumbnailUrl'),
                'thumbnailUrl', coalesce(variant.value->>'thumbnailUrl', variant.value->>'thumbnail_url'),
                'image_urls', ${limitedVariantImagesSql("variant.value->'image_urls'")},
                'images', ${limitedVariantImagesSql("variant.value->'images'")},
                'beauty_meta', variant.value->'beauty_meta',
                'color_hex', coalesce(variant.value->>'color_hex', variant.value->>'shade_hex', variant.value->>'hex'),
                'swatch', variant.value->'swatch',
                'url', coalesce(variant.value->>'url', variant.value->>'deep_link', variant.value->>'product_url'),
                'deep_link', variant.value->>'deep_link',
                'product_url', variant.value->>'product_url'
              )
            )
          ),
          '[]'::jsonb
        )
        FROM jsonb_array_elements(${pathSql}) WITH ORDINALITY AS variant(value, ord)
        WHERE ord <= 80
      )
      ELSE NULL
    END
  `;
  const prunedSeedDataSql = `
    (
      coalesce(seed_data, '{}'::jsonb)
      - 'variants'
      - 'images'
      - 'image_urls'
      - 'snapshot'
      || jsonb_strip_nulls(jsonb_build_object(
        'variants', ${limitedVariantsSql("seed_data->'variants'")},
        'images', ${limitedSeedImagesSql("seed_data->'images'")},
        'image_urls', ${limitedSeedImagesSql("seed_data->'image_urls'")},
        'snapshot',
          (
            coalesce(seed_data->'snapshot', '{}'::jsonb)
            - 'variants'
            - 'images'
            - 'image_urls'
            || jsonb_strip_nulls(jsonb_build_object(
              'variants', coalesce(
                ${limitedVariantsSql("seed_data->'snapshot'->'variants'")},
                ${limitedVariantsSql("seed_data->'variants'")}
              ),
              'images', coalesce(
                ${limitedSeedImagesSql("seed_data->'snapshot'->'images'")},
                ${limitedSeedImagesSql("seed_data->'images'")}
              ),
              'image_urls', coalesce(
                ${limitedSeedImagesSql("seed_data->'snapshot'->'image_urls'")},
                ${limitedSeedImagesSql("seed_data->'image_urls'")}
              )
            ))
          )
      ))
    ) AS seed_data
  `;

  const selectColumns = `
    SELECT
      id,
      external_product_id,
      destination_url,
      canonical_url,
      domain,
      title,
      image_url,
      price_amount,
      price_currency,
      availability,
      attached_product_key,
      ${prunedSeedDataSql},
      updated_at,
      created_at,
      status
    FROM external_product_seeds
    WHERE status = 'active'
      AND %%MATCH_CLAUSE%%
    ORDER BY updated_at DESC NULLS LAST, created_at DESC NULLS LAST
    LIMIT 1
  `;

  try {
    let matchedVia = 'external_product_id';
    let row = null;
    const exactMatches = [
      ['external_product_id', 'external_product_id = $1'],
      ['seed_id', 'id::text = $1'],
    ];

    for (const [label, matchClause] of exactMatches) {
      const res = await query(selectColumns.replace('%%MATCH_CLAUSE%%', matchClause), [productId]);
      row = Array.isArray(res?.rows) ? res.rows[0] : null;
      if (row) {
        matchedVia = label;
        break;
      }
    }

    if (!row) {
      matchedVia = 'seed_json_product_id';
      const res = await query(
        selectColumns.replace(
          '%%MATCH_CLAUSE%%',
          `(
            seed_data->>'external_product_id' = $1
            OR seed_data->>'product_id' = $1
            OR seed_data->'snapshot'->>'product_id' = $1
          )`,
        ),
        [productId],
      );
      row = Array.isArray(res?.rows) ? res.rows[0] : null;
    }

    if (!row) return null;
    if (String(row.status || 'active').trim().toLowerCase() !== 'active') return null;
    row = await maybeHydrateExternalSeedRowFromAttachedCatalogProduct(row);
    const hydratedProduct = buildExternalSeedProduct(row);
    if (!hydratedProduct) return null;

    return {
      product: attachProductDetailSource(
        normalizeProductDetailPrice(hydratedProduct),
        'external_seed_db',
      ),
      matched_via: matchedVia,
      external_seed_id: row.id ? String(row.id) : null,
      updated_at: row.updated_at || null,
    };
  } catch (err) {
    const message = String(err?.message || err || '');
    if (
      err?.code === 'NO_DATABASE' ||
      (message.includes('external_product_seeds') && message.includes('does not exist'))
    ) {
      return null;
    }
    logger.warn(
      { err: err?.message || String(err), productId },
      'Failed to hydrate external seed product detail from DB',
    );
    return null;
  }
}

async function fetchExternalSeedSimilarCardSourcesFromDb(productIds = []) {
  if (!process.env.DATABASE_URL) return new Map();
  const requestedIds = Array.from(
    new Set(
      (Array.isArray(productIds) ? productIds : [])
        .map((value) => String(value || '').trim())
        .filter((value) => isExternalSeedProductId(value) || isPivotaSignatureProductId(value)),
    ),
  ).slice(0, 24);
  const directExternalProductIds = requestedIds.filter((id) => !isPivotaSignatureProductId(id));
  const signatureProductIds = requestedIds.filter((id) => isPivotaSignatureProductId(id));
  if (!directExternalProductIds.length && !signatureProductIds.length) return new Map();

  try {
    const res = await query(
      `
        WITH requested_signature_products AS (
          SELECT unnest($2::text[]) AS pivota_signature_id
        ),
        signature_external_sources AS (
          SELECT DISTINCT ON (cp.pivota_signature_id)
            cp.pivota_signature_id,
            cp.source_product_id AS external_product_id
          FROM catalog_products cp
          JOIN requested_signature_products rsp
            ON rsp.pivota_signature_id = cp.pivota_signature_id
          -- ADR-009: external seeds are keyed by platform, not by the legacy
          -- merchant_id='external_seed' bucket (per-brand merch_obs_ sellers now).
          WHERE cp.platform = 'external_seed'
            AND cp.source_product_id IS NOT NULL
            AND cp.source_product_id <> ''
          ORDER BY cp.pivota_signature_id, cp.updated_at DESC NULLS LAST
        )
        SELECT
          eps.external_product_id,
          ses.pivota_signature_id AS matched_signature_product_id,
          coalesce(seed_data->'snapshot'->>'brand', seed_data->>'brand', '') AS brand,
          coalesce(seed_data->'snapshot'->>'category', seed_data->>'category', '') AS category,
          coalesce(seed_data->'snapshot'->>'product_type', seed_data->>'product_type', '') AS product_type,
          coalesce(seed_data->'snapshot'->>'title', seed_data->>'title', title, '') AS title,
          coalesce(
            seed_data->'image_asset_cache_v1'->'visible_image_urls'->>0,
            seed_data->'snapshot'->'image_asset_cache_v1'->'visible_image_urls'->>0,
            seed_data->'snapshot'->'image_urls'->>0,
            seed_data->'snapshot'->'images'->0->>'url',
            seed_data->'snapshot'->>'image_url',
            seed_data->>'image_url',
            image_url,
            ''
          ) AS image_url,
          coalesce(price_amount::text, seed_data->'snapshot'->>'price', seed_data->>'price', '') AS price_amount,
          coalesce(price_currency, seed_data->'snapshot'->>'currency', seed_data->>'currency', '') AS price_currency,
          coalesce(
            seed_data->'snapshot'->>'pdp_description_raw',
            seed_data->>'pdp_description_raw',
            ''
          ) AS pdp_description_raw,
          coalesce(
            seed_data->'snapshot'->>'description',
            seed_data->>'description',
            seed_data->'snapshot'->>'description_raw',
            seed_data->>'description_raw',
            ''
          ) AS description,
          CASE
            WHEN jsonb_typeof(seed_data->'snapshot'->'pdp_details_sections') = 'array'
              THEN seed_data->'snapshot'->'pdp_details_sections'
            WHEN jsonb_typeof(seed_data->'pdp_details_sections') = 'array'
              THEN seed_data->'pdp_details_sections'
            ELSE '[]'::jsonb
          END AS pdp_details_sections,
          -- Electronics spec surface is FIRST-CLASS at compose time (main route
          -- — no render-time fallback digging into seed_data). Project it here
          -- (snapshot then root) so the similar-card source object composes the
          -- whitelisted electronics_meta identically to the primary PDP route.
          coalesce(
            seed_data->'snapshot'->'electronics_meta',
            seed_data->'electronics_meta'
          ) AS electronics_meta
        FROM external_product_seeds eps
        LEFT JOIN signature_external_sources ses
          ON ses.external_product_id = eps.external_product_id
        WHERE eps.status = 'active'
          AND (
            eps.external_product_id = ANY($1::text[])
            OR ses.external_product_id IS NOT NULL
          )
      `,
      [directExternalProductIds, signatureProductIds],
    );
    const out = new Map();
    for (const row of res?.rows || []) {
      const externalProductId = String(row?.external_product_id || '').trim();
      if (!externalProductId) continue;
      const publicProductId = await resolvePublicExternalSeedProductId(externalProductId);
      const pdpDetailsSections = Array.isArray(row?.pdp_details_sections)
        ? row.pdp_details_sections
        : [];
      const priceAmount = Number(row?.price_amount);
      const hydratedSource = {
        product_id: publicProductId || externalProductId,
        ...(CANONICAL_ENTITY_ID_PUBLIC_EMIT_ENABLED
          ? {
              external_product_id: externalProductId,
              source_product_id: externalProductId,
            }
          : {}),
        brand: firstNonEmptyString(row?.brand),
        category: firstNonEmptyString(row?.category),
        product_type: firstNonEmptyString(row?.product_type),
        title: firstNonEmptyString(row?.title),
        image_url: firstNonEmptyString(row?.image_url),
        price: Number.isFinite(priceAmount) && priceAmount > 0
          ? {
              amount: priceAmount,
              currency: firstNonEmptyString(row?.price_currency, 'USD'),
            }
          : null,
        description: firstNonEmptyString(row?.description),
        pdp_description_raw: firstNonEmptyString(row?.pdp_description_raw),
        pdp_details_sections: pdpDetailsSections,
        ...(pickElectronicsMeta(row?.electronics_meta)
          ? { electronics_meta: pickElectronicsMeta(row?.electronics_meta) }
          : {}),
        seed_data: {
          snapshot: {
            brand: firstNonEmptyString(row?.brand),
            category: firstNonEmptyString(row?.category),
            product_type: firstNonEmptyString(row?.product_type),
            title: firstNonEmptyString(row?.title),
            image_url: firstNonEmptyString(row?.image_url),
            description: firstNonEmptyString(row?.description),
            pdp_description_raw: firstNonEmptyString(row?.pdp_description_raw),
            pdp_details_sections: pdpDetailsSections,
          },
        },
      };
      out.set(externalProductId, hydratedSource);
      const matchedSignatureProductId = firstNonEmptyString(row?.matched_signature_product_id);
      if (matchedSignatureProductId) out.set(matchedSignatureProductId, hydratedSource);
    }
    return out;
  } catch (err) {
    const message = String(err?.message || err || '');
    if (
      err?.code === 'NO_DATABASE' ||
      (message.includes('external_product_seeds') && message.includes('does not exist'))
    ) {
      return new Map();
    }
    logger.warn(
      { err: err?.message || String(err), product_count: requestedIds.length },
      'Failed to hydrate external seed similar card sources from DB',
    );
    return new Map();
  }
}

// Single-flight + short-TTL memoization for the Pivota-signature -> catalog product_ref
// resolver. The lookup is read-only and deterministic for a given sig_*. Real PDP traffic
// includes lots of repeat/concurrent fetches for the same product (rapid back-nav, multiple
// page components hydrating the same PDP, hotset items). Without this, every request runs
// the 2-3 DB round-trips in resolveCatalogProductRefFromPivotaSignature (~400-500ms total).
const RESOLVE_CATALOG_SIGNATURE_CACHE_ENABLED =
  process.env.RESOLVE_CATALOG_SIGNATURE_CACHE_ENABLED !== 'false';
const RESOLVE_CATALOG_SIGNATURE_CACHE_TTL_MS = Math.max(
  5_000,
  parseTimeoutMs(process.env.RESOLVE_CATALOG_SIGNATURE_CACHE_TTL_MS, 60_000),
);
const RESOLVE_CATALOG_SIGNATURE_CACHE_MAX_ENTRIES = Math.max(
  50,
  Number(process.env.RESOLVE_CATALOG_SIGNATURE_CACHE_MAX_ENTRIES || 1000) || 1000,
);
const RESOLVE_CATALOG_SIGNATURE_CACHE = new Map(); // sigId -> { value, expiresAtMs }
const RESOLVE_CATALOG_SIGNATURE_INFLIGHT = new Map(); // sigId -> Promise

// First-paint budget for the signature resolve itself.
//
// WHY THIS EXISTS (2026-07-25): three sitemap PDPs hung FOREVER — zero bytes,
// no status, reproducible for hours. The chain was:
//   1. `query()` is pg `Pool.query` with no `query_timeout` and no
//      `statement_timeout`, so a pathological plan never settles.
//   2. This resolver was the ONLY first-paint stage with no budget guard, so
//      that unsettled promise was awaited directly by the handler.
//   3. Worst of all, the single-flight map above stores the PENDING promise and
//      only evicts it in `.finally()`. A promise that never settles is never
//      evicted, so EVERY later request for that sig was handed the SAME dead
//      promise. One unlucky query poisoned that sig for the life of the
//      process, which is exactly why it looked like corrupt per-product data.
//
// Bounding the promise stored in INFLIGHT is the load-bearing part: it
// guarantees `.finally()` runs, which guarantees the map self-heals.
const RESOLVE_CATALOG_SIGNATURE_BUDGET_MS = Math.max(
  250,
  parseTimeoutMs(process.env.RESOLVE_CATALOG_SIGNATURE_BUDGET_MS, 6_000),
);
// Negative cooldown after a budget miss. `withStageBudget` only stops us
// WAITING — the underlying query keeps running and keeps its pool connection
// pinned (DB_POOL_MAX defaults to 5). Without a cooldown, a crawler hitting a
// pathological sig would launch a fresh multi-second query every request and
// starve the pool for every other operation. Fail fast instead until it lapses.
const RESOLVE_CATALOG_SIGNATURE_COOLDOWN_MS = Math.max(
  1_000,
  parseTimeoutMs(process.env.RESOLVE_CATALOG_SIGNATURE_COOLDOWN_MS, 30_000),
);
const RESOLVE_CATALOG_SIGNATURE_COOLDOWN = new Map(); // cacheKey -> expiresAtMs

// NOTE: the budget above only stops us WAITING. What actually releases the
// pinned connection is the pool-level `statement_timeout` / `query_timeout` in
// src/db/index.js — set there, not per-query, because the per-query helper
// (`queryWithStatementTimeout`) costs three extra round-trips per call.

function buildCatalogSignatureGroupMemberFromIdentityRow(row, canonicalRef = {}) {
  if (!row || typeof row !== 'object') return null;
  const sourcePayload = { ...(isPlainObject(row.source_payload) ? row.source_payload : {}) };
  const catalogOfferPrice = Number(row.catalog_offer_price);
  const catalogOfferCurrency = firstNonEmptyString(row.catalog_offer_currency, sourcePayload.currency, 'USD');
  if (Number.isFinite(catalogOfferPrice) && catalogOfferPrice > 0) {
    sourcePayload.price = { amount: catalogOfferPrice, currency: catalogOfferCurrency };
    sourcePayload.price_amount = catalogOfferPrice;
    sourcePayload.currency = catalogOfferCurrency;
    sourcePayload.catalog_offer_v1 = {
      offer_id: firstNonEmptyString(row.catalog_offer_id),
      sku_key: firstNonEmptyString(row.catalog_sku_key),
      source_system: firstNonEmptyString(row.catalog_offer_source_system),
      source_ref: firstNonEmptyString(row.catalog_offer_source_ref),
    };
  }
  for (const [targetKey, sourceValue] of [
    ['title', row.catalog_title],
    ['brand', row.catalog_brand],
    ['canonical_url', row.catalog_canonical_url],
    ['destination_url', row.catalog_canonical_url],
    ['source_url', row.catalog_canonical_url],
    ['image_url', row.catalog_image_url],
  ]) {
    if (!firstNonEmptyString(sourcePayload[targetKey]) && firstNonEmptyString(sourceValue)) {
      sourcePayload[targetKey] = firstNonEmptyString(sourceValue);
    }
  }
  // Heal the FIRST-CLASS electronics_meta onto the member payload from the
  // resolved catalog row (main route — no render-time fallback). Guarded so an
  // existing (fresher, seed-hydrated) value is never clobbered; whitelisted so
  // only the recognized spec shape is admitted.
  if (!sourcePayload.electronics_meta) {
    const memberElectronicsMeta = pickElectronicsMeta(row.catalog_electronics_meta);
    if (memberElectronicsMeta) sourcePayload.electronics_meta = memberElectronicsMeta;
  }
  const variantAxes = isPlainObject(row.variant_axes) ? row.variant_axes : {};
  const merchantId = firstNonEmptyString(row.merchant_id);
  const productId = firstNonEmptyString(row.product_id);
  if (!merchantId || !productId) return null;
  const merchantName = firstNonEmptyString(
    row.merchant_name,
    sourcePayload.merchant_name,
    sourcePayload.merchantName,
    sourcePayload.store_name,
    sourcePayload.storeName,
    sourcePayload.seller_name,
    sourcePayload.sellerName,
    sourcePayload.seller_of_record,
    sourcePayload.sellerOfRecord,
  );
  return {
    merchant_id: merchantId,
    product_id: productId,
    source_listing_ref: firstNonEmptyString(row.source_listing_ref),
    source_kind: firstNonEmptyString(row.source_kind),
    source_tier: firstNonEmptyString(row.source_tier),
    ...(row.platform ? { platform: String(row.platform).trim() } : {}),
    ...(Object.keys(sourcePayload).length ? { source_payload: sourcePayload } : {}),
    ...(merchantName ? { merchant_name: merchantName } : {}),
    ...(Object.keys(variantAxes).length ? { variant_axes: variantAxes } : {}),
    is_primary:
      merchantId === firstNonEmptyString(canonicalRef.merchant_id) &&
      productId === firstNonEmptyString(canonicalRef.product_id),
  };
}

// #1799 rendering-side follow-up (pre-merge finding 6): group-member catalog
// rows were joined ONLY by cp.source_product_id = <alias>.product_id. For
// Path-C minted canonicals (source_system='catalog_enrichment_agent_v1') the
// identity row's product_id is the attached SEED's external_product_id while
// the minted row's source_product_id is a name slug, so that key could reach
// only the seed's MIRROR row (possibly stale/retired) — minted members admitted
// by the minted-aware seed-identity predicate rendered with a NULL offer/price
// or a retired mirror row's offer. Resolve the catalog row through BOTH lanes —
// direct source_product_id (mirror/connected) and the attached seed
// (eps.attached_product_key = cp.product_key, minted).
//
// Row-selection order (ultrareview #1800 finding: keep this in sync with the
// SERVING GATES of buildActiveExternalSeedIdentityPredicate, not just its join
// keys). The admission predicate's arms each require cp.sync_status='live' AND
// index_pipeline_state.serving_eligible=TRUE on the lane that admitted the
// member, so we PREFER the serving-eligible + live row first, then the minted
// canonical over the mirror, then recency. This is a preference, not a hard
// gate: the direct lane also carries connected-merchant rows (admitted with no
// serving_eligible requirement) and mirror rows, which must never be dropped —
// LIMIT 1 still returns the best available row so a member never regresses to a
// NULL offer. For an admitted external_seed member the admitting lane is
// (live + serving_eligible) by construction, so it wins these ranks; a
// live-but-not-serving-eligible minted row (e.g. pre-graduation PQS gate or an
// evidence hold, while the mirror is still live+eligible) can no longer shadow
// the eligible row the pipeline actually cleared. serving_eligible is checked
// via a correlated EXISTS (semi-join, matching the predicate) so the LEFT JOIN
// never fans cp_pick out on a content_key with multiple pipeline rows.
function buildGroupMemberCatalogOfferLateralJoinSql(alias = 'pil') {
  return `
      LEFT JOIN LATERAL (
        SELECT cp_pick.*
        FROM (
          SELECT cp.*, 1 AS offer_join_lane
          FROM catalog_products cp
          WHERE cp.merchant_id = ${alias}.merchant_id
            AND cp.source_product_id = ${alias}.product_id
          UNION ALL
          SELECT cp.*, 0 AS offer_join_lane
          FROM external_product_seeds eps
          JOIN catalog_products cp
            ON cp.product_key = eps.attached_product_key
           AND cp.source_system = 'catalog_enrichment_agent_v1'
           AND cp.merchant_id = ${alias}.merchant_id
          WHERE eps.external_product_id = ${alias}.product_id
            AND eps.status = 'active'
        ) cp_pick
        ORDER BY
          CASE
            WHEN EXISTS (
              SELECT 1 FROM index_pipeline_state ips_pick
              WHERE ips_pick.content_key = cp_pick.content_key
                AND ips_pick.serving_eligible = TRUE
            ) THEN 0 ELSE 1
          END,
          CASE WHEN cp_pick.sync_status = 'live' THEN 0 ELSE 1 END,
          cp_pick.offer_join_lane ASC,
          cp_pick.updated_at DESC NULLS LAST,
          cp_pick.product_key ASC
        LIMIT 1
      ) cp_offer ON true`;
}

async function fetchApprovedLiveIdentityGroupMembersForOffers({
  sellableItemGroupId,
  excludeMerchantId,
  excludeProductId,
  queryFn = query,
} = {}) {
  const groupId = firstNonEmptyString(sellableItemGroupId);
  const merchantId = firstNonEmptyString(excludeMerchantId);
  const productId = firstNonEmptyString(excludeProductId);
  if (!groupId || !merchantId || !productId || typeof queryFn !== 'function') return [];
  const result = await queryFn(
    `
      SELECT
        pil.source_listing_ref,
        pil.merchant_id,
        pil.product_id,
        pil.source_kind,
        pil.source_tier,
        pil.source_payload,
        pil.variant_axes,
        cp_offer.platform,
        -- ADR-009: resolve the real seller name for connected merchants AND
        -- per-brand observed sellers (merch_obs_…) — suppress ONLY the legacy
        -- anonymous 'external_seed' lump, whose catalog_merchants row is a
        -- placeholder ("External Seed"), not a seller of record.
        CASE
          WHEN ${buildLegacyExternalSeedLumpPredicate('pil')} THEN NULL
          ELSE cm_offer.merchant_name
        END AS merchant_name,
        cp_offer.title AS catalog_title,
        cp_offer.brand AS catalog_brand,
        cp_offer.canonical_url AS catalog_canonical_url,
        cp_offer.image_url AS catalog_image_url,
        -- Electronics spec surface is FIRST-CLASS at compose time (main route —
        -- no render-time fallback). Project the whitelisted electronics_meta off
        -- the resolved catalog row's payload so a group member that later feeds
        -- product composition carries the spec table like the primary route.
        --
        -- GATED on the cheap category column: the #> operator against a TOASTed
        -- jsonb forces a FULL detoast of product_payload, and this projection
        -- runs once per identity-group member. Three Tom Ford Beauty PDPs
        -- (payloads 1.0-1.9MB, in the corpus's two largest identity groups at
        -- 40 and 43 members) were reading ~67-77MB of TOAST per request through
        -- this one column — enough to hang the request outright. Verified
        -- 2026-07-25: ZERO live rows carry seed_data.electronics_meta, so the
        -- gate drops nothing today and still populates the moment an
        -- electronics ingest writes it under an electronics* category.
        CASE
          WHEN cp_offer.category ILIKE 'electronics%'
            THEN cp_offer.product_payload#>'{seed_data,electronics_meta}'
          ELSE NULL
        END AS catalog_electronics_meta,
        offer_row.offer_id AS catalog_offer_id,
        offer_row.sku_key AS catalog_sku_key,
        offer_row.currency AS catalog_offer_currency,
        COALESCE(
          offer_row.merchant_effective_price,
          offer_row.estimated_best_price,
          offer_row.list_price
        ) AS catalog_offer_price,
        offer_row.source_system AS catalog_offer_source_system,
        offer_row.source_ref AS catalog_offer_source_ref
      FROM pdp_identity_listing pil
      ${buildGroupMemberCatalogOfferLateralJoinSql('pil')}
      LEFT JOIN catalog_merchants cm_offer
        ON cm_offer.merchant_id = pil.merchant_id
       -- ADR-009: skip the join only for the legacy anonymous 'external_seed'
       -- lump (placeholder merchant row); observed merch_obs_ sellers and
       -- connected merchants resolve their real catalog_merchants row.
       AND NOT (${buildLegacyExternalSeedLumpPredicate('pil')})
      LEFT JOIN LATERAL (
        SELECT
          o.offer_id,
          o.sku_key,
          o.currency,
          o.merchant_effective_price,
          o.estimated_best_price,
          o.list_price,
          o.source_system,
          o.source_ref
        FROM catalog_skus s
        JOIN catalog_offers o ON o.sku_key = s.sku_key
        WHERE s.product_key = cp_offer.product_key
        ORDER BY
          CASE WHEN o.availability ILIKE 'in%stock%' THEN 0 ELSE 1 END,
          o.updated_at DESC NULLS LAST,
          o.offer_id ASC
        LIMIT 1
      ) offer_row ON true
      WHERE pil.sellable_item_group_id = $1
        AND pil.identity_status = 'approved'
        AND pil.live_read_enabled IS TRUE
        AND COALESCE(pil.review_required, false) IS NOT TRUE
        AND NOT (pil.merchant_id = $2 AND pil.product_id = $3)
        -- ADR-009: admit external-seed group members whose live mirror row is
        -- serving_eligible, correlating by platform + source_system (NOT the
        -- legacy merchant_id='external_seed' bucket) so per-brand merch_obs_
        -- seeds aren't dropped from their own sellable-item-group. Shared with
        -- the ~7 identity/serving queries in pdpIdentityGraph.js (#1775) so the
        -- correlation lives in one place.
        AND ${buildActiveExternalSeedIdentityPredicate('pil')}
        ${buildCatalogSourceQuarantineAntiJoinSql('cp_offer')}
      ORDER BY
        CASE WHEN pil.source_tier = 'brand' THEN 0 ELSE 1 END,
        pil.identity_confidence DESC NULLS LAST,
        pil.updated_at DESC NULLS LAST,
        pil.created_at DESC NULLS LAST
      LIMIT 200
    `,
    [groupId, merchantId, productId],
  );
  return (Array.isArray(result?.rows) ? result.rows : [])
    .map((row) => buildCatalogSignatureGroupMemberFromIdentityRow(row))
    .filter(Boolean);
}

function normalizeCatalogSignatureResolveOptions(options = {}) {
  const hydrateIdentityListing = options?.hydrateIdentityListing !== false;
  const hydrateIdentityGroupMembers =
    hydrateIdentityListing && options?.hydrateIdentityGroupMembers !== false;
  const bypassCache =
    options?.bypassCache === true ||
    options?.no_cache === true ||
    options?.cache_bypass === true ||
    options?.bypass_cache === true ||
    String(options?.no_cache || '').trim().toLowerCase() === 'true' ||
    String(options?.cache_bypass || options?.bypass_cache || '').trim().toLowerCase() === 'true';
  return {
    hydrateIdentityListing,
    hydrateIdentityGroupMembers,
    bypassCache,
    cacheVariant: hydrateIdentityListing
      ? hydrateIdentityGroupMembers
        ? 'rich'
        : 'identity'
      : 'lite',
  };
}

/**
 * Budget-bounded call into the signature resolver.
 *
 * EVERY path out of here settles. That is the invariant the single-flight map
 * below depends on: an unsettled promise in INFLIGHT is a permanent per-sig
 * outage, not a slow request.
 */
function resolveCatalogSignatureInnerBounded(normalizedProductId, resolveOptions, cacheKey) {
  return withStageBudget(
    resolveCatalogProductRefFromPivotaSignatureInner(normalizedProductId, resolveOptions),
    RESOLVE_CATALOG_SIGNATURE_BUDGET_MS,
    'resolve_catalog_signature',
  ).catch((err) => {
    if (err?.code === 'STAGE_TIMEOUT') {
      // Trip the cooldown so we stop launching new copies of a query that is
      // already pinning a pool connection.
      RESOLVE_CATALOG_SIGNATURE_COOLDOWN.set(
        cacheKey,
        Date.now() + RESOLVE_CATALOG_SIGNATURE_COOLDOWN_MS,
      );
      logger.warn(
        {
          product_id: normalizedProductId,
          cache_variant: resolveOptions.cacheVariant,
          budget_ms: RESOLVE_CATALOG_SIGNATURE_BUDGET_MS,
          cooldown_ms: RESOLVE_CATALOG_SIGNATURE_COOLDOWN_MS,
        },
        'resolve_catalog_signature exceeded first-paint budget',
      );
    }
    throw err;
  });
}

function readCatalogSignatureCooldown(cacheKey) {
  const until = RESOLVE_CATALOG_SIGNATURE_COOLDOWN.get(cacheKey);
  if (!until) return null;
  if (until <= Date.now()) {
    RESOLVE_CATALOG_SIGNATURE_COOLDOWN.delete(cacheKey);
    return null;
  }
  return until;
}

function buildCatalogSignatureTimeoutError(normalizedProductId) {
  // Deliberately NOT a null return. Null means "this sig resolves to nothing",
  // which the handler turns into PRODUCT_NOT_FOUND — and a 404 on a sitemap URL
  // tells Google to drop a product that is probably fine. A thrown, retryable
  // error keeps the index signal intact.
  const err = new Error(
    `Catalog signature resolve unavailable (${normalizedProductId}): first-paint budget exceeded`,
  );
  err.code = 'CATALOG_SIGNATURE_RESOLVE_TIMEOUT';
  return err;
}

async function resolveCatalogProductRefFromPivotaSignature(productId, options = {}) {
  if (!process.env.DATABASE_URL) return null;
  const normalizedProductId = String(productId || '').trim();
  if (!isPivotaSignatureProductId(normalizedProductId)) return null;
  const resolveOptions = normalizeCatalogSignatureResolveOptions(options);
  const cacheKey = `${normalizedProductId}::${resolveOptions.cacheVariant}`;

  if (RESOLVE_CATALOG_SIGNATURE_CACHE_ENABLED && !resolveOptions.bypassCache) {
    const cached = RESOLVE_CATALOG_SIGNATURE_CACHE.get(cacheKey);
    if (cached && cached.expiresAtMs > Date.now()) {
      return cached.value;
    }
    if (cached) RESOLVE_CATALOG_SIGNATURE_CACHE.delete(cacheKey);

    // A live cooldown means the last attempt blew its budget and its query may
    // still be holding a connection. Fail fast rather than pile on.
    if (readCatalogSignatureCooldown(cacheKey)) {
      throw buildCatalogSignatureTimeoutError(normalizedProductId);
    }

    const inflight = RESOLVE_CATALOG_SIGNATURE_INFLIGHT.get(cacheKey);
    if (inflight) return inflight;

    const promise = resolveCatalogSignatureInnerBounded(normalizedProductId, resolveOptions, cacheKey)
      .then((value) => {
        if (RESOLVE_CATALOG_SIGNATURE_CACHE.size >= RESOLVE_CATALOG_SIGNATURE_CACHE_MAX_ENTRIES) {
          const firstKey = RESOLVE_CATALOG_SIGNATURE_CACHE.keys().next().value;
          if (firstKey !== undefined) RESOLVE_CATALOG_SIGNATURE_CACHE.delete(firstKey);
        }
        RESOLVE_CATALOG_SIGNATURE_CACHE.set(cacheKey, {
          value,
          expiresAtMs: Date.now() + RESOLVE_CATALOG_SIGNATURE_CACHE_TTL_MS,
        });
        return value;
      })
      .finally(() => {
        RESOLVE_CATALOG_SIGNATURE_INFLIGHT.delete(cacheKey);
      });
    RESOLVE_CATALOG_SIGNATURE_INFLIGHT.set(cacheKey, promise);
    return promise;
  }

  // Cache-bypass path (debug probes, cache_bypass=true). Still bounded — an
  // unbounded await here would hang the request just as hard, it simply would
  // not poison the sig for everyone else.
  return resolveCatalogSignatureInnerBounded(normalizedProductId, resolveOptions, cacheKey);
}

// content_canonical_election is created by pivota-backend migration 181, whose
// prod apply rides db/schema_guard.py at backend boot. THIS repo deploys
// independently, so there is a window — and a merge-order mistake — in which
// this gateway runs against a database that has not grown the table yet.
//
// Without this latch that window is a TOTAL outage, not a degraded feature: the
// election is joined in the PRIMARY signature-resolution query, so a missing
// relation fails every single /products/{sig} PDP, not just the 474 duplicate
// groups the election exists for. That is wildly out of proportion to what is
// being added, which is a canonical TAG. So on undefined_table: drop the join,
// serve every PDP exactly as it did before migration 181 (its own
// self-referential canonical), and pick the election back up on the next
// process start.
//
// Latched per process rather than re-probed per request — a missing table does
// not reappear mid-process, and re-probing would put a guaranteed-failing query
// in front of every PDP.
let CONTENT_CANONICAL_ELECTION_TABLE_MISSING = false;

// Mirrors pivota-backend's INDEX_ELIGIBLE_SITEMAP (ADR-007 SLICE 1, the
// offer-free citation floor). It governs which rows the backend's ELECTOR will
// crown, so the guard that validates an elected sig has to widen with it or it
// silently rejects every widen-only winner.
//
// Read at module load, like the backend's own `_flag_on`. Cross-service flag
// coupling is not lovely, but the alternative — this gateway guessing at the
// backend's eligibility rule — is exactly the drift the whole design is built
// to prevent. Default OFF matches the backend's default; set BOTH or neither.
const INDEX_ELIGIBLE_SITEMAP_ENABLED = ['1', 'true', 'yes', 'on'].includes(
  String(process.env.INDEX_ELIGIBLE_SITEMAP || '').trim().toLowerCase(),
);

function isMissingContentCanonicalElectionError(err) {
  // The relation NAME is the required signal, not the SQLSTATE.
  //
  // This query also touches catalog_products, catalog_merchants,
  // index_pipeline_state and external_product_seeds. Latching on a bare
  // `code === '42P01'` therefore disabled the feature permanently whenever ANY
  // of those went missing — verified by injecting `relation
  // "index_pipeline_state" does not exist`: the next request for a healthy,
  // unrelated sig ran the no-join SQL, and the warn line blamed migration 181.
  // Silent, process-lifetime, and misdiagnosed.
  //
  // Postgres's undefined_table message always names the relation, so requiring
  // the name first costs nothing and the SQLSTATE stays as corroboration (a
  // wrapping proxy may carry only the text).
  const message = String(err?.message || err || '');
  if (!message.includes('content_canonical_election')) return false;
  return err?.code === '42P01' || message.includes('does not exist');
}

async function resolveCatalogProductRefFromPivotaSignatureInner(normalizedProductId, options = {}) {
  try {
    const buildExactSignatureSql = (withElection) => `
        SELECT
          cp.merchant_id,
          cp.platform,
          cp.source_product_id,
          cp.product_key,
          cp.source_system,
          cp.pivota_signature_id,
          cp.content_key,
          cp.title AS catalog_title,
          cp.brand AS catalog_brand,
          cp.image_url AS catalog_image_url,
          cp.description AS catalog_description,
          cp.canonical_url AS catalog_canonical_url,
          cp.pivota_canonical_url AS catalog_pivota_canonical_url,
          cp.product_payload AS catalog_product_payload,
          cp.sync_status AS catalog_sync_status,
          cp.pdp_lifecycle_stage AS catalog_pdp_lifecycle_stage,
          cp.category,
          cp.product_type,
          cp.category_path,
          cp.category_label_source,
          cp.category_confidence,
          -- Migration 186 (pivota-backend) aggregateRating columns. The sig
          -- route builds its identity from THIS resolver (not
          -- resolveCatalogIdentityForProductRef), so omitting them here drops
          -- the rating on exactly the canonical sitemap-indexed pages.
          cp.rating_value AS catalog_rating_value,
          cp.rating_count AS catalog_rating_count,
          signature_ips.serving_eligible AS signature_serving_eligible,
          signature_ips.readiness_tier AS signature_readiness_tier,
          signature_ips.pipeline_stage AS signature_pipeline_stage,
          signature_ips.blocker_code AS signature_blocker_code,
          signature_ips.blocker_detail AS signature_blocker_detail,
          signature_ips.content_quality_score AS signature_content_quality_score,
          -- Migration 181 (pivota-backend). The ONE sig that holds the public
          -- URL for this row's content_key. 474 content_keys serve identical
          -- content under 2-7 sitemap-eligible sigs, and until now every one of
          -- those pages emitted a SELF-referential <link rel="canonical"> — two
          -- URLs, same content, each claiming to be canonical, so Google is
          -- free to index the one the sitemap does NOT advertise.
          --
          -- The value is READ, never derived here. The sitemap advertises
          -- exactly this sig, and it can only do that because both sides read
          -- one stored answer: the winner is sticky on index equity
          -- (pivota-agent-ui#280 seeded it from the URLs already indexed), and
          -- incumbency is not a property either surface can recompute.
          --
          -- Aliased content_canonical_* because canonical_sig_id is already
          -- taken on the ref this row builds, where it means the sellable
          -- ITEM GROUP id — a different and wider canonicalisation.
          ${withElection ? 'cce_valid.canonical_sig_id' : 'NULL::text'} AS content_canonical_sig_id,
          eps.id AS external_seed_id,
          eps.external_product_id AS external_seed_external_product_id,
          eps.status AS external_seed_status,
          eps.updated_at AS external_seed_updated_at,
          eps.created_at AS external_seed_created_at,
          eps.seed_route_lane AS external_seed_route_lane,
          cp.suppression_reason AS catalog_suppression_reason,
          keeper.pivota_signature_id AS tombstone_keeper_sig_id
        FROM catalog_products cp
        LEFT JOIN catalog_merchants cm ON cm.merchant_id = cp.merchant_id
        LEFT JOIN index_pipeline_state signature_ips
          ON signature_ips.content_key = cp.content_key
        -- TOMBSTONE -> KEEPER canonical. A step-5 dedupe loser
        -- (suppression_reason set, suppression_metadata.keeper_product_key
        -- naming the survivor) still resolves and still renders 200 — this
        -- resolver deliberately has no suppression filter, and the ORDER BY
        -- below actively prefers the mirror lane. Measured in prod 2026-07-25:
        -- 431 tombstoned mirrors serve, all self-canonical, and 362 of them are
        -- the sig the live sitemap advertises. Serving them is fine (they ARE
        -- the incumbent URLs); serving them as their OWN canonical is not —
        -- it splits one product's index equity across up to 6 self-canonical
        -- duplicate 200s. Resolve the keeper's sig here so the PDP can point
        -- rel=canonical at it WITHOUT changing which row renders, which URL
        -- answers, or the sitemap's incumbency pick. Equity consolidates; no
        -- redirect and no URL migration is required for this step.
        LEFT JOIN LATERAL (
          SELECT keeper_cp.pivota_signature_id
          FROM catalog_products keeper_cp
          WHERE cp.suppression_reason IS NOT NULL
            AND keeper_cp.product_key = cp.suppression_metadata->>'keeper_product_key'
            -- Three guards, all load-bearing. Same content_key: never
            -- canonicalize to a DIFFERENT product if a keeper pointer is ever
            -- wrong. Keeper not itself tombstoned: a chain of dedupe runs could
            -- otherwise point at another loser. Keeper has a sig: /products/
            -- 500s on a bare content_key, so a sig-less keeper must leave the
            -- page self-canonical rather than advertise a URL that errors.
            AND keeper_cp.content_key = cp.content_key
            AND keeper_cp.suppression_reason IS NULL
            AND keeper_cp.pivota_signature_id IS NOT NULL
          LIMIT 1
        ) keeper ON true
        -- LEFT, never INNER: a content_key with no election yet (freshly
        -- minted, or the sweep has not run) must still resolve. It gets a null
        -- and the PDP falls back to a self-referential canonical — exactly the
        -- behaviour that predates this join. Primary-key lookup on a row this
        -- query has already materialised, so it adds no round trip.
        ${withElection ? `LEFT JOIN LATERAL (
          -- The elected canonical sig for this content_key, but ONLY while that
          -- sig is STILL something we would advertise.
          --
          -- An election is a durable fact; electability is a live one, and they
          -- diverge the moment the elected row stops rendering. Reading the
          -- election unvalidated produces the exact failure this feature exists
          -- to prevent: the SITEMAP is structurally safe (its renderable filter
          -- runs before the dedup, so a dead sig is never a candidate and the
          -- live sibling gets advertised), but this side would still hand the
          -- sibling's PDP the dead sig — so we would submit URL B while B's own
          -- page canonicalised at a URL that 500s. That content_key then loses
          -- ALL index presence: worse than the duplicate, worse than a moved
          -- URL. Not hypothetical — P3 moved 2,051 rows on renderable in a day.
          --
          -- NULL is the correct degradation: it means "no election", which the
          -- consumer already handles by falling back to self, so both surfaces
          -- fall back TOGETHER.
          SELECT cce.canonical_sig_id
          FROM content_canonical_election cce
          JOIN catalog_products cp_elected
            ON cp_elected.pivota_signature_id = cce.canonical_sig_id
          JOIN index_pipeline_state ips_elected
            ON ips_elected.content_key = cp_elected.content_key
          LEFT JOIN catalog_merchants cm_elected
            ON cm_elected.merchant_id = cp_elected.merchant_id
          WHERE cce.content_key = cp.content_key
            -- Skip the whole check when the election names THIS row: a
            -- self-canonical needs no cross-reference, and this confines the
            -- renderability probes to the ~11% of rows that are genuinely
            -- duplicates instead of paying them on every PDP request.
            AND cce.canonical_sig_id IS DISTINCT FROM cp.pivota_signature_id
            -- The stored id must still LOOK like a route id. Under
            -- INDEX_ELIGIBLE_SITEMAP the backend's elector qualifies rows on
            -- index_eligible alone rather than on the sig shape, so a non-sig_
            -- pivota_signature_id could reach this table and then be handed to
            -- agent-ui to build a URL out of. Underscore escaped — it is a
            -- single-character wildcard in LIKE.
            AND cce.canonical_sig_id LIKE 'sig\\_%'
            AND cp_elected.suppressed_at IS NULL
            -- NOT a step-5 dedupe loser. suppression_reason without
            -- suppressed_at is a real, populated state: 431 tombstoned rows
            -- still serve 200s and 362 are live sitemap URLs. #1833 points
            -- every such loser at its keeper, and that keeper is in the SAME
            -- content_key — so crowning a tombstone here would point a live
            -- keeper at a duplicate and undo a fix already in production.
            AND cp_elected.suppression_reason IS NULL
            AND cp_elected.content_key IS NOT NULL
            -- Serving gate, widened in lockstep with the BACKEND's
            -- INDEX_ELIGIBLE_SITEMAP (ADR-007's offer-free citation floor).
            --
            -- That flag is ON in production — 100 rows in the live feed are
            -- index_eligible WITHOUT serving_eligible. Hardcoding
            -- serving_eligible here makes this guard narrower than the elector,
            -- so the backend can elect a widen-only winner that this can never
            -- validate: the sitemap advertises it, every sibling PDP silently
            -- falls back to self-canonical, and the duplicate returns with no
            -- signal anywhere. Narrower is the SAFE direction (degrade, never a
            -- dead URL), which is why this is a correctness-of-coverage fix
            -- rather than an invariant fix — but it is a live flag, not a
            -- hypothetical, so the two must be set together.
            AND (ips_elected.serving_eligible IS TRUE${
              INDEX_ELIGIBLE_SITEMAP_ENABLED ? ' OR ips_elected.index_eligible IS TRUE' : ''
            })
            AND cm_elected.indexable IS TRUE
            AND cm_elected.status IN ('active', 'observed')
            -- BOTH halves of renderability: the lane dispatch AND the seed
            -- route. seedRouteResolvesSql alone would pass a merchant-synced
            -- row whose source_product_id collided with a seed id, while
            -- pdpRouteResolvable calls that lane FALSE — and being wider here
            -- is the over-advertise direction, i.e. canonicalising a live page
            -- at a URL that 500s.
            AND ${seedRoutedLaneSql('cp_elected')}
            AND ${seedRouteResolvesSql('cp_elected')}
          LIMIT 1
        ) cce_valid ON true` : ''}
        LEFT JOIN LATERAL (
          SELECT
            seed_pick.id,
            seed_pick.external_product_id,
            seed_pick.status,
            seed_pick.updated_at,
            seed_pick.created_at,
            seed_pick.seed_route_lane
          FROM (
            -- LANE 0 — ROUTE KEY (unchanged). ADR-009: external seeds are
            -- identified by platform, not the legacy merchant_id='external_seed'
            -- bucket (per-brand merch_obs_ sellers now).
            SELECT
              eps.id,
              eps.external_product_id,
              eps.status,
              eps.updated_at,
              eps.created_at,
              0 AS seed_route_lane
            FROM external_product_seeds eps
            WHERE cp.platform = '${EXTERNAL_SEED_MERCHANT_ID}'
              AND eps.external_product_id = cp.source_product_id
            UNION ALL
            -- LANE 1 — P3 MINTED CANONICALS. Path-C rows
            -- (source_system='catalog_enrichment_agent_v1') attach their seed by
            -- attached_product_key and carry a brand:hash external_product_id,
            -- while their own source_product_id is a canonical NAME SLUG — so the
            -- lane-0 key can never meet (measured prod 2026-07-25: 0 of 2,175
            -- minted rows resolve on it, while 2,063 carry an attached seed and
            -- 2,051 an ACTIVE one). Without this arm every minted PDP 404s at
            -- fetch_canonical_product and the ISR route turns that into a 500.
            -- Same join key as services/catalog_row_trust_upserter.minted_seed_one.
            SELECT
              eps.id,
              eps.external_product_id,
              eps.status,
              eps.updated_at,
              eps.created_at,
              1 AS seed_route_lane
            FROM external_product_seeds eps
            WHERE cp.source_system = 'catalog_enrichment_agent_v1'
              AND eps.attached_product_key = cp.product_key
          ) seed_pick
          ORDER BY
            -- Lane FIRST: whenever lane 0 answers at all, its own best row wins,
            -- so every pre-P3 lane keeps byte-identical resolution. Lane 1 is
            -- reachable only when lane 0 returns nothing.
            seed_pick.seed_route_lane ASC,
            -- ACTIVE FIRST — deliberately ranked ABOVE the identity-carrying
            -- preference that minted_seed_one uses. That CTE picks the seed whose
            -- external_product_id joins pdp_identity_listing, for determinism of
            -- the pil join key; here the winner is the row that DECIDES THE
            -- CONTENT ROUTE, and pdpRenderability's seedRouteResolvesSql predicts
            -- renderable from "an acceptable seed EXISTS". Ranking identity above
            -- status would break that equivalence: a product with an
            -- identity-carrying INACTIVE seed and a plain ACTIVE one would be
            -- advertised renderable and then 404 external_seed_not_active.
            -- (pdp_identity_listing is indexed on (merchant_id, product_id), so a
            -- per-seed identity EXISTS on this hot path would also be an
            -- unindexed probe per candidate — up to 31 candidates on the widest
            -- minted product_key in prod.)
            --
            -- PRECISION NOTE: the downstream external-seed status precheck does
            -- NOT read this winner's status. fetchExternalSeedRouteStatusFromDb
            -- re-queries external_product_seeds by the resolved id and re-ranks
            -- with its own ORDER BY (active first, then recency). The two agree
            -- today because the resolved id is this winner's external_product_id
            -- and the active-unique index makes at most one active row answer it
            -- — but the precheck is a second, independent pick, not a read of
            -- this one. Whichever way that redundancy is resolved, both orderings
            -- must stay active-first or the renderability equivalence above
            -- breaks.
            CASE WHEN seed_pick.status = 'active' THEN 0 ELSE 1 END,
            seed_pick.updated_at DESC NULLS LAST,
            seed_pick.created_at DESC NULLS LAST,
            -- Total order, so a minted product_key with several equally-fresh
            -- seeds renders the SAME seed on every request instead of whichever
            -- row the planner happened to emit first.
            seed_pick.id DESC
          LIMIT 1
        ) eps ON true
        WHERE cp.pivota_signature_id = $1
          AND ${activeCatalogProductSourceWhere('cp', 'cm')}
        ORDER BY
          CASE WHEN cp.source_system = 'external_product_seeds_mirror_v1' THEN 0 ELSE 1 END,
          cp.updated_at DESC NULLS LAST,
          cp.product_key ASC
        LIMIT 1
      `;
    let exactResult;
    try {
      exactResult = await query(
        buildExactSignatureSql(!CONTENT_CANONICAL_ELECTION_TABLE_MISSING),
        [normalizedProductId],
      );
    } catch (err) {
      if (CONTENT_CANONICAL_ELECTION_TABLE_MISSING || !isMissingContentCanonicalElectionError(err)) {
        throw err;
      }
      // First request to notice migration 181 has not landed. Latch, warn ONCE
      // (the flag makes this branch unreachable afterwards), and serve.
      CONTENT_CANONICAL_ELECTION_TABLE_MISSING = true;
      logger.warn?.(
        { err: err?.message || String(err) },
        'content_canonical_election is missing — serving PDPs without cross-canonical tags ' +
          'until pivota-backend migration 181 lands. Duplicate sig URLs stay self-canonical.',
      );
      exactResult = await query(buildExactSignatureSql(false), [normalizedProductId]);
    }
    const exactRow = Array.isArray(exactResult?.rows) ? exactResult.rows[0] : null;
    const exactMerchantId = String(exactRow?.merchant_id || '').trim();
    // P3: when the seed was resolved through LANE 1 (minted canonical, attached
    // by product_key), the row's own source_product_id is a name slug that NO
    // content store answers on. The gateway's downstream content route —
    // precheck_entry_product, the external-seed status precheck, and
    // fetch_canonical_product — is keyed on the product id, so the minted lane
    // must present the SEED's external_product_id, exactly like the mirror lane
    // does (there source_product_id already IS the seed id, which is why that
    // lane renders). This narrows to lane 1 only: lane 0 and the no-seed case
    // keep the slug they resolve on today.
    const mintedSeedRouteProductId =
      Number(exactRow?.external_seed_route_lane) === 1
        ? firstNonEmptyString(exactRow?.external_seed_external_product_id)
        : null;
    const exactSourceProductId =
      mintedSeedRouteProductId || String(exactRow?.source_product_id || '').trim();
    if (exactMerchantId && exactSourceProductId) {
      let exactIdentityRow = null;
      if (
        options.hydrateIdentityListing !== false &&
        isExternalSeedListingMerchantId(exactMerchantId) &&
        isExternalSeedProductId(exactSourceProductId)
      ) {
        try {
          const identityResult = await query(
            `
              SELECT
                pil.sellable_item_group_id,
                pil.product_line_id,
                pil.review_family_id,
                pil.identity_confidence,
                pil.match_basis,
                pil.identity_status,
                pil.live_read_enabled,
                pil.review_required
              FROM pdp_identity_listing pil
              WHERE pil.source_listing_ref = $1
                AND NULLIF(pil.sellable_item_group_id, '') IS NOT NULL
                AND pil.identity_status = 'approved'
                AND pil.live_read_enabled IS TRUE
                AND COALESCE(pil.review_required, false) IS NOT TRUE
              LIMIT 1
            `,
            // Post-#1770 the observed-seller (`merch_obs_`) listing is keyed on
            // its own merchant id, not the legacy `external_seed` bucket, so
            // derive the ref from the resolved merchant rather than hardcoding
            // the prefix. Legacy external seeds keep `external_seed:<epid>`.
            [`${exactMerchantId}:${exactSourceProductId}`],
          );
          exactIdentityRow = Array.isArray(identityResult?.rows) ? identityResult.rows[0] : null;
        } catch (err) {
          const message = String(err?.message || err || '');
          if (!(err?.code === 'NO_DATABASE' || (message.includes('pdp_identity_listing') && message.includes('does not exist')))) {
            logger.debug?.(
              { err: err?.message || String(err), product_id: exactSourceProductId },
              'Failed to resolve exact signature identity listing',
            );
          }
        }
      }
      const exactIdentityGroupId = firstNonEmptyString(exactIdentityRow?.sellable_item_group_id);
      let exactIdentityGroup = null;
      if (options.hydrateIdentityGroupMembers !== false && exactIdentityGroupId) {
        try {
          // Heaviest query in the resolver: two correlated EXISTS plus a
          // LATERAL join are evaluated for EVERY candidate row in the identity
          // group before `LIMIT 200` can apply, so an over-clustered
          // sellable_item_group_id is unbounded work, not a bounded 200 rows.
          const groupRowsResult = await query(
            `
              SELECT
                pil.source_listing_ref,
                pil.merchant_id,
                pil.product_id,
                pil.source_kind,
                pil.source_tier,
                pil.source_payload,
                pil.variant_axes,
                cp_offer.title AS catalog_title,
                cp_offer.brand AS catalog_brand,
                cp_offer.canonical_url AS catalog_canonical_url,
                cp_offer.image_url AS catalog_image_url,
                -- Electronics spec surface is FIRST-CLASS at compose time (main
                -- route — no render-time fallback). Project the whitelisted
                -- electronics_meta off the resolved catalog row's payload so a
                -- group member that later feeds product composition carries the
                -- spec table like the primary route.
                --
                -- GATED on category for the same reason as the sibling
                -- projection above: #> on a TOASTed jsonb detoasts the WHOLE
                -- payload, once per group member. See that comment for the
                -- measured blast radius.
                CASE
                  WHEN cp_offer.category ILIKE 'electronics%'
                    THEN cp_offer.product_payload#>'{seed_data,electronics_meta}'
                  ELSE NULL
                END AS catalog_electronics_meta,
                offer_row.offer_id AS catalog_offer_id,
                offer_row.sku_key AS catalog_sku_key,
                offer_row.currency AS catalog_offer_currency,
                COALESCE(
                  offer_row.merchant_effective_price,
                  offer_row.estimated_best_price,
                  offer_row.list_price
                ) AS catalog_offer_price,
                offer_row.source_system AS catalog_offer_source_system,
                offer_row.source_ref AS catalog_offer_source_ref
              FROM pdp_identity_listing pil
              ${buildGroupMemberCatalogOfferLateralJoinSql('pil')}
              LEFT JOIN LATERAL (
                SELECT
                  o.offer_id,
                  o.sku_key,
                  o.currency,
                  o.merchant_effective_price,
                  o.estimated_best_price,
                  o.list_price,
                  o.source_system,
                  o.source_ref
                FROM catalog_skus s
                JOIN catalog_offers o ON o.sku_key = s.sku_key
                WHERE s.product_key = cp_offer.product_key
                ORDER BY
                  CASE WHEN o.availability ILIKE 'in%stock%' THEN 0 ELSE 1 END,
                  o.updated_at DESC NULLS LAST,
                  o.offer_id ASC
                LIMIT 1
              ) offer_row ON true
              WHERE pil.sellable_item_group_id = $1
                AND pil.identity_status = 'approved'
                AND pil.live_read_enabled IS TRUE
                AND COALESCE(pil.review_required, false) IS NOT TRUE
                AND (
                  pil.source_kind <> 'external_seed'
                  OR EXISTS (
                    SELECT 1
                    FROM external_product_seeds eps
                    JOIN catalog_products cp_active
                      -- ADR-009: match by platform + source_product_id, not the
                      -- legacy merchant_id='external_seed' bucket (per-brand
                      -- merch_obs_ sellers now) — see the sibling EXISTS above.
                      ON cp_active.platform = 'external_seed'
                     AND cp_active.source_system = 'external_product_seeds_mirror_v1'
                     AND cp_active.source_product_id = eps.external_product_id
                     AND cp_active.sync_status = 'live'
                    JOIN index_pipeline_state ips_active
                      ON ips_active.content_key = cp_active.content_key
                     AND ips_active.serving_eligible = TRUE
                    WHERE eps.external_product_id = pil.product_id
                      AND eps.status = 'active'
                  )
                  -- Path-C minted canonicals: seed links by attached_product_key
                  -- (source_product_id is a name slug, never a seed id). Kept in
                  -- sync with buildActiveExternalSeedIdentityPredicate.
                  OR EXISTS (
                    SELECT 1
                    FROM external_product_seeds eps
                    JOIN catalog_products cp_active
                      ON cp_active.source_system = 'catalog_enrichment_agent_v1'
                     AND cp_active.product_key = eps.attached_product_key
                     AND cp_active.sync_status = 'live'
                    JOIN index_pipeline_state ips_active
                      ON ips_active.content_key = cp_active.content_key
                     AND ips_active.serving_eligible = TRUE
                    WHERE eps.external_product_id = pil.product_id
                      AND eps.status = 'active'
                  )
                )
              ORDER BY
                CASE WHEN pil.source_tier = 'brand' THEN 0 ELSE 1 END,
                pil.identity_confidence DESC NULLS LAST,
                pil.updated_at DESC NULLS LAST,
                pil.created_at DESC NULLS LAST
              LIMIT 200
            `,
            [exactIdentityGroupId],
          );
          const directGroupMembers = (Array.isArray(groupRowsResult?.rows) ? groupRowsResult.rows : [])
            .map((row) => buildCatalogSignatureGroupMemberFromIdentityRow(row, {
              merchant_id: exactMerchantId,
              product_id: exactSourceProductId,
            }))
            .filter(Boolean);
          if (directGroupMembers.length > 0) {
            exactIdentityGroup = {
              product_group_id: exactIdentityGroupId,
              sellable_item_group_id: exactIdentityGroupId,
              canonical_product_ref: {
                merchant_id: exactMerchantId,
                product_id: exactSourceProductId,
              },
              group_members: directGroupMembers,
            };
          }
        } catch (err) {
          const message = String(err?.message || err || '');
          if (!(err?.code === 'NO_DATABASE' || (message.includes('pdp_identity_listing') && message.includes('does not exist')))) {
            logger.debug?.(
              {
                err: err?.message || String(err),
                product_id: exactSourceProductId,
                sellable_item_group_id: exactIdentityGroupId,
              },
              'Failed to hydrate exact signature identity group members via direct query',
            );
          }
        }
      }
      if (
        options.hydrateIdentityGroupMembers !== false &&
        exactIdentityGroupId &&
        !exactIdentityGroup?.group_members?.length
      ) {
        try {
          exactIdentityGroup = await resolveLivePdpIdentityGroupForPdp({
            productGroupId: exactIdentityGroupId,
            queryFn: query,
          });
        } catch (err) {
          logger.debug?.(
            {
              err: err?.message || String(err),
              product_id: exactSourceProductId,
              sellable_item_group_id: exactIdentityGroupId,
            },
            'Failed to hydrate exact signature identity group members',
          );
        }
      }
      const exactIdentityGroupMembers = Array.isArray(exactIdentityGroup?.group_members)
        ? exactIdentityGroup.group_members
        : [];
      const exactEffectiveSellableGroupId = firstNonEmptyString(
        exactIdentityGroup?.sellable_item_group_id,
        exactIdentityGroup?.product_group_id,
        exactIdentityGroupId,
        normalizedProductId,
      );
      return {
        merchant_id: exactMerchantId,
        product_id: exactSourceProductId,
        ...(exactRow?.platform ? { platform: String(exactRow.platform).trim() } : {}),
        ...(exactRow?.product_key ? { product_key: String(exactRow.product_key).trim() } : {}),
        ...(exactRow?.source_system ? { source_system: String(exactRow.source_system).trim() } : {}),
        pivota_signature_id: normalizedProductId,
        title: firstNonEmptyString(exactRow?.catalog_title, exactRow?.title),
        brand: firstNonEmptyString(exactRow?.catalog_brand, exactRow?.brand),
        image_url: firstNonEmptyString(exactRow?.catalog_image_url, exactRow?.image_url),
        description: firstNonEmptyString(exactRow?.catalog_description, exactRow?.description),
        canonical_url: firstNonEmptyString(exactRow?.catalog_canonical_url, exactRow?.canonical_url),
        pivota_canonical_url: firstNonEmptyString(
          exactRow?.catalog_pivota_canonical_url,
          exactRow?.pivota_canonical_url,
        ),
        product_payload:
          exactRow?.catalog_product_payload !== undefined
            ? exactRow.catalog_product_payload
            : exactRow?.product_payload,
        sync_status: firstNonEmptyString(exactRow?.catalog_sync_status, exactRow?.sync_status),
        pdp_lifecycle_stage: firstNonEmptyString(
          exactRow?.catalog_pdp_lifecycle_stage,
          exactRow?.pdp_lifecycle_stage,
        ),
        serving_eligibility_prefetched:
          Object.prototype.hasOwnProperty.call(exactRow, 'signature_serving_eligible') ||
          Object.prototype.hasOwnProperty.call(exactRow, 'signature_readiness_tier') ||
          Object.prototype.hasOwnProperty.call(exactRow, 'signature_pipeline_stage') ||
          Object.prototype.hasOwnProperty.call(exactRow, 'signature_blocker_code'),
        signature_serving_eligible: exactRow?.signature_serving_eligible,
        signature_readiness_tier: firstNonEmptyString(exactRow?.signature_readiness_tier),
        signature_pipeline_stage: firstNonEmptyString(exactRow?.signature_pipeline_stage),
        signature_blocker_code: firstNonEmptyString(exactRow?.signature_blocker_code),
        signature_blocker_detail: firstNonEmptyString(exactRow?.signature_blocker_detail),
        signature_content_quality_score: Number.isFinite(Number(exactRow?.signature_content_quality_score))
          ? Number(exactRow.signature_content_quality_score)
          : null,
        category: firstNonEmptyString(exactRow?.category),
        product_type: firstNonEmptyString(exactRow?.product_type),
        category_path: firstNonEmptyString(exactRow?.category_path),
        category_label_source: firstNonEmptyString(exactRow?.category_label_source),
        category_confidence: Number.isFinite(Number(exactRow?.category_confidence))
          ? Number(exactRow.category_confidence)
          : undefined,
        // Migration 186 aggregateRating columns; undefined (not null) when
        // uncaptured so the keys stay absent rather than asserting "no rating".
        catalog_rating_value: Number.isFinite(Number(exactRow?.catalog_rating_value))
          ? Number(exactRow.catalog_rating_value)
          : undefined,
        catalog_rating_count: Number.isFinite(Number(exactRow?.catalog_rating_count))
          ? Number(exactRow.catalog_rating_count)
          : undefined,
        product_group_id: exactEffectiveSellableGroupId,
        sellable_item_group_id: exactEffectiveSellableGroupId,
        canonical_sig_id: exactEffectiveSellableGroupId,
        // Set ONLY when this row is a dedupe loser whose keeper is live and
        // signed (see the keeper LATERAL). Null on every untombstoned row, so
        // the flag-free default for the whole non-deduped catalog is unchanged.
        suppression_reason: firstNonEmptyString(exactRow?.catalog_suppression_reason),
        tombstone_keeper_sig_id: firstNonEmptyString(exactRow?.tombstone_keeper_sig_id),
        public_pdp_id: normalizedProductId,
        requested_pivota_signature_id: normalizedProductId,
        catalog_pivota_signature_id: normalizedProductId,
        identity_sellable_item_group_id: exactIdentityGroupId,
        product_line_id: firstNonEmptyString(exactIdentityRow?.product_line_id),
        review_family_id: firstNonEmptyString(exactIdentityRow?.review_family_id),
        identity_confidence: Number.isFinite(Number(exactIdentityRow?.identity_confidence))
          ? Number(exactIdentityRow.identity_confidence)
          : undefined,
        match_basis: Array.isArray(exactIdentityRow?.match_basis) ? exactIdentityRow.match_basis : [],
        identity_status: firstNonEmptyString(exactIdentityRow?.identity_status),
        live_read_enabled: exactIdentityRow?.live_read_enabled === true,
        review_required: exactIdentityRow?.review_required === true,
        external_seed_status: firstNonEmptyString(exactRow?.external_seed_status),
        external_seed_id: firstNonEmptyString(exactRow?.external_seed_id),
        external_seed_external_product_id: firstNonEmptyString(exactRow?.external_seed_external_product_id),
        external_seed_updated_at: exactRow?.external_seed_updated_at || null,
        external_seed_created_at: exactRow?.external_seed_created_at || null,
        content_key: firstNonEmptyString(exactRow?.content_key) || null,
        // The elected canonical URL id for this content_key (migration 181), or
        // null when nothing has been elected. NOT `canonical_sig_id` — that key
        // is already the sellable ITEM GROUP id on this ref.
        content_canonical_sig_id:
          firstNonEmptyString(exactRow?.content_canonical_sig_id) || null,
        members: exactIdentityGroupMembers,
        group_members: exactIdentityGroupMembers,
        member_sig_ids: uniqueStrings([
          normalizedProductId,
          exactEffectiveSellableGroupId,
          ...exactIdentityGroupMembers
            .map((member) => firstNonEmptyString(member?.pivota_signature_id, member?.signature_id))
            .filter(Boolean),
        ]),
        source: 'catalog_products_signature_exact',
      };
    }

    const canonicalGroup = await resolveCanonicalCatalogEntityGroup({
      productId: normalizedProductId,
      queryFn: query,
    });
    if (canonicalGroup?.canonical_product_ref?.merchant_id && canonicalGroup?.canonical_product_ref?.product_id) {
      const requestedSignatureMember = (
        Array.isArray(canonicalGroup.members)
          ? canonicalGroup.members
          : Array.isArray(canonicalGroup.group_members)
            ? canonicalGroup.group_members
            : []
      ).find((member) => firstNonEmptyString(member?.pivota_signature_id) === normalizedProductId);
      const signatureProductRef =
        requestedSignatureMember?.merchant_id && requestedSignatureMember?.product_id
          ? requestedSignatureMember
          : canonicalGroup.canonical_product_ref;
      const signatureGroupId =
        requestedSignatureMember?.merchant_id && requestedSignatureMember?.product_id
          ? normalizedProductId
          : canonicalGroup.product_group_id || normalizedProductId;
      return {
        merchant_id: signatureProductRef.merchant_id,
        product_id: signatureProductRef.product_id,
        ...(signatureProductRef.platform ? { platform: signatureProductRef.platform } : {}),
        ...(signatureProductRef.product_key ? { product_key: signatureProductRef.product_key } : {}),
        ...(signatureProductRef.pivota_signature_id
          ? { pivota_signature_id: signatureProductRef.pivota_signature_id }
          : {}),
        product_group_id: signatureGroupId,
        sellable_item_group_id:
          signatureGroupId || canonicalGroup.sellable_item_group_id || canonicalGroup.product_group_id || normalizedProductId,
        canonical_sig_id: signatureGroupId || canonicalGroup.canonical_sig_id || canonicalGroup.product_group_id || normalizedProductId,
        content_key: canonicalGroup.content_key || null,
        members: Array.isArray(canonicalGroup.members) ? canonicalGroup.members : [],
        group_members: Array.isArray(canonicalGroup.group_members) ? canonicalGroup.group_members : [],
        member_sig_ids: Array.isArray(canonicalGroup.member_sig_ids) ? canonicalGroup.member_sig_ids : [],
        source: 'canonical_catalog_signature',
      };
    }

    const result = await query(
      `
        SELECT merchant_id, platform, source_product_id, product_key
        FROM catalog_products
        WHERE pivota_signature_id = $1
        LIMIT 1
      `,
      [normalizedProductId],
    );
    const row = Array.isArray(result?.rows) ? result.rows[0] : null;
    const merchantId = String(row?.merchant_id || '').trim();
    const sourceProductId = String(row?.source_product_id || '').trim();
    if (!merchantId || !sourceProductId) return null;
    return {
      merchant_id: merchantId,
      product_id: sourceProductId,
      ...(row?.platform ? { platform: String(row.platform).trim() } : {}),
      ...(row?.product_key ? { product_key: String(row.product_key).trim() } : {}),
    };
  } catch (err) {
    const message = String(err?.message || err || '');
    if (
      err?.code === 'NO_DATABASE' ||
      err?.code === '42P01' ||
      (message.includes('catalog_products') && message.includes('does not exist'))
    ) {
      return null;
    }
    logger.warn(
      { err: err?.message || String(err), product_id: normalizedProductId },
      'Failed to resolve catalog product ref from pivota signature',
    );
    return null;
  }
}

function isPivotaSignatureProductId(value) {
  return /^sig_[a-z0-9]+$/i.test(String(value || '').trim());
}

function buildPublicProductUrl(entityId) {
  const normalizedEntityId = String(entityId || '').trim();
  return `https://agent.pivota.cc/products/${normalizedEntityId}`;
}

function resolvePublicProductIdForEmit(fallbackProductId, canonicalEntityId = '') {
  const normalizedFallbackProductId = String(fallbackProductId || '').trim();
  const normalizedCanonicalEntityId = String(canonicalEntityId || '').trim();
  return CANONICAL_ENTITY_ID_PUBLIC_EMIT_ENABLED && normalizedCanonicalEntityId
    ? normalizedCanonicalEntityId
    : normalizedFallbackProductId;
}

async function resolvePublicExternalSeedProductId(externalProductId, { canonicalEntityId = '' } = {}) {
  const normalizedExternalProductId = String(externalProductId || '').trim();
  if (!normalizedExternalProductId) return '';
  const explicitCanonicalEntityId = String(canonicalEntityId || '').trim();
  if (!CANONICAL_ENTITY_ID_PUBLIC_EMIT_ENABLED) return normalizedExternalProductId;
  if (explicitCanonicalEntityId) return explicitCanonicalEntityId;

  const group = await resolveProductGroupCached({ productId: normalizedExternalProductId }).catch((err) => {
    logger.debug?.(
      {
        err: err?.message || String(err),
        product_id: normalizedExternalProductId,
      },
      'Canonical entity public emit external-seed group resolution failed',
    );
    return null;
  });
  return firstNonEmptyString(group?.canonical_entity_id, normalizedExternalProductId);
}

function applyRequestedPivotaSignatureToPdpProduct(
  product,
  sigId,
  sourceProductId = '',
  canonicalEntityId = '',
  // Keeper sig of a step-5 dedupe group, set only when the row backing THIS
  // request is a tombstoned loser (see the keeper LATERAL in
  // resolveCatalogProductRefFromPivotaSignatureInner). Moves rel=canonical
  // only — the page keeps answering 200 on its own URL with its own `url`.
  canonicalRouteSigId = '',
) {
  if (!product || typeof product !== 'object' || Array.isArray(product)) return product;
  const normalizedSigId = String(sigId || '').trim();
  if (!/^sig_[a-z0-9]+$/i.test(normalizedSigId)) return product;
  const normalizedCanonicalEntityId = String(canonicalEntityId || '').trim();
  const shouldEmitCanonicalEntityId =
    CANONICAL_ENTITY_ID_PUBLIC_EMIT_ENABLED && Boolean(normalizedCanonicalEntityId);
  const publicId = shouldEmitCanonicalEntityId
    ? normalizedCanonicalEntityId
    : normalizedSigId;
  const publicUrl = buildPublicProductUrl(publicId);

  const resolvedSourceProductId = firstNonEmptyString(
    sourceProductId,
    product.source_product_id,
    product.external_product_id,
    product.external_seed_product_id,
    product.platform_product_id,
    product.product_id,
    product.id,
  );
  const currentCanonicalUrl = firstNonEmptyString(product.canonical_url, product.url);
  const merchantCanonicalUrl = firstNonEmptyString(
    product.merchant_canonical_url,
    product.destination_url,
    currentCanonicalUrl && !/\/products\/sig_/i.test(currentCanonicalUrl) ? currentCanonicalUrl : '',
  );
  const pivotaCanonicalUrl = shouldEmitCanonicalEntityId
    ? publicUrl
    : firstNonEmptyString(product.pivota_canonical_url, publicUrl);

  // Dedupe-loser canonical. Deliberately NOT applied on the
  // canonical_entity_id path: that flag already emits a stronger cross-row
  // canonical, and stacking the two would silently change what it publishes.
  const normalizedKeeperSigId = String(canonicalRouteSigId || '').trim();
  const keeperCanonicalUrl =
    !shouldEmitCanonicalEntityId &&
    /^sig_[a-z0-9]+$/i.test(normalizedKeeperSigId) &&
    normalizedKeeperSigId !== publicId
      ? buildPublicProductUrl(normalizedKeeperSigId)
      : '';

  // `url` stays the REQUESTED url even when canonical points elsewhere. The
  // page genuinely answers here; only the consolidation target moves. agent-ui
  // reads rel=canonical off pivota_canonical_url/canonical_url
  // (lib/productHref.resolveProductRouteId), never off `url`.
  const effectiveCanonicalUrl = keeperCanonicalUrl || pivotaCanonicalUrl;

  return {
    ...product,
    id: publicId,
    product_id: publicId,
    pivota_signature_id: product.pivota_signature_id || normalizedSigId,
    signature_id: product.signature_id || normalizedSigId,
    pivota_canonical_url: effectiveCanonicalUrl,
    canonical_url: effectiveCanonicalUrl,
    url: keeperCanonicalUrl ? publicUrl : pivotaCanonicalUrl,
    ...(keeperCanonicalUrl
      ? { canonical_route_sig_id: normalizedKeeperSigId, canonical_route_basis: 'dedupe_keeper' }
      : {}),
    ...(merchantCanonicalUrl ? { merchant_canonical_url: merchantCanonicalUrl } : {}),
    ...(resolvedSourceProductId
      ? {
          source_product_id: product.source_product_id || resolvedSourceProductId,
          external_product_id: product.external_product_id || resolvedSourceProductId,
          external_seed_product_id: product.external_seed_product_id || resolvedSourceProductId,
          platform_product_id: product.platform_product_id || resolvedSourceProductId,
        }
      : {}),
  };
}

function buildCatalogIdentityFromSignatureProductRef(signatureProductRef, {
  requestedSigId = '',
  resolvedMerchantId = '',
  resolvedProductId = '',
} = {}) {
  if (!signatureProductRef || typeof signatureProductRef !== 'object' || Array.isArray(signatureProductRef)) {
    return null;
  }
  const sigId = firstNonEmptyString(
    requestedSigId,
    signatureProductRef.pivota_signature_id,
    signatureProductRef.canonical_sig_id,
    signatureProductRef.sellable_item_group_id,
    signatureProductRef.product_group_id,
  );
  if (!isPivotaSignatureProductId(sigId)) return null;
  const merchantId = firstNonEmptyString(signatureProductRef.merchant_id, resolvedMerchantId);
  const sourceProductId = firstNonEmptyString(signatureProductRef.product_id, resolvedProductId);
  if (!merchantId || !sourceProductId) return null;
  return {
    merchant_id: merchantId,
    platform: firstNonEmptyString(signatureProductRef.platform),
    source_product_id: sourceProductId,
    product_key: firstNonEmptyString(signatureProductRef.product_key),
    pivota_signature_id: sigId,
    signature_id: sigId,
    category: firstNonEmptyString(signatureProductRef.category),
    product_type: firstNonEmptyString(signatureProductRef.product_type),
    category_path: firstNonEmptyString(signatureProductRef.category_path),
    category_label_source: firstNonEmptyString(signatureProductRef.category_label_source),
    category_confidence: Number.isFinite(Number(signatureProductRef.category_confidence))
      ? Number(signatureProductRef.category_confidence)
      : undefined,
    sellable_item_group_id: firstNonEmptyString(
      signatureProductRef.identity_sellable_item_group_id,
      signatureProductRef.sellable_item_group_id,
      sigId,
    ),
    product_group_id: firstNonEmptyString(
      signatureProductRef.identity_sellable_item_group_id,
      signatureProductRef.product_group_id,
      signatureProductRef.sellable_item_group_id,
      sigId,
    ),
    product_line_id: firstNonEmptyString(signatureProductRef.product_line_id),
    review_family_id: firstNonEmptyString(signatureProductRef.review_family_id),
    identity_confidence: Number.isFinite(Number(signatureProductRef.identity_confidence))
      ? Number(signatureProductRef.identity_confidence)
      : undefined,
    match_basis: Array.isArray(signatureProductRef.match_basis)
      ? signatureProductRef.match_basis
      : ['catalog_signature_exact'],
    identity_status: firstNonEmptyString(signatureProductRef.identity_status, 'approved'),
    live_read_enabled: signatureProductRef.live_read_enabled === true,
    review_required: signatureProductRef.review_required === true,
    // The elected canonical URL for this row's content_key (migration 181).
    // Carried through so get_pdp_v2 can read it off catalogIdentity — this
    // builder returns a NEW object, so anything not named here is dropped, and
    // a dropped election reads downstream as "no election": the duplicate PDP
    // silently goes back to declaring itself canonical.
    content_canonical_sig_id:
      firstNonEmptyString(signatureProductRef.content_canonical_sig_id) || null,
    // Migration 186 aggregateRating. Same dropped-key hazard as the election
    // above: this builder is the sig route's ONLY identity source, so a rating
    // not named here never reaches the canonical PDP's JSON-LD.
    catalog_rating_value: Number.isFinite(Number(signatureProductRef.catalog_rating_value))
      ? Number(signatureProductRef.catalog_rating_value)
      : undefined,
    catalog_rating_count: Number.isFinite(Number(signatureProductRef.catalog_rating_count))
      ? Number(signatureProductRef.catalog_rating_count)
      : undefined,
  };
}

async function resolveCatalogIdentityForProductRef({ merchantId, productId, productKey } = {}) {
  if (!process.env.DATABASE_URL) return null;
  const normalizedMerchantId = String(merchantId || '').trim();
  const normalizedProductId = String(productId || '').trim();
  const normalizedProductKey = String(productKey || '').trim();
  if (!normalizedMerchantId || (!normalizedProductId && !normalizedProductKey)) return null;

  const buildIdentityResult = (row, fallback = {}) => {
    const sigId = firstNonEmptyString(
      row?.pivota_signature_id,
      row?.signature_id,
      row?.sellable_item_group_id,
      fallback.pivota_signature_id,
    );
    if (!sigId || !isPivotaSignatureProductId(sigId)) return null;
    return {
      merchant_id: firstNonEmptyString(row?.merchant_id, fallback.merchant_id),
      platform: firstNonEmptyString(row?.platform, fallback.platform),
      source_product_id: firstNonEmptyString(row?.source_product_id, fallback.source_product_id),
      product_key: firstNonEmptyString(row?.product_key, fallback.product_key),
      pivota_signature_id: sigId,
      signature_id: sigId,
      category: firstNonEmptyString(row?.category),
      product_type: firstNonEmptyString(row?.product_type),
      category_path: firstNonEmptyString(row?.category_path),
      category_label_source: firstNonEmptyString(row?.category_label_source),
      category_confidence: Number.isFinite(Number(row?.category_confidence))
        ? Number(row.category_confidence)
        : undefined,
      sellable_item_group_id: firstNonEmptyString(row?.sellable_item_group_id, sigId),
      product_group_id: firstNonEmptyString(row?.sellable_item_group_id, sigId),
      product_line_id: firstNonEmptyString(row?.product_line_id),
      review_family_id: firstNonEmptyString(row?.review_family_id),
      identity_confidence: Number.isFinite(Number(row?.identity_confidence))
        ? Number(row.identity_confidence)
        : undefined,
      match_basis: Array.isArray(row?.match_basis) ? row.match_basis : [],
      identity_status: firstNonEmptyString(row?.identity_status),
      live_read_enabled: row?.live_read_enabled === true,
      review_required: row?.review_required === true,
      // Migration 186 (pivota-backend) aggregateRating columns. Captured from
      // schema.org storefronts; the seed-shaped review_summary lane never reads
      // them, so serving products with a real stored rating emitted no
      // aggregateRating in JSON-LD. undefined (not null) when uncaptured —
      // NULL at the source means "no review data", never zero stars.
      catalog_rating_value: Number.isFinite(Number(row?.catalog_rating_value))
        ? Number(row.catalog_rating_value)
        : undefined,
      catalog_rating_count: Number.isFinite(Number(row?.catalog_rating_count))
        ? Number(row.catalog_rating_count)
        : undefined,
    };
  };

  try {
    const result = await query(
      `
        SELECT
          cp.merchant_id,
          cp.platform,
          cp.source_product_id,
          cp.product_key,
          cp.pivota_signature_id,
          cp.category,
          cp.product_type,
          cp.category_path,
          cp.category_label_source,
          cp.category_confidence,
          cp.rating_value AS catalog_rating_value,
          cp.rating_count AS catalog_rating_count,
          pil.sellable_item_group_id,
          pil.product_line_id,
          pil.review_family_id,
          pil.identity_confidence,
          pil.match_basis,
          pil.identity_status,
          pil.live_read_enabled,
          pil.review_required
        FROM catalog_products cp
        LEFT JOIN pdp_identity_listing pil
          ON pil.merchant_id = cp.merchant_id
         AND pil.product_id = cp.source_product_id
        WHERE cp.merchant_id = $1
          AND (
            ($2::text <> '' AND cp.source_product_id = $2)
            OR ($3::text <> '' AND cp.product_key = $3)
          )
        LIMIT 1
      `,
      [normalizedMerchantId, normalizedProductId, normalizedProductKey],
    );
    const row = Array.isArray(result?.rows) ? result.rows[0] : null;
    const catalogIdentity = buildIdentityResult(row);
    if (catalogIdentity) return catalogIdentity;

    if (
      normalizedMerchantId === EXTERNAL_SEED_MERCHANT_ID &&
      isExternalSeedProductId(normalizedProductId)
    ) {
      const identityResult = await query(
        `
          SELECT
            $1::text AS merchant_id,
            'external_seed'::text AS platform,
            $2::text AS source_product_id,
            pil.sellable_item_group_id AS pivota_signature_id,
            pil.sellable_item_group_id,
            pil.product_line_id,
            pil.review_family_id,
            pil.identity_confidence,
            pil.match_basis,
            pil.identity_status,
            pil.live_read_enabled,
            pil.review_required
          FROM pdp_identity_listing pil
          WHERE pil.source_listing_ref = $3
            AND NULLIF(pil.sellable_item_group_id, '') IS NOT NULL
            AND pil.identity_status = 'approved'
            AND pil.live_read_enabled IS TRUE
            AND COALESCE(pil.review_required, false) IS NOT TRUE
          LIMIT 1
        `,
        [
          EXTERNAL_SEED_MERCHANT_ID,
          normalizedProductId,
          `external_seed:${normalizedProductId}`,
        ],
      );
      return buildIdentityResult(Array.isArray(identityResult?.rows) ? identityResult.rows[0] : null, {
        merchant_id: EXTERNAL_SEED_MERCHANT_ID,
        platform: 'external_seed',
        source_product_id: normalizedProductId,
      });
    }

    return null;
  } catch (err) {
    const message = String(err?.message || err || '');
    if (
      err?.code === 'NO_DATABASE' ||
      ((message.includes('catalog_products') || message.includes('pdp_identity_listing')) &&
        message.includes('does not exist'))
    ) {
      return null;
    }
    logger.warn(
      {
        err: err?.message || String(err),
        merchant_id: normalizedMerchantId,
        product_id: normalizedProductId || null,
      },
      'Failed to resolve catalog identity for PDP product ref',
    );
    return null;
  }
}

// `canonicalRouteSigId` is the dedupe keeper (see
// applyRequestedPivotaSignatureToPdpProduct). It has to be honored HERE as
// well, not just in the shaper: this function runs again at the very end on
// pdpBuilder's projected payload product, and that projection does not carry
// `pivota_canonical_url` — so the `|| publicUrl` fallback below silently
// re-stamped the REQUESTED sig over the keeper. agent-ui reads
// pivota_canonical_url FIRST (lib/productHref.resolveProductRouteId), so the
// keeper being correct on `canonical_url` alone still renders a self-canonical
// page. Caught by tests/integration/get_pdp_v2_dedupe_keeper_canonical.
function applyCatalogIdentityToPdpProduct(product, identity = {}, canonicalRouteSigId = '', options = {}) {
  if (!product || typeof product !== 'object' || Array.isArray(product)) return product;
  const sigId = firstNonEmptyString(identity.pivota_signature_id, identity.signature_id);
  if (!isPivotaSignatureProductId(sigId)) return product;
  const sourceProductId = firstNonEmptyString(
    product.source_product_id,
    identity.source_product_id,
    product.platform_product_id,
    product.product_id,
    product.id,
  );
  const productKey = firstNonEmptyString(product.product_key, identity.product_key);
  const catalogCategoryPath = firstNonEmptyString(identity.category_path);
  const identityCanonicalEntityId = firstNonEmptyString(identity.canonical_entity_id);
  const shouldEmitCanonicalEntityId =
    CANONICAL_ENTITY_ID_PUBLIC_EMIT_ENABLED && Boolean(identityCanonicalEntityId);
  const publicId = resolvePublicProductIdForEmit(sigId, identityCanonicalEntityId);
  const publicUrl = buildPublicProductUrl(publicId);
  // Same precedence rule as the shaper: the canonical_entity_id flag already
  // publishes a stronger cross-row canonical, so the keeper never stacks on it.
  const normalizedKeeperSigId = String(canonicalRouteSigId || '').trim();
  const keeperCanonicalUrl =
    !shouldEmitCanonicalEntityId &&
    /^sig_[a-z0-9]+$/i.test(normalizedKeeperSigId) &&
    normalizedKeeperSigId !== publicId
      ? buildPublicProductUrl(normalizedKeeperSigId)
      : '';
  const catalogCategoryParts = catalogCategoryPath
    ? catalogCategoryPath.split('/').map((part) => String(part || '').trim()).filter(Boolean)
    : [];
  const catalogCategoryPathLooksFormula =
    /^beauty\/(?:skincare|skin-care|makeup\/(?:face|lip|eye|cheek|complexion|base)|fragrance|hair|haircare|body)(?:\/|$)/i
      .test(catalogCategoryPath);
  return {
    ...product,
    ...(sourceProductId ? { source_product_id: sourceProductId } : {}),
    ...(productKey ? { product_key: productKey } : {}),
    ...(catalogCategoryPath ? { catalog_category_path: catalogCategoryPath } : {}),
    ...(catalogCategoryParts.length ? { category_path: catalogCategoryParts } : {}),
    ...(identity.category && !firstNonEmptyString(product.category)
      ? { category: identity.category }
      : {}),
    ...(identity.product_type && !firstNonEmptyString(product.product_type)
      ? { product_type: identity.product_type }
      : {}),
    ...(catalogCategoryPathLooksFormula ? { pdp_schema_profile: 'beauty_formula' } : {}),
    ...(identity.category_label_source ? { category_label_source: identity.category_label_source } : {}),
    ...(identity.category_confidence !== undefined ? { category_confidence: identity.category_confidence } : {}),
    ...(identity.product_line_id ? { product_line_id: identity.product_line_id } : {}),
    ...(identity.review_family_id ? { review_family_id: identity.review_family_id } : {}),
    // Migration 186 aggregateRating. Emitted only with a positive review count
    // behind it (never invented; NULL at the source means "no review data",
    // not zero stars), never over an existing product.rating, and suppressed
    // by the caller when the rendered reviews module already shows a real
    // rating — JSON-LD must never disagree with the visible page.
    // rating/rating_count are the exact keys the UI's aggregateRating
    // resolver reads.
    ...(!options.suppressRatingStamp &&
    Number.isFinite(identity.catalog_rating_value) &&
    Number.isFinite(identity.catalog_rating_count) &&
    identity.catalog_rating_count > 0 &&
    !Number.isFinite(Number(product.rating))
      ? {
          rating: Math.round(identity.catalog_rating_value * 100) / 100,
          rating_count: identity.catalog_rating_count,
        }
      : {}),
    ...(identity.sellable_item_group_id
      ? {
          sellable_item_group_id: identity.sellable_item_group_id,
          product_group_id: product.product_group_id || identity.product_group_id || identity.sellable_item_group_id,
        }
      : {}),
    pivota_signature_id: product.pivota_signature_id || sigId,
    signature_id: product.signature_id || sigId,
    pivota_canonical_url: shouldEmitCanonicalEntityId
      ? publicUrl
      : keeperCanonicalUrl || product.pivota_canonical_url || publicUrl,
    ...(keeperCanonicalUrl
      ? {
          canonical_url: keeperCanonicalUrl,
          canonical_route_sig_id: normalizedKeeperSigId,
          canonical_route_basis: 'dedupe_keeper',
        }
      : {}),
  };
}

function collectCatalogPdpContentSourceProductIds(product = {}, productRef = {}, extraCandidates = []) {
  const refs = [
    productRef,
    product?.canonical_content_ref,
    product?.canonicalContentRef,
    product?.selected_commerce_ref,
    product?.selectedCommerceRef,
    product?.canonical_product_ref,
    product?.canonicalProductRef,
    product?.content_base_ref,
    product?.contentBaseRef,
    product?.canonical_payload_product_ref,
    product?.canonicalPayloadProductRef,
    product?.pdp_open?.product_ref,
    product?.pdp_open?.get_pdp_v2_payload?.product_ref,
  ].filter(isPlainObject);
  for (const candidate of Array.isArray(extraCandidates) ? extraCandidates : [extraCandidates]) {
    if (isPlainObject(candidate)) refs.push(candidate);
  }
  const normalizeContentSourceId = (value) => {
    const text = String(value || '').trim();
    if (!text || isPivotaSignatureProductId(text)) return '';
    if (isExternalSeedProductId(text)) return text;
    const externalSeedRefMatch = text.match(/(?:^|[^a-z0-9])((?:ext|eps)_[a-z0-9_]+)(?:$|[^a-z0-9_])/i);
    if (externalSeedRefMatch?.[1] && isExternalSeedProductId(externalSeedRefMatch[1])) {
      return externalSeedRefMatch[1];
    }
    const productKeyMatch = text
      .split('::')
      .map((part) => part.trim())
      .find((part) => isExternalSeedProductId(part));
    return productKeyMatch || text;
  };
  const values = [
    ...refs.flatMap((ref) => [
      ref.product_id,
      ref.productId,
      ref.source_product_id,
      ref.sourceProductId,
      ref.external_product_id,
      ref.externalProductId,
      ref.external_seed_external_product_id,
      ref.externalSeedExternalProductId,
      ref.external_seed_product_id,
      ref.externalSeedProductId,
      ref.platform_product_id,
      ref.platformProductId,
      ref.product_key,
      ref.productKey,
      ref.source_listing_ref,
      ref.sourceListingRef,
    ]),
    ...(Array.isArray(extraCandidates) ? extraCandidates : [extraCandidates])
      .filter((value) => typeof value === 'string')
      .map((value) => value.trim()),
    product?.source_product_id,
    product?.sourceProductId,
    product?.product_key,
    product?.productKey,
    product?.source_listing_ref,
    product?.sourceListingRef,
    product?.platform_product_id,
    product?.platformProductId,
    product?.external_product_id,
    product?.externalProductId,
    product?.external_seed_external_product_id,
    product?.externalSeedExternalProductId,
    product?.external_seed_product_id,
    product?.externalSeedProductId,
    product?.external_seed_id,
    product?.externalSeedId,
    product?.product_id,
    product?.productId,
    product?.id,
  ];
  return Array.from(
    new Set(
      values
        .map(normalizeContentSourceId)
        .filter((value) => value && !isPivotaSignatureProductId(value)),
    ),
  ).slice(0, 20);
}

const PDP_MODULE_HEALTH_RANK = {
  ok: 0,
  info: 1,
  warning: 2,
  degraded: 3,
};

const PDP_CORE_DEGRADED_MODULE_TYPES = new Set([
  'canonical',
  'offers',
]);

const PDP_INFO_MISSING_REASONS = new Set([
  'deferred',
  'no_results',
]);

function classifyPdpV2ModuleHealth(missing = [], modules = []) {
  const moduleByType = new Map();
  for (const module of Array.isArray(modules) ? modules : []) {
    const type = String(module?.type || '').trim();
    if (type) moduleByType.set(type, module);
  }

  const items = (Array.isArray(missing) ? missing : []).map((item) => {
    const type = String(item?.type || 'unknown').trim() || 'unknown';
    const reason = String(item?.reason || 'unavailable').trim() || 'unavailable';
    const normalizedReason = reason.toLowerCase();
    const module = moduleByType.get(type);
    const required = module?.required === true || item?.required === true;
    const severity =
      required || PDP_CORE_DEGRADED_MODULE_TYPES.has(type)
        ? 'degraded'
        : PDP_INFO_MISSING_REASONS.has(normalizedReason) ||
            normalizedReason.startsWith('not_applicable') ||
            normalizedReason.startsWith('product_family_')
          ? 'info'
          : 'warning';
    return {
      type,
      reason,
      required,
      severity,
    };
  });

  const severity = items.reduce((current, item) => {
    return PDP_MODULE_HEALTH_RANK[item.severity] > PDP_MODULE_HEALTH_RANK[current]
      ? item.severity
      : current;
  }, 'ok');

  return {
    severity,
    applied: severity === 'degraded',
    items,
    degraded: items.filter((item) => item.severity === 'degraded'),
    warnings: items.filter((item) => item.severity === 'warning'),
    info: items.filter((item) => item.severity === 'info'),
  };
}

function hasExternalSeedRichPdpContent(product) {
  if (!isPlainObject(product)) return false;
  const seedData = isPlainObject(product.seed_data) ? product.seed_data : {};
  const snapshot = isPlainObject(seedData.snapshot) ? seedData.snapshot : {};
  const ingredientIntel =
    isPlainObject(product.ingredient_intel) ? product.ingredient_intel
      : isPlainObject(seedData.ingredient_intel) ? seedData.ingredient_intel
        : isPlainObject(snapshot.ingredient_intel) ? snapshot.ingredient_intel
          : {};
  const forceFillContract =
    isPlainObject(ingredientIntel.force_fill_contract) ? ingredientIntel.force_fill_contract
      : isPlainObject(ingredientIntel.forceFillContract) ? ingredientIntel.forceFillContract
        : null;
  const variantSources = [product.variants, seedData.variants, snapshot.variants];
  const hasVariantSignal = variantSources.some((variants) => Array.isArray(variants) && variants.length > 0);
  const hasIngredientSignal = Boolean(
    firstNonEmptyString(
      product.pdp_ingredients_raw,
      product.raw_ingredient_text_clean,
      seedData.pdp_ingredients_raw,
      seedData.raw_ingredient_text_clean,
      snapshot.pdp_ingredients_raw,
      snapshot.raw_ingredient_text_clean,
    ) ||
      (Array.isArray(product.ingredients_inci) && product.ingredients_inci.length > 0) ||
      (Array.isArray(seedData.ingredients_inci) && seedData.ingredients_inci.length > 0) ||
      (Array.isArray(snapshot.ingredients_inci) && snapshot.ingredients_inci.length > 0) ||
      forceFillContract?.contract_version === 'pivota.pdp.force_fill.v1'
  );
  const hasHowToSignal = Boolean(
    firstNonEmptyString(
      product.pdp_how_to_use_raw,
      seedData.pdp_how_to_use_raw,
      snapshot.pdp_how_to_use_raw,
    )
  );
  const hasDetailsSignal = [product.pdp_details_sections, seedData.pdp_details_sections, snapshot.pdp_details_sections]
    .some((sections) => Array.isArray(sections) && sections.length > 0);
  return hasVariantSignal || hasIngredientSignal || hasHowToSignal || hasDetailsSignal;
}

function shouldHydratePdpIdentityLineMemberPayloads({
  entryProductIsExternalSeed = false,
  entryProductId = '',
  productId = '',
  canonicalProductRef = null,
  requestedMerchantId = '',
} = {}) {
  if (
    isRequestedExternalSeedAliasDifferentFromCanonical({
      entryProductIsExternalSeed,
      entryProductId,
      productId,
      canonicalProductRef,
    })
  ) {
    return true;
  }
  return !(
    isExternalSeedListingMerchantId(canonicalProductRef?.merchant_id) &&
    isExternalSeedProductId(canonicalProductRef?.product_id) &&
    (!requestedMerchantId || isExternalSeedListingMerchantId(requestedMerchantId))
  );
}

function isRequestedExternalSeedAliasDifferentFromCanonical({
  entryProductIsExternalSeed = false,
  entryProductId = '',
  productId = '',
  canonicalProductRef = null,
} = {}) {
  const requestedExternalSeedEntryProductId = String(entryProductId || productId || '').trim();
  const canonicalExternalSeedProductId = String(canonicalProductRef?.product_id || '').trim();
  return Boolean(
    entryProductIsExternalSeed &&
      requestedExternalSeedEntryProductId &&
      canonicalExternalSeedProductId &&
      requestedExternalSeedEntryProductId !== canonicalExternalSeedProductId,
  );
}

function readExternalSeedRichVariants(product) {
  if (!isPlainObject(product)) return [];
  const seedData = isPlainObject(product.seed_data) ? product.seed_data : {};
  const snapshot = isPlainObject(seedData.snapshot) ? seedData.snapshot : {};
  for (const variants of [product.variants, seedData.variants, snapshot.variants]) {
    if (Array.isArray(variants) && variants.length > 0) return variants;
  }
  return [];
}

function normalizeVariantSpecText(value) {
  if (typeof value === 'number' && Number.isFinite(value)) return String(value);
  if (isPlainObject(value)) {
    for (const key of ['value', 'label', 'title', 'name', 'text', 'display_label', 'displayLabel', 'option_value', 'optionValue']) {
      const normalized = normalizeVariantSpecText(value[key]);
      if (normalized) return normalized;
    }
    return '';
  }
  if (typeof value !== 'string') return '';
  const normalized = value.replace(/\s+/g, ' ').trim();
  if (!normalized || /^\[object Object\]$/i.test(normalized)) return '';
  if (/^(default|default title|variant \d+|single item|one size)$/i.test(normalized)) return '';
  return normalized;
}

function collectVariantSpecTexts(variant) {
  if (!isPlainObject(variant)) return [];
  const out = [];
  const push = (value) => {
    const normalized = normalizeVariantSpecText(value);
    if (normalized) out.push(normalized);
  };
  push(variant.display_label || variant.displayLabel);
  push(variant.title || variant.name);
  push(variant.option_value || variant.optionValue);
  const optionSources = [variant.options, variant.selected_options, variant.selectedOptions];
  for (const raw of optionSources) {
    if (Array.isArray(raw)) {
      for (const option of raw) {
        if (!isPlainObject(option)) continue;
        push(option.value || option.label || option.text);
      }
    } else if (isPlainObject(raw)) {
      Object.values(raw).forEach(push);
    }
  }
  return Array.from(new Set(out));
}

function variantSpecScore(variant) {
  const texts = collectVariantSpecTexts(variant);
  return texts.reduce((score, text) => {
    let next = score + text.length;
    if (/\d+\s*(?:pads?|sheets?|pcs?|pieces?|count|ct)\b/i.test(text)) next += 20;
    if (/\d+\s*(?:m\s*l|ml|fl\.?\s*oz|oz|g|kg)\b/i.test(text)) next += 10;
    return next;
  }, 0);
}

function isHighQualityVariantSpec(variant) {
  const status = firstNonEmptyString(variant?.source_quality_status, variant?.sourceQualityStatus)
    ?.trim()
    .toLowerCase();
  return ['high', 'reviewed', 'manual_reviewed', 'official_authoritative', 'official', 'source_backed'].includes(status);
}

function shouldUseRichExternalSeedVariantSpec(targetVariant, richVariant) {
  if (!isPlainObject(richVariant)) return false;
  const richScore = variantSpecScore(richVariant);
  if (richScore <= 0) return false;
  const targetScore = variantSpecScore(targetVariant);
  return isHighQualityVariantSpec(richVariant) || richScore > targetScore;
}

function mergeRichExternalSeedVariantSpecFields(targetVariant, richVariant) {
  if (!shouldUseRichExternalSeedVariantSpec(targetVariant, richVariant)) return targetVariant;
  const next = { ...targetVariant };
  for (const key of [
    'title',
    'options',
    'selected_options',
    'selectedOptions',
    'option1',
    'option2',
    'option3',
    'option_name',
    'optionName',
    'option_value',
    'optionValue',
    'display_label',
    'displayLabel',
    'axis_kind',
    'axisKind',
    'source_quality_status',
    'sourceQualityStatus',
  ]) {
    if (richVariant[key] != null) next[key] = richVariant[key];
  }
  return next;
}

function mergeRichExternalSeedVariantSpecs(targetVariants, richVariants) {
  if (!Array.isArray(richVariants) || richVariants.length === 0) return targetVariants;
  if (!Array.isArray(targetVariants) || targetVariants.length === 0) return richVariants;

  const richByKey = new Map();
  richVariants.forEach((variant) => {
    if (!isPlainObject(variant)) return;
    getVariantEvidenceKeys(variant).forEach((key) => {
      if (!richByKey.has(key)) richByKey.set(key, variant);
    });
  });
  if (!richByKey.size && targetVariants.length === 1 && richVariants.length === 1) {
    return [mergeRichExternalSeedVariantSpecFields(targetVariants[0], richVariants[0])];
  }
  return targetVariants.map((variant) => {
    if (!isPlainObject(variant)) return variant;
    const richVariant = getVariantEvidenceKeys(variant)
      .map((key) => richByKey.get(key))
      .find(Boolean);
    return richVariant ? mergeRichExternalSeedVariantSpecFields(variant, richVariant) : variant;
  });
}

function mergeIdentitySyntheticWithRichExternalSeedProduct(syntheticProduct, richProduct) {
  if (!isPlainObject(syntheticProduct) || !hasExternalSeedRichPdpContent(richProduct)) {
    return syntheticProduct;
  }
  const identityFields = {};
  for (const key of [
    'selected_commerce_ref',
    'canonical_content_ref',
    'pdp_content_source',
    'product_line_id',
    'sellable_item_group_id',
    'review_family_id',
    'identity_confidence',
    'match_basis',
    'canonical_scope',
    'content_review_state',
  ]) {
    if (syntheticProduct[key] != null) identityFields[key] = syntheticProduct[key];
  }
  const richVariants = readExternalSeedRichVariants(richProduct);
  const mergedVariants = mergeRichExternalSeedVariantSpecs(syntheticProduct.variants, richVariants);
  return {
    ...syntheticProduct,
    ...richProduct,
    ...(Array.isArray(mergedVariants) && mergedVariants.length > 0 ? { variants: mergedVariants } : {}),
    ...identityFields,
  };
}

function mergeExternalSeedAliasPdpContent(product, aliasProduct) {
  if (!isPlainObject(product) || !hasExternalSeedRichPdpContent(aliasProduct)) return product;
  const identityFields = {};
  for (const key of [
    'merchant_id',
    'product_id',
    'id',
    'platform',
    'platform_product_id',
    'source_product_id',
    'product_key',
    'product_ref',
    'canonical_product_ref',
    'canonical_content_ref',
    'selected_commerce_ref',
    'pdp_content_source',
    'product_line_id',
    'sellable_item_group_id',
    'product_group_id',
    'review_family_id',
    'identity_confidence',
    'match_basis',
    'canonical_scope',
    'content_review_state',
    'pivota_signature_id',
    'signature_id',
    'pivota_canonical_url',
  ]) {
    if (product[key] != null) identityFields[key] = product[key];
  }
  return {
    ...mergeIdentitySyntheticWithRichExternalSeedProduct(product, aliasProduct),
    ...identityFields,
  };
}

async function fetchExternalSeedRouteStatusFromDb(args) {
  if (!process.env.DATABASE_URL) return null;
  const productId = String(args?.productId || '').trim();
  if (!productId) return null;

  const selectSql = `
    SELECT
      id,
      external_product_id,
      status,
      updated_at,
      created_at
    FROM external_product_seeds
    WHERE %%MATCH_CLAUSE%%
    ORDER BY
      CASE WHEN status = 'active' THEN 0 ELSE 1 END,
      updated_at DESC NULLS LAST,
      created_at DESC NULLS LAST
    LIMIT 1
  `;

  try {
    let row = null;
    const matchClauses = [
      'external_product_id = $1',
      'id::text = $1',
      `(
        seed_data->>'external_product_id' = $1
        OR seed_data->>'product_id' = $1
        OR seed_data->'snapshot'->>'product_id' = $1
      )`,
    ];

    for (const matchClause of matchClauses) {
      const res = await query(
        selectSql.replace('%%MATCH_CLAUSE%%', matchClause),
        [productId],
      );
      row = Array.isArray(res?.rows) ? res.rows[0] : null;
      if (row) break;
    }

    if (!row) return null;
    return {
      external_seed_id: row.id ? String(row.id) : null,
      external_product_id: row.external_product_id ? String(row.external_product_id) : null,
      status: String(row.status || '').trim().toLowerCase() || null,
      updated_at: row.updated_at || null,
      created_at: row.created_at || null,
    };
  } catch (err) {
    const message = String(err?.message || err || '');
    if (
      err?.code === 'NO_DATABASE' ||
      (message.includes('external_product_seeds') && message.includes('does not exist'))
    ) {
      return null;
    }
    logger.warn(
      { err: err?.message || String(err), productId },
      'Failed to read external seed route status from DB',
    );
    return null;
  }
}

function normalizePdpServingMode(value) {
  return String(value || '').trim().toLowerCase().replace(/[\s-]+/g, '_');
}

function isTruthyPdpOption(value) {
  if (value === true) return true;
  const normalized = String(value || '').trim().toLowerCase();
  return normalized === 'true' || normalized === '1' || normalized === 'yes';
}

function isPdpIneligibleBypassAllowed() {
  return process.env.NODE_ENV === 'test';
}

function shouldRequirePdpServingEligible(payload, options) {
  const servingMode = normalizePdpServingMode(
    options?.serving_mode ||
      options?.servingMode ||
      payload?.serving_mode ||
      payload?.servingMode ||
      payload?.metadata?.serving_mode ||
      payload?.metadata?.servingMode,
  );
  const requestedAllowIneligible =
    servingMode === 'permissive' ||
    servingMode === 'db_serving' ||
    isTruthyPdpOption(options?.allow_ineligible) ||
    isTruthyPdpOption(options?.allowIneligible) ||
    isTruthyPdpOption(payload?.allow_ineligible) ||
    isTruthyPdpOption(payload?.allowIneligible) ||
    isTruthyPdpOption(payload?.metadata?.allow_ineligible) ||
    isTruthyPdpOption(payload?.metadata?.allowIneligible);
  const allowIneligible = requestedAllowIneligible && isPdpIneligibleBypassAllowed();
  if (allowIneligible) return false;
  if (
    servingMode === 'serving_eligible_only' ||
    isTruthyPdpOption(options?.serving_eligible_only) ||
    isTruthyPdpOption(options?.servingEligibleOnly) ||
    isTruthyPdpOption(payload?.serving_eligible_only) ||
    isTruthyPdpOption(payload?.servingEligibleOnly)
  ) {
    return true;
  }
  return true;
}

function normalizePdpServingEligibilityRow(row) {
  if (!row || typeof row !== 'object') return null;
  const blockerCode = firstNonEmptyString(row.blocker_code) || null;
  const hasActiveExternalSeedSourceMatch = row.active_external_seed_source_match === true;
  const syncStatus = firstNonEmptyString(row.sync_status) || null;
  const contentQualityScore = Number.isFinite(Number(row.content_quality_score))
    ? Number(row.content_quality_score)
    : null;
  return {
    catalog_row_found: true,
    content_key: firstNonEmptyString(row.content_key) || null,
    product_key: firstNonEmptyString(row.product_key) || null,
    pivota_signature_id: firstNonEmptyString(row.pivota_signature_id) || null,
    sync_status: syncStatus,
    pdp_lifecycle_stage: firstNonEmptyString(row.pdp_lifecycle_stage) || null,
    serving_eligible: row.serving_eligible === true,
    readiness_tier: firstNonEmptyString(row.readiness_tier) || null,
    index_row_found: row.serving_eligible !== null && row.serving_eligible !== undefined,
    pipeline_stage: firstNonEmptyString(row.pipeline_stage) || null,
    blocker_code: blockerCode,
    blocker_detail: firstNonEmptyString(row.blocker_detail) || null,
    content_quality_score: contentQualityScore,
    active_external_seed_source_match: hasActiveExternalSeedSourceMatch,
    eligibility_override_reason: null,
  };
}

// A catalog row that exists but fails activeCatalogProductSourceWhere — a
// test-merchant rig (testMerchantPolicy) or a retired/inactive source — is a
// deliberately excluded row, not a read failure. It must surface as the SETTLED
// refusal shape: index_row_found: true, serving_eligible: false. agent-ui's
// classifyPdpFetchFailure (pdpServerPage.tsx) keys its 404-vs-500 decision on
// exactly that pair, so this is what lets a retired product's public PDP URL
// settle to a cacheable 404 instead of a permanent 500. The fail-closed
// { reason: 'serving_eligibility_missing' } flavor (NO index_row_found key) is
// reserved for genuinely-missing rows and DB errors, which must stay on the
// transient side — one Postgres hiccup must not 404-and-cache the catalog.
function buildExcludedCatalogSourcePdpServingEligibility(row) {
  if (!row || typeof row !== 'object') return null;
  const isTestMerchantExcluded = row.not_test_merchant === false;
  const merchantStatus = String(row.merchant_status || '').trim().toLowerCase();
  const causes = [];
  if (isTestMerchantExcluded) causes.push('test_merchant_policy');
  if (merchantStatus && merchantStatus !== 'active' && merchantStatus !== 'observed') {
    causes.push(`merchant_status=${merchantStatus}`);
  }
  if (row.merchant_has_stores === true && row.merchant_has_active_platform_store !== true) {
    causes.push('no_active_platform_store');
  }
  // No cause we can name means we cannot confirm the exclusion was deliberate:
  // either the row became active between the primary read and this probe, or
  // activeCatalogProductSourceWhere gained a leg these checks don't mirror yet.
  // Both must fail TRANSIENT (null → the missing flavor), never settled — a
  // false settled refusal 404s a servable product and gets cached.
  if (causes.length === 0) return null;
  return {
    catalog_row_found: true,
    content_key: firstNonEmptyString(row.content_key) || null,
    product_key: firstNonEmptyString(row.product_key) || null,
    pivota_signature_id: firstNonEmptyString(row.pivota_signature_id) || null,
    sync_status: firstNonEmptyString(row.sync_status) || null,
    pdp_lifecycle_stage: firstNonEmptyString(row.pdp_lifecycle_stage) || null,
    serving_eligible: false,
    readiness_tier: null,
    index_row_found: true,
    pipeline_stage: null,
    blocker_code: isTestMerchantExcluded ? 'test_merchant_excluded' : 'catalog_source_excluded',
    blocker_detail: `catalog row exists but its source is excluded from active serving (${causes.join('; ')})`,
    content_quality_score: null,
    active_external_seed_source_match: false,
    eligibility_override_reason: null,
  };
}

function buildPrefetchedPdpServingEligibilityFromSignatureRef(signatureProductRef) {
  if (!signatureProductRef || typeof signatureProductRef !== 'object') return null;
  if (signatureProductRef.serving_eligibility_prefetched !== true) return null;
  return normalizePdpServingEligibilityRow({
    content_key: signatureProductRef.content_key,
    product_key: signatureProductRef.product_key,
    pivota_signature_id: firstNonEmptyString(
      signatureProductRef.requested_pivota_signature_id,
      signatureProductRef.pivota_signature_id,
      signatureProductRef.catalog_pivota_signature_id,
    ),
    sync_status: signatureProductRef.sync_status,
    pdp_lifecycle_stage: signatureProductRef.pdp_lifecycle_stage,
    serving_eligible: signatureProductRef.signature_serving_eligible,
    readiness_tier: firstNonEmptyString(
      signatureProductRef.signature_readiness_tier,
      signatureProductRef.readiness_tier,
    ),
    pipeline_stage: signatureProductRef.signature_pipeline_stage,
    blocker_code: signatureProductRef.signature_blocker_code,
    blocker_detail: signatureProductRef.signature_blocker_detail,
    content_quality_score: signatureProductRef.signature_content_quality_score,
    active_external_seed_source_match:
      String(signatureProductRef.external_seed_status || '').trim().toLowerCase() === 'active',
  });
}

function signatureRefHasUsableCatalogDetailContent(signatureProductRef) {
  if (!signatureProductRef || typeof signatureProductRef !== 'object') return false;
  const payload = parseCanonicalCatalogPayload(signatureProductRef.product_payload);
  const seedData = isPlainObject(payload.seed_data) ? payload.seed_data : {};
  const snapshot = isPlainObject(seedData.snapshot) ? seedData.snapshot : {};
  const externalSeed = isPlainObject(payload.external_seed) ? payload.external_seed : {};
  const externalSnapshot = isPlainObject(externalSeed.snapshot) ? externalSeed.snapshot : {};
  const hasTitle = Boolean(firstNonEmptyString(
    signatureProductRef.title,
    payload.title,
    seedData.title,
    snapshot.title,
    externalSeed.title,
    externalSnapshot.title,
  ));
  const hasSourceUrl = Boolean(firstNonEmptyString(
    signatureProductRef.canonical_url,
    payload.canonical_url,
    payload.destination_url,
    seedData.canonical_url,
    seedData.destination_url,
    snapshot.canonical_url,
    snapshot.destination_url,
    externalSeed.canonical_url,
    externalSeed.destination_url,
    externalSnapshot.canonical_url,
    externalSnapshot.destination_url,
  ));
  const hasVisualOrContent = Boolean(
    firstCatalogPayloadString(
      signatureProductRef.image_url,
      payload.image_url,
      payload.image_urls,
      payload.images,
      seedData.image_url,
      seedData.image_urls,
      seedData.images,
      snapshot.image_url,
      snapshot.image_urls,
      snapshot.images,
      externalSeed.image_url,
      externalSeed.image_urls,
      externalSeed.images,
      externalSnapshot.image_url,
      externalSnapshot.image_urls,
      externalSnapshot.images,
    ) ||
      firstNonEmptyString(
        signatureProductRef.description,
        payload.description,
        payload.pdp_description_raw,
        seedData.description,
        seedData.pdp_description_raw,
        snapshot.description,
        snapshot.pdp_description_raw,
        externalSeed.description,
        externalSeed.pdp_description_raw,
        externalSnapshot.description,
        externalSnapshot.pdp_description_raw,
      ) ||
      [seedData.variants, snapshot.variants, externalSeed.variants, externalSnapshot.variants]
        .some((variants) => Array.isArray(variants) && variants.length > 0)
  );
  return hasTitle && (hasSourceUrl || hasVisualOrContent);
}

async function buildExternalSeedProductFromSignatureCatalogRef(signatureProductRef) {
  if (!signatureProductRef || typeof signatureProductRef !== 'object') return null;
  if (signatureProductRef.source !== 'catalog_products_signature_exact') return null;
  const merchantId = firstNonEmptyString(signatureProductRef.merchant_id);
  const externalProductId = firstNonEmptyString(signatureProductRef.product_id);
  if (merchantId !== EXTERNAL_SEED_MERCHANT_ID || !isExternalSeedProductId(externalProductId)) {
    return null;
  }
  if (!signatureRefHasUsableCatalogDetailContent(signatureProductRef)) return null;

  const payload = parseCanonicalCatalogPayload(signatureProductRef.product_payload);
  const payloadSeedData = isPlainObject(payload.seed_data) ? payload.seed_data : {};
  const payloadSnapshot = isPlainObject(payloadSeedData.snapshot) ? payloadSeedData.snapshot : {};
  const externalSeed = isPlainObject(payload.external_seed) ? payload.external_seed : {};
  const externalSnapshot = isPlainObject(externalSeed.snapshot) ? externalSeed.snapshot : {};
  const title = firstNonEmptyString(
    signatureProductRef.title,
    payload.title,
    payloadSeedData.title,
    payloadSnapshot.title,
    externalSeed.title,
    externalSnapshot.title,
  );
  const brand = firstNonEmptyString(
    signatureProductRef.brand,
    payload.brand,
    payload.vendor,
    payloadSeedData.brand,
    payloadSeedData.vendor,
    payloadSnapshot.brand,
    payloadSnapshot.vendor,
    externalSeed.brand,
    externalSeed.vendor,
    externalSnapshot.brand,
    externalSnapshot.vendor,
  );
  const canonicalUrl = firstNonEmptyString(
    signatureProductRef.canonical_url,
    payload.canonical_url,
    payload.destination_url,
    payloadSeedData.canonical_url,
    payloadSeedData.destination_url,
    payloadSnapshot.canonical_url,
    payloadSnapshot.destination_url,
    externalSeed.canonical_url,
    externalSeed.destination_url,
    externalSnapshot.canonical_url,
    externalSnapshot.destination_url,
  );
  const imageUrl = firstCatalogPayloadString(
    signatureProductRef.image_url,
    payload.image_url,
    payload.image_urls,
    payload.images,
    payloadSeedData.image_url,
    payloadSeedData.image_urls,
    payloadSeedData.images,
    payloadSnapshot.image_url,
    payloadSnapshot.image_urls,
    payloadSnapshot.images,
    externalSeed.image_url,
    externalSeed.image_urls,
    externalSeed.images,
    externalSnapshot.image_url,
    externalSnapshot.image_urls,
    externalSnapshot.images,
  );
  const description = firstNonEmptyString(
    signatureProductRef.description,
    payload.description,
    payload.pdp_description_raw,
    payloadSeedData.description,
    payloadSeedData.pdp_description_raw,
    payloadSnapshot.description,
    payloadSnapshot.pdp_description_raw,
    externalSeed.description,
    externalSeed.pdp_description_raw,
    externalSnapshot.description,
    externalSnapshot.pdp_description_raw,
  );
  const category = firstNonEmptyString(
    signatureProductRef.category,
    signatureProductRef.product_type,
    payload.category,
    payload.product_type,
    payloadSeedData.category,
    payloadSeedData.product_type,
    payloadSnapshot.category,
    payloadSnapshot.product_type,
    externalSeed.category,
    externalSeed.product_type,
    externalSnapshot.category,
    externalSnapshot.product_type,
  );
  const categoryPath = firstCatalogPayloadString(
    signatureProductRef.category_path,
    payload.category_path,
    payload.catalog_category_path,
    payloadSeedData.category_path,
    payloadSeedData.catalog_category_path,
    payloadSnapshot.category_path,
    payloadSnapshot.catalog_category_path,
    externalSeed.category_path,
    externalSeed.catalog_category_path,
    externalSnapshot.category_path,
    externalSnapshot.catalog_category_path,
  );
  const reviewSummary = [
    payload.review_summary,
    payload.pdp_review_summary,
    payloadSeedData.review_summary,
    payloadSeedData.pdp_review_summary,
    payloadSnapshot.review_summary,
    payloadSnapshot.pdp_review_summary,
    externalSeed.review_summary,
    externalSeed.pdp_review_summary,
    externalSnapshot.review_summary,
    externalSnapshot.pdp_review_summary,
  ].find((value) => isPlainObject(value));
  const publicProductId = await resolvePublicExternalSeedProductId(externalProductId, {
    canonicalEntityId: firstNonEmptyString(signatureProductRef.canonical_entity_id),
  });
  const imageUrls = [
    imageUrl,
    ...(Array.isArray(payloadSeedData.image_urls) ? payloadSeedData.image_urls : []),
    ...(Array.isArray(payloadSnapshot.image_urls) ? payloadSnapshot.image_urls : []),
    ...(Array.isArray(externalSeed.image_urls) ? externalSeed.image_urls : []),
    ...(Array.isArray(externalSnapshot.image_urls) ? externalSnapshot.image_urls : []),
  ].filter(Boolean);
  const seedData = {
    ...payload,
    ...externalSeed,
    ...payloadSeedData,
    external_product_id: firstNonEmptyString(payloadSeedData.external_product_id, externalSeed.external_product_id, externalProductId),
    product_id: firstNonEmptyString(payloadSeedData.product_id, externalSeed.product_id, externalProductId),
    ...(title ? { title } : {}),
    ...(brand ? { brand } : {}),
    ...(description ? { description, pdp_description_raw: payloadSeedData.pdp_description_raw || description } : {}),
    ...(canonicalUrl ? { canonical_url: canonicalUrl, destination_url: canonicalUrl } : {}),
    ...(imageUrl ? { image_url: imageUrl } : {}),
    ...(imageUrls.length ? { image_urls: Array.from(new Set(imageUrls)) } : {}),
    ...(category ? { category, product_type: category } : {}),
    ...(categoryPath ? { category_path: categoryPath, catalog_category_path: categoryPath } : {}),
    ...(signatureProductRef.pivota_signature_id ? { pivota_signature_id: signatureProductRef.pivota_signature_id } : {}),
    ...(signatureProductRef.pivota_canonical_url ? { pivota_canonical_url: signatureProductRef.pivota_canonical_url } : {}),
    ...(reviewSummary ? { review_summary: reviewSummary, pdp_review_summary: reviewSummary } : {}),
    snapshot: {
      ...externalSnapshot,
      ...payloadSnapshot,
      product_id: externalProductId,
      external_product_id: externalProductId,
      ...(title ? { title } : {}),
      ...(brand ? { brand } : {}),
      ...(description ? { description, pdp_description_raw: payloadSnapshot.pdp_description_raw || description } : {}),
      ...(canonicalUrl ? { canonical_url: canonicalUrl, destination_url: canonicalUrl } : {}),
      ...(imageUrl ? { image_url: imageUrl } : {}),
      ...(imageUrls.length ? { image_urls: Array.from(new Set(imageUrls)) } : {}),
      ...(category ? { category, product_type: category } : {}),
      ...(categoryPath ? { category_path: categoryPath, catalog_category_path: categoryPath } : {}),
      ...(signatureProductRef.pivota_signature_id ? { pivota_signature_id: signatureProductRef.pivota_signature_id } : {}),
      ...(signatureProductRef.pivota_canonical_url ? { pivota_canonical_url: signatureProductRef.pivota_canonical_url } : {}),
      ...(reviewSummary ? { review_summary: reviewSummary, pdp_review_summary: reviewSummary } : {}),
    },
  };
  delete seedData.seed_data;
  delete seedData.external_seed;

  const row = {
    id: firstNonEmptyString(signatureProductRef.external_seed_id),
    external_product_id: externalProductId,
    status: firstNonEmptyString(signatureProductRef.external_seed_status, 'active'),
    canonical_url: canonicalUrl,
    destination_url: canonicalUrl,
    title,
    image_url: imageUrl,
    price_amount: firstCatalogPayloadMoney(
      payload.price_amount,
      payload.price,
      payloadSeedData.price_amount,
      payloadSeedData.price,
      payloadSnapshot.price_amount,
      payloadSnapshot.price,
      externalSeed.price_amount,
      externalSeed.price,
      externalSnapshot.price_amount,
      externalSnapshot.price,
    ),
    price_currency: firstNonEmptyString(
      payload.price_currency,
      payload.currency,
      payloadSeedData.price_currency,
      payloadSeedData.currency,
      payloadSnapshot.price_currency,
      payloadSnapshot.currency,
      externalSeed.price_currency,
      externalSeed.currency,
      externalSnapshot.price_currency,
      externalSnapshot.currency,
    ),
    availability: firstNonEmptyString(
      payload.availability,
      payloadSeedData.availability,
      payloadSnapshot.availability,
      externalSeed.availability,
      externalSnapshot.availability,
    ),
    attached_product_key: firstNonEmptyString(signatureProductRef.product_key),
    seed_data: seedData,
    updated_at: signatureProductRef.external_seed_updated_at || null,
    created_at: signatureProductRef.external_seed_created_at || null,
  };

  const product = buildExternalSeedProduct(row);
  if (!product) return null;
  if (
    CANONICAL_ENTITY_ID_PUBLIC_EMIT_ENABLED &&
    publicProductId &&
    publicProductId !== externalProductId
  ) {
    const publicUrl = buildPublicProductUrl(publicProductId);
    product.id = publicProductId;
    product.product_id = publicProductId;
    product.canonical_entity_id = publicProductId;
    product.pivota_canonical_url = publicUrl;
    product.canonical_url = publicUrl;
    product.url = publicUrl;
    if (canonicalUrl) product.merchant_canonical_url = canonicalUrl;
  }
  product.product_key = firstNonEmptyString(signatureProductRef.product_key) || product.product_key;
  product.content_key = firstNonEmptyString(signatureProductRef.content_key) || product.content_key;
  product.source_product_id = externalProductId;
  product.external_product_id = externalProductId;
  product.external_seed_product_id = externalProductId;
  // Electronics spec surface is FIRST-CLASS on the composed product (main
  // route — founder decision: no render-time fallback digging into seed_data).
  // This builder composes it exactly like buildExternalSeedProduct does, so
  // the signature route and the seed-detail route render identically.
  if (!product.electronics_meta) {
    const composedElectronicsMeta = pickElectronicsMeta(payloadSeedData.electronics_meta);
    if (composedElectronicsMeta) product.electronics_meta = composedElectronicsMeta;
  }
  product.pivota_signature_id = firstNonEmptyString(signatureProductRef.pivota_signature_id) || product.pivota_signature_id;
  product.signature_id = firstNonEmptyString(signatureProductRef.pivota_signature_id) || product.signature_id;
  if (categoryPath && !product.catalog_category_path) product.catalog_category_path = categoryPath;
  const contentFields = buildCatalogPdpContentFieldsFromRow({
    source_product_id: externalProductId,
    product_payload: signatureProductRef.product_payload,
  });
  if (contentFields) {
    mergeCatalogPdpContentFieldsIntoProduct(product, contentFields);
    if (product.catalog_pdp_content_hydration) {
      product.catalog_pdp_content_hydration = {
        ...product.catalog_pdp_content_hydration,
        source: 'catalog_signature_exact.product_payload',
        prefetched: true,
      };
    }
  }
  return attachProductDetailSource(
    normalizeProductDetailPrice(product),
    'catalog_signature_exact',
  );
}

function shouldAllowPublishedPdpMissingQualitySnapshot(servingEligibility) {
  if (!servingEligibility || typeof servingEligibility !== 'object') return false;
  if (servingEligibility.serving_eligible === true) return false;
  const blockerCode = String(servingEligibility.blocker_code || '').trim().toLowerCase();
  const blockerDetail = String(servingEligibility.blocker_detail || '').trim().toLowerCase();
  const syncStatus = String(servingEligibility.sync_status || '').trim().toLowerCase();
  const lifecycleStage = String(servingEligibility.pdp_lifecycle_stage || '').trim().toLowerCase();
  const qualityScore = Number(servingEligibility.content_quality_score);
  // ACCEPTS BOTH CODES ON PURPOSE. The backend used to file "never scored" and
  // "scored below the bar" under one `low_quality` code, distinguishing them
  // only in the detail prose; pivota-backend #1758 splits the never-scored case
  // out as `not_scored` so a mass unscoring stops impersonating a quality
  // verdict. This override targets EXACTLY the never-scored rows, so keying on
  // the old spelling alone would have turned that rename into a serving
  // regression: these published, seed-matched PDPs are served today via this
  // branch, and they would have gone hard-blocked — and then vanished from
  // browse, since the UI drops anything with serving_eligible !== true.
  // Keep both spellings until every backend deploy is past the split.
  const hasMissingQualitySnapshot =
    (blockerCode === 'low_quality' || blockerCode === 'not_scored') &&
    blockerDetail.includes('no quality snapshot found') &&
    (!Number.isFinite(qualityScore) || qualityScore <= 0);

  return Boolean(
    syncStatus === 'live' &&
      lifecycleStage === 'published' &&
      servingEligibility.active_external_seed_source_match === true &&
      hasMissingQualitySnapshot,
  );
}

async function fetchPdpServingEligibilityFromDb(args = {}) {
  if (!process.env.DATABASE_URL) return null;
  const contentKey = String(args.contentKey || '').trim();
  const pivotaSignatureId = String(args.pivotaSignatureId || '').trim();
  const merchantId = String(args.merchantId || '').trim();
  const productId = String(args.productId || '').trim();
  // Opt-in: only the serving-eligibility gate needs the settled-vs-missing
  // distinction the excluded-source probe provides. Every other caller reads
  // just readiness_tier / serving_eligible === true, for which the settled
  // refusal is behaviorally identical to null — running the probe there would
  // spend a DB round-trip per miss (including crawler garbage ids) for
  // nothing.
  const probeExcluded = args.probeExcluded === true;
  if (!contentKey && !pivotaSignatureId && (!merchantId || !productId)) return null;

  try {
    const result = await query(
      `
        SELECT
          cp.content_key,
          cp.product_key,
          cp.source_system,
          cp.source_product_id,
          cp.pivota_signature_id,
          cp.title AS catalog_title,
          cp.image_url AS catalog_image_url,
          cp.description AS catalog_description,
          COALESCE(
            cp.product_payload->>'external_seed_product_family',
            cp.product_payload->>'product_family',
            cp.product_payload->'external_seed_product_kind'->>'family',
            eps_active_seed.seed_data->>'product_kind',
            eps_active_seed.seed_data->'snapshot'->>'product_kind'
          ) AS external_seed_product_family,
          CASE
            WHEN jsonb_typeof(cp.product_payload->'image_urls') = 'array'
              THEN jsonb_array_length(cp.product_payload->'image_urls')
            WHEN jsonb_typeof(cp.product_payload->'images') = 'array'
              THEN jsonb_array_length(cp.product_payload->'images')
            ELSE 0
          END AS catalog_image_urls_count,
          cp.sync_status,
          cp.pdp_lifecycle_stage,
          ips.serving_eligible,
          ips.readiness_tier,
          ips.pipeline_stage,
          ips.blocker_code,
          ips.blocker_detail,
          ips.content_quality_score,
          eps_active_seed.external_product_id IS NOT NULL AS active_external_seed_source_match
        FROM catalog_products cp
        LEFT JOIN catalog_merchants cm ON cm.merchant_id = cp.merchant_id
        LEFT JOIN index_pipeline_state ips ON ips.content_key = cp.content_key
        LEFT JOIN external_product_seeds eps_active_seed
          ON cp.source_system = 'external_product_seeds_mirror_v1'
         AND eps_active_seed.status = 'active'
         AND eps_active_seed.external_product_id = cp.source_product_id
        WHERE (
          ($1::text <> '' AND cp.content_key = $1)
          OR ($4::text <> '' AND cp.pivota_signature_id = $4)
          OR (
            $2::text <> ''
            AND $3::text <> ''
            AND cp.merchant_id = $2
            AND cp.source_product_id = $3
          )
        )
          AND ${activeCatalogProductSourceWhere('cp', 'cm')}
        ORDER BY
          CASE WHEN $1::text <> '' AND cp.content_key = $1 THEN 0 ELSE 1 END,
          CASE WHEN $4::text <> '' AND cp.pivota_signature_id = $4 THEN 0 ELSE 1 END,
          CASE WHEN cp.source_system = 'external_product_seeds_mirror_v1' THEN 0 ELSE 1 END,
          cp.updated_at DESC NULLS LAST,
          cp.product_key ASC
        LIMIT 1
      `,
      [contentKey, merchantId, productId, pivotaSignatureId],
    );
    const row = Array.isArray(result?.rows) ? result.rows[0] : null;
    if (row) return normalizePdpServingEligibilityRow(row);
    if (!probeExcluded) return null;

    // The primary read filters through activeCatalogProductSourceWhere, so a
    // deliberately excluded source (test-merchant rig, retired merchant, dead
    // store) and a genuinely-missing row are both "no row" to it. Re-probe the
    // same identity WITHOUT the exclusion predicate: a hit means the row exists
    // and was excluded on purpose — emit the settled refusal so consumers can
    // 404 it (see buildExcludedCatalogSourcePdpServingEligibility). A miss (or
    // any error) still returns null, keeping the fail-closed missing flavor.
    const excludedResult = await query(
      `
        SELECT /* pdp_serving_eligibility_excluded_source_probe */
          cp.content_key,
          cp.product_key,
          cp.pivota_signature_id,
          cp.sync_status,
          cp.pdp_lifecycle_stage,
          ${notTestMerchantSql('cp', { hasSourceDomain: true })} AS not_test_merchant,
          lower(coalesce(cm.status, 'active')) AS merchant_status,
          EXISTS (
            SELECT 1
            FROM merchant_stores ms_any_probe
            WHERE ms_any_probe.merchant_id = cp.merchant_id
          ) AS merchant_has_stores,
          EXISTS (
            SELECT 1
            FROM merchant_stores ms_active_probe
            WHERE ms_active_probe.merchant_id = cp.merchant_id
              AND lower(coalesce(ms_active_probe.status, '')) = 'active'
              AND coalesce(nullif(trim(ms_active_probe.domain), ''), '') <> ''
              AND (
                ${catalogProductPlatformExpr('cp')} = ''
                OR lower(coalesce(ms_active_probe.platform, '')) = ${catalogProductPlatformExpr('cp')}
              )
          ) AS merchant_has_active_platform_store
        FROM catalog_products cp
        LEFT JOIN catalog_merchants cm ON cm.merchant_id = cp.merchant_id
        WHERE (
          ($1::text <> '' AND cp.content_key = $1)
          OR ($4::text <> '' AND cp.pivota_signature_id = $4)
          OR (
            $2::text <> ''
            AND $3::text <> ''
            AND cp.merchant_id = $2
            AND cp.source_product_id = $3
          )
        )
        ORDER BY
          CASE WHEN $1::text <> '' AND cp.content_key = $1 THEN 0 ELSE 1 END,
          CASE WHEN $4::text <> '' AND cp.pivota_signature_id = $4 THEN 0 ELSE 1 END,
          CASE WHEN cp.source_system = 'external_product_seeds_mirror_v1' THEN 0 ELSE 1 END,
          cp.updated_at DESC NULLS LAST,
          cp.product_key ASC
        LIMIT 1
      `,
      [contentKey, merchantId, productId, pivotaSignatureId],
    );
    const excludedRow = Array.isArray(excludedResult?.rows) ? excludedResult.rows[0] : null;
    return buildExcludedCatalogSourcePdpServingEligibility(excludedRow);
  } catch (err) {
    const message = String(err?.message || err || '');
    if (
      err?.code === 'NO_DATABASE' ||
      err?.code === '42P01' ||
      message.includes('index_pipeline_state') ||
      message.includes('external_product_seeds') ||
      message.includes('catalog_products')
    ) {
      return null;
    }
    logger.warn(
      {
        err: err?.message || String(err),
        content_key: contentKey || null,
        pivota_signature_id: pivotaSignatureId || null,
        merchant_id: merchantId || null,
        product_id: productId || null,
      },
      'Failed to fetch PDP serving eligibility',
    );
    return null;
  }
}

function shouldFailClosedForMissingPdpServingEligibility({
  requestedPivotaSignatureId = null,
  canonicalProductRef = null,
} = {}) {
  const merchantId = String(canonicalProductRef?.merchant_id || '').trim();
  const productId = String(canonicalProductRef?.product_id || '').trim();
  return Boolean(
    process.env.DATABASE_URL ||
      process.env.PGHOST ||
    requestedPivotaSignatureId ||
      merchantId === EXTERNAL_SEED_MERCHANT_ID ||
      isExternalSeedProductId(productId) ||
      isPivotaSignatureProductId(productId),
  );
}

function buildPdpServingEligibilityDetails(eligibility, fallbackReason = 'serving_eligibility_missing') {
  if (!eligibility) {
    return {
      reason: fallbackReason,
      serving_eligible: false,
    };
  }
  return {
    reason:
      eligibility.blocker_code ||
      (eligibility.index_row_found ? 'not_serving_eligible' : 'serving_eligibility_missing'),
    serving_eligible: eligibility.serving_eligible === true,
    index_row_found: eligibility.index_row_found === true,
    content_key: eligibility.content_key || null,
    pivota_signature_id: eligibility.pivota_signature_id || null,
    pipeline_stage: eligibility.pipeline_stage || null,
    blocker_code: eligibility.blocker_code || null,
    blocker_detail: eligibility.blocker_detail || null,
    content_quality_score: eligibility.content_quality_score,
    pdp_lifecycle_stage: eligibility.pdp_lifecycle_stage || null,
    sync_status: eligibility.sync_status || null,
    active_external_seed_source_match: eligibility.active_external_seed_source_match === true,
    eligibility_override_reason: eligibility.eligibility_override_reason || null,
  };
}

function attachProductDetailSource(product, detailSource) {
  if (!product || typeof product !== 'object') return product;
  const source = String(detailSource || '').trim();
  if (!source) return product;
  try {
    Object.defineProperty(product, '__detail_source', {
      value: source,
      enumerable: false,
      configurable: true,
      writable: true,
    });
  } catch {
    product.__detail_source = source;
  }
  return product;
}

// Attach in-memory cache metadata so downstream log/response builders can
// correlate user-visible staleness with cache age (e.g. for diagnosing a
// "this price looks wrong" report). Non-enumerable to avoid leaking into JSON
// payloads served to clients; consumers that want it must read it explicitly.
function attachProductDetailCacheMeta(product, { storedAtMs, ageMs } = {}) {
  if (!product || typeof product !== 'object') return product;
  const meta = {
    stored_at_ms: Number.isFinite(storedAtMs) ? storedAtMs : null,
    age_ms_at_read: Number.isFinite(ageMs) ? ageMs : null,
  };
  try {
    Object.defineProperty(product, '__detail_cache_meta', {
      value: meta,
      enumerable: false,
      configurable: true,
      writable: true,
    });
  } catch {
    product.__detail_cache_meta = meta;
  }
  return product;
}

function inferDetailSourceFromQuerySource(querySource) {
  const source = String(querySource || '').trim().toLowerCase();
  if (!source) return null;
  if (source === 'products_cache') return 'fresh_cache';
  if (source === 'products_cache_stale') return 'stale_cache';
  if (source === 'external_seed_db') return 'external_seed_db';
  if (source === 'upstream') return 'upstream';
  return null;
}

function getProductDetailSource(product) {
  if (!product || typeof product !== 'object') return null;
  const source = String(product.__detail_source || '').trim();
  return source || null;
}

const SAVINGS_PRESENTATION_FIELDS = [
  'payment_offer_evidence',
  'payment_offer_summary',
  'payment_offer_badges',
  'payment_pricing',
  // Promotions lane deleted (ADR-022): nothing generates the store_discount_*
  // keys any more. They stay in this shared field list because it serves two
  // roles: strip call sites remove the keys from allowlist-built offer
  // payloads (belt-and-braces — those payloads are constructed from scratch
  // and never carry them), and pick call sites COPY them forward, which is the
  // pinned PDP passthrough contract (pdp_builder_structured_modules,
  // get_pdp_v2_identity_graph) for upstream payloads that still send them.
  'store_discount_evidence',
  'store_discount_summary',
  'store_discount_badges',
  'discount_evidence',
  'promotion_lines',
];

function pickSavingsPresentationFields(source) {
  if (!source || typeof source !== 'object') return {};
  return SAVINGS_PRESENTATION_FIELDS.reduce((out, field) => {
    if (Object.prototype.hasOwnProperty.call(source, field) && source[field] !== undefined) {
      out[field] = source[field];
    }
    return out;
  }, {});
}

function hasSavingsPresentationFields(source) {
  return Object.values(pickSavingsPresentationFields(source)).some((value) => {
    if (value == null) return false;
    if (Array.isArray(value)) return value.length > 0;
    if (typeof value === 'object') return Object.keys(value).length > 0;
    return true;
  });
}

function stripSavingsPresentationFields(source) {
  if (!source || typeof source !== 'object') return source;
  const out = { ...source };
  SAVINGS_PRESENTATION_FIELDS.forEach((field) => {
    delete out[field];
  });
  if (Array.isArray(out.variants)) {
    out.variants = out.variants.map((variant) => {
      if (!variant || typeof variant !== 'object') return variant;
      const cleanVariant = { ...variant };
      SAVINGS_PRESENTATION_FIELDS.forEach((field) => {
        delete cleanVariant[field];
      });
      return cleanVariant;
    });
  }
  return out;
}

function projectExternalSeedOfferVariant(variant) {
  if (!variant || typeof variant !== 'object') return null;
  return stripSavingsPresentationFields({
    id: variant.id,
    variant_id: variant.variant_id || variant.variantId || variant.id,
    sku: variant.sku,
    sku_id: variant.sku_id || variant.skuId || variant.sku,
    title: variant.title || variant.name,
    options: variant.options || variant.selected_options || variant.selectedOptions,
    option1: variant.option1,
    option2: variant.option2,
    option3: variant.option3,
    price: variant.price ?? variant.pricing ?? variant.current_price,
    price_amount: variant.price_amount ?? variant.priceAmount,
    currency: variant.currency,
    in_stock: variant.in_stock,
    available: variant.available,
    available_quantity: variant.available_quantity,
    inventory_quantity: variant.inventory_quantity,
    image_url: variant.image_url || variant.imageUrl,
  });
}

function projectExternalSeedOfferPayload(payload, merchantId, productId) {
  const normalizedPayload = parseCanonicalCatalogPayload(payload);
  const seedData = isPlainObject(normalizedPayload.seed_data) ? normalizedPayload.seed_data : {};
  const snapshot = isPlainObject(seedData.snapshot) ? seedData.snapshot : {};
  const externalSeed = isPlainObject(normalizedPayload.external_seed) ? normalizedPayload.external_seed : {};
  const externalSnapshot = isPlainObject(externalSeed.snapshot) ? externalSeed.snapshot : {};
  const normalizedProductId =
    firstNonEmptyString(
      normalizedPayload.product_id,
      normalizedPayload.id,
      externalSeed.external_product_id,
      externalSeed.product_id,
      seedData.external_product_id,
      seedData.product_id,
      snapshot.product_id,
      productId,
    ) || productId;
  const commerceFacts =
    normalizedPayload.commerce_facts_v1 ||
    normalizedPayload.commerce_facts ||
    externalSeed.commerce_facts_v1 ||
    externalSeed.commerce_facts ||
    seedData.commerce_facts_v1 ||
    seedData.commerce_facts ||
    snapshot.commerce_facts_v1 ||
    null;
  const agentSafeCommerceFacts =
    normalizedPayload.agent_safe_commerce_facts ||
    externalSeed.agent_safe_commerce_facts ||
    seedData.agent_safe_commerce_facts ||
    (commerceFacts ? buildAgentSafeCommerceFacts(commerceFacts) : null);
  const variantsSource = Array.isArray(normalizedPayload.variants)
    ? normalizedPayload.variants
    : Array.isArray(externalSeed.variants)
      ? externalSeed.variants
      : Array.isArray(seedData.variants)
        ? seedData.variants
        : Array.isArray(snapshot.variants)
          ? snapshot.variants
          : Array.isArray(externalSnapshot.variants)
            ? externalSnapshot.variants
      : [];
  const variants = variantsSource.map(projectExternalSeedOfferVariant).filter(Boolean);
  return stripSavingsPresentationFields({
    merchant_id: merchantId,
    product_id: normalizedProductId,
    id:
      firstNonEmptyString(normalizedPayload.id, normalizedPayload.product_id, externalSeed.id, seedData.id, productId) ||
      productId,
    source: normalizedPayload.source || externalSeed.source || seedData.source || 'external_seed',
    source_kind:
      normalizedPayload.source_kind ||
      normalizedPayload.sourceKind ||
      externalSeed.source_kind ||
      externalSeed.sourceKind ||
      seedData.source_kind ||
      seedData.sourceKind ||
      'external_seed',
    external_product_id:
      firstNonEmptyString(
        normalizedPayload.external_product_id,
        normalizedPayload.externalProductId,
        externalSeed.external_product_id,
        seedData.external_product_id,
        productId,
      ) || productId,
    title: firstNonEmptyString(
      normalizedPayload.title,
      normalizedPayload.name,
      externalSeed.title,
      seedData.title,
      snapshot.title,
    ),
    brand: firstNonEmptyString(normalizedPayload.brand, normalizedPayload.vendor, externalSeed.brand, seedData.brand),
    vendor: firstNonEmptyString(normalizedPayload.vendor, externalSeed.vendor, seedData.vendor),
    merchant_name: firstNonEmptyString(
      normalizedPayload.merchant_name,
      normalizedPayload.merchantName,
      externalSeed.merchant_name,
      seedData.merchant_name,
    ),
    store_name: firstNonEmptyString(
      normalizedPayload.store_name,
      normalizedPayload.storeName,
      externalSeed.store_name,
      seedData.store_name,
    ),
    seller_name: firstNonEmptyString(
      normalizedPayload.seller_name,
      normalizedPayload.sellerName,
      externalSeed.seller_name,
      seedData.seller_name,
    ),
    price: firstCatalogPayloadMoney(
      normalizedPayload.price,
      normalizedPayload.price_amount,
      normalizedPayload.priceAmount,
      externalSeed.price,
      externalSeed.price_amount,
      externalSeed.priceAmount,
      seedData.price,
      seedData.price_amount,
      seedData.priceAmount,
      snapshot.price_amount,
      snapshot.price,
    ),
    currency: firstNonEmptyString(normalizedPayload.currency, externalSeed.currency, seedData.currency, seedData.price_currency),
    shipping: normalizedPayload.shipping || externalSeed.shipping || seedData.shipping,
    shipping_cost:
      normalizedPayload.shipping_cost ||
      normalizedPayload.shippingCost ||
      externalSeed.shipping_cost ||
      seedData.shipping_cost,
    returns: normalizedPayload.returns || externalSeed.returns || seedData.returns,
    promotions: Array.isArray(normalizedPayload.promotions)
      ? normalizedPayload.promotions
      : Array.isArray(externalSeed.promotions)
        ? externalSeed.promotions
        : Array.isArray(seedData.promotions)
          ? seedData.promotions
          : undefined,
    in_stock: normalizedPayload.in_stock ?? externalSeed.in_stock ?? seedData.in_stock ?? snapshot.in_stock,
    fulfillment_type:
      normalizedPayload.fulfillment_type ||
      normalizedPayload.fulfillmentType ||
      externalSeed.fulfillment_type ||
      seedData.fulfillment_type,
    destination_url: firstCatalogPayloadString(
      normalizedPayload.destination_url,
      normalizedPayload.destinationUrl,
      normalizedPayload.external_redirect_url,
      normalizedPayload.externalRedirectUrl,
      normalizedPayload.source_url,
      normalizedPayload.sourceUrl,
      externalSeed.destination_url,
      externalSeed.canonical_url,
      externalSeed.url,
      seedData.destination_url,
      seedData.canonical_url,
      snapshot.destination_url,
      snapshot.canonical_url,
    ),
    canonical_url: firstCatalogPayloadString(
      normalizedPayload.canonical_url,
      normalizedPayload.canonicalUrl,
      externalSeed.canonical_url,
      seedData.canonical_url,
      snapshot.canonical_url,
    ),
    url: firstCatalogPayloadString(normalizedPayload.url, externalSeed.url, seedData.url),
    image_url: firstCatalogPayloadString(
      normalizedPayload.image_url,
      normalizedPayload.imageUrl,
      normalizedPayload.images,
      normalizedPayload.image_urls,
      externalSeed.image_url,
      externalSeed.images,
      seedData.image_url,
      seedData.images,
      snapshot.image_url,
      snapshot.images,
    ),
    images: Array.isArray(normalizedPayload.images)
      ? normalizedPayload.images.slice(0, 8)
      : Array.isArray(externalSeed.images)
        ? externalSeed.images.slice(0, 8)
        : Array.isArray(seedData.images)
          ? seedData.images.slice(0, 8)
          : undefined,
    ...(commerceFacts ? { commerce_facts_v1: commerceFacts, commerce_facts: commerceFacts } : {}),
    ...(agentSafeCommerceFacts ? { agent_safe_commerce_facts: agentSafeCommerceFacts } : {}),
    ...(variants.length ? { variants } : {}),
  });
}

function externalSeedOfferPayloadHasPriceSignal(product) {
  if (!product || typeof product !== 'object') return false;
  const productPrice = readPriceAmountForNormalization(
    product.price ?? product.price_amount ?? product.priceAmount,
  );
  if (Number.isFinite(productPrice) && productPrice > 0) return true;

  const variants = Array.isArray(product.variants) ? product.variants : [];
  return variants.some((variant) => {
    if (!variant || typeof variant !== 'object') return false;
    const variantPrice = readPriceAmountForNormalization(
      variant.price ?? variant.price_amount ?? variant.priceAmount,
    );
    return Number.isFinite(variantPrice) && variantPrice > 0;
  });
}

function buildExternalSeedOfferProductFromMember(member) {
  if (!member || typeof member !== 'object') return null;
  const merchantId = String(member.merchant_id || member.merchantId || '').trim();
  if (!memberIsExternalSeedSupply(member)) return null;
  const productId = String(member.product_id || member.productId || '').trim();
  const payload =
    member.source_payload && typeof member.source_payload === 'object'
      ? member.source_payload
      : member.sourcePayload && typeof member.sourcePayload === 'object'
        ? member.sourcePayload
        : null;
  if (!productId || !payload) return null;
  const projected = projectExternalSeedOfferPayload(payload, merchantId, productId);
  if (!externalSeedOfferPayloadHasPriceSignal(projected)) return null;
  return attachProductDetailSource(
    normalizeProductDetailPrice(projected),
    'identity_graph',
  );
}

function collectOfferProductRefKeys(product) {
  if (!product || typeof product !== 'object') return [];
  const refs = [
    product.selected_commerce_ref,
    product.selectedCommerceRef,
    product.commerce_ref,
    product.commerceRef,
    product.product_ref,
    product.productRef,
    {
      merchant_id: product.merchant_id || product.merchantId,
      product_id: product.product_id || product.productId || product.id,
    },
  ];
  const keys = refs
    .map((ref) => ({
      merchant_id: String(ref?.merchant_id || ref?.merchantId || '').trim(),
      product_id: String(ref?.product_id || ref?.productId || ref?.id || '').trim(),
    }))
    .filter((ref) => ref.merchant_id && ref.product_id)
    .map((ref) => `${ref.merchant_id}:${ref.product_id}`);
  return Array.from(new Set(keys));
}

function buildPrefetchedOfferProductMap(products) {
  const out = new Map();
  (Array.isArray(products) ? products : []).forEach((product) => {
    if (!product || typeof product !== 'object') return;
    const projected = buildOfferProductProjection(product);
    collectOfferProductRefKeys(product).forEach((key) => {
      if (!out.has(key)) out.set(key, projected);
    });
  });
  return out;
}

function hasOfferProductTransactionHold(product = {}) {
  if (!isPlainObject(product)) return false;
  const seedData = isPlainObject(product.seed_data) ? product.seed_data : {};
  const snapshot = isPlainObject(seedData.snapshot) ? seedData.snapshot : {};
  const family = String(
    firstNonEmptyString(product.product_family, product.external_seed_product_family) || '',
  ).toLowerCase();
  const hasContract = (value) => {
    const contract = isPlainObject(value) ? value : {};
    return Boolean(firstNonEmptyString(contract.status, contract.reason, contract.contract_version));
  };
  return Boolean(
    product.transaction_ready === false ||
      family === 'non_merch' ||
      hasContract(product.transaction_readiness_blocker_v1) ||
      hasContract(product.non_merch_terminal_hold_v1) ||
      hasContract(seedData.transaction_readiness_blocker_v1) ||
      hasContract(snapshot.transaction_readiness_blocker_v1) ||
      hasContract(seedData.non_merch_terminal_hold_v1) ||
      hasContract(snapshot.non_merch_terminal_hold_v1) ||
      hasContract(seedData.source_unavailable_v1) ||
      hasContract(snapshot.source_unavailable_v1)
  );
}

function findPrefetchedSavingsPresentationProduct(product, prefetchedProducts) {
  if (!product || typeof product !== 'object') return null;
  const productKeys = new Set(collectOfferProductRefKeys(product));
  if (!productKeys.size) return null;
  for (const candidate of Array.isArray(prefetchedProducts) ? prefetchedProducts : []) {
    if (!candidate || typeof candidate !== 'object' || !hasSavingsPresentationFields(candidate)) continue;
    const matches = collectOfferProductRefKeys(candidate).some((key) => productKeys.has(key));
    if (matches) return candidate;
  }
  return null;
}

function buildOfferProductProjection(product) {
  if (!product || typeof product !== 'object') return product;
  const selectedRef =
    product.selected_commerce_ref ||
    product.selectedCommerceRef ||
    product.commerce_ref ||
    product.commerceRef ||
    product.product_ref ||
    product.productRef ||
    {};
  const merchantId = String(
    selectedRef?.merchant_id ||
      selectedRef?.merchantId ||
      product.merchant_id ||
      product.merchantId ||
      '',
  ).trim();
  const productId = String(
    selectedRef?.product_id ||
      selectedRef?.productId ||
      selectedRef?.id ||
      product.product_id ||
      product.productId ||
      product.id ||
      '',
  ).trim();
  const savingsFields =
    merchantId && merchantId !== EXTERNAL_SEED_MERCHANT_ID && !isExternalSeedLikeProduct(product)
      ? pickSavingsPresentationFields(product)
      : {};
  return attachProductDetailSource(
    normalizeProductDetailPrice({
      merchant_id: merchantId || product.merchant_id || product.merchantId,
      product_id: productId || product.product_id || product.productId || product.id,
      id: productId || product.id || product.product_id || product.productId,
      merchant_name: product.merchant_name || product.merchantName,
      store_name: product.store_name || product.storeName,
      seller_name: product.seller_name || product.sellerName,
      seller_of_record: product.seller_of_record || product.sellerOfRecord,
      vendor: product.vendor,
      brand: product.brand,
      price: product.price,
      currency: product.currency,
      shipping: product.shipping,
      shipping_cost: product.shipping_cost,
      returns: product.returns,
      in_stock: product.in_stock,
      fulfillment_type: product.fulfillment_type,
      variants: Array.isArray(product.variants)
        ? product.variants.map((variant) => ({
            id: variant?.id,
            variant_id: variant?.variant_id || variant?.variantId || variant?.id,
            sku: variant?.sku,
            sku_id: variant?.sku_id || variant?.skuId || variant?.sku,
            title: variant?.title || variant?.name,
            options: variant?.options || variant?.selected_options || variant?.selectedOptions,
            price: variant?.price,
            price_amount: variant?.price_amount || variant?.priceAmount,
            currency: variant?.currency,
            in_stock: variant?.in_stock,
            available: variant?.available,
            available_quantity: variant?.available_quantity,
            inventory_quantity: variant?.inventory_quantity,
            image_url: variant?.image_url || variant?.imageUrl,
            ...(merchantId && merchantId !== EXTERNAL_SEED_MERCHANT_ID && !isExternalSeedLikeProduct(product)
              ? pickSavingsPresentationFields(variant)
              : {}),
          }))
        : undefined,
      ...savingsFields,
      ...buildOfferPurchaseMetadataFromProduct(product),
    }),
    getProductDetailSource(product) || 'pdp_prefetched',
  );
}

function getVariantEvidenceKeys(variant) {
  if (!variant || typeof variant !== 'object') return [];
  return [
    variant.variant_id,
    variant.variantId,
    variant.id,
    variant.sku_id,
    variant.skuId,
    variant.sku,
    variant.admin_graphql_api_id,
    variant.adminGraphqlApiId,
  ]
    .map((value) => String(value || '').trim())
    .filter(Boolean);
}

function mergeSavingsPresentationFields(target, source) {
  if (!target || typeof target !== 'object' || !source || typeof source !== 'object') {
    return target;
  }
  const merged = {
    ...target,
    ...pickSavingsPresentationFields(source),
  };
  const sourceVariants = Array.isArray(source.variants) ? source.variants : [];
  const targetVariants = Array.isArray(target.variants) ? target.variants : [];
  if (!targetVariants.length || !sourceVariants.length) return merged;

  const sourceByKey = new Map();
  sourceVariants.forEach((variant) => {
    if (!variant || typeof variant !== 'object') return;
    getVariantEvidenceKeys(variant).forEach((key) => {
      if (!sourceByKey.has(key)) sourceByKey.set(key, variant);
    });
  });
  if (!sourceByKey.size) return merged;

  merged.variants = targetVariants.map((variant) => {
    if (!variant || typeof variant !== 'object') return variant;
    const match = getVariantEvidenceKeys(variant)
      .map((key) => sourceByKey.get(key))
      .find(Boolean);
    if (!match || !hasSavingsPresentationFields(match)) return variant;
    return {
      ...variant,
      ...pickSavingsPresentationFields(match),
    };
  });
  return merged;
}

async function hydrateSavingsPresentationFromUpstream({
  product,
  canonicalProductRef,
  checkoutToken,
  force = false,
} = {}) {
  if (!product || typeof product !== 'object') return product;
  if (!force && hasSavingsPresentationFields(product)) return product;
  const selectedCommerceRef =
    product.selected_commerce_ref ||
    product.selectedCommerceRef ||
    product.commerce_ref ||
    product.commerceRef ||
    null;
  const productRef = product.product_ref || product.productRef || null;
  const candidateRefs = [
    selectedCommerceRef,
    productRef,
    canonicalProductRef,
    {
      merchant_id: product.merchant_id || product.merchantId,
      product_id: product.product_id || product.productId || product.id,
    },
  ];
  const hydrationRef = candidateRefs
    .map((ref) => ({
      merchant_id: String(ref?.merchant_id || ref?.merchantId || '').trim(),
      product_id: String(ref?.product_id || ref?.productId || ref?.id || '').trim(),
    }))
    .find((ref) => ref.merchant_id && ref.product_id && !isExternalSeedListingMerchantId(ref.merchant_id));
  const merchantId = hydrationRef?.merchant_id || '';
  const productId = hydrationRef?.product_id || '';
  if (!merchantId || !productId || isExternalSeedListingMerchantId(merchantId)) return product;

  try {
    const upstreamProduct = await fetchProductDetailFromUpstream({
      merchantId,
      productId,
      checkoutToken,
      noRetry: true,
    });
    if (!upstreamProduct || typeof upstreamProduct !== 'object') return product;
    const normalizedUpstream = attachProductDetailSource(
      normalizeProductDetailPrice({
        ...upstreamProduct,
        merchant_id: merchantId,
        product_id:
          String(upstreamProduct.product_id || upstreamProduct.id || productId).trim() ||
          productId,
      }),
      'upstream',
    );
    cacheProductDetailForOffers({
      merchantId,
      productId,
      checkoutToken,
      product: normalizedUpstream,
      source: 'upstream',
    });
    if (!hasSavingsPresentationFields(normalizedUpstream)) return product;
    return mergeSavingsPresentationFields(product, normalizedUpstream);
  } catch (err) {
    logger.warn(
      {
        err: err?.message || String(err),
        merchant_id: merchantId,
        product_id: productId,
      },
      'Failed to hydrate PDP savings presentation evidence',
    );
    return product;
  }
}

async function fetchProductDetailForOffers(args) {
  const merchantId = String(args?.merchantId || '').trim();
  const productId = String(args?.productId || '').trim();
  const checkoutToken = args?.checkoutToken;
  const surfaceUpstreamErrors = args?.surfaceUpstreamErrors === true;
  const bypassCache = args?.bypassCache === true;
  const skipUpstreamFallback = args?.skipUpstreamFallback === true;
  const totalTimeoutMs = Math.max(0, Number(args?.totalTimeoutMs || args?.stageTimeoutMs || 0) || 0);
  // ADR-009: a seed-shaped product id addresses the seed store on its own —
  // fetchExternalSeedProductDetailFromDb keys on the product id ALONE and never
  // names a seller. Before this, the only way to reach that lookup was to
  // fabricate a seller from the id prefix and let the retired shared bucket act
  // as a routing token; admitting the seller-less call here is what makes that
  // fabrication deletable. It admits exactly one caller: every other call site
  // either guards on a non-empty merchant or draws from a group-member list
  // already filtered on one (buildOffersFromGroupMembers and both find_similar
  // member normalizers), so no existing caller changes behaviour.
  const seedRoutedWithoutMerchant = !merchantId && isExternalSeedProductId(productId);
  if ((!merchantId && !seedRoutedWithoutMerchant) || !productId) return null;
  // Freshness parity with the seller-addressed twin of this call, which resolves
  // to a 0ms TTL (the retired bucket's historical cache bypass). Deriving the
  // TTL from an empty merchant would hand this lane the DEFAULT ttl instead and
  // silently start caching seed detail that is deliberately never cached.
  const resolvedCacheTtlMs = seedRoutedWithoutMerchant
    ? 0
    : resolveProductDetailCacheTtlMs(merchantId);
  const useMemoryCache =
    PRODUCT_DETAIL_CACHE_ENABLED &&
    !bypassCache &&
    resolvedCacheTtlMs > 0;

  const cacheKey = buildProductDetailCacheKey({ merchantId, productId, checkoutToken });

  if (PRODUCT_DETAIL_CACHE_ENABLED && !useMemoryCache) {
    PRODUCT_DETAIL_CACHE_METRICS.bypasses += 1;
  }

  if (useMemoryCache) {
    const cachedEntry = getProductDetailCacheEntry(cacheKey);
    const cachedValue = cachedEntry?.value;
    const cachedProduct =
      cachedValue && typeof cachedValue === 'object'
        ? cachedValue.product || cachedValue?.data?.product
        : null;
    const cachedSource = inferDetailSourceFromQuerySource(cachedValue?.metadata?.query_source);
    if (cachedProduct && typeof cachedProduct === 'object') {
      const served = attachProductDetailSource(
        normalizeProductDetailPrice({
        ...cachedProduct,
        merchant_id: merchantId,
        product_id:
          String(cachedProduct.product_id || cachedProduct.id || productId).trim() ||
          productId,
        }),
        cachedSource || 'fresh_cache',
      );
      const storedAtMs = Number(cachedEntry?.storedAtMs);
      if (Number.isFinite(storedAtMs)) {
        attachProductDetailCacheMeta(served, {
          storedAtMs,
          ageMs: Math.max(0, Date.now() - storedAtMs),
        });
      }
      return served;
    }
  }

  const inflight = useMemoryCache ? PRODUCT_DETAIL_INFLIGHT.get(cacheKey) : null;
  if (inflight) {
    return inflight;
  }

  const loadPromise = (async () => {
    // ADR-009: observed sellers (`merch_obs_`) are external-seed supply — their
    // only detail store is external_product_seeds (no products_cache row: the
    // legacy cache lane's source gate excludes them; no upstream API: the
    // backend 404s for observed refs). Route them through the seed-DB detail
    // path alongside the legacy bucket, re-stamped with the observed seller id
    // so identity/offer keying stays on the resolved merchant.
    if (
      process.env.DATABASE_URL &&
      (isExternalSeedListingMerchantId(merchantId) || seedRoutedWithoutMerchant)
    ) {
      const seedDetail = await fetchExternalSeedProductDetailFromDb({ productId });
      if (seedDetail?.product) {
        // Re-stamp onto the RESOLVED seller only. A seller-less call has nothing
        // to re-stamp with, and stamping the empty string would overwrite the
        // seed payload's own merchant_id with nothing.
        const seedProduct =
          merchantId && merchantId !== EXTERNAL_SEED_MERCHANT_ID
            ? { ...seedDetail.product, merchant_id: merchantId }
            : seedDetail.product;
        if (useMemoryCache) {
          setProductDetailCache(cacheKey, {
            status: 'success',
            success: true,
            product: seedProduct,
            metadata: {
              query_source: 'external_seed_db',
              external_seed_id: seedDetail.external_seed_id || null,
              matched_via: seedDetail.matched_via || null,
              updated_at: seedDetail.updated_at || null,
            },
          }, resolvedCacheTtlMs);
        }
        return seedProduct;
      }
      if (PDP_EXTERNAL_SEED_LEGACY_DETAIL_FALLBACK_ENABLED) {
        const fromExternalSeeds = await findExternalSeedProductById({ productId }).catch(() => null);
        if (fromExternalSeeds) {
          const normalizedExternalSeed = attachProductDetailSource(
            normalizeProductDetailPrice(
              merchantId && merchantId !== EXTERNAL_SEED_MERCHANT_ID
                ? { ...fromExternalSeeds, merchant_id: merchantId }
                : fromExternalSeeds,
            ),
            'external_seed_db',
          );
          if (useMemoryCache) {
            setProductDetailCache(cacheKey, {
              status: 'success',
              success: true,
              product: normalizedExternalSeed,
              metadata: {
                query_source: 'external_product_seeds_legacy_fallback',
              },
            }, resolvedCacheTtlMs);
          }
          return normalizedExternalSeed;
        }
      }

      return null;
    }

    // The seller-less admission above unlocks the seed store and NOTHING else:
    // products_cache and the upstream detail API are both seller-scoped, so with
    // no seller there is no well-formed request left to make of them. (Reached
    // only when the seed branch above was skipped for want of a database.)
    if (seedRoutedWithoutMerchant) return null;

    if (process.env.DATABASE_URL) {
      const fromDb = await fetchProductDetailFromProductsCache({
        merchantId,
        productId,
        includeExpired: false,
      });
      if (fromDb?.product) {
        const normalizedDb = attachProductDetailSource(
          normalizeProductDetailPrice(fromDb.product),
          'fresh_cache',
        );
        if (useMemoryCache) {
          setProductDetailCache(cacheKey, {
            status: 'success',
            success: true,
            product: normalizedDb,
            metadata: {
              query_source: 'products_cache',
              cached_at: fromDb.cached_at || null,
            },
          }, resolvedCacheTtlMs);
        }
        return normalizedDb;
      }
    }

    if (skipUpstreamFallback) {
      return null;
    }

    let upstreamProduct = null;
    let upstreamError = null;
    try {
      upstreamProduct = await fetchProductDetailFromUpstream({
        merchantId,
        productId,
        checkoutToken,
        timeoutMs: args?.timeoutMs,
        noRetry: args?.noRetry === true,
      });
    } catch (err) {
      upstreamError = err;
      upstreamProduct = null;
    }

    if (upstreamProduct && typeof upstreamProduct === 'object') {
      const normalizedUpstream = attachProductDetailSource(
        normalizeProductDetailPrice({
          ...upstreamProduct,
          merchant_id: merchantId,
          product_id:
            String(upstreamProduct.product_id || upstreamProduct.id || productId).trim() ||
            productId,
        }),
        'upstream',
      );

      if (useMemoryCache) {
        setProductDetailCache(cacheKey, {
          status: 'success',
          success: true,
          product: normalizedUpstream,
          metadata: { query_source: 'upstream' },
        }, resolvedCacheTtlMs);
      }
      return normalizedUpstream;
    }

    if (process.env.DATABASE_URL && PRODUCT_DETAIL_STALE_LOOKUP_ENABLED) {
      const staleFromDb = await fetchProductDetailFromProductsCache({
        merchantId,
        productId,
        includeExpired: true,
        staleMaxAgeHours: PRODUCT_DETAIL_STALE_MAX_AGE_HOURS,
      });
      if (staleFromDb?.product) {
        const normalizedStale = attachProductDetailSource(
          normalizeProductDetailPrice(staleFromDb.product),
          'stale_cache',
        );
        if (useMemoryCache) {
          setProductDetailCache(cacheKey, {
            status: 'success',
            success: true,
            product: normalizedStale,
            metadata: {
              query_source: 'products_cache_stale',
              cached_at: staleFromDb.cached_at || null,
              stale_max_age_hours: PRODUCT_DETAIL_STALE_MAX_AGE_HOURS,
            },
          }, resolvedCacheTtlMs);
        }
        return normalizedStale;
      }
    }

    if (surfaceUpstreamErrors && upstreamError) {
      const upstreamStatus =
        Number(upstreamError?.response?.status || upstreamError?.status || 0) || null;
      const upstreamCode = String(upstreamError?.code || '').trim().toUpperCase();
      const shouldSurfaceUpstreamError =
        !upstreamStatus ||
        upstreamStatus >= 500 ||
        upstreamCode === 'ECONNABORTED' ||
        upstreamCode === 'ETIMEDOUT' ||
        upstreamCode === 'ECONNRESET' ||
        upstreamCode === 'EAI_AGAIN';
      if (shouldSurfaceUpstreamError) {
        throw upstreamError;
      }
    }

    return null;
  })();

  // ALWAYS bounded. The caller's own budget still wins when it is tighter; the
  // backstop only exists so a load with no budget cannot run forever.
  const effectiveTimeoutMs = totalTimeoutMs > 0
    ? Math.min(totalTimeoutMs, PRODUCT_DETAIL_MAX_LOAD_MS)
    : PRODUCT_DETAIL_MAX_LOAD_MS;
  const guardedLoadPromise = withStageBudget(
    loadPromise,
    effectiveTimeoutMs,
    `offer_detail:${merchantId}:${productId}`,
  );

  if (!useMemoryCache) {
    return guardedLoadPromise;
  }

  // Store the GUARDED promise, not the raw one. Concurrent callers for this key
  // return the stored promise directly (see the PRODUCT_DETAIL_INFLIGHT.get
  // above) — storing the unguarded load meant those piggybacking callers
  // awaited something with no deadline, and evicting the map entry does not
  // cancel an await already in flight.
  trimOldestInflightEntries(PRODUCT_DETAIL_INFLIGHT, PRODUCT_DETAIL_INFLIGHT_MAX_ENTRIES);
  PRODUCT_DETAIL_INFLIGHT.set(cacheKey, guardedLoadPromise);
  try {
    return await guardedLoadPromise;
  } finally {
    // Identity-checked so a slow unwind cannot evict a NEWER entry that has
    // already replaced this one under the same key.
    if (PRODUCT_DETAIL_INFLIGHT.get(cacheKey) === guardedLoadPromise) {
      PRODUCT_DETAIL_INFLIGHT.delete(cacheKey);
    }
  }
}

async function resolveProductGroupCached(args) {
  const productId = String(args?.productId || '').trim();
  const merchantId = String(args?.merchantId || '').trim() || null;
  const platform = args?.platform ? String(args.platform).trim() : null;
  const checkoutToken = args?.checkoutToken;
  const bypassCache = args?.bypassCache === true;
  const debug = args?.debug === true;

  if (!productId) return null;

  const cacheKey = JSON.stringify({
    productId,
    merchantId,
    platform,
    hasCheckoutToken: Boolean(checkoutToken),
  });
  const cacheEnabled = RESOLVE_PRODUCT_GROUP_CACHE_ENABLED && !bypassCache;
  if (!cacheEnabled) RESOLVE_PRODUCT_GROUP_CACHE_METRICS.bypasses += 1;
  const cachedEntry = cacheEnabled ? getResolveProductGroupCacheEntry(cacheKey) : null;
  if (cachedEntry?.value) {
    const ageMs =
      typeof cachedEntry.storedAtMs === 'number'
        ? Math.max(0, Date.now() - cachedEntry.storedAtMs)
        : 0;
    return debug
      ? {
          ...cachedEntry.value,
          cache: { hit: true, age_ms: ageMs, ttl_ms: RESOLVE_PRODUCT_GROUP_CACHE_TTL_MS },
        }
      : cachedEntry.value;
  }

  const canonicalCatalogGroup = await resolveCanonicalCatalogEntityGroup({
    productId,
    merchantId,
    queryFn: query,
  }).catch((err) => {
    logger.warn(
      {
        err: err?.message || String(err),
        product_id: productId,
        merchant_id: merchantId,
      },
      'Canonical catalog product group resolution failed; falling back to upstream',
    );
    return null;
  });
  if (
    canonicalCatalogGroup?.canonical_product_ref &&
    Array.isArray(canonicalCatalogGroup.members) &&
    canonicalCatalogGroup.members.length > 0
  ) {
    const result = {
      status: 'success',
      product_group_id: canonicalCatalogGroup.product_group_id,
      sellable_item_group_id:
        canonicalCatalogGroup.sellable_item_group_id || canonicalCatalogGroup.product_group_id,
      canonical_sig_id: canonicalCatalogGroup.canonical_sig_id || canonicalCatalogGroup.product_group_id,
      // Stable pg_*-first canonical product identity (sig_* fallback). See resolver.
      canonical_entity_id:
        canonicalCatalogGroup.canonical_entity_id || canonicalCatalogGroup.product_group_id,
      content_key: canonicalCatalogGroup.content_key || null,
      internal_product_group_id: canonicalCatalogGroup.internal_product_group_id || null,
      canonical_product_ref: canonicalCatalogGroup.canonical_product_ref,
      members: canonicalCatalogGroup.members,
      member_sig_ids: canonicalCatalogGroup.member_sig_ids || [],
      seller_count: canonicalCatalogGroup.seller_count || canonicalCatalogGroup.members.length,
      member_count: canonicalCatalogGroup.member_count || canonicalCatalogGroup.members.length,
      offer_count: canonicalCatalogGroup.offer_count || 0,
      source: 'canonical_catalog',
    };
    if (cacheEnabled) setResolveProductGroupCache(cacheKey, result);
    return debug
      ? { ...result, cache: { hit: false, age_ms: 0, ttl_ms: RESOLVE_PRODUCT_GROUP_CACHE_TTL_MS } }
      : result;
  }

  const resolvedGroup = merchantId
    ? await resolveProductGroupFromUpstream({
        merchantId,
        productId,
        platform,
        checkoutToken,
      })
    : await resolveProductGroupByProductIdFromUpstream({
        productId,
        platform,
        checkoutToken,
      });

  const productGroupIdRaw =
    resolvedGroup?.product_group_id || resolvedGroup?.productGroupId || null;
  const productGroupId =
    typeof productGroupIdRaw === 'string' && productGroupIdRaw.trim()
      ? productGroupIdRaw.trim()
      : null;
  const membersRaw = Array.isArray(resolvedGroup?.members) ? resolvedGroup.members : [];
  const members = membersRaw
    .map((m) => ({
      merchant_id: String(m?.merchant_id || m?.merchantId || '').trim(),
      merchant_name: m?.merchant_name || m?.merchantName || undefined,
      seller_name: m?.seller_name || m?.sellerName || undefined,
      store_name: m?.store_name || m?.storeName || undefined,
      seller_of_record: m?.seller_of_record || m?.sellerOfRecord || undefined,
      product_id: String(m?.product_id || m?.productId || '').trim(),
      platform: m?.platform ? String(m.platform).trim() : undefined,
      is_primary: Boolean(m?.is_primary || m?.isPrimary),
    }))
    .filter((m) => Boolean(m.merchant_id) && Boolean(m.product_id));

  const canonicalMember = members.find((m) => m.is_primary) || members[0] || null;

  const result = {
    status: 'success',
    ...(productGroupId ? { product_group_id: productGroupId } : {}),
    // Upstream (non-catalog) path has no pg_*; fall back to the upstream group id so
    // the field is always present for consumers.
    ...(productGroupId ? { canonical_entity_id: productGroupId } : {}),
    canonical_product_ref: canonicalMember
      ? {
          merchant_id: canonicalMember.merchant_id,
          product_id: canonicalMember.product_id,
          ...(canonicalMember.platform ? { platform: canonicalMember.platform } : {}),
        }
      : null,
    members,
  };

  if (cacheEnabled) setResolveProductGroupCache(cacheKey, result);
  return debug
    ? { ...result, cache: { hit: false, age_ms: 0, ttl_ms: RESOLVE_PRODUCT_GROUP_CACHE_TTL_MS } }
    : result;
}

function normalizeOfferMoney(amount, currency) {
  const raw = amount;
  let normalizedAmount = 0;
  let normalizedCurrency = String(currency || 'USD').toUpperCase() || 'USD';

  if (typeof raw === 'number') {
    normalizedAmount = raw;
  } else if (typeof raw === 'string') {
    normalizedAmount = Number(raw) || 0;
  } else if (raw && typeof raw === 'object') {
    const obj = raw;
    const candidateAmount =
      obj.amount ??
      obj.current?.amount ??
      obj.price ??
      obj.value ??
      null;
    if (typeof candidateAmount === 'number') normalizedAmount = candidateAmount;
    else if (typeof candidateAmount === 'string') normalizedAmount = Number(candidateAmount) || 0;

    const candidateCurrency =
      obj.currency ??
      obj.current?.currency ??
      obj.currency_code ??
      null;
    if (typeof candidateCurrency === 'string' && candidateCurrency.trim()) {
      normalizedCurrency = candidateCurrency.trim().toUpperCase();
    }
  }

  return {
    amount: Number(normalizedAmount) || 0,
    currency: normalizedCurrency,
  };
}

function normalizeOfferMoneyForProduct(amount, currency, product = {}, variant = null) {
  const productContext = buildProductDetailPriceContext(product, currency);
  const context = {
    ...productContext,
    currency: firstNonEmptyString(
      currency,
      variant?.currency,
      variant?.price_currency,
      variant?.priceCurrency,
      variant?.price?.currency,
      variant?.price?.current?.currency,
      productContext.currency,
      'USD',
    ),
    title: [
      productContext.title,
      variant?.title,
      variant?.name,
      variant?.sku,
    ]
      .map((value) => String(value || '').trim())
      .filter(Boolean)
      .join(' '),
    description: firstNonEmptyString(variant?.description, productContext.description),
  };
  const rawAmount = readPriceAmountForNormalization(amount);
  if (!Number.isFinite(rawAmount) || rawAmount <= 0) return null;
  let normalizedAmount = normalizeExternalSeedPrice(amount, context);
  const productAmount = readPriceAmountForNormalization(
    product?.price ?? product?.price_amount ?? product?.priceAmount,
  );
  if (
    Number.isFinite(rawAmount) &&
    Number.isFinite(productAmount) &&
    rawAmount >= 1000 &&
    productAmount > 0 &&
    productAmount < 1000 &&
    rawAmount > productAmount * 20 &&
    Math.abs(rawAmount / 100 - productAmount) < 0.01
  ) {
    normalizedAmount = productAmount;
  }
  if (!Number.isFinite(Number(normalizedAmount)) || Number(normalizedAmount) <= 0) return null;
  return normalizeOfferMoney(normalizedAmount, context.currency);
}

function computeOfferTotal(offer) {
  const amount = Number(offer?.price?.amount ?? offer?.price?.current?.amount);
  if (!Number.isFinite(amount) || amount <= 0) return Number.POSITIVE_INFINITY;
  const shipping = Number(offer?.shipping?.cost?.amount ?? 0) || 0;
  return amount + shipping;
}

function readPositiveOfferMoney(offer) {
  if (!offer || typeof offer !== 'object') return null;
  const amount = readPriceAmountForNormalization(offer.price);
  if (!Number.isFinite(amount) || amount <= 0) return null;
  return {
    amount,
    currency: readOfferCurrency(offer) || 'USD',
  };
}

function readOfferCurrency(offer) {
  return String(
    offer?.price?.currency ||
      offer?.price?.current?.currency ||
      offer?.currency ||
      '',
  ).trim().toUpperCase();
}

function offerIsInternalCheckoutCandidate(offer) {
  const route = String(offer?.purchase_route || offer?.purchaseRoute || '').trim().toLowerCase();
  if (route === 'internal_checkout') return true;
  const merchantId = String(offer?.merchant_id || offer?.merchantId || '').trim();
  return Boolean(merchantId && merchantId !== EXTERNAL_SEED_MERCHANT_ID);
}

function offerHasAvailableInventory(offer) {
  const inStock = offer?.inventory?.in_stock ?? offer?.inventory?.inStock ?? offer?.in_stock ?? offer?.inStock;
  return inStock !== false;
}

function compareOffersForDefaultSelection(a, b) {
  const aInternal = offerIsInternalCheckoutCandidate(a) ? 1 : 0;
  const bInternal = offerIsInternalCheckoutCandidate(b) ? 1 : 0;
  if (aInternal !== bInternal) return bInternal - aInternal;

  const aInStock = offerHasAvailableInventory(a) ? 1 : 0;
  const bInStock = offerHasAvailableInventory(b) ? 1 : 0;
  if (aInStock !== bInStock) return bInStock - aInStock;

  const aCurrency = readOfferCurrency(a);
  const bCurrency = readOfferCurrency(b);
  if (aCurrency && bCurrency && aCurrency === bCurrency) {
    const aTotal = computeOfferTotal(a);
    const bTotal = computeOfferTotal(b);
    if (aTotal !== bTotal) return aTotal < bTotal ? -1 : 1;
  }

  return 0;
}

function findPositiveOfferById(offers, offerId) {
  const id = String(offerId || '').trim();
  if (!id) return null;
  return offers.find((offer) => String(offer?.offer_id || offer?.id || '').trim() === id && readPositiveOfferMoney(offer));
}

function pickOfferForCanonicalPdpPrice(offersData) {
  const offers = Array.isArray(offersData?.offers) ? offersData.offers : [];
  if (!offers.length) return null;

  const defaultOffer = findPositiveOfferById(offers, offersData?.default_offer_id);
  if (defaultOffer && offerHasAvailableInventory(defaultOffer)) return defaultOffer;

  const bestPriceOffer = findPositiveOfferById(offers, offersData?.best_price_offer_id);
  if (bestPriceOffer && offerHasAvailableInventory(bestPriceOffer)) return bestPriceOffer;

  if (defaultOffer) return defaultOffer;
  if (bestPriceOffer) return bestPriceOffer;

  return (
    offers.find((offer) => offerHasAvailableInventory(offer) && readPositiveOfferMoney(offer)) ||
    offers.find((offer) => readPositiveOfferMoney(offer)) ||
    null
  );
}

function isDecorativeOfferMediaUrl(url) {
  const normalized = String(url || '').trim().toLowerCase();
  if (!normalized) return false;
  if (/\.(?:svg)(?:$|\?)/i.test(normalized)) return true;
  return ['menu', 'icon', 'logo', 'plpbanner', 'banner', 'navigation', 'cart'].some((token) =>
    normalized.includes(token),
  );
}

function collectNormalizedImageUrlsFromValue(value, out) {
  if (value === null || value === undefined) return;
  if (typeof value === 'string') {
    const url = normalizePdpImageUrl(value);
    if (url && !isDecorativeOfferMediaUrl(url)) out.push(url);
    return;
  }
  if (Array.isArray(value)) {
    value.forEach((item) => collectNormalizedImageUrlsFromValue(item, out));
    return;
  }
  if (value && typeof value === 'object') {
    collectNormalizedImageUrlsFromValue(value.url, out);
    collectNormalizedImageUrlsFromValue(value.src, out);
    collectNormalizedImageUrlsFromValue(value.image_url, out);
    collectNormalizedImageUrlsFromValue(value.imageUrl, out);
    collectNormalizedImageUrlsFromValue(value.thumbnail_url, out);
    collectNormalizedImageUrlsFromValue(value.thumbnailUrl, out);
  }
}

function dedupePdpImageUrls(urls) {
  const seen = new Set();
  const out = [];
  for (const value of Array.isArray(urls) ? urls : []) {
    const url = normalizePdpImageUrl(value);
    const key = buildPdpImageDedupeKey(url) || url;
    if (!url || !key || seen.has(key) || isDecorativeOfferMediaUrl(url)) continue;
    seen.add(key);
    out.push(url);
  }
  return out;
}

function isCatalogImageCacheUrl(url) {
  try {
    return new URL(String(url || '')).pathname.startsWith('/catalog-image-cache/');
  } catch {
    return false;
  }
}

function isTomFordOfficialShopifyFileUrl(url) {
  try {
    const parsed = new URL(String(url || ''));
    const host = parsed.hostname.toLowerCase();
    const pathName = parsed.pathname.toLowerCase();
    return (
      host === 'cdn.shopify.com' &&
      pathName.includes('/s/files/1/0761/9690/5173/files/') &&
      /\/tfb?_sku_/i.test(pathName)
    );
  } catch {
    return false;
  }
}

function preferReliableOfferImageUrls(urls) {
  // This function HOISTS cache URLs ahead of working merchant CDN URLs, so a cache row stored
  // under a retired host would be promoted into the hero slot of the offer/PDP gallery. Re-home
  // before partitioning, so what gets promoted is a URL that actually serves.
  const deduped = dedupePdpImageUrls(urls).map((url) => normalizeCatalogImageCacheUrlHost(url));
  const cached = deduped.filter(isCatalogImageCacheUrl);
  if (!cached.length) return deduped;

  const nonStaleDirect = deduped.filter((url) => {
    if (isCatalogImageCacheUrl(url)) return false;
    return !isTomFordOfficialShopifyFileUrl(url);
  });
  return [...cached, ...nonStaleDirect];
}

function collectOfferImageUrls(offer) {
  if (!offer || typeof offer !== 'object') return [];
  const rawUrls = [];
  collectNormalizedImageUrlsFromValue(offer.image_url, rawUrls);
  collectNormalizedImageUrlsFromValue(offer.imageUrl, rawUrls);
  collectNormalizedImageUrlsFromValue(offer.images, rawUrls);
  collectNormalizedImageUrlsFromValue(offer.image_urls, rawUrls);
  collectNormalizedImageUrlsFromValue(offer.media, rawUrls);
  if (Array.isArray(offer.variants)) {
    offer.variants.forEach((variant) => {
      collectNormalizedImageUrlsFromValue(variant?.image_url, rawUrls);
      collectNormalizedImageUrlsFromValue(variant?.imageUrl, rawUrls);
      collectNormalizedImageUrlsFromValue(variant?.images, rawUrls);
      collectNormalizedImageUrlsFromValue(variant?.image_urls, rawUrls);
      collectNormalizedImageUrlsFromValue(variant?.media, rawUrls);
    });
  }
  return preferReliableOfferImageUrls(rawUrls).slice(0, 8);
}

function pdpPayloadHasMediaGallery(pdpPayload) {
  const modules = Array.isArray(pdpPayload?.modules) ? pdpPayload.modules : [];
  return modules.some((module) => {
    if (String(module?.type || '').trim() !== 'media_gallery') return false;
    return (
      Array.isArray(module?.data?.items) &&
      module.data.items.some((item) =>
        normalizePdpImageUrl(item?.url || item?.image_url || item?.src),
      )
    );
  });
}

function productHasUsableImage(product) {
  const urls = [];
  collectNormalizedImageUrlsFromValue(product?.image_url, urls);
  collectNormalizedImageUrlsFromValue(product?.imageUrl, urls);
  collectNormalizedImageUrlsFromValue(product?.images, urls);
  collectNormalizedImageUrlsFromValue(product?.image_urls, urls);
  return dedupePdpImageUrls(urls).length > 0;
}

function stripNonPositiveVariantPrice(variant) {
  if (!variant || typeof variant !== 'object' || Array.isArray(variant)) return variant;
  const amount = readPriceAmountForNormalization(
    variant.price ?? variant.price_amount ?? variant.priceAmount ?? variant.amount ?? variant.value,
  );
  if (Number.isFinite(amount) && amount > 0) return variant;

  const next = { ...variant };
  delete next.price;
  delete next.price_amount;
  delete next.priceAmount;
  if (next.price_source === 'default_offer') delete next.price_source;
  return next;
}

function hydrateCanonicalPdpMediaFromOfferImages(pdpPayload, product, offerImageUrls) {
  if (!offerImageUrls.length) return pdpPayload;
  const shouldHydrateProductImage = !productHasUsableImage(product);
  const shouldHydrateMediaGallery = !pdpPayloadHasMediaGallery(pdpPayload);
  if (!shouldHydrateProductImage && !shouldHydrateMediaGallery) return pdpPayload;

  const nextProduct = { ...product };
  if (shouldHydrateProductImage) {
    nextProduct.image_url = offerImageUrls[0];
    nextProduct.images = offerImageUrls;
    nextProduct.image_urls = offerImageUrls;
    nextProduct.image_source = 'default_offer';
  }

  const nextPayload = {
    ...pdpPayload,
    product: nextProduct,
  };

  if (shouldHydrateMediaGallery) {
    const offerMediaItems = offerImageUrls.map((url) => ({
      type: 'image',
      url,
      alt_text: nextProduct.title || undefined,
      source: 'default_offer',
      source_scope: 'offer',
      source_kind: 'canonical_offer',
    }));
    const existingModules = Array.isArray(pdpPayload.modules) ? pdpPayload.modules : [];
    nextPayload.modules = [
      {
        module_id: 'm_media',
        type: 'media_gallery',
        priority: 100,
        data: {
          items: offerMediaItems,
          gallery_scope: 'selected_offer',
        },
      },
      ...existingModules.filter((module) => String(module?.type || '').trim() !== 'media_gallery'),
    ];
  }

  return nextPayload;
}

function hydrateCanonicalPdpPayloadFromOffers(pdpPayload, offersData) {
  if (!pdpPayload || typeof pdpPayload !== 'object') return pdpPayload;
  const product = pdpPayload.product && typeof pdpPayload.product === 'object'
    ? { ...pdpPayload.product }
    : null;
  if (!product) return pdpPayload;

  const offers = Array.isArray(offersData?.offers) ? offersData.offers : [];
  let selectedOffer = pickOfferForCanonicalPdpPrice(offersData);
  let selectedOfferImageUrls = collectOfferImageUrls(selectedOffer);
  if (!selectedOfferImageUrls.length) {
    const imageBearingOffer = offers.find((offer) => collectOfferImageUrls(offer).length > 0);
    if (imageBearingOffer) {
      selectedOffer = imageBearingOffer;
      selectedOfferImageUrls = collectOfferImageUrls(imageBearingOffer);
    }
  }
  const selectedOfferMoney = readPositiveOfferMoney(selectedOffer);

  const currentProductAmount = readPriceAmountForNormalization(
    product.price ?? product.price_amount ?? product.priceAmount,
  );
  const shouldHydratePrice = !Number.isFinite(currentProductAmount) || currentProductAmount <= 0;
  const shouldProjectGroupOfferPrice =
    String(offersData?.offer_source || '').trim() === 'group_fused' && Boolean(selectedOfferMoney);

  if (offersData?.default_offer_id) product.default_offer_id = offersData.default_offer_id;
  if (offersData?.best_price_offer_id) product.best_price_offer_id = offersData.best_price_offer_id;

  let projectedOfferPrice = null;
  if (selectedOfferMoney && (shouldHydratePrice || shouldProjectGroupOfferPrice)) {
    const existingPrice =
      product.price && typeof product.price === 'object' && !Array.isArray(product.price)
        ? product.price
        : {};
    projectedOfferPrice = {
      amount: selectedOfferMoney.amount,
      currency: selectedOfferMoney.currency,
    };
    product.price = {
      ...existingPrice,
      amount: projectedOfferPrice.amount,
      currency: projectedOfferPrice.currency,
      current: {
        ...(existingPrice.current && typeof existingPrice.current === 'object'
          ? existingPrice.current
          : {}),
        amount: projectedOfferPrice.amount,
        currency: projectedOfferPrice.currency,
      },
    };
    product.price_amount = projectedOfferPrice.amount;
    product.currency = projectedOfferPrice.currency;
    product.price_source = 'default_offer';
  } else if (shouldHydratePrice) {
    delete product.price;
    delete product.price_amount;
    delete product.priceAmount;
    if (Array.isArray(product.variants)) {
      product.variants = product.variants.map((variant) => stripNonPositiveVariantPrice(variant));
    }
    if (product.price_source === 'default_offer') delete product.price_source;
  }

  let modules = pdpPayload.modules;
  if (projectedOfferPrice && Array.isArray(pdpPayload.modules)) {
    let replacedPriceModule = false;
    modules = pdpPayload.modules.map((module) => {
      if (String(module?.type || '').trim() !== 'price_promo') return module;
      replacedPriceModule = true;
      const data = module?.data && typeof module.data === 'object' && !Array.isArray(module.data)
        ? module.data
        : {};
      return {
        ...module,
        data: {
          ...data,
          price: projectedOfferPrice,
        },
      };
    });
    if (!replacedPriceModule) {
      modules = [
        ...modules,
        {
          module_id: 'm_price',
          type: 'price_promo',
          priority: 90,
          data: {
            price: projectedOfferPrice,
            promotions: [],
          },
        },
      ];
    }
  }

  return hydrateCanonicalPdpMediaFromOfferImages({
    ...pdpPayload,
    ...(modules ? { modules } : {}),
    product,
  }, product, selectedOfferImageUrls);
}

function buildOfferPurchaseMetadataFromProduct(product) {
  const redirectUrl = resolveProductExternalRedirectUrl(product);
  const externalLike = isExternalSeedLikeProduct(product);
  if (redirectUrl) {
    return {
      purchase_route: 'affiliate_outbound',
      external_redirect_url: redirectUrl,
      url: redirectUrl,
      action: {
        type: 'redirect_url',
        url: redirectUrl,
      },
    };
  }
  return {
    purchase_route: externalLike ? 'affiliate_outbound' : 'internal_checkout',
  };
}

function normalizeOfferVariantAxisValue(value) {
  if (value == null || typeof value === 'boolean') return '';
  return String(value || '')
    .toLowerCase()
    .replace(/&nbsp;/g, ' ')
    .replace(/[^\p{L}\p{N}.\s-]+/gu, ' ')
    .replace(/[-_/]+/g, ' ')
    .replace(/\s+/g, ' ')
    .trim();
}

function compactOfferVariantAxisValue(value) {
  return normalizeOfferVariantAxisValue(value).replace(/\s+/g, '');
}

function extractOfferVariantUnitTokens(compactValue) {
  const compact = String(compactValue || '').toLowerCase();
  const tokens = new Set();
  const re = /(\d+(?:\.\d+)?)(fl(?:uid)?oz|floz|oz|ml|l|g|mg|kg)/g;
  let match = re.exec(compact);
  while (match) {
    const unit = String(match[2] || '').replace(/^fl(?:uid)?oz$/, 'floz');
    tokens.add(`${match[1]}${unit}`);
    match = re.exec(compact);
  }
  return tokens;
}

function offerVariantTextMatchesAxis(text, axisValue) {
  const normalizedText = normalizeOfferVariantAxisValue(text);
  const normalizedAxis = normalizeOfferVariantAxisValue(axisValue);
  if (!normalizedText || !normalizedAxis) return false;
  if (normalizedText === normalizedAxis) return true;

  const textCompact = compactOfferVariantAxisValue(text);
  const axisCompact = compactOfferVariantAxisValue(axisValue);
  if (!textCompact || !axisCompact) return false;
  if (textCompact === axisCompact) return true;

  const axisUnitTokens = extractOfferVariantUnitTokens(axisCompact);
  if (axisUnitTokens.size > 0) {
    const textUnitTokens = extractOfferVariantUnitTokens(textCompact);
    for (const token of axisUnitTokens) {
      if (textUnitTokens.has(token)) return true;
    }
    return false;
  }

  return axisCompact.length >= 4 && (textCompact.includes(axisCompact) || axisCompact.includes(textCompact));
}

function collectOfferVariantMatchTexts(variant) {
  if (!variant || typeof variant !== 'object') return [];
  const out = [];
  const push = (value) => {
    const text = String(value || '').trim();
    if (text) out.push(text);
  };

  push(variant.title);
  push(variant.name);
  push(variant.display_name);
  push(variant.displayName);
  push(variant.option1);
  push(variant.option2);
  push(variant.option3);

  const optionSources = [variant.options, variant.selected_options, variant.selectedOptions];
  for (const raw of optionSources) {
    if (!raw) continue;
    if (Array.isArray(raw)) {
      for (const option of raw) {
        if (!option || typeof option !== 'object') continue;
        const name = option.name || option.option || option.key || option.label;
        const value = option.value || option.text;
        push(name);
        push(value);
        if (name && value) push(`${name} ${value}`);
      }
      continue;
    }
    if (typeof raw === 'object') {
      for (const [name, value] of Object.entries(raw)) {
        push(name);
        push(value);
        if (name && value) push(`${name} ${value}`);
      }
    }
  }

  return Array.from(new Set(out));
}

function findOfferVariantForAxes(product, axes) {
  const variants = Array.isArray(product?.variants) ? product.variants : [];
  if (!variants.length) return null;

  const axisEntries = Object.entries(axes && typeof axes === 'object' ? axes : {})
    .filter(([key, value]) => {
      const normalizedKey = String(key || '').trim().toLowerCase();
      if (!normalizedKey || normalizedKey === 'multi_variant' || normalizedKey === 'variant_count') return false;
      return Boolean(normalizeOfferVariantAxisValue(value));
    });
  if (!axisEntries.length) return variants.length === 1 ? variants[0] : null;

  for (const variant of variants) {
    const texts = collectOfferVariantMatchTexts(variant);
    const matchedAllAxes = axisEntries.every(([, axisValue]) =>
      texts.some((text) => offerVariantTextMatchesAxis(text, axisValue)),
    );
    if (matchedAllAxes) return variant;
  }

  return variants.length === 1 ? variants[0] : null;
}

function getOfferVariantId(variant) {
  return firstNonEmptyString(variant?.variant_id, variant?.variantId, variant?.id);
}

function getOfferVariantSku(variant) {
  return firstNonEmptyString(variant?.sku_id, variant?.skuId, variant?.sku, variant?.sku_code);
}

function formatOfferVariantOptions(optionsRecord) {
  return Object.entries(optionsRecord || {})
    .map(([name, value]) => {
      const normalizedName = String(name || '').trim();
      const normalizedValue = String(value || '').trim();
      if (!normalizedName || !normalizedValue) return null;
      return {
        name: normalizedName,
        value: normalizedValue,
      };
    })
    .filter(Boolean);
}

function buildOfferVariantsForPayload(product, fallbackCurrency) {
  const variants = Array.isArray(product?.variants) ? product.variants : [];
  if (!variants.length) return [];

  return variants
    .map((variant) => {
      const variantId = getOfferVariantId(variant);
      if (!variantId) return null;

      const sku = getOfferVariantSku(variant);
      const optionsRecord = extractVariantOptions(variant);
      const options = formatOfferVariantOptions(optionsRecord);
      const currency =
        firstNonEmptyString(
          variant?.currency,
          variant?.price?.currency,
          variant?.price?.current?.currency,
          fallbackCurrency,
          'USD',
        ) || 'USD';
      const rawVariantPrice =
        variant?.price?.current?.amount ??
        variant?.price?.amount ??
        variant?.price_amount ??
        variant?.priceAmount ??
        variant?.pricing?.current?.amount ??
        variant?.pricing?.amount ??
        variant?.price ??
        null;
      const variantPrice = normalizeOfferMoneyForProduct(rawVariantPrice, currency, product, variant);
      const availableQuantityRaw =
        variant?.availability?.available_quantity ??
        variant?.available_quantity ??
        variant?.inventory_quantity ??
        variant?.quantity ??
        variant?.stock_quantity;
      const availableQuantity =
        availableQuantityRaw == null || availableQuantityRaw === ''
          ? undefined
          : Number.isFinite(Number(availableQuantityRaw))
            ? Math.max(0, Math.floor(Number(availableQuantityRaw)))
            : undefined;
      const inStock =
        typeof variant?.availability?.in_stock === 'boolean'
          ? variant.availability.in_stock
          : typeof variant?.in_stock === 'boolean'
            ? variant.in_stock
            : typeof variant?.available === 'boolean'
              ? variant.available
              : availableQuantity != null
                ? availableQuantity > 0
                : undefined;
      const title = firstNonEmptyString(variant?.title, variant?.name);
      const imageUrl = firstNonEmptyString(variant?.image_url, variant?.imageUrl);

      return {
        variant_id: variantId,
        ...(sku ? { sku_id: sku, sku } : {}),
        ...(title ? { title } : {}),
        ...(options.length ? { options } : {}),
        ...(variantPrice ? { price: { current: variantPrice } } : {}),
        availability: {
          ...(typeof inStock === 'boolean' ? { in_stock: inStock } : {}),
          ...(availableQuantity != null ? { available_quantity: availableQuantity } : {}),
        },
        ...(imageUrl ? { image_url: imageUrl } : {}),
        ...pickSavingsPresentationFields(variant),
      };
    })
    .filter(Boolean);
}

function decoratePdpPayloadWithIdentity(pdpPayload, {
  productGroupId = null,
  sellableItemGroupId = null,
  productLineId = null,
  reviewFamilyId = null,
  canonicalScope = null,
  offersCount = null,
} = {}) {
  if (!pdpPayload || typeof pdpPayload !== 'object') return pdpPayload;
  const groupId = String(productGroupId || '').trim();
  const sellableId = String(sellableItemGroupId || groupId || '').trim();
  const lineId = String(productLineId || '').trim();
  const reviewId = String(reviewFamilyId || '').trim();
  const scope = String(canonicalScope || '').trim();
  const count = Number(offersCount);
  const hasOfferCount = Number.isFinite(count) && count >= 0;
  const product = pdpPayload.product && typeof pdpPayload.product === 'object'
    ? { ...pdpPayload.product }
    : {};

  if (groupId) {
    product.product_group_id = groupId;
    if (!product.sellable_item_group_id) product.sellable_item_group_id = sellableId || groupId;
  }
  if (sellableId && !product.sellable_item_group_id) product.sellable_item_group_id = sellableId;
  if (lineId) product.product_line_id = lineId;
  if (reviewId) product.review_family_id = reviewId;
  if (scope) product.canonical_scope = scope;
  if (hasOfferCount) {
    product.offers_count = count;
    product.offer_count = count;
    product.has_multiple_offers = count > 1;
  }

  return {
    ...pdpPayload,
    ...(groupId ? { product_group_id: groupId } : {}),
    ...(sellableId ? { sellable_item_group_id: sellableId } : {}),
    ...(lineId ? { product_line_id: lineId } : {}),
    ...(reviewId ? { review_family_id: reviewId } : {}),
    ...(scope ? { canonical_scope: scope } : {}),
    ...(hasOfferCount
      ? {
          offers_count: count,
          offer_count: count,
          has_multiple_offers: count > 1,
        }
      : {}),
    product,
  };
}

// A group can carry several member rows that are really the *same* seller
// listing — e.g. multiple external_seed scrape records of one merchant
// product. Each becomes its own offer row, so the PDP seller picker shows
// "N sellers" when there is genuinely one. Collapse offers that share a
// strong identity: same merchant + same checkout URL + same price. Offers
// missing any of those signals are never deduped (kept conservatively).
function offerDedupeKey(offer) {
  const merchantId = String(offer?.merchant_id || '').trim().toLowerCase();
  const rawUrl = String(
    offer?.merchant_checkout_url ||
      offer?.external_redirect_url ||
      offer?.source_url ||
      offer?.destination_url ||
      offer?.url ||
      '',
  ).trim();
  const url = rawUrl
    .toLowerCase()
    .replace(/[?#].*$/, '')
    .replace(/\/+$/, '');
  const amount =
    offer?.price && Number.isFinite(Number(offer.price.amount)) ? Number(offer.price.amount) : null;
  const currency = String(offer?.price?.currency || '').trim().toUpperCase();
  if (!merchantId || !url || amount == null || !currency) return null;
  return `${merchantId}|${url}|${amount}|${currency}`;
}

function dedupeEquivalentOffers(offers) {
  const list = Array.isArray(offers) ? offers : [];
  if (list.length < 2) return { offers: list, removed: 0 };
  const seen = new Set();
  const result = [];
  let removed = 0;
  for (const offer of list) {
    const key = offerDedupeKey(offer);
    if (key && seen.has(key)) {
      removed += 1;
      continue;
    }
    if (key) seen.add(key);
    result.push(offer);
  }
  return { offers: result, removed };
}

function readCollapsibleInternalMerchantId(offer) {
  const merchantId = String(offer?.merchant_id || offer?.merchantId || '').trim();
  if (!merchantId || merchantId === EXTERNAL_SEED_MERCHANT_ID) return null;
  if (!isInternalOffer(offer) && !offerIsInternalCheckoutCandidate(offer)) return null;
  return merchantId.toLowerCase();
}

function compareOffersForSameMerchantCollapse(a, b) {
  const aInStock = offerHasAvailableInventory(a) ? 1 : 0;
  const bInStock = offerHasAvailableInventory(b) ? 1 : 0;
  if (aInStock !== bInStock) return bInStock - aInStock;

  const aTotal = computeOfferTotal(a);
  const bTotal = computeOfferTotal(b);
  if (aTotal !== bTotal) return aTotal < bTotal ? -1 : 1;

  return 0;
}

function collapseSameInternalMerchantOffers(offers) {
  const list = Array.isArray(offers) ? offers : [];
  if (list.length < 2) return { offers: list, removed: 0 };

  const groups = new Map();
  for (const offer of list) {
    const merchantId = readCollapsibleInternalMerchantId(offer);
    if (!merchantId) continue;

    const current = groups.get(merchantId);
    if (!current) {
      groups.set(merchantId, { best: offer, count: 1 });
      continue;
    }
    current.count += 1;
    if (compareOffersForSameMerchantCollapse(offer, current.best) < 0) {
      current.best = offer;
    }
  }

  const collapsedMerchantIds = new Set(
    Array.from(groups.entries())
      .filter(([, group]) => group.count > 1)
      .map(([merchantId]) => merchantId),
  );
  if (!collapsedMerchantIds.size) return { offers: list, removed: 0 };

  const emitted = new Set();
  const result = [];
  for (const offer of list) {
    const merchantId = readCollapsibleInternalMerchantId(offer);
    if (!merchantId || !collapsedMerchantIds.has(merchantId)) {
      result.push(offer);
      continue;
    }
    if (emitted.has(merchantId)) continue;
    emitted.add(merchantId);
    result.push(groups.get(merchantId).best);
  }

  return { offers: result, removed: list.length - result.length };
}

// Returns the survivor list, or null when the value is not a survivor list at
// all. The distinction matters: an empty array is this filter answering "every
// member is quarantined", while a missing or unparseable value is the filter
// not answering. Collapsing the second case into the first drops every offer on
// the PDP, so the caller fails open on null instead.
function parseQuarantineSurvivorMembers(value) {
  if (Array.isArray(value)) return value;
  if (typeof value === 'string' && value.trim()) {
    try {
      const parsed = JSON.parse(value);
      return Array.isArray(parsed) ? parsed : null;
    } catch (_err) {
      return null;
    }
  }
  return null;
}

async function filterGroupMembersByCatalogSourceQuarantine(members, { queryFn = query } = {}) {
  const list = Array.isArray(members) ? members : [];
  if (!list.length || !process.env.DATABASE_URL || typeof queryFn !== 'function') {
    return { members: list, filteredCount: 0 };
  }

  const requestedMembers = list.map((member, index) => ({
    merchant_id: String(member?.merchant_id || '').trim(),
    product_id: String(member?.product_id || '').trim(),
    ord: index,
  })).filter((member) => member.merchant_id && member.product_id);
  if (!requestedMembers.length) return { members: list, filteredCount: 0 };

  try {
    const result = await queryFn(
      `
        WITH requested_members AS (
          SELECT
            rm.merchant_id,
            rm.product_id,
            MIN(rm.ord)::int AS ord
          FROM jsonb_to_recordset($1::jsonb) AS rm(merchant_id text, product_id text, ord int)
          WHERE COALESCE(NULLIF(trim(rm.merchant_id), ''), '') <> ''
            AND COALESCE(NULLIF(trim(rm.product_id), ''), '') <> ''
          GROUP BY rm.merchant_id, rm.product_id
        ),
        surviving_members AS (
          SELECT DISTINCT ON (rm.merchant_id, rm.product_id)
            rm.merchant_id,
            rm.product_id,
            rm.ord
          FROM requested_members rm
          ${buildGroupMemberCatalogOfferLateralJoinSql('rm')}
          WHERE 1 = 1
            ${buildCatalogSourceQuarantineAntiJoinSql('cp_offer')}
          ORDER BY rm.merchant_id, rm.product_id, rm.ord
        )
        SELECT
          COALESCE(
            jsonb_agg(
              jsonb_build_object(
                'merchant_id', merchant_id,
                'product_id', product_id
              )
              ORDER BY ord
            ),
            '[]'::jsonb
          ) AS members
        FROM surviving_members
      `,
      [JSON.stringify(requestedMembers)],
    );
    if (!Array.isArray(result?.rows) || result.rows.length !== 1) {
      return { members: list, filteredCount: 0 };
    }
    // The aggregate below always projects a `members` column (COALESCE(...,
    // '[]'::jsonb)), so a row without one did not come from this query. Fail
    // open rather than reading "no survivor column" as "no survivors".
    const survivors = parseQuarantineSurvivorMembers(result.rows[0]?.members);
    if (!survivors) {
      logger.warn(
        { member_count: list.length },
        'Catalog source quarantine returned no survivor list; serving group members unfiltered',
      );
      return { members: list, filteredCount: 0 };
    }
    const survivingKeys = new Set(
      survivors
        .map((member) => `${String(member?.merchant_id || '').trim()}:${String(member?.product_id || '').trim()}`)
        .filter((key) => key !== ':'),
    );
    const filtered = list.filter((member) =>
      survivingKeys.has(`${String(member?.merchant_id || '').trim()}:${String(member?.product_id || '').trim()}`),
    );
    return {
      members: filtered,
      filteredCount: Math.max(0, list.length - filtered.length),
    };
  } catch (err) {
    logger.warn(
      {
        err: err?.message || String(err),
        member_count: list.length,
      },
      'Failed to apply catalog source quarantine to PDP group members',
    );
    return { members: list, filteredCount: 0 };
  }
}

async function buildOffersFromGroupMembers(args) {
  const totalStartedAt = Date.now();
  const timings = {};
  const productGroupId = args?.productGroupId ? String(args.productGroupId).trim() : null;
  const groupMembers = Array.isArray(args?.members) ? args.members : [];
  const checkoutToken = args?.checkoutToken;
  const bypassCache = args?.bypassCache === true;
  const limit = Math.min(Math.max(1, Number(args?.limit || groupMembers.length || 10) || 10), 50);
  const preferredMerchantId = args?.preferredMerchantId ? String(args.preferredMerchantId).trim() : null;
  const preferredProductId = args?.preferredProductId ? String(args.preferredProductId).trim() : null;
  const debug = args?.debug === true;
  const prefetchedProductByKey = buildPrefetchedOfferProductMap(args?.prefetchedProducts);

  if (!groupMembers.length) return null;
  timings.setup = Date.now() - totalStartedAt;

  const normalizedMembers = groupMembers
    .map((m) => {
      const merchantId = String(m?.merchant_id || m?.merchantId || '').trim();
      const sourceKind = firstNonEmptyString(
        m?.source_kind,
        m?.sourceKind,
        merchantId === EXTERNAL_SEED_MERCHANT_ID ? EXTERNAL_SEED_MERCHANT_ID : '',
      );
      return {
        merchant_id: merchantId,
        merchant_name: m?.merchant_name || m?.merchantName || undefined,
        product_id: String(m?.product_id || m?.productId || '').trim(),
        platform: m?.platform ? String(m.platform).trim() : undefined,
        source_listing_ref: m?.source_listing_ref || m?.sourceListingRef || undefined,
        source_kind: sourceKind || undefined,
        source_tier: m?.source_tier || m?.sourceTier || undefined,
        source_payload:
          m?.source_payload && typeof m.source_payload === 'object'
            ? m.source_payload
            : m?.sourcePayload && typeof m.sourcePayload === 'object'
              ? m.sourcePayload
              : undefined,
        variant_axes: m?.variant_axes && typeof m.variant_axes === 'object' ? m.variant_axes : undefined,
        is_primary: Boolean(m?.is_primary || m?.isPrimary),
      };
    })
    .filter((m) => Boolean(m.merchant_id) && Boolean(m.product_id))
    .slice(0, limit);

  const quarantineFilterResult = normalizedMembers.length > 1
    ? await filterGroupMembersByCatalogSourceQuarantine(
        normalizedMembers,
        { queryFn: args?.queryFn || query },
      )
    : { members: normalizedMembers, filteredCount: 0 };
  const members = quarantineFilterResult.members;
  const sourceQuarantineFilteredCount = quarantineFilterResult.filteredCount;
  if (!members.length) {
    // Returning null here drops the whole offers module, and `filteredCount` is
    // only ever surfaced in the debug diagnostics built further down — so
    // without this line "quarantine suppressed every offer" is indistinguishable
    // in prod logs from "this product has no offers".
    logger.warn(
      {
        product_group_id: productGroupId,
        requested_member_count: normalizedMembers.length,
        source_quarantine_filtered_count: sourceQuarantineFilteredCount,
      },
      'PDP offer group emptied before build; offers module will be omitted',
    );
    return null;
  }

  const canonicalMember = members.find((m) => m.is_primary) || members[0] || null;
  const canonicalProductRef = canonicalMember
    ? {
        merchant_id: canonicalMember.merchant_id,
        product_id: canonicalMember.product_id,
        ...(canonicalMember.platform ? { platform: canonicalMember.platform } : {}),
      }
    : null;

  const merchantNameById = new Map(
    members
      .map((m) => [String(m.merchant_id || '').trim(), m.merchant_name])
      .filter(([mid, name]) => Boolean(mid) && Boolean(name)),
  );
  const merchantProfileNameLookupEnabled =
    String(process.env.PDP_OFFER_MERCHANT_NAME_LOOKUP_ENABLED || 'true').toLowerCase() !== 'false';
  const merchantProfileNameById = merchantProfileNameLookupEnabled
    ? await fetchMerchantDisplayNamesByIds(
        members
          .filter((m) => {
            const mid = String(m?.merchant_id || '').trim();
            return mid && mid !== EXTERNAL_SEED_MERCHANT_ID && !merchantNameById.has(mid);
          })
          .map((m) => m.merchant_id),
      )
    : new Map();

  const fetched = [];
  const buildSourceStats = {
    identity_payload: 0,
    prefetched: 0,
    fetched: 0,
    hydrated: 0,
    unresolved: 0,
  };
  const unresolvedMembers = [];
  const memberFetchDiagnostics = [];
  const fetchProductsStartedAt = Date.now();
  const chunkSize = 4;
  for (let i = 0; i < members.length; i += chunkSize) {
    const chunk = members.slice(i, i + chunkSize);
    // eslint-disable-next-line no-await-in-loop
    const results = await Promise.all(
      chunk.map(async (m) => {
        const memberStartedAt = Date.now();
        let source = 'unresolved';
        let fetchError = null;
        const prefetchedProduct =
          prefetchedProductByKey.get(`${m.merchant_id}:${m.product_id}`) || null;
        const memberPayloadProduct = buildExternalSeedOfferProductFromMember(m);
        const usedPrefetchedProduct = Boolean(prefetchedProduct);
        const memberIsExternalSeed = memberIsExternalSeedSupply(m);
        const memberPayloadCarriesCatalogOfferTruth = Boolean(
          memberIsExternalSeed &&
          memberPayloadProduct &&
          m.source_payload &&
          typeof m.source_payload === 'object' &&
          !Array.isArray(m.source_payload) &&
          m.source_payload.catalog_offer_v1 &&
          typeof m.source_payload.catalog_offer_v1 === 'object',
        );
        const prefersFreshExternalSeedProduct =
          memberIsExternalSeed && !memberPayloadCarriesCatalogOfferTruth;
        if (memberPayloadProduct && !prefersFreshExternalSeedProduct) {
          buildSourceStats.identity_payload += 1;
          source = 'identity_payload';
        } else if (usedPrefetchedProduct) {
          buildSourceStats.prefetched += 1;
          source = 'prefetched';
        }
        const fetchedProductPromise = () =>
          fetchProductDetailForOffers({
            merchantId: m.merchant_id,
            productId: m.product_id,
            checkoutToken,
            bypassCache,
            skipUpstreamFallback: memberIsExternalSeed,
            timeoutMs: PDP_OFFER_GROUP_MEMBER_FETCH_TIMEOUT_MS,
            totalTimeoutMs: PDP_OFFER_GROUP_MEMBER_FETCH_TIMEOUT_MS,
            noRetry: true,
          }).catch((err) => {
            fetchError = err;
            return null;
          });
        const product = prefersFreshExternalSeedProduct
          ? prefetchedProduct || (await fetchedProductPromise()) || memberPayloadProduct
          : memberPayloadProduct || prefetchedProduct || (await fetchedProductPromise());
        if (
          !memberPayloadProduct &&
          !usedPrefetchedProduct &&
          product
        ) {
          buildSourceStats.fetched += 1;
          source = getProductDetailSource(product) || 'fetched';
        } else if (
          prefersFreshExternalSeedProduct &&
          !usedPrefetchedProduct &&
          product &&
          product !== memberPayloadProduct
        ) {
          buildSourceStats.fetched += 1;
          source = getProductDetailSource(product) || 'fetched';
        } else if (prefersFreshExternalSeedProduct && product && product === memberPayloadProduct) {
          buildSourceStats.identity_payload += 1;
          source = 'identity_payload_fallback';
        }
        if (!product) {
          buildSourceStats.unresolved += 1;
          unresolvedMembers.push({
            merchant_id: m.merchant_id,
            product_id: m.product_id,
            source_kind: m.source_kind || null,
            reason:
              fetchError?.code === 'STAGE_TIMEOUT'
                ? 'member_fetch_budget_exceeded'
                : fetchError
                  ? 'member_fetch_failed'
                  : 'member_unavailable',
            ...(fetchError?.stage ? { stage: fetchError.stage } : {}),
          });
        }
        const hydratedProduct =
          !product || memberIsExternalSeed || usedPrefetchedProduct
            ? product
            : await hydrateSavingsPresentationFromUpstream({
                product,
                checkoutToken,
              }).catch(() => product);
        if (
          product &&
          hydratedProduct &&
          !memberIsExternalSeed &&
          !usedPrefetchedProduct
        ) {
          buildSourceStats.hydrated += 1;
          source = source === 'fetched' ? 'hydrated' : source;
        }
        memberFetchDiagnostics.push({
          merchant_id: m.merchant_id,
          product_id: m.product_id,
          source,
          duration_ms: Math.max(0, Date.now() - memberStartedAt),
          ...(fetchError?.code ? { error_code: fetchError.code } : {}),
          ...(fetchError?.stage ? { stage: fetchError.stage } : {}),
        });
        return hydratedProduct ? { member: m, product: hydratedProduct } : null;
      }),
    );
    fetched.push(...results.filter(Boolean));
  }
  timings.fetch_products = Date.now() - fetchProductsStartedAt;

  const transactionHeldOfferCount = fetched.filter((entry) => hasOfferProductTransactionHold(entry.product)).length;
  const offerEligibleFetched = fetched.filter((entry) => !hasOfferProductTransactionHold(entry.product));
  const products = offerEligibleFetched.map((entry) => entry.product).filter(Boolean);
  if (!products.length) return null;

  const resolvedProductGroupId =
    productGroupId ||
    (canonicalProductRef?.platform
      ? buildProductGroupId({
          platform: String(canonicalProductRef.platform || '').trim(),
          platform_product_id: String(
            products[0]?.platform_product_id || products[0]?.platformProductId || '',
          ).trim(),
        })
      : null) ||
    (products[0]?.platform
      ? buildProductGroupId({
          platform: String(products[0].platform || '').trim(),
          platform_product_id: String(products[0].platform_product_id || products[0].platformProductId || '').trim(),
        })
      : null) ||
    `pg:pid:${String(canonicalProductRef?.product_id || products[0]?.product_id || products[0]?.id || '').trim()}`;

  const buildOfferRowsStartedAt = Date.now();
  const offers = offerEligibleFetched.map(({ member, product: p }) => {
    const mid = String(p.merchant_id || '').trim();
    const offerSourceKind = firstNonEmptyString(
      member?.source_kind,
      p.source_kind,
      p.sourceKind,
      mid === EXTERNAL_SEED_MERCHANT_ID ? EXTERNAL_SEED_MERCHANT_ID : '',
    );
    const offerProductId = String(p.product_id || '').trim() || undefined;
    const selectedVariant = findOfferVariantForAxes(p, member?.variant_axes);
    const selectedVariantId = selectedVariant ? getOfferVariantId(selectedVariant) : null;
    const selectedVariantSku = selectedVariant ? getOfferVariantSku(selectedVariant) : null;
    const selectedOptions = selectedVariant ? extractVariantOptions(selectedVariant) : {};
    const selectedVariantPrice =
      selectedVariant?.price ??
      selectedVariant?.price_amount ??
      selectedVariant?.priceAmount ??
      selectedVariant?.pricing?.current?.amount ??
      selectedVariant?.pricing?.amount ??
      null;
    const selectedVariantPriceAmount = readPriceAmountForNormalization(selectedVariantPrice);
    const productPrice =
      p.price ??
      p.price_amount ??
      p.priceAmount ??
      p.pricing?.current?.amount ??
      p.pricing?.amount ??
      null;
    const currency =
      firstNonEmptyString(
        selectedVariant?.currency,
        selectedVariant?.price?.currency,
        selectedVariant?.price?.current?.currency,
        p.currency,
        p.price?.currency,
        p.price?.current?.currency,
        'USD',
      ) || 'USD';
    const shipCost = p.shipping?.cost || p.shipping_cost || null;
    const shipCostAmount =
      shipCost == null
        ? undefined
        : Number(typeof shipCost === 'object' ? shipCost.amount : shipCost);
    const shipCostCurrency =
      shipCost && typeof shipCost === 'object'
        ? String(shipCost.currency || currency)
        : currency;
    const etaRaw = p.shipping?.eta_days_range || p.shipping?.etaDaysRange || null;
    const etaRange =
      Array.isArray(etaRaw) && etaRaw.length >= 2
        ? [Number(etaRaw[0]) || 0, Number(etaRaw[1]) || 0]
        : undefined;
    const offerVariants = buildOfferVariantsForPayload(p, currency);
    const savingsPresentationFields = {
      ...pickSavingsPresentationFields(p),
      ...pickSavingsPresentationFields(selectedVariant),
    };
    const commerceFacts = p.commerce_facts_v1 || p.commerce_facts || null;
    const agentSafeCommerceFacts =
      p.agent_safe_commerce_facts ||
      (commerceFacts ? buildAgentSafeCommerceFacts(commerceFacts) : null);
    const offerPrice = normalizeOfferMoneyForProduct(
      Number.isFinite(selectedVariantPriceAmount) && selectedVariantPriceAmount > 0
        ? selectedVariantPrice
        : productPrice,
      currency,
      p,
      selectedVariant,
    );

    return {
      offer_id:
        buildOfferId({
          merchant_id: mid,
          product_group_id: resolvedProductGroupId,
          fulfillment_type: p.fulfillment_type || 'merchant',
          tier: 'default',
          ...(mid === 'external_seed' && offerProductId
            ? { offer_discriminator: offerProductId }
            : {}),
        }) ||
        `of:v1:${mid}:${resolvedProductGroupId}:${p.fulfillment_type || 'merchant'}:default`,
      product_group_id: resolvedProductGroupId,
      product_id: offerProductId,
      merchant_id: mid,
      merchant_name:
        resolveOfferSellerDisplayName({
          product: p,
          member: {
            ...member,
            merchant_name:
              member?.merchant_name ||
              merchantNameById.get(mid) ||
              merchantProfileNameById.get(mid),
          },
          merchantId: mid,
        }) || undefined,
      ...(offerPrice ? { price: offerPrice } : {}),
      shipping:
        p.shipping || etaRange || shipCostAmount != null
          ? {
              method_label: p.shipping?.method_label || p.shipping?.methodLabel || undefined,
              eta_days_range: etaRange,
              ...(shipCostAmount != null && Number.isFinite(shipCostAmount)
                ? { cost: normalizeOfferMoney(shipCostAmount, shipCostCurrency) }
                : {}),
            }
          : undefined,
      returns: p.returns || undefined,
      inventory: {
        in_stock:
          typeof selectedVariant?.in_stock === 'boolean'
            ? selectedVariant.in_stock
            : typeof selectedVariant?.available === 'boolean'
              ? selectedVariant.available
              : typeof p.in_stock === 'boolean'
                ? p.in_stock
                : undefined,
      },
      fulfillment_type: p.fulfillment_type || undefined,
      ...(selectedVariantId ? { variant_id: selectedVariantId, selected_variant_id: selectedVariantId } : {}),
      ...(selectedVariantSku ? { sku_id: selectedVariantSku, sku: selectedVariantSku } : {}),
      ...(Object.keys(selectedOptions).length ? { selected_options: selectedOptions } : {}),
      ...(selectedVariant?.title ? { variant_title: String(selectedVariant.title).trim() } : {}),
      ...(offerVariants.length ? { variants: offerVariants } : {}),
      ...savingsPresentationFields,
      ...(p.source ? { source: p.source } : {}),
      ...(p.source_url || p.canonical_url || p.destination_url || p.url
        ? { source_url: p.source_url || p.canonical_url || p.destination_url || p.url }
        : {}),
      ...(p.availability ? { availability: p.availability } : {}),
      ...(Array.isArray(p.promotions) && p.promotions.length ? { promotions: p.promotions } : {}),
      ...(commerceFacts ? { commerce_facts_v1: commerceFacts, commerce_facts: commerceFacts } : {}),
      ...(agentSafeCommerceFacts ? { agent_safe_commerce_facts: agentSafeCommerceFacts } : {}),
      ...(offerSourceKind ? { source_kind: offerSourceKind } : {}),
      ...(member?.source_tier ? { source_tier: member.source_tier } : {}),
      ...buildOfferPurchaseMetadataFromProduct(p),
      risk_tier: 'standard',
    };
  });
  timings.build_offer_rows = Date.now() - buildOfferRowsStartedAt;

  const { offers: dedupedOffers, removed: dedupedOfferCount } = dedupeEquivalentOffers(offers);
  const {
    offers: merchantCollapsedOffers,
    removed: sameMerchantCollapsedOfferCount,
  } = collapseSameInternalMerchantOffers(dedupedOffers);

  const sortStartedAt = Date.now();
  const annotatedOffers = annotateOffersWithCommerceMetadata(merchantCollapsedOffers);
  const prioritizedOffers = prioritizeOffers(annotatedOffers);
  const sortedByTotal = [...annotatedOffers].sort((a, b) => {
    const aTotal = computeOfferTotal(a);
    const bTotal = computeOfferTotal(b);
    if (aTotal === bTotal) return 0;
    return aTotal < bTotal ? -1 : 1;
  });
  const bestPriceOfferId = sortedByTotal[0]?.offer_id || null;
  const preferredOffer =
    (preferredProductId
      ? prioritizedOffers.find(
          (offer) =>
            String(offer?.product_id || '').trim() === preferredProductId &&
            (!preferredMerchantId || String(offer?.merchant_id || '').trim() === preferredMerchantId),
        )
      : null) ||
    (preferredMerchantId
      ? prioritizedOffers.find((offer) => String(offer?.merchant_id || '').trim() === preferredMerchantId)
      : null);
  const defaultOfferId = preferredOffer?.offer_id || pickDefaultOfferId(prioritizedOffers) || bestPriceOfferId;
  timings.sort = Date.now() - sortStartedAt;
  timings.total = Date.now() - totalStartedAt;

  return {
    status: 'success',
    product_group_id: resolvedProductGroupId,
    canonical_product_ref: canonicalProductRef,
    offers_count: merchantCollapsedOffers.length,
    offers: prioritizedOffers,
    default_offer_id: defaultOfferId,
    best_price_offer_id: bestPriceOfferId,
    ...(debug
      ? {
          diagnostics: {
            build_sources: buildSourceStats,
            timings_ms: timings,
            unresolved_members: unresolvedMembers,
            member_fetches: memberFetchDiagnostics,
            merchant_name_lookup_enabled: merchantProfileNameLookupEnabled,
            deduped_offer_count: dedupedOfferCount,
            same_merchant_collapsed_offer_count: sameMerchantCollapsedOfferCount,
            transaction_held_offer_count: transactionHeldOfferCount,
            source_quarantine_filtered_count: sourceQuarantineFilteredCount,
          },
        }
      : {}),
  };
}

// --- Currency helpers (Creator cache surfaces) ---
// Creator feeds/search can be served directly from products_cache for speed.
// For Shopify stores, product_data prices are in the shop currency, but some
// legacy cache rows can have currency mislabeled as USD. Fix labels in-flight
// using shop.json, cached per merchant to avoid repeated Shopify calls.
const SHOPIFY_MERCHANT_CURRENCY_CACHE = new Map(); // merchant_id -> { currency, expiresAtMs }
const SHOPIFY_MERCHANT_CURRENCY_TTL_MS = 6 * 60 * 60 * 1000;
const SHOPIFY_MERCHANT_CURRENCY_NEG_TTL_MS = 10 * 60 * 1000;

function getCachedShopifyMerchantCurrency(merchantId) {
  const mid = String(merchantId || '').trim();
  if (!mid) return null;
  const hit = SHOPIFY_MERCHANT_CURRENCY_CACHE.get(mid);
  if (!hit) return null;
  if (hit.expiresAtMs && hit.expiresAtMs < Date.now()) {
    SHOPIFY_MERCHANT_CURRENCY_CACHE.delete(mid);
    return null;
  }
  return hit.currency || null;
}

function setCachedShopifyMerchantCurrency(merchantId, currency, ttlMs = SHOPIFY_MERCHANT_CURRENCY_TTL_MS) {
  const mid = String(merchantId || '').trim();
  const cur = String(currency || '').trim().toUpperCase();
  if (!mid) return;
  SHOPIFY_MERCHANT_CURRENCY_CACHE.set(mid, {
    currency: cur || null,
    expiresAtMs: Date.now() + (Number(ttlMs) > 0 ? Number(ttlMs) : SHOPIFY_MERCHANT_CURRENCY_TTL_MS),
  });
}

function parseShopifyAccessToken(apiKeyRaw) {
  if (!apiKeyRaw) return '';
  const raw = String(apiKeyRaw).trim();
  if (!raw) return '';
  if (!raw.startsWith('{')) return raw;
  try {
    const parsed = JSON.parse(raw);
    if (parsed && typeof parsed === 'object') {
      const token = parsed.access_token || parsed.token || '';
      return String(token || '').trim();
    }
  } catch (_) {
    // ignore
  }
  return raw;
}

async function fetchShopifyMerchantCurrency(merchantId) {
  const cached = getCachedShopifyMerchantCurrency(merchantId);
  if (cached) return cached;

  if (!process.env.DATABASE_URL) return null;

  const mid = String(merchantId || '').trim();
  if (!mid) return null;

  let storeRow;
  try {
    const res = await query(
      `
        SELECT domain, api_key
        FROM merchant_stores
        WHERE merchant_id = $1
          AND platform = 'shopify'
          AND status IN ('active', 'connected')
        ORDER BY connected_at DESC NULLS LAST
        LIMIT 1
      `,
      [mid],
    );
    storeRow = res.rows && res.rows[0] ? res.rows[0] : null;
  } catch (err) {
    logger.warn({ err: err.message, merchantId: mid }, 'Failed to query merchant_stores for Shopify currency');
    return null;
  }

  const domain = storeRow && storeRow.domain ? String(storeRow.domain).trim() : '';
  const accessToken = parseShopifyAccessToken(storeRow && storeRow.api_key ? storeRow.api_key : '');

  if (!domain || !accessToken) {
    setCachedShopifyMerchantCurrency(mid, null, SHOPIFY_MERCHANT_CURRENCY_NEG_TTL_MS);
    return null;
  }

  try {
    const url = `https://${domain}/admin/api/2024-07/shop.json`;
    const resp = await axios.get(url, {
      headers: {
        'X-Shopify-Access-Token': accessToken,
        'Content-Type': 'application/json',
      },
      timeout: 8000,
      validateStatus: () => true,
    });

    if (resp.status !== 200) {
      setCachedShopifyMerchantCurrency(mid, null, SHOPIFY_MERCHANT_CURRENCY_NEG_TTL_MS);
      return null;
    }

    const cur = String(resp.data && resp.data.shop && resp.data.shop.currency ? resp.data.shop.currency : '')
      .trim()
      .toUpperCase();
    if (!cur) {
      setCachedShopifyMerchantCurrency(mid, null, SHOPIFY_MERCHANT_CURRENCY_NEG_TTL_MS);
      return null;
    }

    setCachedShopifyMerchantCurrency(mid, cur, SHOPIFY_MERCHANT_CURRENCY_TTL_MS);
    return cur;
  } catch (err) {
    logger.warn({ err: err.message, merchantId: mid }, 'Failed to fetch Shopify shop currency');
    setCachedShopifyMerchantCurrency(mid, null, SHOPIFY_MERCHANT_CURRENCY_NEG_TTL_MS);
    return null;
  }
}

async function applyShopifyCurrencyOverride(products) {
  if (!Array.isArray(products) || products.length === 0) return products;

  const merchantIds = new Set();
  for (const p of products) {
    if (!p) continue;
    const platform = String(p.platform || '').toLowerCase();
    if (platform !== 'shopify') continue;
    const cur = String(p.currency || '').trim().toUpperCase();
    // Only bother when the label is missing or looks like a legacy USD default.
    if (cur && cur !== 'USD') continue;
    const mid = String(p.merchant_id || p.merchantId || '').trim();
    if (mid) merchantIds.add(mid);
  }

  if (merchantIds.size === 0) return products;

  const mids = Array.from(merchantIds);
  const currencies = await Promise.all(mids.map((mid) => fetchShopifyMerchantCurrency(mid)));
  const currencyByMerchant = new Map();
  mids.forEach((mid, idx) => {
    const cur = currencies[idx];
    if (cur) currencyByMerchant.set(mid, cur);
  });

  if (currencyByMerchant.size === 0) return products;

  for (const p of products) {
    if (!p) continue;
    const platform = String(p.platform || '').toLowerCase();
    if (platform !== 'shopify') continue;
    const mid = String(p.merchant_id || p.merchantId || '').trim();
    const cur = currencyByMerchant.get(mid);
    if (!cur) continue;
    p.currency = cur;
  }

  return products;
}

async function probeCreatorCacheDbStats(merchantIds, intentTarget = 'unknown', options = {}) {
  const force = options && options.force === true;
  if (!force && !ROUTE_DEBUG_ENABLED) return null;
  if (!process.env.DATABASE_URL) return { db_configured: false };
  if (!Array.isArray(merchantIds) || merchantIds.length === 0) return { db_configured: true, merchant_ids_count: 0 };

  const baseWhere = `
    merchant_id = ANY($1)
    AND (expires_at IS NULL OR expires_at > now())
    AND ${buildSellableStatusPredicate("product_data->>'status'")}
    AND COALESCE(lower(product_data->>'orderable'), 'true') <> 'false'
  `;

  const pet = buildPetSignalSql(2);
  const petWhere = intentTarget === 'pet' ? ` AND ${pet.sql}` : '';
  const petParams = intentTarget === 'pet' ? pet.params : [];

  try {
    const [allRes, sellableRes, petRes, embRes] = await Promise.all([
      query(
        `SELECT COUNT(*)::int AS c FROM products_cache WHERE merchant_id = ANY($1) AND ${activeProductsCacheSourceWhere('products_cache')}`,
        [merchantIds],
      ),
      query(`SELECT COUNT(*)::int AS c FROM products_cache WHERE ${baseWhere}`, [merchantIds]),
      intentTarget === 'pet'
        ? query(
            `SELECT COUNT(*)::int AS c FROM products_cache WHERE ${baseWhere}${petWhere}`,
            [merchantIds, ...petParams],
          )
        : Promise.resolve({ rows: [{ c: null }] }),
      query(
        `SELECT COUNT(*)::int AS c FROM products_cache_embeddings_fallback WHERE merchant_id = ANY($1)`,
        [merchantIds],
      ),
    ]);

    return {
      db_configured: true,
      merchant_ids_count: merchantIds.length,
      products_cache_total: Number(allRes.rows?.[0]?.c || 0),
      products_cache_sellable_total: Number(sellableRes.rows?.[0]?.c || 0),
      products_cache_pet_signal_sellable_total:
        intentTarget === 'pet' ? Number(petRes.rows?.[0]?.c || 0) : null,
      embeddings_fallback_total: Number(embRes.rows?.[0]?.c || 0),
    };
  } catch (err) {
    return {
      db_configured: true,
      merchant_ids_count: merchantIds.length,
      error: String(err && err.message ? err.message : err),
    };
  }
}

function uniqueStrings(values) {
  const out = [];
  const seen = new Set();
  for (const v of values || []) {
    const s = String(v || '').trim();
    if (!s) continue;
    if (seen.has(s)) continue;
    seen.add(s);
    out.push(s);
  }
  return out;
}

function getCreatorCatalogMerchantIds() {
  const all = [];
  for (const cfg of CREATOR_CONFIGS || []) {
    if (Array.isArray(cfg.merchantIds)) {
      for (const mid of cfg.merchantIds) all.push(mid);
    }
  }
  return uniqueStrings(all);
}

function getCatalogSyncMerchantIdsFromEnv() {
  const raw = String(
    process.env.CATALOG_SYNC_MERCHANT_IDS ||
      process.env.CREATOR_CATALOG_MERCHANT_IDS ||
      '',
  ).trim();
  if (!raw) return [];
  return uniqueStrings(raw.split(','));
}

async function discoverCatalogSyncMerchantIdsFromDb(limit = 5000) {
  if (!process.env.DATABASE_URL) return { merchantIds: [], source: 'db_not_configured' };
  const normalizedLimit = Math.min(Math.max(1, Number(limit || 5000)), 5000);
  const allowRelaxedFallback =
    String(process.env.CATALOG_SYNC_DISCOVERY_RELAXED || '').trim().toLowerCase() === 'true';

  try {
    const activeStoresRes = await query(
      `
        SELECT DISTINCT merchant_id, lower(COALESCE(platform, '')) AS platform
        FROM merchant_stores
        WHERE COALESCE(NULLIF(trim(merchant_id), ''), '') <> ''
          AND lower(COALESCE(platform, '')) IN ('shopify', 'wix')
          AND lower(COALESCE(status, '')) = 'active'
          AND COALESCE(NULLIF(trim(domain), ''), '') <> ''
          AND COALESCE(NULLIF(trim(api_key), ''), '') <> ''
        ORDER BY merchant_id ASC, platform ASC
        LIMIT $1
      `,
      [normalizedLimit],
    );
    const activeStoreTargets = [];
    const seenTargets = new Set();
    for (const row of activeStoresRes.rows || []) {
      const merchantId = String(row?.merchant_id || '').trim();
      const platform = String(row?.platform || '').trim().toLowerCase();
      if (!merchantId || !platform) continue;
      const key = `${merchantId}:${platform}`;
      if (seenTargets.has(key)) continue;
      seenTargets.add(key);
      activeStoreTargets.push({ merchant_id: merchantId, platform });
    }
    const activeStoreMerchantIds = uniqueStrings(activeStoreTargets.map((target) => target.merchant_id));
    if (activeStoreTargets.length) {
      return {
        merchantIds: activeStoreMerchantIds,
        targets: activeStoreTargets,
        source: 'merchant_stores_active_platforms',
      };
    }
  } catch (err) {
    logger.warn(
      { err: err?.message || String(err) },
      'Catalog sync merchant discovery via merchant_stores failed',
    );
  }

  if (!allowRelaxedFallback) {
    return { merchantIds: [], source: 'merchant_stores_empty' };
  }

  try {
    const onboardingRes = await query(
      `
        SELECT DISTINCT merchant_id
        FROM merchant_onboarding
        WHERE COALESCE(NULLIF(trim(merchant_id), ''), '') <> ''
          AND lower(COALESCE(status, '')) = 'approved'
          AND ${transactionCapableMerchantWhere('merchant_onboarding')}
        ORDER BY merchant_id ASC
        LIMIT $1
      `,
      [normalizedLimit],
    );
    const onboardingMerchantIds = uniqueStrings(
      (onboardingRes.rows || []).map((row) => row?.merchant_id),
    );
    if (onboardingMerchantIds.length) {
      return { merchantIds: onboardingMerchantIds, source: 'merchant_onboarding_relaxed' };
    }
  } catch (err) {
    logger.warn(
      { err: err?.message || String(err) },
      'Catalog sync merchant discovery via merchant_onboarding failed in relaxed mode',
    );
  }

  try {
    const cacheRes = await query(
      `
        SELECT DISTINCT merchant_id
        FROM products_cache
        WHERE COALESCE(NULLIF(trim(merchant_id), ''), '') <> ''
          AND merchant_id <> 'external_seed'
          AND ${activeProductsCacheSourceWhere('products_cache')}
        ORDER BY merchant_id ASC
        LIMIT $1
      `,
      [normalizedLimit],
    );
    const cacheMerchantIds = uniqueStrings(
      (cacheRes.rows || []).map((row) => row?.merchant_id),
    );
    if (cacheMerchantIds.length) {
      return { merchantIds: cacheMerchantIds, source: 'products_cache_relaxed' };
    }
  } catch (err) {
    logger.warn(
      { err: err?.message || String(err) },
      'Catalog sync merchant discovery via products_cache failed in relaxed mode',
    );
  }

  return { merchantIds: [], source: 'db_empty_relaxed' };
}

async function resolveCatalogSyncMerchantIds() {
  const envMerchantIds = getCatalogSyncMerchantIdsFromEnv();
  if (envMerchantIds.length) {
    return { merchantIds: envMerchantIds, source: 'env' };
  }

  const discovered = await discoverCatalogSyncMerchantIdsFromDb();
  if (discovered.merchantIds.length) return discovered;

  const creatorMerchantIds = getCreatorCatalogMerchantIds();
  if (creatorMerchantIds.length) {
    return { merchantIds: creatorMerchantIds, source: 'creator_configs_fallback' };
  }

  return { merchantIds: [], source: discovered.source || 'none' };
}

const catalogSyncState = {
  last_run_at: null,
  last_success_at: null,
  last_error: null,
  per_merchant: {},
  target_source: null,
  target_count: 0,
  target_eligible_count: 0,
  target_suppressed_count: 0,
  target_sample: [],
  target_suppressed_sample: [],
};

function isCatalogSyncRetryableError(err) {
  const status = Number(err?.response?.status || 0);
  if (status === 429 || status >= 500) return true;

  const code = String(err?.code || '').trim().toUpperCase();
  if (
    code === 'ECONNABORTED' ||
    code === 'ETIMEDOUT' ||
    code === 'ECONNRESET' ||
    code === 'EAI_AGAIN'
  ) {
    return true;
  }

  const message = String(err?.message || '').trim().toLowerCase();
  return message.includes('timeout') || message.includes('timed out');
}

function getCatalogSyncErrorText(err) {
  const data = err?.response?.data;
  const candidates = [
    data?.detail?.message,
    data?.detail?.error,
    data?.detail,
    data?.error?.message,
    data?.error,
    err?.message,
  ];
  if (data && typeof data === 'object') {
    try {
      candidates.push(JSON.stringify(data));
    } catch (_) {
      // Best-effort diagnostics only.
    }
  }
  return candidates
    .filter((value) => value !== undefined && value !== null)
    .map((value) => (typeof value === 'string' ? value : JSON.stringify(value)))
    .filter(Boolean)
    .join(' ')
    .trim()
    .toLowerCase();
}

function isCatalogSyncCanonicalIngestFailure(err) {
  const message = getCatalogSyncErrorText(err);
  if (!message) return false;
  if (message.includes('canonical catalog ingest failed')) return true;
  if (message.includes('textclause')) return true;
  if (message.includes('object has no attribute') && message.includes('values')) return true;
  return false;
}

function isCatalogSyncNonRetryableError(err) {
  const status = Number(err?.response?.status || 0);
  if (status === 400 || status === 401 || status === 403 || status === 404) return true;
  if (isCatalogSyncCanonicalIngestFailure(err)) return true;
  if (isCatalogSyncTimeoutError(err)) return true;

  const detailStatus = Number(
    err?.response?.data?.status ||
      err?.response?.data?.error?.status ||
      err?.response?.data?.detail?.status ||
      0,
  );
  if (detailStatus === 400 || detailStatus === 401 || detailStatus === 403 || detailStatus === 404) {
    return true;
  }

  const code = String(err?.code || '').trim().toUpperCase();
  if (code === 'ENOTFOUND') return true;

  const message = getCatalogSyncErrorText(err);
  if (!message) return false;
  if (message.includes('shopify api error: 404')) return true;
  if (message.includes('\"errors\":\"not found\"')) return true;
  if (message.includes("errors':'not found")) return true;
  if (message.includes('shopify') && message.includes('not found')) return true;
  return false;
}

function isCatalogSyncInvalidMerchantError(err) {
  const status = Number(err?.response?.status || 0);
  if (status === 400 || status === 401 || status === 403 || status === 404) return true;

  const detailStatus = Number(
    err?.response?.data?.status ||
      err?.response?.data?.error?.status ||
      err?.response?.data?.detail?.status ||
      0,
  );
  if (detailStatus === 400 || detailStatus === 401 || detailStatus === 403 || detailStatus === 404) {
    return true;
  }

  const message = String(
    err?.response?.data?.detail?.message ||
      err?.response?.data?.detail ||
      err?.response?.data?.error?.message ||
      err?.message ||
      '',
  )
    .trim()
    .toLowerCase();
  if (!message) return false;
  if (message.includes('shopify api error: 404')) return true;
  if (message.includes('\"errors\":\"not found\"')) return true;
  if (message.includes("errors':'not found")) return true;
  if (message.includes('shopify') && message.includes('not found')) return true;
  if (message.includes('invalid api key')) return true;
  if (message.includes('access denied')) return true;
  if (message.includes('unauthorized')) return true;
  if (message.includes('forbidden')) return true;
  return false;
}

function isCatalogSyncTimeoutError(err) {
  const code = String(err?.code || '').trim().toUpperCase();
  if (
    code === 'ECONNABORTED' ||
    code === 'ETIMEDOUT' ||
    code === 'ECONNRESET' ||
    code === 'EAI_AGAIN'
  ) {
    return true;
  }
  const message = String(err?.message || '').trim().toLowerCase();
  return message.includes('timeout') || message.includes('timed out');
}

function getCatalogSyncAttemptTimeoutMs({ merchantState, attempt }) {
  const timeoutStreak = Math.max(0, Number(merchantState?.timeout_streak || 0));
  const attemptIndex = Math.max(0, Number(attempt || 1) - 1);
  const growth = Math.min(timeoutStreak + attemptIndex, 3);
  const multiplier = Math.pow(2, growth);
  const baseTimeoutMs = Number(CREATOR_CATALOG_AUTO_SYNC_TIMEOUT_MS || 0);
  const maxTimeoutMs = Number(CREATOR_CATALOG_AUTO_SYNC_TIMEOUT_MAX_MS || baseTimeoutMs);
  return Math.max(
    baseTimeoutMs,
    Math.min(maxTimeoutMs, Math.floor(baseTimeoutMs * multiplier)),
  );
}

function getCatalogSyncSuppressionStatus(merchantId, nowMs = Date.now()) {
  const state = catalogSyncState.per_merchant[merchantId];
  const blockedUntilMs = Number(state?.blocked_until_ms || 0);
  if (!blockedUntilMs || blockedUntilMs <= nowMs) {
    return {
      suppressed: false,
      reason: null,
      blocked_until: null,
      invalid_merchant: false,
    };
  }
  return {
    suppressed: true,
    reason: state?.invalid_merchant ? 'invalid_merchant_cooldown' : 'non_retryable_cooldown',
    blocked_until: state?.blocked_until || new Date(blockedUntilMs).toISOString(),
    invalid_merchant: state?.invalid_merchant === true,
  };
}

function normalizeCatalogSyncTargets(target) {
  const rawTargets = Array.isArray(target?.targets) ? target.targets : [];
  const sourceMerchantIds = Array.isArray(target?.merchantIds) ? target.merchantIds : [];
  const out = [];
  const seen = new Set();

  for (const raw of rawTargets) {
    const merchantId = String(raw?.merchant_id || raw?.merchantId || '').trim();
    const platform = String(raw?.platform || '').trim().toLowerCase() || null;
    if (!merchantId) continue;
    const key = `${merchantId}:${platform || 'default'}`;
    if (seen.has(key)) continue;
    seen.add(key);
    out.push({ merchant_id: merchantId, platform });
  }

  if (!out.length) {
    for (const merchantId of sourceMerchantIds) {
      const mid = String(merchantId || '').trim();
      if (!mid) continue;
      const key = `${mid}:default`;
      if (seen.has(key)) continue;
      seen.add(key);
      out.push({ merchant_id: mid, platform: null });
    }
  }

  return out;
}

function buildCatalogSyncTargetKey(target) {
  const merchantId = String(target?.merchant_id || target?.merchantId || '').trim();
  const platform = String(target?.platform || '').trim().toLowerCase();
  return platform ? `${merchantId}:${platform}` : merchantId;
}

function buildCatalogSyncProductsUrl({ merchantId, platform, limit, ttlSeconds }) {
  const pf = String(platform || '').trim().toLowerCase();
  if (pf && pf !== 'shopify') {
    return `${PIVOTA_API_BASE}/agent/internal/platform/products/sync/${encodeURIComponent(
      merchantId,
    )}?platform=${encodeURIComponent(pf)}&limit=${encodeURIComponent(String(limit))}`;
  }
  return `${PIVOTA_API_BASE}/agent/internal/shopify/products/sync/${encodeURIComponent(
    merchantId,
  )}?limit=${encodeURIComponent(String(limit))}&ttl_seconds=${encodeURIComponent(String(ttlSeconds))}`;
}

function summarizeCatalogSyncMerchantState() {
  const rows = Object.entries(catalogSyncState.per_merchant || {}).map(([targetKey, state]) => ({
    target_key: targetKey,
    merchant_id: state?.merchant_id || targetKey,
    platform: state?.platform || null,
    ok: state?.ok === true,
    skipped: state?.skipped === true,
    invalid_merchant: state?.invalid_merchant === true,
    status: Number.isFinite(Number(state?.status)) ? Number(state.status) : null,
    attempts: Number.isFinite(Number(state?.attempts)) ? Number(state.attempts) : null,
    timeout_streak: Number.isFinite(Number(state?.timeout_streak)) ? Number(state.timeout_streak) : 0,
    last_run_at: state?.last_run_at || null,
    blocked_until: state?.blocked_until || null,
    error: state?.error ? String(state.error) : null,
  }));
  rows.sort((a, b) => {
    const ta = Date.parse(String(a.last_run_at || '')) || 0;
    const tb = Date.parse(String(b.last_run_at || '')) || 0;
    return tb - ta;
  });
  return rows.slice(0, 20);
}

async function runPdpIdentityAutoResolve() {
  // Bounded, idempotent resolver tick — turns newly onboarded seeds into
  // depositable canonical anchors so the catalog-coverage loop completes without
  // a manual GHA dispatch. Best-effort: a failed tick logs and never crashes.
  if (!PDP_IDENTITY_AUTO_RESOLVE_ENABLED) return;
  if (!process.env.DATABASE_URL) return;
  try {
    const result = await backfillPdpIdentityGraph({
      limit: PDP_IDENTITY_AUTO_RESOLVE_LIMIT,
      dryRun: false,
    });
    logger.info({ ...result }, 'pdp_identity_auto_resolve tick');
  } catch (err) {
    logger.warn({ err: err?.message || String(err) }, 'pdp_identity_auto_resolve tick failed');
  }
}

async function runCreatorCatalogAutoSync() {
  const enabled = CREATOR_CATALOG_AUTO_SYNC_ENABLED;
  if (!enabled) return;
  if (!PIVOTA_API_BASE) return;

  const adminKey = process.env.CREATOR_CATALOG_SYNC_ADMIN_KEY || ADMIN_API_KEY;
  if (!adminKey) {
    logger.warn('CREATOR_CATALOG_AUTO_SYNC_ENABLED is true but no admin key is configured');
    return;
  }

  const merchantTarget = await resolveCatalogSyncMerchantIds();
  const resolvedTargets = normalizeCatalogSyncTargets(merchantTarget);
  const nowMs = Date.now();
  const eligibleTargets = [];
  const suppressedTargets = [];
  for (const target of resolvedTargets) {
    const merchantId = target.merchant_id;
    const targetKey = buildCatalogSyncTargetKey(target);
    const suppression = getCatalogSyncSuppressionStatus(targetKey, nowMs);
    if (!suppression.suppressed) {
      eligibleTargets.push(target);
      continue;
    }
    const existingState = catalogSyncState.per_merchant[targetKey];
    catalogSyncState.per_merchant[targetKey] = {
      ...(existingState && typeof existingState === 'object' ? existingState : {}),
      merchant_id: merchantId,
      platform: target.platform || null,
      ok: false,
      skipped: true,
      last_run_at: new Date().toISOString(),
      status: Number.isFinite(Number(existingState?.status)) ? Number(existingState.status) : null,
      attempts: 0,
      duration_ms: 0,
      invalid_merchant: existingState?.invalid_merchant === true,
      error:
        existingState?.error ||
        'Skipped due to temporary cooldown after non-retryable sync error',
      blocked_until_ms: Number(existingState?.blocked_until_ms || 0) || null,
      blocked_until: suppression.blocked_until,
    };
    suppressedTargets.push({
      target_key: targetKey,
      merchant_id: merchantId,
      platform: target.platform || null,
      reason: suppression.reason,
      blocked_until: suppression.blocked_until,
      invalid_merchant: suppression.invalid_merchant,
    });
  }
  catalogSyncState.target_source = merchantTarget.source || null;
  catalogSyncState.target_count = resolvedTargets.length;
  catalogSyncState.target_eligible_count = eligibleTargets.length;
  catalogSyncState.target_suppressed_count = suppressedTargets.length;
  catalogSyncState.target_sample = resolvedTargets.slice(0, 20);
  catalogSyncState.target_suppressed_sample = suppressedTargets.slice(0, 20);
  if (!eligibleTargets.length) {
    logger.warn(
      {
        target_source: merchantTarget.source || null,
        target_count: resolvedTargets.length,
        suppressed_count: suppressedTargets.length,
      },
      'CREATOR_CATALOG_AUTO_SYNC_ENABLED is true but no sync target merchants were resolved',
    );
    return;
  }

  const limit = getCreatorCatalogAutoSyncLimitConfig().limitEffective;
  const ttlSeconds = CREATOR_CATALOG_CACHE_TTL_SECONDS;
  const maxAttempts = Math.max(1, Number(CREATOR_CATALOG_AUTO_SYNC_RETRIES || 0) + 1);

  catalogSyncState.last_run_at = new Date().toISOString();
  catalogSyncState.last_error = null;

  for (const target of eligibleTargets) {
    const merchantId = target.merchant_id;
    const platform = target.platform || null;
    const targetKey = buildCatalogSyncTargetKey(target);
    const existingState = catalogSyncState.per_merchant[targetKey];
    const url = buildCatalogSyncProductsUrl({ merchantId, platform, limit, ttlSeconds });
    const startedAtMs = Date.now();
    let attempt = 0;
    let res = null;
    let err = null;
    let timeoutUsedMs = CREATOR_CATALOG_AUTO_SYNC_TIMEOUT_MS;
    for (attempt = 1; attempt <= maxAttempts; attempt += 1) {
      timeoutUsedMs = getCatalogSyncAttemptTimeoutMs({
        merchantState: existingState,
        attempt,
      });
      try {
        res = await axios.post(url, null, {
          headers: { 'X-ADMIN-KEY': adminKey },
          timeout: timeoutUsedMs,
        });
        err = null;
        break;
      } catch (attemptErr) {
        err = attemptErr;
        const retryable = isCatalogSyncRetryableError(attemptErr);
        const nonRetryable = isCatalogSyncNonRetryableError(attemptErr);
        if (attempt < maxAttempts && retryable && !nonRetryable) {
          const delayMs = Math.min(
            CREATOR_CATALOG_AUTO_SYNC_RETRY_BACKOFF_MS * Math.pow(2, attempt - 1),
            30000,
          );
          logger.warn(
            {
              merchantId,
              attempt,
              max_attempts: maxAttempts,
              retry_in_ms: delayMs,
              timeout_ms: timeoutUsedMs,
              status: attemptErr?.response?.status || null,
              code: attemptErr?.code || null,
              non_retryable: nonRetryable,
              error: attemptErr?.message || String(attemptErr),
            },
            'Creator catalog auto sync attempt failed; retrying',
          );
          await new Promise((resolve) => setTimeout(resolve, delayMs));
          continue;
        }
        break;
      }
    }

    if (!err && res) {
      catalogSyncState.per_merchant[targetKey] = {
        merchant_id: merchantId,
        platform,
        ok: true,
        skipped: false,
        last_run_at: new Date().toISOString(),
        attempts: attempt,
        duration_ms: Math.max(0, Date.now() - startedAtMs),
        summary: res.data && res.data.summary ? res.data.summary : res.data,
        status: Number.isFinite(Number(res.status)) ? Number(res.status) : 200,
        timeout_ms: timeoutUsedMs,
        timeout_streak: 0,
        invalid_merchant: false,
        error: null,
        blocked_until_ms: null,
        blocked_until: null,
      };
      catalogSyncState.last_success_at = new Date().toISOString();
      logger.info(
        {
          merchantId,
          platform,
          limit,
          ttl_seconds: ttlSeconds,
          attempts: attempt,
          duration_ms: Math.max(0, Date.now() - startedAtMs),
          timeout_ms: timeoutUsedMs,
        },
        'Creator catalog auto sync succeeded',
      );
    } else if (err) {
      const status = err.response?.status;
      const data = err.response?.data;
      const message =
        (data && data.detail && typeof data.detail === 'object' && data.detail.message) ||
        (data && typeof data.detail === 'string' ? data.detail : null) ||
        err.message;
      const nonRetryable = isCatalogSyncNonRetryableError(err);
      const invalidMerchant = isCatalogSyncInvalidMerchantError(err);
      const timeoutError = isCatalogSyncTimeoutError(err);
      const previousTimeoutStreak = Math.max(0, Number(existingState?.timeout_streak || 0));
      const timeoutStreak = timeoutError ? Math.min(previousTimeoutStreak + 1, 10) : 0;
      const blockedUntilMs = nonRetryable
        ? Date.now() +
          (invalidMerchant
            ? CREATOR_CATALOG_AUTO_SYNC_INVALID_MERCHANT_COOLDOWN_SECONDS
            : CREATOR_CATALOG_AUTO_SYNC_NON_RETRYABLE_COOLDOWN_SECONDS) *
            1000
        : null;
      catalogSyncState.per_merchant[targetKey] = {
        merchant_id: merchantId,
        platform,
        ok: false,
        skipped: false,
        last_run_at: new Date().toISOString(),
        attempts: attempt,
        duration_ms: Math.max(0, Date.now() - startedAtMs),
        status: status || null,
        timeout_ms: timeoutUsedMs,
        timeout_streak: timeoutStreak,
        invalid_merchant: invalidMerchant,
        error: message,
        blocked_until_ms: blockedUntilMs,
        blocked_until: blockedUntilMs ? new Date(blockedUntilMs).toISOString() : null,
      };
      catalogSyncState.last_error = `${targetKey}: ${message}`;
      logger.warn(
        {
          merchantId,
          platform,
          status,
          message,
          attempts: attempt,
          timeout_ms: timeoutUsedMs,
          max_attempts: maxAttempts,
          timeout_streak: timeoutStreak,
          non_retryable: nonRetryable,
          invalid_merchant: invalidMerchant,
          blocked_until: blockedUntilMs ? new Date(blockedUntilMs).toISOString() : null,
        },
        'Creator catalog auto sync failed',
      );
    }
  }
}

// API Mode: HYBRID or REAL.
// MOCK is no longer a runtime mode. Tests that need fixture products should
// import their fixtures directly instead of routing through production code.
// HYBRID: legacy mode name retained, but runtime mock handlers fail closed
// REAL: All real API calls (requires API key)
// If API_MODE is not explicitly provided, default to REAL so environments
// cannot silently serve disabled fixture catalog data.
const REQUESTED_API_MODE =
  String(process.env.API_MODE || (PIVOTA_API_KEY ? 'REAL' : 'REAL')).trim().toUpperCase() || 'REAL';
const API_MODE =
  REQUESTED_API_MODE === 'HYBRID'
    ? 'HYBRID'
    : 'REAL';
if (REQUESTED_API_MODE === 'MOCK') {
  logger.warn(
    { requested_api_mode: REQUESTED_API_MODE, effective_api_mode: API_MODE },
    'Ignoring disabled API_MODE=MOCK runtime mode',
  );
}
const MOCK_RUNTIME_ENABLED = false;
const USE_HYBRID = API_MODE === 'HYBRID';
const REAL_API_ENABLED = API_MODE === 'REAL' && Boolean(PIVOTA_API_KEY);

// Load tool schema once for chat endpoint.
// This runs at module-load time, so an unreadable / malformed file would
// crash the worker before the HTTP server binds — and the default stack
// trace ("Unexpected token ...") doesn't make the cause obvious. Rethrow
// with the path included so it shows up clearly in deploy logs.
const toolSchemaPath = path.join(__dirname, '..', 'docs', 'tool-schema.json');
let toolSchema;
try {
  toolSchema = JSON.parse(fs.readFileSync(toolSchemaPath, 'utf-8'));
} catch (err) {
  throw new Error(
    `Failed to load tool schema from ${toolSchemaPath}: ${err.message}. ` +
    'Verify the file exists in the deployed image and contains valid JSON.'
  );
}
const uiChatToolSchema = {
  name: toolSchema.name,
  description: toolSchema.description,
  parameters: toolSchema.parameters,
};

function buildQueryString(params) {
  const sp = new URLSearchParams();
  const entries = params && typeof params === 'object' ? Object.entries(params) : [];
  for (const [key, value] of entries) {
    if (value === undefined || value === null) continue;
    if (Array.isArray(value)) {
      for (const item of value) {
        if (item === undefined || item === null) continue;
        sp.append(key, String(item));
      }
      continue;
    }
    sp.append(key, String(value));
  }
  const qs = sp.toString();
  return qs ? `?${qs}` : '';
}

function copyDefinedFields(target, source, fieldNames = []) {
  if (!target || !source || typeof source !== 'object') return target;
  for (const fieldName of fieldNames) {
    if (source[fieldName] !== undefined) target[fieldName] = source[fieldName];
  }
  return target;
}

function slicePlainArray(value, maxItems) {
  if (!Array.isArray(value)) return undefined;
  return value.slice(0, Math.max(0, Number(maxItems || 0) || 0));
}

function truncateTransportText(value, maxLength = 900) {
  if (typeof value !== 'string') return value;
  if (value.length <= maxLength) return value;
  return `${value.slice(0, Math.max(0, maxLength - 3)).trimEnd()}...`;
}

function projectSearchTransportDeal(deal) {
  if (!deal || typeof deal !== 'object' || Array.isArray(deal)) return deal;
  return copyDefinedFields({}, deal, [
    'offer_id',
    'merchant_id',
    'merchant_name',
    'store_name',
    'seller_name',
    'product_id',
    'variant_id',
    'sku_id',
    'price',
    'currency',
    'compare_at_price',
    'shipping_cost',
    'shipping_summary',
    'availability',
    'in_stock',
    'destination_url',
    'canonical_url',
    'url',
  ]);
}

function projectSearchTransportOffer(offer) {
  if (!offer || typeof offer !== 'object' || Array.isArray(offer)) return offer;
  const projected = copyDefinedFields({}, offer, [
    'offer_id',
    'merchant_id',
    'merchant_name',
    'store_name',
    'seller_name',
    'seller_of_record',
    'source_type',
    'connector',
    'product_id',
    'variant_id',
    'sku_id',
    'merchant_sku',
    'title',
    'price',
    'price_amount',
    'currency',
    'compare_at_price',
    'sale_price',
    'shipping_cost',
    'shipping_summary',
    'availability',
    'in_stock',
    'checkout_mode',
    'checkout_handoff',
    'commerce_mode',
    'destination_url',
    'canonical_url',
    'url',
    'image_url',
    'confidence',
    'freshness_ts',
    'payment_offer_summary',
    'payment_offer_evidence',
    'payment_offer_badges',
    'capability_flags',
  ]);
  if (Array.isArray(offer.promotions)) projected.promotions = offer.promotions.slice(0, 3);
  return projected;
}

function projectSearchTransportVariant(variant) {
  if (!variant || typeof variant !== 'object' || Array.isArray(variant)) return variant;
  return copyDefinedFields({}, variant, [
    'id',
    'variant_id',
    'sku',
    'sku_id',
    'title',
    'name',
    'option1',
    'option2',
    'option3',
    'options',
    'selected_options',
    'price',
    'price_amount',
    'currency',
    'compare_at_price',
    'in_stock',
    'available',
    'available_quantity',
    'inventory_quantity',
    'image_url',
  ]);
}

function projectSearchTransportProduct(product, stats = null) {
  if (!product || typeof product !== 'object' || Array.isArray(product)) return product;
  const projected = copyDefinedFields({}, product, [
    'id',
    'product_id',
    'productId',
    'platform_product_id',
    'external_product_id',
    'pivota_signature_id',
    'signature_id',
    'product_key',
    'attached_product_key',
    'title',
    'name',
    'canonical_title',
    'brand',
    'vendor',
    'merchant_id',
    'merchant_name',
    'store_name',
    'seller_name',
    'source',
    'source_kind',
    'platform',
    'category',
    'canonical_category',
    'category_path',
    'product_type',
    'price',
    'price_amount',
    'currency',
    'in_stock',
    'availability',
    'inventory_quantity',
    'image_url',
    'canonical_url',
    'destination_url',
    'external_url',
    'url',
    'offer_id',
    'default_offer_id',
    'offers_count',
    'offer_count',
    'best_offer_id',
    'canonical_scope',
    'review_family_id',
    'product_line_id',
    'sellable_item_group_id',
    'product_group_id',
    'dedupe_group_id',
    'pdp_scope',
    'canonical_ref',
    'canonical_product_ref',
    'selected_commerce_ref',
    'commerce_ref',
    // ranking mechanics (score/confidence/ranking_features_summary) are internal-only and intentionally NOT
    // projected to the agent surface — see resultSanitizer RANKING_INTERNAL. Keep the "why" prose below.
    'recommendation_reason',
    'match_reason',
    'why_this_one',
    'rating',
    'reviews_count',
    'review_count',
    'payment_offer_summary',
    'payment_offer_evidence',
  ]);

  if (typeof product.description === 'string') {
    projected.description = truncateTransportText(product.description);
  }
  if (typeof product.summary === 'string') {
    projected.summary = truncateTransportText(product.summary);
  }
  if (typeof product.snippet === 'string') {
    projected.snippet = truncateTransportText(product.snippet, 500);
  }
  if (product.attributes && typeof product.attributes === 'object' && !Array.isArray(product.attributes)) {
    projected.attributes = safeCloneJson(product.attributes);
  }
  if (product.provenance && typeof product.provenance === 'object' && !Array.isArray(product.provenance)) {
    projected.provenance = safeCloneJson(product.provenance);
  }
  if (product.commerce_facts_v1 && typeof product.commerce_facts_v1 === 'object' && !Array.isArray(product.commerce_facts_v1)) {
    projected.commerce_facts_v1 = safeCloneJson(product.commerce_facts_v1);
  }
  if (product.agent_safe_commerce_facts && typeof product.agent_safe_commerce_facts === 'object' && !Array.isArray(product.agent_safe_commerce_facts)) {
    projected.agent_safe_commerce_facts = safeCloneJson(product.agent_safe_commerce_facts);
  }

  const images = slicePlainArray(product.images, FIND_PRODUCTS_MULTI_TRANSPORT_MAX_IMAGES_PER_PRODUCT);
  if (images) projected.images = images;
  const imageRefs = slicePlainArray(product.image_refs, FIND_PRODUCTS_MULTI_TRANSPORT_MAX_IMAGES_PER_PRODUCT);
  if (imageRefs) projected.image_refs = imageRefs;
  for (const fieldName of ['tags', 'badges', 'highlights', 'key_ingredients', 'active_ingredients', 'ingredient_tags']) {
    const items = slicePlainArray(product[fieldName], 12);
    if (items) projected[fieldName] = items;
  }

  if (Array.isArray(product.best_deal)) {
    projected.best_deal = product.best_deal.slice(0, 1).map(projectSearchTransportDeal);
  } else if (product.best_deal && typeof product.best_deal === 'object') {
    projected.best_deal = projectSearchTransportDeal(product.best_deal);
  }
  if (Array.isArray(product.all_deals)) {
    projected.all_deals = product.all_deals.slice(0, 3).map(projectSearchTransportDeal);
  }

  if (Array.isArray(product.variants)) {
    projected.variants = product.variants
      .slice(0, FIND_PRODUCTS_MULTI_TRANSPORT_MAX_VARIANTS_PER_PRODUCT)
      .map(projectSearchTransportVariant);
    projected.variants_count = product.variants.length;
    if (stats && product.variants.length > projected.variants.length) {
      stats.trimmed_variants += product.variants.length - projected.variants.length;
    }
  }
  if (Array.isArray(product.offers)) {
    projected.offers = product.offers
      .slice(0, FIND_PRODUCTS_MULTI_TRANSPORT_MAX_OFFERS_PER_PRODUCT)
      .map(projectSearchTransportOffer);
    projected.offers_count = Number(product.offers_count || product.offer_count || product.offers.length) || product.offers.length;
    if (stats && product.offers.length > projected.offers.length) {
      stats.trimmed_offers += product.offers.length - projected.offers.length;
    }
  }

  return projected;
}

// ADR-007 citable supplement — OPERATION-LEVEL. find_products_multi has many
// lanes (agent_products_search / external_seed_mainline / ingredient_recall_direct)
// with different return points, so per-exit wiring missed most of them. Instead we
// hook the single universal res.json wrapper: PREFETCH offer-free index_eligible
// items once (async, OFF the serial path — see handleInvokeRequest) via
// buildCitableSupplementItems, then APPEND whatever has resolved by send time
// synchronously inside the wrapper (appendCitableSupplementItems) so EVERY response
// is covered. Flag-gated by INDEX_ELIGIBLE_RECALL (default OFF -> no query, no-op).
// Append-only + deduped; each item is buyable:false / catalog_track:'citation' so
// it can never be a buyable/checkout result. Best-effort; never throws.
function citableSupplementEnabled() {
  return ['1', 'true', 'yes', 'on'].includes(
    String(process.env.INDEX_ELIGIBLE_RECALL || '').trim().toLowerCase(),
  );
}

// The tokenMatch canonical query behind the supplement is expensive
// (prod fpm_stage_breakdown measured it at 5.8-17.2s), so results are cached
// per normalized query and concurrent identical queries share one DB
// round-trip. The first request for a query warms the cache (its own response
// usually ships before the query resolves); subsequent requests append from
// cache. Items are cloned on the way out so downstream response mutation
// (near-dup collapse, page-size trim, projections) can't poison the cache.
const CITABLE_SUPPLEMENT_CACHE_MAX_ENTRIES = 500;
const citableSupplementCache = new Map(); // normalized query -> { items, expiresAt }
const citableSupplementInFlight = new Map(); // normalized query -> Promise<items>

function citableSupplementCacheTtlMs() {
  const raw = Number(process.env.CITABLE_SUPPLEMENT_CACHE_TTL_MS);
  return Number.isFinite(raw) && raw >= 0 ? raw : 5 * 60 * 1000;
}

// Finalize one built product into a citation item (ADR-007). Marks it
// non-buyable and strips fields that don't belong on a citation:
//   - the raw seed_data / external_seed jsonb blobs that
//     buildCanonicalChainMainlineProduct echoes onto every item. On a citation
//     these are pure response bloat — measured on prod as present on ~65% of
//     citable items and the dominant per-item byte cost. The DERIVED fields the
//     builder extracts from those blobs (ingredient_intel, active_ingredients,
//     ingredients_inci, pdp_ingredients_raw, fashion_meta, identity) are separate
//     top-level keys and are intentionally KEPT.
// A citation may be referral-only, but it still needs a source-backed price to
// be shown in a shopping result. The public search contract never permits a
// card with an absent price or a fabricated currency. We therefore materialize
// a positive amount/currency pair before removing the source payload below.
// Scoped to the citation lane only; other lanes keep the full item shape.
function readCanonicalSearchPricePair(value, fallbackCurrency = '') {
  if (value === null || value === undefined) return null;
  if (typeof value === 'number' || typeof value === 'string') {
    const amount = Number(value);
    const currency = String(fallbackCurrency || '').trim().toUpperCase();
    return Number.isFinite(amount) && amount > 0 && currency ? { amount, currency } : null;
  }
  if (!isPlainObject(value)) return null;

  const localCurrency = firstNonEmptyString(
    value.currency,
    value.currency_code,
    value.price_currency,
    value.priceCurrency,
    fallbackCurrency,
  );
  for (const field of ['amount', 'value', 'price_amount', 'priceAmount', 'current_price', 'currentPrice', 'sale_price', 'salePrice', 'min_price', 'minPrice']) {
    const amount = Number(value[field]);
    if (Number.isFinite(amount) && amount > 0 && localCurrency) {
      return { amount, currency: String(localCurrency).trim().toUpperCase() };
    }
  }
  for (const field of ['price', 'pricing', 'current', 'sale', 'min', 'offer_price', 'offerPrice']) {
    const pair = readCanonicalSearchPricePair(value[field], localCurrency);
    if (pair) return pair;
  }
  return null;
}

function resolveCanonicalSearchProductPrice(product) {
  if (!isPlainObject(product)) return null;
  const productCurrency = firstNonEmptyString(
    product.currency,
    product.currency_code,
    product.price_currency,
    product.priceCurrency,
  );
  const direct = readCanonicalSearchPricePair(product, productCurrency);
  if (direct) return direct;

  for (const collection of [product.offers, product.variants]) {
    if (!Array.isArray(collection)) continue;
    for (const entry of collection) {
      const pair = readCanonicalSearchPricePair(entry, productCurrency);
      if (pair) return pair;
    }
  }

  // Citation rows retain their exact source snapshot until finalization. Each
  // object is evaluated independently, so an amount can never borrow a
  // currency from a different source.
  for (const source of [product.seed_data, product.external_seed]) {
    if (!isPlainObject(source)) continue;
    const directSourcePair = readCanonicalSearchPricePair(source);
    if (directSourcePair) return directSourcePair;
    const snapshotPair = readCanonicalSearchPricePair(source.snapshot);
    if (snapshotPair) return snapshotPair;
  }
  return null;
}

function materializeCanonicalSearchProductPrice(product) {
  const price = resolveCanonicalSearchProductPrice(product);
  if (!price) return null;
  // Keep the established response-finalization identity semantics: callers
  // may safely retain references to a card while its canonical price is
  // normalized in place.
  product.price = price.amount;
  product.currency = price.currency;
  return product;
}

function isShoppingAgentFindProductsMultiRequest(req, operation) {
  if (String(operation || '').trim().toLowerCase() !== 'find_products_multi') return false;
  const metadata = req?.body?.metadata;
  if (!metadata || typeof metadata !== 'object' || Array.isArray(metadata)) return false;
  const source = String(metadata.source || metadata.client_source || '')
    .trim()
    .toLowerCase();
  return source === 'shopping_agent' || source === 'shopping-agent';
}

function enforceFindProductsMultiPriceContract(responseBody) {
  if (!responseBody || typeof responseBody !== 'object' || Array.isArray(responseBody)) return responseBody;
  const container = Array.isArray(responseBody.products)
    ? responseBody
    : responseBody.data && Array.isArray(responseBody.data.products)
      ? responseBody.data
      : null;
  if (!container) return responseBody;

  const input = container.products;
  const priced = input.map(materializeCanonicalSearchProductPrice).filter(Boolean);
  const dropped = input.length - priced.length;
  container.products = priced;
  if (Array.isArray(responseBody.products)) responseBody.products = priced;
  const metadata =
    responseBody.metadata && typeof responseBody.metadata === 'object' && !Array.isArray(responseBody.metadata)
      ? responseBody.metadata
      : {};
  metadata.price_contract = {
    canonical_price_or_offer_required: true,
    dropped_unpriced: dropped,
  };
  responseBody.metadata = metadata;
  responseBody.page_size = priced.length;
  if (Number.isFinite(Number(responseBody.total))) {
    responseBody.total = Math.max(priced.length, Number(responseBody.total) - dropped);
  } else {
    responseBody.total = priced.length;
  }
  return responseBody;
}

function dedupeFindProductsMultiProductGroups(responseBody) {
  if (!responseBody || typeof responseBody !== 'object' || Array.isArray(responseBody)) return responseBody;
  const container = Array.isArray(responseBody.products)
    ? responseBody
    : responseBody.data && Array.isArray(responseBody.data.products)
      ? responseBody.data
      : null;
  if (!container) return responseBody;

  const seenGroups = new Set();
  const products = [];
  let dropped = 0;
  for (const product of container.products) {
    const groupId = firstNonEmptyString(product?.dedupe_group_id, product?.dedupeGroupId);
    if (groupId && seenGroups.has(groupId)) {
      dropped += 1;
      continue;
    }
    if (groupId) seenGroups.add(groupId);
    products.push(product);
  }
  container.products = products;
  if (Array.isArray(responseBody.products)) responseBody.products = products;
  if (!dropped) return responseBody;
  responseBody.page_size = products.length;
  if (Number.isFinite(Number(responseBody.total))) {
    responseBody.total = Math.max(products.length, Number(responseBody.total) - dropped);
  }
  const metadata =
    responseBody.metadata && typeof responseBody.metadata === 'object' && !Array.isArray(responseBody.metadata)
      ? responseBody.metadata
      : {};
  metadata.search_dedupe = { dedupe_group_id_applied: true, dropped_duplicate_groups: dropped };
  responseBody.metadata = metadata;
  return responseBody;
}

function finalizeCitableSupplementItem(item) {
  if (!item || typeof item !== 'object' || Array.isArray(item)) return null;
  const pricedItem = materializeCanonicalSearchProductPrice(item);
  if (!pricedItem) return null;
  item = pricedItem;
  item.buyable = false;
  item.in_stock = false;
  // The price/currency above are a verified pair. The previous reason code
  // would be stale after that materialization and must not leak to clients.
  delete item.price_absent_reason;
  delete item.seed_data;
  delete item.external_seed;
  item.source = 'canonical_citation';
  item.search_recall_source = 'canonical_citation';
  item.catalog_source = 'canonical_citation';
  item.catalog_track = 'citation';
  return item;
}

async function queryCitableSupplementItems(q) {
  const rows = await fetchCanonicalChainRows({
    query: q,
    includeSkuOffers: false,
    eligibility: 'index_eligible',
    tokenMatch: true,
    deps: { query },
  });
  if (!Array.isArray(rows) || !rows.length) return [];
  const items = [];
  for (const row of rows) {
    const item = finalizeCitableSupplementItem(buildCanonicalChainMainlineProduct(row));
    if (!item) continue;
    items.push(item);
  }
  return items;
}

async function buildCitableSupplementItems(queryText = '') {
  try {
    if (!citableSupplementEnabled()) return [];
    const q = String(queryText || '').trim();
    if (!q) return [];
    const cacheKey = q.toLowerCase();
    const cached = citableSupplementCache.get(cacheKey);
    if (cached && cached.expiresAt > Date.now()) {
      return structuredClone(cached.items);
    }
    if (cached) citableSupplementCache.delete(cacheKey);
    let inFlight = citableSupplementInFlight.get(cacheKey);
    if (!inFlight) {
      inFlight = queryCitableSupplementItems(q)
        .then((items) => {
          const ttlMs = citableSupplementCacheTtlMs();
          if (ttlMs > 0) {
            if (citableSupplementCache.size >= CITABLE_SUPPLEMENT_CACHE_MAX_ENTRIES) {
              const oldestKey = citableSupplementCache.keys().next().value;
              if (oldestKey !== undefined) citableSupplementCache.delete(oldestKey);
            }
            citableSupplementCache.set(cacheKey, { items, expiresAt: Date.now() + ttlMs });
          }
          return items;
        })
        .finally(() => {
          citableSupplementInFlight.delete(cacheKey);
        });
      citableSupplementInFlight.set(cacheKey, inFlight);
    }
    const items = await inFlight;
    return structuredClone(items);
  } catch (_) {
    return []; // best-effort: never break recall
  }
}

// Sync: append prefetched citable items to whatever final body is being sent,
// deduped against the products already present. Returns the (possibly mutated)
// body. Safe to call on any shape; no-op when items is empty.
function appendCitableSupplementItems(responseBody, items) {
  try {
    if (!responseBody || typeof responseBody !== 'object') return responseBody;
    // Strict-contract lanes (ingredient_recall_direct + the upstream strict
    // proxy) paginate inside the lane AND are exempt from
    // enforceFindProductsMultiRequestedPageSize's trim, so anything appended
    // here ships to the client uncapped: prod probes showed limit=10 requests
    // returning 48-52 products whenever the supplement cache was warm at send
    // time (and 10 when it wasn't — the count flapped with cache warmth).
    // Citation items are token-matched, never checked against the ingredient
    // constraint, so they don't belong in a strict_constraint_query response
    // either. Skip the lane entirely.
    //
    // The discriminator must NOT rely on contract_bridge alone:
    // applyPivotBeautyContractToInvokeSearchResponse runs EARLIER in the same
    // res.json wrapper and overwrites contract_bridge.{attempted,resolved}_contract
    // to 'pivot.agent.v1' for beauty-shaped requests — and the strict lane
    // deliberately still serves pivot-contract ingredient queries
    // (shouldPreserveIngredientDirectForPivotBeautyContract). That rewrite
    // spreads the rest of metadata untouched, so the lane's top-level
    // resolved_contract and strict_constraint_query stamps survive it; the
    // upstream strict proxy stamps only contract_bridge, which is covered by
    // the first arm when no rewrite fired.
    //
    // This check sits BEFORE the items-length early-return so strict bodies
    // stamp count 0 + skip_reason deterministically, cold or warm cache —
    // otherwise the skip_reason itself would flap with cache warmth, the
    // exact ambiguity it exists to remove.
    const responseMetadata =
      responseBody.metadata && typeof responseBody.metadata === 'object' && !Array.isArray(responseBody.metadata)
        ? responseBody.metadata
        : null;
    const isStrictContractBody = Boolean(
      responseMetadata &&
        (String(responseMetadata.contract_bridge?.resolved_contract || '') === 'shop_invoke_strict' ||
          String(responseMetadata.resolved_contract || '') === 'shop_invoke_strict' ||
          responseMetadata.strict_constraint_query === true),
    );
    if (isStrictContractBody) {
      responseMetadata.citable_supplement_count = 0;
      responseMetadata.citable_supplement_skip_reason = 'strict_contract';
      return responseBody;
    }
    if (!Array.isArray(items) || !items.length) return responseBody;
    const container = Array.isArray(responseBody.products)
      ? responseBody
      : (responseBody.data && Array.isArray(responseBody.data.products) ? responseBody.data : null);
    if (!container) return responseBody;
    const seen = new Set(
      container.products.map((p) => p && (p.content_key || p.product_id)).filter(Boolean),
    );
    let added = 0;
    for (const item of items) {
      const key = item && (item.content_key || item.product_id);
      if (key && seen.has(key)) continue;
      if (key) seen.add(key);
      container.products.push(item);
      added += 1;
    }
    if (responseBody.metadata && typeof responseBody.metadata === 'object') {
      responseBody.metadata.citable_supplement_count = added;
    }
  } catch (_) {
    // best-effort: the citable supplement must never break recall transport
  }
  return responseBody;
}

// Op-level refinement for find_products_multi BEAUTY responses, applied AFTER the
// citable supplement is appended. The lane-level rank/collapse (PR #1738/#1739)
// runs BEFORE the supplement, so citable items — which carry distinct
// content_keys and so pass appendCitableSupplementItems' exact-key dedupe — can
// re-introduce near-identical titles the lane already collapsed (e.g. "(Copy_Tn)"
// test copies), and a small-distinct-set lane's demoted dupes can leak into the
// page. This is the single place that sees the fully merged list.
//   - Near-dup collapse runs for EVERY beauty lane (idempotent where the lane
//     already collapsed; catches citable-supplement dupes). Demotes to tail,
//     never drops → total/pagination stay stable.
//   - Token-relevance reorder runs ONLY for the ingredient-recall-direct lane
//     (which has no scorer of its own). The mainline lane keeps its richer
//     in-lane ranking (brand/category/active weights) untouched — re-sorting it
//     by token relevance alone would be a regression.
// Best-effort + flag-gated; never breaks recall transport.
function refineBeautyFindProductsMultiResponseBody(responseBody, queryText = '') {
  try {
    if (
      !PIVOT_BEAUTY_NEAR_DUP_COLLAPSE_ENABLED &&
      !PIVOT_BEAUTY_TOKEN_RELEVANCE_RANK_ENABLED &&
      !PIVOT_BEAUTY_SET_DEMOTION_ENABLED
    ) {
      return responseBody;
    }
    if (!responseBody || typeof responseBody !== 'object') return responseBody;
    const querySource = String(responseBody.metadata?.query_source || '');
    if (!/beauty|ingredient_recall/i.test(querySource)) return responseBody;
    const container = Array.isArray(responseBody.products)
      ? responseBody
      : responseBody.data && Array.isArray(responseBody.data.products)
        ? responseBody.data
        : null;
    if (!container || container.products.length < 2) return responseBody;
    const isIngredientDirect = /ingredient_recall_direct/i.test(querySource);
    const result = reorderBeautyIngredientDirectProducts(container.products, {
      queryText,
      // Reorder only the scorer-less ingredient-direct lane; collapse everywhere.
      tokenRelevanceEnabled: isIngredientDirect && PIVOT_BEAUTY_TOKEN_RELEVANCE_RANK_ENABLED,
      nearDupCollapseEnabled: PIVOT_BEAUTY_NEAR_DUP_COLLAPSE_ENABLED,
      // Set demotion runs for EVERY beauty lane: the bundles show up in the
      // mainline's own results, not just the scorer-less lane, and this is the
      // only place that sees the fully merged list.
      setDemotionEnabled: PIVOT_BEAUTY_SET_DEMOTION_ENABLED,
    });
    if (
      result.near_dup_collapsed_count > 0 ||
      result.token_relevance_applied ||
      result.set_demoted_count > 0
    ) {
      container.products = result.products;
      if (responseBody.metadata && typeof responseBody.metadata === 'object') {
        if (result.near_dup_collapsed_count > 0) {
          responseBody.metadata.op_level_near_dup_collapsed_count = result.near_dup_collapsed_count;
        }
        if (result.token_relevance_applied) {
          responseBody.metadata.op_level_token_relevance_applied = true;
        }
        if (result.set_demoted_count > 0) {
          responseBody.metadata.op_level_set_demoted_count = result.set_demoted_count;
        }
      }
    }
  } catch (_) {
    // best-effort: refinement must never break recall transport
  }
  return responseBody;
}

function projectFindProductsMultiTransportResponse(responseBody, { operation = null } = {}) {
  if (
    String(operation || '').trim() !== 'find_products_multi' ||
    !responseBody ||
    typeof responseBody !== 'object' ||
    Array.isArray(responseBody) ||
    !Array.isArray(responseBody.products)
  ) {
    return responseBody;
  }
  const stats = { trimmed_offers: 0, trimmed_variants: 0 };
  const products = responseBody.products
    .map((product) => promoteVisibleSimilarProductSigId(product))
    .map((product) => projectSearchTransportProduct(product, stats));
  const metadata =
    responseBody.metadata && typeof responseBody.metadata === 'object' && !Array.isArray(responseBody.metadata)
      ? responseBody.metadata
      : {};
  return {
    ...responseBody,
    products,
    results: Array.isArray(responseBody.results) ? products : responseBody.results,
    data:
      responseBody.data && typeof responseBody.data === 'object' && !Array.isArray(responseBody.data)
        ? {
            ...responseBody.data,
            ...(Array.isArray(responseBody.data.products) ? { products } : {}),
          }
        : responseBody.data,
    metadata: {
      ...metadata,
      search_transport_projection: {
        applied: true,
        max_offers_per_product: FIND_PRODUCTS_MULTI_TRANSPORT_MAX_OFFERS_PER_PRODUCT,
        max_variants_per_product: FIND_PRODUCTS_MULTI_TRANSPORT_MAX_VARIANTS_PER_PRODUCT,
        max_images_per_product: FIND_PRODUCTS_MULTI_TRANSPORT_MAX_IMAGES_PER_PRODUCT,
        trimmed_offers: stats.trimmed_offers,
        trimmed_variants: stats.trimmed_variants,
      },
    },
  };
}

function normalizeAgentProductsListResponse(raw, ctx = {}) {
  if (!raw) return raw;

  const nowIso = new Date().toISOString();

  const getProducts = (obj) => {
    if (!obj) return [];
    if (Array.isArray(obj)) return obj;
    if (Array.isArray(obj.products)) return obj.products;
    if (Array.isArray(obj.items)) return obj.items;
    if (Array.isArray(obj.results)) return obj.results;
    const data = obj.data;
    if (data && typeof data === 'object') {
      if (Array.isArray(data.products)) return data.products;
      if (Array.isArray(data.items)) return data.items;
      if (Array.isArray(data.results)) return data.results;
    }
    return [];
  };

  const base = raw && typeof raw === 'object' && !Array.isArray(raw) ? raw : {};
  const pagination =
    base.pagination && typeof base.pagination === 'object' && !Array.isArray(base.pagination)
      ? base.pagination
      : {};
  const products = getProducts(raw);
  const normalizedProducts = products.map((product) => {
    if (!product || typeof product !== 'object' || Array.isArray(product)) return product;
    const compatProduct = normalizeCanonicalSearchProductCompat(product);
    const { primaryImageUrl, normalizedImages } = normalizeProductImages(compatProduct);
    if (!primaryImageUrl && normalizedImages.length === 0) return compatProduct;
    return {
      ...compatProduct,
      ...(primaryImageUrl ? { image_url: primaryImageUrl } : {}),
      ...(normalizedImages.length > 0 ? { images: normalizedImages } : {}),
    };
  });

  const totalRaw =
    base.total ??
    base.count ??
    base.total_count ??
    base.totalCount ??
    base.page_total ??
    base.pageTotal ??
    pagination.total ??
    pagination.count ??
    pagination.total_count ??
    pagination.totalCount;
  const total = typeof totalRaw === 'number' ? totalRaw : normalizedProducts.length;

  const limitRaw =
    ctx.limit ??
    base.limit ??
    base.page_size ??
    base.pageSize ??
    pagination.limit ??
    pagination.page_size ??
    pagination.pageSize;
  const offsetRaw = ctx.offset ?? base.offset ?? pagination.offset ?? 0;
  const limit = Number(limitRaw);
  const offset = Number(offsetRaw);
  const page =
    Number.isFinite(limit) && limit > 0 && Number.isFinite(offset) && offset >= 0
      ? Math.floor(offset / limit) + 1
      : base.page || pagination.page || 1;

  const mergedMetadata =
    base.metadata && typeof base.metadata === 'object' && !Array.isArray(base.metadata)
      ? { ...base.metadata }
      : {};

  if (!mergedMetadata.query_source) mergedMetadata.query_source = 'agent_products_search';
  if (!mergedMetadata.fetched_at) mergedMetadata.fetched_at = nowIso;

  return {
    ...base,
    status: base.status || 'success',
    success: typeof base.success === 'boolean' ? base.success : true,
    products: normalizedProducts,
    total,
    page,
    page_size:
      typeof base.page_size === 'number'
        ? base.page_size
        : Number.isFinite(limit) && limit > 0
          ? limit
          : normalizedProducts.length,
    reply: base.reply ?? null,
    metadata: mergedMetadata,
  };
}

// Final page-size contract for find_products_multi: the recall/rank pipeline
// intentionally carries a wide candidate pool (upstream often returns ~50 rows
// no matter what limit it was asked for), but the CLIENT-facing response must
// honor an explicitly requested page_size/limit. Applied at the res.json choke
// point — after policy ranking and LLM rerank, so trimming never shrinks the
// pool those stages rank over. Strict-contract responses are left untouched
// (their shape is parity-locked with the backend).
function enforceFindProductsMultiRequestedPageSize({ responseBody, searchParams, queryText = '' }) {
  if (!responseBody || typeof responseBody !== 'object' || Array.isArray(responseBody)) {
    return responseBody;
  }
  const search =
    searchParams && typeof searchParams === 'object' && !Array.isArray(searchParams)
      ? searchParams
      : {};
  const explicitRaw = search.page_size ?? search.pageSize ?? search.limit;
  if (explicitRaw === undefined || explicitRaw === null || explicitRaw === '') {
    return responseBody;
  }
  const parsedLimit = Math.floor(Number(explicitRaw));
  // Invalid or non-positive values are treated as "not requested", never as 1.
  if (!Number.isFinite(parsedLimit) || parsedLimit < 1) return responseBody;
  const requestedLimit = Math.min(parsedLimit, SEARCH_LIMIT_MAX);
  if (
    String(responseBody?.metadata?.contract_bridge?.resolved_contract || '') ===
    'shop_invoke_strict'
  ) {
    return responseBody;
  }
  const products = Array.isArray(responseBody.products) ? responseBody.products : null;
  if (!products || products.length <= requestedLimit) return responseBody;
  // Brand page guard: a brand-name query must not have its brand-matching
  // items trimmed away in favor of items that don't match the brand at all.
  // The failure this fixes: the primary pool returns irrelevant products
  // (e.g. post-expansion junk or fallback recall) ranked ahead of brand-exact
  // items the citable supplement appended AFTER ranking, so the page fills
  // with junk and this trim used to drop the actual brand hits. Stable
  // partition: brand-matching items keep their relative order, then the rest
  // — and only when the plain trim would actually lose a brand-matching item.
  let orderedProducts = products;
  let brandGuard = null;
  try {
    const brandDetection = detectBrandEntities(String(queryText || ''), { candidateProducts: [] });
    const brandCompacts = (brandDetection?.brand_like ? brandDetection.brands : [])
      .map((brand) => String(brand || '').toLowerCase().replace(/[^a-z0-9]+/g, ''))
      .filter((brand) => brand.length >= 4);
    if (brandCompacts.length) {
      const matchesBrand = (product) => {
        // Two-tier match (review finding: compacted substrings have no token
        // boundaries — "nars" ⊂ "lunarspell", "fresh" ⊂ "refreshing"):
        // the product's own brand field matches on containment at any length,
        // but the loose title/name substring arm requires a longer compact so
        // short brand names can't collide with unrelated words.
        const brandField = String(product?.brand || '')
          .toLowerCase()
          .replace(/[^a-z0-9]+/g, '');
        const hay = `${product?.brand || ''} ${product?.title || ''} ${product?.name || ''}`
          .toLowerCase()
          .replace(/[^a-z0-9]+/g, '');
        return brandCompacts.some(
          (brand) =>
            (brandField && brandField.includes(brand)) ||
            (brand.length >= 6 && hay.includes(brand)),
        );
      };
      const matched = [];
      const rest = [];
      for (const product of products) (matchesBrand(product) ? matched : rest).push(product);
      const brandItemsOnPlainPage = products.slice(0, requestedLimit).filter(matchesBrand).length;
      if (matched.length > 0 && brandItemsOnPlainPage < Math.min(matched.length, requestedLimit)) {
        orderedProducts = [...matched, ...rest];
        brandGuard = {
          brands: brandDetection.brands,
          brand_matched_count: matched.length,
          promoted_count: Math.min(matched.length, requestedLimit) - brandItemsOnPlainPage,
        };
      }
    }
  } catch (_) {
    // best-effort: the guard must never break page-size enforcement
  }
  const existingMetadata =
    responseBody.metadata && typeof responseBody.metadata === 'object' && !Array.isArray(responseBody.metadata)
      ? responseBody.metadata
      : {};
  return {
    ...responseBody,
    products: orderedProducts.slice(0, requestedLimit),
    page_size: requestedLimit,
    metadata: {
      ...existingMetadata,
      page_size_enforcement: {
        applied: true,
        requested_page_size: requestedLimit,
        pre_trim_count: products.length,
        ...(brandGuard ? { brand_guard: brandGuard } : {}),
      },
    },
  };
}

function withProxySearchFallbackMetadata(body, patch) {
  if (!body || typeof body !== 'object' || Array.isArray(body)) return body;
  const metadata =
    body.metadata && typeof body.metadata === 'object' && !Array.isArray(body.metadata)
      ? { ...body.metadata }
      : {};
  metadata.proxy_search_fallback = {
    ...(metadata.proxy_search_fallback &&
    typeof metadata.proxy_search_fallback === 'object' &&
    !Array.isArray(metadata.proxy_search_fallback)
      ? metadata.proxy_search_fallback
      : {}),
    ...patch,
  };
  return { ...body, metadata };
}

function buildSearchRouteHealth({
  primaryPathUsed,
  primaryLatencyMs,
  fallbackTriggered,
  fallbackReason,
  ambiguityScorePre = null,
  ambiguityScorePost = null,
  clarifyTriggered = false,
  degradeFlags = null,
  orchestratorPath = null,
  decisionNode = null,
  querySemanticClass = null,
  domainFilterDroppedExternal = 0,
  externalFillGateReason = null,
  semanticRetryApplied = false,
  semanticRetryActualAttempted = false,
  semanticRetryQuery = null,
  semanticRetryHits = 0,
  externalSeedQueryTimeout = false,
  externalSeedSkipReason = null,
  externalSeedCacheHit = false,
  externalSeedRowsFetched = 0,
  externalSeedRowsBuilt = 0,
  externalSeedBrandStrictRows = 0,
  externalSeedBrandRelevantRows = 0,
  externalSeedBroadFallbackUsed = false,
  externalSeedBroadScopeRows = 0,
  internalRawCount = 0,
  externalRawCount = 0,
  mergedPreLimitCount = 0,
  primaryQualityGatePassed = true,
  primaryQualityScore = null,
  lowQualityNonemptyDetected = false,
  supplementAttempted = false,
  supplementSkipReason = null,
  retryAttemptCount = 0,
  fallbackAttemptCount = 0,
  selectedFallbackAttempt = 0,
  finalReturnedCount = 0,
}) {
  const normalizedExternalSeedSkipReason = externalSeedSkipReason
    ? String(externalSeedSkipReason || '').trim() || null
    : null;
  const derivedExternalSeedCacheHit =
    Boolean(externalSeedCacheHit) || normalizedExternalSeedSkipReason === 'cache_hit';
  return {
    orchestrator_path: orchestratorPath ? String(orchestratorPath) : 'external_invoke_route',
    decision_node: decisionNode ? String(decisionNode) : String(primaryPathUsed || 'unknown'),
    primary_path_used: String(primaryPathUsed || 'unknown'),
    primary_latency_ms: Math.max(0, Number(primaryLatencyMs || 0) || 0),
    fallback_triggered: Boolean(fallbackTriggered),
    fallback_reason: fallbackReason ? String(fallbackReason) : null,
    query_semantic_class: querySemanticClass ? String(querySemanticClass) : 'default',
    domain_filter_dropped_external: Math.max(
      0,
      Number.isFinite(Number(domainFilterDroppedExternal)) ? Number(domainFilterDroppedExternal) : 0,
    ),
    external_fill_gate_reason: externalFillGateReason ? String(externalFillGateReason) : null,
    semantic_retry_applied: Boolean(semanticRetryApplied),
    semantic_retry_actual_attempted: Boolean(semanticRetryActualAttempted),
    semantic_retry_query: semanticRetryQuery ? String(semanticRetryQuery) : null,
    semantic_retry_hits: Math.max(
      0,
      Number.isFinite(Number(semanticRetryHits)) ? Number(semanticRetryHits) : 0,
    ),
    external_seed_query_timeout: Boolean(externalSeedQueryTimeout),
    external_seed_skip_reason: normalizedExternalSeedSkipReason,
    external_seed_cache_hit: derivedExternalSeedCacheHit,
    external_seed_rows_fetched: Math.max(
      0,
      Number.isFinite(Number(externalSeedRowsFetched)) ? Number(externalSeedRowsFetched) : 0,
    ),
    external_seed_rows_built: Math.max(
      0,
      Number.isFinite(Number(externalSeedRowsBuilt)) ? Number(externalSeedRowsBuilt) : 0,
    ),
    external_seed_brand_strict_rows: Math.max(
      0,
      Number.isFinite(Number(externalSeedBrandStrictRows)) ? Number(externalSeedBrandStrictRows) : 0,
    ),
    external_seed_brand_relevant_rows: Math.max(
      0,
      Number.isFinite(Number(externalSeedBrandRelevantRows)) ? Number(externalSeedBrandRelevantRows) : 0,
    ),
    external_seed_broad_fallback_used: Boolean(externalSeedBroadFallbackUsed),
    external_seed_broad_scope_rows: Math.max(
      0,
      Number.isFinite(Number(externalSeedBroadScopeRows)) ? Number(externalSeedBroadScopeRows) : 0,
    ),
    internal_raw_count: Math.max(
      0,
      Number.isFinite(Number(internalRawCount)) ? Number(internalRawCount) : 0,
    ),
    external_raw_count: Math.max(
      0,
      Number.isFinite(Number(externalRawCount)) ? Number(externalRawCount) : 0,
    ),
    merged_pre_limit_count: Math.max(
      0,
      Number.isFinite(Number(mergedPreLimitCount)) ? Number(mergedPreLimitCount) : 0,
    ),
    primary_quality_gate_passed: Boolean(primaryQualityGatePassed),
    primary_quality_score:
      Number.isFinite(Number(primaryQualityScore)) && Number(primaryQualityScore) >= 0
        ? Math.max(0, Math.min(1, Number(primaryQualityScore)))
        : null,
    low_quality_nonempty_detected: Boolean(lowQualityNonemptyDetected),
    supplement_attempted: Boolean(supplementAttempted),
    supplement_skip_reason: supplementSkipReason ? String(supplementSkipReason) : null,
    retry_attempt_count: Math.max(
      0,
      Number.isFinite(Number(retryAttemptCount)) ? Number(retryAttemptCount) : 0,
    ),
    fallback_attempt_count: Math.max(
      0,
      Number.isFinite(Number(fallbackAttemptCount)) ? Number(fallbackAttemptCount) : 0,
    ),
    selected_fallback_attempt: Math.max(
      0,
      Number.isFinite(Number(selectedFallbackAttempt)) ? Number(selectedFallbackAttempt) : 0,
    ),
    final_returned_count: Math.max(
      0,
      Number.isFinite(Number(finalReturnedCount)) ? Number(finalReturnedCount) : 0,
    ),
    ambiguity_score_pre: Number.isFinite(Number(ambiguityScorePre))
      ? Math.max(0, Math.min(1, Number(ambiguityScorePre)))
      : null,
    ambiguity_score_post: Number.isFinite(Number(ambiguityScorePost))
      ? Math.max(0, Math.min(1, Number(ambiguityScorePost)))
      : null,
    clarify_triggered: Boolean(clarifyTriggered),
    degrade_flags:
      degradeFlags && typeof degradeFlags === 'object' && !Array.isArray(degradeFlags)
        ? {
            vector_skipped: Boolean(degradeFlags.vector_skipped),
            behavior_skipped: Boolean(degradeFlags.behavior_skipped),
            nlu_degraded: Boolean(degradeFlags.nlu_degraded),
          }
        : null,
  };
}

function buildSearchTrace({
  traceId,
  rawQuery,
  expandedQuery,
  expansionMode,
  intent,
  cacheStage,
  upstreamStage,
  resolverStage,
  finalDecision,
  queryClass = null,
  rewriteGate = null,
  associationPlan = null,
  flagsSnapshot = null,
}) {
  return {
    trace_id: String(traceId || ''),
    raw_query: String(rawQuery || ''),
    expanded_query: String(expandedQuery || rawQuery || ''),
    expansion_mode: String(expansionMode || 'conservative'),
    query_class: queryClass ? String(queryClass) : null,
    rewrite_gate:
      rewriteGate && typeof rewriteGate === 'object' && !Array.isArray(rewriteGate)
        ? rewriteGate
        : null,
    association_plan:
      associationPlan && typeof associationPlan === 'object' && !Array.isArray(associationPlan)
        ? associationPlan
        : null,
    flags_snapshot:
      flagsSnapshot && typeof flagsSnapshot === 'object' && !Array.isArray(flagsSnapshot)
        ? flagsSnapshot
        : null,
    intent_domain: intent?.primary_domain || null,
    intent_target: intent?.target_object?.type || null,
    intent_scenario: intent?.scenario?.name || null,
    scenario: intent?.scenario?.name || null,
    cache_stage: cacheStage || null,
    upstream_stage: upstreamStage || null,
    resolver_stage: resolverStage || null,
    final_decision: String(finalDecision || 'unknown'),
  };
}

function classifyBeautyMixBucket(product) {
  const text = buildFallbackCandidateText(product);
  if (!text) return 'other';
  return classifyBeautyBucketFromText(text);
}

function buildCategoryMixTopN(products, topN = 10) {
  const list = Array.isArray(products) ? products.slice(0, Math.max(1, Number(topN) || 10)) : [];
  const buckets = {};
  for (const product of list) {
    const bucket = classifyBeautyMixBucket(product);
    buckets[bucket] = (buckets[bucket] || 0) + 1;
  }
  return buckets;
}

function buildSearchRelevanceDebug({ intent, products, diversityPenaltyApplied = false }) {
  const domain = String(intent?.primary_domain || '');
  if (!domain) return null;
  const out = {
    intent_domain: intent?.primary_domain || null,
    intent_scenario: intent?.scenario?.name || null,
    diversity_penalty_applied: Boolean(diversityPenaltyApplied),
  };
  if (domain === 'beauty') {
    out.category_mix_topN = buildCategoryMixTopN(products, 10);
  } else {
    out.category_mix_topN = null;
  }
  return out;
}

function buildServiceVersionMetadata() {
  return {
    service: SERVICE_NAME,
    commit: SERVICE_GIT_SHA_SHORT,
    build_id: SERVICE_BUILD_ID,
    branch: SERVICE_GIT_BRANCH || null,
    deployment_id: SERVICE_DEPLOYMENT_ID || null,
    started_at: SERVICE_STARTED_AT,
  };
}

function completeServiceVersionMetadata(existing = null) {
  const base = buildServiceVersionMetadata();
  const current =
    existing && typeof existing === 'object' && !Array.isArray(existing)
      ? existing
      : {};
  return {
    ...base,
    ...current,
    service: firstNonEmptyString(current.service, base.service) || null,
    commit: firstNonEmptyString(current.commit, base.commit) || null,
    build_id: firstNonEmptyString(current.build_id, current.buildId, base.build_id) || null,
    branch: firstNonEmptyString(current.branch, base.branch) || null,
    deployment_id: firstNonEmptyString(current.deployment_id, current.deploymentId, base.deployment_id) || null,
    started_at: firstNonEmptyString(current.started_at, current.startedAt, base.started_at) || null,
  };
}

function buildCacheStageDiagnosticBundle(cacheStage = null) {
  const stage =
    cacheStage && typeof cacheStage === 'object' && !Array.isArray(cacheStage)
      ? cacheStage
      : null;
  if (!stage) return null;
  const retrievalSources = Array.isArray(stage.retrieval_sources) ? stage.retrieval_sources : [];
  const strictSource =
    retrievalSources.find(
      (item) => item && typeof item === 'object' && String(item.source || '') === 'lexical_cache',
    ) || null;
  const relaxedSource =
    retrievalSources.find(
      (item) =>
        item &&
        typeof item === 'object' &&
        String(item.source || '') === 'lexical_cache_relaxed_no_onboarding',
    ) || null;
  const intOrZero = (value) => {
    const parsed = Number(value);
    return Number.isFinite(parsed) ? Math.max(0, Math.floor(parsed)) : 0;
  };
  const selectedSource =
    stage.selected_source != null ? String(stage.selected_source || '').trim() || null : null;
  return {
    cache_stage_attempted: Boolean(stage.attempted),
    cache_stage_query_terms: Array.isArray(stage.query_terms) ? stage.query_terms : [],
    cache_stage_strict_total: intOrZero(
      stage.strict_total != null ? stage.strict_total : strictSource?.total,
    ),
    cache_stage_relaxed_total: intOrZero(
      stage.relaxed_total != null ? stage.relaxed_total : relaxedSource?.total,
    ),
    cache_stage_filtered_irrelevant_count: intOrZero(stage.filtered_irrelevant_count),
    cache_stage_beauty_bucket:
      stage.beauty_bucket != null ? String(stage.beauty_bucket || '').trim() || null : null,
    cache_stage_selected_source: selectedSource,
  };
}

function buildCacheStageSnapshot({
  hit = false,
  candidateCount = 0,
  relevantCount = 0,
  retrievalSources = [],
  cacheRouteDebug = null,
  selectedSource = null,
} = {}) {
  const stage = {
    hit: Boolean(hit),
    candidate_count: Number(candidateCount || 0),
    relevant_count: Number(relevantCount || 0),
    retrieval_sources: Array.isArray(retrievalSources) ? retrievalSources : [],
    attempted: Boolean(cacheRouteDebug?.attempted),
    query_terms: Array.isArray(cacheRouteDebug?.cache_query_terms)
      ? cacheRouteDebug.cache_query_terms
      : [],
    strict_total: (() => {
      const lexical = Array.isArray(retrievalSources)
        ? retrievalSources.find((item) => String(item?.source || '') === 'lexical_cache')
        : null;
      return Number(lexical?.total || 0) || 0;
    })(),
    relaxed_total: (() => {
      const relaxed = Array.isArray(retrievalSources)
        ? retrievalSources.find(
            (item) => String(item?.source || '') === 'lexical_cache_relaxed_no_onboarding',
          )
        : null;
      return Number(relaxed?.total || 0) || 0;
    })(),
    filtered_irrelevant_count: Number(
      cacheRouteDebug?.internal_filtered_irrelevant_count || 0,
    ) || 0,
    beauty_bucket:
      cacheRouteDebug?.beauty_query_bucket != null
        ? String(cacheRouteDebug.beauty_query_bucket || '').trim() || null
        : null,
    selected_source: selectedSource || null,
  };
  return stage;
}

function decideGenericSkincareCachePreference({
  rawQuery = '',
  queryClass = null,
  beautyBucket = null,
  strictConstraintQuery = false,
  upstreamResponse = null,
  cacheResponse = null,
} = {}) {
  const queryText = String(rawQuery || '').trim();
  const normalizedQueryClass = String(queryClass || '').trim().toLowerCase();
  const beautyQueryProfile = buildBeautyQueryProfile({
    rawQuery: queryText,
    queryClass: normalizedQueryClass || undefined,
  });
  const effectiveBeautyBucket = String(
    beautyBucket || beautyQueryProfile?.bucket || '',
  ).trim().toLowerCase();
  const upstreamProducts = Array.isArray(upstreamResponse?.products) ? upstreamResponse.products : [];
  const cacheProducts = Array.isArray(cacheResponse?.products) ? cacheResponse.products : [];
  const upstreamQuerySource = String(upstreamResponse?.metadata?.query_source || '').trim();
  const cacheInternalProducts = cacheProducts.filter((product) => !isExternalSeedProduct(product));
  const hasSerumSignal = /\bserum(?:s)?\b/i.test(queryText);
  const genericQueryClass = !normalizedQueryClass || ['category', 'exploratory'].includes(normalizedQueryClass);
  const genericSerumCategoryQuery =
    hasSerumSignal &&
    genericQueryClass &&
    effectiveBeautyBucket === 'skincare' &&
    !Boolean(strictConstraintQuery);
  const upstreamExternalOnly =
    upstreamProducts.length > 0 && upstreamProducts.every((product) => isExternalSeedProduct(product));
  const evaluated =
    genericSerumCategoryQuery &&
    cacheInternalProducts.length > 0 &&
    upstreamProducts.length > 0 &&
    !upstreamQuerySource.startsWith('cache_');

  if (!genericSerumCategoryQuery) {
    return {
      evaluated: false,
      decision: 'keep_upstream',
      reason: 'not_generic_skincare_serum_query',
      beauty_bucket: effectiveBeautyBucket || null,
      cache_internal_count: cacheInternalProducts.length,
      upstream_external_only: upstreamExternalOnly,
      upstream_query_source: upstreamQuerySource || null,
    };
  }

  if (!upstreamExternalOnly) {
    return {
      evaluated,
      decision: 'keep_upstream',
      reason: 'upstream_not_external_only',
      beauty_bucket: effectiveBeautyBucket || null,
      cache_internal_count: cacheInternalProducts.length,
      upstream_external_only: upstreamExternalOnly,
      upstream_query_source: upstreamQuerySource || null,
    };
  }

  if (cacheInternalProducts.length <= 0) {
    return {
      evaluated,
      decision: 'keep_upstream',
      reason: 'cache_internal_unavailable',
      beauty_bucket: effectiveBeautyBucket || null,
      cache_internal_count: 0,
      upstream_external_only: upstreamExternalOnly,
      upstream_query_source: upstreamQuerySource || null,
    };
  }

  return {
    evaluated: true,
    decision: 'replace_with_cache',
    reason: 'generic_skincare_internal_preferred',
    beauty_bucket: effectiveBeautyBucket || null,
    cache_internal_count: cacheInternalProducts.length,
    upstream_external_only: upstreamExternalOnly,
    upstream_query_source: upstreamQuerySource || null,
  };
}

function resolvePublicBeautyUnifiedMinAcceptCount(requestedLimit = 20) {
  const safeRequestedLimit = Math.min(
    Math.max(1, Number(requestedLimit || 20) || 20),
    SEARCH_LIMIT_MAX,
  );
  return safeRequestedLimit >= 8 ? 8 : safeRequestedLimit;
}

function resolvePublicBeautyCompoundIntent(queryText = '') {
  const normalized = normalizeSearchTextForMatch(queryText);
  if (!normalized) return null;
  const tokens = new Set(tokenizeSearchTextForMatch(normalized));
  if (normalized === 'hair oil' || (tokens.has('hair') && tokens.has('oil'))) return 'hair_oil';
  if (normalized === 'lip balm' || (tokens.has('lip') && tokens.has('balm'))) return 'lip_balm';
  if (normalized === 'lip oil' || (tokens.has('lip') && tokens.has('oil'))) return 'lip_oil';
  return null;
}

function shouldForcePublicBeautyUnifiedExternalSeedContract(search = {}, metadata = {}) {
  if (!shouldDefaultPublicSearchExternalSeedContract(search, metadata)) return false;
  const queryText = String(search?.query || search?.q || '').trim();
  if (!queryText) return false;
  const beautyQueryProfile = buildBeautyQueryProfile({ rawQuery: queryText });
  return Boolean(beautyQueryProfile?.isBeautyQuery);
}

function isPublicBeautyUnifiedMainlineSearch({
  operation = '',
  metadata = null,
  search = null,
  queryText = '',
  queryClass = null,
  intent = null,
  invokeSearchRail = null,
} = {}) {
  if (String(operation || '').trim().toLowerCase() !== 'find_products_multi') return false;
  const normalizedMetadata =
    metadata && typeof metadata === 'object' && !Array.isArray(metadata) ? metadata : {};
  const normalizedSearch =
    search && typeof search === 'object' && !Array.isArray(search) ? search : {};
  const rail = String(
    invokeSearchRail ||
      normalizedMetadata.invoke_search_rail ||
      resolveInvokeSearchRailFromMetadata(normalizedMetadata) ||
      '',
  )
    .trim()
    .toLowerCase();
  if (
    rail !== 'public_observability' &&
    !isPublicSearchSource(normalizedMetadata?.source) &&
    !isPublicSearchRouteMetadata(normalizedMetadata) &&
    !isPublicBeautyMainlineSearchRoute(normalizedMetadata)
  ) {
    return false;
  }
  if (parseQueryBoolean(normalizedSearch.product_only ?? normalizedSearch.productOnly) === true) {
    return false;
  }
  if (
    parseQueryBoolean(
      normalizedSearch.local_mainline_child ?? normalizedSearch.localMainlineChild,
    ) === true
  ) {
    return false;
  }
  if (hasStrictInvokeCatalogSurface(normalizedSearch, normalizedMetadata)) return false;
  const uiSurface = normalizeSearchUiSurface(
    normalizedMetadata?.ui_surface ||
      normalizedMetadata?.uiSurface ||
      normalizedSearch?.ui_surface ||
      normalizedSearch?.uiSurface,
  );
  if (uiSurface === 'ingredient_plan_guidance_only') return false;
  const rawQuery = String(queryText || normalizedSearch?.query || normalizedSearch?.q || '').trim();
  if (!rawQuery) return false;
  const anchorTokens = extractSearchAnchorTokens(rawQuery);
  if (isLookupStyleSearchQuery(rawQuery, anchorTokens) || isKnownLookupAliasQuery(rawQuery)) {
    return false;
  }
  const normalizedQueryClass = String(queryClass || intent?.query_class || '')
    .trim()
    .toLowerCase();
  const beautyQueryProfile = buildBeautyQueryProfile({
    rawQuery,
    queryClass: normalizedQueryClass || undefined,
    intent,
  });
  if (!beautyQueryProfile?.isBeautyQuery) return false;
  const fastpath = resolveBeautyCategoryBrowseFastpath(rawQuery, {
    queryClass: normalizedQueryClass || beautyQueryProfile?.queryClass,
  });
  if (fastpath) return true;
  const brandLike = Boolean(detectBrandEntities(rawQuery, { candidateProducts: [] })?.brand_like);
  const tokenCount = tokenizeSearchTextForMatch(rawQuery).length;
  return Boolean(
    beautyQueryProfile?.isSpecificBeautyQuery &&
      ['category', 'exploratory', 'attribute', ''].includes(normalizedQueryClass) &&
      tokenCount > 0 &&
      tokenCount <= 3 &&
      !brandLike,
  );
}

function hasExplicitBeautyCatalogSurface(search = {}, metadata = {}) {
  return (
    String(
      firstNonEmptyString(
        search?.catalog_surface,
        search?.catalogSurface,
        metadata?.catalog_surface,
        metadata?.catalogSurface,
      ) || '',
    )
      .trim()
      .toLowerCase() === 'beauty'
  );
}

function shouldBridgePublicBeautySearchToDiscovery({
  operation = '',
  metadata = null,
  search = null,
  queryText = '',
  queryClass = null,
  intent = null,
  invokeSearchRail = null,
  strictDecision = null,
} = {}) {
  if (String(operation || '').trim() !== 'find_products_multi') return false;
  const searchObj =
    search && typeof search === 'object' && !Array.isArray(search) ? search : {};
  const metadataObj =
    metadata && typeof metadata === 'object' && !Array.isArray(metadata) ? metadata : {};
  if (strictDecision?.enabled === true) return false;
  const rawQuery = String(queryText || searchObj.query || searchObj.q || '').trim();
  if (!rawQuery) return false;
  if (!hasExplicitBeautyCatalogSurface(searchObj, metadataObj)) {
    return false;
  }
  if (
    !isPublicBeautyUnifiedMainlineSearch({
      operation,
      metadata: metadataObj,
      search: searchObj,
      queryText: rawQuery,
      queryClass,
      intent,
      invokeSearchRail,
    })
  ) {
    return false;
  }
  return true;
}

function resolvePublicBrandScopeForDiscovery({
  operation = '',
  metadata = null,
  search = null,
  queryText = '',
  invokeSearchRail = null,
} = {}) {
  if (String(operation || '').trim().toLowerCase() !== 'find_products_multi') return [];
  const normalizedMetadata =
    metadata && typeof metadata === 'object' && !Array.isArray(metadata) ? metadata : {};
  const normalizedSearch =
    search && typeof search === 'object' && !Array.isArray(search) ? search : {};
  const rail = String(
    invokeSearchRail ||
      normalizedMetadata.invoke_search_rail ||
      resolveInvokeSearchRailFromMetadata(normalizedMetadata) ||
      '',
  )
    .trim()
    .toLowerCase();
  if (
    rail !== 'public_observability' &&
    !isPublicSearchSource(normalizedMetadata?.source) &&
    !isPublicSearchRouteMetadata(normalizedMetadata) &&
    !isPublicBeautyMainlineSearchRoute(normalizedMetadata)
  ) {
    return [];
  }
  if (parseQueryBoolean(normalizedSearch.product_only ?? normalizedSearch.productOnly) === true) {
    return [];
  }
  if (
    parseQueryBoolean(
      normalizedSearch.local_mainline_child ?? normalizedSearch.localMainlineChild,
    ) === true
  ) {
    return [];
  }
  if (hasStrictInvokeCatalogSurface(normalizedSearch, normalizedMetadata)) return [];
  const rawQuery = String(queryText || normalizedSearch?.query || normalizedSearch?.q || '').trim();
  if (!rawQuery) return [];
  const brandDetection = detectBrandEntities(rawQuery, { candidateProducts: [] });
  if (!brandDetection?.brand_like) return [];
  const brands = uniqueStrings(Array.isArray(brandDetection.brands) ? brandDetection.brands : []).slice(
    0,
    4,
  );
  if (brands.length === 0) return [];
  return brands;
}

function buildDiscoveryPayloadFromPublicBeautySearch(
  search = {},
  metadata = {},
  queryText = '',
  options = {},
) {
  const limit = Math.min(
    Math.max(1, Number(search?.limit || search?.page_size || search?.pageSize || 24) || 24),
    SEARCH_LIMIT_MAX,
  );
  const offset = Math.max(0, Number(search?.offset || 0) || 0);
  const page =
    Number(search?.page || 0) > 0
      ? Math.max(1, Number(search.page || 1) || 1)
      : Math.floor(offset / Math.max(1, limit)) + 1;
  const locale = firstNonEmptyString(
    search?.locale,
    search?.language,
    metadata?.locale,
    metadata?.language,
    'en-US',
  );
  const debug =
    search?.debug === true ||
    metadata?.debug === true ||
    String(search?.debug || metadata?.debug || '').trim().toLowerCase() === 'true';
  const brandNames = uniqueStrings(options?.brandNames || []);
  return {
    discoveryPayload: {
      surface: 'browse_products',
      page,
      limit,
      debug,
      query: { text: String(queryText || search?.query || search?.q || '').trim() },
      ...(brandNames.length > 0 ? { scope: { brand_names: brandNames } } : {}),
      context: {
        auth_state: 'anonymous',
        locale,
        recent_views: [],
        recent_queries: [],
      },
    },
    page,
    limit,
    offset,
  };
}

function countDiscoveryProviderReturns(metadata = {}, providerName = '') {
  const target = String(providerName || '').trim();
  const providerBreakdown = Array.isArray(metadata?.provider_breakdown)
    ? metadata.provider_breakdown
    : [];
  return providerBreakdown
    .filter((entry) => String(entry?.provider || '').trim() === target)
    .reduce((sum, entry) => sum + (Number(entry?.returned || 0) || 0), 0);
}

function buildFindProductsMultiDiscoveryBridgeResponse({
  discoveryResponse = null,
  search = null,
  metadata = null,
  queryText = '',
  page = 1,
  limit = 24,
  offset = 0,
} = {}) {
  const sourceMetadata =
    metadata && typeof metadata === 'object' && !Array.isArray(metadata) ? metadata : {};
  const discoveryMetadata =
    discoveryResponse?.metadata &&
    typeof discoveryResponse.metadata === 'object' &&
    !Array.isArray(discoveryResponse.metadata)
      ? discoveryResponse.metadata
      : {};
  const products = Array.isArray(discoveryResponse?.products)
    ? discoveryResponse.products
    : [];
  const routeHealth =
    discoveryMetadata.route_health &&
    typeof discoveryMetadata.route_health === 'object' &&
    !Array.isArray(discoveryMetadata.route_health)
      ? discoveryMetadata.route_health
      : {};
  const underfilledReason = firstNonEmptyString(
    discoveryMetadata.underfilled_reason,
    discoveryMetadata.strict_empty_reason,
    routeHealth.underfilled_reason,
  );
  const strictEmpty = products.length === 0;
  const externalSeedCount =
    Number(discoveryMetadata.external_seed_qualified_count || 0) ||
    Number(discoveryMetadata?.candidate_counts?.external_seed_products || 0) ||
    countDiscoveryProviderReturns(discoveryMetadata, 'external_seeds');
  const internalCount =
    Number(discoveryMetadata?.candidate_counts?.internal_products || 0) ||
    countDiscoveryProviderReturns(discoveryMetadata, 'internal_catalog');

  return normalizeAgentProductsListResponse(
    {
      status: 'success',
      success: true,
      products,
      total:
        Number.isFinite(Number(discoveryResponse?.total)) && Number(discoveryResponse.total) >= 0
          ? Number(discoveryResponse.total)
          : products.length,
      page,
      page_size: products.length,
      reply: strictEmpty
        ? "I couldn't build a reliable beauty set from current inventory, so I won't show unrelated products."
        : null,
      metadata: {
        ...discoveryMetadata,
        query_source: 'beauty_discovery_mainline',
        primary_lane: 'beauty_discovery_mainline',
        primary_retrieval_contract: 'agent_v1_search_beauty_mainline',
        search_request_contract:
          sourceMetadata.search_request_contract || discoveryMetadata.search_request_contract || null,
        contract_bridge: {
          ...(sourceMetadata.contract_bridge &&
          typeof sourceMetadata.contract_bridge === 'object' &&
          !Array.isArray(sourceMetadata.contract_bridge)
            ? sourceMetadata.contract_bridge
            : {}),
          attempted_contract: 'agent_v1_search_beauty_mainline',
          resolved_contract: 'agent_v1_search_beauty_mainline',
          legacy_fallback: false,
        },
        source_breakdown: {
          ...(discoveryMetadata.source_breakdown &&
          typeof discoveryMetadata.source_breakdown === 'object' &&
          !Array.isArray(discoveryMetadata.source_breakdown)
            ? discoveryMetadata.source_breakdown
            : {}),
          internal_count: internalCount,
          external_seed_count: externalSeedCount,
          stale_cache_used: false,
          strategy_applied: 'unified_relevance',
        },
        route_health: {
          ...routeHealth,
          orchestrator_path: 'local_discovery_bridge',
          decision_node: 'beauty_discovery_mainline',
          primary_path_used: 'beauty_discovery_mainline',
          fallback_triggered: false,
          fallback_reason: null,
          final_returned_count: products.length,
          primary_quality_gate_passed:
            routeHealth.primary_quality_gate_passed != null
              ? routeHealth.primary_quality_gate_passed
              : products.length > 0 && !underfilledReason,
          primary_underfilled_public_beauty_unified:
            underfilledReason === 'public_search_underfilled_unified_relevance',
          primary_exact_intent_underfilled_public_beauty:
            underfilledReason === 'public_search_underfilled_exact_intent',
          underfilled_reason: underfilledReason || null,
        },
        ...(underfilledReason ? { underfilled_reason: underfilledReason } : {}),
        ...(strictEmpty
          ? {
              strict_empty: true,
              strict_empty_reason:
                underfilledReason || 'public_search_discovery_mainline_empty',
            }
          : {}),
        public_search_discovery_bridge: true,
        bridged_operation: 'get_discovery_feed',
        bridged_query_text: String(queryText || search?.query || search?.q || '').trim(),
      },
    },
    { limit, offset },
  );
}

function buildPublicBeautyUnifiedSearchDedupeKey(product) {
  if (!product || typeof product !== 'object') return '';
  const urlKey =
    normalizeSearchProductUrlForDedupe(product.canonical_url) ||
    normalizeSearchProductUrlForDedupe(product.destination_url) ||
    normalizeSearchProductUrlForDedupe(product.external_url) ||
    normalizeSearchProductUrlForDedupe(product.url);
  if (urlKey) return urlKey;
  const brandKey = extractSearchProductBrandToken(product);
  const titleKey = normalizeSearchProductTitleForDedupe(product);
  if (brandKey && titleKey) return `${brandKey}::${titleKey}`;
  if (titleKey) return titleKey;
  return buildSearchProductKey(product);
}

function mergePublicBeautyUnifiedOfferLists(leftOffers = [], rightOffers = []) {
  const offers = [];
  const seen = new Set();
  const pushOffer = (offer) => {
    if (!offer || typeof offer !== 'object') return;
    const offerKey = String(
      offer.offer_id ||
        offer.offerId ||
        `${offer.merchant_id || offer.merchantId || ''}::${offer.variant_id || offer.variantId || ''}::${offer.sku_id || offer.skuId || ''}::${offer.product_id || offer.productId || ''}::${offer.url || offer.destination_url || offer.external_url || ''}`,
    ).trim();
    if (offerKey && seen.has(offerKey)) return;
    if (offerKey) seen.add(offerKey);
    offers.push(offer);
  };
  for (const offer of Array.isArray(leftOffers) ? leftOffers : []) pushOffer(offer);
  for (const offer of Array.isArray(rightOffers) ? rightOffers : []) pushOffer(offer);
  return offers;
}

function mergePublicBeautyUnifiedDuplicateProduct(primary, duplicate) {
  if (!primary || typeof primary !== 'object') return duplicate;
  if (!duplicate || typeof duplicate !== 'object') return primary;
  const merged = { ...primary };
  const mergedOffers = mergePublicBeautyUnifiedOfferLists(primary.offers, duplicate.offers);
  if (mergedOffers.length > 0) {
    merged.offers = mergedOffers;
  }
  const mergedSources = Array.from(
    new Set(
      [
        ...(Array.isArray(primary.merged_sources) ? primary.merged_sources : []),
        primary.source,
        duplicate.source,
        primary.merchant_id || primary.merchantId,
        duplicate.merchant_id || duplicate.merchantId,
      ]
        .map((value) => String(value || '').trim())
        .filter(Boolean),
    ),
  );
  if (mergedSources.length > 0) {
    merged.merged_sources = mergedSources;
  }
  const mergedProvenance = [
    ...(Array.isArray(primary.merged_provenance) ? primary.merged_provenance : []),
    ...(primary.provenance && typeof primary.provenance === 'object' ? [primary.provenance] : []),
    ...(duplicate.provenance && typeof duplicate.provenance === 'object' ? [duplicate.provenance] : []),
  ];
  if (mergedProvenance.length > 0) {
    merged.merged_provenance = mergedProvenance;
  }
  if (!merged.provenance && duplicate.provenance && typeof duplicate.provenance === 'object') {
    merged.provenance = duplicate.provenance;
  }
  return merged;
}

function mergePublicBeautyUnifiedSearchProducts(products = [], { limit = null } = {}) {
  const list = Array.isArray(products) ? products : [];
  if (list.length <= 1) return list.slice();
  const safeLimit =
    limit == null
      ? null
      : Math.min(Math.max(1, Number(limit || 0) || 0), SEARCH_LIMIT_MAX);
  const seenProductKeys = new Set();
  const mergedByDedupeKey = new Map();
  const ordered = [];
  for (const product of list) {
    if (!product || typeof product !== 'object') continue;
    const productKey = buildSearchProductKey(product);
    if (productKey && seenProductKeys.has(productKey)) continue;
    if (productKey) seenProductKeys.add(productKey);
    const dedupeKey = buildPublicBeautyUnifiedSearchDedupeKey(product);
    if (!dedupeKey) {
      ordered.push(product);
      if (safeLimit && ordered.length >= safeLimit) break;
      continue;
    }
    if (!mergedByDedupeKey.has(dedupeKey)) {
      mergedByDedupeKey.set(dedupeKey, ordered.length);
      ordered.push(product);
    } else {
      const existingIndex = mergedByDedupeKey.get(dedupeKey);
      ordered[existingIndex] = mergePublicBeautyUnifiedDuplicateProduct(
        ordered[existingIndex],
        product,
      );
    }
    if (safeLimit && ordered.length >= safeLimit) break;
  }
  return ordered;
}

function withSearchDiagnostics(body, diagnostics = {}) {
  if (!body || typeof body !== 'object' || Array.isArray(body)) return body;
  const metadata =
    body.metadata && typeof body.metadata === 'object' && !Array.isArray(body.metadata)
      ? { ...body.metadata }
      : {};
  const existingRouteHealth =
    metadata.route_health && typeof metadata.route_health === 'object' && !Array.isArray(metadata.route_health)
      ? { ...metadata.route_health }
      : {};
  const routeHealthPatch =
    diagnostics.route_health && typeof diagnostics.route_health === 'object' && !Array.isArray(diagnostics.route_health)
      ? diagnostics.route_health
      : null;
  const routeHealth = routeHealthPatch ? { ...existingRouteHealth, ...routeHealthPatch } : existingRouteHealth;
  const existingSearchDecision =
    metadata.search_decision && typeof metadata.search_decision === 'object' && !Array.isArray(metadata.search_decision)
      ? { ...metadata.search_decision }
      : null;
  const intNonNegative = (value) => {
    const parsed = Number(value);
    return Number.isFinite(parsed) ? Math.max(0, Math.floor(parsed)) : 0;
  };
  const fallbackStrategy =
    metadata.fallback_strategy && typeof metadata.fallback_strategy === 'object'
      ? metadata.fallback_strategy
      : {};
  const secondaryAttempts = Array.isArray(fallbackStrategy.secondary_attempts)
    ? fallbackStrategy.secondary_attempts.filter((item) => item && typeof item === 'object')
    : [];
  const secondaryAttemptCount = intNonNegative(fallbackStrategy.secondary_attempt_count);
  const retryBaseQueryNormalized = normalizeSearchTextForMatch(
    String(
      diagnostics?.search_trace?.raw_query ||
        metadata?.search_trace?.raw_query ||
        '',
    ).trim(),
  );
  const semanticRetryQueryCandidate =
    metadata.semantic_retry_query ||
    routeHealth.semantic_retry_query ||
    fallbackStrategy.secondary_selected_query ||
    (secondaryAttempts.length > 1 ? secondaryAttempts[secondaryAttempts.length - 1]?.query : null) ||
    null;
  const semanticRetryQueryNormalized = normalizeSearchTextForMatch(
    String(semanticRetryQueryCandidate || '').trim(),
  );
  const semanticRetryActualAttemptedDerived = Boolean(
    metadata.semantic_retry_actual_attempted === true ||
      routeHealth.semantic_retry_actual_attempted === true ||
      fallbackStrategy.secondary_actual_retry_attempted === true ||
      String(metadata?.proxy_search_fallback?.query_variant || '').trim() === 'semantic_retry' ||
      secondaryAttempts.length > 1 ||
      secondaryAttemptCount > 1 ||
      (
        semanticRetryQueryNormalized &&
        retryBaseQueryNormalized &&
        semanticRetryQueryNormalized !== retryBaseQueryNormalized
      ),
  );
  const semanticRetryAppliedDerived = semanticRetryActualAttemptedDerived;
  const semanticRetryQueryDerived = semanticRetryAppliedDerived ? semanticRetryQueryCandidate : null;
  const semanticRetryHitsDerived = intNonNegative(
    metadata.semantic_retry_hits != null
      ? metadata.semantic_retry_hits
      : routeHealth.semantic_retry_hits != null
      ? routeHealth.semantic_retry_hits
      : semanticRetryAppliedDerived
      ? fallbackStrategy.secondary_usable_count
      : 0,
  );
  const bodyProductsForHealth = Array.isArray(body?.products) ? body.products : [];
  const bodyExternalCountForHealth = bodyProductsForHealth.filter((product) =>
    isExternalSeedProduct(product),
  ).length;
  const bodyInternalCountForHealth = Math.max(0, bodyProductsForHealth.length - bodyExternalCountForHealth);
  routeHealth.orchestrator_path = String(
    routeHealth.orchestrator_path || metadata.orchestrator_path || 'external_invoke_route',
  );
  routeHealth.decision_node = String(
    routeHealth.decision_node ||
      metadata.decision_node ||
      metadata.query_source ||
      routeHealth.primary_path_used ||
      'unknown',
  );
  const normalizedQuerySemanticClass = (() => {
    const routeDebugSemanticClass = String(
      metadata?.route_debug?.policy?.ambiguity?.query_semantic_class || '',
    )
      .trim()
      .toLowerCase();
    const inferredByRawQuery = (() => {
      const raw =
        String(diagnostics?.search_trace?.raw_query || metadata?.search_trace?.raw_query || '').trim();
      if (!raw) return '';
      return hasFragranceQuerySignal(raw) ? 'fragrance' : '';
    })();
    const candidate =
      [
        routeHealth.query_semantic_class,
        metadata.query_semantic_class,
        existingSearchDecision?.query_semantic_class,
        routeDebugSemanticClass,
      ].find((value) => value != null && String(value).trim() !== '') || null;
    let value = String(candidate || '').trim().toLowerCase();
    if ((!value || value === 'default') && inferredByRawQuery) {
      value = inferredByRawQuery;
    }
    return value || null;
  })();
  routeHealth.query_semantic_class = normalizedQuerySemanticClass;
  routeHealth.domain_filter_dropped_external = intNonNegative(
    routeHealth.domain_filter_dropped_external != null
      ? routeHealth.domain_filter_dropped_external
      : metadata.domain_filter_dropped_external != null
      ? metadata.domain_filter_dropped_external
      : existingSearchDecision?.domain_filter_dropped_external,
  );
  routeHealth.external_fill_gate_reason =
    routeHealth.external_fill_gate_reason != null
      ? routeHealth.external_fill_gate_reason
      : metadata.external_fill_gate_reason || null;
  routeHealth.semantic_retry_applied = semanticRetryAppliedDerived;
  routeHealth.semantic_retry_actual_attempted = semanticRetryActualAttemptedDerived;
  routeHealth.semantic_retry_query = semanticRetryQueryDerived ? String(semanticRetryQueryDerived) : null;
  routeHealth.semantic_retry_hits = semanticRetryHitsDerived;
  routeHealth.external_seed_query_timeout = Boolean(
    routeHealth.external_seed_query_timeout != null
      ? routeHealth.external_seed_query_timeout
      : metadata.external_seed_query_timeout,
  );
  routeHealth.external_seed_skip_reason =
    routeHealth.external_seed_skip_reason != null
      ? String(routeHealth.external_seed_skip_reason || '').trim() || null
      : String(metadata.external_seed_skip_reason || '').trim() || null;
  routeHealth.external_seed_cache_hit =
    Boolean(
      routeHealth.external_seed_cache_hit != null
        ? routeHealth.external_seed_cache_hit
        : metadata.external_seed_cache_hit,
    ) || routeHealth.external_seed_skip_reason === 'cache_hit';
  routeHealth.external_seed_rows_fetched = intNonNegative(
    routeHealth.external_seed_rows_fetched != null
      ? routeHealth.external_seed_rows_fetched
      : metadata.external_seed_rows_fetched,
  );
  routeHealth.external_seed_rows_built = intNonNegative(
    routeHealth.external_seed_rows_built != null
      ? routeHealth.external_seed_rows_built
      : metadata.external_seed_rows_built,
  );
  const fallbackReasonToken = String(
    routeHealth.fallback_reason != null ? routeHealth.fallback_reason : metadata.fallback_reason || '',
  )
    .trim()
    .toLowerCase();
  const lowQualityReasonHint = fallbackReasonToken.includes('low_quality');
  routeHealth.external_seed_brand_strict_rows = intNonNegative(
    routeHealth.external_seed_brand_strict_rows != null
      ? routeHealth.external_seed_brand_strict_rows
      : metadata.external_seed_brand_strict_rows,
  );
  routeHealth.external_seed_brand_relevant_rows = intNonNegative(
    routeHealth.external_seed_brand_relevant_rows != null
      ? routeHealth.external_seed_brand_relevant_rows
      : metadata.external_seed_brand_relevant_rows,
  );
  routeHealth.external_seed_broad_fallback_used = Boolean(
    routeHealth.external_seed_broad_fallback_used != null
      ? routeHealth.external_seed_broad_fallback_used
      : metadata.external_seed_broad_fallback_used,
  );
  routeHealth.external_seed_broad_scope_rows = intNonNegative(
    routeHealth.external_seed_broad_scope_rows != null
      ? routeHealth.external_seed_broad_scope_rows
      : metadata.external_seed_broad_scope_rows,
  );
  routeHealth.internal_raw_count = Math.max(
    intNonNegative(
      routeHealth.internal_raw_count != null
        ? routeHealth.internal_raw_count
        : metadata.internal_raw_count != null
        ? metadata.internal_raw_count
        : metadata?.source_breakdown?.internal_count,
    ),
    bodyInternalCountForHealth,
  );
  routeHealth.external_raw_count = Math.max(
    intNonNegative(
      routeHealth.external_raw_count != null
        ? routeHealth.external_raw_count
        : metadata.external_raw_count != null
        ? metadata.external_raw_count
        : metadata?.source_breakdown?.external_seed_count,
    ),
    bodyExternalCountForHealth,
  );
  const externalSeedReturnedCount = routeHealth.external_raw_count;
  routeHealth.external_seed_returned_count = externalSeedReturnedCount;
  routeHealth.merged_pre_limit_count = Math.max(
    routeHealth.merged_pre_limit_count != null
      ? intNonNegative(routeHealth.merged_pre_limit_count)
      : metadata.merged_pre_limit_count != null
      ? intNonNegative(metadata.merged_pre_limit_count)
      : intNonNegative(body?.total),
    bodyProductsForHealth.length,
  );
  const primaryQualityScoreRaw =
    routeHealth.primary_quality_score != null
      ? routeHealth.primary_quality_score
      : metadata.primary_quality_score;
  routeHealth.primary_quality_score =
    Number.isFinite(Number(primaryQualityScoreRaw)) && Number(primaryQualityScoreRaw) >= 0
      ? Math.max(0, Math.min(1, Number(primaryQualityScoreRaw)))
      : null;
  const lowQualityNonemptyDerived = Boolean(
    routeHealth.low_quality_nonempty_detected != null
      ? routeHealth.low_quality_nonempty_detected
      : metadata.low_quality_nonempty_detected,
  );
  const strictEmptyForHealth = Boolean(
    diagnostics.strict_empty === true ||
      metadata.strict_empty === true ||
      String(diagnostics.strict_empty_reason || metadata.strict_empty_reason || '').trim(),
  );
  routeHealth.low_quality_nonempty_detected = lowQualityNonemptyDerived || lowQualityReasonHint;
  if (strictEmptyForHealth || bodyProductsForHealth.length === 0) {
    routeHealth.primary_quality_gate_passed = false;
  } else if (lowQualityReasonHint) {
    routeHealth.primary_quality_gate_passed = false;
  } else {
    routeHealth.primary_quality_gate_passed = Boolean(
      routeHealth.primary_quality_gate_passed != null
        ? routeHealth.primary_quality_gate_passed
        : metadata.primary_quality_gate_passed != null
        ? metadata.primary_quality_gate_passed
        : !routeHealth.low_quality_nonempty_detected,
    );
  }
  routeHealth.supplement_attempted = Boolean(
    routeHealth.supplement_attempted != null
      ? routeHealth.supplement_attempted
      : metadata.supplement_attempted != null
      ? metadata.supplement_attempted
      : metadata?.search_stage_b?.attempted,
  );
  routeHealth.supplement_skip_reason =
    routeHealth.supplement_skip_reason != null
      ? String(routeHealth.supplement_skip_reason || '').trim() || null
      : String(
          metadata.supplement_skip_reason != null
            ? metadata.supplement_skip_reason
            : metadata?.search_stage_b?.reason || '',
        ).trim() || null;
  const retryAttemptCountDerived = intNonNegative(
    routeHealth.retry_attempt_count != null
      ? routeHealth.retry_attempt_count
      : metadata.retry_attempt_count != null
      ? metadata.retry_attempt_count
      : metadata?.fallback_strategy?.secondary_attempt_count,
  );
  routeHealth.retry_attempt_count = Math.max(
    retryAttemptCountDerived,
    secondaryAttemptCount,
    semanticRetryActualAttemptedDerived ? 1 : 0,
  );
  routeHealth.fallback_attempt_count = Math.max(
    intNonNegative(routeHealth.fallback_attempt_count),
    intNonNegative(metadata.fallback_attempt_count),
    secondaryAttemptCount,
  );
  routeHealth.selected_fallback_attempt = Math.max(
    intNonNegative(routeHealth.selected_fallback_attempt),
    intNonNegative(metadata.selected_fallback_attempt),
    intNonNegative(fallbackStrategy.secondary_selected_attempt),
  );
  routeHealth.final_returned_count = Math.max(
    intNonNegative(
      routeHealth.final_returned_count != null
        ? routeHealth.final_returned_count
        : metadata.final_returned_count != null
        ? metadata.final_returned_count
        : Array.isArray(body?.products)
        ? body.products.length
        : 0,
    ),
    bodyProductsForHealth.length,
  );
  const fallbackReason =
    routeHealth.fallback_reason != null
      ? routeHealth.fallback_reason
      : metadata.fallback_reason != null
      ? metadata.fallback_reason
      : null;
  routeHealth.fallback_reason = fallbackReason;
  metadata.orchestrator_path = routeHealth.orchestrator_path;
  metadata.decision_node = routeHealth.decision_node;
  metadata.query_semantic_class = routeHealth.query_semantic_class;
  metadata.domain_filter_dropped_external = routeHealth.domain_filter_dropped_external;
  metadata.external_fill_gate_reason = routeHealth.external_fill_gate_reason;
  metadata.semantic_retry_applied = routeHealth.semantic_retry_applied;
  metadata.semantic_retry_actual_attempted = routeHealth.semantic_retry_actual_attempted;
  metadata.semantic_retry_query = routeHealth.semantic_retry_query;
  metadata.semantic_retry_hits = routeHealth.semantic_retry_hits;
  metadata.external_seed_query_timeout = routeHealth.external_seed_query_timeout;
  metadata.external_seed_skip_reason = routeHealth.external_seed_skip_reason;
  metadata.external_seed_cache_hit = routeHealth.external_seed_cache_hit;
  metadata.external_seed_rows_fetched = routeHealth.external_seed_rows_fetched;
  metadata.external_seed_rows_built = routeHealth.external_seed_rows_built;
  metadata.external_seed_brand_strict_rows = routeHealth.external_seed_brand_strict_rows;
  metadata.external_seed_brand_relevant_rows = routeHealth.external_seed_brand_relevant_rows;
  metadata.external_seed_broad_fallback_used = routeHealth.external_seed_broad_fallback_used;
  metadata.external_seed_broad_scope_rows = routeHealth.external_seed_broad_scope_rows;
  metadata.external_seed_returned_count = externalSeedReturnedCount;
  metadata.internal_raw_count = routeHealth.internal_raw_count;
  metadata.external_raw_count = routeHealth.external_raw_count;
  metadata.merged_pre_limit_count = routeHealth.merged_pre_limit_count;
  metadata.primary_quality_gate_passed = routeHealth.primary_quality_gate_passed;
  metadata.primary_quality_score = routeHealth.primary_quality_score;
  metadata.low_quality_nonempty_detected = routeHealth.low_quality_nonempty_detected;
  metadata.supplement_attempted = routeHealth.supplement_attempted;
  metadata.supplement_skip_reason = routeHealth.supplement_skip_reason;
  metadata.retry_attempt_count = routeHealth.retry_attempt_count;
  metadata.fallback_attempt_count = routeHealth.fallback_attempt_count;
  metadata.selected_fallback_attempt = routeHealth.selected_fallback_attempt;
  metadata.final_returned_count = routeHealth.final_returned_count;
  metadata.fallback_reason = fallbackReason;
  const brandQueryBypassAmbiguity = Boolean(
    metadata.brand_query_bypass_ambiguity === true ||
      existingSearchDecision?.brand_query_bypass_ambiguity === true ||
      metadata?.route_debug?.policy?.ambiguity?.brand_query_bypass_ambiguity === true,
  );
  metadata.brand_query_bypass_ambiguity = brandQueryBypassAmbiguity;
  if (existingSearchDecision) {
    existingSearchDecision.query_semantic_class = routeHealth.query_semantic_class;
    existingSearchDecision.domain_filter_dropped_external = routeHealth.domain_filter_dropped_external;
    existingSearchDecision.brand_query_bypass_ambiguity = brandQueryBypassAmbiguity;
    const bodyProducts = Array.isArray(body?.products) ? body.products : [];
    const hasBodyClarification = Boolean(body?.clarification?.question);
    const decisionToken = String(existingSearchDecision.final_decision || '').trim();
    const productsEmpty = bodyProducts.length === 0;
    if (productsEmpty) {
      if (hasBodyClarification) {
        if (
          decisionToken === 'products_returned' ||
          decisionToken === 'upstream_returned' ||
          decisionToken === 'cache_returned' ||
          decisionToken === 'resolver_returned'
        ) {
          existingSearchDecision.final_decision = 'clarify';
        }
      } else if (
        decisionToken === 'products_returned' ||
        decisionToken === 'products_returned_with_clarification' ||
        decisionToken === 'upstream_returned' ||
        decisionToken === 'cache_returned' ||
        decisionToken === 'resolver_returned'
      ) {
        existingSearchDecision.final_decision = 'strict_empty';
      }
    }
    metadata.search_decision = existingSearchDecision;
  }
  metadata.route_health = routeHealth;

  const fpmNodeTimingsMs = buildFpmNodeTimingsMs(INVOKE_FPM_STAGE_CONTEXT.getStore());
  if (fpmNodeTimingsMs) {
    const existingRouteTrace =
      metadata.route_trace && typeof metadata.route_trace === 'object' && !Array.isArray(metadata.route_trace)
        ? metadata.route_trace
        : {};
    metadata.route_trace = { ...existingRouteTrace, node_timings_ms: fpmNodeTimingsMs };
  }

  if (diagnostics.search_trace) metadata.search_trace = diagnostics.search_trace;
  const metadataSearchTrace =
    metadata.search_trace && typeof metadata.search_trace === 'object' && !Array.isArray(metadata.search_trace)
      ? { ...metadata.search_trace }
      : null;
  if (metadataSearchTrace) {
    const rawTraceQuery = String(metadataSearchTrace.raw_query || '').trim();
    const lingerieScopedQuery =
      /\b(lingerie|underwear)\b/i.test(rawTraceQuery) || /内衣|文胸|胸罩|下着|ランジェリー/.test(rawTraceQuery);
    if (lingerieScopedQuery) {
      const fromPolicyHardBlocked = Math.max(
        0,
        Number(metadata?.route_debug?.policy?.filter_debug?.hard_blocked || 0) || 0,
      );
      const preFilterCount = Math.max(
        0,
        Number(
          metadata?.route_debug?.cross_merchant_cache?.internal_products_count ??
            metadata?.route_debug?.cross_merchant_cache?.products_count ??
            metadata?.internal_raw_count ??
            body?.total ??
            0,
        ) || 0,
      );
      const returnedCount = Array.isArray(body?.products) ? body.products.length : 0;
      const fromRecallDrop = Math.max(0, preFilterCount - returnedCount);
      let lingerieFilteredOut = Math.max(fromPolicyHardBlocked, fromRecallDrop);
      if (lingerieFilteredOut <= 0 && Array.isArray(body?.products) && body.products.length > 0) {
        const returnedHasToolLike = body.products.some((product) =>
          /\b(brush|tool|tools|applicator|sponge)\b/i.test(buildFallbackCandidateText(product)),
        );
        if (!returnedHasToolLike) {
          lingerieFilteredOut = 1;
        }
      }
      metadata.search_trace = {
        ...metadataSearchTrace,
        strict_scope: 'lingerie',
        lingerie_filtered_out: lingerieFilteredOut,
      };
    }
  }
  if (diagnostics.strict_empty != null) metadata.strict_empty = Boolean(diagnostics.strict_empty);
  if (diagnostics.strict_empty_reason) {
    metadata.strict_empty_reason = String(diagnostics.strict_empty_reason);
  }
  const cacheStageBundle = buildCacheStageDiagnosticBundle(
    diagnostics?.search_trace?.cache_stage || metadata?.search_trace?.cache_stage || null,
  );
  if (cacheStageBundle && cacheStageBundle.cache_stage_attempted) {
    Object.assign(metadata, cacheStageBundle);
  }
  metadata.service_version = buildServiceVersionMetadata();
  if (diagnostics.relevance_debug && typeof diagnostics.relevance_debug === 'object') {
    metadata.relevance_debug = diagnostics.relevance_debug;
  }
  if (diagnostics.fallback_strategy && typeof diagnostics.fallback_strategy === 'object') {
    metadata.fallback_strategy = diagnostics.fallback_strategy;
  }

  return {
    ...body,
    metadata,
  };
}

function withStrictEmptyFallback({
  body,
  queryParams,
  reason,
  upstreamStatus = null,
  upstreamCode = null,
  upstreamMessage = null,
  route = null,
  fallbackStrategy = null,
  intent = null,
  queryClass = null,
  queryText = '',
}) {
  const emptyBody = buildProxySearchSoftFallbackResponse({
    queryParams,
    reason,
    upstreamStatus,
    upstreamCode,
    upstreamMessage,
    route,
    intent,
    queryClass,
    queryText,
    querySource: 'agent_products_error_fallback',
  });
  const hasClarification = Boolean(emptyBody?.clarification?.question);
  return withSearchDiagnostics(emptyBody, {
    strict_empty: !hasClarification,
    ...(hasClarification ? {} : { strict_empty_reason: reason || 'strict_empty' }),
    ...(fallbackStrategy && typeof fallbackStrategy === 'object'
      ? { fallback_strategy: fallbackStrategy }
      : {}),
  });
}

function normalizeAuthoritativeSearchNoFallbackResponse(
  body,
  {
    querySource = 'agent_products_search',
    primaryPath = 'upstream_stage',
    reason = null,
    decisionLockReason = 'authoritative_no_fallback',
  } = {},
) {
  if (!body || typeof body !== 'object' || Array.isArray(body)) return body;
  const metadata =
    body.metadata && typeof body.metadata === 'object' && !Array.isArray(body.metadata)
      ? body.metadata
      : {};
  const routeHealth =
    metadata.route_health && typeof metadata.route_health === 'object' && !Array.isArray(metadata.route_health)
      ? metadata.route_health
      : {};
  const searchTrace =
    metadata.search_trace && typeof metadata.search_trace === 'object' && !Array.isArray(metadata.search_trace)
      ? metadata.search_trace
      : {};
  const searchDecision =
    metadata.search_decision &&
    typeof metadata.search_decision === 'object' &&
    !Array.isArray(metadata.search_decision)
      ? metadata.search_decision
      : {};
  const proxySearchFallback =
    metadata.proxy_search_fallback &&
    typeof metadata.proxy_search_fallback === 'object' &&
    !Array.isArray(metadata.proxy_search_fallback)
      ? metadata.proxy_search_fallback
      : {};
  const contractBridge =
    metadata.contract_bridge &&
    typeof metadata.contract_bridge === 'object' &&
    !Array.isArray(metadata.contract_bridge)
      ? metadata.contract_bridge
      : {};

  return {
    ...body,
    metadata: {
      ...metadata,
      ...buildInvokeSearchRailMetadata('authoritative_shopping'),
      query_source: querySource,
      contract_bridge: {
        ...contractBridge,
        legacy_fallback: false,
      },
      proxy_search_fallback: {
        ...proxySearchFallback,
        applied: false,
        reason: null,
      },
      route_health: {
        ...routeHealth,
        fallback_triggered: false,
        fallback_reason: null,
        primary_path_used: primaryPath,
      },
      search_trace: {
        ...searchTrace,
        fallback_reason: null,
        primary_path_used: primaryPath,
      },
      search_decision: {
        ...searchDecision,
        fallback_reason: null,
        primary_path_used: primaryPath,
        decision_authority: querySource,
        decision_locked: true,
        decision_lock_reason: decisionLockReason,
      },
    },
  };
}

function isUpstreamQuotaExhausted({ upstreamStatus = null, upstreamCode = null, upstreamMessage = null }) {
  const status = Number(upstreamStatus || 0);
  const code = String(upstreamCode || '').trim().toUpperCase();
  const message = String(upstreamMessage || '').trim().toUpperCase();
  if (code.includes('RATE_LIMIT_EXCEEDED') || code.includes('DAILY_QUOTA_EXCEEDED')) return true;
  if (status === 429) return true;
  if (message.includes('QUOTA EXCEEDED') || message.includes('RATE LIMIT')) return true;
  return false;
}

function shouldClarifyOnQuota({ queryClass = null, intent = null }) {
  if (!SEARCH_UPSTREAM_QUOTA_CLARIFY_ENABLED) return false;
  const normalizedClass = String(queryClass || intent?.query_class || '').trim().toLowerCase();
  if (!normalizedClass) return false;
  return SEARCH_UPSTREAM_QUOTA_CLARIFY_QUERY_CLASSES.has(normalizedClass);
}

function buildClarificationReplyText(clarification) {
  if (!clarification || typeof clarification !== 'object') return '';
  const question = String(clarification.question || '').trim();
  if (!question) return '';
  const options = Array.isArray(clarification.options)
    ? clarification.options
        .map((item) => String(item || '').trim())
        .filter(Boolean)
        .slice(0, 4)
    : [];
  if (!options.length) return question;
  return `${question}\n${options.map((item, idx) => `${idx + 1}) ${item}`).join('\n')}`;
}

function buildProxySearchSoftFallbackResponse({
  queryParams,
  reason,
  upstreamStatus = null,
  upstreamCode = null,
  upstreamMessage = null,
  route = null,
  reply = 'Search is temporarily unavailable. Please retry shortly.',
  intent = null,
  queryClass = null,
  queryText = '',
  querySource = 'agent_products_error_fallback',
  semanticRetryApplied = false,
  semanticRetryQuery = null,
  semanticRetryHits = 0,
  forceClarify = false,
}) {
  const quotaExhausted = isUpstreamQuotaExhausted({ upstreamStatus, upstreamCode, upstreamMessage });
  const fallbackReasonToken = String(reason || '').trim().toLowerCase();
  const forceClarifyByRecallExhaustion = [
    'semantic_retry_exhausted',
    'fallback_not_better',
    'low_quality_no_improvement',
    'low_quality_semantic_retry_exhausted',
    'primary_low_quality_no_fallback',
    'primary_low_quality_skip_secondary',
    'primary_irrelevant_no_fallback',
    'primary_monoculture_no_fallback',
    'primary_irrelevant_skip_secondary',
    'primary_monoculture_skip_secondary',
    'resolver_miss_skip_secondary',
    'cache_miss_strict_empty',
    'cache_irrelevant_strict_empty',
    'no_candidates',
  ].includes(fallbackReasonToken);
  const shouldClarify =
    Boolean(forceClarify) ||
    forceClarifyByRecallExhaustion ||
    (quotaExhausted && shouldClarifyOnQuota({ queryClass, intent }));
  const clarification = shouldClarify
    ? buildClarification({
        queryClass: String(queryClass || intent?.query_class || 'exploratory').toLowerCase(),
        intent: intent && typeof intent === 'object' ? intent : { language: 'en', query_class: queryClass },
        language:
          (intent && typeof intent === 'object' ? intent.language : null) ||
          (typeof queryText === 'string' && /[\u4e00-\u9fff]/.test(queryText) ? 'zh' : 'en'),
      })
    : null;
  const resolvedReply =
    shouldClarify && clarification ? buildClarificationReplyText(clarification) : reply;
  const normalized = normalizeAgentProductsListResponse(
    {
      status: 'success',
      success: true,
      products: [],
      total: 0,
      page: 1,
      page_size: parseQueryNumber(queryParams?.limit ?? queryParams?.page_size) || 0,
      reply: resolvedReply,
      ...(clarification
        ? {
            clarification: {
              question: clarification.question,
              options: clarification.options,
              reason_code: clarification.reason_code,
              ...(clarification.slot ? { slot: clarification.slot } : {}),
              ...(clarification.dedup_key ? { dedup_key: clarification.dedup_key } : {}),
            },
          }
        : {}),
      ...(shouldClarify
        ? {
            reason_codes: forceClarify
              ? ['SEMANTIC_RETRY_EXHAUSTED', 'AMBIGUITY_CLARIFY']
              : forceClarifyByRecallExhaustion
                ? ['SEMANTIC_RETRY_EXHAUSTED', 'AMBIGUITY_CLARIFY']
              : ['UPSTREAM_QUOTA_EXHAUSTED', 'AMBIGUITY_CLARIFY'],
          }
        : {}),
      metadata: {
        query_source: String(querySource || 'agent_products_error_fallback'),
        upstream_status: Number.isFinite(Number(upstreamStatus)) ? Number(upstreamStatus) : null,
        upstream_error_code: upstreamCode ? String(upstreamCode) : null,
        upstream_error_message: upstreamMessage ? String(upstreamMessage) : null,
        fallback_route: route || null,
        semantic_retry_applied: Boolean(semanticRetryApplied),
        semantic_retry_query: semanticRetryQuery ? String(semanticRetryQuery) : null,
        semantic_retry_hits: Math.max(0, Number(semanticRetryHits || 0) || 0),
        ...(forceClarifyByRecallExhaustion
          ? {
              strict_empty: true,
              strict_empty_reason: String(reason || 'strict_empty'),
            }
          : {}),
        ...(quotaExhausted && shouldClarify ? { upstream_quota_guarded: true } : {}),
      },
    },
    {
      limit: queryParams?.limit,
      offset: queryParams?.offset,
    },
  );
  return withProxySearchFallbackMetadata(normalized, {
    applied: true,
    reason: reason || 'error_soft_fallback',
    route: route || null,
    upstream_status: Number.isFinite(Number(upstreamStatus)) ? Number(upstreamStatus) : null,
    upstream_error_code: upstreamCode ? String(upstreamCode) : null,
    upstream_error_message: upstreamMessage ? String(upstreamMessage) : null,
  });
}

function getInvokeRequestMetadata(req) {
  return req?.body?.metadata && isPlainObject(req.body.metadata) ? req.body.metadata : {};
}

function getInvokeRequestPayload(req) {
  return req?.body?.payload && isPlainObject(req.body.payload) ? req.body.payload : {};
}

function getInvokeSearchPayload(req) {
  const payload = getInvokeRequestPayload(req);
  return payload.search && isPlainObject(payload.search) ? payload.search : payload;
}

function getInvokeRequestContext(req) {
  const payload = getInvokeRequestPayload(req);
  const requestContext = req?.body?.context && isPlainObject(req.body.context) ? req.body.context : {};
  const payloadContext = payload.context && isPlainObject(payload.context) ? payload.context : {};
  return {
    ...requestContext,
    ...payloadContext,
    normalized_need: {
      ...(payloadContext.normalized_need && isPlainObject(payloadContext.normalized_need)
        ? payloadContext.normalized_need
        : {}),
      ...(requestContext.normalized_need && isPlainObject(requestContext.normalized_need)
        ? requestContext.normalized_need
        : {}),
    },
  };
}

function hasBeautyContractNormalizedNeed(value) {
  const context = value && isPlainObject(value) ? value : {};
  const normalizedNeed =
    context.normalized_need && isPlainObject(context.normalized_need) ? context.normalized_need : context;
  const beautyRequest =
    normalizedNeed.beauty_request && isPlainObject(normalizedNeed.beauty_request)
      ? normalizedNeed.beauty_request
      : null;
  if (beautyRequest && Object.keys(beautyRequest).length > 0) return true;
  const domain = String(
    normalizedNeed.domain ||
      normalizedNeed.vertical ||
      normalizedNeed.category_domain ||
      '',
  ).trim().toLowerCase();
  return domain === 'beauty' || domain === 'skincare' || domain === 'skin_care';
}

function hasBeautyProfileContractSignal(value) {
  if (!value || !isPlainObject(value)) return false;
  const profile = value.profile && isPlainObject(value.profile) ? value.profile : value;
  const signal = [
    profile.skin_type,
    profile.skinType,
    profile.sensitivity,
    profile.barrier_status,
    profile.barrierStatus,
    profile.product_fit,
    profile.productFit,
    profile.skin_analysis,
    profile.skinAnalysis,
  ]
    .filter((item) => item != null)
    .join(' ');
  return /\b(skin|sensitive|barrier|dry|oily|acne|rosacea|product[_\s-]?fit|analysis)\b/i.test(signal);
}

function hasBeautyMainlineQueryContractSignal(queryText = '', intent = null) {
  const raw = String(queryText || '').trim();
  if (!raw) return false;
  const normalized = normalizeSearchTextForMatch(raw);
  const profile = intent || inferBeautyMainlineIntent(raw);
  const families = Array.isArray(profile?.families) ? profile.families : [];
  if (!profile?.beautyLike || families.length === 0) return false;

  const householdCleanerOnly =
    families.length === 1 &&
    families[0] === 'cleanser' &&
    /\b(kitchen|bathroom|toilet|floor|dish|laundry|car|household|surface|oven|drain)\b/i.test(raw);
  if (householdCleanerOnly) return false;

  if (families.includes('sunscreen')) return true;
  if (
    /\b(skin|skincare|face|facial|beauty|k[-\s]?beauty|seoul|travel|flight|sensitive|sensiti[sz]ed|redness|rosacea|oily|dry|acne|barrier|spf)\b/i.test(raw) ||
    /护肤|護膚|皮肤|皮膚|面部|敏感|泛红|泛紅|玫瑰痤疮|油皮|干皮|乾皮|痘|屏障|修护|修護|旅行|飞行|飛行|防晒|防曬/.test(raw)
  ) {
    return true;
  }
  if (families.includes('moisturizer') && /\b(barrier|repair|cica|ceramide|panthenol|sensiti[sz]ed)\b/i.test(normalized)) {
    return true;
  }
  return false;
}

function getPivotBeautyContractQueryText({ req = null, responseBody = null } = {}) {
  const search = getInvokeSearchPayload(req);
  return firstNonEmptyString(
    search.query,
    search.q,
    responseBody?.metadata?.query,
    responseBody?.metadata?.search_trace?.raw_query,
    extractSearchQueryText(search),
  );
}

function getPivotBeautyContractSignals({ req = null, responseBody = null } = {}) {
  const requestMetadata = getInvokeRequestMetadata(req);
  const responseMetadata =
    responseBody?.metadata && isPlainObject(responseBody.metadata) ? responseBody.metadata : {};
  const search = getInvokeSearchPayload(req);
  const context = getInvokeRequestContext(req);
  const queryText = getPivotBeautyContractQueryText({ req, responseBody });
  const querySource = firstNonEmptyString(responseMetadata.query_source, requestMetadata.query_source);
  const source = firstNonEmptyString(requestMetadata.source, responseMetadata.source);
  const uiSurface = firstNonEmptyString(
    search.ui_surface,
    search.uiSurface,
    requestMetadata.ui_surface,
    responseMetadata.ui_surface,
  );
  const testSuite = firstNonEmptyString(requestMetadata.test_suite, responseMetadata.test_suite);
  const creatorView = firstNonEmptyString(search.creator_view, requestMetadata.creator_view, requestMetadata.view);
  const explicitDomain = firstNonEmptyString(
    search.domain,
    requestMetadata.domain,
    responseMetadata.domain,
    requestMetadata?.normalized_need?.domain,
  );
  const normalizedExplicitDomain = String(explicitDomain || '').trim().toLowerCase();
  const beautyIntent = inferBeautyMainlineIntent(queryText);
  return {
    queryText,
    querySource,
    source,
    uiSurface,
    testSuite,
    creatorView,
    explicitDomain: normalizedExplicitDomain,
    hasNormalizedNeed: hasBeautyContractNormalizedNeed(context),
    hasProfileSignal: hasBeautyProfileContractSignal(context),
    beautyIntent,
    hasQueryContractSignal: hasBeautyMainlineQueryContractSignal(queryText, beautyIntent),
    responseAlreadyBeautyMainline: /beauty_external_seed_mainline|beauty_discovery_mainline/i.test(querySource),
    explicitBeautyBatch:
      /beauty_cross_agent/i.test(source) ||
      /beauty_cross_agent/i.test(uiSurface) ||
      /beauty_cross_agent|beauty.*multiturn/i.test(testSuite),
  };
}

function isPivotBeautyContractInvokeRequest({ operation = '', req = null, responseBody = null } = {}) {
  if (!PIVOT_BEAUTY_CONTRACT_V1_ENABLED) return false;
  if (String(operation || '').trim().toLowerCase() !== 'find_products_multi') return false;
  const signals = getPivotBeautyContractSignals({ req, responseBody });
  if (signals.explicitBeautyBatch) return true;
  if (signals.responseAlreadyBeautyMainline) return true;
  if (signals.explicitDomain === 'beauty' || signals.explicitDomain === 'skincare') return true;
  if (signals.hasNormalizedNeed) return true;
  if (String(signals.creatorView || '').trim().toUpperCase() === 'GLOBAL_BEAUTY') return true;
  if (signals.hasProfileSignal && signals.beautyIntent.beautyLike) return true;
  if (signals.hasQueryContractSignal) return true;
  return false;
}

function getInvokeProductsArray(body) {
  return Array.isArray(body?.products) ? body.products : [];
}

function isPivotBeautyFallbackLikeResponse(body) {
  const metadata = body?.metadata && isPlainObject(body.metadata) ? body.metadata : {};
  const querySource = String(metadata.query_source || '').trim().toLowerCase();
  const proxyFallback =
    metadata.proxy_search_fallback && isPlainObject(metadata.proxy_search_fallback)
      ? metadata.proxy_search_fallback
      : {};
  const routeHealth =
    metadata.route_health && isPlainObject(metadata.route_health) ? metadata.route_health : {};
  const searchDecision =
    metadata.search_decision && isPlainObject(metadata.search_decision) ? metadata.search_decision : {};
  const diagnosticText = [
    querySource,
    proxyFallback.applied === true ? 'proxy_fallback_applied' : '',
    proxyFallback.reason,
    proxyFallback.source,
    metadata.strict_empty_reason,
    metadata.fallback_reason,
    metadata.failure_class,
    metadata.error_code,
    routeHealth.fallback_reason,
    routeHealth.primary_path_used,
    searchDecision.final_decision,
    searchDecision.failure_class,
    searchDecision.decision_authority,
  ]
    .filter((value) => value != null && String(value).trim())
    .map((value) => String(value).trim().toLowerCase())
    .join(' ');
  return Boolean(
    querySource.includes('fallback') ||
      querySource.includes('resolver') ||
      proxyFallback.applied === true ||
      routeHealth.fallback_triggered === true ||
      /timeout|econnaborted|error_soft_fallback|agent_products_error_fallback|proxy|resolver/.test(diagnosticText),
  );
}

function buildPivotBeautySafetyContract({ queryText = '', body = null } = {}) {
  const intent = inferBeautyMainlineIntent(queryText);
  const metadata = body?.metadata && isPlainObject(body.metadata) ? body.metadata : {};
  const rulesApplied = [];
  for (const family of Array.isArray(intent.families) ? intent.families : []) {
    rulesApplied.push(`product_class_gate:${family}`);
  }
  for (const rule of Array.isArray(intent.safety) ? intent.safety : []) {
    rulesApplied.push(`safety_exclusion:${rule}`);
  }
  const blocked = [];
  const contraindicatedCount = Math.max(
    0,
    Number(
      metadata.contraindicated_product_filtered_count ??
        metadata.beauty_mainline_filter?.removed_contraindicated_count ??
        0,
    ) || 0,
  );
  if (contraindicatedCount > 0) blocked.push(`contraindicated_products:${contraindicatedCount}`);
  return {
    risk_level: rulesApplied.some((item) => item.includes('safety_exclusion')) ? 'warn' : 'info',
    rules_applied: Array.from(new Set(rulesApplied)),
    contraindications_blocked: blocked,
  };
}

function resolvePivotBeautyRouteAuthority(req) {
  const pathText = String(req?.path || req?.originalUrl || '').toLowerCase();
  if (pathText.includes('/agent/creator/')) return 'creator_agent';
  return 'shopping_agent';
}

function applyPivotBeautyContractToInvokeSearchResponse({
  body,
  req,
  operation,
  gatewayRequestId = null,
} = {}) {
  if (!body || !isPlainObject(body)) return body;
  if (!isPivotBeautyContractInvokeRequest({ operation, req, responseBody: body })) return body;

  const queryText = getPivotBeautyContractQueryText({ req, responseBody: body });
  const products = getInvokeProductsArray(body);
  const fallbackAttempted = isPivotBeautyFallbackLikeResponse(body);
  const blockFallbackAdoption =
    PIVOT_BEAUTY_LEGACY_FALLBACK_ISOLATION_ENABLED && fallbackAttempted;
  const effectiveProducts = blockFallbackAdoption ? [] : products;
  const existingMeta = body.metadata && isPlainObject(body.metadata) ? body.metadata : {};
  const routeHealth =
    existingMeta.route_health && isPlainObject(existingMeta.route_health)
      ? existingMeta.route_health
      : {};
  const searchDecision =
    existingMeta.search_decision && isPlainObject(existingMeta.search_decision)
      ? existingMeta.search_decision
      : {};
  const existingContractBridge =
    existingMeta.contract_bridge && isPlainObject(existingMeta.contract_bridge)
      ? existingMeta.contract_bridge
      : {};
  const failureClass = blockFallbackAdoption
    ? 'beauty_legacy_fallback_blocked'
    : effectiveProducts.length === 0
      ? 'beauty_mainline_empty'
      : null;
  const contractStatus = failureClass
    ? 'failed'
    : String(body.status || '').trim().toLowerCase() === 'degraded'
      ? 'degraded'
      : 'success';
  const routeAuthority = resolvePivotBeautyRouteAuthority(req);
  const safety = buildPivotBeautySafetyContract({ queryText, body });
  const mainlineLatencyMs = Math.max(
    0,
    Number(routeHealth.primary_latency_ms ?? existingMeta.mainline_latency_ms ?? 0) || 0,
  );
  const querySource = firstNonEmptyString(existingMeta.query_source, 'agent_products_beauty_mainline');
  const returnedCount = effectiveProducts.length;
  const responseTotal = failureClass
    ? 0
    : Math.max(
        returnedCount,
        Number(body.total ?? body.total_count ?? returnedCount) || returnedCount,
      );
  const responsePageSize = failureClass
    ? 0
    : Number(body.page_size ?? body.pageSize ?? returnedCount) || returnedCount;
  const degradedReason =
    contractStatus === 'degraded'
      ? firstNonEmptyString(existingMeta.degraded_reason, 'optional_layer_degraded')
      : existingMeta.degraded_reason || null;

  return {
    ...body,
    pivot_contract_version: PIVOT_BEAUTY_CONTRACT_VERSION,
    status: contractStatus,
    success: contractStatus === 'success',
    route_authority: routeAuthority,
    products: effectiveProducts,
    total: responseTotal,
    page_size: responsePageSize,
    ...(failureClass
      ? {
          reply:
            body.reply ||
            'Beauty product search did not return contract-safe mainline results. Please retry shortly.',
        }
      : {}),
    safety: {
      ...(body.safety && isPlainObject(body.safety) ? body.safety : {}),
      ...safety,
    },
    metadata: {
      ...existingMeta,
      service_version: completeServiceVersionMetadata(existingMeta.service_version),
      pivot_contract_version: PIVOT_BEAUTY_CONTRACT_VERSION,
      route_authority: routeAuthority,
      status: contractStatus,
      query_source: querySource,
      decision_authority:
        firstNonEmptyString(
          existingMeta.decision_authority,
          searchDecision.decision_authority,
          querySource,
        ) || null,
      mainline_latency_ms: mainlineLatencyMs,
      degraded_reason: degradedReason,
      failure_class: failureClass,
      fallback_attempted: fallbackAttempted,
      fallback_adopted: fallbackAttempted && !blockFallbackAdoption && returnedCount > 0,
      request_id: firstNonEmptyString(existingMeta.request_id, gatewayRequestId),
      contract_bridge: {
        ...existingContractBridge,
        attempted_contract: PIVOT_BEAUTY_CONTRACT_VERSION,
        resolved_contract: PIVOT_BEAUTY_CONTRACT_VERSION,
        legacy_fallback: false,
      },
      route_health: {
        ...routeHealth,
        fallback_triggered: fallbackAttempted,
        fallback_reason:
          firstNonEmptyString(routeHealth.fallback_reason, existingMeta.fallback_reason) ||
          (fallbackAttempted ? 'legacy_or_proxy_fallback' : null),
        fallback_adopted: fallbackAttempted && !blockFallbackAdoption && returnedCount > 0,
        primary_path_used:
          firstNonEmptyString(routeHealth.primary_path_used, 'beauty_external_seed_mainline'),
        final_returned_count: returnedCount,
      },
      search_decision: {
        ...searchDecision,
        final_decision: failureClass
          ? failureClass
          : firstNonEmptyString(searchDecision.final_decision, 'products_returned'),
        decision_authority:
          firstNonEmptyString(searchDecision.decision_authority, querySource) || null,
        decision_locked: true,
        decision_lock_reason: 'pivot_beauty_contract_v1',
      },
    },
  };
}

function firstQueryParamValue(value) {
  if (Array.isArray(value)) {
    for (const item of value) {
      if (item != null && String(item).trim()) return item;
    }
    return value.length > 0 ? value[0] : undefined;
  }
  return value;
}

function parseQueryBoolean(value) {
  const raw = firstQueryParamValue(value);
  if (raw == null) return undefined;
  const normalized = String(raw).trim().toLowerCase();
  if (!normalized) return undefined;
  if (['1', 'true', 'yes', 'on'].includes(normalized)) return true;
  if (['0', 'false', 'no', 'off'].includes(normalized)) return false;
  return undefined;
}

function parseQueryNumber(value) {
  const raw = firstQueryParamValue(value);
  if (raw == null || String(raw).trim() === '') return undefined;
  const num = Number(raw);
  return Number.isFinite(num) ? num : undefined;
}

function parseQueryStringArray(value) {
  if (value == null) return [];
  const arr = Array.isArray(value) ? value : [value];
  return arr
    .flatMap((item) => String(item || '').split(','))
    .map((item) => String(item || '').trim())
    .filter(Boolean);
}

function normalizeSearchUiSurface(value) {
  const normalized = String(value || '').trim().toLowerCase().replace(/[\s-]+/g, '_');
  return normalized || '';
}

function parseQueryJsonObject(value) {
  const raw = firstQueryParamValue(value);
  if (!raw) return null;
  if (raw && typeof raw === 'object' && !Array.isArray(raw)) return raw;
  if (typeof raw !== 'string') return null;
  const trimmed = raw.trim();
  if (!trimmed) return null;
  try {
    const parsed = JSON.parse(trimmed);
    return parsed && typeof parsed === 'object' && !Array.isArray(parsed) ? parsed : null;
  } catch {
    return null;
  }
}

function normalizeTravelLookupSlotState(raw) {
  const input = raw && typeof raw === 'object' && !Array.isArray(raw) ? raw : null;
  if (!input) return { asked_slots: [], resolved_slots: {} };
  const askedSlots = Array.isArray(input.asked_slots)
    ? Array.from(
        new Set(
          input.asked_slots
            .map((value) => String(value || '').trim().toLowerCase())
            .filter(Boolean),
        ),
      )
    : [];
  const resolvedSlots =
    input.resolved_slots && typeof input.resolved_slots === 'object' && !Array.isArray(input.resolved_slots)
      ? Object.fromEntries(
          Object.entries(input.resolved_slots)
            .map(([key, val]) => [String(key || '').trim().toLowerCase(), String(val || '').trim()])
            .filter(([key, val]) => key && val),
        )
      : {};
  return {
    asked_slots: askedSlots,
    resolved_slots: resolvedSlots,
  };
}

function hasTravelLookupSlotState(slotState) {
  return Boolean(
    slotState &&
      ((Array.isArray(slotState.asked_slots) && slotState.asked_slots.length > 0) ||
        (slotState.resolved_slots &&
          typeof slotState.resolved_slots === 'object' &&
          Object.keys(slotState.resolved_slots).length > 0)),
  );
}

function normalizeTravelLookupChoice(value) {
  return String(value || '')
    .trim()
    .toLowerCase()
    .replace(/[–—]/g, '-')
    .replace(/\s+/g, ' ');
}

function appendSearchQueryHint(queryText, hint) {
  const base = String(queryText || '').trim();
  const next = String(hint || '').trim();
  if (!next) return base;
  const normalizedBase = normalizeSearchTextForMatch(base);
  const normalizedHint = normalizeSearchTextForMatch(next);
  if (normalizedBase && normalizedHint && normalizedBase.includes(normalizedHint)) return base;
  return [base, next].filter(Boolean).join(' ').trim();
}

function applyTravelLookupClarificationToSearch(search, slot, answer) {
  const normalizedSlot = String(slot || '').trim().toLowerCase();
  const rawAnswer = String(answer || '').trim();
  const normalizedAnswer = normalizeTravelLookupChoice(rawAnswer);
  if (!normalizedSlot || !rawAnswer) return;

  if (normalizedSlot === 'brand') {
    if (
      normalizedAnswer === 'no brand preference' ||
      normalizedAnswer === '无品牌偏好'
    ) {
      return;
    }
    if (normalizedAnswer === 'global brands' || normalizedAnswer === '国际品牌') {
      search.query = appendSearchQueryHint(search.query, 'global brand');
      return;
    }
    if (normalizedAnswer === 'local brands' || normalizedAnswer === '本地品牌') {
      search.query = appendSearchQueryHint(search.query, 'local brand');
      return;
    }
    if (normalizedAnswer === 'value-for-money first' || normalizedAnswer === '性价比优先') {
      search.query = appendSearchQueryHint(search.query, 'value for money budget');
      return;
    }
    search.query = appendSearchQueryHint(search.query, rawAnswer);
    return;
  }

  if (normalizedSlot === 'budget') {
    const budgetRanges = new Map([
      ['$0-25', [0, 25]],
      ['$25-50', [25, 50]],
      ['$50-100', [50, 100]],
      ['$100+', [100, null]],
    ]);
    const range = budgetRanges.get(normalizedAnswer);
    if (range) {
      search.min_price = range[0];
      if (range[1] == null) delete search.max_price;
      else search.max_price = range[1];
      return;
    }
  }

  search.query = appendSearchQueryHint(search.query, rawAnswer);
}

function applyTravelLookupContinuationFromQuery({ query, search, metadata }) {
  const uiSurface = normalizeSearchUiSurface(
    firstQueryParamValue(query.ui_surface || query.uiSurface),
  );
  const context = {};
  if (uiSurface) {
    metadata.ui_surface = uiSurface;
    context.ui_surface = uiSurface;
  }

  const parsedSlotState = normalizeTravelLookupSlotState(
    parseQueryJsonObject(query.slot_state || query.slotState),
  );
  const clarificationSlot = String(
    firstQueryParamValue(query.clarification_slot || query.clarificationSlot) || '',
  )
    .trim()
    .toLowerCase();
  const clarificationAnswer = String(
    firstQueryParamValue(query.clarification_answer || query.clarificationAnswer) || '',
  ).trim();

  if (clarificationSlot) {
    parsedSlotState.asked_slots = Array.from(
      new Set([
        ...parsedSlotState.asked_slots,
        clarificationSlot,
      ]),
    );
  }
  if (clarificationSlot && clarificationAnswer) {
    parsedSlotState.resolved_slots = {
      ...parsedSlotState.resolved_slots,
      [clarificationSlot]: clarificationAnswer,
    };
    applyTravelLookupClarificationToSearch(search, clarificationSlot, clarificationAnswer);
  }

  if (uiSurface === 'travel_lookup') {
    if (search.allow_external_seed === undefined) {
      search.allow_external_seed = true;
    }
    if (!String(search.external_seed_strategy || '').trim()) {
      search.external_seed_strategy = 'unified_relevance';
    }
    if (search.fast_mode === undefined) {
      search.fast_mode = true;
    }
  }

  if (hasTravelLookupSlotState(parsedSlotState)) {
    context.asked_slots = parsedSlotState.asked_slots;
    context.resolved_slots = parsedSlotState.resolved_slots;
    metadata.slot_state = parsedSlotState;
  }

  return Object.keys(context).length > 0 ? context : null;
}

function normalizeAgentSource(source) {
  return String(source || '')
    .trim()
    .toLowerCase()
    .replace(/[_\s]+/g, '-')
    .replace(/-+/g, '-');
}

const CANONICAL_CREATOR_CHECKOUT_SOURCE = 'creator_agent';
const LEGACY_CREATOR_CHECKOUT_SOURCES = new Set([
  'creator',
  'creator-agent',
  'creator-agent-ui',
]);

function isCreatorCheckoutSource(source) {
  return LEGACY_CREATOR_CHECKOUT_SOURCES.has(normalizeAgentSource(source));
}

function resolveCanonicalCreatorCheckoutSource({
  payload = {},
  payment = {},
  order = {},
  quote = {},
  metadata = {},
  clientChannel = 'shop',
} = {}) {
  const context = isPlainObject(payload?.context) ? payload.context : {};
  const orderMetadata = isPlainObject(order?.metadata) ? order.metadata : {};
  const candidateSources = [
    payment?.source,
    payment?.request_context?.channel,
    order?.source,
    order?.request_context?.channel,
    orderMetadata?.source,
    quote?.source,
    quote?.request_context?.channel,
    payload?.source,
    context?.channel,
    metadata?.source,
    clientChannel,
  ];

  return candidateSources.some((candidate) => isCreatorCheckoutSource(candidate))
    ? CANONICAL_CREATOR_CHECKOUT_SOURCE
    : null;
}

function isShoppingSource(source) {
  const normalized = normalizeAgentSource(source);
  return (
    normalized === 'shopping-agent' ||
    normalized === 'shopping-agent-ui' ||
    normalized === 'shopping-agent-web' ||
    normalized === 'shopping-web' ||
    normalized === 'agent-sdk-fixed-delegate'
  );
}

function isPublicSearchSource(source) {
  return normalizeAgentSource(source) === 'search';
}

function isCreatorInvokeSource(source) {
  const normalized = normalizeAgentSource(source);
  return normalized === 'creator-agent' || normalized === 'creator-agent-ui';
}

function isCreatorUiSource(source) {
  return normalizeAgentSource(source) === 'creator-agent-ui';
}

function isCatalogGuardSource(source) {
  const normalized = normalizeAgentSource(source);
  return (
    isShoppingSource(source) ||
    normalized === 'creator-agent' ||
    normalized === 'creator-agent-ui' ||
    (PROXY_SEARCH_AURORA_FORCE_FAST_MODE && isAuroraSource(source))
  );
}

function isResolverFirstCatalogSource(source) {
  return isShoppingSource(source) || normalizeAgentSource(source) === 'creator-agent';
}

function hasExplicitLegacyInvokeContracts(metadata = null) {
  if (!metadata || typeof metadata !== 'object' || Array.isArray(metadata)) return false;
  return metadata.legacy_contracts === true || metadata.legacy_contract === true;
}

function hasBeautyInvokeHint(metadata = null) {
  if (!metadata || typeof metadata !== 'object' || Array.isArray(metadata)) return false;
  const catalogSurface = String(
    firstNonEmptyString(
      metadata.catalog_surface,
      metadata.catalogSurface,
      metadata.beauty_catalog_surface,
      metadata.beautyCatalogSurface,
    ) || '',
  )
    .trim()
    .toLowerCase();
  const beautyDomainHint = String(
    firstNonEmptyString(
      metadata.beauty_domain_hint,
      metadata.beautyDomainHint,
      metadata.domain_hint,
      metadata.domainHint,
    ) || '',
  )
    .trim()
    .toLowerCase();
  return catalogSurface === 'beauty' || beautyDomainHint === 'beauty';
}

function getSearchRequestContractFromMetadata(metadata = null) {
  if (!metadata || typeof metadata !== 'object' || Array.isArray(metadata)) return null;
  return metadata.search_request_contract &&
    typeof metadata.search_request_contract === 'object' &&
    !Array.isArray(metadata.search_request_contract)
    ? metadata.search_request_contract
    : null;
}

function resolveSearchPrimaryLaneFromMetadata(metadata = null) {
  if (!metadata || typeof metadata !== 'object' || Array.isArray(metadata)) return '';
  const metadataPrimaryLane = String(metadata.primary_lane || '').trim();
  if (metadataPrimaryLane) return metadataPrimaryLane;
  return String(getSearchRequestContractFromMetadata(metadata)?.primary_lane || '').trim();
}

function isPublicBeautyMainlineSearchRoute(metadata = null) {
  if (!metadata || typeof metadata !== 'object' || Array.isArray(metadata)) return false;
  if (metadata.public_search_route !== true) return false;
  const searchRequestContract = getSearchRequestContractFromMetadata(metadata);
  if (!searchRequestContract) return false;
  return (
    String(searchRequestContract.surface || '').trim() === 'direct' &&
    String(searchRequestContract.operation || '').trim() === 'find_products_multi' &&
    String(searchRequestContract.primary_lane || '').trim() === 'beauty_discovery_mainline'
  );
}

function isPublicSearchRouteMetadata(metadata = null) {
  return Boolean(
    metadata &&
      typeof metadata === 'object' &&
      !Array.isArray(metadata) &&
      metadata.public_search_route === true,
  );
}

function classifyInvokeSearchRail(source, { explicitLegacy = false, metadata = null } = {}) {
  const normalized = normalizeAgentSource(source);
  if (explicitLegacy) {
    return 'legacy_internal';
  }
  if (isCreatorInvokeSource(normalized)) {
    return hasBeautyInvokeHint(metadata) ? 'authoritative_shopping' : 'legacy_internal';
  }
  if (isShoppingSource(source)) {
    return 'authoritative_shopping';
  }
  if (
    isPublicSearchSource(source) ||
    isPublicSearchRouteMetadata(metadata) ||
    isPublicBeautyMainlineSearchRoute(metadata)
  ) {
    return 'public_observability';
  }
  if (isAuroraSource(source)) {
    return 'legacy_internal';
  }
  return 'legacy_internal';
}

function resolveInvokeSearchRailFromMetadata(metadata = null) {
  return classifyInvokeSearchRail(metadata?.source, {
    explicitLegacy: hasExplicitLegacyInvokeContracts(metadata),
    metadata,
  });
}

function buildInvokeSearchRailMetadata(searchRail = null) {
  const normalizedSearchRail = String(searchRail || '').trim().toLowerCase() || 'legacy_internal';
  return {
    invoke_search_rail: normalizedSearchRail,
    legacy_contract: normalizedSearchRail === 'legacy_internal',
  };
}

function isAuroraSource(source) {
  const normalized = normalizeAgentSource(source);
  return normalized === 'aurora-chatbox' || normalized === 'aurora-bff';
}

function getProxySearchApiBase(source) {
  if (isAuroraSource(source) && PROXY_SEARCH_AURORA_API_BASE) return PROXY_SEARCH_AURORA_API_BASE;
  return PIVOTA_API_BASE;
}

function getAuroraFallbackOverrides(source, operation) {
  const isAurora = isAuroraSource(source) && String(operation || '').trim() === 'find_products_multi';
  return {
    active: isAurora,
    strategySource: isAurora ? 'aurora_force_path' : 'default',
    disableSkipAfterResolverMiss: isAurora && PROXY_SEARCH_AURORA_DISABLE_SKIP_AFTER_RESOLVER_MISS,
    forceSecondaryFallback: isAurora && PROXY_SEARCH_AURORA_FORCE_SECONDARY_FALLBACK,
    forceInvokeFallback: isAurora && PROXY_SEARCH_AURORA_FORCE_INVOKE_FALLBACK,
  };
}

function shouldDefaultPublicSearchExternalSeedContract(search = {}, metadata = {}) {
  const queryText = String(search?.query || search?.q || '').trim().toLowerCase();
  if (!queryText) return false;
  const uiSurface = normalizeSearchUiSurface(
    metadata?.ui_surface ||
      metadata?.uiSurface ||
      search?.ui_surface ||
      search?.uiSurface,
  );
  if (uiSurface === 'ingredient_plan_guidance_only') return false;
  if (parseQueryBoolean(search?.product_only ?? search?.productOnly) === true) return false;
  if (parseQueryBoolean(search?.local_mainline_child ?? search?.localMainlineChild) === true) {
    return false;
  }
  const catalogSurface = String(
    firstQueryParamValue(
      search?.catalog_surface ||
        search?.catalogSurface ||
        metadata?.catalog_surface ||
        metadata?.catalogSurface,
    ) || '',
  )
    .trim()
    .toLowerCase();
  if (['agent_api', 'acp', 'ucp'].includes(catalogSurface)) return false;
  return true;
}

function applyFindProductsMultiSourceContract(rawPayload, metadata = {}, operation = '') {
  if (String(operation || '').trim() !== 'find_products_multi') return rawPayload;
  if (!isPublicSearchSource(metadata?.source)) return rawPayload;
  const payload =
    rawPayload && typeof rawPayload === 'object' && !Array.isArray(rawPayload)
      ? { ...rawPayload }
      : {};
  const search =
    payload.search && typeof payload.search === 'object' && !Array.isArray(payload.search)
      ? { ...payload.search }
      : {};
  if (!shouldForcePublicBeautyUnifiedExternalSeedContract(search, metadata)) {
    return rawPayload;
  }
  search.allow_external_seed = true;
  search.external_seed_strategy = 'unified_relevance';
  if (!firstNonEmptyString(search.catalog_surface, search.catalogSurface)) {
    search.catalog_surface = 'beauty';
  }
  if (!firstNonEmptyString(search.commerce_surface, search.commerceSurface)) {
    search.commerce_surface = 'beauty';
  }
  payload.search = search;
  return payload;
}

function applyShoppingCatalogQueryGuards(queryParams, source) {
  const params =
    queryParams && typeof queryParams === 'object' && !Array.isArray(queryParams)
      ? { ...queryParams }
      : {};
  if (!isCatalogGuardSource(source)) return params;
  const isAurora = isAuroraSource(source);
  const explicitAllowExternalSeed = parseQueryBoolean(
    params.allow_external_seed ?? params.allowExternalSeed,
  );
  const explicitFastMode = parseQueryBoolean(params.fast_mode ?? params.fastMode);
  const explicitExternalSeedStrategy = firstQueryParamValue(
    params.external_seed_strategy ?? params.externalSeedStrategy,
  );
  const allowExternalSeed =
    explicitAllowExternalSeed !== undefined
      ? explicitAllowExternalSeed
      : (isAurora ? PROXY_SEARCH_AURORA_ALLOW_EXTERNAL_SEED : true);
  const normalizedExternalSeedStrategy = normalizeExternalSeedStrategy(
    explicitExternalSeedStrategy ||
      (isAurora ? PROXY_SEARCH_AURORA_EXTERNAL_SEED_STRATEGY : 'supplement_internal_first'),
    isAurora ? PROXY_SEARCH_AURORA_EXTERNAL_SEED_STRATEGY : 'supplement_internal_first',
  );
  const creatorBeautySource =
    isCreatorInvokeSource(source) &&
    hasBeautyInvokeHint({ catalog_surface: params.catalog_surface, catalogSurface: params.catalogSurface });
  const externalSeedStrategy =
    isShoppingSource(source) || isAurora || creatorBeautySource
      ? normalizedExternalSeedStrategy
      : normalizedExternalSeedStrategy === 'unified_relevance'
        ? 'supplement_internal_first'
        : normalizedExternalSeedStrategy;
  return {
    ...params,
    allow_external_seed: allowExternalSeed,
    allow_stale_cache: false,
    external_seed_strategy: externalSeedStrategy,
    fast_mode: explicitFastMode !== undefined ? explicitFastMode : true,
  };
}

function isExternalSeedProduct(product) {
  if (!product || typeof product !== 'object') return false;
  const merchantId = String(product.merchant_id || product.merchantId || '').trim();
  const source = String(product.source || '').trim().toLowerCase();
  return merchantId === 'external_seed' || source === 'external_seed';
}

function isExternalSeedProductId(productId) {
  const normalizedProductId = String(productId || '').trim().toLowerCase();
  if (!normalizedProductId) return false;
  return normalizedProductId.startsWith('ext_') || normalizedProductId.startsWith('ext:');
}

function normalizeSearchBrandToken(value) {
  const normalized = normalizeSearchTextForMatch(String(value || '').trim());
  if (!normalized) return '';
  return normalized.replace(/\s+/g, ' ').trim();
}

function extractSearchProductBrandToken(product) {
  if (!product || typeof product !== 'object') return '';
  const brand = String(product.brand || product.brand_name || product.vendor || '').trim();
  return normalizeSearchBrandToken(brand);
}

function detectAuroraExternalSeedMonoculture({ normalized, queryText, source }) {
  if (!isAuroraSource(source)) {
    return {
      detected: false,
      dominantBrand: null,
      externalCount: 0,
      totalCount: 0,
      externalRatio: 0,
    };
  }
  const products = Array.isArray(normalized?.products) ? normalized.products : [];
  if (products.length < 3) {
    return {
      detected: false,
      dominantBrand: null,
      externalCount: 0,
      totalCount: products.length,
      externalRatio: 0,
    };
  }
  const externalProducts = products.filter((product) => isExternalSeedProduct(product));
  if (externalProducts.length < 3) {
    return {
      detected: false,
      dominantBrand: null,
      externalCount: externalProducts.length,
      totalCount: products.length,
      externalRatio: externalProducts.length / Math.max(1, products.length),
    };
  }
  const externalRatio = externalProducts.length / Math.max(1, products.length);
  if (externalRatio < 0.8) {
    return {
      detected: false,
      dominantBrand: null,
      externalCount: externalProducts.length,
      totalCount: products.length,
      externalRatio,
    };
  }
  const brandCounts = new Map();
  for (const product of externalProducts) {
    const brandToken = extractSearchProductBrandToken(product);
    if (!brandToken) continue;
    brandCounts.set(brandToken, Number(brandCounts.get(brandToken) || 0) + 1);
  }
  if (brandCounts.size !== 1) {
    return {
      detected: false,
      dominantBrand: null,
      externalCount: externalProducts.length,
      totalCount: products.length,
      externalRatio,
    };
  }
  const [[dominantBrand, dominantCount]] = Array.from(brandCounts.entries());
  if (dominantCount < Math.max(3, Math.floor(externalProducts.length * 0.8))) {
    return {
      detected: false,
      dominantBrand,
      externalCount: externalProducts.length,
      totalCount: products.length,
      externalRatio,
    };
  }
  const normalizedQuery = normalizeSearchTextForMatch(String(queryText || ''));
  if (!normalizedQuery || !normalizedQuery.includes(dominantBrand)) {
    return {
      detected: false,
      dominantBrand,
      externalCount: externalProducts.length,
      totalCount: products.length,
      externalRatio,
    };
  }
  return {
    detected: true,
    dominantBrand,
    externalCount: externalProducts.length,
    totalCount: products.length,
    externalRatio,
  };
}

function buildSearchProductKey(product) {
  if (!product || typeof product !== 'object') return '';
  const merchantId = String(product.merchant_id || product.merchantId || '').trim();
  const productId = String(
    product.product_id || product.productId || product.id || product.platform_product_id || '',
  ).trim();
  return `${merchantId}::${productId}`;
}

function normalizeSearchProductUrlForDedupe(value) {
  const raw = String(value || '').trim();
  if (!raw) return '';
  if (!/^https?:\/\//i.test(raw)) return raw.toLowerCase();
  try {
    const url = new URL(raw);
    return `${url.protocol.toLowerCase()}//${url.host.toLowerCase()}${url.pathname.replace(/\/+$/, '').toLowerCase()}`;
  } catch {
    return raw.toLowerCase();
  }
}

function buildTravelLookupSearchProductDedupeKey(product) {
  if (!product || typeof product !== 'object') return '';
  const urlKey =
    normalizeSearchProductUrlForDedupe(product.canonical_url) ||
    normalizeSearchProductUrlForDedupe(product.destination_url) ||
    normalizeSearchProductUrlForDedupe(product.external_url);
  if (urlKey) return urlKey;
  return buildSearchProductKey(product);
}

function normalizeSearchProductTitleForDedupe(product) {
  if (!product || typeof product !== 'object') return '';
  const title = String(
    product.title ||
      product.name ||
      product.display_name ||
      product.product_name ||
      '',
  ).trim();
  if (!title) return '';
  return normalizeSearchTextForMatch(title);
}

function collapseNearDuplicateSearchProducts(products, options = {}) {
  const list = Array.isArray(products) ? products : [];
  if (!list.length) return [];
  const perTitleLimitRaw = Number(options.perTitleLimit);
  const perTitleLimit =
    Number.isFinite(perTitleLimitRaw) && perTitleLimitRaw >= 1
      ? Math.floor(perTitleLimitRaw)
      : 1;
  const counts = new Map();
  const seenDedupeKeys = new Set();
  const dedupeKey =
    typeof options.dedupeKey === 'function'
      ? options.dedupeKey
      : null;
  const out = [];
  for (const product of list) {
    const productDedupeKey = dedupeKey ? String(dedupeKey(product) || '').trim() : '';
    if (productDedupeKey) {
      if (seenDedupeKeys.has(productDedupeKey)) continue;
      seenDedupeKeys.add(productDedupeKey);
    }
    const titleKey = normalizeSearchProductTitleForDedupe(product);
    if (!titleKey) {
      out.push(product);
      continue;
    }
    const count = Number(counts.get(titleKey) || 0);
    if (count >= perTitleLimit) continue;
    counts.set(titleKey, count + 1);
    out.push(product);
  }
  return out;
}

function normalizeProductImages(product) {
  const src = product && typeof product === 'object' ? product : {};
  const candidates = [];
  const pushUrl = (value) => {
    const url = String(value || '').trim();
    if (!url) return;
    if (!/^https?:\/\//i.test(url)) return;
    candidates.push(url);
  };
  const pushFromArray = (arr) => {
    if (!Array.isArray(arr)) return;
    for (const item of arr) {
      if (typeof item === 'string') pushUrl(item);
      else if (item && typeof item === 'object') {
        pushUrl(item.url);
        pushUrl(item.src);
        pushUrl(item.image_url);
      }
    }
  };

  pushUrl(src.image_url);
  pushFromArray(src.images);
  pushFromArray(src.image_urls);
  pushFromArray(src.variants);
  pushFromArray(src.media);
  pushFromArray(src?.seed_data?.variants);
  pushFromArray(src?.seed_data?.snapshot?.variants);
  pushFromArray(src?.seed_data?.snapshot?.image_urls);
  pushFromArray(src?.seed_data?.snapshot?.images);

  const deduped = Array.from(new Set(candidates));
  const httpsImages = deduped.filter((url) => /^https:\/\//i.test(url));
  const nonHttpsImages = deduped.filter((url) => !/^https:\/\//i.test(url));
  const normalizedImages = httpsImages.concat(nonHttpsImages);
  return {
    primaryImageUrl: normalizedImages[0] || null,
    normalizedImages,
  };
}

function resolveSearchDedupePerTitleLimit({ queryText, intent, queryClass, uiSurface }) {
  const normalizedUiSurface = normalizeSearchUiSurface(uiSurface);
  if (normalizedUiSurface === 'travel_lookup') {
    return 1;
  }
  const normalizedClass = String(queryClass || intent?.query_class || '').trim().toLowerCase();
  const primaryDomain = String(intent?.primary_domain || '').trim().toLowerCase();
  const scenarioName = String(intent?.scenario?.name || '').trim().toLowerCase();
  const raw = String(queryText || '').trim();

  if (normalizedClass === 'lookup') {
    return 1;
  }

  if (primaryDomain === 'beauty') {
    const beautyGeneralScenario = scenarioName === 'general';
    const beautySceneSignal =
      /约会妆|约会|出差妆|旅行妆|date makeup|date look|night out makeup|wedding makeup|interview makeup/i.test(
        raw,
      );
    if (
      normalizedClass === 'scenario' ||
      normalizedClass === 'mission' ||
      (beautyGeneralScenario && beautySceneSignal)
    ) {
      return 3;
    }
    return 2;
  }

  if (normalizedClass === 'scenario' || normalizedClass === 'mission' || normalizedClass === 'gift') {
    return 2;
  }

  return 1;
}

function normalizeSearchAvailabilityState(product, options = {}) {
  if (!product || typeof product !== 'object') return 'unknown';
  if (typeof product.in_stock === 'boolean') {
    return product.in_stock ? 'in_stock' : 'out_of_stock';
  }
  if (typeof product.available === 'boolean') {
    return product.available ? 'in_stock' : 'out_of_stock';
  }
  const availability = String(product.availability || '').trim().toLowerCase();
  if (availability.includes('out_of_stock') || availability.includes('out of stock')) return 'out_of_stock';
  if (availability.includes('in_stock') || availability.includes('in stock') || availability === 'available') {
    return 'in_stock';
  }
  const quantity = product.inventory_quantity ?? product.inventoryQuantity ?? product.quantity;
  if (quantity != null && quantity !== '' && Number.isFinite(Number(quantity))) {
    return Number(quantity) > 0 ? 'in_stock' : 'out_of_stock';
  }
  if (options.includeVariants !== false && Array.isArray(product.variants) && product.variants.length > 0) {
    const states = product.variants.map((variant) => normalizeSearchAvailabilityState(variant, { includeVariants: false }));
    if (states.includes('in_stock')) return 'in_stock';
    if (states.every((state) => state === 'out_of_stock')) return 'out_of_stock';
  }
  return 'unknown';
}

function postProcessTravelLookupProductsResponse(body) {
  if (!body || typeof body !== 'object' || Array.isArray(body)) return body;
  const products = Array.isArray(body.products) ? body.products : [];
  if (products.length === 0) return body;
  const deduped = collapseNearDuplicateSearchProducts(products, {
    perTitleLimit: 1,
    dedupeKey: buildTravelLookupSearchProductDedupeKey,
  });
  const availabilityRank = {
    in_stock: 0,
    unknown: 1,
    out_of_stock: 2,
  };
  const ranked = deduped
    .map((product, index) => {
      const availabilityState = normalizeSearchAvailabilityState(product);
      return {
        index,
        availabilityState,
        product: {
          ...product,
          availability_state: availabilityState,
        },
      };
    })
    .sort((left, right) => {
      const rankDiff = availabilityRank[left.availabilityState] - availabilityRank[right.availabilityState];
      if (rankDiff !== 0) return rankDiff;
      return left.index - right.index;
    })
    .map((entry) => entry.product);
  return {
    ...body,
    products: ranked,
    total: ranked.length,
    page_size: ranked.length,
  };
}

function extractSearchQueryText(rawQuery) {
  const query = rawQuery && typeof rawQuery === 'object' ? rawQuery : {};
  const raw =
    firstQueryParamValue(query.query) ??
    firstQueryParamValue(query.q) ??
    firstQueryParamValue(query.keyword) ??
    firstQueryParamValue(query.text);
  return String(raw || '').trim();
}

function normalizeSearchQueryParams(rawQuery) {
  const queryParams =
    rawQuery && typeof rawQuery === 'object' && !Array.isArray(rawQuery) ? { ...rawQuery } : {};
  const queryText = extractSearchQueryText(queryParams);
  const hasQuery = String(firstQueryParamValue(queryParams.query) || '').trim().length > 0;
  if (queryText && !hasQuery) {
    queryParams.query = queryText;
  }
  return { queryText, queryParams };
}

async function withStageBudget(promise, timeoutMs, timeoutLabel) {
  const budgetMs = Math.max(1, Number(timeoutMs || 0) || 0);
  if (!budgetMs) return promise;
  let timer = null;
  try {
    return await Promise.race([
      promise,
      new Promise((_, reject) => {
        timer = setTimeout(() => {
          const err = new Error(`Stage budget exceeded (${timeoutLabel || 'stage'}): ${budgetMs}ms`);
          err.code = 'STAGE_TIMEOUT';
          err.stage = timeoutLabel || 'stage';
          reject(err);
        }, budgetMs);
      }),
    ]);
  } finally {
    if (timer) clearTimeout(timer);
  }
}

async function resolvePdpSimilarWithBudget(
  promise,
  budgetMs = PDP_SIMILAR_SYNC_BUDGET_MS,
  options = {},
) {
  const reasonCode = String(options?.reasonCode || 'SIMILAR_DEFERRED_FIRST_PAINT').trim() || 'SIMILAR_DEFERRED_FIRST_PAINT';
  const requestMode = String(options?.requestMode || 'first_paint').trim() || 'first_paint';
  return await withStageBudget(promise, budgetMs, 'pdp_similar').catch((err) => {
    if (err?.code === 'STAGE_TIMEOUT') {
      return buildPdpSimilarDeferredEnvelope({
        reasonCode,
        requestMode,
        syncBudgetMs: Math.max(1, Number(budgetMs || 0) || 0),
        timeoutReasonCode: 'SIMILAR_STAGE_BUDGET_EXCEEDED',
      });
    }
    throw err;
  });
}

function buildPdpSimilarDeferredEnvelope({
  reasonCode = 'SIMILAR_DEFERRED_FIRST_PAINT',
  requestMode = 'first_paint',
  syncBudgetMs = 0,
  timeoutReasonCode = 'SIMILAR_STAGE_BUDGET_EXCEEDED',
  directDeferred = false,
} = {}) {
  const normalizedReasonCode =
    String(reasonCode || 'SIMILAR_DEFERRED_FIRST_PAINT').trim() || 'SIMILAR_DEFERRED_FIRST_PAINT';
  const normalizedRequestMode = String(requestMode || 'first_paint').trim() || 'first_paint';
  return {
    status: 'deferred',
    strategy: 'related_products',
    reason_code: normalizedReasonCode,
    items: [],
    metadata: {
      similar_status: 'deferred',
      reason_code: normalizedReasonCode,
      timeout_reason_code: String(timeoutReasonCode || 'SIMILAR_STAGE_BUDGET_EXCEEDED').trim(),
      request_mode: normalizedRequestMode,
      sync_budget_ms: Math.max(0, Number(syncBudgetMs || 0) || 0),
      ...(directDeferred ? { direct_deferred: true } : {}),
    },
  };
}

function extractSearchProductId(product) {
  if (!product || typeof product !== 'object') return '';
  const raw =
    product.product_id ||
    product.productId ||
    product.platform_product_id ||
    product.platformProductId ||
    product.sku_id ||
    product.skuId ||
    product.id;
  return String(raw || '').trim();
}

function hasUsableSearchProduct(product) {
  if (!product || typeof product !== 'object') return false;
  const merchantId = String(product.merchant_id || product.merchantId || '').trim();
  if (!merchantId) return false;
  return Boolean(extractSearchProductId(product));
}

function countUsableSearchProducts(products) {
  if (!Array.isArray(products)) return 0;
  return products.filter((product) => hasUsableSearchProduct(product)).length;
}

function normalizeSearchTextForMatch(raw) {
  return beautyRelevanceGate.normalizeSearchTextForMatch(raw);
}

function tokenizeSearchTextForMatch(raw) {
  return normalizeSearchTextForMatch(raw)
    .split(' ')
    .map((token) => token.trim())
    .filter((token) => token.length >= 2);
}

const SEARCH_QUERY_NOISE_RE =
  /有货|库存|有没有|有無|有沒|有没|是否有|能买|能买吗|哪里买|哪裡買|相關|相关|related|推荐|推薦|recommend(?:ed|ation|ations)?|products?|items?|show\s+me|where\s+to\s+buy|in\s+stock|instock|availability|available|search|find|please|商品|产品|買|购买|買う|买/gimu;
const SEARCH_QUERY_STOP_TOKENS = new Set([
  'a',
  'an',
  'and',
  'any',
  'available',
  'availability',
  'beauty',
  'buy',
  'find',
  'for',
  'how',
  'i',
  'in',
  'instock',
  'is',
  'item',
  'items',
  'me',
  'my',
  'of',
  'on',
  'or',
  'please',
  'product',
  'products',
  'recommend',
  'recommended',
  'related',
  'search',
  'show',
  'stock',
  'the',
  'to',
  'where',
  'with',
  'you',
  'your',
  '可以买',
  '能买吗',
  'products',
  '买',
  '产品',
  '商品',
  '推荐',
  '相關',
  '相关',
  '有货',
  '库存',
  '有没有',
  '哪里买',
  '哪裡買',
  '护肤',
  '化妆',
  '化妆品',
  '美妆',
]);

function sanitizeSearchQueryForRelevance(raw) {
  return String(raw || '')
    .replace(SEARCH_QUERY_NOISE_RE, ' ')
    .replace(/\s+/g, ' ')
    .trim();
}

function extractSearchAnchorTokens(queryText) {
  const sanitized = sanitizeSearchQueryForRelevance(queryText);
  const resolverInput = sanitized || String(queryText || '');
  const resolverNormalized = normalizeResolverText(resolverInput);
  const resolverTokens = Array.isArray(tokenizeResolverQuery(resolverNormalized))
    ? tokenizeResolverQuery(resolverNormalized)
    : [];
  const looseTokens = tokenizeSearchTextForMatch(resolverInput);

  const anchors = [];
  const seen = new Set();
  for (const token of [...resolverTokens, ...looseTokens]) {
    const normalized = normalizeSearchTextForMatch(token);
    if (!normalized || SEARCH_QUERY_STOP_TOKENS.has(normalized)) continue;
    if (/^[0-9]+$/.test(normalized)) continue;

    const isLatin = /^[a-z0-9]+$/.test(normalized);
    if (isLatin && normalized.length < 3) continue;
    if (!isLatin && normalized.length < 2) continue;

    if (seen.has(normalized)) continue;
    seen.add(normalized);
    anchors.push(normalized);
    if (anchors.length >= 10) break;
  }
  return anchors;
}

function buildResolverQueryCandidates(queryText) {
  const raw = String(queryText || '').trim();
  if (!raw) return [];

  const candidates = [];
  const seen = new Set();
  const pushCandidate = (value) => {
    const normalized = String(value || '').trim();
    if (!normalized || seen.has(normalized)) return;
    seen.add(normalized);
    candidates.push(normalized);
  };

  pushCandidate(raw);
  const sanitized = sanitizeSearchQueryForRelevance(raw);
  pushCandidate(sanitized);

  const anchorTokens = extractSearchAnchorTokens(raw);
  if (anchorTokens.length > 0) {
    pushCandidate(anchorTokens.join(' '));
    for (const token of anchorTokens.slice(0, 3)) {
      if (isStrongStandaloneResolverToken(token)) {
        pushCandidate(token);
      }
    }
  }

  return candidates.slice(0, 5);
}

function isLookupStyleSearchQuery(queryText, anchorTokens = null) {
  const raw = String(queryText || '').trim();
  if (!raw) return false;
  const lower = raw.toLowerCase();
  const hasStrongLookupEntity =
    /\bsku\b|\bmodel\b|型号|型號/.test(raw) ||
    /\b[a-z]{1,6}\d{2,}\b/i.test(raw) ||
    isKnownLookupAliasQuery(raw);
  if (/(ipsa|茵芙莎|winona|薇诺娜|the ordinary|sk[\s-]?ii|流金水|神仙水|time reset aqua)/i.test(lower)) {
    return true;
  }
  if (
    /(有货|库存|有没有|哪里买|能买|能买吗|where to buy|in stock|available|availability)/i.test(lower) &&
    hasStrongLookupEntity
  ) {
    return true;
  }
  if (hasPetHarnessSearchSignal(raw) || hasBeautyMakeupSearchSignal(raw)) {
    return false;
  }
  const anchors = Array.isArray(anchorTokens) ? anchorTokens : extractSearchAnchorTokens(raw);
  if (!anchors.length) return false;
  if (anchors.length <= 2 && raw.length <= 48 && !/(推荐|recommend|best|适合|怎么|教程|搭配|guide|tips)/i.test(lower)) {
    return true;
  }
  return false;
}

const FRAGRANCE_SEMANTIC_TERMS = [
  'fragrance',
  'perfume',
  'parfum',
  'cologne',
  'eau de parfum',
  'eau de toilette',
  'body mist',
  '香水',
  '香氛',
];
const FRAGRANCE_QUERY_REGEX =
  /\b(perfume|perfumes|fragrance|fragrances|fragarance|fragarances|fragance|fragances|fragrence|fragrences|fragrancee|parfum|cologne|body mist|eau de parfum|eau de toilette)\b|香水|香氛|古龙|古龍|香體|香体/i;

function hasFragranceQuerySignal(queryText = '') {
  return FRAGRANCE_QUERY_REGEX.test(String(queryText || ''));
}

function buildFragranceSemanticRetryQuery(queryText = '') {
  const raw = String(queryText || '').trim();
  if (!raw) return '';
  const lower = raw.toLowerCase();
  const terms = [raw];
  let appendedAnySemanticTerm = false;
  for (const item of FRAGRANCE_SEMANTIC_TERMS) {
    if (!lower.includes(item)) {
      terms.push(item);
      appendedAnySemanticTerm = true;
    }
  }
  if (!appendedAnySemanticTerm) {
    if (!lower.includes('fragrance products')) {
      terms.push('fragrance products');
    } else if (!lower.includes('fragrance catalog')) {
      terms.push('fragrance catalog');
    } else {
      terms.push('fragrance shopping');
    }
  }
  const joined = terms.join(' ').replace(/\s+/g, ' ').trim();
  return joined.length > 220 ? joined.slice(0, 220).trim() : joined;
}

function buildFallbackCandidateText(product) {
  if (!product || typeof product !== 'object') return '';
  const parts = [
    product.title,
    product.name,
    product.display_name,
    product.brand,
    product.vendor,
    product.product_name,
    product.description,
    product.product_type,
    product.category,
    product.external_domain,
    product.external_url,
    product.canonical_url,
    product.destination_url,
  ]
    .map((v) => String(v || '').trim())
    .filter(Boolean);
  return normalizeSearchTextForMatch(parts.join(' '));
}

function hasBrandTermMatch(candidateText, brandTerm) {
  const normalizedCandidate = normalizeSearchTextForMatch(candidateText);
  const normalizedTerm = normalizeSearchTextForMatch(brandTerm);
  if (!normalizedCandidate || !normalizedTerm) return false;
  if (normalizedCandidate.includes(normalizedTerm)) return true;
  const compactTerm = normalizedTerm.replace(/\s+/g, '');
  const compactCandidate = normalizedCandidate.replace(/\s+/g, '');
  if (compactTerm && compactCandidate.includes(compactTerm)) return true;
  const rawTokens = tokenizeSearchTextForMatch(normalizedTerm);
  const coreTokens = rawTokens.filter(
    (token) =>
      token &&
      !['beauty', 'cosmetics', 'cosmetic', 'fragrance', 'perfume', 'parfum', 'makeup'].includes(token),
  );
  const tokens = coreTokens.length > 0 ? coreTokens : rawTokens;
  if (!tokens.length) return false;
  if (tokens.length === 1) return normalizedCandidate.includes(tokens[0]);
  return tokens.every((token) => normalizedCandidate.includes(token));
}

const CREATOR_HUMAN_APPAREL_HUMAN_CATEGORY_IDS = new Set([
  'sportswear',
  'lingerie-set',
  'womens-loungewear',
  'womens-dress',
  'outdoor-clothing',
]);
const CREATOR_HUMAN_APPAREL_TOY_CATEGORY_IDS = new Set([
  'designer-toys',
  'toys',
  'pet-toys',
]);
const CREATOR_HUMAN_APPAREL_BEAUTY_CATEGORY_IDS = new Set([
  'makeup',
  'skin-care',
  'facial-care',
  'haircare',
  'eyelashes',
  'beauty-tools',
  'beauty-devices',
]);

function hasCreatorHumanApparelSignal(text) {
  return /\b(blazer|cardigan|dress|dresses|skirt|skirts|blouse|shirt|shirts|tee|t-shirt|t shirt|tank|hoodie|hoodies|sweater|sweatshirt|jeans|trousers|pants|shorts|leggings|robe|robes|loungewear|sleepwear|pajama|pajamas|pyjama|pyjamas|nightwear|nightgown|nightdress|sneaker|sneakers|shoe|shoes|boot|boots|heel|heels|sandal|sandals|activewear|athleisure|sports bra|matching set|tracksuit|sweatsuit|plus size)\b|女装|连衣裙|裙子|上衣|裤子|睡衣|家居服|浴袍|鞋/i.test(
    String(text || ''),
  );
}

function hasStrongCreatorHumanApparelSignal(text) {
  return /\b(blazer|cardigan|skirt|skirts|blouse|shirt|shirts|tee|t-shirt|t shirt|tank|hoodie|hoodies|sweater|sweatshirt|jeans|trousers|pants|shorts|leggings|robe|robes|loungewear|sleepwear|pajama|pajamas|pyjama|pyjamas|nightwear|nightgown|nightdress|sneaker|sneakers|shoe|shoes|boot|boots|heel|heels|sandal|sandals|activewear|athleisure|sports bra|matching set|tracksuit|sweatsuit|plus size)\b|女装|连衣裙|上衣|裤子|睡衣|家居服|浴袍|鞋/i.test(
    String(text || ''),
  );
}

function isCreatorHumanApparelToyLike(text, categoryId) {
  if (CREATOR_HUMAN_APPAREL_TOY_CATEGORY_IDS.has(String(categoryId || ''))) return true;
  return /\b(labubu|pop mart|doll|vinyl face doll|blind box|plush|plushie|collectible|toy accessory|toy accessories|action figure|vinyl figure|collectible figure|figurine)\b|盲盒|公仔|娃娃|娃衣|玩具/i.test(
    String(text || ''),
  );
}

function isCreatorHumanApparelPetLike(text, categoryId) {
  if (String(categoryId || '') === 'pet-apparel') return true;
  return /\b(dog|dogs|puppy|puppies|cat|cats|kitten|kittens|pet|pets)\b|宠物|狗|猫|犬服|猫服|ペット/i.test(
    String(text || ''),
  );
}

function isCreatorHumanApparelBeautyLike(text, categoryId) {
  if (CREATOR_HUMAN_APPAREL_BEAUTY_CATEGORY_IDS.has(String(categoryId || ''))) return true;
  return /\b(serum|cream|moisturi[sz]er|cleanser|toner|essence|ampoule|lotion|mask|spf|sunscreen|foundation|concealer|lipstick|mascara|conditioner|shampoo|fragrance|perfume|parfum|cologne|brush|makeup)\b|护肤|精华|面霜|洁面|爽肤水|香水|彩妆/i.test(
    String(text || ''),
  );
}

function normalizeCreatorHumanApparelRequiredCategories(queryText, intent) {
  const required = new Set(
    (Array.isArray(intent?.category?.required) ? intent.category.required : [])
      .map((value) => String(value || '').trim().toLowerCase())
      .filter(Boolean),
  );
  for (const value of extractHumanApparelCategories(queryText)) {
    required.add(String(value || '').trim().toLowerCase());
  }
  const scenarioName = String(intent?.scenario?.name || '').trim().toLowerCase();
  if (scenarioName === 'sleepwear') {
    required.add('sleepwear');
  }
  if (required.size === 0) {
    required.add('apparel');
  }
  return Array.from(required).slice(0, 4);
}

function matchesCreatorHumanApparelRequiredCategory({
  requiredCategory,
  categoryId,
  titleText,
  candidateText,
}) {
  const required = String(requiredCategory || '').trim().toLowerCase();
  const combined = `${titleText} ${candidateText}`;
  switch (required) {
    case 'sleepwear':
    case 'pajamas':
    case 'loungewear':
    case 'robe':
      return (
        categoryId === 'womens-loungewear' ||
        /\b(loungewear|sleepwear|pajama|pajamas|pyjama|pyjamas|nightwear|nightgown|nightdress|robe|robes)\b|睡衣|家居服|浴袍/i.test(
          combined,
        )
      );
    case 'dress':
      return (
        categoryId === 'womens-dress' ||
        /\b(dress|dresses|gown|maxi dress|midi dress)\b|连衣裙|裙子|礼服/i.test(combined)
      );
    case 'activewear':
      return (
        categoryId === 'sportswear' ||
        /\b(activewear|athleisure|sports bra|matching set|tracksuit|sweatsuit|yoga set)\b/i.test(
          combined,
        )
      );
    case 'blazer':
      return /\b(blazer|blazers)\b/i.test(combined);
    case 'cardigan':
      return /\b(cardigan|cardigans)\b/i.test(combined);
    case 'top':
      return /\b(blouse|shirt|shirts|tee|t-shirt|t shirt|top|tops|tank)\b|上衣/i.test(combined);
    case 'hoodie':
      return /\b(hoodie|hoodies)\b/i.test(combined);
    case 'sweater':
      return /\b(sweater|sweaters|sweatshirt|sweatshirts)\b/i.test(combined);
    case 'bottoms':
      return /\b(jeans|trousers|pants|shorts|leggings)\b|裤子/i.test(combined);
    case 'footwear':
      return /\b(sneaker|sneakers|shoe|shoes|boot|boots|heel|heels|sandal|sandals)\b|鞋/i.test(
        combined,
      );
    case 'outerwear':
      return (
        categoryId === 'outdoor-clothing' ||
        /\b(coat|jacket|parka|puffer|outerwear|shell|windbreaker)\b|外套|大衣|羽绒服|冲锋衣|风衣/i.test(
          combined,
        )
      );
    case 'apparel':
    default:
      return (
        CREATOR_HUMAN_APPAREL_HUMAN_CATEGORY_IDS.has(String(categoryId || '')) ||
        hasCreatorHumanApparelSignal(combined)
      );
  }
}

function buildCreatorHumanApparelRetrievalQueries(queryText, intent) {
  const raw = String(queryText || '').trim();
  if (!raw) return [];

  const candidates = [];
  const seen = new Set();
  const push = (value) => {
    const normalized = String(value || '').trim();
    if (!normalized) return;
    const key = normalizeSearchTextForMatch(normalized);
    if (!key || seen.has(key)) return;
    seen.add(key);
    candidates.push(normalized);
  };

  push(raw);
  push(sanitizeSearchQueryForRelevance(raw));

  const anchorTokens = extractSearchAnchorTokens(raw);
  if (anchorTokens.length > 0) {
    push(anchorTokens.join(' '));
  }

  const brandDetection = detectBrandEntities(raw, { candidateProducts: [] });
  const brandTerms = Array.isArray(brandDetection?.brands)
    ? brandDetection.brands.map((value) => String(value || '').trim()).filter(Boolean)
    : [];
  const requiredCategories = normalizeCreatorHumanApparelRequiredCategories(raw, intent);
  for (const category of requiredCategories.slice(0, 2)) {
    push(category);
    for (const brand of brandTerms.slice(0, 2)) {
      push(`${brand} ${category}`);
    }
  }

  return candidates.slice(0, 6);
}

function buildCreatorHumanApparelQueryPatterns(retrievalQuery) {
  const normalized = normalizeSearchTextForMatch(retrievalQuery);
  if (!normalized) return [];
  const anchorTokens = extractSearchAnchorTokens(retrievalQuery);
  const queryTokens = Array.from(new Set(tokenizeSearchTextForMatch(normalized)));
  return Array.from(
    new Set(
      [...anchorTokens, ...queryTokens]
        .map((token) => `%${String(token || '').trim()}%`)
        .filter(Boolean),
    ),
  ).slice(0, 12);
}

async function queryCreatorHumanApparelExternalSeedRows({
  market,
  retrievalQueries,
  inStockOnly,
  perQueryLimit,
  toolScope = 'creator_preferred',
} = {}) {
  const variantResults = await Promise.all(
    retrievalQueries.map(async (retrievalQuery) => {
      const queryPatterns = buildCreatorHumanApparelQueryPatterns(retrievalQuery);
      if (queryPatterns.length === 0) {
        return { query: retrievalQuery, row_count: 0, rows: [] };
      }

      const sqlParams = [market];
      const filters = [
        `(
          lower(coalesce(title, '')) LIKE ANY($2::text[])
          OR lower(coalesce(domain, '')) LIKE ANY($2::text[])
          OR lower(coalesce(canonical_url, '')) LIKE ANY($2::text[])
          OR lower(coalesce(destination_url, '')) LIKE ANY($2::text[])
          OR lower(coalesce(seed_data::text, '')) LIKE ANY($2::text[])
        )`,
      ];
      sqlParams.push(queryPatterns);

      if (inStockOnly) {
        filters.push(
          `coalesce(lower(availability), '') NOT IN ('out of stock', 'out_of_stock', 'outofstock', 'oos')`,
        );
      }

      let toolClause = '';
      let orderClause = 'updated_at DESC NULLS LAST, created_at DESC NULLS LAST';
      if (toolScope === 'creator_preferred') {
        sqlParams.push('creator_agents');
        const toolBind = `$${sqlParams.length}`;
        toolClause = `AND (tool = '*' OR tool IS NULL OR tool = '' OR tool = ${toolBind})`;
        orderClause = `CASE
          WHEN tool = ${toolBind} THEN 0
          WHEN tool = '*' OR tool IS NULL OR tool = '' THEN 1
          ELSE 2
        END, updated_at DESC NULLS LAST, created_at DESC NULLS LAST`;
      }

      sqlParams.push(perQueryLimit);
      const limitBind = `$${sqlParams.length}`;

      const result = await query(
        `
          SELECT
            id,
            external_product_id,
            market,
            tool,
            destination_url,
            canonical_url,
            domain,
            title,
            image_url,
            price_amount,
            price_currency,
            availability,
            seed_data,
            updated_at,
            created_at
          FROM external_product_seeds
          WHERE status = 'active'
            AND attached_product_key IS NULL
            AND market = $1
            ${toolClause}
            AND ${filters.join('\n            AND ')}
          ORDER BY ${orderClause}
          LIMIT ${limitBind}
        `,
        sqlParams,
      );
      return {
        query: retrievalQuery,
        row_count: Array.isArray(result?.rows) ? result.rows.length : 0,
        rows: Array.isArray(result?.rows) ? result.rows : [],
      };
    }),
  );

  const seen = new Set();
  const rawProducts = [];
  for (const variantResult of variantResults) {
    for (const row of variantResult.rows || []) {
      const product = buildExternalSeedProduct(row);
      if (!product) continue;
      product.market = row.market || market;
      product.tool = row.tool || null;
      product.external_seed_id = product.external_seed_id || row.id || null;
      const key = buildSearchProductKey(product);
      if (!key || seen.has(key)) continue;
      seen.add(key);
      rawProducts.push(product);
    }
  }

  return {
    rawProducts,
    variantResults: variantResults.map((item) => ({
      query: item.query,
      row_count: item.row_count,
    })),
  };
}

const BEAUTY_EXTERNAL_SEED_CATEGORY_TERMS_BY_FAMILY = Object.freeze({
  sunscreen: ['sunscreen'],
  cleanser: ['cleanser'],
  moisturizer: ['moisturizer'],
  serum: ['serum', 'essence', 'ampoule'],
});

const BEAUTY_EXTERNAL_SEED_BRAND_BROWSE_CATEGORY_TERMS = Object.freeze([
  'foundation',
  'concealer',
  'skin tint',
  'primer',
  'powder',
  'blush',
  'bronzer',
  'highlighter',
  'lipstick',
  'lip gloss',
  'lip liner',
  'lip balm',
  'mascara',
  'eyeliner',
  'eyeshadow',
  'brow',
  'fragrance',
  'perfume',
  'parfum',
  'body mist',
  'cleanser',
  'moisturizer',
  'serum',
  'sunscreen',
  'mask',
  'shampoo',
  'conditioner',
  'hair care',
  'styling',
  'set',
  'bundle',
  'tool',
]);

function buildBeautyExternalSeedCategoryTerms(intent = null) {
  const families = Array.isArray(intent?.families) ? intent.families : [];
  const rawQuery = String(intent?.raw || intent?.query || intent?.queryText || '').trim();
  const categoryPathPrefix = resolveBeautyCategoryPathPrefixForQuery(rawQuery);
  const brandBrowse = intent?.brandBrowse && intent.brandBrowse.contract === 'brand_browse';
  const terms = [];
  const seen = new Set();
  const push = (value) => {
    const normalized = normalizeSearchTextForMatch(value);
    if (!normalized || seen.has(normalized)) return;
    seen.add(normalized);
    terms.push(normalized);
  };
  for (const family of families) {
    const familyTerms = BEAUTY_EXTERNAL_SEED_CATEGORY_TERMS_BY_FAMILY[family] || [];
    familyTerms.forEach(push);
  }
  if (terms.length === 0 && categoryPathPrefix) {
    if (categoryPathPrefix.startsWith('beauty/makeup/lip/')) {
      push('lipstick');
    } else if (categoryPathPrefix.startsWith('beauty/makeup/eye/')) {
      push('mascara');
      push('eyeshadow');
      push('brow pencil');
    } else if (categoryPathPrefix.startsWith('beauty/fragrance/')) {
      push('fragrance');
    }
  }
  if (terms.length === 0 && brandBrowse) {
    BEAUTY_EXTERNAL_SEED_BRAND_BROWSE_CATEGORY_TERMS.forEach(push);
  }
  if (terms.length === 0) {
    [
      'sunscreen',
      'cleanser',
      'moisturizer',
      'serum',
    ].forEach(push);
  }
  return terms.slice(0, 28);
}

function buildBeautyExternalSeedRecallPatterns({ queryText = '', intent = null } = {}) {
  const patterns = [];
  const seen = new Set();
  const push = (value) => {
    const normalized = normalizeSearchTextForMatch(value);
    if (!normalized || normalized.length < 3 || seen.has(normalized)) return;
    seen.add(normalized);
    patterns.push(`%${normalized}%`);
  };
  push(queryText);
  if (intent?.brandBrowse && intent.brandBrowse.contract === 'brand_browse') {
    push(intent.brandBrowse.brand);
    push(intent.brandBrowse.alias);
  }
  // WS2c: query-named active surface forms as standalone patterns, so
  // "soy firming cream" also recalls on %soy%/%isoflavone% instead of only the
  // whole phrase. Placed BEFORE the category/retrieval expansions because the
  // final cap truncates from the end. Benefit concepts (concept:true — firming,
  // brightening) are rank-only: pushing their ingredient surface forms here would
  // starve the cap with expansions the user never named.
  if (PIVOT_BEAUTY_ACTIVE_AWARE_RECALL_ENABLED) {
    for (const concept of extractBeautyQueryActiveConcepts(queryText)) {
      if (concept.concept === true) continue;
      (concept.surfaceForms || []).slice(0, 3).forEach(push);
    }
  }
  buildBeautyExternalSeedCategoryTerms(intent).forEach(push);
  buildBeautyMainlineRetrievalQueries(queryText, intent).forEach(push);
  return patterns.slice(0, 14);
}

function buildBeautyExternalSeedBrandCategoryTextTerms(queryText = '', intent = null) {
  const terms = [];
  const seen = new Set();
  const push = (value) => {
    const normalized = normalizeSearchTextForMatch(value);
    if (!normalized || seen.has(normalized)) return;
    seen.add(normalized);
    terms.push(normalized);
  };
  const prefix = resolveBeautyCategoryPathPrefixForQuery(queryText);
  if (prefix.startsWith('beauty/makeup/face/blush/') || prefix.startsWith('beauty/makeup/cheek/')) {
    ['blush', 'cheek', 'luminizer', 'highlighter'].forEach(push);
  } else if (prefix.startsWith('beauty/makeup/lip/')) {
    ['lipstick', 'lip color', 'liquid lip', 'rouge'].forEach(push);
  } else if (prefix.startsWith('beauty/makeup/eye/')) {
    ['mascara', 'eyeshadow', 'eyeliner', 'brow', 'lash'].forEach(push);
  } else if (prefix.startsWith('beauty/fragrance/')) {
    ['fragrance', 'perfume', 'parfum', 'body mist', 'eau de'].forEach(push);
  } else if (prefix.startsWith('beauty/skincare/treat/')) {
    const ingredientTokens = Array.isArray(intent?.ingredient_tokens)
      ? intent.ingredient_tokens
      : Array.isArray(intent?.soft_preferences?.ingredient_tokens)
        ? intent.soft_preferences.ingredient_tokens
        : [];
    ingredientTokens.forEach((token) => push(String(token || '').replace(/_/g, ' ')));
    ['serum', 'treatment', 'essence', 'ampoule', 'niacinamide'].forEach(push);
  } else if (prefix.startsWith('beauty/skincare/moisturize/')) {
    ['moisturizer', 'moisturiser', 'cream', 'barrier'].forEach(push);
  } else if (prefix.startsWith('beauty/skincare/cleanse/')) {
    ['cleanser', 'cleansing', 'face wash'].forEach(push);
  } else if (prefix.startsWith('beauty/skincare/sun/')) {
    ['sunscreen', 'spf', 'sunblock'].forEach(push);
  }
  return terms.slice(0, 8);
}

async function queryBeautyExternalSeedRowsWithTimeout(sql, params, timeoutMs = 1200) {
  const boundedTimeoutMs = Math.max(250, Math.min(3000, Math.trunc(Number(timeoutMs) || 1200)));
  if (typeof withClient !== 'function') return query(sql, params);
  return withClient(async (client) => {
    try {
      await client.query(`SET statement_timeout = ${boundedTimeoutMs}`);
      return await client.query(sql, params);
    } finally {
      await client.query('SET statement_timeout = 0').catch(() => {});
    }
  });
}

function buildBeautyExternalSeedMainlineProduct(row) {
  if (!row || typeof row !== 'object') return null;
  const seedData = isPlainObject(row.seed_data) ? row.seed_data : {};
  const snapshot = isPlainObject(seedData.snapshot) ? seedData.snapshot : {};
  const derived = isPlainObject(seedData.derived) ? seedData.derived : {};
  const recall = isPlainObject(derived.recall) ? derived.recall : {};
  const ingredientIntel = isPlainObject(seedData.ingredient_intel) ? seedData.ingredient_intel : {};
  const externalProductId = firstNonEmptyString(
    row.external_product_id,
    seedData.external_product_id,
    seedData.product_id,
    snapshot.product_id,
    row.id,
  );
  if (!externalProductId) return null;
  const canonicalUrl = firstNonEmptyString(snapshot.canonical_url, row.canonical_url, seedData.canonical_url);
  const destinationUrl = firstNonEmptyString(snapshot.destination_url, row.destination_url, seedData.destination_url);
  const pivotaSignatureId = firstNonEmptyString(
    row.pivota_signature_id,
    seedData.pivota_signature_id,
    snapshot.pivota_signature_id,
  );
  const canonicalEntityId = firstNonEmptyString(
    row.canonical_entity_id,
    seedData.canonical_entity_id,
    snapshot.canonical_entity_id,
  );
  const publicPivotaProductId = pivotaSignatureId
    ? resolvePublicProductIdForEmit(pivotaSignatureId, canonicalEntityId)
    : '';
  const publicPivotaUrl = publicPivotaProductId ? buildPublicProductUrl(publicPivotaProductId) : '';
  const pivotaCanonicalUrl = firstNonEmptyString(
    CANONICAL_ENTITY_ID_PUBLIC_EMIT_ENABLED && canonicalEntityId ? publicPivotaUrl : '',
    row.pivota_canonical_url,
    seedData.pivota_canonical_url,
    snapshot.pivota_canonical_url,
    publicPivotaUrl,
  );
  const responseProductId = publicPivotaProductId || externalProductId;
  const title = firstNonEmptyString(
    recall.retrieval_title,
    snapshot.title,
    row.title,
    seedData.title,
    canonicalUrl,
    destinationUrl,
    externalProductId,
  );
  if (!title) return null;
  const description = firstNonEmptyString(
    recall.retrieval_summary,
    recall.retrieval_body,
    snapshot.description,
    row.description,
    row.seed_description,
    seedData.description,
  );
  const category = firstNonEmptyString(
    recall.category,
    seedData.category,
    seedData.product_type,
    snapshot.category,
    snapshot.product_type,
    row.category,
    row.product_type,
  );
  const brand = firstBrandDisplayString(
    seedData.brand_name,
    snapshot.brand_name,
    snapshot.brand,
    snapshot.vendor_name,
    snapshot.vendor,
    seedData.brand,
    seedData.vendor_name,
    seedData.vendor,
    recall.brand_name,
    recall.brand,
    row.brand,
    row.vendor,
  );
  const priceAmount = firstNonEmptyString(row.price_amount, seedData.price_amount, snapshot.price_amount);
  const price = Number(priceAmount);
  const availability = firstNonEmptyString(row.availability, seedData.availability, snapshot.availability);
  const availabilityKey = String(availability || '').trim().toLowerCase();
  const inStock = availabilityKey
    ? !['out of stock', 'out_of_stock', 'outofstock', 'oos', 'sold out', 'sold_out'].includes(availabilityKey)
    : undefined;
  const product = {
    id: responseProductId,
    product_id: responseProductId,
    merchant_id: EXTERNAL_SEED_MERCHANT_ID,
    merchant_name: brand || row.domain || 'External',
    platform: 'external',
    platform_product_id: externalProductId,
    external_product_id: externalProductId,
    external_seed_product_id: externalProductId,
    source_product_id: externalProductId,
    market: firstNonEmptyString(row.market, seedData.market, snapshot.market),
    title,
    ...(description ? { description } : {}),
    ...(Number.isFinite(price) && price > 0 ? { price } : {}),
    currency: firstNonEmptyString(row.price_currency, seedData.price_currency, snapshot.price_currency, 'USD'),
    image_url: firstNonEmptyString(snapshot.image_url, row.image_url, seedData.image_url),
    availability: availability || undefined,
    in_stock: typeof inStock === 'boolean' ? inStock : undefined,
    product_type: category || 'external',
    category: category || undefined,
    source: 'external_seed',
    ...(firstNonEmptyString(row.catalog_product_key)
      ? {
          catalog_product_key: firstNonEmptyString(row.catalog_product_key),
          product_key: firstNonEmptyString(row.catalog_product_key),
        }
      : {}),
    ...(firstNonEmptyString(row.catalog_category_path)
      ? {
          catalog_category_path: firstNonEmptyString(row.catalog_category_path),
          category_path: firstNonEmptyString(row.catalog_category_path),
        }
      : {}),
    ...(pivotaSignatureId ? { pivota_signature_id: pivotaSignatureId, signature_id: pivotaSignatureId } : {}),
    ...(pivotaCanonicalUrl ? { pivota_canonical_url: pivotaCanonicalUrl } : {}),
    source_listing_scope: firstNonEmptyString(seedData.source_listing_scope),
    url: pivotaCanonicalUrl || canonicalUrl || destinationUrl || undefined,
    canonical_url: pivotaCanonicalUrl || canonicalUrl || undefined,
    ...(canonicalUrl ? { merchant_canonical_url: canonicalUrl } : {}),
    destination_url: destinationUrl || undefined,
    external_seed_id: row.id ? String(row.id) : undefined,
    seed_data: seedData,
    external_seed_recall: recall,
    raw_ingredient_text_clean: firstNonEmptyString(
      seedData.raw_ingredient_text_clean,
      snapshot.raw_ingredient_text_clean,
      ingredientIntel.raw_ingredient_text_clean,
    ),
    pdp_ingredients_raw: firstNonEmptyString(seedData.pdp_ingredients_raw, snapshot.pdp_ingredients_raw),
    pdp_active_ingredients_raw: firstNonEmptyString(seedData.pdp_active_ingredients_raw, snapshot.pdp_active_ingredients_raw),
    ingredient_intel: ingredientIntel,
    ingredient_tokens: Array.isArray(recall.ingredient_tokens) ? recall.ingredient_tokens : undefined,
  };
  if (brand) {
    product.brand = brand;
    product.vendor = brand;
  }
  const localityFacts = resolveExternalSeedLocalityFacts({ row, seedData, snapshot });
  if (hasLocalityFactsValue(localityFacts)) {
    product.seed_data = applyLocalityFactsToSeedData(seedData, localityFacts);
    product.locality_facts_v1 = localityFacts;
    product.locality_facts = localityFacts;
    product.local_authority = localityFacts;
    if (localityFacts.brand_origin) product.brand_origin = localityFacts.brand_origin;
    if (localityFacts.brand_origin_country) product.brand_origin_country = localityFacts.brand_origin_country;
    if (localityFacts.brand_home_market) product.brand_home_market = localityFacts.brand_home_market;
    if (localityFacts.market_availability) product.market_availability = localityFacts.market_availability;
    if (Array.isArray(localityFacts.available_markets) && localityFacts.available_markets.length) {
      product.available_markets = localityFacts.available_markets;
    }
    if (Array.isArray(localityFacts.local_purchase_markets) && localityFacts.local_purchase_markets.length) {
      product.local_purchase_markets = localityFacts.local_purchase_markets;
    }
    if (Array.isArray(localityFacts.local_retail_channels) && localityFacts.local_retail_channels.length) {
      product.local_retail_channels = localityFacts.local_retail_channels;
      product.local_retail_channel = localityFacts.local_retail_channels
        .map((channel) => channel?.channel)
        .filter(Boolean);
    }
    if (typeof localityFacts.travel_size === 'boolean') product.travel_size = localityFacts.travel_size;
    if (localityFacts.creator_local_reason) product.creator_local_reason = localityFacts.creator_local_reason;
  }
  return product;
}

function beautyProductHasTargetMarketAuthority(product = {}, targetMarket = '', { requirePurchase = false } = {}) {
  const target = String(targetMarket || '').trim().toUpperCase();
  if (!target || !product || typeof product !== 'object') return false;
  const localAuthority = buildBeautyProductLocalAuthorityForResponse(product) || {};
  const purchaseMarkets = [
    product.market,
    product.merchant_market,
    localAuthority.retailer_region,
    ...(Array.isArray(localAuthority.local_purchase_markets) ? localAuthority.local_purchase_markets : []),
  ].map((value) => String(value || '').trim().toUpperCase()).filter(Boolean);
  if (purchaseMarkets.includes(target)) return true;
  if (requirePurchase) return false;
  const authorityMarkets = [
    localAuthority.brand_home_market,
    localAuthority.brand_origin_country,
    ...(Array.isArray(localAuthority.available_markets) ? localAuthority.available_markets : []),
  ].map((value) => String(value || '').trim().toUpperCase()).filter(Boolean);
  return authorityMarkets.includes(target);
}

async function queryBeautyExternalSeedRowsFast({
  market,
  queryText,
  intent,
  inStockOnly,
  limit,
  toolScope = 'all_tools',
} = {}) {
  if (!process.env.DATABASE_URL) {
    return {
      rawProducts: [],
      variantResults: [],
      categoryTerms: [],
      recallPatterns: [],
    };
  }

  const safeMarket = String(market || 'US').trim().toUpperCase() || 'US';
  const safeLimit = Math.max(1, Math.min(60, Number(limit || 24) || 24));
  const perScopeRowLimit = Math.max(8, Math.min(24, safeLimit * 2));
  const categoryTerms = buildBeautyExternalSeedCategoryTerms(intent);
  const perCategoryRowLimit = Math.max(3, Math.min(8, Math.ceil(perScopeRowLimit / Math.max(1, categoryTerms.length))));
  const recallPatterns = buildBeautyExternalSeedRecallPatterns({ queryText, intent });
  const primaryToolScopes = toolScope === 'creator_preferred'
    ? ['creator_agents', '*']
    : ['shopping_agents', 'creator_agents', '*'];
  const legacyToolScopes = [''];
  const toolScopes = PIVOT_BEAUTY_LEGACY_TOOL_SCOPE_RECALL_ENABLED
    ? primaryToolScopes.concat(legacyToolScopes)
    : primaryToolScopes;
  const rawProductCap = Math.max(safeLimit, Math.min(60, safeLimit * Math.max(1, toolScopes.length)));

  const seen = new Set();
  const rawProducts = [];
  const variantResults = [];
  const destinationBrandMarketBridge = {
    attempted: false,
    source_market: null,
    target_market: safeMarket,
    returned_count: 0,
  };
  const categoryAuthoritySql = `lower(coalesce(
    seed_data->'derived'->'recall'->>'category',
    seed_data->>'category',
    seed_data->'product'->>'category',
    seed_data->'snapshot'->>'category',
    seed_data->>'product_type',
    seed_data->'product'->>'product_type',
    seed_data->'snapshot'->>'product_type',
    ''
  ))`;
  const catalogMirrorProjectionSql = `
          (SELECT cp.product_key
             FROM catalog_products cp
             JOIN index_pipeline_state ips
               ON ips.content_key = cp.content_key
              AND ips.serving_eligible = TRUE
            WHERE cp.product_key = external_product_seeds.attached_product_key
            LIMIT 1) AS catalog_product_key,
          (SELECT cp.pivota_signature_id
             FROM catalog_products cp
             JOIN index_pipeline_state ips
               ON ips.content_key = cp.content_key
              AND ips.serving_eligible = TRUE
            WHERE cp.product_key = external_product_seeds.attached_product_key
            LIMIT 1) AS pivota_signature_id,
          (SELECT cp.pivota_canonical_url
             FROM catalog_products cp
             JOIN index_pipeline_state ips
               ON ips.content_key = cp.content_key
              AND ips.serving_eligible = TRUE
            WHERE cp.product_key = external_product_seeds.attached_product_key
            LIMIT 1) AS pivota_canonical_url,
          (SELECT cp.category_path
             FROM catalog_products cp
             JOIN index_pipeline_state ips
               ON ips.content_key = cp.content_key
              AND ips.serving_eligible = TRUE
            WHERE cp.product_key = external_product_seeds.attached_product_key
            LIMIT 1) AS catalog_category_path`;
  const attachedServingSeedFilterSql = `
              AND coalesce(attached_product_key, '') <> ''
              AND EXISTS (
                SELECT 1
                FROM catalog_products cp_serving
                JOIN index_pipeline_state ips_serving
                  ON ips_serving.content_key = cp_serving.content_key
                 AND ips_serving.serving_eligible = TRUE
                WHERE cp_serving.product_key = external_product_seeds.attached_product_key
              )`;
  const runScopeQuery = async (tool, queryMarket = safeMarket, marketScope = 'exact_market') => {
    try {
      const safeQueryMarket = String(queryMarket || safeMarket).trim().toUpperCase() || safeMarket;
      const isSingleCategory = categoryTerms.length === 1;
      const categoryLimitBind = `$${categoryTerms.length + 3}`;
      const scopeLimitBind = `$${categoryTerms.length + 4}`;
      const multiCategorySql = `
        SELECT
          id,
          external_product_id,
          market,
          tool,
          destination_url,
          canonical_url,
          domain,
          title,
          image_url,
          price_amount,
          price_currency,
          availability,
          seed_data,
          updated_at,
          created_at,
          catalog_product_key,
          pivota_signature_id,
          pivota_canonical_url,
          catalog_category_path
        FROM (
          ${categoryTerms
            .map((categoryTerm, index) => {
              const categoryBind = `$${index + 3}`;
              return `
          (
            SELECT
              id,
              external_product_id,
              market,
              tool,
              destination_url,
              canonical_url,
              domain,
              title,
              image_url,
              price_amount,
              price_currency,
              availability,
              seed_data,
              updated_at,
              created_at,
              ${catalogMirrorProjectionSql},
              ${index} AS category_order
            FROM external_product_seeds
            WHERE status = 'active'
              ${attachedServingSeedFilterSql}
              AND market = $1
              AND tool = $2
              AND ${categoryAuthoritySql} = ${categoryBind}
              ${inStockOnly ? `AND coalesce(lower(availability), '') NOT IN ('out of stock', 'out_of_stock', 'outofstock', 'oos')` : ''}
            ORDER BY
              updated_at DESC NULLS LAST,
              created_at DESC NULLS LAST
            LIMIT ${categoryLimitBind}
          )`;
            })
            .join('\n          UNION ALL\n')}
        ) scoped
        ORDER BY
          category_order ASC,
          updated_at DESC NULLS LAST,
          created_at DESC NULLS LAST
        LIMIT ${scopeLimitBind}
      `;
      const sql = isSingleCategory
        ? `
        SELECT
          id,
          external_product_id,
          market,
          tool,
          destination_url,
          canonical_url,
          domain,
          title,
          image_url,
          price_amount,
          price_currency,
          availability,
          seed_data,
          updated_at,
          created_at,
          ${catalogMirrorProjectionSql}
        FROM external_product_seeds
        WHERE status = 'active'
          ${attachedServingSeedFilterSql}
          AND market = $1
          AND tool = $2
          AND ${categoryAuthoritySql} = $3
          ${inStockOnly ? `AND coalesce(lower(availability), '') NOT IN ('out of stock', 'out_of_stock', 'outofstock', 'oos')` : ''}
        ORDER BY
          updated_at DESC NULLS LAST,
          created_at DESC NULLS LAST
        LIMIT $4
      `
        : multiCategorySql;
      const params = isSingleCategory
        ? [safeQueryMarket, tool, categoryTerms[0], perScopeRowLimit]
        : [safeQueryMarket, tool, ...categoryTerms, perCategoryRowLimit, perScopeRowLimit];
      const queryStartedAt = Date.now();
      const result = await queryBeautyExternalSeedRowsWithTimeout(
        sql,
        params,
        1200,
      );
      const queryDurationMs = Math.max(0, Date.now() - queryStartedAt);
      const rows = Array.isArray(result?.rows) ? result.rows : [];
      return {
        tool,
        rows,
        variant: {
          query: String(queryText || '').trim(),
          row_count: rows.length,
          category_terms: categoryTerms,
          recall_pattern_count: recallPatterns.length,
          per_category_row_limit: perCategoryRowLimit,
          market: safeQueryMarket,
          market_scope: marketScope,
          tool_scope: tool || '(empty)',
          legacy_tool_scope_recall: PIVOT_BEAUTY_LEGACY_TOOL_SCOPE_RECALL_ENABLED,
          single_category_indexed_query: isSingleCategory,
          multi_category_indexed_union_query: !isSingleCategory,
          query_duration_ms: queryDurationMs,
          parallel_scope_recall: PIVOT_BEAUTY_PARALLEL_SCOPE_RECALL_ENABLED,
        },
      };
    } catch (err) {
      return {
        tool,
        rows: [],
        variant: {
          query: String(queryText || '').trim(),
          row_count: 0,
          category_terms: categoryTerms,
          recall_pattern_count: recallPatterns.length,
          market: String(queryMarket || safeMarket).trim().toUpperCase() || safeMarket,
          market_scope: marketScope,
          tool_scope: tool || '(empty)',
          legacy_tool_scope_recall: PIVOT_BEAUTY_LEGACY_TOOL_SCOPE_RECALL_ENABLED,
          single_category_indexed_query: categoryTerms.length === 1,
          multi_category_indexed_union_query: categoryTerms.length !== 1,
          parallel_scope_recall: PIVOT_BEAUTY_PARALLEL_SCOPE_RECALL_ENABLED,
          error_code: String(err?.code || err?.name || 'query_failed').slice(0, 80),
          timeout: String(err?.code || '').trim() === '57014' || /timeout|cancel/i.test(String(err?.message || '')),
        },
      };
    }
  };
  const runTextRecallQuery = async (tool, queryMarket = safeMarket, marketScope = 'text_recall_underfill') => {
    const safePatterns = recallPatterns.filter(Boolean).slice(0, 14);
    const brandCategoryRecall = Boolean(
      intent?.brandBrowse &&
        intent.brandBrowse.contract === 'brand_browse' &&
        intent.brandBrowse.brand_only === false,
    );
    const brandPatterns = brandCategoryRecall
      ? uniqueStrings([intent.brandBrowse.brand, intent.brandBrowse.alias])
          .map((value) => normalizeSearchTextForMatch(value))
          .filter(Boolean)
          .map((value) => `%${value}%`)
      : [];
    const brandCategoryTerms = brandCategoryRecall
      ? buildBeautyExternalSeedBrandCategoryTextTerms(queryText, intent)
      : [];
    const brandCategoryPatterns = brandCategoryTerms.map((value) => `%${value}%`);
    if (!safePatterns.length) {
      return {
        tool,
        rows: [],
        variant: {
          query: String(queryText || '').trim(),
          row_count: 0,
          category_terms: categoryTerms,
          recall_pattern_count: 0,
          market: String(queryMarket || safeMarket).trim().toUpperCase() || safeMarket,
          market_scope: marketScope,
          tool_scope: tool || '(empty)',
          text_recall_underfill: true,
        },
      };
    }
    try {
      const safeQueryMarket = String(queryMarket || safeMarket).trim().toUpperCase() || safeMarket;
      const useBrandCategoryRecall = brandPatterns.length > 0 && brandCategoryPatterns.length > 0;
      if (useBrandCategoryRecall) {
        const brandClauses = brandPatterns.map((_, index) => {
          const bind = `$${index + 3}`;
          return `(
            lower(coalesce(seed_data->>'brand', '')) LIKE ${bind}
            OR lower(coalesce(seed_data->>'vendor', '')) LIKE ${bind}
            OR lower(coalesce(seed_data->'snapshot'->>'brand', '')) LIKE ${bind}
            OR lower(coalesce(seed_data->'snapshot'->>'vendor', '')) LIKE ${bind}
            OR lower(coalesce(seed_data->'derived'->'recall'->>'brand_name', '')) LIKE ${bind}
          )`;
        });
        const categoryStartIndex = 3 + brandPatterns.length;
        const categoryClauses = brandCategoryPatterns.map((_, index) => {
          const bind = `$${categoryStartIndex + index}`;
          return `(
            lower(coalesce(title, '')) LIKE ${bind}
            OR lower(coalesce(seed_data->>'title', '')) LIKE ${bind}
            OR lower(coalesce(seed_data->>'category', '')) LIKE ${bind}
            OR lower(coalesce(seed_data->>'product_type', '')) LIKE ${bind}
            OR lower(coalesce(seed_data->'snapshot'->>'title', '')) LIKE ${bind}
            OR lower(coalesce(seed_data->'snapshot'->>'category', '')) LIKE ${bind}
            OR lower(coalesce(seed_data->'derived'->'recall'->>'retrieval_title', '')) LIKE ${bind}
            OR lower(coalesce(seed_data->'derived'->'recall'->>'retrieval_summary', '')) LIKE ${bind}
            OR lower(coalesce(seed_data->'derived'->'recall'->>'category', '')) LIKE ${bind}
          )`;
        });
        const limitBind = `$${3 + brandPatterns.length + brandCategoryPatterns.length}`;
        const sql = `
          SELECT
            id,
            external_product_id,
            market,
            tool,
            destination_url,
            canonical_url,
            domain,
            title,
            image_url,
            price_amount,
            price_currency,
            availability,
            seed_data,
            updated_at,
            created_at,
            ${catalogMirrorProjectionSql}
          FROM external_product_seeds
          WHERE status = 'active'
            ${attachedServingSeedFilterSql}
            AND market = $1
            AND tool = $2
            AND (${brandClauses.join('\n            OR ')})
            AND (${categoryClauses.join('\n            OR ')})
            ${inStockOnly ? `AND coalesce(lower(availability), '') NOT IN ('out of stock', 'out_of_stock', 'outofstock', 'oos')` : ''}
          ORDER BY
            updated_at DESC NULLS LAST,
            created_at DESC NULLS LAST
          LIMIT ${limitBind}
        `;
        const queryStartedAt = Date.now();
        const result = await queryBeautyExternalSeedRowsWithTimeout(
          sql,
          [safeQueryMarket, tool, ...brandPatterns, ...brandCategoryPatterns, perScopeRowLimit],
          2800,
        );
        const queryDurationMs = Math.max(0, Date.now() - queryStartedAt);
        const rows = Array.isArray(result?.rows) ? result.rows : [];
        return {
          tool,
          rows,
          variant: {
            query: String(queryText || '').trim(),
            row_count: rows.length,
            category_terms: categoryTerms,
            recall_pattern_count: safePatterns.length,
            brand_category_text_terms: brandCategoryTerms,
            market: safeQueryMarket,
            market_scope: marketScope,
            tool_scope: tool || '(empty)',
            text_recall_underfill: true,
            brand_category_text_recall: true,
            query_duration_ms: queryDurationMs,
          },
        };
      }
      const patternClauses = safePatterns.map((_, index) => {
        const bind = `$${index + 3}`;
        return `(
          lower(coalesce(title, '')) LIKE ${bind}
          OR lower(coalesce(domain, '')) LIKE ${bind}
          OR lower(coalesce(seed_data->>'brand', '')) LIKE ${bind}
          OR lower(coalesce(seed_data->>'vendor', '')) LIKE ${bind}
          OR lower(coalesce(seed_data->>'title', '')) LIKE ${bind}
          OR lower(coalesce(seed_data->>'category', '')) LIKE ${bind}
          OR lower(coalesce(seed_data->>'product_type', '')) LIKE ${bind}
          OR lower(coalesce(seed_data->'snapshot'->>'brand', '')) LIKE ${bind}
          OR lower(coalesce(seed_data->'snapshot'->>'title', '')) LIKE ${bind}
          OR lower(coalesce(seed_data->'snapshot'->>'category', '')) LIKE ${bind}
          OR lower(coalesce(seed_data->'derived'->'recall'->>'brand_name', '')) LIKE ${bind}
          OR lower(coalesce(seed_data->'derived'->'recall'->>'retrieval_title', '')) LIKE ${bind}
          OR lower(coalesce(seed_data->'derived'->'recall'->>'retrieval_summary', '')) LIKE ${bind}
          OR lower(coalesce(seed_data->'derived'->'recall'->>'category', '')) LIKE ${bind}${
            PIVOT_BEAUTY_ACTIVE_AWARE_RECALL_ENABLED
              ? `
          OR lower(coalesce(seed_data#>>'{derived,recall,ingredient_tokens}', '')) LIKE ${bind}
          OR lower(coalesce(seed_data#>>'{derived,recall,alias_tokens}', '')) LIKE ${bind}`
              : ''
          }
        )`;
      });
      const limitBind = `$${safePatterns.length + 3}`;
      const sql = `
        SELECT
          id,
          external_product_id,
          market,
          tool,
          destination_url,
          canonical_url,
          domain,
          title,
          image_url,
          price_amount,
          price_currency,
          availability,
          seed_data,
          updated_at,
          created_at,
          ${catalogMirrorProjectionSql}
        FROM external_product_seeds
        WHERE status = 'active'
          ${attachedServingSeedFilterSql}
          AND market = $1
          AND tool = $2
          AND (${patternClauses.join('\n          OR ')})
          ${inStockOnly ? `AND coalesce(lower(availability), '') NOT IN ('out of stock', 'out_of_stock', 'outofstock', 'oos')` : ''}
        ORDER BY
          updated_at DESC NULLS LAST,
          created_at DESC NULLS LAST
        LIMIT ${limitBind}
      `;
      const queryStartedAt = Date.now();
      const result = await queryBeautyExternalSeedRowsWithTimeout(
        sql,
        [safeQueryMarket, tool, ...safePatterns, perScopeRowLimit],
        1200,
      );
      const queryDurationMs = Math.max(0, Date.now() - queryStartedAt);
      const rows = Array.isArray(result?.rows) ? result.rows : [];
      return {
        tool,
        rows,
        variant: {
          query: String(queryText || '').trim(),
          row_count: rows.length,
          category_terms: categoryTerms,
          recall_pattern_count: safePatterns.length,
          market: safeQueryMarket,
          market_scope: marketScope,
          tool_scope: tool || '(empty)',
          text_recall_underfill: true,
          query_duration_ms: queryDurationMs,
        },
      };
    } catch (err) {
      return {
        tool,
        rows: [],
        variant: {
          query: String(queryText || '').trim(),
          row_count: 0,
          category_terms: categoryTerms,
          recall_pattern_count: safePatterns.length,
          market: String(queryMarket || safeMarket).trim().toUpperCase() || safeMarket,
          market_scope: marketScope,
          tool_scope: tool || '(empty)',
          text_recall_underfill: true,
          error_code: String(err?.code || err?.name || 'query_failed').slice(0, 80),
          timeout: String(err?.code || '').trim() === '57014' || /timeout|cancel/i.test(String(err?.message || '')),
        },
      };
    }
  };
  const appendScopeRows = (scopeResult, { requireTargetMarketAuthority = false } = {}) => {
    if (!scopeResult || typeof scopeResult !== 'object') return;
    if (scopeResult.variant) variantResults.push(scopeResult.variant);
    const brandCategoryScopeRequiresBrand = Boolean(
      intent?.brandBrowse &&
        intent.brandBrowse.contract === 'brand_browse' &&
        intent.brandBrowse.brand_only === false,
    );
    for (const row of Array.isArray(scopeResult.rows) ? scopeResult.rows : []) {
      if (rawProducts.length >= rawProductCap) break;
      const product = buildBeautyExternalSeedMainlineProduct(row);
      if (!product) continue;
      const candidateText = brandCategoryScopeRequiresBrand ? buildFallbackCandidateText(product) : '';
      if (
        brandCategoryScopeRequiresBrand &&
        !searchProductMatchesBeautyBrandBrowse(product, intent.brandBrowse, candidateText)
      ) {
        continue;
      }
      if (
        requireTargetMarketAuthority &&
        !beautyProductHasTargetMarketAuthority(product, safeMarket, { requirePurchase: false })
      ) {
        continue;
      }
      product.market = row.market || safeMarket;
      product.tool = row.tool || null;
      product.external_seed_id = product.external_seed_id || row.id || null;
      if (isBeautyProductContraindicatedForQuery(product, queryText, intent)) continue;
      const intentFamilies = Array.isArray(intent?.families) ? intent.families : [];
      if (
        intentFamilies.length > 0 &&
        !intentFamilies.some((family) => beautyProductMatchesFamily(product, family))
      ) {
        continue;
      }
      const key = buildSearchProductKey(product);
      if (!key || seen.has(key)) continue;
      seen.add(key);
      rawProducts.push(product);
      if (requireTargetMarketAuthority) destinationBrandMarketBridge.returned_count += 1;
    }
  };

  if (PIVOT_BEAUTY_PARALLEL_SCOPE_RECALL_ENABLED) {
    const scopeResults = await Promise.all(toolScopes.map((tool) => runScopeQuery(tool)));
    for (const scopeResult of scopeResults) {
      appendScopeRows(scopeResult);
    }
  } else {
    for (const tool of toolScopes) {
      if (rawProducts.length >= rawProductCap) break;
      appendScopeRows(await runScopeQuery(tool));
    }
  }

  const brandCategoryTextRecallRequired = Boolean(
    intent?.brandBrowse &&
      intent.brandBrowse.contract === 'brand_browse' &&
      intent.brandBrowse.brand_only === false,
  );
  if ((rawProducts.length < safeLimit || brandCategoryTextRecallRequired) && recallPatterns.length > 0) {
    if (PIVOT_BEAUTY_PARALLEL_SCOPE_RECALL_ENABLED) {
      const textScopeResults = await Promise.all(toolScopes.map((tool) => runTextRecallQuery(tool)));
      for (const scopeResult of textScopeResults) {
        appendScopeRows(scopeResult);
      }
    } else {
      for (const tool of toolScopes) {
        if (rawProducts.length >= rawProductCap) break;
        appendScopeRows(await runTextRecallQuery(tool));
      }
    }
  }

  const shouldBridgeDestinationBrandMarket =
    safeMarket !== 'US' &&
    safeMarket === 'KR' &&
    hasKBeautyLocalIntent(queryText) &&
    rawProducts.length < safeLimit;
  if (shouldBridgeDestinationBrandMarket) {
    destinationBrandMarketBridge.attempted = true;
    destinationBrandMarketBridge.source_market = 'US';
    if (PIVOT_BEAUTY_PARALLEL_SCOPE_RECALL_ENABLED) {
      const bridgeResults = await Promise.all(
        toolScopes.map((tool) => runScopeQuery(tool, 'US', `${safeMarket.toLowerCase()}_brand_home_bridge`)),
      );
      for (const scopeResult of bridgeResults) {
        appendScopeRows(scopeResult, { requireTargetMarketAuthority: true });
      }
    } else {
      for (const tool of toolScopes) {
        if (rawProducts.length >= rawProductCap) break;
        appendScopeRows(await runScopeQuery(tool, 'US', `${safeMarket.toLowerCase()}_brand_home_bridge`), {
          requireTargetMarketAuthority: true,
        });
      }
    }
  }

  return {
    rawProducts,
    variantResults,
    categoryTerms,
    recallPatterns,
    destinationBrandMarketBridge,
  };
}

function parseCanonicalPayloadObject(value) {
  if (isPlainObject(value)) return value;
  if (typeof value !== 'string') return {};
  try {
    const parsed = JSON.parse(value);
    return isPlainObject(parsed) ? parsed : {};
  } catch {
    return {};
  }
}

function parseCanonicalCatalogPayload(value) {
  const payload = parseCanonicalPayloadObject(value);
  if (!Object.keys(payload).length) return {};
  const seedData = parseCanonicalPayloadObject(payload.seed_data);
  const externalSeed = parseCanonicalPayloadObject(payload.external_seed);
  const seedSnapshot = parseCanonicalPayloadObject(seedData.snapshot);
  const externalSnapshot = parseCanonicalPayloadObject(externalSeed.snapshot);
  const normalizedSeedData = {
    ...seedData,
    ...(Object.keys(seedSnapshot).length ? { snapshot: seedSnapshot } : {}),
  };
  const normalizedExternalSeed = {
    ...externalSeed,
    ...(Object.keys(externalSnapshot).length ? { snapshot: externalSnapshot } : {}),
  };

  return {
    ...payload,
    ...(Object.keys(normalizedSeedData).length ? { seed_data: normalizedSeedData } : {}),
    ...(Object.keys(normalizedExternalSeed).length ? { external_seed: normalizedExternalSeed } : {}),
  };
}

function firstStringFromArray(value) {
  if (!Array.isArray(value)) return null;
  for (const item of value) {
    if (typeof item === 'string') {
      const trimmed = item.trim();
      if (trimmed) return trimmed;
      continue;
    }
    if (isPlainObject(item)) {
      const candidate = firstNonEmptyString(
        item.url,
        item.src,
        item.href,
        item.image_url,
        item.imageUrl,
        item.canonical_url,
        item.destination_url,
      );
      if (candidate) return candidate;
    }
  }
  return null;
}

function firstCatalogPayloadString(...values) {
  for (const value of values) {
    if (Array.isArray(value)) {
      const candidate = firstStringFromArray(value);
      if (candidate) return candidate;
      continue;
    }
    const candidate = firstNonEmptyString(value);
    if (candidate) return candidate;
  }
  return null;
}

function firstNonEmptyArray(...values) {
  for (const value of values) {
    if (Array.isArray(value) && value.length > 0) return value;
  }
  return null;
}

function normalizeCatalogCategoryPathArray(value) {
  const text = String(value || '').trim();
  if (!text) return [];
  return text.split('/').map((part) => part.trim()).filter(Boolean);
}

function normalizeBrandCase(brand) {
  if (typeof brand !== 'string') return brand;
  if (!brand || /\p{Lu}/u.test(brand)) return brand;
  return brand.replace(/\b\p{L}/gu, (ch) => ch.toUpperCase());
}

function firstBrandDisplayString(...values) {
  const candidates = [];
  for (const value of values) {
    const candidate = firstNonEmptyString(value);
    if (candidate) candidates.push(candidate);
  }
  if (!candidates.length) return null;
  return normalizeBrandCase(candidates.find((candidate) => /\p{Lu}/u.test(candidate)) || candidates[0]);
}

// Reason code stamped on a canonical-chain product whose joined catalog_offers
// row carries no usable price. Counted into the search-quality telemetry as
// `no_offer_derived_price_count` so this residue stays sortable instead of
// being silently absorbed by a guess.
const CANONICAL_NO_OFFER_DERIVED_PRICE_REASON = 'no_offer_derived_price';

/**
 * Resolve a canonical-chain row's price from that row's OWN catalog_offers row.
 *
 * PRIMARY ROUTE ONLY — THERE IS DELIBERATELY NO FALLBACK. Amount and currency
 * must come from the SAME offer row or no price is emitted at all.
 *
 * This used to be two INDEPENDENT chains: the amount walked
 * merchant_effective_price -> estimated_best_price -> list_price -> the seed
 * payload, while the currency walked a separate chain ending in the literal
 * 'USD'. Nothing tied them together, so an amount taken from the payload could
 * be labelled with a currency taken from somewhere else — or with a hardcoded
 * USD that no source ever asserted. Measured on prod 2026-08-05 across the
 * 15,961 rows the fan-out lane emits for 9,289 serving-eligible products: two
 * rows resolved amount-from-payload with currency-from-offer-row, and one of
 * them (product_key prod::external_seed::external_seed::ext_b0a4058ee31f92149cfb14ba)
 * carried a EUR payload amount under a USD offer currency — a live wrong price.
 *
 * A fallback-derived price is an invisible wrong answer that makes a broken
 * primary route look healthy. An absent price is a countable failure that gets
 * fixed. So when the offer row has no usable price this returns `priced:false`
 * and the caller emits NO price and NO currency; getSearchProductServingEligibility
 * then drops the product on `missing_price`, which is the correct outcome.
 *
 * coalesce(merchant_effective_price, list_price) is the buyable-price
 * expression from services/pricedOfferSql.js — the same one the OFFER_PRICE_MISSING
 * trust gate and the best_offer LATERAL in services/canonicalCatalogSearch.js
 * use, so the served surface and the gate that admits it now agree by
 * construction. estimated_best_price is deliberately NOT consulted: it is our
 * own derived estimate, and pricedOfferSql excludes it for exactly that reason
 * ("a PDP must not be published on the strength of our own guess"). It sat at
 * position 2 of the old amount chain, AHEAD of list_price, so the served price
 * could be an estimate the trust gate did not even count as a price. Measured
 * 2026-08-05: estimated_best_price is set on 11,098 rows but would have won on
 * 0 of them, so removing it changes no row today and closes the divergence
 * before a writer populates only that column.
 *
 * `> 0` rather than merely present, matching pricedOfferSql: a 0.00 price is
 * not buyable either.
 */
function resolveCanonicalOfferDerivedPrice(row) {
  if (!isPlainObject(row)) {
    return { priced: false, reason: CANONICAL_NO_OFFER_DERIVED_PRICE_REASON };
  }
  const currency = firstNonEmptyString(row.currency);
  const amountRaw = firstNonEmptyString(row.merchant_effective_price, row.list_price);
  const amount = Number(amountRaw);
  if (!currency || !Number.isFinite(amount) || amount <= 0) {
    return { priced: false, reason: CANONICAL_NO_OFFER_DERIVED_PRICE_REASON };
  }
  return { priced: true, amount, currency };
}

function buildCanonicalChainMainlineProduct(row) {
  if (!row || typeof row !== 'object' || Array.isArray(row)) return null;
  const payload = parseCanonicalCatalogPayload(row.product_payload);
  const seedData = isPlainObject(payload.seed_data) ? payload.seed_data : {};
  const snapshot = isPlainObject(seedData.snapshot) ? seedData.snapshot : {};
  const externalSeed = isPlainObject(payload.external_seed) ? payload.external_seed : {};
  const externalSnapshot = isPlainObject(externalSeed.snapshot) ? externalSeed.snapshot : {};
  const sourceProductId = firstNonEmptyString(
    row.source_product_id,
    externalSeed.external_product_id,
    externalSeed.product_id,
    seedData.external_product_id,
    seedData.product_id,
    externalSnapshot.product_id,
    snapshot.product_id,
  );
  const pivotaSignatureId = firstNonEmptyString(row.pivota_signature_id);
  const productId = firstNonEmptyString(pivotaSignatureId, sourceProductId, row.product_key);
  const title = firstNonEmptyString(
    row.product_title,
    seedData.title,
    seedData.name,
    seedData.product_name,
    snapshot.title,
    snapshot.name,
    externalSeed.title,
    externalSeed.name,
    externalSnapshot.title,
    productId,
  );
  if (!productId || !title) return null;
  const merchantId = firstNonEmptyString(row.merchant_id, EXTERNAL_SEED_MERCHANT_ID);
  const brand = firstBrandDisplayString(
    seedData.brand,
    seedData.brand_name,
    seedData.vendor,
    snapshot.brand,
    snapshot.vendor,
    externalSeed.brand,
    externalSeed.vendor,
    externalSeed.merchant_name,
    externalSnapshot.brand,
    externalSnapshot.vendor,
    externalSnapshot.merchant_name,
    row.brand,
  );
  const categoryPathText = firstCatalogPayloadString(
    row.category_path,
    seedData.category_path,
    seedData.catalog_category_path,
    snapshot.category_path,
    snapshot.catalog_category_path,
    externalSeed.category_path,
    externalSnapshot.category_path,
  );
  const offerPrice = resolveCanonicalOfferDerivedPrice(row);
  const availability = firstNonEmptyString(
    row.availability,
    externalSeed.availability,
    externalSeed.in_stock,
    externalSnapshot.availability,
    seedData.availability,
    seedData.in_stock,
    snapshot.availability,
  );
  const availabilityKey = String(availability || '').trim().toLowerCase();
  const inStock = availabilityKey
    ? availabilityKey === 'true'
      ? true
      : availabilityKey === 'false'
        ? false
        : !['out of stock', 'out_of_stock', 'outofstock', 'oos', 'sold out', 'sold_out', 'unavailable'].includes(availabilityKey)
    : undefined;
  const imageUrl = firstCatalogPayloadString(
    row.sku_image_url,
    row.product_image_url,
    externalSeed.image_url,
    externalSeed.imageUrl,
    externalSeed.images,
    externalSeed.image_urls,
    externalSnapshot.image_url,
    externalSnapshot.images,
    seedData.image_url,
    seedData.imageUrl,
    seedData.images,
    seedData.image_urls,
    snapshot.image_url,
    snapshot.images,
    snapshot.image_urls,
  );
  const merchantCanonicalUrl = firstCatalogPayloadString(
    row.canonical_url,
    row.destination_url,
    externalSeed.destination_url,
    externalSeed.destinationUrl,
    externalSeed.canonical_url,
    externalSeed.canonicalUrl,
    externalSeed.url,
    externalSnapshot.destination_url,
    externalSnapshot.canonical_url,
    seedData.destination_url,
    seedData.destinationUrl,
    seedData.canonical_url,
    seedData.canonicalUrl,
    seedData.url,
    snapshot.destination_url,
    snapshot.canonical_url,
  );
  const pivotaCanonicalUrl = firstNonEmptyString(row.pivota_canonical_url);
  const canonicalProductRef = {
    merchant_id: merchantId,
    product_id: sourceProductId || productId,
    platform: firstNonEmptyString(row.platform, row.merchant_primary_platform, merchantId === EXTERNAL_SEED_MERCHANT_ID ? 'external_seed' : 'catalog'),
    ...(firstNonEmptyString(row.product_key) ? { product_key: firstNonEmptyString(row.product_key) } : {}),
    ...(pivotaSignatureId ? { pivota_signature_id: pivotaSignatureId } : {}),
  };
  const category = firstNonEmptyString(
    row.category,
    row.product_type,
    externalSeed.category,
    externalSeed.product_type,
    externalSeed.kind,
    externalSnapshot.category,
    seedData.category,
    seedData.product_type,
    seedData.kind,
    snapshot.category,
    snapshot.product_type,
  );
  const description = firstNonEmptyString(
    row.product_description,
    externalSeed.description,
    externalSeed.description_text,
    externalSeed.pdp_description,
    externalSeed.pdp_description_raw,
    externalSeed.overview,
    externalSeed.summary,
    externalSnapshot.description,
    seedData.description,
    seedData.description_text,
    seedData.pdp_description,
    seedData.pdp_description_raw,
    seedData.overview,
    seedData.summary,
    snapshot.description,
    snapshot.description_text,
    snapshot.pdp_description,
    snapshot.pdp_description_raw,
    snapshot.overview,
    snapshot.summary,
  );
  const ingredientIntel =
    [payload.ingredient_intel, seedData.ingredient_intel, snapshot.ingredient_intel, externalSeed.ingredient_intel, externalSnapshot.ingredient_intel]
      .find((value) => isPlainObject(value)) || {};
  const ingredientRemediation =
    [
      payload.ingredient_remediation_v1,
      seedData.ingredient_remediation_v1,
      snapshot.ingredient_remediation_v1,
      externalSeed.ingredient_remediation_v1,
      externalSnapshot.ingredient_remediation_v1,
    ].find((value) => isPlainObject(value)) || null;
  const pdpFieldQualitySummary =
    [
      payload.pdp_field_quality_summary,
      seedData.pdp_field_quality_summary,
      snapshot.pdp_field_quality_summary,
      externalSeed.pdp_field_quality_summary,
      externalSnapshot.pdp_field_quality_summary,
    ].find((value) => isPlainObject(value)) || null;
  const ingredientsInci = firstNonEmptyArray(
    payload.ingredients_inci,
    seedData.ingredients_inci,
    snapshot.ingredients_inci,
    externalSeed.ingredients_inci,
    externalSnapshot.ingredients_inci,
    ingredientIntel.inci_list,
  );
  const activeIngredients = firstNonEmptyArray(
    payload.active_ingredients,
    seedData.active_ingredients,
    snapshot.active_ingredients,
    externalSeed.active_ingredients,
    externalSnapshot.active_ingredients,
    ingredientIntel.active_ingredients,
  );

  return {
    id: productId,
    product_id: productId,
    merchant_id: merchantId,
    merchant_name: firstNonEmptyString(row.merchant_name, brand, merchantId),
    platform: firstNonEmptyString(row.platform, row.merchant_primary_platform, merchantId === EXTERNAL_SEED_MERCHANT_ID ? 'external_seed' : 'catalog'),
    platform_product_id: sourceProductId || productId,
    title,
    ...(description ? { description } : {}),
    // Price and currency ship together or not at all — they come from one
    // offer row (see resolveCanonicalOfferDerivedPrice). `currency` is NOT
    // emitted unconditionally any more: it used to be present on every product
    // even when there was no price, which is where the hardcoded 'USD' default
    // surfaced. A price-less product now carries a reason code instead.
    ...(offerPrice.priced
      ? { price: offerPrice.amount, currency: offerPrice.currency }
      : { price_absent_reason: offerPrice.reason }),
    ...(imageUrl ? { image_url: imageUrl, images: [imageUrl], image_urls: [imageUrl] } : {}),
    ...(availability ? { availability } : {}),
    ...(typeof inStock === 'boolean' ? { in_stock: inStock } : {}),
    product_type: category || 'canonical_catalog',
    ...(category ? { category } : {}),
    ...(categoryPathText ? { category_path: normalizeCatalogCategoryPathArray(categoryPathText) } : {}),
    ...(categoryPathText ? { catalog_category_path: categoryPathText } : {}),
    source: 'canonical_chain',
    search_recall_source: 'canonical_chain',
    catalog_source: 'canonical_chain',
    catalog_product_key: firstNonEmptyString(row.product_key),
    product_key: firstNonEmptyString(row.product_key),
    source_product_id: sourceProductId || undefined,
    canonical_product_ref: canonicalProductRef,
    pdp_open: {
      path: 'internal',
      product_ref: canonicalProductRef,
      canonical_product_ref: canonicalProductRef,
      subject: {
        type: 'product_group',
        id: pivotaSignatureId || productId,
      },
    },
    ...(pivotaSignatureId ? { pivota_signature_id: pivotaSignatureId } : {}),
    ...(pivotaCanonicalUrl ? { pivota_canonical_url: pivotaCanonicalUrl } : {}),
    url: pivotaCanonicalUrl || merchantCanonicalUrl || undefined,
    ...(pivotaCanonicalUrl || merchantCanonicalUrl ? { canonical_url: pivotaCanonicalUrl || merchantCanonicalUrl } : {}),
    ...(merchantCanonicalUrl ? { destination_url: merchantCanonicalUrl, merchant_canonical_url: merchantCanonicalUrl } : {}),
    raw_ingredient_text_clean: firstNonEmptyString(
      payload.raw_ingredient_text_clean,
      seedData.raw_ingredient_text_clean,
      snapshot.raw_ingredient_text_clean,
      externalSeed.raw_ingredient_text_clean,
      externalSnapshot.raw_ingredient_text_clean,
      ingredientIntel.raw_ingredient_text_clean,
    ),
    pdp_ingredients_raw: firstNonEmptyString(
      payload.pdp_ingredients_raw,
      seedData.pdp_ingredients_raw,
      snapshot.pdp_ingredients_raw,
      externalSeed.pdp_ingredients_raw,
      externalSnapshot.pdp_ingredients_raw,
    ),
    ...(ingredientsInci ? { ingredients_inci: ingredientsInci } : {}),
    ...(activeIngredients ? { active_ingredients: activeIngredients } : {}),
    ...(Object.keys(ingredientIntel).length ? { ingredient_intel: ingredientIntel } : {}),
    ...(ingredientRemediation ? { ingredient_remediation_v1: ingredientRemediation } : {}),
    ...(pdpFieldQualitySummary ? { pdp_field_quality_summary: pdpFieldQualitySummary } : {}),
    catalog_track: firstNonEmptyString(row.catalog_track),
    truth_tier: firstNonEmptyString(row.truth_tier),
    readiness_tier: firstNonEmptyString(row.readiness_tier),
    pdp_scope: firstNonEmptyString(row.pdp_scope),
    ...(sourceProductId && sourceProductId.startsWith('ext_') ? { external_seed_id: sourceProductId } : {}),
    ...(Object.keys(seedData).length ? { seed_data: seedData } : {}),
    ...(Object.keys(externalSeed).length ? { external_seed: externalSeed } : {}),
    ...(brand ? { brand, vendor: brand } : {}),
    ...buildFashionMetaFromCanonicalRow(row),
  };
}

// Phase O-5b: assemble product.fashion_meta from the new catalog_products
// columns (material / care + per-field provenance siblings). pdpBuilder's
// pickFashionMeta consumes the provenance-tagged shape and applies its
// 0.6 confidence threshold to drop low-trust derived values from
// merchant-facing prose. Only emits the key when at least one field has
// a value — keeps the payload clean for products with no fashion data.
//
// size_guide is intentionally NOT emitted here yet. The current jsonb
// shape from the regex extractor is {raw: string}; the UI consumer
// (FashionSizeFitGuide) expects {columns, rows, ...} structured data.
// That mapping ships in a follow-up alongside the LLM extractor that
// can produce the structured shape.
function buildFashionMetaFromCanonicalRow(row) {
  const fields = {};
  const addField = (key, value, source, confidence) => {
    if (typeof value !== 'string' || !value.trim()) return;
    const entry = { value: value.trim() };
    if (typeof source === 'string' && source.trim()) entry.source = source.trim();
    if (typeof confidence === 'number' && Number.isFinite(confidence)) {
      entry.confidence = confidence;
    }
    fields[key] = entry;
  };
  addField('material', row.material, row.material_source, row.material_confidence);
  addField('care', row.care, row.care_source, row.care_confidence);
  if (Object.keys(fields).length === 0) return {};
  return { fashion_meta: fields };
}

function mergeCanonicalChainProductsWithSeedProducts(seedProducts = [], canonicalProducts = []) {
  const canonicalList = Array.isArray(canonicalProducts) ? canonicalProducts.filter(Boolean) : [];
  const canonicalProductKeys = new Set(
    canonicalList
      .map((product) => firstNonEmptyString(product.catalog_product_key, product.product_key))
      .filter(Boolean),
  );
  const canonicalSourceProductIds = new Set(
    canonicalList
      .map((product) => firstNonEmptyString(product.source_product_id, product.platform_product_id))
      .filter(Boolean),
  );
  let canonicalDedupeCount = 0;
  const filteredSeeds = [];
  for (const product of Array.isArray(seedProducts) ? seedProducts : []) {
    if (!product || typeof product !== 'object' || Array.isArray(product)) continue;
    const seedProductKey = firstNonEmptyString(
      product.attached_product_key,
      product.attachedProductKey,
      product.catalog_product_key,
      product.product_key,
    );
    const seedSourceProductId = firstNonEmptyString(
      product.source_product_id,
      product.platform_product_id,
      product.product_id,
      product.id,
    );
    if (
      (seedProductKey && canonicalProductKeys.has(seedProductKey)) ||
      (seedSourceProductId && canonicalSourceProductIds.has(seedSourceProductId))
    ) {
      canonicalDedupeCount += 1;
      continue;
    }
    filteredSeeds.push(product);
  }

  const merged = [];
  const seen = new Set();
  const push = (product) => {
    if (!product || typeof product !== 'object' || Array.isArray(product)) return;
    const key =
      firstNonEmptyString(product.catalog_product_key, product.product_key, product.source_product_id)
        ? `canonical:${firstNonEmptyString(product.catalog_product_key, product.product_key, product.source_product_id)}`
        : buildSearchProductKey(product);
    if (key && seen.has(key)) return;
    if (key) seen.add(key);
    merged.push(product);
  };

  filteredSeeds.forEach(push);
  canonicalList.forEach(push);

  return {
    products: merged,
    canonical_dedupe_count: canonicalDedupeCount,
    canonical_product_keys: canonicalProductKeys,
  };
}

const SEARCH_CARD_GENERIC_CATEGORY_LABELS = new Set([
  '',
  'all',
  'catalog',
  'external',
  'misc',
  'other',
  'product',
  'products',
  'unknown',
  'uncategorized',
]);

function firstSearchProductImageUrl(product = {}) {
  if (!isPlainObject(product)) return '';
  const seedData = isPlainObject(product.seed_data) ? product.seed_data : {};
  const snapshot = isPlainObject(seedData.snapshot) ? seedData.snapshot : {};
  const externalSeed = isPlainObject(product.external_seed) ? product.external_seed : {};
  const externalSnapshot = isPlainObject(externalSeed.snapshot) ? externalSeed.snapshot : {};
  return firstCatalogPayloadString(
    product.image_url,
    product.imageUrl,
    product.image,
    product.thumbnail_url,
    product.thumbnailUrl,
    product.images,
    product.image_urls,
    product.gallery_images,
    externalSeed.image_url,
    externalSeed.imageUrl,
    externalSeed.images,
    externalSeed.image_urls,
    externalSnapshot.image_url,
    externalSnapshot.images,
    externalSnapshot.image_urls,
    seedData.image_url,
    seedData.imageUrl,
    seedData.images,
    seedData.image_urls,
    snapshot.image_url,
    snapshot.images,
    snapshot.image_urls,
  ) || '';
}

function firstSearchProductCategoryPath(product = {}) {
  if (!isPlainObject(product)) return '';
  return firstNonEmptyString(
    product.catalog_category_path,
    Array.isArray(product.category_path) ? product.category_path.join('/') : product.category_path,
    product.categoryPath,
    product.seed_data?.catalog_category_path,
    product.seed_data?.category_path,
    product.external_seed?.catalog_category_path,
    product.external_seed?.category_path,
  ) || '';
}

function getSearchProductPriceAmount(product = {}) {
  if (!isPlainObject(product)) return null;
  const candidates = [
    product.price_amount,
    product.priceAmount,
    product.current_price,
    product.currentPrice,
    product.price,
    product.price?.amount,
    product.price?.value,
    product.price?.current?.amount,
    product.best_deal?.price,
    product.bestDeal?.price,
  ];
  if (Array.isArray(product.offers)) {
    for (const offer of product.offers) {
      candidates.push(offer?.price, offer?.price?.amount, offer?.price?.current?.amount);
    }
  }
  if (Array.isArray(product.variants)) {
    for (const variant of product.variants) {
      candidates.push(variant?.price, variant?.price?.amount, variant?.price?.current?.amount);
    }
  }
  for (const candidate of candidates) {
    const amount = Number(candidate);
    if (Number.isFinite(amount)) return amount;
  }
  return null;
}

function hasExplicitUnknownPrice(product = {}) {
  if (!isPlainObject(product)) return false;
  const label = firstNonEmptyString(product.price_label, product.priceLabel);
  return Boolean(
    product.price_unknown === true ||
      product.priceUnknown === true ||
      product.price?.unknown === true ||
      (label && /price\s+(?:unknown|unavailable)|暂不可得|未知/i.test(label)),
  );
}

function hasExplicitFreePrice(product = {}) {
  if (!isPlainObject(product)) return false;
  const text = normalizeSearchTextForMatch(
    [
      product.price_label,
      product.priceLabel,
      product.title,
      product.name,
      product.product_type,
      product.category,
    ].filter(Boolean).join(' '),
  );
  return Boolean(
    product.price_is_free === true ||
      product.is_free === true ||
      product.free_sample === true ||
      /\b(free|sample|gift\s+with\s+purchase)\b/.test(text),
  );
}

function isSearchProductPdpResolvable(product = {}) {
  if (!isPlainObject(product)) return false;
  const ref = isPlainObject(product.canonical_product_ref) ? product.canonical_product_ref : {};
  const hasProductRef = Boolean(
    firstNonEmptyString(product.product_id, product.id, ref.product_id, product.pivota_signature_id),
  );
  const hasMerchantRef = Boolean(firstNonEmptyString(product.merchant_id, ref.merchant_id));
  const hasUrl = Boolean(
    firstNonEmptyString(
      product.pivota_canonical_url,
      product.canonical_url,
      product.destination_url,
      product.merchant_canonical_url,
      product.url,
    ),
  );
  return hasProductRef && (hasMerchantRef || hasUrl);
}

function ensureSearchProductPdpOpen(product = {}) {
  if (!isPlainObject(product)) return product;
  if (isPlainObject(product.pdp_open)) return product;

  const ref = isPlainObject(product.canonical_product_ref) ? product.canonical_product_ref : {};
  const signatureId = firstNonEmptyString(
    ref.pivota_signature_id,
    product.pivota_signature_id,
    String(product.product_id || '').startsWith('sig_') ? product.product_id : '',
    String(product.id || '').startsWith('sig_') ? product.id : '',
  );
  const productId = firstNonEmptyString(
    ref.product_id,
    product.source_product_id,
    product.platform_product_id,
    product.external_product_id,
    product.external_seed_product_id,
    product.product_id,
    product.id,
    signatureId,
  );
  const merchantId = firstNonEmptyString(
    ref.merchant_id,
    product.merchant_id,
    product.merchantId,
    String(product.platform || product.source || '').includes('external_seed') ? EXTERNAL_SEED_MERCHANT_ID : '',
  );
  if (!productId || !merchantId) return product;

  const platform = firstNonEmptyString(
    ref.platform,
    product.platform,
    String(product.source || '').includes('external_seed') ? 'external_seed' : '',
    merchantId === EXTERNAL_SEED_MERCHANT_ID ? 'external_seed' : '',
  );
  const productKey = firstNonEmptyString(ref.product_key, product.product_key, product.catalog_product_key);
  const productRef = {
    merchant_id: merchantId,
    product_id: productId,
    ...(platform ? { platform } : {}),
    ...(productKey ? { product_key: productKey } : {}),
    ...(signatureId ? { pivota_signature_id: signatureId } : {}),
  };
  const subjectId = signatureId || firstNonEmptyString(product.pivota_signature_id, product.product_id, product.id, productId);
  const next = {
    ...product,
    canonical_product_ref: isPlainObject(product.canonical_product_ref) ? product.canonical_product_ref : productRef,
    pdp_open: {
      path: 'internal',
      product_ref: productRef,
      canonical_product_ref: productRef,
      subject: {
        type: 'product_group',
        id: subjectId,
      },
    },
  };
  if (signatureId && !next.pivota_signature_id) next.pivota_signature_id = signatureId;
  if (signatureId && !next.pivota_canonical_url) {
    next.pivota_canonical_url = buildPublicProductUrl(
      resolvePublicProductIdForEmit(
        signatureId,
        firstNonEmptyString(product.canonical_entity_id, product.canonicalEntityId),
      ),
    );
  }
  return next;
}

function getSearchProductServingEligibility(product = {}, options = {}) {
  const reasons = [];
  if (!isPlainObject(product)) {
    return { eligible: false, reasons: ['invalid_product'] };
  }

  const imageUrl = firstSearchProductImageUrl(product);
  if (!imageUrl) reasons.push('missing_image');

  const categoryPath = firstSearchProductCategoryPath(product).toLowerCase().replace(/^\/+|\/+$/g, '');
  const categoryKind = String(product.category_kind || product.categoryKind || '').trim().toLowerCase();
  const profile = String(product.pdp_schema_profile || '').trim().toLowerCase();
  const category = String(firstNonEmptyString(product.category, product.product_type) || '')
    .trim()
    .toLowerCase();
  const beautyCategory =
    categoryPath === 'beauty' ||
    categoryPath.startsWith('beauty/') ||
    categoryKind === 'beauty' ||
    profile === 'beauty_formula' ||
    hasBeautyCatalogProductSignal(buildFallbackCandidateText(product));
  if (options.requireBeauty === true && !beautyCategory) reasons.push('non_beauty_product');
  if (options.requireBeauty === true && productLooksLikeNonBeautyMerchandise(product)) {
    reasons.push('non_beauty_merchandise');
  }
  if (!beautyCategory && SEARCH_CARD_GENERIC_CATEGORY_LABELS.has(category)) {
    reasons.push('generic_category');
  }
  if (hasOfferProductTransactionHold(product)) {
    reasons.push('source_unavailable_or_non_merchandise');
  }

  const amount = getSearchProductPriceAmount(product);
  if (amount == null) {
    if (!hasExplicitUnknownPrice(product)) reasons.push('missing_price');
    // Narrower companion to `missing_price`, stamped by the canonical-chain
    // mapper when the product's own catalog_offers row carried no usable
    // price. `missing_price` says the served card has no amount; THIS says the
    // primary route produced nothing and no guess was substituted. Kept as a
    // separate reason so the residue left by deleting the price fallback is
    // countable and sortable rather than blended into the generic bucket.
    if (product.price_absent_reason === CANONICAL_NO_OFFER_DERIVED_PRICE_REASON) {
      reasons.push(CANONICAL_NO_OFFER_DERIVED_PRICE_REASON);
    }
  } else if (amount <= 0 && !hasExplicitFreePrice(product)) {
    reasons.push('non_positive_price');
  }

  if (!isSearchProductPdpResolvable(product)) reasons.push('unresolved_pdp_ref');

  return {
    eligible: reasons.length === 0,
    reasons,
    image_url: imageUrl || null,
    price_amount: amount,
    category_path: categoryPath || null,
  };
}

function searchProductMatchesBeautyBrandBrowse(product = {}, brandBrowse = null, candidateText = '') {
  if (!brandBrowse || brandBrowse.contract !== 'brand_browse') return true;
  const requestedBrand = normalizeSearchTextForMatch(brandBrowse.brand || '');
  const requestedAlias = normalizeSearchTextForMatch(brandBrowse.alias || '');
  if (!requestedBrand && !requestedAlias) return true;
  const productBrand = normalizeSearchTextForMatch(
    firstNonEmptyString(product?.brand, product?.vendor, product?.merchant_name),
  );
  const text = String(candidateText || buildFallbackCandidateText(product) || '');
  const matches = (needle) => Boolean(
    needle &&
      (
        (productBrand && (productBrand.includes(needle) || needle.includes(productBrand))) ||
        text.includes(needle)
      )
  );
  return matches(requestedBrand) || matches(requestedAlias);
}

function filterSearchServingEligibleProducts(products = [], options = {}) {
  const eligible = [];
  const rejected = [];
  for (const product of Array.isArray(products) ? products : []) {
    const gate = getSearchProductServingEligibility(product, options);
    if (gate.eligible) {
      eligible.push(product);
    } else {
      rejected.push({
        product_id: firstNonEmptyString(product?.product_id, product?.id, product?.pivota_signature_id) || null,
        title: firstNonEmptyString(product?.title, product?.name) || null,
        source: firstNonEmptyString(product?.source, product?.search_recall_source, product?.catalog_source) || null,
        reasons: gate.reasons,
      });
    }
  }
  return {
    products: eligible,
    rejected,
    rejected_count: rejected.length,
    input_count: Array.isArray(products) ? products.length : 0,
  };
}

function isBeautySearchQualityContractApplied(contract = null) {
  return Boolean(
    SEARCH_QUALITY_CONTRACT_V1_ENABLED &&
      contract &&
      contract.contract_version === SEARCH_QUALITY_CONTRACT_VERSION &&
      contract.target_domain === 'beauty' &&
      contract.query_class !== 'ambiguous_or_non_shopping'
  );
}

function isSearchQualityContractSafeEmptyContract(contract = null) {
  return Boolean(
    SEARCH_QUALITY_CONTRACT_V1_ENABLED &&
      contract &&
      contract.contract_version === SEARCH_QUALITY_CONTRACT_VERSION &&
      (
        String(contract.target_domain || '').trim().toLowerCase() !== 'beauty' ||
        String(contract.query_class || '').trim().toLowerCase() === 'ambiguous_or_non_shopping'
      )
  );
}

function isSearchQualityContractSafeEmptyResponse(response = null) {
  if (!response || typeof response !== 'object' || Array.isArray(response)) return false;
  const metadata = response.metadata && typeof response.metadata === 'object' ? response.metadata : {};
  const decision = metadata.search_decision && typeof metadata.search_decision === 'object'
    ? metadata.search_decision
    : {};
  return (
    String(metadata.query_source || '') === 'search_quality_contract_v1_safe_empty' ||
    String(decision.decision_lock_reason || '') === 'search_quality_contract_ambiguous_or_non_shopping'
  );
}

function shouldShortCircuitInvokeSearchQualitySafeEmpty({
  contract = null,
  payload = null,
  metadata = null,
  queryClass = null,
} = {}) {
  if (!isSearchQualityContractSafeEmptyContract(contract)) return false;
  const search =
    payload?.search && typeof payload.search === 'object' && !Array.isArray(payload.search)
      ? payload.search
      : payload && typeof payload === 'object' && !Array.isArray(payload)
        ? payload
        : {};
  if (hasStrictInvokeCatalogSurface(search, metadata)) return true;

  const normalizedQueryClass = String(queryClass || '').trim().toLowerCase();
  if (normalizedQueryClass === 'non_shopping') return true;

  const understanding =
    contract?.query_understanding &&
    typeof contract.query_understanding === 'object' &&
    !Array.isArray(contract.query_understanding)
      ? contract.query_understanding
      : null;
  if (understanding?.hard_negatives?.non_merchandise_query === true) return true;
  const riskFlags = Array.isArray(understanding?.risk_flags) ? understanding.risk_flags : [];
  return riskFlags.map((flag) => String(flag || '').trim()).includes('non_merchandise_query_guard');
}

function projectSearchQualityContractForMetadata(contract = null) {
  if (!contract || typeof contract !== 'object') return null;
  return {
    contract_version: contract.contract_version || SEARCH_QUALITY_CONTRACT_VERSION,
    target_domain: contract.target_domain || null,
    query_class: contract.query_class || null,
    effective_query: contract.effective_query || null,
    clarification_allowed: Boolean(contract.clarification_allowed),
    hard_constraints: contract.hard_constraints || {},
    soft_preferences: contract.soft_preferences || {},
  };
}

function buildCanonicalBrandFilterForBeautyRecall(contract = null, brandBrowse = null) {
  const out = [];
  const hardBrand =
    isBeautySearchQualityContractApplied(contract) &&
    contract.hard_constraints &&
    typeof contract.hard_constraints === 'object'
      ? contract.hard_constraints.brand
      : null;
  if (hardBrand && typeof hardBrand === 'object') out.push(hardBrand);
  if (brandBrowse && brandBrowse.contract === 'brand_browse') {
    out.push({
      canonical: brandBrowse.brand || null,
      alias: brandBrowse.alias || null,
      brand_key: brandBrowse.brand_key || null,
    });
  }
  return out.length > 0 ? out : null;
}

function buildCanonicalQueryTextForBeautyBrandRecall(queryText = '', brandBrowse = null, categoryPathPrefix = '') {
  const original = String(queryText || '').trim();
  if (!original) return '';
  if (!brandBrowse || brandBrowse.contract !== 'brand_browse' || brandBrowse.brand_only !== false) return original;
  if (String(categoryPathPrefix || '').trim()) return original;

  const normalizedOriginal = normalizeSearchTextForMatch(original);
  if (!normalizedOriginal) return original;
  const removalParts = [
    brandBrowse.brand,
    brandBrowse.alias,
    String(brandBrowse.brand || '').replace(/\bbeauty\b/gi, ' '),
  ]
    .map((value) => normalizeSearchTextForMatch(value))
    .filter(Boolean)
    .sort((left, right) => right.length - left.length);
  let remainder = ` ${normalizedOriginal} `;
  for (const part of removalParts) {
    const escaped = part.replace(/[.*+?^${}()|[\]\\]/g, '\\$&').replace(/\s+/g, '\\s+');
    remainder = remainder.replace(new RegExp(`\\s${escaped}\\s`, 'g'), ' ');
  }
  remainder = remainder
    .replace(/\b(beauty|cosmetics?|products?|product|shop|buy|show|find|recommend|recommendations?|best)\b/g, ' ')
    .replace(/\s+/g, ' ')
    .trim();
  return remainder || original;
}

function normalizeSearchQualityBrandNeedle(value) {
  return normalizeSearchTextForMatch(value).replace(/\bbeauty\b/g, ' ').replace(/\s+/g, ' ').trim();
}

function productMatchesSearchQualityBrand(product = {}, brand = null, candidateText = '') {
  const canonical = normalizeSearchQualityBrandNeedle(brand?.canonical || brand?.brand || '');
  const alias = normalizeSearchQualityBrandNeedle(brand?.alias || '');
  if (!canonical && !alias) return true;
  const productBrand = normalizeSearchQualityBrandNeedle(
    firstNonEmptyString(product?.brand, product?.vendor, product?.merchant_name),
  );
  const text = normalizeSearchTextForMatch(candidateText || buildFallbackCandidateText(product));
  const compactText = text.replace(/\s+/g, '');
  const matches = (needle) => {
    if (!needle) return false;
    if (productBrand) return productBrand.includes(needle) || needle.includes(productBrand);
    const compactNeedle = needle.replace(/\s+/g, '');
    return Boolean(
      text.includes(needle) ||
        (compactNeedle && compactText.includes(compactNeedle))
    );
  };
  return matches(canonical) || matches(alias);
}

const SEARCH_EXACT_PRODUCT_ANCHOR_STOP_WORDS = new Set([
  'beauty',
  'cosmetic',
  'cosmetics',
  'product',
  'products',
  'shop',
  'buy',
  'show',
  'find',
  'recommend',
  'recommendation',
  'recommendations',
]);

function productMatchesSearchQualityExactAnchor(product = {}, exactProductAnchor = '', candidateText = '') {
  const anchor = normalizeSearchTextForMatch(exactProductAnchor);
  if (!anchor) return true;
  const tokens = tokenizeSearchTextForMatch(anchor)
    .filter((token) => token.length >= 2)
    .filter((token) => !SEARCH_EXACT_PRODUCT_ANCHOR_STOP_WORDS.has(token));
  if (!tokens.length) return true;
  const text = normalizeSearchTextForMatch(candidateText || buildFallbackCandidateText(product));
  if (!text) return false;
  const matched = tokens.filter((token) => text.includes(token));
  if (tokens.length <= 4) return matched.length === tokens.length;
  return matched.length >= 4 && matched.length / tokens.length >= 0.8;
}

function productLooksLikeFragranceMerchandise(product = {}) {
  const categoryPath = firstSearchProductCategoryPath(product).toLowerCase();
  if (categoryPath.startsWith('beauty/fragrance')) return true;
  const text = buildBeautyProductPrimarySurfaceText(product);
  if (!text) return false;
  if (/\b(fragrance[-\s]?free|unscented|no\s+fragrance|without\s+fragrance)\b/i.test(text)) return false;
  return /\b(perfume|parfum|eau\s+de|cologne|body\s*mist|fragrance)\b/i.test(text);
}

function productLooksLikeNonBeautyMerchandise(product = {}) {
  const text = buildBeautyProductPrimarySurfaceText(product);
  if (!text) return false;
  if (/\b(?:shipping|delivery|route|package|order)\s+protection\b/i.test(text)) return true;
  if (/\b(?:e[-\s]?gift\s*card|digital\s+gift\s*card|gift\s*card)\b/i.test(text)) return true;
  if (
    /\b(?:dog|cat|puppy|kitten|pet|pooch)\b(?:\s+\w+){0,5}\s+\b(?:toy|toys|collar|leash|bowl|bandana|bed)\b/i.test(text) ||
    /\b(?:toy|toys|collar|leash|bowl|bandana|bed)\b(?:\s+\w+){0,5}\s+\b(?:dog|cat|puppy|kitten|pet|pooch)\b/i.test(text)
  ) {
    return true;
  }
  return /\b(?:tote\s*bag|canvas\s*bag|phone\s*case|key\s*chain|keychain|stickers?|enamel\s*pins?|hoodie|sweatshirt|t[-\s]?shirt|tee\s*shirt|baseball\s*cap|water\s*bottle|mug)\b/i.test(text);
}

function getSearchQualityContractHardConstraintResult(product = {}, contract = null, queryText = '') {
  if (!isBeautySearchQualityContractApplied(contract)) return { eligible: true, reasons: [] };
  const reasons = [];
  const hard = contract.hard_constraints || {};
  const candidateText = buildFallbackCandidateText(product);
  const queryClass = String(contract.query_class || '').trim().toLowerCase();

  if (hasOfferProductTransactionHold(product)) reasons.push('source_unavailable_or_non_merchandise');
  if (productLooksLikeNonBeautyMerchandise(product)) reasons.push('non_beauty_merchandise');
  if (
    hard.exact_product_anchor &&
    !productMatchesSearchQualityExactAnchor(product, hard.exact_product_anchor, candidateText)
  ) {
    reasons.push('exact_product_mismatch');
  }

  if (
    ['brand_browse', 'brand_category', 'exact_product'].includes(queryClass) &&
    hard.brand &&
    !productMatchesSearchQualityBrand(product, hard.brand, candidateText)
  ) {
    reasons.push('brand_mismatch');
  }

  const categoryPathPrefix = String(hard.category_path_prefix || '').trim();
  if (categoryPathPrefix && ['brand_category', 'category_browse', 'need_solution', 'constraint_search', 'exact_product'].includes(queryClass)) {
    const existingCategoryPath = firstSearchProductCategoryPath(product).toLowerCase().replace(/^\/+|\/+$/g, '');
    const pathMatches = beautyProductMatchesCategoryPathPrefix(product, categoryPathPrefix);
    const textMatches = beautyProductMatchesCategoryPathQuery(
      product,
      queryText || contract.effective_query,
      categoryPathPrefix,
    );
    if (existingCategoryPath) {
      if (!pathMatches) reasons.push('category_mismatch');
    } else if (!textMatches) {
      reasons.push('category_mismatch');
    }
  }

  if (hard.strict_lipstick === true && !beautyProductMatchesStrictLipstickIntent(product)) {
    reasons.push('strict_lipstick_mismatch');
  }

  if (hard.fragrance_free_skincare === true && productLooksLikeFragranceMerchandise(product)) {
    reasons.push('fragrance_product_for_fragrance_free_query');
  }

  return {
    eligible: reasons.length === 0,
    reasons,
  };
}

function applySearchQualityContractResponseHints(product = {}, contract = null, queryText = '') {
  if (!isPlainObject(product) || !isBeautySearchQualityContractApplied(contract)) return product;
  const hard = contract.hard_constraints || {};
  const categoryPathPrefix = String(hard.category_path_prefix || '').trim();
  if (!categoryPathPrefix || firstSearchProductCategoryPath(product)) return product;
  const gate = getSearchQualityContractHardConstraintResult(product, contract, queryText || contract.effective_query);
  if (!gate.eligible) return product;
  const inferredPath = categoryPathPrefix.replace(/^\/+|\/+$/g, '');
  if (!inferredPath) return product;
  const next = {
    ...product,
    catalog_category_path: inferredPath,
    category_path: inferredPath,
  };
  if (!firstNonEmptyString(next.category, next.product_type)) {
    next.category = inferredPath.split('/').filter(Boolean).slice(-1)[0] || 'Beauty';
    next.product_type = next.category;
  }
  return next;
}

function scoreBeautySearchQualityContract({ product, contract = null, queryText = '', baseScore = 0 } = {}) {
  if (!isBeautySearchQualityContractApplied(contract)) return 0;
  const hard = contract.hard_constraints || {};
  const soft = contract.soft_preferences || {};
  const candidateText = buildFallbackCandidateText(product);
  const primaryText = buildBeautyProductPrimarySurfaceText(product);
  let score = 0;

  if (String(product?.source || product?.search_recall_source || product?.catalog_source || '') === 'canonical_chain') {
    score += 42;
  }
  if (productMatchesSearchQualityBrand(product, hard.brand, candidateText)) score += hard.brand ? 34 : 0;
  if (hard.exact_product_anchor) {
    if (productMatchesSearchQualityExactAnchor(product, hard.exact_product_anchor, candidateText)) score += 120;
    else score -= 160;
  }
  if (hard.category_path_prefix && beautyProductMatchesCategoryPathPrefix(product, hard.category_path_prefix)) {
    score += 72;
  } else if (hard.category_path_prefix && beautyProductMatchesCategoryPathQuery(product, queryText, hard.category_path_prefix)) {
    score += 34;
  }

  const ingredients = Array.isArray(soft.ingredient_tokens) ? soft.ingredient_tokens : [];
  for (const token of ingredients) {
    const pattern = String(token || '').replace(/_/g, '[\\s-]?');
    if (pattern && new RegExp(`\\b${pattern}\\b`, 'i').test(candidateText)) score += 16;
  }

  const concerns = Array.isArray(soft.concerns) ? soft.concerns : [];
  if (concerns.includes('acne') && beautyProductHasAcneOilControlEvidence(product, candidateText)) score += 28;
  if (concerns.includes('oil_control') && /\b(oil[-\s]?control|sebum|shine[-\s]?control|non[-\s]?comedogenic|niacinamide|zinc)\b/i.test(candidateText)) score += 18;
  if (concerns.includes('clogged_pores') && /\b(pore|comedogenic|salicylic|bha|azelaic|clarifying)\b/i.test(candidateText)) score += 18;

  const formats = Array.isArray(soft.format) ? soft.format : [];
  if (formats.includes('waterproof') && /\b(waterproof|water\s+resistant)\b/i.test(candidateText)) score += 14;
  if (formats.includes('travel_size') && /\b(mini|travel|travel\s+size|portable)\b/i.test(candidateText)) score += 10;

  const quality = getSearchProductServingEligibility(product, { requireBeauty: true });
  const qualityReasons = new Set(Array.isArray(quality.reasons) ? quality.reasons : []);
  if (quality.eligible) score += 28;
  if (qualityReasons.has('missing_image')) score -= 70;
  if (qualityReasons.has('non_positive_price')) score -= 70;
  if (qualityReasons.has('unresolved_pdp_ref')) score -= 60;
  if (qualityReasons.has('generic_category')) score -= 36;
  if (qualityReasons.has('source_unavailable_or_non_merchandise')) score -= 120;
  if (qualityReasons.has('non_beauty_merchandise')) score -= 120;

  if (/\b(set|bundle|kit|duo|trio|routine|regimen|gift|collector|case|minis?|mystery\s*box)\b/i.test(primaryText)) {
    score -= 22;
  }
  if (/\b(accessory|tool|brush|case|mirror|pouch|bag|delivery\s*protection|shipping\s*protection)\b/i.test(primaryText)) {
    score -= 42;
  }
  if (Number(baseScore) < -50) score -= 10;
  return score;
}

function buildSearchQualityTierCounts(products = [], contract = null, queryText = '') {
  const counts = {
    input_count: Array.isArray(products) ? products.length : 0,
    canonical_chain_count: 0,
    external_seed_count: 0,
    hard_constraint_pass_count: 0,
    hard_constraint_reject_count: 0,
    serving_eligible_count: 0,
    missing_image_count: 0,
    invalid_price_count: 0,
    // Subset of invalid_price_count: dropped specifically because the
    // canonical-chain row's own catalog_offers row carried no usable price and
    // nothing was guessed in its place. Tracks the residue of the price
    // fallback deletion so it can be driven down at the source (the writers
    // that leave unsuppressed offers price-less) instead of hidden.
    no_offer_derived_price_count: 0,
    missing_or_unresolved_pdp_count: 0,
    polluted_or_unavailable_count: 0,
  };
  for (const product of Array.isArray(products) ? products : []) {
    const source = String(product?.source || product?.search_recall_source || product?.catalog_source || '').trim();
    if (source === 'canonical_chain') counts.canonical_chain_count += 1;
    else counts.external_seed_count += 1;

    const hardGate = getSearchQualityContractHardConstraintResult(product, contract, queryText);
    if (hardGate.eligible) counts.hard_constraint_pass_count += 1;
    else counts.hard_constraint_reject_count += 1;

    const serving = getSearchProductServingEligibility(product, { requireBeauty: true });
    const reasons = new Set(Array.isArray(serving.reasons) ? serving.reasons : []);
    if (serving.eligible) counts.serving_eligible_count += 1;
    if (reasons.has('missing_image')) counts.missing_image_count += 1;
    if (reasons.has('non_positive_price')) counts.invalid_price_count += 1;
    if (reasons.has('missing_price')) counts.invalid_price_count += 1;
    if (reasons.has(CANONICAL_NO_OFFER_DERIVED_PRICE_REASON)) counts.no_offer_derived_price_count += 1;
    if (reasons.has('unresolved_pdp_ref')) counts.missing_or_unresolved_pdp_count += 1;
    if (
      reasons.has('generic_category') ||
      reasons.has('non_beauty_merchandise') ||
      reasons.has('source_unavailable_or_non_merchandise') ||
      hardGate.reasons.includes('non_beauty_merchandise') ||
      hardGate.reasons.includes('source_unavailable_or_non_merchandise')
    ) {
      counts.polluted_or_unavailable_count += 1;
    }
  }
  return counts;
}

function relaxSearchQualityContractForMultiFamilyBeautyIntent(contract = null, beautyIntent = null) {
  if (!isBeautySearchQualityContractApplied(contract)) return contract;
  const families = Array.isArray(beautyIntent?.families)
    ? beautyIntent.families.map((value) => String(value || '').trim()).filter(Boolean)
    : [];
  if (families.length <= 1) return contract;
  const hard = contract.hard_constraints && typeof contract.hard_constraints === 'object'
    ? contract.hard_constraints
    : {};
  if (!hard.category_path_prefix) return contract;
  return {
    ...contract,
    hard_constraints: {
      ...hard,
      category_path_prefix: null,
    },
    category_path_prefix_relaxed_for_multi_family: true,
  };
}

function summarizeSearchQualityFailureReasons({ scoredRejected = [], servingRejected = [] } = {}) {
  const counts = {};
  const add = (reason) => {
    const key = String(reason || '').trim();
    if (!key) return;
    counts[key] = (counts[key] || 0) + 1;
  };
  for (const row of Array.isArray(scoredRejected) ? scoredRejected : []) {
    for (const reason of Array.isArray(row?.reasons) ? row.reasons : []) add(reason);
  }
  for (const row of Array.isArray(servingRejected) ? servingRejected : []) {
    for (const reason of Array.isArray(row?.reasons) ? row.reasons : []) add(reason);
  }
  return counts;
}

function resolveCanonicalCategoryPathPrefixForQuery(queryText) {
  const beautyPrefix = resolveBeautyCategoryPathPrefixForQuery(queryText);
  if (beautyPrefix) return beautyPrefix;

  const text = String(queryText || '').trim();
  const normalized = normalizeSearchTextForMatch(text);
  if (!normalized) return '';

  if (
    /\b(e\s*reader|ereader|e\s*book\s*reader|ebook\s*reader|kindle|kobo|boox)\b/i.test(normalized) ||
    /电子阅读器|電子閱讀器|电纸书|電紙書|电子书阅读器|電子書閱讀器/.test(text)
  ) {
    return 'electronics/reading/';
  }

  if (
    /\b(earbuds?|ear\s*buds?|earphones?|headphones?|airpods?|galaxy\s*buds?|studio\s*buds?|bluetooth\s*(?:earbuds?|headphones?|earphones?)|wireless\s*(?:earbuds?|headphones?|earphones?)|noise\s*cancell(?:ing|ation)|anc\s*headphones?)\b/i.test(normalized) ||
    /蓝牙耳机|藍牙耳機|无线耳机|無線耳機|耳机|耳機|降噪/.test(text)
  ) {
    return 'electronics/audio/';
  }

  // Camera drones (electronics_drone sub-vertical — HoverAir pilot). Without
  // this branch a drone query resolves '' → the search-quality contract
  // safe-empties it, so served drone canonicals could never surface through
  // find_products_multi (the exact failure mode the electronics pilot warned
  // about below). Prefix matches catalog_products.category_path
  // 'electronics/drones/camera-drone'. No bare "camera" — cameras are not
  // drones; "hoverair" is a category-defining product line like "airpods".
  if (
    /\b(drones?|quadcopters?|fpv\s*drones?|camera\s*drones?|self\s*flying\s*(?:camera|drone)|flying\s*camera|follow\s*me\s*drones?|hover\s*air|hoverair|uav)\b/i.test(normalized) ||
    /无人机|無人機|四轴飞行器|四軸飛行器|航拍机|航拍機/.test(text)
  ) {
    return 'electronics/drones/';
  }

  return '';
}

function isNonBeautyCanonicalCategoryPathPrefix(categoryPathPrefix) {
  const normalized = String(categoryPathPrefix || '').trim().toLowerCase();
  return Boolean(normalized && !normalized.startsWith('beauty/'));
}

function buildCanonicalChainRecallSearchResponse({
  search = {},
  products = [],
  telemetry = {},
  querySource = 'canonical_chain_catalog',
} = {}) {
  const safeProducts = Array.isArray(products) ? products.filter(Boolean) : [];
  const safePage = Math.max(1, Math.floor(Number(search.page || 1) || 1));
  const requestedLimit = Math.floor(Number(search.limit || search.page_size || 20) || 20);
  const safeLimit = Math.max(1, Math.min(SEARCH_LIMIT_MAX, requestedLimit));
  const returnedCount = safeProducts.length;
  const canonicalRawCount = Math.max(0, Number(telemetry?.canonical_raw_count || 0) || 0);
  const canonicalProductCount = Math.max(
    returnedCount,
    Number(telemetry?.canonical_product_count || 0) || 0,
  );
  const canonicalDurationMs = Math.max(0, Number(telemetry?.canonical_duration_ms || 0) || 0);
  const canonicalCategoryPathPrefix = telemetry?.canonical_category_path_prefix || null;
  const queryUnderstanding =
    search?.query_understanding && typeof search.query_understanding === 'object'
      ? search.query_understanding
      : null;

  return {
    status: 'success',
    success: true,
    products: safeProducts,
    total: returnedCount,
    page: safePage,
    page_size: Math.min(safeLimit, returnedCount),
    reply: null,
    metadata: {
      ...buildInvokeSearchRailMetadata('authoritative_shopping'),
      query_source: querySource,
      fetched_at: new Date().toISOString(),
      canonical_path_executed: true,
      canonical_raw_count: canonicalRawCount,
      canonical_product_count: canonicalProductCount,
      canonical_returned_count: returnedCount,
      canonical_dedupe_count: Math.max(0, Number(telemetry?.canonical_dedupe_count || 0) || 0),
      canonical_category_path_prefix: canonicalCategoryPathPrefix,
      canonical_duration_ms: canonicalDurationMs,
      ...(queryUnderstanding
        ? {
            query_understanding: queryUnderstanding,
            query_understanding_executed: true,
            query_understanding_decision: queryUnderstanding.decision || null,
          }
        : {}),
      source_breakdown: {
        internal_count: 0,
        external_seed_count: 0,
        canonical_chain_count: returnedCount,
        canonical_chain_candidate_count: canonicalProductCount,
        stale_cache_used: false,
        strategy_applied: querySource,
      },
      route_health: {
        fallback_triggered: false,
        fallback_reason: null,
        primary_path_used: 'canonical_chain_catalog',
        canonical_path_executed: true,
        canonical_raw_count: canonicalRawCount,
        canonical_product_count: canonicalProductCount,
        canonical_returned_count: returnedCount,
        canonical_dedupe_count: Math.max(0, Number(telemetry?.canonical_dedupe_count || 0) || 0),
        canonical_duration_ms: canonicalDurationMs,
        ...(queryUnderstanding
          ? {
              query_understanding_executed: true,
              query_understanding_decision: queryUnderstanding.decision || null,
            }
          : {}),
      },
      search_trace: {
        fallback_reason: null,
        primary_path_used: 'canonical_chain_catalog',
      },
      search_decision: {
        final_decision: returnedCount > 0 ? 'products_returned' : 'strict_empty',
        fallback_reason: null,
        primary_path_used: 'canonical_chain_catalog',
        decision_authority: querySource,
        decision_locked: true,
        decision_lock_reason: 'canonical_chain_mainline',
      },
      proxy_search_fallback: {
        applied: false,
        reason: null,
      },
      contract_bridge: {
        legacy_fallback: false,
      },
    },
  };
}

async function fetchCanonicalChainRecallForFindProductsMulti({ search = {} } = {}) {
  if (!PIVOT_BEAUTY_DIRECT_INDEXED_RECALL_ENABLED) return null;
  if (!process.env.DATABASE_URL) return null;
  const searchQualityContract =
    SEARCH_QUALITY_CONTRACT_V1_ENABLED &&
    search?.search_quality_contract &&
    typeof search.search_quality_contract === 'object' &&
    !Array.isArray(search.search_quality_contract)
      ? search.search_quality_contract
      : null;
  const searchQualityContractApplied = isBeautySearchQualityContractApplied(searchQualityContract);
  // The search-quality contract is beauty-centric: any non-beauty query is
  // classified target_domain:'other' / query_class:'ambiguous_or_non_shopping',
  // which isSearchQualityContractSafeEmptyContract() treats as safe-empty and
  // returns products:[] before touching the DB. That gate must NOT fire for the
  // non-beauty canonical direct lane (electronics vertical pilot) — otherwise the
  // electronics canonical catalog can never serve through find_products_multi and
  // such queries fall through to slow upstream search + clarify. Bypass safe-empty
  // when the query resolves to a non-beauty canonical category prefix (today:
  // electronics/audio/, electronics/reading/); beauty prefixes always win inside
  // resolveCanonicalCategoryPathPrefixForQuery(), so beauty behaviour is unchanged.
  const canonicalRecallQueryTextForSafeEmpty =
    (searchQualityContractApplied && searchQualityContract?.effective_query) ||
    extractSearchQueryText(search);
  const hasNonBeautyCanonicalPrefixForRecall = isNonBeautyCanonicalCategoryPathPrefix(
    resolveCanonicalCategoryPathPrefixForQuery(canonicalRecallQueryTextForSafeEmpty),
  );
  if (
    !hasNonBeautyCanonicalPrefixForRecall &&
    isSearchQualityContractSafeEmptyContract(searchQualityContract)
  ) {
    return {
      products: [],
      telemetry: {
        canonical_path_executed: false,
        canonical_raw_count: 0,
        canonical_product_count: 0,
        canonical_category_path_prefix: null,
        canonical_brand_filter_applied: false,
        canonical_duration_ms: 0,
        query_text: searchQualityContract.effective_query || extractSearchQueryText(search),
        requested_limit: Math.max(
          1,
          Math.min(SEARCH_LIMIT_MAX, Math.floor(Number(search.limit || search.page_size || 20) || 20)),
        ),
        search_quality_contract: searchQualityContract,
        search_quality_contract_safe_empty: true,
      },
    };
  }
  const queryText =
    (searchQualityContractApplied && searchQualityContract?.effective_query) ||
    extractSearchQueryText(search);
  if (!String(queryText || '').trim()) return null;
  const beautyBrandBrowse = resolveBeautyBrandBrowseQuery(queryText);
  const safeLimit = Math.max(
    1,
    Math.min(SEARCH_LIMIT_MAX, Math.floor(Number(search.limit || search.page_size || 20) || 20)),
  );
  const canonicalLimit = searchQualityContractApplied
    ? Math.max(18, Math.min(48, safeLimit * 4))
    : Math.max(12, Math.min(32, safeLimit * 2));
  const canonicalCategoryPathPrefix = searchQualityContractApplied
    ? (searchQualityContract?.hard_constraints?.category_path_prefix || null)
    : (resolveCanonicalCategoryPathPrefixForQuery(queryText) || null);
  const canonicalBrandFilter = buildCanonicalBrandFilterForBeautyRecall(
    searchQualityContractApplied ? searchQualityContract : null,
    beautyBrandBrowse.matched ? beautyBrandBrowse : null,
  );
  const canonicalQueryText = buildCanonicalQueryTextForBeautyBrandRecall(
    queryText,
    beautyBrandBrowse.matched ? beautyBrandBrowse : null,
    canonicalCategoryPathPrefix,
  );
  // Market-aware recall: pass the user's market into canonicalCatalogSearch
  // so non-matching Path B rows are filtered. Falls back to env / 'US' to
  // preserve existing behaviour for callers that don't pass market.
  const safeMarket =
    String(search.market || process.env.CREATOR_CATEGORIES_EXTERNAL_SEED_MARKET || 'US')
      .trim()
      .toUpperCase() || 'US';
  const startedAt = Date.now();
  try {
    const rows = await fetchCanonicalChainRows({
      query: canonicalQueryText,
      categoryPathPrefix: canonicalCategoryPathPrefix,
      // Deliberate category-browse: when the prefix resolves, this lane WANTS
      // bucket semantics (the text predicate is dropped — see the helper's
      // contract guard). Post-recall relevance filtering narrows the bucket.
      categoryMode: 'category_browse',
      verticalSearch:
        Boolean(canonicalCategoryPathPrefix && String(canonicalCategoryPathPrefix).startsWith('beauty/')) &&
        hasBeautyIngredientIntentSignal(queryText),
      limit: canonicalLimit,
      // Phase 7d backfill (pivota-backend #399 + #401, 2026-05-09)
      // populated catalog_skus + catalog_offers for all 3,936 Path B
      // mirrored products. Pre-7d this flag was false because the
      // chain didn't exist for external_seed rows; surfacing it
      // would return NULL price columns. With the chain now complete,
      // JOIN them so canonical_chain response items carry price +
      // currency + availability — without this, the chat shows $0.
      includeSkuOffers: true,
      // Market-aware filtering — exclude Path B rows whose source seed
      // has a non-matching market. Mirrors the filter on
      // queryBeautyExternalSeedRowsFast which already enforces it on
      // the external-seed-direct path. Without parity here, Round Lab
      // (market=KR) products were leaking into US users' canonical_chain
      // results.
      marketId: safeMarket,
      brandFilter: canonicalBrandFilter,
      deps: { query },
    });
    const products = (Array.isArray(rows) ? rows : [])
      .map((row) => buildCanonicalChainMainlineProduct(row))
      .filter(Boolean);
    return {
      products,
      telemetry: {
        canonical_path_executed: true,
        canonical_raw_count: Array.isArray(rows) ? rows.length : 0,
        canonical_product_count: products.length,
        canonical_category_path_prefix: canonicalCategoryPathPrefix,
        canonical_brand_filter_applied: Boolean(canonicalBrandFilter),
        ...(canonicalQueryText !== queryText ? { canonical_recall_query_text: canonicalQueryText } : {}),
        canonical_duration_ms: Math.max(0, Date.now() - startedAt),
        query_text: queryText,
        requested_limit: safeLimit,
        ...(searchQualityContract ? { search_quality_contract: searchQualityContract } : {}),
        beauty_brand_browse: beautyBrandBrowse.matched
          ? {
              contract: beautyBrandBrowse.contract,
              brand: beautyBrandBrowse.brand,
              alias: beautyBrandBrowse.alias,
              brand_only: beautyBrandBrowse.brand_only,
              explicit_category: beautyBrandBrowse.explicit_category,
            }
          : null,
      },
    };
  } catch (err) {
    return {
      products: [],
      telemetry: {
        canonical_path_executed: true,
        canonical_raw_count: 0,
        canonical_product_count: 0,
        canonical_category_path_prefix: canonicalCategoryPathPrefix,
        canonical_brand_filter_applied: Boolean(canonicalBrandFilter),
        ...(canonicalQueryText !== queryText ? { canonical_recall_query_text: canonicalQueryText } : {}),
        canonical_duration_ms: Math.max(0, Date.now() - startedAt),
        canonical_error: String(err?.code || err?.message || err || 'canonical_query_failed').slice(0, 160),
        query_text: queryText,
        requested_limit: safeLimit,
        ...(searchQualityContract ? { search_quality_contract: searchQualityContract } : {}),
        beauty_brand_browse: beautyBrandBrowse.matched
          ? {
              contract: beautyBrandBrowse.contract,
              brand: beautyBrandBrowse.brand,
              alias: beautyBrandBrowse.alias,
              brand_only: beautyBrandBrowse.brand_only,
              explicit_category: beautyBrandBrowse.explicit_category,
            }
          : null,
      },
    };
  }
}

function attachCanonicalChainRecallTelemetry(body, canonicalResult) {
  if (!body || typeof body !== 'object' || Array.isArray(body)) return body;
  const telemetry =
    canonicalResult?.telemetry && typeof canonicalResult.telemetry === 'object'
      ? canonicalResult.telemetry
      : null;
  if (!telemetry?.canonical_path_executed) return body;
  const metadata =
    body.metadata && typeof body.metadata === 'object' && !Array.isArray(body.metadata)
      ? { ...body.metadata }
      : {};
  const routeHealth =
    metadata.route_health && typeof metadata.route_health === 'object' && !Array.isArray(metadata.route_health)
      ? { ...metadata.route_health }
      : {};
  const sourceBreakdown =
    metadata.source_breakdown && typeof metadata.source_breakdown === 'object' && !Array.isArray(metadata.source_breakdown)
      ? { ...metadata.source_breakdown }
      : {};
  const products = Array.isArray(body.products) ? body.products : [];
  const responseCanonicalReturnedCount = products.filter((product) => (
    String(product?.source || product?.search_recall_source || product?.catalog_source || '') === 'canonical_chain'
  )).length;
  const canonicalDedupeCount = Math.max(0, Number(metadata.canonical_dedupe_count || 0) || 0);
  const canonicalRawCount = Math.max(0, Number(telemetry.canonical_raw_count || 0) || 0);
  const canonicalProductCount = Math.max(0, Number(telemetry.canonical_product_count || 0) || 0);
  const canonicalReturnedCount = Math.max(
    responseCanonicalReturnedCount,
    Number(metadata.canonical_returned_count || 0) || 0,
  );
  const canonicalProducts = Array.isArray(canonicalResult?.products)
    ? canonicalResult.products.filter(Boolean)
    : [];
  const canonicalQueryText = firstNonEmptyString(
    telemetry.query_text,
    metadata?.search_trace?.raw_query,
    metadata?.search_trace?.expanded_query,
  ) || '';
  const telemetrySearchQualityContract =
    telemetry.search_quality_contract &&
    typeof telemetry.search_quality_contract === 'object' &&
    !Array.isArray(telemetry.search_quality_contract)
      ? telemetry.search_quality_contract
      : metadata.search_quality_contract &&
          typeof metadata.search_quality_contract === 'object' &&
          !Array.isArray(metadata.search_quality_contract)
        ? metadata.search_quality_contract
        : null;
  const telemetrySearchQualityContractApplied = isBeautySearchQualityContractApplied(
    telemetrySearchQualityContract,
  );
  const beautyBrandBrowse =
    telemetry.beauty_brand_browse && typeof telemetry.beauty_brand_browse === 'object'
      ? telemetry.beauty_brand_browse
      : resolveBeautyBrandBrowseQuery(canonicalQueryText);
  const isBeautyBrandBrowse = Boolean(beautyBrandBrowse?.matched || beautyBrandBrowse?.contract === 'brand_browse');
  const contractMatchedCanonicalProducts = telemetrySearchQualityContractApplied
    ? canonicalProducts.filter((product) =>
        getSearchQualityContractHardConstraintResult(
          product,
          telemetrySearchQualityContract,
          canonicalQueryText,
        ).eligible,
      )
    : null;
  const contractMatchedCurrentProducts = telemetrySearchQualityContractApplied
    ? products.filter((product) =>
        getSearchQualityContractHardConstraintResult(
          product,
          telemetrySearchQualityContract,
          canonicalQueryText,
        ).eligible,
      )
    : null;
  const brandMatchedCanonicalProducts = telemetrySearchQualityContractApplied
    ? contractMatchedCanonicalProducts
    : isBeautyBrandBrowse
      ? canonicalProducts.filter((product) => searchProductMatchesBeautyBrandBrowse(product, beautyBrandBrowse))
      : canonicalProducts;
  const currentBrandMatchedProducts = telemetrySearchQualityContractApplied
    ? contractMatchedCurrentProducts
    : isBeautyBrandBrowse
      ? products.filter((product) => searchProductMatchesBeautyBrandBrowse(product, beautyBrandBrowse))
      : products;
  const canonicalServingGate = filterSearchServingEligibleProducts(brandMatchedCanonicalProducts, {
    queryText: canonicalQueryText,
    requireBeauty: isBeautyBrandBrowse || telemetrySearchQualityContractApplied,
  });
  const currentServingGate = (isBeautyBrandBrowse || telemetrySearchQualityContractApplied)
    ? filterSearchServingEligibleProducts(currentBrandMatchedProducts, {
        queryText: canonicalQueryText,
        requireBeauty: true,
      })
    : null;
  const requestedLimit = Math.max(
    1,
    Math.min(
      SEARCH_LIMIT_MAX,
      Math.floor(
        Number(
          telemetry.requested_limit ||
            metadata.page_size ||
            metadata.limit ||
            body.page_size ||
            body.limit ||
            products.length ||
            20,
        ) || 20,
      ),
    ),
  );
  const brandBrowseMinimum = beautyBrandBrowse?.brand_only === false ? 1 : Math.min(3, requestedLimit);
  const canonicalEligibleProducts = canonicalServingGate.products.slice(0, requestedLimit);
  const shouldApplyCanonicalProducts =
    canonicalEligibleProducts.length > 0 &&
    (
      (
        telemetrySearchQualityContractApplied &&
        SEARCH_QUALITY_CONTRACT_V1_MODE === 'enforce' &&
        SEARCH_SERVING_QUALITY_HOLD_ENABLED &&
        (
          products.length === 0 ||
          (currentServingGate && currentServingGate.products.length < canonicalEligibleProducts.length) ||
          responseCanonicalReturnedCount === 0
        )
      ) ||
      (
        isBeautyBrandBrowse &&
        canonicalEligibleProducts.length >= brandBrowseMinimum &&
        (
          products.length === 0 ||
          (currentServingGate && currentServingGate.products.length < canonicalEligibleProducts.length) ||
          responseCanonicalReturnedCount === 0
        )
      ) ||
      (
        products.length === 0 &&
        isNonBeautyCanonicalCategoryPathPrefix(telemetry.canonical_category_path_prefix)
      )
    );
  const finalProducts = shouldApplyCanonicalProducts ? canonicalEligibleProducts : products;
  const finalCanonicalReturnedCount = shouldApplyCanonicalProducts
    ? canonicalEligibleProducts.length
    : canonicalReturnedCount;
  const searchDecision =
    metadata.search_decision && typeof metadata.search_decision === 'object' && !Array.isArray(metadata.search_decision)
      ? { ...metadata.search_decision }
      : {};
  const proxySearchFallback =
    metadata.proxy_search_fallback && typeof metadata.proxy_search_fallback === 'object' && !Array.isArray(metadata.proxy_search_fallback)
      ? { ...metadata.proxy_search_fallback }
      : {};
  const contractBridge =
    metadata.contract_bridge && typeof metadata.contract_bridge === 'object' && !Array.isArray(metadata.contract_bridge)
      ? { ...metadata.contract_bridge }
      : {};

  return {
    ...body,
    ...(shouldApplyCanonicalProducts
      ? {
          status: 'success',
          success: true,
          products: finalProducts,
          results: Array.isArray(body.results) ? finalProducts : body.results,
          total: Math.max(Number(body.total || 0) || 0, finalProducts.length),
          page_size: finalProducts.length,
          reply: null,
        }
      : {}),
    metadata: {
      ...metadata,
      ...(shouldApplyCanonicalProducts
        ? {
            query_source: 'canonical_chain_catalog',
            strict_empty: false,
            strict_empty_reason: null,
            reply: null,
          }
        : {}),
      canonical_path_executed: true,
      canonical_raw_count: canonicalRawCount,
      canonical_product_count: canonicalProductCount,
      canonical_category_path_prefix: telemetry.canonical_category_path_prefix || null,
      canonical_duration_ms: Math.max(0, Number(telemetry.canonical_duration_ms || 0) || 0),
      canonical_dedupe_count: canonicalDedupeCount,
      canonical_returned_count: finalCanonicalReturnedCount,
      ...(telemetrySearchQualityContract
        ? {
            search_quality_contract: projectSearchQualityContractForMetadata(telemetrySearchQualityContract),
            search_quality_contract_applied: telemetrySearchQualityContractApplied,
            search_quality_contract_mode: SEARCH_QUALITY_CONTRACT_V1_MODE,
            search_quality_failure_reasons: summarizeSearchQualityFailureReasons({
              servingRejected: [
                ...canonicalServingGate.rejected,
                ...(currentServingGate ? currentServingGate.rejected : []),
              ],
            }),
            search_quality_tier_counts: buildSearchQualityTierCounts(
              canonicalProducts,
              telemetrySearchQualityContractApplied ? telemetrySearchQualityContract : null,
              canonicalQueryText,
            ),
          }
        : {}),
      search_card_quality_gate: {
        applied: isBeautyBrandBrowse || telemetrySearchQualityContractApplied,
        mode: telemetrySearchQualityContractApplied
          ? 'beauty_search_quality_contract_v1'
          : isBeautyBrandBrowse
            ? 'beauty_brand_browse'
            : 'telemetry_only',
        canonical_input_count: canonicalServingGate.input_count,
        canonical_eligible_count: canonicalServingGate.products.length,
        canonical_rejected_count: canonicalServingGate.rejected_count,
        current_input_count: products.length,
        current_eligible_count: currentServingGate ? currentServingGate.products.length : null,
        current_rejected_count: currentServingGate ? currentServingGate.rejected_count : null,
      },
      ...(isBeautyBrandBrowse
        ? {
            beauty_brand_browse: {
              contract: 'brand_browse',
              brand: beautyBrandBrowse.brand || null,
              alias: beautyBrandBrowse.alias || null,
              brand_only: beautyBrandBrowse.brand_only === true,
              explicit_category: beautyBrandBrowse.explicit_category === true,
            },
          }
        : {}),
      ...(telemetry.canonical_error ? { canonical_error: telemetry.canonical_error } : {}),
      ...(shouldApplyCanonicalProducts
        ? {
            contract_bridge: {
              ...contractBridge,
              legacy_fallback: false,
            },
            proxy_search_fallback: {
              ...proxySearchFallback,
              applied: false,
              reason: null,
            },
            search_decision: {
              ...searchDecision,
              final_decision: 'products_returned',
              fallback_reason: null,
              primary_path_used: 'canonical_chain_catalog',
              decision_authority: 'canonical_chain_catalog',
              decision_locked: true,
              decision_lock_reason: 'canonical_chain_mainline_after_primary_deadline',
            },
          }
        : {}),
      source_breakdown: {
        ...sourceBreakdown,
        canonical_chain_count: Math.max(
          Number(sourceBreakdown.canonical_chain_count || 0) || 0,
          finalCanonicalReturnedCount,
        ),
        canonical_chain_candidate_count: Math.max(
          Number(sourceBreakdown.canonical_chain_candidate_count || 0) || 0,
          canonicalProductCount,
        ),
        ...(shouldApplyCanonicalProducts
          ? {
              external_seed_count: Math.max(
                0,
                finalProducts.length - finalCanonicalReturnedCount,
              ),
            }
          : {}),
      },
      route_health: {
        ...routeHealth,
        canonical_path_executed: true,
        canonical_raw_count: canonicalRawCount,
        canonical_product_count: canonicalProductCount,
        canonical_dedupe_count: canonicalDedupeCount,
        canonical_returned_count: finalCanonicalReturnedCount,
        canonical_duration_ms: Math.max(0, Number(telemetry.canonical_duration_ms || 0) || 0),
        search_card_quality_gate_applied: isBeautyBrandBrowse || telemetrySearchQualityContractApplied,
        canonical_eligible_count: canonicalServingGate.products.length,
        canonical_rejected_count: canonicalServingGate.rejected_count,
        current_eligible_count: currentServingGate ? currentServingGate.products.length : null,
        current_rejected_count: currentServingGate ? currentServingGate.rejected_count : null,
        ...(shouldApplyCanonicalProducts
          ? {
              fallback_triggered: false,
              fallback_reason: null,
              primary_path_used: 'canonical_chain_catalog',
              final_returned_count: finalProducts.length,
            }
          : {}),
      },
    },
  };
}

// DO NOT put a timeout on this await without splitting the function first. The name says telemetry, but
// attachCanonicalChainRecallTelemetry ALSO applies a strict-empty product rescue: when
// shouldApplyCanonicalProducts is true it replaces body.products/status/total wholesale (see the return
// at the end of that function). Two of its three arms fire precisely when products.length === 0, so
// abandoning the wait would hand a partner an EMPTY result where they previously got products. Its cost
// is real — it is the last await before serialization and fetchCanonicalChainRows is the query family
// this file documents at 5.8-17.2s on prod — but the fix is to make the rescue cheaper or to separate it
// from the diagnostics half, not to race it. The canonical_chain_join stage below measures it.
async function attachCanonicalChainRecallTelemetryFromPromise(body, canonicalPromise) {
  if (!canonicalPromise) return body;
  try {
    const canonicalResult = await canonicalPromise;
    return attachCanonicalChainRecallTelemetry(body, canonicalResult);
  } catch (err) {
    logger.warn(
      { err: err?.message || String(err) },
      'find_products_multi canonical chain telemetry attachment failed',
    );
    return body;
  }
}

function scoreCreatorHumanApparelExternalSeedProduct({
  product,
  normalizedQuery,
  anchorTokens,
  queryTokens,
  requiredCategories,
  brandTerms,
}) {
  const titleText = normalizeSearchTextForMatch(
    [
      product?.title,
      product?.name,
      product?.brand,
      product?.vendor,
      product?.category,
      product?.product_type,
    ]
      .map((value) => String(value || '').trim())
      .filter(Boolean)
      .join(' '),
  );
  const candidateText = buildFallbackCandidateText(product);
  const categoryId = heuristicCategoryForProduct(product);
  const brandMatched =
    brandTerms.length === 0 ? false : brandTerms.some((term) => hasBrandTermMatch(candidateText, term));
  const requiredMatchCount = requiredCategories.filter((requiredCategory) =>
    matchesCreatorHumanApparelRequiredCategory({
      requiredCategory,
      categoryId,
      titleText,
      candidateText,
    }),
  ).length;
  const hasApparelSignal = hasCreatorHumanApparelSignal(candidateText);
  const hasStrongApparelSignal = hasStrongCreatorHumanApparelSignal(candidateText);
  const toyLike = isCreatorHumanApparelToyLike(candidateText, categoryId);
  const petLike = isCreatorHumanApparelPetLike(candidateText, categoryId);
  const beautyLike = isCreatorHumanApparelBeautyLike(candidateText, categoryId);
  const titleExact = normalizedQuery && titleText.includes(normalizedQuery);
  const candidateExact = normalizedQuery && candidateText.includes(normalizedQuery);
  const anchorOverlap = anchorTokens.filter(
    (token) => titleText.includes(token) || candidateText.includes(token),
  ).length;
  const queryOverlap = queryTokens.filter(
    (token) => titleText.includes(token) || candidateText.includes(token),
  ).length;
  const humanCategoryHit = CREATOR_HUMAN_APPAREL_HUMAN_CATEGORY_IDS.has(String(categoryId || ''));

  if (toyLike || petLike) {
    return { product, relevant: false, score: -100, categoryId };
  }
  if (beautyLike && !humanCategoryHit && !hasStrongApparelSignal) {
    return { product, relevant: false, score: -80, categoryId };
  }
  if (brandTerms.length > 0 && !brandMatched) {
    return { product, relevant: false, score: -40, categoryId };
  }
  if (
    requiredCategories.length > 0 &&
    requiredMatchCount === 0 &&
    !humanCategoryHit &&
    !titleExact &&
    !(hasApparelSignal && anchorOverlap >= 2)
  ) {
    return { product, relevant: false, score: -20, categoryId };
  }
  if (!hasApparelSignal && !humanCategoryHit && !titleExact && anchorOverlap === 0) {
    return { product, relevant: false, score: -10, categoryId };
  }

  let score = 0;
  if (titleExact) score += 32;
  if (candidateExact) score += 16;
  score += requiredMatchCount * 18;
  score += anchorOverlap * 7;
  score += queryOverlap * 3;
  if (brandMatched) score += 18;
  if (humanCategoryHit) score += 14;
  if (hasStrongApparelSignal) score += 10;
  else if (hasApparelSignal) score += 4;
  if (beautyLike) score -= 30;
  return {
    product,
    relevant: true,
    score,
    categoryId,
  };
}

async function searchCreatorHumanApparelExternalSeedProductsDirect({
  search = {},
  metadata = {},
  intent = null,
} = {}) {
  if (!process.env.DATABASE_URL) return null;

  const queryText = extractSearchQueryText(search);
  if (!String(queryText || '').trim()) return null;

  const safeLimit = Math.max(1, Math.min(SEARCH_LIMIT_MAX, Math.floor(Number(search.limit || 20) || 20)));
  const safePage = Math.max(1, Math.floor(Number(search.page || 1) || 1));
  const safeOffset = Math.max(
    0,
    Number.isFinite(Number(search.offset))
      ? Math.floor(Number(search.offset))
      : (safePage - 1) * safeLimit,
  );
  const inStockOnly = parseQueryBoolean(search.in_stock_only ?? search.inStockOnly) !== false;
  const market =
    String(process.env.CREATOR_CATEGORIES_EXTERNAL_SEED_MARKET || 'US').trim().toUpperCase() || 'US';
  const normalizedQuery = normalizeSearchTextForMatch(queryText);
  const anchorTokens = extractSearchAnchorTokens(queryText);
  const queryTokens = Array.from(new Set(tokenizeSearchTextForMatch(normalizedQuery)));
  const requiredCategories = normalizeCreatorHumanApparelRequiredCategories(queryText, intent);
  const brandDetection = detectBrandEntities(queryText, { candidateProducts: [] });
  const brandTerms = Array.isArray(brandDetection?.brands)
    ? brandDetection.brands
        .map((value) => normalizeSearchTextForMatch(value))
        .filter((value) => value && value.length >= 2)
    : [];
  const retrievalQueries = buildCreatorHumanApparelRetrievalQueries(queryText, intent);
  const perQueryLimit = Math.max(24, Math.min(120, safeLimit * 6));
  const creatorScoped = await queryCreatorHumanApparelExternalSeedRows({
    market,
    retrievalQueries,
    inStockOnly,
    perQueryLimit,
    toolScope: 'creator_preferred',
  });
  const creatorScopedScored = creatorScoped.rawProducts.map((product) =>
    scoreCreatorHumanApparelExternalSeedProduct({
      product,
      normalizedQuery,
      anchorTokens,
      queryTokens,
      requiredCategories,
      brandTerms,
    }),
  );
  const shouldBroadenToolScope =
    creatorScoped.rawProducts.length === 0 ||
    creatorScopedScored.every((item) => item.relevant !== true);
  const allToolsScoped = shouldBroadenToolScope
    ? await queryCreatorHumanApparelExternalSeedRows({
        market,
        retrievalQueries,
        inStockOnly,
        perQueryLimit,
        toolScope: 'all_tools',
      })
    : null;
  const selectedScope = allToolsScoped || creatorScoped;
  const scored = (allToolsScoped ? allToolsScoped.rawProducts : creatorScoped.rawProducts)
    .map((product) =>
      scoreCreatorHumanApparelExternalSeedProduct({
        product,
        normalizedQuery,
        anchorTokens,
        queryTokens,
        requiredCategories,
        brandTerms,
      }),
    )
    .filter((item) => item.relevant === true)
    .sort((left, right) => {
      if (right.score !== left.score) return right.score - left.score;
      return String(right.product?.title || '').localeCompare(String(left.product?.title || ''));
    });
  const rankedProducts = scored.map((item) => item.product);
  const pagedProducts = rankedProducts.slice(safeOffset, safeOffset + safeLimit);

  return {
    status: 'success',
    success: true,
    products: pagedProducts,
    total: rankedProducts.length,
    page: safePage,
    page_size: pagedProducts.length,
    reply:
      pagedProducts.length > 0
        ? null
        : 'I couldn’t find a matching product in the current catalog. Try a more specific brand, style, or category.',
    metadata: {
      query_source: 'agent_products_creator_external_seed_direct',
      fetched_at: new Date().toISOString(),
      external_seed_only_requested: true,
      external_seed_rows_fetched: selectedScope.rawProducts.length,
      external_seed_rows_built: rankedProducts.length,
      external_seed_returned_count: pagedProducts.length,
      creator_external_seed_tool_scope: allToolsScoped ? 'all_tools' : 'creator_preferred',
      retrieval_query_variants: retrievalQueries,
      retrieval_query_debug: selectedScope.variantResults,
      source_breakdown: {
        internal_count: 0,
        external_seed_count: pagedProducts.length,
        stale_cache_used: false,
        strategy_applied: 'creator_human_apparel_external_seed_direct',
      },
      search_decision: {
        final_decision: pagedProducts.length > 0 ? 'products_returned' : 'empty',
        decision_authority: 'agent_products_creator_external_seed_direct',
        query_target_domain: 'human_apparel',
      },
      route_debug: {
        creator_external_seed_direct: {
          attempted: true,
          tool_scope: allToolsScoped ? 'all_tools' : 'creator_preferred',
          query: queryText,
          required_categories: requiredCategories,
          brand_terms: brandTerms,
        },
      },
    },
  };
}

function inferBeautyMainlineIntent(queryText = '') {
  const raw = String(queryText || '');
  const normalized = normalizeSearchTextForMatch(raw);
  const beautyBrandBrowse = resolveBeautyBrandBrowseQuery(raw);
  const families = new Set();
  const safety = new Set();

  if (
    /\b(sunscreen|spf|sunblock|sun\s*protection|uv|uva|uvb|pa\+{1,4})\b/i.test(raw) ||
    /防晒|防曬|日焼け止め/.test(raw)
  ) {
    families.add('sunscreen');
  }
  if (
    /\b(cleanser|cleansing|face\s*wash|facial\s*wash|洗面|foam|gel\s*cleanser)\b/i.test(raw) ||
    /洁面|潔面|洗面奶|洗面乳|洗脸|洗臉/.test(raw)
  ) {
    families.add('cleanser');
  }
  if (
    /\b(moisturi[sz]er|cream|gel\s*cream|barrier|repair|cica|ceramide|panthenol|b5|lotion)\b/i.test(raw) ||
    /保湿|保濕|面霜|乳液|屏障|修护|修護|舒缓|舒緩|神经酰胺|神經醯胺|泛醇/.test(raw)
  ) {
    families.add('moisturizer');
  }
  if (
    /\b(serum|essence|ampoule|vitamin\s*c|ascorbic|azelaic|niacinamide|tranexamic|brighten|brightening|anti[-\s]?aging|peptide)\b/i.test(raw) ||
    /精华|精華|提亮|淡斑|抗老|胜肽|煙酰胺|烟酰胺|壬二酸|传明酸|傳明酸/.test(raw)
  ) {
    families.add('serum');
  }
  if (/\b(travel|travel[-\s]?size|portable|flight|carry[-\s]?on)\b/i.test(raw) || /旅行|便携|便攜|飞机|飛機/.test(raw)) {
    safety.add('travel_size_preferred');
  }
  if (
    /\b(pregnan\w*|pregnancy|trying\s*to\s*conceive|ttc|retinol[-\s]?free|retinoid[-\s]?free|avoid\s+retinoid|no\s+retinol)\b/i.test(raw) ||
    /怀孕|懷孕|备孕|備孕|孕期|不要视黄醇|不含视黄醇|避开视黄醇/.test(raw)
  ) {
    safety.add('avoid_retinoids');
  }
  if (
    /\b(rosacea|redness|sensitive|sensiti[sz]ed|stinging|burning|gentle|fragrance[-\s]?free|dry\s*sensitive)\b/i.test(raw) ||
    /玫瑰痤疮|酒糟|泛红|泛紅|敏感|刺痛|温和|溫和|无香精|無香精|干敏|乾敏/.test(raw)
  ) {
    safety.add('avoid_cooling_irritants');
  }
  if (
    (
      /\b(rosacea|redness|sensitive|sensiti[sz]ed|stinging|burning)\b/i.test(raw) ||
      /玫瑰痤疮|酒糟|泛红|泛紅|敏感|刺痛/.test(raw)
    ) &&
    (
      /\b(cleanser|cleansing|face\s*wash|wash)\b/i.test(raw) ||
      /洁面|潔面|洗面/.test(raw)
    )
  ) {
    safety.add('avoid_cooling_strong_cleanser');
  }
  if (
    /\b(barrier\s*damage|damaged\s*barrier|over[-\s]?exfoliat|peeling|flaking|stinging|burning)\b/i.test(raw) ||
    /屏障受损|屏障受損|脱皮|脫皮|刺痛|刷酸过度|刷酸過度/.test(raw)
  ) {
    safety.add('avoid_exfoliating_acids');
  }

  return {
    raw,
    normalized,
    beautyLike:
      beautyBrandBrowse.matched ||
      hasBeautyMakeupSearchSignal(raw) ||
      detectBeautyQueryBucket(raw) != null ||
      families.size > 0,
    brandBrowse: beautyBrandBrowse.matched
      ? {
          contract: beautyBrandBrowse.contract,
          brand_key: beautyBrandBrowse.brand_key,
          brand: beautyBrandBrowse.brand,
          alias: beautyBrandBrowse.alias,
          brand_only: beautyBrandBrowse.brand_only,
          explicit_category: beautyBrandBrowse.explicit_category,
        }
      : null,
    families: Array.from(families),
    safety: Array.from(safety),
  };
}

function beautyProductMatchesFamily(product, family) {
  const text = buildFallbackCandidateText(product);
  if (!text) return false;
  const normalizedFamily = String(family || '').trim().toLowerCase();
  if (normalizedFamily === 'sunscreen') {
    const visibleText = normalizeSearchTextForMatch([
      product?.title,
      product?.name,
      product?.product_name,
      product?.display_name,
      product?.category,
      product?.product_type,
      product?.description,
      product?.summary,
      product?.canonical_url,
      product?.destination_url,
      product?.url,
    ].filter(Boolean).join(' '));
    const sunscreenText = visibleText.replace(/\b(without|no|not|non)\s+(spf|sunscreen|sunblock)\b/gi, ' ');
    return /\b(spf|sunscreen|sunblock|broad\s*spectrum|uva|uvb|pa\+{1,4}|anthelios|mineral\s*screen)\b/i.test(sunscreenText) ||
      /防晒|防曬|日焼け止め/.test(visibleText);
  }
  if (normalizedFamily === 'cleanser') {
    return /\b(cleanser|cleansing|face\s*wash|facial\s*wash|foaming\s*wash|wash\s*gel|cleansing\s*gel|cleansing\s*milk)\b/i.test(text) ||
      /洁面|潔面|洗面奶|洗面乳|洗顔料/.test(text);
  }
  if (normalizedFamily === 'moisturizer') {
    return /\b(moisturi[sz]er|cream|gel\s*cream|barrier|repair|cica|ceramide|panthenol|b5|lotion|balm)\b/i.test(text) ||
      /保湿|保濕|面霜|乳液|屏障|修护|修護|舒缓|舒緩|神经酰胺|神經醯胺|泛醇|クリーム/.test(text);
  }
  if (normalizedFamily === 'serum') {
    return /\b(serum|essence|ampoule|vitamin\s*c|ascorbic|azelaic|niacinamide|tranexamic|peptide|brighten|brightening)\b/i.test(text) ||
      /精华|精華|美容液|提亮|淡斑|胜肽|烟酰胺|煙酰胺|壬二酸|传明酸|傳明酸/.test(text);
  }
  return false;
}

function buildBeautyProductDisplayText(product) {
  return normalizeSearchTextForMatch([
    product?.title,
    product?.name,
    product?.product_name,
    product?.display_name,
    product?.brand,
    product?.vendor,
    product?.category,
    product?.product_type,
    product?.canonical_url,
    product?.destination_url,
    product?.url,
  ].filter(Boolean).join(' '));
}

function buildBeautyProductPrimarySurfaceText(product) {
  return normalizeSearchTextForMatch([
    product?.title,
    product?.name,
    product?.product_name,
    product?.display_name,
    product?.brand,
    product?.vendor,
    product?.canonical_url,
    product?.destination_url,
    product?.url,
  ].filter(Boolean).join(' '));
}

function buildBeautyProductSafetyText(product, baseText = '') {
  if (!product || typeof product !== 'object') return String(baseText || '');
  const parts = [baseText];
  const append = (value) => {
    if (Array.isArray(value)) {
      for (const item of value) append(item);
      return;
    }
    if (value && typeof value === 'object') return;
    const text = String(value || '').trim();
    if (text) parts.push(text);
  };
  const seedData = product.seed_data && typeof product.seed_data === 'object' ? product.seed_data : {};
  const ingredientIntel =
    product.ingredient_intel && typeof product.ingredient_intel === 'object'
      ? product.ingredient_intel
      : seedData.ingredient_intel && typeof seedData.ingredient_intel === 'object'
        ? seedData.ingredient_intel
        : {};
  append(product.raw_ingredient_text_clean);
  append(product.pdp_ingredients_raw);
  append(product.pdp_active_ingredients_raw);
  append(product.pdp_description_raw);
  append(product.inci_list);
  append(product.ingredients_inci);
  append(product.active_ingredients);
  append(product.key_ingredients);
  append(product.ingredient_tokens);
  append(seedData.raw_ingredient_text_clean);
  append(seedData.pdp_ingredients_raw);
  append(seedData.pdp_active_ingredients_raw);
  append(seedData.inci_list);
  append(seedData.ingredients_inci);
  append(seedData.active_ingredients);
  append(seedData.key_ingredients);
  append(ingredientIntel.raw_ingredient_text_clean);
  append(ingredientIntel.inci_list);
  append(ingredientIntel.inci_normalized);
  append(ingredientIntel.active_ingredients);
  append(ingredientIntel.key_ingredients);
  return normalizeSearchTextForMatch(parts.join(' '));
}

function hasKBeautyLocalIntent(queryText = '') {
  return /\b(k[-\s]?beauty|korean|korea|seoul)\b|韩国|韓國|韩妆|韓妝|首尔|首爾/i.test(String(queryText || ''));
}

function buildBeautyProductLocalAuthorityText(product = {}) {
  if (!product || typeof product !== 'object') return '';
  const seedData = isPlainObject(product.seed_data) ? product.seed_data : {};
  const snapshot = isPlainObject(seedData.snapshot) ? seedData.snapshot : {};
  const derived = isPlainObject(seedData.derived) ? seedData.derived : {};
  const commerce = isPlainObject(seedData.commerce) ? seedData.commerce : {};
  const recall = isPlainObject(derived.recall) ? derived.recall : {};
  return normalizeSearchTextForMatch(
    [
      product.brand_origin_country,
      product.brand_home_market,
      product.merchant_market,
      product.retailer_region,
      product.retailer_country,
      product.available_markets,
      product.local_purchase_markets,
      product.offline_availability_region,
      seedData.brand_origin_country,
      seedData.brand_home_market,
      seedData.merchant_market,
      seedData.retailer_region,
      seedData.retailer_country,
      seedData.available_markets,
      seedData.local_purchase_markets,
      seedData.offline_availability_region,
      snapshot.brand_origin_country,
      snapshot.brand_home_market,
      snapshot.merchant_market,
      snapshot.retailer_region,
      snapshot.retailer_country,
      snapshot.available_markets,
      snapshot.local_purchase_markets,
      snapshot.offline_availability_region,
      commerce.brand_origin_country,
      commerce.brand_home_market,
      commerce.local_purchase_markets,
      commerce.available_markets,
      recall.brand_origin_country,
      recall.brand_home_market,
      recall.local_purchase_markets,
      recall.available_markets,
      product.kbeauty,
      product.k_beauty,
      seedData.kbeauty,
      seedData.k_beauty,
      snapshot.kbeauty,
      snapshot.k_beauty,
    ]
      .flatMap((value) => (Array.isArray(value) ? value : [value]))
      .map((value) => String(value || '').trim())
      .filter(Boolean)
      .join(' '),
  );
}

function normalizeStringArrayForContract(value) {
  const values = Array.isArray(value) ? value : [value];
  return Array.from(
    new Set(
      values
        .flatMap((item) => (Array.isArray(item) ? item : [item]))
        .filter((item) => item == null || ['string', 'number', 'boolean'].includes(typeof item))
        .map((item) => String(item || '').trim())
        .filter(Boolean),
    ),
  );
}

function firstNonEmptyScalarString(...values) {
  for (const value of values) {
    if (value == null || !['string', 'number', 'boolean'].includes(typeof value)) continue;
    const text = String(value).trim();
    if (text) return text;
  }
  return '';
}

function buildBeautyProductLocalAuthorityForResponse(product = {}) {
  if (!product || typeof product !== 'object') return null;
  const seedData = isPlainObject(product.seed_data) ? product.seed_data : {};
  const snapshot = isPlainObject(seedData.snapshot) ? seedData.snapshot : {};
  const derived = isPlainObject(seedData.derived) ? seedData.derived : {};
  const commerce = isPlainObject(seedData.commerce) ? seedData.commerce : {};
  const recall = isPlainObject(derived.recall) ? derived.recall : {};
  const brandOriginCountry = firstNonEmptyScalarString(
    product.brand_origin_country,
    seedData.brand_origin_country,
    snapshot.brand_origin_country,
    commerce.brand_origin_country,
    recall.brand_origin_country,
  );
  const brandHomeMarket = firstNonEmptyScalarString(
    product.brand_home_market,
    seedData.brand_home_market,
    snapshot.brand_home_market,
    commerce.brand_home_market,
    recall.brand_home_market,
  );
  const availableMarkets = normalizeStringArrayForContract(
    product.available_markets ||
      seedData.available_markets ||
      snapshot.available_markets ||
      commerce.available_markets ||
      recall.available_markets,
  );
  const localPurchaseMarkets = normalizeStringArrayForContract(
    product.local_purchase_markets ||
      seedData.local_purchase_markets ||
      snapshot.local_purchase_markets ||
      commerce.local_purchase_markets ||
      recall.local_purchase_markets,
  );
  const retailerRegion = firstNonEmptyScalarString(
    product.retailer_region,
    product.retailer_country,
    seedData.retailer_region,
    seedData.retailer_country,
    snapshot.retailer_region,
    snapshot.retailer_country,
  );
  const authoritySource = firstNonEmptyScalarString(
    product.authority_source,
    product.local_authority_source,
    seedData.authority_source,
    seedData.local_authority_source,
    commerce.authority_source,
    recall.authority_source,
    brandOriginCountry || brandHomeMarket || availableMarkets.length || localPurchaseMarkets.length || retailerRegion
      ? 'seed'
      : '',
  );
  if (
    !brandOriginCountry &&
    !brandHomeMarket &&
    availableMarkets.length === 0 &&
    localPurchaseMarkets.length === 0 &&
    !retailerRegion &&
    !authoritySource
  ) {
    return null;
  }
  return {
    brand_origin_country: brandOriginCountry || null,
    brand_home_market: brandHomeMarket || null,
    available_markets: availableMarkets,
    local_purchase_markets: localPurchaseMarkets,
    retailer_region: retailerRegion || null,
    authority_source: authoritySource || null,
  };
}

function buildBeautyProductFitAttributesForResponse(product = {}) {
  if (!product || typeof product !== 'object') return null;
  const seedData = isPlainObject(product.seed_data) ? product.seed_data : {};
  const snapshot = isPlainObject(seedData.snapshot) ? seedData.snapshot : {};
  const commerceFacts = isPlainObject(seedData.commerce_facts_v1) ? seedData.commerce_facts_v1 : {};
  const rawText = [
    product?.title,
    product?.name,
    product?.product_name,
    product?.display_name,
    product?.description,
    product?.summary,
    seedData.description,
    snapshot.description,
  ]
    .map((value) => String(value || '').trim())
    .filter(Boolean)
    .join(' ');
  const text = buildFallbackCandidateText(product);
  const spfValue = extractBeautySpfValue(product);
  const spfRating = firstNonEmptyString(
    product.spf_rating,
    seedData.spf_rating,
    snapshot.spf_rating,
    commerceFacts.spf_rating,
    spfValue ? `SPF ${spfValue}` : '',
  );
  const paMatch = rawText.match(/(pa\+{1,4})/i);
  const paRating = firstNonEmptyString(
    product.pa_rating,
    seedData.pa_rating,
    snapshot.pa_rating,
    commerceFacts.pa_rating,
    paMatch ? paMatch[1].toUpperCase() : '',
  );
  const texture = firstNonEmptyString(
    product.texture,
    seedData.texture,
    snapshot.texture,
    commerceFacts.texture,
    /\bstick\b/i.test(text)
      ? 'stick'
      : /\bcushion\b/i.test(text)
        ? 'cushion'
        : /\bfluid\b/i.test(text)
          ? 'fluid'
          : /\bgel\s*cream\b/i.test(text)
            ? 'gel_cream'
            : /\bgel\b/i.test(text)
              ? 'gel'
              : /\blotion\b/i.test(text)
                ? 'lotion'
                : /\bcream\b/i.test(text)
                  ? 'cream'
                  : '',
  );
  const finish = firstNonEmptyString(
    product.finish,
    seedData.finish,
    snapshot.finish,
    commerceFacts.finish,
    /\bmatte\b/i.test(text)
      ? 'matte'
      : /\b(dewy|glow|glowy|luminous)\b/i.test(text)
        ? 'dewy'
        : /\bnatural\b/i.test(text)
          ? 'natural'
          : '',
  );
  const fragranceFreeClaim = /\b(fragrance[-\s]?free|unscented|no\s+fragrance|without\s+fragrance)\b|无香精|無香精/i.test(text);
  const alcoholDenatHit =
    /\b(alcohol\s*denat|denatured\s*alcohol|sd\s*alcohol)\b/i.test(text) &&
    !/\b(alcohol[-\s]?free|no\s+alcohol|without\s+alcohol)\b|无酒精|無酒精/i.test(text);
  const nonComedogenicClaim = /\b(non[-\s]?comedogenic|won't\s+clog\s+pores|will\s+not\s+clog\s+pores)\b/i.test(text);
  const packVariant = detectBeautyProductPackVariant(product);
  const result = {
    spf_rating: spfRating || null,
    pa_rating: paRating || null,
    texture: texture || null,
    finish: finish || null,
    fragrance_free: fragranceFreeClaim || undefined,
    alcohol_denat: alcoholDenatHit || undefined,
    non_comedogenic: nonComedogenicClaim || undefined,
    travel_size: packVariant.any ? Boolean(packVariant.travel_size) : undefined,
  };
  const hasAny = Object.values(result).some((value) => value !== null && value !== undefined && value !== false);
  return hasAny ? result : null;
}

function beautyProductHasKBeautySignal(product) {
  const text = buildFallbackCandidateText(product);
  const localAuthorityText = buildBeautyProductLocalAuthorityText(product);
  if (
    /\b(kr|kor|korea|korean|south\s*korea|seoul|k[-\s]?beauty|yes|true)\b/i.test(localAuthorityText) ||
    /韩国|韓國|首尔|首爾|韩妆|韓妝/.test(localAuthorityText)
  ) {
    return true;
  }
  if (!text) return false;
  return (
    /\b(k[-\s]?beauty|korean|korea|seoul|round\s*lab|dokdo|beauty\s+of\s+joseon|joseon|cosrx|anua|skin1004|skin\s*1004|torriden|dr\.?\s*jart|etude|innisfree|isntree|purito|haruharu|numbuzin|abib|laneige|rovectin|mediheal|mixsoon|axis[-\s]?y|ma:nyo|manyo|pyunkang|illiyoon|iunik|skinfood|skin\s*food|celimax|needly|d'?alba|romand|mugwort|birch\s+moisturi[sz]ing\s+sun)\b/i.test(text) ||
    /韩国|韓國|韩妆|韓妝|首尔|首爾/.test(text)
  );
}

function beautyQueryHasHotHumidOilyAcneContext(queryText = '') {
  return (
    /\b(oily|oilier|oil\s*control|acne|blemish|breakout|clog(?:ged)?|comedogenic|humid|humidity|hot|sweat|sweaty|tropical|bangkok|seoul|summer)\b/i.test(String(queryText || '')) ||
    /油皮|油痘|痘|粉刺|闭口|閉口|闷痘|悶痘|湿热|濕熱|高温|高溫|出汗|曼谷|首尔|首爾/.test(String(queryText || ''))
  );
}

function beautyQueryHasColdDryBarrierContext(queryText = '') {
  return (
    /\b(dry|dehydrated|tight|flaking|peeling|cold|winter|reykjavik|barrier|repair|flight|airplane|low\s*humidity|sensitive|rosacea)\b/i.test(String(queryText || '')) ||
    /干皮|乾皮|干敏|乾敏|脱皮|脫皮|刺痛|冷干|冷乾|屏障|修护|修護|飞机|飛機|低湿|低濕|敏感|泛红|泛紅/.test(String(queryText || ''))
  );
}

function beautyQueryRequestsHighUvSpf(queryText = '') {
  return (
    /\b(spf\s*50|spf50|pa\+{3,4}|uva|uvb|uv|high\s*uv|strong\s*sun|sun\s*exposure|travel|seoul|bangkok)\b/i.test(String(queryText || '')) ||
    /防晒|防曬|紫外线|紫外線|补涂|補塗|首尔|首爾|曼谷|旅行/.test(String(queryText || ''))
  );
}

function extractBeautySpfValue(product = {}) {
  const text = normalizeSearchTextForMatch(
    [
      product?.title,
      product?.name,
      product?.product_name,
      product?.display_name,
      product?.description,
      product?.summary,
      product?.seed_data?.description,
      product?.seed_data?.snapshot?.description,
    ]
      .map((value) => String(value || '').trim())
      .filter(Boolean)
      .join(' '),
  );
  const match = text.match(/\bspf\s*([1-9][0-9]{1,2})\+?\b/i);
  if (!match) return null;
  const value = Number(match[1]);
  return Number.isFinite(value) ? value : null;
}

function scoreBeautyStrictQualityOverlay({ product, queryText = '', intent = null } = {}) {
  if (!PIVOT_BEAUTY_STRICT_RECO_QUALITY_ENABLED) return 0;
  const candidateText = buildFallbackCandidateText(product);
  if (!candidateText) return 0;
  const rawCandidateText = [
    product?.title,
    product?.name,
    product?.product_name,
    product?.display_name,
    product?.description,
    product?.summary,
    product?.seed_data?.description,
    product?.seed_data?.snapshot?.description,
  ]
    .map((value) => String(value || '').trim())
    .filter(Boolean)
    .join(' ');
  const families = new Set(Array.isArray(intent?.families) ? intent.families : []);
  const hotHumidOilyAcne = beautyQueryHasHotHumidOilyAcneContext(queryText);
  const coldDryBarrier = beautyQueryHasColdDryBarrierContext(queryText);
  const localKBeauty = hasKBeautyLocalIntent(queryText);
  const highUvSpf = beautyQueryRequestsHighUvSpf(queryText);
  let score = 0;

  if (families.has('sunscreen')) {
    const spfValue = extractBeautySpfValue(product);
    if (highUvSpf) {
      if (spfValue && spfValue >= 50) score += 10;
      if (spfValue && spfValue < 50) score -= 24;
      if (/pa\+{3,4}/i.test(rawCandidateText)) score += 8;
    }
    if (hotHumidOilyAcne) {
      if (/\b(lightweight|airy|fluid|gel|watery|aqua|matte|oil[-\s]?control|shine[-\s]?control|non[-\s]?comedogenic|stick|cushion)\b/i.test(candidateText)) score += 14;
      if (/\b(glowscreen|golden\s*hour|dewy|glow|luminous|super\s*cream|daily\s*facial\s*moisturi[sz]er|moisturi[sz]er\s+with\s+sunscreen|rich|heavy)\b/i.test(candidateText)) score -= 22;
    }
    if (localKBeauty) {
      if (beautyProductHasKBeautySignal(product)) score += 24;
      else score -= 22;
      if (/\b(olay|glowscreen|supergoop|golden\s*hour)\b/i.test(candidateText) && !beautyProductHasKBeautySignal(product)) {
        score -= 18;
      }
    }
  }

  if (families.has('moisturizer')) {
    if (hotHumidOilyAcne && !coldDryBarrier) {
      if (/\b(gel\s*cream|water\s*cream|lotion|lightweight|oil[-\s]?free|non[-\s]?comedogenic|panthenol|cica|centella|ceramide|fragrance[-\s]?free|unscented)\b/i.test(candidateText)) score += 12;
      if (/\b(intense\s*hydration|ultra\s*repair\s*cream|rich|heavy|balm|butter|occlusive|sleeping\s*mask)\b/i.test(candidateText)) score -= 20;
    }
    if (coldDryBarrier) {
      if (/\b(ceramide|panthenol|cica|centella|barrier|repair|colloidal|oat|oatmeal|fragrance[-\s]?free|unscented|sensitive)\b/i.test(candidateText)) score += 12;
    }
  }

  if (families.has('cleanser')) {
    if (/\b(sensitive|sensiti[sz]ed|rosacea|redness|gentle|fragrance[-\s]?free)\b|敏感|泛红|泛紅|温和|溫和|玫瑰痤疮|酒糟/i.test(String(queryText || ''))) {
      if (/\b(ultra\s*gentle|gentle|cream[-\s]?to[-\s]?foam|cream\s*cleanser|gel\s*cleanser|low[-\s]?ph|non[-\s]?stripping|fragrance[-\s]?free|unscented|sensitive|colloidal|oat|oatmeal)\b/i.test(candidateText)) score += 12;
      if (/\b(cleansing\s*oil|cleansing\s*water|micellar|deep\s*clean|purifying|foaming\s*scrub)\b/i.test(candidateText)) score -= 8;
    }
    if (localKBeauty && beautyProductHasKBeautySignal(product)) score += 10;
  }

  if (families.has('serum')) {
    if (/\b(sensitive|sensiti[sz]ed|dry\s*sensitive|fragrance[-\s]?free|gentle)\b|敏感|干敏|乾敏|温和|溫和/i.test(String(queryText || ''))) {
      if (/\b(niacinamide\s*(?:10|15|20)(?:\s*%|\b)|(?:10|15|20)(?:\s*%|\b)\s*niacinamide|zinc\s*1\s*%)\b/i.test(candidateText)) score -= 18;
      if (/\b(niacinamide\s*5(?:\s*%|\b)|azelaic|tranexamic|ceramide|barrier|essence|unscented|fragrance[-\s]?free)\b/i.test(candidateText)) score += 8;
    }
  }

  return score;
}

function scoreBeautyCreatorCurationOverlay({ product, queryText = '', creatorId = '' } = {}) {
  if (!PIVOT_BEAUTY_CREATOR_CURATION_RANKING_ENABLED || !product || typeof product !== 'object') return 0;
  const seedData = isPlainObject(product.seed_data) ? product.seed_data : {};
  const commerce = isPlainObject(seedData.commerce) ? seedData.commerce : {};
  const creator = isPlainObject(seedData.creator) ? seedData.creator : {};
  const text = normalizeSearchTextForMatch(
    [
      product.creator_id,
      product.creator_ids,
      product.creator_tags,
      product.creator_rank_tags,
      product.source_listing_scope,
      product.tool,
      seedData.creator_id,
      seedData.creator_ids,
      seedData.creator_tags,
      seedData.creator_rank_tags,
      seedData.source_listing_scope,
      creator.creator_id,
      creator.creator_ids,
      creator.tags,
      creator.rank_tags,
      creator.curation_tier,
      commerce.affiliate_url,
      commerce.purchase_route,
    ]
      .flatMap((value) => (Array.isArray(value) ? value : [value]))
      .map((value) => String(value || '').trim())
      .filter(Boolean)
      .join(' '),
  );
  const safeCreatorId = normalizeSearchTextForMatch(creatorId);
  let score = 0;
  if (safeCreatorId && text.includes(safeCreatorId)) score += 16;
  if (/\b(creator\s*curated|creator[-\s]?curated|creator\s*pick|creator[-\s]?pick|nina\s*pick|editorial\s*pick|staff\s*pick|top\s*pick)\b/i.test(text)) score += 14;
  if (/\b(carried|storefront|owned\s*inventory|creator\s*inventory|creator[-\s]?preferred)\b/i.test(text)) score += 10;
  if (/\b(sensitive|barrier|travel|k[-\s]?beauty|seoul|fragrance[-\s]?free)\b/i.test(text) && /\b(sensitive|barrier|travel|seoul|k[-\s]?beauty|fragrance[-\s]?free)\b/i.test(String(queryText || ''))) {
    score += 6;
  }
  if (PIVOT_BEAUTY_CREATOR_COMMERCIAL_RANKING_ENABLED) {
    const commission = Number(
      product.commission_rate ??
        product.affiliate_commission_rate ??
        seedData.commission_rate ??
        seedData.affiliate_commission_rate ??
        commerce.commission_rate ??
        commerce.affiliate_commission_rate,
    );
    if (Number.isFinite(commission) && commission > 0) {
      score += Math.min(8, Math.max(1, Math.round(commission * 100)));
    } else if (/\b(affiliate|affiliate_outbound|commissionable|revshare|revenue\s*share)\b/i.test(text)) {
      score += 3;
    }
  }
  return Math.min(score, 28);
}

function getBeautyCreatorOverlaySkippedReason(overlayScore = 0) {
  if (Number(overlayScore || 0) > 0) return null;
  if (!PIVOT_CREATOR_RANKING_OVERLAY_ENABLED) return 'overlay_disabled';
  if (!PIVOT_CREATOR_LOCAL_CURATION_ENABLED) return 'local_curation_disabled';
  return 'no_reviewed_creator_inventory';
}

function buildBeautyCreatorRankTelemetry({ overlayScore = 0 } = {}) {
  const normalizedScore = Math.max(0, Number(overlayScore || 0) || 0);
  const boostApplied = normalizedScore > 0 && PIVOT_BEAUTY_CREATOR_CURATION_RANKING_ENABLED;
  return {
    creator_inventory_match: boostApplied,
    creator_boost_applied: boostApplied,
    commercial_boost_applied: boostApplied && PIVOT_BEAUTY_CREATOR_COMMERCIAL_RANKING_ENABLED,
    rank_reasons: boostApplied ? ['creator_curation_overlay'] : [],
    overlay_score: normalizedScore,
    overlay_enabled: PIVOT_CREATOR_RANKING_OVERLAY_ENABLED,
    local_curation_enabled: PIVOT_CREATOR_LOCAL_CURATION_ENABLED,
    commercial_boost_enabled: PIVOT_CREATOR_COMMERCIAL_BOOST_ENABLED,
    overlay_skipped_reason: getBeautyCreatorOverlaySkippedReason(normalizedScore),
  };
}


function beautyQueryRequestsLipCare(queryText = '') {
  return /\b(lip|lips|lip\s*balm|lip\s*shield|chapstick)\b|唇膏|润唇|潤唇|护唇|護唇/i.test(String(queryText || ''));
}

function beautyProductIsLipCareSurface(product) {
  const text = buildBeautyProductPrimarySurfaceText(product);
  if (!text) return false;
  return (
    /\b(lip|lips|lip\s*balm|lip\s*shield|lip\s*sunscreen|chapstick)\b/i.test(text) ||
    /唇膏|润唇|潤唇|护唇|護唇/.test(text)
  );
}

function isBeautyProductContraindicatedForQuery(product, queryText = '', intent = null) {
  const text = buildFallbackCandidateText(product);
  if (!text) return false;
  const profile = intent || inferBeautyMainlineIntent(queryText);
  const safety = new Set(Array.isArray(profile.safety) ? profile.safety : []);
  const families = new Set(Array.isArray(profile.families) ? profile.families : []);
  const displayText = buildBeautyProductDisplayText(product);
  const primarySurfaceText = buildBeautyProductPrimarySurfaceText(product);
  const titleSurfaceText = normalizeSearchTextForMatch([
    product?.title,
    product?.name,
    product?.product_name,
    product?.display_name,
    product?.category,
    product?.product_type,
  ].filter(Boolean).join(' '));
  const titleNameSurfaceText = normalizeSearchTextForMatch([
    product?.title,
    product?.name,
    product?.product_name,
    product?.display_name,
  ].filter(Boolean).join(' '));
  const safetyText = buildBeautyProductSafetyText(product, text);
  const normalizedQuery = normalizeSearchTextForMatch(queryText);
  const acneOilControlIntent = beautyQueryHasAcneOilControlIntent(queryText);
  const calmFaceSkincareQuery =
    (families.size > 0 || acneOilControlIntent) &&
    /\b(face|facial|skin|skincare|sensitive|sensiti[sz]ed|redness|rosacea|dry|oily|acne|blemish|breakout|pore|barrier|repair|gentle|fragrance[-\s]?free|travel|flight|moisturi[sz]er|cream|cleanser|serum|sunscreen)\b|面部|脸|臉|护肤|護膚|敏感|泛红|泛紅|干皮|乾皮|油皮|痘|粉刺|毛孔|屏障|修护|修護|温和|溫和|无香精|無香精|旅行|飞行|飛行|保湿|保濕|洁面|潔面|精华|精華|防晒|防曬/i.test(normalizedQuery);
  const barrierFirstQuery =
    /\b(sensitive|sensiti[sz]ed|redness|rosacea|dry|barrier|repair|gentle|fragrance[-\s]?free|travel|flight|acne|peeling|stinging|burning)\b|敏感|泛红|泛紅|干皮|乾皮|屏障|修护|修護|温和|溫和|无香精|無香精|旅行|飞行|飛行|痘|脱皮|脫皮|刺痛/i.test(normalizedQuery);
  const fragranceAverseQuery =
    barrierFirstQuery || safety.has('avoid_cooling_irritants') || safety.has('avoid_cooling_strong_cleanser');
  const queryRequestsExfoliatingAcid =
    /\b(aha|bha|pha|salicylic|glycolic|lactic|mandelic|exfoliat|peel|peeling|resurfacing|p50)\b|刷酸|去角质|去角質|水杨酸|水楊酸|果酸|杏仁酸|焕肤|煥膚/i.test(normalizedQuery);
  const productLooksLikeExfoliatingAcid =
    /\b(lotion\s*p50\w*|p50\w*|aha|bha|pha|glycolic|lactic|mandelic|salicylic|resurfacing|peel|peeling|exfoliating|acid\s*(?:toner|lotion|peel|exfoliant)|toner\s*pads?)\b|刷酸|去角质|去角質|水杨酸|水楊酸|果酸|杏仁酸|焕肤|煥膚/i.test(safetyText);
  const queryRequestsEye = /\b(eye|eyes|undereye|under[-\s]?eye)\b|眼霜|眼部/i.test(normalizedQuery);
  const queryRequestsBody = /\b(body|hand|hands|hair|scalp|lip|lips)\b|身体|身體|护手|護手|头发|頭髮|头皮|頭皮|唇/i.test(normalizedQuery);
  const queryRequestsOil = /\b(face\s*oil|facial\s*oil|dry\s*oil|beauty\s*oil|huile|oil)\b|面油|护肤油|護膚油|美容油/i.test(normalizedQuery);
  const queryRequestsAntiAging = /\b(anti[-\s]?aging|anti[-\s]?ageing|firming|wrinkle|lift|lifting|mature\s*skin)\b|抗老|抗皱|抗皺|紧致|緊緻|提拉/i.test(normalizedQuery);
  const queryRequestsMask = /\b(mask|mud\s*pack|clay\s*pack|sleeping\s*pack|wash[-\s]?off\s*pack)\b|面膜|泥膜/i.test(normalizedQuery);
  const queryRequestsRoutineSet = /\b(routine|regimen|set|kit|bundle|capsule|starter\s*kit)\b|套装|套組|套組|套组|组合|組合|护理包|護理包/i.test(normalizedQuery);
  const queryRequestsBrushTool = /\b(brush|brushes|makeup\s*brush|tool|tools)\b|刷具|化妆刷|化妝刷|工具/i.test(normalizedQuery);
  const gentleSensitiveQuery =
    /\b(sensitive|sensiti[sz]ed|gentle|fragrance[-\s]?free|dry\s*sensitive)\b|敏感|温和|溫和|无香精|無香精|干敏|乾敏/i.test(normalizedQuery);
  const brighteningSerumQuery =
    families.has('serum') &&
    /\b(brighten|brightening|dark\s*spot|uneven\s*tone|tone|vitamin\s*c|ascorbic|azelaic|niacinamide|tranexamic)\b|提亮|淡斑|肤色不均|膚色不均|维\s*c|維\s*c|烟酰胺|煙酰胺|壬二酸|传明酸|傳明酸/i.test(normalizedQuery);
  const queryRequestsTreatmentSerum =
    families.has('serum') ||
    /\b(serum|essence|ampoule|suspension|treatment|azelaic|hyaluronic\s+acid|niacinamide|tranexamic|vitamin\s*c)\b|精华|精華|安瓶|壬二酸|玻尿酸|透明质酸|煙酰胺|烟酰胺|传明酸|傳明酸/i.test(normalizedQuery);
  const productLooksLikeOilSurface = /\b(huile|face\s*oil|facial\s*oil|dry\s*oil|beauty\s*oil)\b|面油|护肤油|護膚油|美容油/i.test(titleSurfaceText);
  const productLooksLikeAntiAging =
    /\b(anti[-\s]?aging|anti[-\s]?ageing|firming|wrinkle|wrinkles|lift|lifting|merveillance|nuxuriance|global\s+anti[-\s]?aging|exceptional\s+day\s*&?\s*night)\b|抗老|抗皱|抗皺|紧致|緊緻|提拉/i.test(safetyText);
  const productLooksLikeMaskPack = /\b(mud\s*pack|clay\s*pack|sleeping\s*pack|wash[-\s]?off\s*pack|sleeping\s*mask|sheet\s*mask|mask)\b|面膜|泥膜/i.test(titleSurfaceText);
  const productLooksLikeRoutineSet = /\b(am\/pm\s+routine|cult\s+skincare\s+routine|routine|regimen|starter\s*kit|kit|set|duo|trio|bundle|collection|capsule)\b|套装|套組|套组|组合|組合|护理包|護理包/i.test(titleSurfaceText);
  const productLooksLikeBrushTool = /\b(brush\s*cleanser|brushes?|makeup\s*brush|brush\s*cleaning|tool\s*cleanser)\b|刷具|化妆刷|化妝刷|工具/i.test(safetyText);
  const productLooksLikeCleanserSurface =
    /\b(cleanser|cleansing|face\s*wash|facial\s*wash|foaming\s*wash|wash\s*gel|cleansing\s*gel|cleansing\s*foam|cleansing\s*milk)\b|洁面|潔面|洗面奶|洗面乳|洗顔料/i.test(titleNameSurfaceText);
  const productLooksLikeTreatmentSerum =
    /\b(serum|essence|ampoule|suspension|treatment|azelaic\s+acid|hyaluronic\s+acid(?:\s+\d+%?)?|niacinamide|tranexamic\s+acid)\b|精华|精華|安瓶|壬二酸|玻尿酸|透明质酸|煙酰胺|烟酰胺|传明酸|傳明酸/i.test(titleSurfaceText);
  const productLooksLikeVolumePlumpingSerum =
    /\b(volufiline|pal[-\s]?isoleucine|adipofil(?:l)?in|volume\s*boost|plumping\s*serum)\b/i.test(safetyText);
  const fragranceFreeClaim = /\b(fragrance[-\s]?free|unscented|no\s+fragrance|without\s+fragrance)\b|无香精|無香精|不含香精/i.test(safetyText);
  const fragranceHit =
    /\b(parfum\/fragrance|parfum|perfume|fragrance|scented|linalool|limonene|citronellol|geraniol|coumarin|hydroxycitronellal|alpha[-\s]?isomethyl\s+ionone|rose\s+ketones)\b|香精|香料/i.test(safetyText);
  const retinoidHit =
    /\b(bio[-\s]?retinol|retinol|retinal|retinoid|retinyl|tretinoin|adapalene|hydroxypinacolone|hpr)\b/i.test(safetyText) ||
    /视黄醇|視黃醇|维a醇|維a醇|维甲酸|維甲酸|a醇/.test(safetyText);
  if (safety.has('avoid_retinoids')) {
    if (retinoidHit && !/\b(retinol[-\s]?free|retinoid[-\s]?free|no\s+retinol|without\s+retinol)\b/i.test(text)) {
      return true;
    }
    if (/\b(resurfacing|pore\s*refine|clarifying|peel|peeling|exfoliating|aha|bha|salicylic|glycolic|lactic|mandelic)\b|刷酸|去角质|去角質|水杨酸|水楊酸|果酸/i.test(text)) {
      return true;
    }
  }
  if (
    retinoidHit &&
    (families.has('sunscreen') || families.has('cleanser') || families.has('moisturizer')) &&
    !/\b(retinol[-\s]?free|retinoid[-\s]?free|no\s+retinol|without\s+retinol)\b/i.test(text)
  ) {
    return true;
  }
  if (
    retinoidHit &&
    /\b(sensitive|sensiti[sz]ed|gentle|brightening|fragrance[-\s]?free|pregnan\w*|trying\s*to\s*conceive|ttc)\b|敏感|温和|溫和|提亮|备孕|備孕|怀孕|懷孕/i.test(String(queryText || '')) &&
    !/\b(retinol[-\s]?free|retinoid[-\s]?free|no\s+retinol|without\s+retinol)\b/i.test(text)
  ) {
    return true;
  }
  if (safety.has('avoid_cooling_strong_cleanser')) {
    if (
      /\b(menthol|mint|peppermint|eucalyptus|cooling|scrub|polish|deep\s*clean|deep\s*cleansing|purifying\s*scrub|exfoliating\s*cleanser)\b/i.test(text) ||
      /薄荷|清凉|清涼|磨砂|去角质洁面|去角質潔面|强清洁|強清潔/.test(text)
    ) {
      return true;
    }
  }
  if (safety.has('avoid_cooling_irritants')) {
    if (
      /\b(menthol|mint|peppermint|eucalyptus|camphor|cooling)\b/i.test(text) ||
      /薄荷|清凉|清涼|樟脑|樟腦/.test(text)
    ) {
      return true;
    }
  }
  if (safety.has('avoid_exfoliating_acids')) {
    if (
      productLooksLikeExfoliatingAcid ||
      /果酸|水杨酸|水楊酸|杏仁酸|乳酸|刷酸|去角质酸|去角質酸/.test(text)
    ) {
      return true;
    }
  }
  if (calmFaceSkincareQuery && productLooksLikeExfoliatingAcid && !queryRequestsExfoliatingAcid) {
    return true;
  }
  if (fragranceAverseQuery && fragranceHit && !fragranceFreeClaim) {
    return true;
  }
  if (calmFaceSkincareQuery && families.has('moisturizer') && productLooksLikeOilSurface && !queryRequestsOil) {
    return true;
  }
  if (barrierFirstQuery && productLooksLikeAntiAging && !queryRequestsAntiAging) {
    return true;
  }
  if (calmFaceSkincareQuery && productLooksLikeRoutineSet && !queryRequestsRoutineSet) {
    return true;
  }
  if ((brighteningSerumQuery || gentleSensitiveQuery) && productLooksLikeVolumePlumpingSerum) {
    return true;
  }
  if (calmFaceSkincareQuery && productLooksLikeMaskPack && !queryRequestsMask) {
    return true;
  }
  if (calmFaceSkincareQuery && families.has('cleanser') && productLooksLikeBrushTool && !queryRequestsBrushTool) {
    return true;
  }
  if (
    calmFaceSkincareQuery &&
    (families.has('cleanser') || families.has('moisturizer') || families.has('sunscreen')) &&
    productLooksLikeTreatmentSerum &&
    !queryRequestsTreatmentSerum &&
    !(families.has('cleanser') && productLooksLikeCleanserSurface)
  ) {
    return true;
  }
  if (
    calmFaceSkincareQuery &&
    !queryRequestsEye &&
    /\b(?:(?:eye|eyes)\b.{0,16}\b(?:cream|balm|serum|treatment)|(?:cream|balm|serum|treatment)\b.{0,16}\b(?:eye|eyes)|under[-\s]?eye)\b|眼霜|眼部/i.test(primarySurfaceText)
  ) {
    return true;
  }
  if (
    calmFaceSkincareQuery &&
    !queryRequestsBody &&
    (
      (
        /\b(body\s*(?:lotion|cream|oil|gel|wash|cleanser|sunscreen|milk)|hand\s*(?:cream|lotion)|scalp|hair|capillaire)\b|身体|身體|护手|護手|头发|頭髮|头皮|頭皮/i.test(primarySurfaceText) &&
        !/\bface|facial\b|面部|脸|臉/i.test(primarySurfaceText)
      ) ||
      /\b(?:sulphate|sulfate)\s*\d+%?\s*cleanser\s+for\s+body\s+and\s+hair\b/i.test(text)
    )
  ) {
    return true;
  }
  if (
    calmFaceSkincareQuery &&
    /\b(scented|fragrance|parfum|perfume)\b|香精|香料/i.test(primarySurfaceText) &&
    !/\b(fragrance[-\s]?free|unscented|no\s+fragrance)\b|无香精|無香精/i.test(text)
  ) {
    return true;
  }
  if (
    beautyProductIsLipCareSurface(product) &&
    !beautyQueryRequestsLipCare(queryText) &&
    (
      /\b(face|facial|skin|skincare|sensitive|sensiti[sz]ed|redness|rosacea|oily|dry|acne|pregnan\w*|ttc|brighten|brightening|moisturi[sz]er|serum|barrier|repair|daily\s+sunscreen)\b|面部|脸|臉|护肤|護膚|敏感|泛红|泛紅|油皮|干皮|乾皮|痘|孕|提亮|保湿|保濕|屏障|修护|修護/.test(normalizedQuery) ||
      profile.families.length > 1
    )
  ) {
    return true;
  }
  if (
    families.has('cleanser') &&
    /\b(cleansing\s*pads?|cleanse\s*pads?|peel\s*pads?|toner\s*pads?|exfoliating\s*pads?|clarifying\s*pads?)\b/i.test(text) &&
    !/\b(?:pad|pads)\b|棉片|片/i.test(normalizedQuery)
  ) {
    return true;
  }
  if (
    families.has('moisturizer') &&
    /\b(barrier|repair|sensitive|sensiti[sz]ed|fragrance\s*free|ceramide|panthenol|cica)\b|屏障|修护|修護|敏感|无香精|無香精|神经酰胺|神經醯胺|泛醇/i.test(normalizedQuery) &&
    /\b(resurfacing|exfoliating|peel|peeling|retinol|retinoid|acid\s*toner|clarifying|aha|bha|salicylic|glycolic|lactic|mandelic)\b|刷酸|去角质|去角質|水杨酸|水楊酸|果酸|视黄醇|視黃醇/i.test(text)
  ) {
    return true;
  }
  if (
    families.has('moisturizer') &&
    /\b(barrier|repair|sensitive|sensiti[sz]ed|fragrance\s*free|ceramide|panthenol|cica)\b|屏障|修护|修護|敏感|无香精|無香精|神经酰胺|神經醯胺|泛醇/i.test(normalizedQuery) &&
    /\b(azelaic|salicylic|glycolic|lactic|mandelic|ascorbic|vitamin\s*c|retinol|retinal|aha|bha|pha)\b/i.test(displayText) &&
    /\b(serum|suspension|solution|treatment|toner|peel|exfoliating|acid)\b/i.test(displayText) &&
    !/\b(moisturi[sz]er|barrier|repair|ceramide|cica|panthenol|b5)\b/i.test(primarySurfaceText)
  ) {
    return true;
  }
  return false;
}

function looksLikeBeautyVariantTitleSuffix(suffix = '', baseTitle = '') {
  const normalizedSuffix = normalizeSearchTextForMatch(suffix);
  const normalizedBase = normalizeSearchTextForMatch(baseTitle);
  if (!normalizedSuffix || !normalizedBase) return false;
  const suffixTokens = tokenizeSearchTextForMatch(normalizedSuffix).filter(Boolean);
  if (suffixTokens.length === 0 || suffixTokens.length > 5) return false;
  const baseHasBeautyProductTerm =
    /\b(?:foundation|concealer|bronzer|blush|highlighter|eye\s*brightener|brightener|lipstick|lip\s*color|lip\s*paint|lip\s*cream|lip\s*gloss|lip\s*balm|mascara|eyeliner|eyeshadow|brow|powder|primer|skin\s*tint|moisturi[sz]er|serum|cleanser|sunscreen|spf|fragrance|perfume|parfum|mist|shampoo|conditioner|cream|gel|oil|stick|pencil|liner)\b/.test(normalizedBase);
  if (!baseHasBeautyProductTerm) return false;
  if (/\b(?:foundation|concealer|bronzer|blush|highlighter|lipstick|mascara|eyeliner|eyeshadow|moisturi[sz]er|serum|cleanser|sunscreen|fragrance|perfume|parfum|bundle|set|kit|duo|trio)\b/.test(normalizedSuffix)) {
    return false;
  }
  return true;
}

function stripBeautyVariantSuffixForDedupe(rawTitle = '') {
  const title = String(rawTitle || '').trim();
  if (!title) return '';
  const separatorMatch = title.match(/^(.{8,}?)\s+(?:[-–—:|])\s+(.{1,80})$/u);
  if (!separatorMatch) return title;
  const base = String(separatorMatch[1] || '').trim();
  const suffix = String(separatorMatch[2] || '').trim();
  return looksLikeBeautyVariantTitleSuffix(suffix, base) ? base : title;
}

function canonicalizeBeautyProductTitleForDedupe(rawTitle = '') {
  return normalizeSearchTextForMatch(stripBeautyVariantSuffixForDedupe(rawTitle))
    .replace(/\b(?:jumbo|supersize|super\s*size|value\s*size|value\s*pack|double\s*pack|duo|bundle|set|refill|mini|trial\s*size|travel\s*size|full\s*size)\b/g, ' ')
    .replace(/\b\d+(?:\.\d+)?\s*(?:ml|m l|oz|fl\s*oz|g|gram|grams)\b/g, ' ')
    .replace(/\b(?:pack\s*of\s*)?\d+\s*(?:pack|pc|pcs|piece|pieces|count|ct)\b/g, ' ')
    .replace(/\b(?:two|three|four)\s*pack\b/g, ' ')
    .replace(/\s+/g, ' ')
    .trim();
}

// Phase 2 WS2 near-dup collapse: strip trailing ANNOTATION suffixes — test/copy
// markers like "(Copy_T1)", "[TEST]", "- sample 2" — while preserving genuine
// variant descriptors ("(Refill)", "(50ml)", "(SPF 50)", "(Shade 21)"). General
// by design (annotation keywords + short codes), not a Copy_T-specific hack.
const BEAUTY_TITLE_ANNOTATION_KEYWORDS =
  /\b(?:copy|copies|test|dupe?|duplicate|clone|sample|demo|draft|tmp|temp|qa|internal|staging|tripwire|do\s*not\s*(?:buy|use))\b/i;
const BEAUTY_TITLE_VARIANT_KEEP_GUARD =
  /\b(?:\d+(?:\.\d+)?\s*(?:ml|oz|g|gram|grams)|spf\s*\d+|refill|unscented|fragrance\s*free|travel|mini|shade|tone|no\.?\s*\d+)\b/i;
const BEAUTY_TITLE_ANNOTATION_SHORT_CODE = /^[a-z]{0,4}[\s_.-]*\d{1,4}$/i;

function stripBeautyTitleAnnotationSuffix(rawTitle = '') {
  let title = String(rawTitle || '').trim();
  if (!title) return '';
  for (let pass = 0; pass < 3; pass += 1) {
    let stripped = title;
    // Trailing bracketed group: (…) [TEST] {qa 2} — annotation keyword or short code.
    const bracket = stripped.match(/^(.{4,}?)\s*[([{]([^()[\]{}]{1,40})[)\]}]$/u);
    if (bracket) {
      const inner = String(bracket[2] || '').trim();
      // Underscore/dash are word characters, so "Copy_T1" would defeat \b
      // keyword matching — normalize separators before testing.
      const innerWords = inner.replace(/[_\-.]+/g, ' ').trim();
      if (
        !BEAUTY_TITLE_VARIANT_KEEP_GUARD.test(innerWords) &&
        (BEAUTY_TITLE_ANNOTATION_KEYWORDS.test(innerWords) ||
          BEAUTY_TITLE_ANNOTATION_SHORT_CODE.test(innerWords))
      ) {
        stripped = String(bracket[1] || '').trim();
      }
    }
    if (stripped === title) {
      // Bare trailing annotation: "… - copy 3", "…_test", "… sample 2".
      const bare = stripped.match(
        /^(.{8,}?)[\s_-]+(?:copy|copies|test|dupe?|duplicate|clone|sample|demo|draft|tmp|temp|qa)[\s_-]*[a-z]?\d{0,4}$/iu,
      );
      if (bare) stripped = String(bare[1] || '').trim();
    }
    if (stripped === title) break;
    title = stripped;
  }
  return title;
}

// Serving-time collapse of near-identical scored rows (post-score, post-sort, pre-
// display). Key = brand + annotation-stripped canonical title. The best-scored row
// per key keeps its position; the rest are DEMOTED below all distinct rows (not
// dropped — total stays stable and prompt-test reports ranked_below_page instead
// of a silent disappearance).
function collapseNearDuplicateScoredBeautyProducts(scoredRows = []) {
  const rows = Array.isArray(scoredRows) ? scoredRows : [];
  if (rows.length < 2) return { rows, collapsed_count: 0 };
  const seen = new Set();
  const distinct = [];
  const demoted = [];
  for (const row of rows) {
    const product = row && row.product ? row.product : {};
    const rawTitle = firstNonEmptyString(product.title, product.name, product.product_name, product.display_name) || '';
    const canonicalTitle = canonicalizeBeautyProductTitleForDedupe(stripBeautyTitleAnnotationSuffix(rawTitle));
    if (!canonicalTitle) {
      distinct.push(row);
      continue;
    }
    const brand = normalizeSearchTextForMatch(String(product.brand || product.vendor || '')) || 'unbranded';
    const key = `${brand}|${canonicalTitle}`;
    if (seen.has(key)) {
      const representative = distinct.find((kept) => kept.__near_dup_key === key);
      demoted.push({
        ...row,
        near_dup_demoted: true,
        near_dup_of:
          (representative &&
            firstNonEmptyString(
              representative.product?.pivota_signature_id,
              representative.product?.id,
              representative.product?.product_id,
            )) ||
          null,
      });
    } else {
      seen.add(key);
      distinct.push(Object.assign(row, { __near_dup_key: key }));
    }
  }
  for (const row of distinct) delete row.__near_dup_key;
  return { rows: [...distinct, ...demoted], collapsed_count: demoted.length };
}

function detectBeautyProductPackVariant(product = {}) {
  const rawTitle = [
      product.title,
      product.name,
      product.product_name,
      product.display_name,
      product.variant_title,
      product.option_title,
      product.options && JSON.stringify(product.options),
    ]
      .map((value) => String(value || '').trim())
      .filter(Boolean)
      .join(' ')
      .toLowerCase();
  const title = normalizeSearchTextForMatch(rawTitle);
  if (!title) {
    return {
      travel_size: false,
      jumbo_or_value: false,
      multi_pack: false,
      any: false,
    };
  }
  const volumeMlMatch = rawTitle.match(/\b(\d+(?:\.\d+)?)\s*(?:ml|m l)\b/);
  const smallMlSize = volumeMlMatch ? Number(volumeMlMatch[1]) > 0 && Number(volumeMlMatch[1]) <= 15 : false;
  const volumeOzMatch = rawTitle.match(/(?:^|\s)(?:fl\.?\s*)?(\d+(?:\.\d+)?|\.\d+)\s*(?:fl\.?\s*)?oz\b/);
  const smallOzSize = volumeOzMatch ? Number(volumeOzMatch[1]) > 0 && Number(volumeOzMatch[1]) <= 1 : false;
  const travelSize = /\b(?:travel\s*size|mini|trial\s*size|sample|portable)\b/.test(title) || /\b(?:travel\s*size|mini|trial\s*size|sample|portable)\b/.test(rawTitle) || smallMlSize || smallOzSize;
  const jumboOrValue = /\b(?:jumbo|supersize|super\s*size|value\s*size|value\s*pack|refill|full\s*size)\b/.test(title) || /\b(?:jumbo|supersize|super\s*size|value\s*size|value\s*pack|refill|full\s*size)\b/.test(rawTitle);
  const multiPack = /\b(?:double\s*pack|duo|bundle|set|pack\s*of\s*\d+|\d+\s*(?:pack|pc|pcs|piece|pieces|count|ct))\b/.test(title) || /\b(?:double\s*pack|duo|bundle|set|pack\s*of\s*\d+|\d+\s*(?:pack|pc|pcs|piece|pieces|count|ct))\b/.test(rawTitle);
  return {
    travel_size: travelSize,
    jumbo_or_value: jumboOrValue,
    multi_pack: multiPack,
    any: travelSize || jumboOrValue || multiPack,
  };
}

function dedupeBeautyProductsByDisplayKey(products = []) {
  const out = [];
  const seen = new Set();
  for (const product of Array.isArray(products) ? products : []) {
    if (!product || typeof product !== 'object') continue;
    const pick = (...values) =>
      values
        .map((value) => String(value || '').trim())
        .find(Boolean) || '';
    const rawTitle = pick(product.title, product.name, product.product_name, product.display_name);
    const title = normalizeSearchTextForMatch(rawTitle);
    const canonicalTitle = canonicalizeBeautyProductTitleForDedupe(rawTitle);
    const brand = normalizeSearchTextForMatch(pick(product.brand, product.vendor));
    const url = normalizeSearchTextForMatch(
      pick(product.canonical_url, product.destination_url, product.external_url, product.url),
    );
    const id = normalizeSearchTextForMatch(
      pick(product.product_id, product.id, product.external_seed_id, product.sku),
    );
    const key = (canonicalTitle || title)
      ? `title:${brand || 'unbranded'}:${canonicalTitle || title}`
      : url
        ? `url:${url}`
        : id
          ? `id:${id}`
          : '';
    if (key && seen.has(key)) continue;
    if (key) seen.add(key);
    out.push(product);
  }
  return out;
}

function isWeakSeoulLocalSunscreenDisplayCandidate(product = {}, queryText = '') {
  if (!hasKBeautyLocalIntent(queryText)) return false;
  if (!beautyProductMatchesFamily(product, 'sunscreen')) return false;
  if (beautyProductHasKBeautySignal(product)) return false;
  const text = buildFallbackCandidateText(product);
  if (!text) return false;
  const spfValue = extractBeautySpfValue(product);
  return (
    (spfValue && spfValue < 50) ||
    /\b(olay|glowscreen|supergoop|golden\s*hour|daily\s*facial\s*moisturi[sz]er|moisturi[sz]er\s+with\s+sunscreen|super\s*cream)\b/i.test(text)
  );
}

function beautyQueryNeedsGentleSensitiveSerum(queryText = '') {
  const raw = String(queryText || '');
  return (
    (
      /\b(sensitive|sensiti[sz]ed|reactive|stinging|burning|dry\s*sensitive|fragrance[-\s]?free|gentle|vitamin\s*c|l[-\s]?aa|brighten|brightening|dark\s*spot|alternative)\b/i.test(raw) ||
      /敏感|刺痛|干敏|乾敏|无香精|無香精|温和|溫和|维\s*c|維\s*c|提亮|替代/.test(raw)
    ) &&
    (
      /\b(serum|essence|ampoule|niacinamide|azelaic|tranexamic|vitamin\s*c|ascorbic|brighten|brightening)\b/i.test(raw) ||
      /精华|精華|煙酰胺|烟酰胺|壬二酸|传明酸|傳明酸|提亮/.test(raw)
    )
  );
}

function isWeakSensitiveHighStrengthSerumDisplayCandidate(product = {}, queryText = '') {
  if (!beautyQueryNeedsGentleSensitiveSerum(queryText)) return false;
  const text = buildBeautyProductSafetyText(product, buildFallbackCandidateText(product));
  if (!text) return false;
  if (
    !beautyProductMatchesFamily(product, 'serum') &&
    !/\b(serum|essence|ampoule|niacinamide|azelaic|tranexamic|ascorbic|vitamin\s*c|brightening)\b/i.test(text)
  ) {
    return false;
  }
  const explicitFreeClaims = /\b(fragrance\s*free|unscented|no\s+fragrance|without\s+fragrance|alcohol\s*free|no\s+alcohol|without\s+alcohol)\b|无香精|無香精|无酒精|無酒精/i.test(text);
  return (
    /\b(niacinamide\s*(?:10|15|20)(?:\s*%|\b)|(?:10|15|20)(?:\s*%|\b)\s*niacinamide|zinc\s*1\s*%)\b/i.test(text) ||
    /\b((?:l[-\s]?ascorbic|ascorbic\s+acid|vitamin\s*c).{0,24}(?:15|20|25)(?:\s*%|\b)|(?:15|20|25)(?:\s*%|\b).{0,24}(?:l[-\s]?ascorbic|ascorbic\s+acid|vitamin\s*c))\b/i.test(text) ||
    (
      /\b(alcohol\s*denat|denatured\s*alcohol|sd\s*alcohol|parfum|fragrance|essential\s*oil)\b|香精|香料|酒精/i.test(text) &&
      !explicitFreeClaims &&
      /\b(vitamin\s*c|ascorbic|brightening|active\s*serum)\b/i.test(text)
    )
  );
}

function beautyQueryNeedsPregnancySafeProduct(queryText = '') {
  return (
    /\b(pregnan\w*|pregnancy|trying\s*to\s*conceive|ttc|retinol[-\s]?free|retinoid[-\s]?free|avoid\s+retinoid|no\s+retinol)\b/i.test(String(queryText || '')) ||
    /怀孕|懷孕|备孕|備孕|孕期|不要视黄醇|不含视黄醇|避开视黄醇/i.test(String(queryText || ''))
  );
}

function isWeakPregnancyAntiAgingDisplayCandidate(product = {}, queryText = '') {
  if (!beautyQueryNeedsPregnancySafeProduct(queryText)) return false;
  if (!beautyProductMatchesFamily(product, 'serum') && !beautyProductMatchesFamily(product, 'moisturizer')) return false;
  const text = buildBeautyProductSafetyText(product, buildFallbackCandidateText(product));
  if (!text) return false;
  const antiAgingSurface =
    /\b(bouncy|firm|firming|lift|lifting|wrinkle|anti[-\s]?aging|anti[-\s]?ageing|collagen|elasticity|plump|plumping)\b|抗老|抗皱|抗皺|紧致|緊緻|提拉|胶原|膠原/i.test(text);
  if (!antiAgingSurface) return false;
  const pregnancyEvidence =
    /\b(pregnancy[-\s]?safe|pregnancy[-\s]?friendly|retinol[-\s]?free|retinoid[-\s]?free|no\s+retinol|without\s+retinol)\b/i.test(text) ||
    /\b(spf|sunscreen|mineral\s+sunscreen|azelaic)\b/i.test(text);
  return !pregnancyEvidence;
}

function filterWeakBeautyQualityDisplayCandidates(products = [], queryText = '', minUsefulCount = 4) {
  const list = Array.isArray(products) ? products : [];
  if (list.length <= minUsefulCount) return list;
  const filtered = list.filter(
    (product) =>
      !isWeakSensitiveHighStrengthSerumDisplayCandidate(product, queryText) &&
      !isWeakPregnancyAntiAgingDisplayCandidate(product, queryText),
  );
  return filtered.length >= minUsefulCount ? filtered : list;
}

function buildBeautyProductDiversitySignature(product = {}, queryText = '') {
  const text = buildFallbackCandidateText(product);
  if (!text) return '';
  if (!beautyProductMatchesFamily(product, 'moisturizer')) return '';
  const barrierOrRepairQuery =
    /\b(barrier|repair|moisturi[sz]er|cream|sensitive|travel|flight|dry)\b|屏障|修护|修護|保湿|保濕|面霜|敏感|旅行|飞行|飛行/i.test(String(queryText || ''));
  if (!barrierOrRepairQuery) return '';
  const clusters = [];
  if (/\bceramide|神经酰胺|神經醯胺/i.test(text)) clusters.push('ceramide');
  if (/\bpanthenol|b5|泛醇/i.test(text)) clusters.push('panthenol');
  if (/\bcica|centella|madecassoside|积雪草|積雪草/i.test(text)) clusters.push('cica');
  if (/\boat|oatmeal|colloidal|燕麦|燕麥/i.test(text)) clusters.push('oat');
  if (/\bpeptide\b|胜肽|勝肽|肽/i.test(text)) clusters.push('peptide');
  if (/\bhyaluronic|透明质酸|玻尿酸/i.test(text)) clusters.push('hyaluronic');
  if (/\bgel\s*cream|water\s*cream|lightweight|lotion\b/i.test(text)) clusters.push('light');
  if (/\brich|intense|balm|butter|heavy|occlusive\b/i.test(text)) clusters.push('rich');
  if (clusters.length >= 2) return `moisturizer:${clusters.slice(0, 3).join('+')}`;
  const title = canonicalizeBeautyProductTitleForDedupe(
    [
      product?.title,
      product?.name,
      product?.product_name,
      product?.display_name,
    ]
      .map((value) => String(value || '').trim())
      .filter(Boolean)
      .join(' '),
  )
    .replace(/\b(face|facial|skin|skincare|moisturi[sz]er|cream|barrier|repair|daily|with|for|the|a|an)\b/g, ' ')
    .replace(/\s+/g, ' ')
    .trim();
  return title ? `moisturizer:title:${title.split(/\s+/).slice(0, 5).join(' ')}` : '';
}

function diversifyBeautyProductDisplayList(products = [], queryText = '', safeLimit = 20) {
  const list = Array.isArray(products) ? products : [];
  if (list.length <= 3) return list;
  const limit = Math.max(1, Math.floor(Number(safeLimit) || 20));
  const minUsefulCount = Math.min(4, limit);
  const out = [];
  const overflow = [];
  const counts = new Map();
  for (const product of list) {
    const signature = buildBeautyProductDiversitySignature(product, queryText);
    if (!signature) {
      out.push(product);
      continue;
    }
    const count = counts.get(signature) || 0;
    if (count < 2) {
      counts.set(signature, count + 1);
      out.push(product);
    } else {
      counts.set(signature, count + 1);
      overflow.push(product);
    }
  }
  if (overflow.length === 0 || out.length < minUsefulCount) return list;
  return [...out, ...overflow];
}

function polishBeautyProductRankingForDisplay(products = [], queryText = '', safeLimit = 20) {
  const list = Array.isArray(products) ? products : [];
  if (list.length <= 1) return list;
  const limit = Math.max(1, Math.floor(Number(safeLimit) || 20));
  const queryHasTravelSizeNeed =
    /\b(travel|portable|carry\s*on|carryon|flight|mini|travel\s*size)\b|旅行|便携|便攜|小样|小樣/.test(String(queryText || ''));
  const polished = list.filter((product) => {
    const packVariant = detectBeautyProductPackVariant(product);
    if (queryHasTravelSizeNeed) {
      return !packVariant.jumbo_or_value && !packVariant.multi_pack;
    }
    return !packVariant.any;
  });
  const minUsefulCount = Math.min(4, limit);
  if (hasKBeautyLocalIntent(queryText)) {
    const localPolished = filterWeakBeautyQualityDisplayCandidates(
      polished.filter((product) => !isWeakSeoulLocalSunscreenDisplayCandidate(product, queryText)),
      queryText,
      minUsefulCount,
    );
    if (localPolished.length >= minUsefulCount) {
      return diversifyBeautyProductDisplayList(localPolished, queryText, limit);
    }
  }
  const qualityPolished = filterWeakBeautyQualityDisplayCandidates(polished, queryText, minUsefulCount);
  if (qualityPolished.length >= minUsefulCount) {
    return diversifyBeautyProductDisplayList(qualityPolished, queryText, limit);
  }
  if (hasKBeautyLocalIntent(queryText)) {
    const localList = filterWeakBeautyQualityDisplayCandidates(
      list.filter((product) => !isWeakSeoulLocalSunscreenDisplayCandidate(product, queryText)),
      queryText,
      minUsefulCount,
    );
    if (localList.length >= minUsefulCount) {
      return diversifyBeautyProductDisplayList(localList, queryText, limit);
    }
  }
  return diversifyBeautyProductDisplayList(list, queryText, limit);
}

function balanceBeautyMainlineFamilyCoverage(products = [], intent = null, safeLimit = 20) {
  const list = Array.isArray(products) ? products.slice() : [];
  const limit = Math.max(1, Math.floor(Number(safeLimit) || 20));
  const families = Array.isArray(intent?.families)
    ? intent.families.map((family) => String(family || '').trim()).filter(Boolean)
    : [];
  if (list.length <= 1 || families.length <= 1 || limit <= 1) return list;

  const head = list.slice(0, limit);
  const tail = list.slice(limit);
  for (const family of families) {
    if (head.some((product) => beautyProductMatchesFamily(product, family))) continue;
    const candidateIndex = tail.findIndex((product) => beautyProductMatchesFamily(product, family));
    if (candidateIndex < 0) continue;
    const candidate = tail.splice(candidateIndex, 1)[0];
    let replacementIndex = -1;
    for (let i = head.length - 1; i >= 0; i -= 1) {
      const matchedFamilies = families.filter((item) => beautyProductMatchesFamily(head[i], item));
      if (matchedFamilies.length !== 1) continue;
      const onlyFamily = matchedFamilies[0];
      const familyCount = head.filter((product) => beautyProductMatchesFamily(product, onlyFamily)).length;
      if (familyCount <= 1) continue;
      replacementIndex = i;
      break;
    }
    if (replacementIndex < 0) replacementIndex = Math.max(0, head.length - 1);
    const [removed] = head.splice(replacementIndex, 1, candidate);
    if (removed) tail.unshift(removed);
  }
  return [...head, ...tail];
}

function queryLooksLikeChinese(text = '') {
  return /[\u4e00-\u9fff]/.test(String(text || ''));
}

function inferTravelDestinationMarketFromQuery(queryText = '') {
  const raw = String(queryText || '');
  if (/\b(seoul|korea|south korea|busan)\b|首尔|首爾|韩国|韓國/i.test(raw)) return { market: 'KR', city: 'Seoul' };
  if (/\b(tokyo|osaka|kyoto|japan)\b|东京|東京|大阪|京都|日本/i.test(raw)) return { market: 'JP', city: 'Tokyo' };
  if (/\b(bangkok|thailand)\b|曼谷|泰国|泰國/i.test(raw)) return { market: 'TH', city: 'Bangkok' };
  if (/\b(shanghai|beijing|china)\b|上海|北京|中国|中國/i.test(raw)) return { market: 'CN', city: 'Shanghai' };
  if (/\b(reykjavik|iceland)\b|雷克雅未克|冰岛|冰島/i.test(raw)) return { market: 'IS', city: 'Reykjavik' };
  return { market: '', city: '' };
}

function hasTravelLocalQuerySignal(queryText = '') {
  return (
    /\b(travel|trip|flight|cabin|local|locally|seoul|korea|tokyo|bangkok|reykjavik|pack|packing|portable|travel[-\s]?size)\b/i.test(String(queryText || '')) ||
    /旅行|出发|出發|飞行|飛行|机舱|機艙|当地|本地|首尔|首爾|韩国|韓國|便携|便攜|行李|护肤包|護膚包/.test(String(queryText || ''))
  );
}

function buildBeautyTripContextReasonForResponse({ product, queryText, localAuthority, fitAttributes } = {}) {
  if (!hasTravelLocalQuerySignal(queryText)) return null;
  const lang = queryLooksLikeChinese(queryText) ? 'CN' : 'EN';
  const destination = inferTravelDestinationMarketFromQuery(queryText);
  const targetMarket = String(destination.market || '').trim().toUpperCase();
  const city = destination.city || (lang === 'CN' ? '当地' : 'the destination');
  const families = inferBeautyMainlineIntent(queryText).families || [];
  const hasDestinationPurchaseAuthority =
    targetMarket &&
    (
      (Array.isArray(localAuthority?.local_purchase_markets) && localAuthority.local_purchase_markets.includes(targetMarket)) ||
      String(product?.market || product?.merchant_market || '').trim().toUpperCase() === targetMarket
    );
  const hasDestinationBrandAuthority =
    targetMarket &&
    (
      String(localAuthority?.brand_home_market || '').trim().toUpperCase() === targetMarket ||
      String(localAuthority?.brand_origin_country || '').trim().toUpperCase() === targetMarket
    );
  const isLocalAuthority = hasDestinationPurchaseAuthority || hasDestinationBrandAuthority;
  const hasTravelSize = fitAttributes && fitAttributes.travel_size === true;
  const family = families.find((candidate) => beautyProductMatchesFamily(product, candidate)) || families[0] || '';

  if (lang === 'CN') {
    if (hasDestinationPurchaseAuthority && targetMarket === 'KR') {
      if (family === 'sunscreen') return `Seoul 当地购买理由：用于当地 UV、步行暴晒和补涂；商品带有 KR/韩国本地 authority 信号。`;
      if (family === 'cleanser') return `Seoul 当地购买理由：用于晚间清洁防晒、汗和 fine dust/城市污染残留；商品带有 KR/韩国本地 authority 信号。`;
      if (family === 'moisturizer') return `Seoul 当地购买理由：用于落地前 48 小时、口罩摩擦或泛红后的轻修护；商品带有 KR/韩国本地 authority 信号。`;
      return `Seoul 当地购买理由：只按真实缺口补买，商品带有 KR/韩国本地 authority 信号。`;
    }
    if (hasDestinationBrandAuthority && targetMarket === 'KR') {
      if (family === 'sunscreen') return `Seoul 候选核验理由：韩国品牌/韩妆 authority 信号适合到 Olive Young 或当地渠道先核验；当前商品 row 未确认 KR 本地库存，不包装成落地必买。`;
      if (family === 'cleanser') return `Seoul 候选核验理由：韩国品牌/韩妆 authority 信号适合晚间清洁防晒、汗和 fine dust 残留；当前商品 row 未确认 KR 本地库存，不包装成落地必买。`;
      if (family === 'moisturizer') return `Seoul 候选核验理由：韩国品牌/韩妆 authority 信号适合落地前 48 小时轻修护；当前商品 row 未确认 KR 本地库存，不包装成落地必买。`;
      return `Seoul 候选核验理由：韩国品牌/韩妆 authority 信号可作为当地柜台核验清单；当前商品 row 未确认 KR 本地库存。`;
    }
    if (isLocalAuthority) return `${city} 当地购买理由：商品带有目的地本地 authority 信号，只按旅行缺口补买。`;
    if (hasTravelSize) return `旅行携带理由：商品有 travel-size/便携证据，适合出发前带，避免落地前 48 小时临时试新品。`;
    return `旅行使用理由：按飞行、当地 UV/通勤和屏障稳定来筛选；若无本地 authority，不把它包装成 ${city} 当地必买。`;
  }

  if (hasDestinationPurchaseAuthority && targetMarket === 'KR') {
    if (family === 'sunscreen') return 'Seoul local reason: use for local UV, walking sun exposure, and reapplication; the product carries KR/Korea local authority signals.';
    if (family === 'cleanser') return 'Seoul local reason: use at night for SPF, sweat, and fine-dust/city-pollution residue; the product carries KR/Korea local authority signals.';
    if (family === 'moisturizer') return 'Seoul local reason: use during the first 48 hours after landing or after mask-friction redness; the product carries KR/Korea local authority signals.';
    return 'Seoul local reason: buy only for a real gap; the product carries KR/Korea local authority signals.';
  }
  if (hasDestinationBrandAuthority && targetMarket === 'KR') {
    if (family === 'sunscreen') return 'Seoul shortlist reason: Korean-brand authority makes it worth checking at Olive Young or local retailers for UV and reapplication; this row does not confirm KR local stock.';
    if (family === 'cleanser') return 'Seoul shortlist reason: Korean-brand authority fits evening SPF, sweat, and fine-dust residue cleansing; this row does not confirm KR local stock.';
    if (family === 'moisturizer') return 'Seoul shortlist reason: Korean-brand authority fits first-48-hour light repair; this row does not confirm KR local stock.';
    return 'Seoul shortlist reason: Korean-brand authority makes it a local-counter candidate to verify, not an automatic destination buy.';
  }
  if (isLocalAuthority) return `${city} local reason: the product carries destination-local authority signals and should only fill a real travel gap.`;
  if (hasTravelSize) return 'Travel-pack reason: travel-size/portable evidence makes it better suited to pack before departure instead of testing something new after landing.';
  return `Travel reason: screened for flight, local UV/transit, and barrier stability; without local authority, it is not presented as a ${city} local must-buy.`;
}

function buildBeautyTravelPurchaseBucketForResponse({ product, localAuthority, fitAttributes, queryText } = {}) {
  if (!hasTravelLocalQuerySignal(queryText)) return null;
  const destination = inferTravelDestinationMarketFromQuery(queryText);
  const targetMarket = String(destination.market || '').trim().toUpperCase();
  const hasDestinationPurchaseAuthority =
    targetMarket &&
    (
      (Array.isArray(localAuthority?.local_purchase_markets) && localAuthority.local_purchase_markets.includes(targetMarket)) ||
      String(product?.market || product?.merchant_market || '').trim().toUpperCase() === targetMarket
    );
  if (hasDestinationPurchaseAuthority) return 'buy_in_destination';
  const hasDestinationBrandAuthority =
    targetMarket &&
    (
      String(localAuthority?.brand_home_market || '').trim().toUpperCase() === targetMarket ||
      String(localAuthority?.brand_origin_country || '').trim().toUpperCase() === targetMarket
    );
  if (hasDestinationBrandAuthority) return 'check_in_destination';
  if (fitAttributes && fitAttributes.travel_size === true) return 'pack_before_flight';
  return 'pack_before_flight_or_travel_review';
}

function compactBeautyMainlineProductForResponse(product, intent = null, queryText = '') {
  if (!product || typeof product !== 'object' || Array.isArray(product)) return product;
  const localAuthority = buildBeautyProductLocalAuthorityForResponse(product);
  const fitAttributes = buildBeautyProductFitAttributesForResponse(product);
  const seedData = isPlainObject(product.seed_data) ? product.seed_data : {};
  const snapshot = isPlainObject(seedData.snapshot) ? seedData.snapshot : {};
  const recall = isPlainObject(product.external_seed_recall) ? product.external_seed_recall : {};
  const responseBrand = firstBrandDisplayString(
    seedData.brand_name,
    snapshot.brand_name,
    snapshot.brand,
    snapshot.vendor_name,
    snapshot.vendor,
    seedData.brand,
    seedData.vendor_name,
    seedData.vendor,
    recall.brand_name,
    recall.brand,
    product.brand,
    product.vendor,
  );
  const {
    seed_data: _seedData,
    external_seed_recall: _externalSeedRecall,
    extraction_debug: _extractionDebug,
    debug: _debug,
    raw: _raw,
    ...rest
  } = product;
  const next = { ...rest };
  if (responseBrand) {
    next.brand = responseBrand;
    next.vendor = responseBrand;
  }
  if (Array.isArray(next.images) && next.images.length > 4) next.images = next.images.slice(0, 4);
  if (Array.isArray(next.image_urls) && next.image_urls.length > 4) next.image_urls = next.image_urls.slice(0, 4);
  if (typeof next.description === 'string' && next.description.length > 520) {
    next.description = `${next.description.slice(0, 517).trimEnd()}...`;
  }
  if (intent && Array.isArray(intent.families) && intent.families.length === 1) {
    next.product_class = intent.families[0];
  }
  if (localAuthority) {
    next.local_authority = localAuthority;
  }
  if (fitAttributes) {
    next.fit_attributes = fitAttributes;
  }
  const tripContextReason = buildBeautyTripContextReasonForResponse({
    product,
    queryText,
    localAuthority,
    fitAttributes,
  });
  if (tripContextReason) {
    next.trip_context_reason = tripContextReason;
    next.travel_purchase_bucket = buildBeautyTravelPurchaseBucketForResponse({
      product,
      localAuthority,
      fitAttributes,
      queryText,
    }) || 'pack_before_flight_or_travel_review';
  }
  const recommendationReason = buildBeautyMainlineRecommendationReason(product, queryText, intent);
  if (recommendationReason) {
    next.recommendation_reason = recommendationReason;
    next.match_reason = recommendationReason;
    if (!next.card_highlight) next.card_highlight = recommendationReason;
    next.shopping_card = {
      ...(next.shopping_card && typeof next.shopping_card === 'object' ? next.shopping_card : {}),
      highlight: next.shopping_card?.highlight || recommendationReason,
      recommendation_reason: recommendationReason,
    };
    next.search_card = {
      ...(next.search_card && typeof next.search_card === 'object' ? next.search_card : {}),
      highlight_candidate: next.search_card?.highlight_candidate || recommendationReason,
      recommendation_reason: recommendationReason,
    };
  }
  return ensureSearchProductPdpOpen(next);
}

function filterBeautyMainlineProductsByQuery(products = [], queryText = '', options = {}) {
  const list = Array.isArray(products) ? products : [];
  const intent = inferBeautyMainlineIntent(queryText);
  if (!intent.beautyLike || list.length === 0) {
    return {
      products: list,
      applied: false,
      removed_count: 0,
      removed_contraindicated_count: 0,
      removed_class_mismatch_count: 0,
      target_families: intent.families,
      safety_rules: intent.safety,
    };
  }

  const strictClass = options.strictClass !== false;
  const out = [];
  let removedContra = 0;
  let removedClass = 0;
  for (const product of list) {
    if (isBeautyProductContraindicatedForQuery(product, queryText, intent)) {
      removedContra += 1;
      continue;
    }
    if (strictClass && intent.families.length > 0) {
      const familyMatch = intent.families.some((family) =>
        beautyProductMatchesFamily(product, family),
      );
      if (!familyMatch) {
        removedClass += 1;
        continue;
      }
    } else if (!hasBeautyCatalogProductSignal(buildFallbackCandidateText(product))) {
      removedClass += 1;
      continue;
    }
    out.push(product);
  }
  return {
    products: out,
    applied: true,
    removed_count: Math.max(0, list.length - out.length),
    removed_contraindicated_count: removedContra,
    removed_class_mismatch_count: removedClass,
    target_families: intent.families,
    safety_rules: intent.safety,
  };
}

function buildBeautyMainlineRetrievalQueries(queryText = '', intent = null) {
  const raw = String(queryText || '').trim();
  if (!raw) return [];
  const profile = intent || inferBeautyMainlineIntent(raw);
  const out = [];
  const seen = new Set();
  const push = (value) => {
    const text = String(value || '').trim();
    if (!text) return;
    const key = normalizeSearchTextForMatch(text);
    if (!key || seen.has(key)) return;
    seen.add(key);
    out.push(text);
  };
  push(raw);
  push(sanitizeSearchQueryForRelevance(raw));
  for (const family of profile.families) {
    if (family === 'sunscreen') {
      push('sunscreen SPF face lightweight');
      push('daily sunscreen SPF');
    } else if (family === 'cleanser') {
      push('gentle cleanser face wash');
      push('fragrance free gentle cleanser');
    } else if (family === 'moisturizer') {
      push('barrier repair moisturizer cream');
      push('fragrance free moisturizer ceramide');
    } else if (family === 'serum') {
      push('gentle brightening serum');
      push('niacinamide azelaic serum');
    }
  }
  if (profile.safety.includes('avoid_retinoids')) {
    push('pregnancy safe skincare brightening');
    push('retinol free brightening serum');
    push('daily sunscreen pregnancy safe');
  }
  if (profile.safety.includes('avoid_cooling_strong_cleanser')) {
    push('rosacea gentle cleanser fragrance free');
    push('sensitive skin cleanser');
  }
  if (profile.safety.includes('avoid_exfoliating_acids')) {
    push('barrier repair cream');
    push('gentle hydrating cleanser');
  }
  return out.slice(0, 8);
}

function getBeautyProductCategoryPathText(product = {}) {
  return beautyRelevanceGate.getProductCategoryPathText(product);
}

function beautyProductMatchesCategoryPathPrefix(product = {}, categoryPathPrefix = '') {
  return beautyRelevanceGate.productMatchesCategoryPathPrefix(product, categoryPathPrefix);
}

function beautyProductMatchesCategoryPathQuery(product = {}, queryText = '', categoryPathPrefix = '') {
  if (!categoryPathPrefix) return true;
  if (beautyProductMatchesCategoryPathPrefix(product, categoryPathPrefix)) return true;
  const text = buildFallbackCandidateText(product);
  if (!text) return false;
  const prefix = String(categoryPathPrefix || '').trim().toLowerCase();
  if (prefix.startsWith('beauty/makeup/lip')) {
    return /\b(lipsticks?|lip\s*sticks?|lip\s*colors?|lip\s*colours?|lip\s*tints?|lip\s*gloss(?:es)?|lip\s*liners?|lip\s*balms?|rouge)\b|口红|口紅|唇膏|唇釉|唇彩|唇线|唇線/i.test(text);
  }
  if (prefix.startsWith('beauty/makeup/eye')) {
    return /\b(mascara|eyeliner|eye\s*liner|eyeshadow|eye\s*shadow|brow|lash)\b|睫毛膏|眼线|眼線|眼影|眉笔|眉筆/i.test(text);
  }
  if (prefix.startsWith('beauty/makeup/face/blush') || prefix.startsWith('beauty/makeup/cheek')) {
    return /\b(blush|blusher|cheek\s*(?:color|colour|tint|stain|balm)?|liquid\s*blush|cream\s*blush|powder\s*blush|luminizer|highlighter)\b|腮红|腮紅/i.test(text);
  }
  if (prefix.startsWith('beauty/makeup/face')) {
    return /\b(foundation|concealer|primer|blush|bronzer|highlighter|setting\s*powder|powder|cushion)\b|粉底|遮瑕|妆前|妝前|腮红|腮紅|高光|修容|气垫|氣墊/i.test(text);
  }
  if (prefix.startsWith('beauty/fragrance')) {
    return /\b(fragrance|perfume|parfum|eau\s+de\s+parfum|eau\s+de\s+toilette|edt|edp|cologne|scent)\b|香水|香氛/i.test(text);
  }
  if (prefix.startsWith('beauty/skincare/treat')) {
    return /\b(serum|essence|ampoule|treatment|concentrate|booster|niacinamide|retinol|retinal|retinoid|vitamin\s*c|ascorbic|azelaic|salicylic|bha|aha|glycolic|lactic|peptide|zinc)\b|精华|精華|美容液|烟酰胺|煙酰胺|视黄醇|視黃醇|壬二酸|水杨酸|水楊酸/i.test(text);
  }
  if (prefix.startsWith('beauty/skincare/moisturize')) {
    return /\b(moisturi[sz]er|cream|lotion|gel\s*cream|barrier|balm)\b|面霜|乳液|保湿|保濕/i.test(text);
  }
  if (prefix.startsWith('beauty/skincare/cleanse')) {
    return /\b(cleanser|cleansing|face\s*wash|facial\s*wash|wash|cleansing\s*(?:foam|gel|milk|oil|balm))\b|洁面|潔面|洗顔/i.test(text);
  }
  if (prefix.startsWith('beauty/skincare/sun')) {
    return /\b(sunscreen|sun\s*screen|sunblock|spf\b|broad\s*spectrum|uv|uva|uvb)\b|防晒|防曬/i.test(text);
  }
  return hasBeautyCatalogProductSignal(text);
}

function hasStrictLipstickQueryIntent(queryText = '') {
  const raw = String(queryText || '');
  if (!raw) return false;
  if (/\b(lipsticks?|lip\s*sticks?)\b/i.test(raw) || /口红|口紅/.test(raw)) {
    return !/\b(lip\s*gloss(?:es)?|lip\s*oils?|lip\s*balms?|lip\s*treatments?|lip\s*masks?)\b/i.test(raw);
  }
  return false;
}

function beautyProductMatchesStrictLipstickIntent(product = {}) {
  const text = normalizeSearchTextForMatch([
    product?.title,
    product?.name,
    product?.product_name,
    product?.display_name,
    product?.canonical_url,
    product?.destination_url,
    product?.url,
    product?.merchant_canonical_url,
  ].filter(Boolean).join(' '));
  if (!text) return false;
  if (/\b(lip\s*oil|lip\s*balm|lip\s*treatment|lip\s*mask)\b/i.test(text)) return false;
  return /\b(lipstick|lip\s*stick|liquid\s*lip|lip\s*color|lip\s*colour|rouge)\b/i.test(text);
}

function beautyQueryHasAcneOilControlIntent(queryText = '') {
  return /\b(acne|blemish(?:es)?|breakouts?|pimples?|spots?|clog(?:ged)?\s*pores?|comedones?|oily|oil[-\s]?control|oilier|sebum|shine[-\s]?control|acne[-\s]?prone|breakout[-\s]?prone)\b|痘|粉刺|闭口|閉口|油皮|控油/i.test(
    String(queryText || ''),
  );
}

function beautyProductHasAcneOilControlEvidence(product = {}, candidateText = '') {
  const text = String(candidateText || buildFallbackCandidateText(product) || '');
  if (!text) return false;
  return /\b(acne|blemish(?:es)?|breakouts?|pimples?|spot[-\s]?treat(?:ment)?|clog(?:ged)?\s*pores?|comedones?|clarif(?:y|ying)|salicylic|azelaic|succinic|benzoyl\s*peroxide|adapalene|sulfur|bha\b|aha\b|niacinamide|zinc\s*pca|sebum|oil[-\s]?control|shine[-\s]?control|pore[-\s]?refin(?:e|ing)|non[-\s]?comedogenic|tea\s*tree|centella|cica|madecassoside|heartleaf|mugwort|clay)\b|痘|粉刺|闭口|閉口|控油|水杨酸|水楊酸|壬二酸|烟酰胺|煙酰胺|积雪草|積雪草/i.test(
    text,
  );
}

function buildBeautyMainlineRecommendationReason(product = {}, queryText = '', intent = null) {
  const text = buildFallbackCandidateText(product);
  if (!text) return '';
  const evidenceReasons = [];
  const matchReasons = [];
  const families = Array.isArray(intent?.families) ? intent.families : [];
  const normalizedQuery = normalizeSearchTextForMatch(queryText);
  const productBrand = firstNonEmptyString(product?.brand, product?.vendor, product?.merchant_name);
  const normalizedBrand = normalizeSearchTextForMatch(productBrand);
  const brandWasRequested = Boolean(
    normalizedBrand &&
      normalizedQuery &&
      normalizedQuery.includes(normalizedBrand),
  );
  if (beautyQueryHasAcneOilControlIntent(queryText) && beautyProductHasAcneOilControlEvidence(product, text)) {
    if (/\bazelaic\b/i.test(text)) evidenceReasons.push('azelaic-acid support for blemish-prone skin');
    else if (/\bsalicylic|bha\b/i.test(text)) evidenceReasons.push('BHA/salicylic support for clogged pores');
    else if (/\bniacinamide|zinc\s*pca|sebum|oil[-\s]?control|shine[-\s]?control|pore[-\s]?refin/i.test(text)) evidenceReasons.push('oil-control and pore-refining signals');
    else if (/\bcentella|cica|madecassoside|heartleaf|mugwort|tea\s*tree/i.test(text)) evidenceReasons.push('calming signals for breakout-prone skin');
    else evidenceReasons.push('acne or blemish-care match');
  }
  if (families.includes('sunscreen') && /\b(spf|sunscreen|broad\s*spectrum)\b/i.test(text)) {
    matchReasons.push('the SPF lane');
  } else if (families.includes('serum') && /\b(serum|essence|ampoule|solution|treatment)\b/i.test(text)) {
    matchReasons.push('the treatment step');
  } else if (families.includes('cleanser') && /\b(cleanser|cleansing|face\s*wash)\b/i.test(text)) {
    matchReasons.push('the cleanser step');
  } else if (families.includes('moisturizer') && /\b(moisturi[sz]er|cream|gel\s*cream|barrier|repair)\b/i.test(text)) {
    matchReasons.push('the moisturizer step');
  }
  if (hasStrictLipstickQueryIntent(queryText) && beautyProductMatchesStrictLipstickIntent(product)) {
    matchReasons.push(brandWasRequested && productBrand ? `${productBrand} lipstick request` : 'the lipstick request');
  } else {
    const categoryPathPrefix = resolveBeautyCategoryPathPrefixForQuery(queryText) || '';
    if (categoryPathPrefix && beautyProductMatchesCategoryPathPrefix(product, categoryPathPrefix)) {
      let categoryLabel = 'requested category';
      if (/fragrance/i.test(categoryPathPrefix)) categoryLabel = 'fragrance category';
      else if (/sunscreen|sun/i.test(categoryPathPrefix)) categoryLabel = 'SPF category';
      else if (/cleanser/i.test(categoryPathPrefix)) categoryLabel = 'cleanser category';
      else if (/moisturi[sz]er|cream/i.test(categoryPathPrefix)) categoryLabel = 'moisturizer category';
      else if (/makeup\/lip/i.test(categoryPathPrefix)) categoryLabel = 'lip category';
      matchReasons.push(`the ${categoryLabel}`);
    }
    if (brandWasRequested && productBrand) {
      matchReasons.push(`${productBrand} brand request`);
    }
  }
  const uniqueEvidence = Array.from(new Set(evidenceReasons)).slice(0, 2);
  const uniqueMatches = Array.from(new Set(matchReasons)).slice(0, 2);
  if (uniqueEvidence.length > 0 && uniqueMatches.length > 0) {
    return `Recommended because it has ${uniqueEvidence.join(' and ')} and matches ${uniqueMatches.join(' and ')}.`;
  }
  if (uniqueEvidence.length > 0) {
    return `Recommended because it has ${uniqueEvidence.join(' and ')}.`;
  }
  if (uniqueMatches.length > 0) {
    return `Recommended because it matches ${uniqueMatches.join(' and ')}.`;
  }
  return '';
}

