function scoreBeautyBrandBrowseCategoryPriority(product = {}, intent = null, candidateText = '') {
  const brandBrowse = intent?.brandBrowse || null;
  if (!brandBrowse || brandBrowse.contract !== 'brand_browse' || brandBrowse.brand_only === false) return 0;
  const brandKey = String(brandBrowse.brand_key || '').trim().toLowerCase();
  const text = normalizeSearchTextForMatch(
    [
      candidateText,
      buildBeautyProductPrimarySurfaceText(product),
      firstSearchProductCategoryPath(product),
      product?.category,
      product?.product_type,
    ]
      .filter(Boolean)
      .join(' '),
  );
  if (!text) return 0;

  const isMakeup =
    /\b(makeup|foundation|concealer|skin\s*tint|primer|powder|blush|bronzer|highlighter|lipstick|lip\s*gloss|lip\s*liner|mascara|eyeliner|eyeshadow|brow|eye\s*brightener)\b/.test(text) ||
    /\bbeauty\/makeup\b/.test(text);
  const isHair = /\b(hair|curl|shampoo|conditioner|scalp|frizz|heat\s*protectant|styling|leave[-\s]?in)\b/.test(text);
  const isFragrance = /\b(fragrance|perfume|parfum|cologne|eau\s+de|body\s*mist)\b/.test(text);
  const isSkincare = /\b(skincare|skin\s*care|cleanser|moisturi[sz]er|serum|sunscreen|spf|mask|toner|body\s*(?:cream|scrub|wash|lotion|oil|butter))\b/.test(text);
  const isSet = /\b(set|bundle|kit|duo|trio|routine|regimen|gift|collector|case|minis?|mystery\s*box|box)\b/.test(text);
  const isAccessory = /\b(accessory|tool|brush|case|mirror|pouch|bag|washcloth|delivery\s*protection|shipping\s*protection)\b/.test(text);
  const isLimitedOrPromo = /\b(arcane|mystery\s*box|collector|limited\s*edition|delivery\s*protection|shipping\s*protection)\b/.test(text);

  let score = 0;
  if (BEAUTY_BRAND_BROWSE_HAIR_BRAND_KEYS.has(brandKey)) {
    if (isHair) score += 34;
    if (isMakeup || isFragrance) score -= 16;
  } else if (BEAUTY_BRAND_BROWSE_FRAGRANCE_BRAND_KEYS.has(brandKey)) {
    if (isFragrance) score += 34;
    if (isHair || isSkincare) score -= 12;
  } else if (BEAUTY_BRAND_BROWSE_SKINCARE_BRAND_KEYS.has(brandKey)) {
    if (isSkincare) score += 34;
    if (isMakeup || isFragrance || isHair) score -= 14;
  } else {
    if (isMakeup) score += 38;
    if (isSkincare) score += 8;
    if (isFragrance) score += 4;
    if (isHair) score -= 18;
  }
  if (isSet) score -= 34;
  if (isAccessory) score -= 30;
  if (isLimitedOrPromo) score -= 44;
  return score;
}

// Phase 1 active-aware rank: a compact registry mapping an active/benefit the
// user can NAME in a query (queryForms) to the surface forms that prove a product
// delivers it (surfaceForms — ingredient names, including INCI forms that differ
// from the friendly word, e.g. soy -> "glycine soja"). Benefit concepts
// (concept:true) map to ACTIVE ingredient names rather than the benefit word, so a
// product that merely prints "firming" in its title does NOT match — only one whose
// actives actually firm (adenosine, collagen, peptides…). Gated by
// PIVOT_BEAUTY_ACTIVE_AWARE_RANK_ENABLED. See
// docs/find_products_multi_actives_recall_design.md.
const BEAUTY_ACTIVE_AWARE_RANK_WEIGHT = 44;
const BEAUTY_ACTIVE_AWARE_RANK_MAX_CONCEPTS = 3;
const BEAUTY_ACTIVE_CONCEPTS = [
  {
    key: 'soy',
    queryForms: ['soy', 'soya', 'soybean', 'isoflavone', 'isoflavones', 'genistein', 'daidzein'],
    surfaceForms: ['soy', 'soya', 'soybean', 'soja', 'glycine soja', 'glycine max', 'soymilk', 'soy milk', 'isoflavone', 'isoflavones', 'genistein', 'daidzein'],
  },
  { key: 'adenosine', queryForms: ['adenosine'], surfaceForms: ['adenosine'] },
  { key: 'collagen', queryForms: ['collagen'], surfaceForms: ['collagen', 'hydrolyzed collagen'] },
  { key: 'niacinamide', queryForms: ['niacinamide', 'vitamin b3'], surfaceForms: ['niacinamide', 'nicotinamide'] },
  {
    key: 'peptide',
    queryForms: ['peptide', 'peptides', 'tripeptide', 'tetrapeptide', 'hexapeptide', 'copper peptide'],
    surfaceForms: ['peptide', 'tripeptide', 'tetrapeptide', 'hexapeptide', 'palmitoyl', 'copper tripeptide'],
  },
  { key: 'retinol', queryForms: ['retinol', 'retinoid', 'retinal', 'vitamin a'], surfaceForms: ['retinol', 'retinal', 'retinyl', 'retinoid'] },
  { key: 'hyaluronic', queryForms: ['hyaluronic', 'hyaluron', 'hyaluronic acid'], surfaceForms: ['hyaluron', 'hyaluronate', 'hyaluronic'] },
  // Surface forms are whole normalized tokens (the matcher boundary-pads single
  // tokens), so use the real derivative roots — `ascorb*` as a bare fragment would
  // NOT match `ascorbyl` / `ascorbate` / `ascorbic acid` (the common Vit-C forms).
  { key: 'vitamin_c', queryForms: ['vitamin c', 'ascorbic', 'ascorbate'], surfaceForms: ['ascorbic', 'ascorbyl', 'ascorbate', 'vitamin c'] },
  { key: 'ceramide', queryForms: ['ceramide', 'ceramides'], surfaceForms: ['ceramide'] },
  { key: 'centella', queryForms: ['centella', 'cica', 'madecassoside'], surfaceForms: ['centella', 'cica', 'madecassoside', 'asiaticoside'] },
  {
    key: 'firming',
    concept: true,
    queryForms: ['firming', 'firm', 'firmness', 'elasticity', 'lifting', 'tightening', 'anti aging', 'antiaging', 'wrinkle'],
    surfaceForms: ['adenosine', 'collagen', 'peptide', 'tripeptide', 'tetrapeptide', 'hexapeptide', 'palmitoyl', 'retinol', 'retinal', 'isoflavone', 'genistein', 'idebenone', 'bakuchiol', 'elastin'],
  },
  {
    key: 'brightening',
    concept: true,
    queryForms: ['brightening', 'brighten', 'whitening', 'dark spot', 'glow'],
    surfaceForms: ['niacinamide', 'ascorbic', 'ascorbyl', 'ascorbate', 'vitamin c', 'arbutin', 'tranexamic', 'glutathione', 'kojic'],
  },
];

// Whitespace-padded substring test with a word boundary for single-token forms
// (so "soy" does not falsely match inside an unrelated token) and plain substring
// for multi-word forms (e.g. "glycine soja" inside a normalized ingredient list).
function beautyActiveTextHasForm(paddedNormalizedText, form) {
  const f = normalizeSearchTextForMatch(form);
  if (!f) return false;
  return paddedNormalizedText.includes(f.includes(' ') ? f : ` ${f} `);
}

// Concepts the user named in the query (active ingredients + benefit words).
function extractBeautyQueryActiveConcepts(queryText) {
  const normalized = normalizeSearchTextForMatch(queryText);
  if (!normalized) return [];
  const padded = ` ${normalized} `;
  return BEAUTY_ACTIVE_CONCEPTS.filter((concept) =>
    concept.queryForms.some((form) => beautyActiveTextHasForm(padded, form)),
  );
}

// All ingredient/active text already present on a mainline product object — across
// external-seed (ingredient_tokens / external_seed_recall) and canonical_chain
// (raw_ingredient_text_clean / ingredients_inci / active_ingredients / seed_data
// derived.recall) shapes. No DB read; purely re-uses fields the builders attach.
// includeTitleBrand (token-relevance flag) additionally counts the display title/
// brand as an actives surface, so "Vita Niacinamide Dark Spot Serum" earns the
// niacinamide concept even with no INCI/recall data. Benefit concepts (firming,
// brightening) are unaffected: their surfaceForms are ingredient names, so a title
// that merely prints the benefit word still matches nothing.
function buildBeautyActivesText(product, { includeTitleBrand = false } = {}) {
  if (!product || typeof product !== 'object') return '';
  const joinArr = (v) => (Array.isArray(v) ? v.join(' ') : typeof v === 'string' ? v : '');
  const recall =
    product.external_seed_recall && typeof product.external_seed_recall === 'object'
      ? product.external_seed_recall
      : product.seed_data &&
          product.seed_data.derived &&
          typeof product.seed_data.derived.recall === 'object'
        ? product.seed_data.derived.recall
        : null;
  const ing =
    product.ingredient_intel && typeof product.ingredient_intel === 'object' ? product.ingredient_intel : {};
  const parts = [
    joinArr(product.ingredient_tokens),
    recall ? joinArr(recall.ingredient_tokens) : '',
    recall ? joinArr(recall.alias_tokens) : '',
    recall ? recall.retrieval_summary : '',
    recall ? recall.retrieval_title : '',
    product.raw_ingredient_text_clean,
    product.pdp_ingredients_raw,
    product.pdp_active_ingredients_raw,
    joinArr(product.ingredients_inci),
    joinArr(product.active_ingredients),
    ing.raw_ingredient_text_clean,
    joinArr(ing.active_ingredients),
    product.description,
  ];
  if (includeTitleBrand) {
    parts.push(
      product.title,
      product.name,
      product.product_name,
      product.display_name,
      product.brand,
      product.vendor,
    );
  }
  const cleaned = parts.map((v) => String(v || '').trim()).filter(Boolean);
  return normalizeSearchTextForMatch(cleaned.join(' '));
}

// How many distinct query-named concepts the product's actives actually deliver.
function countBeautyActiveConceptMatches(queryText, product, options = {}) {
  const concepts = extractBeautyQueryActiveConcepts(queryText);
  if (!concepts.length) return { count: 0, keys: [] };
  const activesText = buildBeautyActivesText(product, options);
  if (!activesText) return { count: 0, keys: [] };
  const padded = ` ${activesText} `;
  const keys = [];
  for (const concept of concepts) {
    if (concept.surfaceForms.some((form) => beautyActiveTextHasForm(padded, form))) {
      keys.push(concept.key);
    }
  }
  return { count: keys.length, keys };
}

// Phase 2 WS2 token relevance: how much of the query's significant vocabulary the
// product's DISPLAY surface (title + brand) actually carries. Complements the
// active-concept bonus (which grounds in ingredient evidence): "Vita Niacinamide
// Dark Spot Serum" should not lose to a zero-token category-bucket row just
// because its INCI data is sparse. Pure, no DB.
const BEAUTY_TOKEN_RELEVANCE_PER_TOKEN = 26; // < one proven active concept (44)
const BEAUTY_TOKEN_RELEVANCE_MAX_TOKENS = 4; // per-token bonus cap: +104
const BEAUTY_TOKEN_RELEVANCE_ALL_TOKENS_BONUS = 48;
const BEAUTY_TOKEN_RELEVANCE_PHRASE_BONUS = 36;

function scoreBeautyQueryTokenRelevance({ product, queryTokens } = {}) {
  const empty = { matched: [], count: 0, bonus: 0, all_tokens: false, phrase: false };
  if (!product || typeof product !== 'object') return empty;
  const surface = normalizeSearchTextForMatch(
    [product.title, product.name, product.product_name, product.display_name, product.brand, product.vendor]
      .map((v) => String(v || '').trim())
      .filter(Boolean)
      .join(' '),
  );
  const significant = (Array.isArray(queryTokens) ? queryTokens : []).filter(
    (token) => typeof token === 'string' && token.length >= 3 && !SEARCH_QUERY_STOP_TOKENS.has(token),
  );
  if (!surface || !significant.length) return empty;
  const padded = ` ${surface} `;
  // Boundary-padded token presence with a cheap plural fold (spots -> spot).
  const hasToken = (token) =>
    padded.includes(` ${token} `) ||
    (token.endsWith('s') && token.length >= 4 && padded.includes(` ${token.slice(0, -1)} `));
  const matched = significant.filter(hasToken);
  if (!matched.length) return empty;
  let bonus = Math.min(BEAUTY_TOKEN_RELEVANCE_MAX_TOKENS, matched.length) * BEAUTY_TOKEN_RELEVANCE_PER_TOKEN;
  const allTokens = significant.length >= 2 && matched.length === significant.length;
  if (allTokens) bonus += BEAUTY_TOKEN_RELEVANCE_ALL_TOKENS_BONUS;
  // Phrase: any adjacent significant-token bigram of the query present verbatim
  // (with the same plural fold on the trailing token).
  let phrase = false;
  for (let i = 0; i + 1 < significant.length; i += 1) {
    const second = significant[i + 1];
    const bigram = ` ${significant[i]} ${second} `;
    const bigramSingular =
      second.endsWith('s') && second.length >= 4 ? ` ${significant[i]} ${second.slice(0, -1)} ` : null;
    if (padded.includes(bigram) || (bigramSingular && padded.includes(bigramSingular))) {
      phrase = true;
      break;
    }
  }
  if (phrase) bonus += BEAUTY_TOKEN_RELEVANCE_PHRASE_BONUS;
  return { matched, count: matched.length, bonus, all_tokens: allTokens, phrase };
}

// Relevance-order + near-dup-collapse a plain product array for the
// ingredient-recall-direct lane (which recalls + filters but never ranks). Pure:
// takes explicit flag booleans (not env) so it is unit-testable. Preserves the
// full set — reorders and demotes near-dups below distinct rows, never drops —
// so callers' `total`/pagination are unchanged. Both flags off ⇒ returns the
// input array reference unchanged (byte-identical prior behavior).
function reorderBeautyIngredientDirectProducts(
  products,
  {
    queryText = '',
    tokenRelevanceEnabled = false,
    nearDupCollapseEnabled = false,
    setDemotionEnabled = false,
  } = {},
) {
  const input = Array.isArray(products) ? products : [];
  if (
    (!tokenRelevanceEnabled && !nearDupCollapseEnabled && !setDemotionEnabled) ||
    input.length < 2
  ) {
    return {
      products: input,
      token_relevance_applied: false,
      near_dup_collapsed_count: 0,
      set_demoted_count: 0,
    };
  }
  let rows = input.map((product, idx) => ({ product, __recall_idx: idx }));
  let tokenRelevanceApplied = false;
  if (tokenRelevanceEnabled) {
    const queryTokens = Array.from(
      new Set(tokenizeSearchTextForMatch(normalizeSearchTextForMatch(queryText))),
    );
    rows = rows.map((row) => {
      const tokenRelevance = scoreBeautyQueryTokenRelevance({ product: row.product, queryTokens });
      const activeMatch = countBeautyActiveConceptMatches(queryText, row.product, {
        includeTitleBrand: true,
      });
      const relevanceScore =
        (tokenRelevance.bonus || 0) +
        Math.min(BEAUTY_ACTIVE_AWARE_RANK_MAX_CONCEPTS, activeMatch.count || 0) *
          BEAUTY_ACTIVE_AWARE_RANK_WEIGHT;
      // A row matching neither a query token nor a query-named active is demoted
      // below every row that matches something. A proven ingredient (via INCI)
      // counts, so rows recalled by ingredient evidence are never demoted.
      const tokenTier = tokenRelevance.count > 0 || (activeMatch.count || 0) > 0 ? 1 : 0;
      // A title carrying a stripped annotation (e.g. "(Copy_T1)") is a worse
      // representative than the clean original when scores tie — so near-dup
      // collapse (which keeps the first-seen per key) surfaces the clean row.
      const rawTitle =
        firstNonEmptyString(
          row.product?.title,
          row.product?.name,
          row.product?.product_name,
          row.product?.display_name,
        ) || '';
      const isAnnotatedTitle = stripBeautyTitleAnnotationSuffix(rawTitle) !== rawTitle;
      return { ...row, relevance_score: relevanceScore, token_tier: tokenTier, __annotated: isAnnotatedTitle };
    });
    // Stable reorder: tier, then relevance score, then clean-title-first (so the
    // near-dup representative is the un-annotated original), then recall order.
    rows.sort((left, right) => {
      if ((left.token_tier ?? 1) !== (right.token_tier ?? 1)) {
        return (right.token_tier ?? 1) - (left.token_tier ?? 1);
      }
      if ((right.relevance_score || 0) !== (left.relevance_score || 0)) {
        return (right.relevance_score || 0) - (left.relevance_score || 0);
      }
      if (Boolean(left.__annotated) !== Boolean(right.__annotated)) {
        return left.__annotated ? 1 : -1;
      }
      return left.__recall_idx - right.__recall_idx;
    });
    tokenRelevanceApplied = true;
  }
  let nearDupCollapsedCount = 0;
  if (nearDupCollapseEnabled) {
    const collapsed = collapseNearDuplicateScoredBeautyProducts(rows);
    rows = collapsed.rows;
    nearDupCollapsedCount = collapsed.collapsed_count;
  }
  // Multi-product bundles sink below single products — LAST, so it dominates
  // the other orderings for the one thing a category shopper cares about
  // (getting a product, not a kit). Stable within each group: relative order
  // from the steps above is preserved, and nothing is dropped, so `total` and
  // pagination are untouched. Skipped entirely when the query asked for a set.
  let setDemotedCount = 0;
  if (setDemotionEnabled && !queryWantsMultiProductSet(queryText)) {
    const marked = rows.map((row, idx) => ({
      row,
      idx,
      isSet: titleLooksLikeMultiProductSet(
        firstNonEmptyString(
          row.product?.title,
          row.product?.name,
          row.product?.product_name,
          row.product?.display_name,
        ) || '',
      ),
    }));
    setDemotedCount = marked.filter((entry) => entry.isSet).length;
    // Demote only when singles exist to take their place — an all-bundle result
    // set is better served in its recall order than reshuffled to no effect.
    if (setDemotedCount > 0 && setDemotedCount < marked.length) {
      marked.sort((left, right) => {
        if (left.isSet !== right.isSet) return left.isSet ? 1 : -1;
        return left.idx - right.idx;
      });
      rows = marked.map((entry) => entry.row);
    } else {
      setDemotedCount = 0;
    }
  }
  return {
    products: rows.map((row) => row.product),
    token_relevance_applied: tokenRelevanceApplied,
    near_dup_collapsed_count: nearDupCollapsedCount,
    set_demoted_count: setDemotedCount,
  };
}

// WS1 actives authoring (docs/find_products_multi_phase2_scope.md): ingredient
// SOURCE text — primary ingredient evidence only (INCI / active ingredients / raw
// ingredient text), deliberately EXCLUDING any already-authored derived.recall
// tokens so derivation grounds in real ingredients, not its own prior output.
function buildBeautyIngredientSourceText(product) {
  if (!product || typeof product !== 'object') return '';
  const joinArr = (v) => (Array.isArray(v) ? v.join(' ') : typeof v === 'string' ? v : '');
  const ing = product.ingredient_intel && typeof product.ingredient_intel === 'object' ? product.ingredient_intel : {};
  const parts = [
    joinArr(product.ingredients_inci),
    joinArr(product.active_ingredients),
    product.raw_ingredient_text_clean,
    product.pdp_ingredients_raw,
    product.pdp_active_ingredients_raw,
    ing.raw_ingredient_text_clean,
    joinArr(ing.active_ingredients),
    joinArr(ing.inci_list),
    product.description,
  ]
    .map((v) => String(v || '').trim())
    .filter(Boolean);
  return normalizeSearchTextForMatch(parts.join(' '));
}

// Derive searchable actives for a product from its ingredient evidence, reusing the
// Phase-1 concept registry so authoring and matching share one taxonomy. Returns
// friendly ingredient_tokens + alias_tokens (incl. the INCI surface forms) + the
// matched concept set + per-concept evidence. Pure / no DB; persisting these into
// derived.recall is a separate, gated write step (WS1 increment 2).
function deriveBeautyRecallActives(product) {
  const empty = { ingredient_tokens: [], alias_tokens: [], concepts: [], evidence: [], source_chars: 0 };
  const text = buildBeautyIngredientSourceText(product);
  if (!text) return empty;
  const padded = ` ${text} `;
  const ingredientTokens = new Set();
  const aliasTokens = new Set();
  const concepts = [];
  const evidence = [];
  for (const concept of BEAUTY_ACTIVE_CONCEPTS) {
    const matched = concept.surfaceForms.filter((f) => beautyActiveTextHasForm(padded, f));
    if (!matched.length) continue;
    concepts.push(concept.key);
    evidence.push({ concept: concept.key, matched });
    // Benefit concepts (firming/brightening) describe the product but are not
    // ingredients — keep them in `concepts` only, out of the ingredient tokens.
    if (!concept.concept) {
      ingredientTokens.add(concept.key.replace(/_/g, ' '));
      concept.queryForms.forEach((q) => aliasTokens.add(q));
      matched.forEach((m) => aliasTokens.add(m));
    }
  }
  return {
    ingredient_tokens: Array.from(ingredientTokens),
    alias_tokens: Array.from(aliasTokens),
    concepts,
    evidence,
    source_chars: text.length,
  };
}

function scoreBeautyExternalSeedProduct({
  product,
  queryText,
  intent,
  normalizedQuery,
  queryTokens,
  searchQualityContract = null,
}) {
  const candidateText = buildFallbackCandidateText(product);
  if (!candidateText) return { product, relevant: false, score: -100 };
  const contractGate = getSearchQualityContractHardConstraintResult(product, searchQualityContract, queryText);
  if (!contractGate.eligible) {
    return {
      product,
      relevant: false,
      score: -100,
      rejection_reasons: contractGate.reasons,
      search_quality_rejected: true,
    };
  }
  if (!searchProductMatchesBeautyBrandBrowse(product, intent?.brandBrowse, candidateText)) {
    return { product, relevant: false, score: -90 };
  }
  if (isBeautyProductContraindicatedForQuery(product, queryText, intent)) {
    return { product, relevant: false, score: -100 };
  }

  const targetFamilies = Array.isArray(intent?.families) ? intent.families : [];
  const familyMatches = targetFamilies.filter((family) => beautyProductMatchesFamily(product, family));
  const categoryPathPrefix = resolveBeautyCategoryPathPrefixForQuery(queryText) || '';
  const explicitCategoryPathQuery = Boolean(categoryPathPrefix && targetFamilies.length === 0);
  const categoryPathMatch = beautyProductMatchesCategoryPathPrefix(product, categoryPathPrefix);
  const categoryLexicalMatch = explicitCategoryPathQuery
    ? beautyProductMatchesCategoryPathQuery(product, queryText, categoryPathPrefix)
    : false;
  const acneOilControlIntent = beautyQueryHasAcneOilControlIntent(queryText);
  const acneOilControlEvidence = acneOilControlIntent
    ? beautyProductHasAcneOilControlEvidence(product, candidateText)
    : false;
  const primarySurfaceText = buildBeautyProductPrimarySurfaceText(product);
  if (
    acneOilControlIntent &&
    !acneOilControlEvidence &&
    /\b(body\s*mist|fragrance|perfume|parfum|cologne|hair|scalp|hand\s*(?:cream|mask|lotion)|lip\s*(?:balm|oil|mask|treatment))\b/i.test(primarySurfaceText)
  ) {
    return { product, relevant: false, score: -48 };
  }
  if (
    acneOilControlIntent &&
    !/\b(body|back\s*acne|chest\s*acne|body\s*acne|body\s*breakout)\b/i.test(String(queryText || '')) &&
    /\bbody\s*(?:mist|scrub|wash|cleanser|cream|lotion|oil|milk|butter|polish)\b/i.test(primarySurfaceText)
  ) {
    return { product, relevant: false, score: -49 };
  }
  if (
    acneOilControlIntent &&
    !/\b(routine|regimen|set|kit|bundle|duo|trio)\b/i.test(String(queryText || '')) &&
    /\b(routine|regimen|starter\s*kit|kit|set|bundle|duo|trio)\b/i.test(primarySurfaceText)
  ) {
    return { product, relevant: false, score: -49 };
  }
  if (targetFamilies.length > 0 && familyMatches.length === 0) {
    return { product, relevant: false, score: -40 };
  }
  if (explicitCategoryPathQuery && !categoryPathMatch && !categoryLexicalMatch) {
    return { product, relevant: false, score: -45 };
  }
  if (hasStrictLipstickQueryIntent(queryText) && !beautyProductMatchesStrictLipstickIntent(product)) {
    return { product, relevant: false, score: -55 };
  }
  if (targetFamilies.length === 0 && !hasBeautyCatalogProductSignal(candidateText)) {
    return { product, relevant: false, score: -30 };
  }

  let score = 0;
  if (normalizedQuery && candidateText.includes(normalizedQuery)) score += 32;
  const productBrand = normalizeSearchTextForMatch(
    firstNonEmptyString(product?.brand, product?.vendor, product?.merchant_name),
  );
  if (
    productBrand &&
    normalizedQuery &&
    (normalizedQuery.includes(productBrand) || productBrand.includes(normalizedQuery))
  ) {
    score += 220;
  }
  if (categoryPathMatch) score += 140;
  else if (categoryLexicalMatch) score += 64;
  if (acneOilControlIntent) {
    if (acneOilControlEvidence) {
      score += 72;
      if (/\b(azelaic|salicylic|bha\b|benzoyl\s*peroxide|adapalene|succinic|sulfur)\b/i.test(candidateText)) score += 18;
      if (/\b(niacinamide|zinc\s*pca|sebum|oil[-\s]?control|shine[-\s]?control|pore[-\s]?refin)\b/i.test(candidateText)) score += 14;
      if (/\b(non[-\s]?comedogenic|lightweight|gel|fluid)\b/i.test(candidateText)) score += 8;
    } else {
      score -= categoryPathMatch || categoryLexicalMatch ? 110 : 50;
    }
  }
  if (String(product?.source || product?.search_recall_source || product?.catalog_source || '') === 'canonical_chain') {
    score += 24;
  }
  const sourceProductId = String(
    firstNonEmptyString(
      product?.source_product_id,
      product?.external_product_id,
      product?.external_seed_product_id,
      product?.platform_product_id,
    ) || '',
  );
  const quality = getSearchProductServingEligibility(product, { requireBeauty: false });
  const qualityReasons = new Set(Array.isArray(quality.reasons) ? quality.reasons : []);
  if (qualityReasons.has('missing_image')) score -= 34;
  else score += 18;
  if (qualityReasons.has('non_positive_price')) score -= 44;
  else if (qualityReasons.has('missing_price')) score -= 18;
  else score += 16;
  if (qualityReasons.has('generic_category')) score -= 18;
  if (qualityReasons.has('unresolved_pdp_ref')) score -= 28;
  if (qualityReasons.has('non_beauty_product')) score -= 22;
  if (hasOfferProductTransactionHold(product)) score -= 80;
  if (/^ext_[a-z0-9]+$/i.test(sourceProductId)) score += 12;
  if (!/^ext_[a-z0-9]+$/i.test(sourceProductId) && qualityReasons.size > 0) score -= 18;
  score += scoreBeautyBrandBrowseCategoryPriority(product, intent, candidateText);
  score += familyMatches.length * 24;
  const bucket = classifyBeautyBucketFromText(candidateText);
  if (bucket === 'skincare' && !explicitCategoryPathQuery) score += 12;
  if ((bucket === 'makeup' || bucket === 'fragrance') && explicitCategoryPathQuery) score += 10;
  if (bucket === 'bodycare' && targetFamilies.includes('moisturizer')) score += 4;
  if (intent?.safety?.includes('avoid_retinoids') && /\b(retinol[-\s]?free|retinoid[-\s]?free|pregnancy[-\s]?safe)\b/i.test(candidateText)) {
    score += 16;
  }
  if (intent?.safety?.includes('avoid_cooling_strong_cleanser') && /\b(fragrance[-\s]?free|gentle|sensitive|soap[-\s]?free)\b/i.test(candidateText)) {
    score += 12;
  }
  if (intent?.safety?.includes('avoid_exfoliating_acids') && /\b(barrier|repair|ceramide|panthenol|cica|gentle|hydrating)\b/i.test(candidateText)) {
    score += 12;
  }
  if (hasKBeautyLocalIntent(queryText)) {
    if (beautyProductHasKBeautySignal(product)) score += 18;
    else score -= 6;
  }
  const queryHasTravelSizeNeed =
    /\b(travel|portable|carry\s*on|carryon|flight|mini|travel\s*size)\b|旅行|便携|便攜|小样|小樣/.test(String(queryText || ''));
  const packVariant = detectBeautyProductPackVariant(product);
  if (packVariant.travel_size) score += queryHasTravelSizeNeed ? 12 : -7;
  if (packVariant.jumbo_or_value) score += queryHasTravelSizeNeed ? -12 : -8;
  if (packVariant.multi_pack) score += -8;
  const pregnancyOrRetinolFreeContext =
    intent?.safety?.includes('avoid_retinoids') ||
    /\b(pregnan\w*|ttc|trying\s*to\s*conceive|retinol[-\s]?free)\b|备孕|備孕|怀孕|懷孕|孕期/i.test(String(queryText || ''));
  if (pregnancyOrRetinolFreeContext) {
    if (/\b(spf|sunscreen|azelaic|niacinamide|peptide|ceramide|panthenol|barrier|repair|moisturi[sz]er)\b/i.test(candidateText)) {
      score += 10;
    }
    if (/\b(resurfacing|pore\s*refine|clarifying|peel|peeling|exfoliating|aha|bha|salicylic|glycolic|lactic|mandelic)\b/i.test(candidateText)) {
      score -= 18;
    }
  }
  if (
    /\b(sensitive|sensiti[sz]ed|fragrance\s*free|gentle)\b|敏感|温和|溫和|无香精|無香精/i.test(String(queryText || '')) &&
    /\b(fragrance|parfum|perfume|essential\s*oil|alcohol\s*denat|denatured\s*alcohol)\b|香精|香料|酒精/.test(candidateText) &&
    !/\b(fragrance\s*free|unscented|no\s*fragrance|without\s*fragrance|alcohol\s*free|no\s*alcohol|without\s*alcohol)\b|无香精|無香精|无酒精|無酒精/.test(candidateText)
  ) {
    score -= 16;
  }
  if (
    /\b(sensitive|sensiti[sz]ed|gentle|fragrance[-\s]?free|dry\s*sensitive)\b|敏感|温和|溫和|无香精|無香精|干敏|乾敏/i.test(String(queryText || '')) &&
    /\b(?:niacinamide|azelaic|ascorbic|vitamin\s*c|glycolic|salicylic|lactic|mandelic)\b.{0,24}\b(?:1[0-9]|[2-9][0-9])(?:\.\d+)?(?:\s*%|\b)|\b(?:1[0-9]|[2-9][0-9])(?:\.\d+)?(?:\s*%|\b)\s*(?:niacinamide|azelaic|ascorbic|vitamin\s*c|glycolic|salicylic|lactic|mandelic)\b/i.test(candidateText)
  ) {
    score -= 24;
  }
  if (
    /\b(brighten|brightening|dark\s*spot|uneven\s*tone|vitamin\s*c|azelaic|niacinamide|tranexamic)\b|提亮|淡斑|烟酰胺|煙酰胺|壬二酸|传明酸|傳明酸/i.test(String(queryText || '')) &&
    /\b(niacinamide|azelaic|tranexamic|ascorbyl|vitamin\s*c|brighten|brightening|dark\s*spot)\b|烟酰胺|煙酰胺|壬二酸|传明酸|傳明酸|提亮/i.test(candidateText)
  ) {
    score += 8;
  }
  score += scoreBeautyStrictQualityOverlay({ product, queryText, intent });
  const overlap = (Array.isArray(queryTokens) ? queryTokens : []).filter(
    (token) => token.length >= 3 && candidateText.includes(token),
  ).length;
  score += Math.min(18, overlap * 3);
  let tokenRelevance = null;
  if (PIVOT_BEAUTY_TOKEN_RELEVANCE_RANK_ENABLED) {
    tokenRelevance = scoreBeautyQueryTokenRelevance({ product, queryTokens });
    score += tokenRelevance.bonus;
  }
  score += scoreBeautySearchQualityContract({
    product,
    contract: searchQualityContract,
    queryText,
    baseScore: score,
  });
  // activeMatch is needed even when the Phase-1 rank flag is off: the token tier
  // must never demote an ingredient-proven product (e.g. the Aruen pilot, whose
  // actives live in INCI text, not its title).
  let activeMatch = null;
  if (PIVOT_BEAUTY_ACTIVE_AWARE_RANK_ENABLED || PIVOT_BEAUTY_TOKEN_RELEVANCE_RANK_ENABLED) {
    activeMatch = countBeautyActiveConceptMatches(queryText, product, {
      includeTitleBrand: PIVOT_BEAUTY_TOKEN_RELEVANCE_RANK_ENABLED,
    });
  }
  // Tier 1 = carries query vocabulary (title/brand tokens) or delivers a query-
  // named active; tier 0 = pure category-bucket filler. Sorted tier-first so a
  // zero-token blusher can never outrank a token-matched serum. Flag off => every
  // row is tier 1 (comparator byte-identical to today).
  const tokenTier = !PIVOT_BEAUTY_TOKEN_RELEVANCE_RANK_ENABLED
    ? 1
    : (tokenRelevance && tokenRelevance.count > 0) || (activeMatch && activeMatch.count > 0)
      ? 1
      : 0;
  const tokenFields = PIVOT_BEAUTY_TOKEN_RELEVANCE_RANK_ENABLED
    ? { token_relevance: tokenRelevance, token_tier: tokenTier }
    : {};
  if (PIVOT_BEAUTY_ACTIVE_AWARE_RANK_ENABLED && activeMatch && activeMatch.count > 0) {
    const activeBonus =
      Math.min(BEAUTY_ACTIVE_AWARE_RANK_MAX_CONCEPTS, activeMatch.count) *
      BEAUTY_ACTIVE_AWARE_RANK_WEIGHT;
    score += activeBonus;
    return {
      product,
      relevant: true,
      score,
      active_match: { count: activeMatch.count, keys: activeMatch.keys, bonus: activeBonus },
      ...tokenFields,
    };
  }
  return { product, relevant: true, score, ...tokenFields };
}

// WS3a operator prompt-test (docs/find_products_multi_phase2_scope.md). These two
// helpers power GET /api/admin/find-products-prompt-test and the no-op-by-default
// `inspectProductId` hook inside searchBeautyExternalSeedProductsMainline below;
// they never run for normal find_products_multi traffic.
function mainlineProductMatchesId(product, wantedId) {
  if (!product || typeof product !== 'object' || wantedId == null) return false;
  const id = String(wantedId).trim();
  if (!id) return false;
  const candidates = [
    product.pivota_signature_id, product.signature_id, product.id, product.product_id,
    product.content_key, product.source_product_id, product.external_product_id,
    product.external_seed_product_id, product.platform_product_id,
    product.catalog_product_key, product.product_key,
  ];
  return candidates.some((v) => v != null && String(v).trim() === id);
}

// Operator-friendly one-word verdict derived from a prompt_inspect payload.
function diagnosePromptInspect(inspect) {
  if (!inspect || typeof inspect !== 'object') return 'unknown';
  if (inspect.display_rank && inspect.in_visible_page) return 'ranked_visible';
  if (inspect.display_rank) return 'ranked_below_page';
  if (inspect.relevant === false) return 'recalled_but_rejected';
  if (!inspect.in_recall_pool) return 'not_recalled';
  return 'recalled_not_served';
}

async function searchBeautyExternalSeedProductsMainline({
  search = {},
  metadata = {},
  intent = null,
  creatorScoped = false,
  inspectProductId = null,
} = {}) {
  if (!PIVOT_BEAUTY_DIRECT_INDEXED_RECALL_ENABLED) return null;
  if (!process.env.DATABASE_URL) return null;
  const queryUnderstanding =
    search?.query_understanding && typeof search.query_understanding === 'object'
      ? search.query_understanding
      : metadata?.query_understanding && typeof metadata.query_understanding === 'object'
        ? metadata.query_understanding
        : null;
  const rawQueryText = extractSearchQueryText(search);
  const market =
    String(search.market || metadata.market || process.env.CREATOR_CATEGORIES_EXTERNAL_SEED_MARKET || 'US')
      .trim()
      .toUpperCase() || 'US';
  const requestSearchQualityContract =
    search?.search_quality_contract &&
    typeof search.search_quality_contract === 'object' &&
    !Array.isArray(search.search_quality_contract)
      ? search.search_quality_contract
      : metadata?.search_quality_contract &&
          typeof metadata.search_quality_contract === 'object' &&
          !Array.isArray(metadata.search_quality_contract)
        ? metadata.search_quality_contract
        : null;
  const searchQualityContract = SEARCH_QUALITY_CONTRACT_V1_ENABLED
    ? requestSearchQualityContract ||
      buildSearchQualityContract({
          rawQuery: rawQueryText,
          market,
          source: metadata?.source || search?.source || null,
          allowContextBinding: false,
        })
    : null;
  const searchQualityContractApplied = isBeautySearchQualityContractApplied(searchQualityContract);
  const searchQualityEnforced =
    searchQualityContractApplied && SEARCH_QUALITY_CONTRACT_V1_MODE === 'enforce';
  const safeLimit = Math.max(1, Math.min(SEARCH_LIMIT_MAX, Math.floor(Number(search.limit || 20) || 20)));
  const safePage = Math.max(1, Math.floor(Number(search.page || 1) || 1));
  const safeOffset = Math.max(
    0,
    Number.isFinite(Number(search.offset))
      ? Math.floor(Number(search.offset))
      : (safePage - 1) * safeLimit,
  );
  const contractSafeEmpty = isSearchQualityContractSafeEmptyContract(searchQualityContract);
  if (contractSafeEmpty) {
    return {
      status: 'success',
      success: true,
      products: [],
      total: 0,
      page: safePage,
      page_size: 0,
      reply: searchQualityContract?.clarification_allowed
        ? 'Please search for a product, brand, category, or skin concern.'
        : null,
      metadata: {
        ...buildInvokeSearchRailMetadata('authoritative_shopping'),
        query_source: 'search_quality_contract_v1_safe_empty',
        fetched_at: new Date().toISOString(),
        ...(queryUnderstanding
          ? {
              query_understanding: queryUnderstanding,
              query_understanding_executed: true,
              query_understanding_decision: queryUnderstanding.decision || null,
            }
          : {}),
        search_quality_contract: projectSearchQualityContractForMetadata(searchQualityContract),
        search_quality_contract_applied: false,
        search_quality_contract_mode: SEARCH_QUALITY_CONTRACT_V1_MODE,
        search_quality_failure_reasons: {},
        search_quality_tier_counts: {
          input_count: 0,
          canonical_chain_count: 0,
          external_seed_count: 0,
          hard_constraint_pass_count: 0,
          hard_constraint_reject_count: 0,
          serving_eligible_count: 0,
          missing_image_count: 0,
          invalid_price_count: 0,
          no_offer_derived_price_count: 0,
          missing_or_unresolved_pdp_count: 0,
          polluted_or_unavailable_count: 0,
        },
        source_breakdown: {
          internal_count: 0,
          external_seed_count: 0,
          canonical_chain_count: 0,
          canonical_chain_candidate_count: 0,
          stale_cache_used: false,
          strategy_applied: 'search_quality_contract_v1_safe_empty',
        },
        search_decision: {
          final_decision: searchQualityContract?.clarification_allowed ? 'clarify' : 'strict_empty',
          decision_authority: 'search_quality_contract_v1',
          query_target_domain: searchQualityContract.target_domain || null,
          decision_locked: true,
          decision_lock_reason: 'search_quality_contract_ambiguous_or_non_shopping',
        },
        route_health: {
          primary_path_used: 'search_quality_contract_v1_safe_empty',
          fallback_triggered: false,
          fallback_reason: null,
          canonical_path_executed: false,
          final_returned_count: 0,
          search_quality_contract_applied: false,
          search_quality_contract_mode: SEARCH_QUALITY_CONTRACT_V1_MODE,
        },
        route_debug: {
          beauty_external_seed_mainline: {
            attempted: false,
            skipped_reason: 'search_quality_contract_ambiguous_or_non_shopping',
          },
        },
        proxy_search_fallback: {
          applied: false,
          reason: null,
        },
        contract_bridge: {
          legacy_fallback: false,
        },
      },
    };
  }
  const queryText =
    (searchQualityContractApplied && searchQualityContract?.effective_query) ||
    rawQueryText;
  const beautyIntent = inferBeautyMainlineIntent(queryText);
  const effectiveSearchQualityContract = relaxSearchQualityContractForMultiFamilyBeautyIntent(
    searchQualityContract,
    beautyIntent,
  );
  const searchQualityContractRelaxedForMultiFamily = Boolean(
    effectiveSearchQualityContract &&
      searchQualityContract &&
      effectiveSearchQualityContract !== searchQualityContract,
  );
  if (
    (!beautyIntent.beautyLike && !searchQualityContractApplied) ||
    !String(queryText || '').trim()
  ) {
    return null;
  }

  const inStockOnly = parseQueryBoolean(search.in_stock_only ?? search.inStockOnly) !== false;
  const retrievalQueries = buildBeautyMainlineRetrievalQueries(queryText, beautyIntent);
  const perQueryLimit = searchQualityContractApplied
    ? Math.max(safeLimit * 2, Math.min(48, safeLimit * 4))
    : Math.max(safeLimit, Math.min(24, safeLimit * 2));
  const canonicalCategoryPathPrefix = searchQualityContractApplied
    ? (searchQualityContract?.hard_constraints?.category_path_prefix || null)
    : (resolveBeautyCategoryPathPrefixForQuery(queryText) || null);
  const canonicalBrandFilter = buildCanonicalBrandFilterForBeautyRecall(
    searchQualityContractApplied ? effectiveSearchQualityContract : null,
    beautyIntent.brandBrowse,
  );
  const canonicalQueryText = buildCanonicalQueryTextForBeautyBrandRecall(
    queryText,
    beautyIntent.brandBrowse,
    canonicalCategoryPathPrefix,
  );
  const canonicalLimit = searchQualityContractApplied
    ? Math.max(18, Math.min(48, safeLimit * 4))
    : Math.max(6, Math.min(12, Math.ceil(safeLimit / 2)));
  const canonicalStartedAt = Date.now();
  const canonicalRowsPromise = fetchCanonicalChainRows({
    query: canonicalQueryText,
    categoryPathPrefix: canonicalCategoryPathPrefix,
    // Deliberate category-browse: mainline recalls the bucket and then runs
    // its own relevance gate (scoreBeautyMainlineProduct + relevant===true),
    // which is what masks bucket noise on this lane.
    //
    // The "burns its candidate budget on bucket rows" follow-up noted here is
    // now PARTLY addressed in the helper: browse mode ORs the query text into
    // the WHERE and boosts title/brand matches (isCategoryBrowseTextUnionEnabled).
    // Read that flag's comment for what it does NOT fix — multi-word browse
    // queries, and the fact that this is a reranking change rather than a pure
    // recall add.
    categoryMode: 'category_browse',
    verticalSearch: hasBeautyIngredientIntentSignal(queryText),
    // Per-token title/brand matching on the buyable mainline lane (reuses the
    // #1722 citable-lane tokenizer). #1933: gated on its own flag, NOT on
    // ACTIVE_AWARE_RECALL — see PIVOT_BEAUTY_MAINLINE_TOKEN_MATCH_ENABLED for
    // why that grouping kept the rank ladder dark, and for the measured effect
    // in category-bucket mode. NOTE: with the category-browse text union on
    // (the default) the token WHERE is no longer dropped under a prefix — the
    // union carries the PLAIN text clause, token arm included.
    tokenMatch: PIVOT_BEAUTY_MAINLINE_TOKEN_MATCH_ENABLED,
    // #1935: sargable text WHERE. Still a no-op in category-bucket mode, but
    // for a DIFFERENT reason than when this was written: the text WHERE used to
    // be discarded there, whereas now the union deliberately routes past the
    // sargable form and takes the plain clause (see the whereClause comment in
    // canonicalCatalogSearch.js for why extending an unmeasured plan change to
    // every prefix-resolving query would be wrong). So this still only affects
    // the ~30% of beauty queries that resolve to no prefix — where it cut prod
    // EXPLAIN execution 2798ms -> 850ms with byte-identical rows and order
    // across 12 measured queries. The COROLLARY, unmeasured and called out in
    // review: prefix-resolving queries now run the plain disjunction, which
    // this file's own prod EXPLAINs put at 3.2-3.9s.
    // See PIVOT_BEAUTY_MAINLINE_SARGABLE_TEXT_WHERE_ENABLED.
    sargableTextWhere: PIVOT_BEAUTY_MAINLINE_SARGABLE_TEXT_WHERE_ENABLED,
    limit: canonicalLimit,
    // Market-aware filtering — pass the user's market (already computed
    // above for the external-seed-direct path's `safeQueryMarket`) so
    // canonical_chain enforces the same market parity. Without this,
    // Round Lab (market=KR) products were leaking into US users'
    // canonical_chain results despite the external-seed-direct path
    // already filtering correctly.
    marketId: market,
    // Phase 7d backfill (pivota-backend #399 + #401, 2026-05-09)
    // populated the catalog_skus + catalog_offers chain for all 3,936
    // Path B mirrored products. JOIN them so canonical_chain response
    // items carry price + currency + availability — without this the
    // chat shows $0 because the SQL returns NULL placeholders for
    // those columns when joinSkuOffers is false.
    includeSkuOffers: true,
    brandFilter: canonicalBrandFilter,
    deps: { query },
  })
    .then((rows) => ({
      rows: Array.isArray(rows) ? rows : [],
      error: null,
      duration_ms: Math.max(0, Date.now() - canonicalStartedAt),
    }))
    .catch((err) => ({
      rows: [],
      error: String(err?.code || err?.message || err || 'canonical_query_failed').slice(0, 160),
      duration_ms: Math.max(0, Date.now() - canonicalStartedAt),
    }));
  const [creatorScopedRows, canonicalResult] = await Promise.all([
    queryBeautyExternalSeedRowsFast({
      market,
      queryText,
      intent: beautyIntent,
      inStockOnly,
      limit: perQueryLimit,
      toolScope: creatorScoped ? 'creator_preferred' : 'all_tools',
    }),
    canonicalRowsPromise,
  ]);
  const canonicalProducts = (Array.isArray(canonicalResult?.rows) ? canonicalResult.rows : [])
    .map((row) => buildCanonicalChainMainlineProduct(row))
    .filter(Boolean);
  // NOTE: the ADR-007 citable lane is NOT here. It's an operation-level supplement
  // applied in the universal res.json wrapper (buildCitableSupplementItems prefetch
  // + appendCitableSupplementItems) so it reaches ALL find_products_multi lanes —
  // branded/ingredient queries never run this canonical block. Flag-gated by
  // INDEX_ELIGIBLE_RECALL.
  const canonicalTelemetry = {
    canonical_path_executed: true,
    canonical_raw_count: Array.isArray(canonicalResult?.rows) ? canonicalResult.rows.length : 0,
    canonical_product_count: canonicalProducts.length,
    canonical_category_path_prefix: canonicalCategoryPathPrefix,
    canonical_brand_filter_applied: Boolean(canonicalBrandFilter),
    // #1927: this lane re-scores what it recalls, so set diversity here shows
    // up as candidate-pool composition rather than as served order — the quota
    // is what stops bundles eating the candidate budget before the scorer runs.
    canonical_set_diversity: isCanonicalSetDiversityEnabled(),
    // #1933: whether the +25/token rank arm fired for this search. Reads the
    // same constant passed to the call above — a free-floating literal here
    // would keep reporting true if that arg ever becomes conditional again,
    // which is exactly the drift the ingredient lane's stamp warns about.
    canonical_token_match: PIVOT_BEAUTY_MAINLINE_TOKEN_MATCH_ENABLED,
    // #1935: the EFFECTIVE sargable state FOR THIS SEARCH, not the requested
    // opt-in. Three env prerequisites plus one per-request condition:
    //   * the helper honors sargableTextWhere only while tokenMatch is on AND
    //     the recall_doc arm is enabled (that arm is what covers the rows the
    //     dropped catalog_skus arms would otherwise recall), so a literal
    //     `true` would lie wherever either is off;
    //   * and under a category prefix the text WHERE is discarded entirely, so
    //     the option did nothing for THIS request no matter how it is flagged.
    // The prefix term is not cosmetic: ~70% of beauty searches resolve to a
    // bucket, so without it this field reports true for the whole lane and the
    // soak cannot be sliced to the ~30% actually affected — which is precisely
    // the "must see what actually ran" failure the ingredient lane's stamp
    // warns about, reintroduced one level up.
    canonical_sargable_text_where:
      PIVOT_BEAUTY_MAINLINE_SARGABLE_TEXT_WHERE_ENABLED &&
      PIVOT_BEAUTY_MAINLINE_TOKEN_MATCH_ENABLED &&
      isCanonicalRecallDocMatchEnabled() &&
      !canonicalCategoryPathPrefix,
    // Whether the +60 product-form arm actually FIRED for this search, not
    // whether its flag is set. The arm is query-conditional — it only fires
    // when the query names a form in the lexicon — so a bare flag stamp would
    // report true for the whole lane and the soak could not be sliced to the
    // requests actually reordered. Unlike the sargable stamp above there is no
    // category-prefix term: bucket mode drops the text WHERE but the rank arms
    // still apply, so the arm DOES reorder browse traffic. That is the mode
    // most beauty searches take and the one with no relevance measurement
    // behind it — this field is how that gets sliced after the flip.
    canonical_form_agreement: canonicalFormAgreementEffectiveFor(canonicalQueryText),
    ...(canonicalQueryText !== queryText ? { canonical_recall_query_text: canonicalQueryText } : {}),
    canonical_duration_ms: Math.max(0, Number(canonicalResult?.duration_ms || 0) || 0),
    query_text: queryText,
    requested_limit: safeLimit,
    beauty_brand_browse: beautyIntent.brandBrowse || null,
    ...(canonicalResult?.error ? { canonical_error: canonicalResult.error } : {}),
  };
  const creatorScopedProducts = Array.isArray(creatorScopedRows?.rawProducts)
    ? creatorScopedRows.rawProducts
    : [];
  const shouldBroaden =
    creatorScoped &&
    creatorScopedProducts.every((product) =>
      scoreBeautyExternalSeedProduct({
        product,
        queryText,
        intent: beautyIntent,
        normalizedQuery: beautyIntent.normalized,
        queryTokens: Array.from(new Set(tokenizeSearchTextForMatch(beautyIntent.normalized))),
        searchQualityContract: searchQualityEnforced ? effectiveSearchQualityContract : null,
      }).relevant !== true,
    );
  const broadenedRows = shouldBroaden
    ? await queryBeautyExternalSeedRowsFast({
        market,
        queryText,
        intent: beautyIntent,
        inStockOnly,
        limit: perQueryLimit,
        toolScope: 'all_tools',
      })
    : null;
  const selectedRows = broadenedRows || creatorScopedRows;
  const normalizedQuery = beautyIntent.normalized;
  const queryTokens = Array.from(new Set(tokenizeSearchTextForMatch(normalizedQuery)));
  const seedProducts = Array.isArray(selectedRows?.rawProducts) ? selectedRows.rawProducts : [];
  const mergedCanonical = mergeCanonicalChainProductsWithSeedProducts(seedProducts, canonicalProducts);
  const recallProducts = mergedCanonical.products;
  canonicalTelemetry.canonical_dedupe_count = mergedCanonical.canonical_dedupe_count;
  const searchQualityTierCounts = buildSearchQualityTierCounts(
    recallProducts,
    searchQualityContractApplied ? effectiveSearchQualityContract : null,
    queryText,
  );
  const scoreRejected = [];
  const scored = recallProducts
    .map((product) => {
      const base = scoreBeautyExternalSeedProduct({
        product,
        queryText,
        intent: beautyIntent,
        normalizedQuery,
        queryTokens,
        searchQualityContract: searchQualityEnforced ? effectiveSearchQualityContract : null,
      });
      if (base.relevant !== true) {
        scoreRejected.push({
          product_id: firstNonEmptyString(product?.product_id, product?.id, product?.pivota_signature_id) || null,
          title: firstNonEmptyString(product?.title, product?.name) || null,
          source: firstNonEmptyString(product?.source, product?.search_recall_source, product?.catalog_source) || null,
          reasons: Array.isArray(base.rejection_reasons) ? base.rejection_reasons : ['ranker_rejected'],
        });
      }
      if (base.relevant === true && creatorScoped) {
        const creatorOverlayScore = scoreBeautyCreatorCurationOverlay({
          product,
          queryText,
          creatorId: metadata.creator_id,
        });
        if (creatorOverlayScore > 0) {
          return {
            ...base,
            score: base.score + creatorOverlayScore,
            creator_overlay_score: creatorOverlayScore,
          };
        }
      }
      return base;
    })
    .filter((row) => row.relevant === true)
    .sort((left, right) => {
      // Tier-first (token-relevance flag): rows carrying query vocabulary or a
      // query-named active always rank above pure category-bucket filler. Flag
      // off => every row defaults to tier 1 and this comparator is byte-identical
      // to the historical score/title ordering.
      if (PIVOT_BEAUTY_TOKEN_RELEVANCE_RANK_ENABLED) {
        const leftTier = left.token_tier ?? 1;
        const rightTier = right.token_tier ?? 1;
        if (rightTier !== leftTier) return rightTier - leftTier;
      }
      if (right.score !== left.score) return right.score - left.score;
      return String(left.product?.title || '').localeCompare(String(right.product?.title || ''));
    });
  const nearDupCollapse = PIVOT_BEAUTY_NEAR_DUP_COLLAPSE_ENABLED
    ? collapseNearDuplicateScoredBeautyProducts(scored)
    : null;
  const rankedScored = nearDupCollapse ? nearDupCollapse.rows : scored;
  if (nearDupCollapse) canonicalTelemetry.near_dup_collapsed_count = nearDupCollapse.collapsed_count;
  const displayRankedProducts = polishBeautyProductRankingForDisplay(
    dedupeBeautyProductsByDisplayKey(
      rankedScored.map((row) => {
        const creatorRank = creatorScoped
          ? buildBeautyCreatorRankTelemetry({ overlayScore: row.creator_overlay_score || 0 })
          : null;
        const productForResponse = creatorRank
          ? {
              ...row.product,
              creator_rank: creatorRank,
            }
          : row.product;
        const compactProduct = compactBeautyMainlineProductForResponse(productForResponse, beautyIntent, queryText);
        return searchQualityContractApplied
          ? applySearchQualityContractResponseHints(compactProduct, effectiveSearchQualityContract, queryText)
          : compactProduct;
      }),
    ),
    queryText,
    safeLimit,
  );
  const brandBrowseGateRequired = Boolean(beautyIntent.brandBrowse?.contract === 'brand_browse');
  const searchQualityServingGateRequired = Boolean(
    searchQualityEnforced &&
      SEARCH_SERVING_QUALITY_HOLD_ENABLED &&
      searchQualityContractApplied
  );
  const servingEligibilityGate = (searchQualityServingGateRequired || brandBrowseGateRequired)
    ? filterSearchServingEligibleProducts(displayRankedProducts, {
        queryText,
        requireBeauty: true,
      })
    : {
        products: displayRankedProducts,
        rejected: [],
        rejected_count: 0,
        input_count: displayRankedProducts.length,
      };
  const budgetConstraint = resolveBeautyMainlineBudgetConstraint({
    search,
    intent,
    queryText,
  });
  const budgetFilter = budgetConstraint
    ? filterFindProductsMultiDirectProductsByBudget(budgetConstraint, servingEligibilityGate.products)
    : null;
  const rankedProducts = budgetFilter ? budgetFilter.products : servingEligibilityGate.products;
  const budgetFxMetadata = budgetFilter?.resolution?.metadata || null;
  const searchQualityFailureReasons = summarizeSearchQualityFailureReasons({
    scoredRejected: scoreRejected,
    servingRejected: servingEligibilityGate.rejected,
  });
  const balancedProducts = balanceBeautyMainlineFamilyCoverage(rankedProducts, beautyIntent, safeLimit);
  const pagedProducts = balancedProducts.slice(safeOffset, safeOffset + safeLimit);
  const pagedCanonicalCount = pagedProducts.filter((product) => (
    String(product?.source || product?.search_recall_source || product?.catalog_source || '') === 'canonical_chain'
  )).length;
  const pagedExternalSeedCount = Math.max(0, pagedProducts.length - pagedCanonicalCount);
  const querySource = creatorScoped
    ? 'agent_products_creator_beauty_external_seed_mainline'
    : 'agent_products_beauty_external_seed_mainline';

  // WS3a operator prompt-test: when an inspectProductId is supplied (only the
  // /api/admin/find-products-prompt-test diagnostic does this), attach an
  // authoritative read of where that product landed in THIS recall+rank pass.
  // No-op for all normal traffic (inspectProductId is null).
  let promptInspect = null;
  if (typeof inspectProductId === 'string' && inspectProductId.trim()) {
    const wantedId = inspectProductId.trim();
    const idMatch = (p) => mainlineProductMatchesId(p, wantedId);
    const recallHit = (Array.isArray(recallProducts) ? recallProducts : []).find(idMatch) || null;
    const scoredIdx = rankedScored.findIndex((row) => idMatch(row && row.product));
    const scoredRow = scoredIdx >= 0 ? rankedScored[scoredIdx] : null;
    const balancedIdx = balancedProducts.findIndex(idMatch);
    const rejected = scoreRejected.find((r) => String((r && r.product_id) || '').trim() === wantedId) || null;
    promptInspect = {
      product_id: wantedId,
      query: queryText,
      query_active_concepts: extractBeautyQueryActiveConcepts(queryText).map((c) => c.key),
      in_recall_pool: Boolean(recallHit),
      recall_source: recallHit
        ? firstNonEmptyString(recallHit.source, recallHit.search_recall_source, recallHit.catalog_source) || null
        : null,
      relevant: scoredRow ? true : rejected ? false : null,
      rejection_reasons: rejected ? rejected.reasons : null,
      score: scoredRow ? scoredRow.score : null,
      // What the scorer actually credited (flag-dependent) vs what the product
      // matches regardless of flag — lets an operator see "you match soy+firming
      // but the active-aware rank flag isn't crediting it".
      active_bonus_applied: scoredRow && scoredRow.active_match ? scoredRow.active_match : null,
      token_relevance: scoredRow && scoredRow.token_relevance ? scoredRow.token_relevance : null,
      token_tier: scoredRow && scoredRow.token_tier != null ? scoredRow.token_tier : null,
      near_dup_demoted: Boolean(scoredRow && scoredRow.near_dup_demoted),
      // Same includeTitleBrand surface as the scorer so operator diagnostics agree
      // with what serving actually credited.
      concept_match: recallHit
        ? countBeautyActiveConceptMatches(queryText, recallHit, {
            includeTitleBrand: PIVOT_BEAUTY_TOKEN_RELEVANCE_RANK_ENABLED,
          })
        : null,
      display_rank: balancedIdx >= 0 ? balancedIdx + 1 : null,
      total_ranked: balancedProducts.length,
      in_visible_page: balancedIdx >= 0 && balancedIdx >= safeOffset && balancedIdx < safeOffset + safeLimit,
      page_size: safeLimit,
    };
  }

  return {
    status: 'success',
    success: true,
    products: pagedProducts,
    total: balancedProducts.length,
    page: safePage,
    page_size: pagedProducts.length,
    reply: pagedProducts.length > 0 ? null : 'No matching beauty products found on the mainline catalog path.',
    metadata: {
      query_source: querySource,
      ...(promptInspect ? { prompt_inspect: promptInspect } : {}),
      fetched_at: new Date().toISOString(),
      external_seed_only_requested: true,
      external_seed_rows_fetched: Array.isArray(selectedRows?.rawProducts) ? selectedRows.rawProducts.length : 0,
      external_seed_rows_built: rankedProducts.length,
      external_seed_returned_count: pagedExternalSeedCount,
      ...(queryUnderstanding
        ? {
            query_understanding: queryUnderstanding,
            query_understanding_executed: true,
            query_understanding_decision: queryUnderstanding.decision || null,
          }
        : {}),
      search_quality_contract: projectSearchQualityContractForMetadata(searchQualityContract),
      search_quality_contract_applied: searchQualityContractApplied,
      search_quality_contract_mode: SEARCH_QUALITY_CONTRACT_V1_MODE,
      ...(searchQualityContractRelaxedForMultiFamily
        ? { search_quality_contract_relaxed_for_multi_family: true }
        : {}),
      search_quality_failure_reasons: searchQualityFailureReasons,
      search_quality_tier_counts: searchQualityTierCounts,
      beauty_mainline_budget_filter_applied: Boolean(budgetFilter),
      beauty_mainline_budget_filtered_out_count: budgetFilter?.filteredOut || 0,
      beauty_mainline_budget_currency_filtered_out_count: budgetFilter?.currencyFilteredOut || 0,
      ...(budgetFxMetadata || {}),
      ...canonicalTelemetry,
      canonical_returned_count: pagedCanonicalCount,
      creator_external_seed_tool_scope: broadenedRows ? 'all_tools' : (creatorScoped ? 'creator_preferred' : 'all_tools'),
      retrieval_query_variants: retrievalQueries,
      retrieval_query_debug: selectedRows?.variantResults || [],
      beauty_mainline_filter: {
        target_families: beautyIntent.families,
        safety_rules: beautyIntent.safety,
      },
      search_card_quality_gate: {
        applied: searchQualityServingGateRequired || brandBrowseGateRequired,
        mode: searchQualityServingGateRequired
          ? 'beauty_search_quality_contract_v1'
          : brandBrowseGateRequired
            ? 'beauty_brand_browse'
            : 'not_required',
        input_count: servingEligibilityGate.input_count,
        eligible_count: rankedProducts.length,
        rejected_count: servingEligibilityGate.rejected_count,
        rejected: servingEligibilityGate.rejected.slice(0, 8),
      },
      ...(beautyIntent.brandBrowse
        ? {
            beauty_brand_browse: beautyIntent.brandBrowse,
          }
        : {}),
      beauty_strict_quality_ranker: {
        applied: PIVOT_BEAUTY_STRICT_RECO_QUALITY_ENABLED,
        version: 'beauty_strict_quality_2026_04_30',
        local_authority_fields_supported: true,
      },
      ...(selectedRows?.destinationBrandMarketBridge?.attempted
        ? {
            destination_brand_market_bridge: selectedRows.destinationBrandMarketBridge,
          }
        : {}),
      ...(creatorScoped
        ? {
            creator_rank_overlay: {
              applied: PIVOT_BEAUTY_CREATOR_CURATION_RANKING_ENABLED,
              mode: PIVOT_BEAUTY_CREATOR_CURATION_RANKING_ENABLED ? 'curation_rank_overlay' : 'no_op',
              overlay_enabled: PIVOT_CREATOR_RANKING_OVERLAY_ENABLED,
              local_curation_enabled: PIVOT_CREATOR_LOCAL_CURATION_ENABLED,
              commercial_boost_enabled: PIVOT_CREATOR_COMMERCIAL_BOOST_ENABLED,
              creator_id: metadata.creator_id || null,
              max_overlay_score: 28,
              safety_and_class_gate_precedes_overlay: true,
              overlay_skipped_reason: PIVOT_BEAUTY_CREATOR_CURATION_RANKING_ENABLED
                ? null
                : getBeautyCreatorOverlaySkippedReason(0),
            },
          }
        : {}),
      source_breakdown: {
        internal_count: 0,
        external_seed_count: pagedExternalSeedCount,
        canonical_chain_count: pagedCanonicalCount,
        canonical_chain_candidate_count: canonicalProducts.length,
        stale_cache_used: false,
        strategy_applied: canonicalProducts.length > 0
          ? 'beauty_external_seed_mainline_plus_canonical_chain'
          : 'beauty_external_seed_mainline',
      },
      search_decision: {
        final_decision: pagedProducts.length > 0 ? 'products_returned' : 'empty',
        decision_authority: querySource,
        query_target_domain: 'beauty',
      },
      route_debug: {
        beauty_external_seed_mainline: {
          attempted: true,
          query: queryText,
          target_families: beautyIntent.families,
          safety_rules: beautyIntent.safety,
          creator_scoped: Boolean(creatorScoped),
          broadened_tool_scope: Boolean(broadenedRows),
          destination_brand_market_bridge: selectedRows?.destinationBrandMarketBridge || null,
          canonical_chain: canonicalTelemetry,
          search_quality_contract_applied: searchQualityContractApplied,
          search_quality_contract_mode: SEARCH_QUALITY_CONTRACT_V1_MODE,
          ...(searchQualityContractRelaxedForMultiFamily
            ? { search_quality_contract_relaxed_for_multi_family: true }
            : {}),
          budget_filter: {
            applied: Boolean(budgetFilter),
            filtered_out_count: budgetFilter?.filteredOut || 0,
            currency_filtered_out_count: budgetFilter?.currencyFilteredOut || 0,
          },
          search_card_quality_gate: {
            applied: searchQualityServingGateRequired || brandBrowseGateRequired,
            input_count: servingEligibilityGate.input_count,
            eligible_count: rankedProducts.length,
            rejected_count: servingEligibilityGate.rejected_count,
          },
        },
      },
      route_health: {
        primary_path_used: 'beauty_external_seed_mainline',
        fallback_triggered: false,
        fallback_reason: null,
        canonical_path_executed: canonicalTelemetry.canonical_path_executed,
        canonical_raw_count: canonicalTelemetry.canonical_raw_count,
        canonical_dedupe_count: canonicalTelemetry.canonical_dedupe_count,
        search_quality_contract_applied: searchQualityContractApplied,
        search_quality_contract_mode: SEARCH_QUALITY_CONTRACT_V1_MODE,
        search_card_quality_gate_applied: searchQualityServingGateRequired || brandBrowseGateRequired,
        search_card_quality_gate_rejected_count: servingEligibilityGate.rejected_count,
        ...(queryUnderstanding
          ? {
              query_understanding_executed: true,
              query_understanding_decision: queryUnderstanding.decision || null,
            }
          : {}),
        final_returned_count: pagedProducts.length,
      },
      ...(metadata?.creator_id ? { creator_id: metadata.creator_id } : {}),
      ...(metadata?.creator_name ? { creator_name: metadata.creator_name } : {}),
    },
  };
}

const LOOKUP_EQUIVALENCE_FAMILIES = [
  ['winona', '薇诺娜'],
  ['ipsa', '茵芙莎', '流金水'],
  ['time reset aqua', '流金水', 'ipsa'],
  ['the ordinary', 'ordinary'],
  ['sk ii', 'skii', '神仙水'],
];

const BEAUTY_FORM_FACTOR_TOKENS = new Set([
  'serum',
  'essence',
  'ampoule',
  'lotion',
  'cream',
  'moisturizer',
  'moisturiser',
  'cleanser',
  'toner',
  'mask',
  'spf',
  'sunscreen',
]);

function hasBeautyIngredientIntentSignal(queryText) {
  const q = normalizeSearchTextForMatch(queryText);
  if (!q) return false;
  return (
    /\b(copper|peptide|tripeptide|tetrapeptide|hexapeptide|retinol|retinal|niacinamide|ceramide|hyaluronic|ascorbic|vitamin c|salicylic|glycolic|lactic|mandelic|azelaic|tranexamic|benzoyl)\b/i.test(
      q,
    ) ||
    /(铜肽|胜肽|视黄醇|烟酰胺|神经酰胺|玻尿酸|水杨酸|果酸|壬二酸)/.test(q)
  );
}

function shouldPreserveIngredientDirectForPivotBeautyContract(queryText, ingredientIntentIds = []) {
  const normalized = normalizeSearchTextForMatch(queryText);
  const raw = String(queryText || '');
  const intents = new Set(
    (Array.isArray(ingredientIntentIds) ? ingredientIntentIds : [])
      .map((value) => String(value || '').trim().toLowerCase())
      .filter(Boolean),
  );
  if (!normalized || intents.size === 0) return false;

  const hasRetinoidIntent = ['retinol', 'retinal', 'retinoid'].some((value) => intents.has(value));
  if (
    hasRetinoidIntent &&
    (
      /\b(pregnan\w*|ttc|trying\s*to\s*conceive|retinol[-\s]?free|retinoid[-\s]?free|no\s+retinol|without\s+retinol|avoid\s+retinol|avoid\s+retinoids?)\b/i.test(raw) ||
      /备孕|備孕|怀孕|懷孕|孕期|不用视黄醇|不用視黃醇|避开视黄醇|避開視黃醇/.test(raw)
    )
  ) {
    return false;
  }

  const acidIntents = new Set(['salicylic_acid', 'glycolic_acid', 'lactic_acid', 'mandelic_acid']);
  const hasAcidIntent = Array.from(intents).some((value) => acidIntents.has(value));
  if (
    hasAcidIntent &&
    (
      /\b(barrier|damaged\s+barrier|barrier\s+damage|over[-\s]?exfoliat|sensiti[sz]ed|stinging|redness|peeling|avoid\s+acid|no\s+acid|acid[-\s]?free)\b/i.test(raw) ||
      /屏障|刺痛|泛红|泛紅|脱皮|脫皮|刷酸过度|刷酸過度|不用酸|避开酸|避開酸/.test(raw)
    )
  ) {
    return false;
  }

  return true;
}

function buildBeautyIngredientIntentTokens(queryText, queryTokens = []) {
  const normalized = normalizeSearchTextForMatch(queryText);
  const out = new Set();
  const pushToken = (token) => {
    const value = normalizeSearchTextForMatch(token);
    if (!value || BEAUTY_FORM_FACTOR_TOKENS.has(value) || value.length < 3) return;
    out.add(value);
  };

  for (const token of Array.isArray(queryTokens) ? queryTokens : []) {
    pushToken(token);
  }

  if (!normalized) return Array.from(out);
  if (/\bcopper\b/.test(normalized) && /\b(peptide|tripeptide|tetrapeptide|hexapeptide)/.test(normalized)) {
    pushToken('copper');
    pushToken('peptide');
    pushToken('multi peptide');
    pushToken('copper tripeptide');
    pushToken('tripeptide');
  }
  if (/\b(peptide|tripeptide|tetrapeptide|hexapeptide)/.test(normalized)) {
    pushToken('peptide');
    pushToken('multi peptide');
  }
  if (/\bretinol|retinal|retinoid/.test(normalized)) pushToken('retinol');
  if (/\bniacinamide/.test(normalized)) pushToken('niacinamide');
  if (/\bceramide/.test(normalized)) pushToken('ceramide');
  if (/\bhyaluronic/.test(normalized)) pushToken('hyaluronic');
  if (/\bascorbic|vitamin c/.test(normalized)) pushToken('vitamin c');
  if (/\bsalicylic/.test(normalized)) pushToken('salicylic');
  if (/\bglycolic/.test(normalized)) pushToken('glycolic');
  if (/\blactic/.test(normalized)) pushToken('lactic');
  if (/\bazelaic/.test(normalized)) pushToken('azelaic');
  if (/\btranexamic/.test(normalized)) pushToken('tranexamic');

  return Array.from(out);
}

function buildFallbackOverlapPreview(products, queryText, maxItems = 3) {
  const rows = [];
  const normalizedQuery = normalizeSearchTextForMatch(queryText);
  const baseTokens = Array.from(new Set(tokenizeSearchTextForMatch(normalizedQuery)));
  const ingredientIntent = hasBeautyIngredientIntentSignal(queryText);
  const meaningfulTokens = ingredientIntent
    ? baseTokens.filter((token) => !BEAUTY_FORM_FACTOR_TOKENS.has(token))
    : baseTokens;
  const intentTokens = ingredientIntent ? buildBeautyIngredientIntentTokens(queryText, meaningfulTokens) : [];
  const effectiveTokens = Array.from(new Set([...meaningfulTokens, ...intentTokens])).slice(0, 12);

  for (const product of Array.isArray(products) ? products : []) {
    if (rows.length >= maxItems) break;
    if (!hasUsableSearchProduct(product)) continue;
    const candidateText = buildFallbackCandidateText(product);
    if (!candidateText) continue;
    const matched = effectiveTokens.filter((token) => candidateText.includes(token)).slice(0, 4);
    rows.push({
      product_id: String(product?.product_id || product?.id || ''),
      title: String(product?.title || product?.name || ''),
      overlap_count: matched.length,
      matched_tokens: matched,
    });
  }
  return rows;
}

function isKnownLookupAliasQuery(queryText) {
  const normalizedQuery = normalizeSearchTextForMatch(queryText);
  if (!normalizedQuery) return false;
  for (const family of LOOKUP_EQUIVALENCE_FAMILIES) {
    const normalizedFamilyTerms = family
      .map((term) => normalizeSearchTextForMatch(term))
      .filter(Boolean);
    if (normalizedFamilyTerms.some((term) => term && normalizedQuery.includes(term))) {
      return true;
    }
  }
  return false;
}

function expandLookupAnchorTokens(queryText, anchorTokens) {
  const normalizedQuery = normalizeSearchTextForMatch(queryText);
  const normalizedAnchors = Array.isArray(anchorTokens)
    ? anchorTokens
        .map((token) => normalizeSearchTextForMatch(token))
        .filter(Boolean)
    : [];
  const expanded = new Set(normalizedAnchors);
  const anchorSet = new Set(normalizedAnchors);
  const queryTokens = new Set(tokenizeSearchTextForMatch(normalizedQuery));

  for (const family of LOOKUP_EQUIVALENCE_FAMILIES) {
    const normalizedFamilyTerms = family
      .map((term) => normalizeSearchTextForMatch(term))
      .filter(Boolean);
    if (!normalizedFamilyTerms.length) continue;

    const matched = normalizedFamilyTerms.some((term) => {
      if (!term) return false;
      if (anchorSet.has(term)) return true;
      if (normalizedQuery.includes(term)) return true;
      return !term.includes(' ') && queryTokens.has(term);
    });
    if (!matched) continue;

    for (const term of normalizedFamilyTerms) {
      expanded.add(term);
      if (term.includes(' ')) {
        for (const sub of term.split(' ')) {
          const normalizedSub = normalizeSearchTextForMatch(sub);
          if (normalizedSub && normalizedSub.length >= 2) {
            expanded.add(normalizedSub);
          }
        }
      }
    }
  }

  return Array.from(expanded);
}

function isProxySearchFallbackRelevant(normalized, queryText) {
  const products = Array.isArray(normalized?.products) ? normalized.products : [];
  if (!products.length) return false;

  const normalizedQuery = normalizeSearchTextForMatch(queryText);
  if (!normalizedQuery) return true;
  if (hasFragranceQuerySignal(queryText)) {
    // Recall-first for fragrance: keep candidates for downstream ranking/clarify.
    return products.slice(0, 8).some((product) => hasUsableSearchProduct(product));
  }

  const hasLingerieScopeSignal =
    /\b(lingerie|underwear|bra|panties|bodysuit)\b/i.test(String(queryText || '')) ||
    /内衣|文胸|胸罩|下着|ランジェリー/.test(String(queryText || ''));
  if (hasLingerieScopeSignal) {
    return products.slice(0, 8).some((product) => {
      if (!hasUsableSearchProduct(product)) return false;
      const candidateText = buildFallbackCandidateText(product);
      if (!candidateText) return false;
      return (
        /\b(lingerie|underwear|bra|panties|bodysuit)\b/i.test(candidateText) ||
        /内衣|文胸|胸罩|下着|ランジェリー/.test(candidateText)
      );
    });
  }

  const hasPetHarnessSignal = hasPetHarnessSearchSignal(queryText);
  if (hasPetHarnessSignal) {
    for (const product of products.slice(0, 8)) {
      if (!hasUsableSearchProduct(product)) continue;
      const candidateText = buildFallbackCandidateText(product);
      if (!candidateText) continue;
      if (hasStrictPetHarnessCatalogSignal(candidateText)) return true;
    }
    return false;
  }

  const anchorTokens = extractSearchAnchorTokens(queryText);
  const lookupTokens = expandLookupAnchorTokens(queryText, anchorTokens);
  const queryTokens = Array.from(new Set(tokenizeSearchTextForMatch(normalizedQuery)));
  const ingredientIntent = hasBeautyIngredientIntentSignal(queryText);
  const meaningfulTokens = ingredientIntent
    ? queryTokens.filter((token) => !BEAUTY_FORM_FACTOR_TOKENS.has(token))
    : queryTokens;
  const intentTokens = ingredientIntent ? buildBeautyIngredientIntentTokens(queryText, meaningfulTokens) : [];
  const effectiveTokens = Array.from(new Set([...meaningfulTokens, ...intentTokens]));
  const longQuery = effectiveTokens.length >= 2;
  const requiredOverlap = ingredientIntent ? 1 : 2;
  const beautyQueryBucket = detectBeautyQueryBucket(queryText);

  if (beautyQueryBucket) {
    for (const product of products.slice(0, 8)) {
      if (!hasUsableSearchProduct(product)) continue;
      const candidateBucket = classifyBeautyBucketFromProduct(product);
      if (!isBeautyBucketCompatibleForQuery(candidateBucket, beautyQueryBucket)) continue;
      const candidateText = buildFallbackCandidateText(product);
      if (!candidateText) continue;
      if (candidateText.includes(normalizedQuery)) return true;
      if (!effectiveTokens.length) return true;
      if (effectiveTokens.length === 1) return candidateText.includes(effectiveTokens[0]);
      if (!longQuery) return true;
      const overlapCount = effectiveTokens.filter((token) => candidateText.includes(token)).length;
      if (overlapCount >= requiredOverlap) return true;
    }
    return false;
  }

  if (isLookupStyleSearchQuery(queryText, anchorTokens) && lookupTokens.length > 0) {
    for (const product of products.slice(0, 8)) {
      if (!hasUsableSearchProduct(product)) continue;
      const candidateText = buildFallbackCandidateText(product);
      if (!candidateText) continue;
      if (lookupTokens.some((token) => candidateText.includes(token))) return true;
    }
    return false;
  }

  for (const product of products.slice(0, 8)) {
    if (!hasUsableSearchProduct(product)) continue;
    const candidateText = buildFallbackCandidateText(product);
    if (!candidateText) continue;
    if (candidateText.includes(normalizedQuery)) return true;
    if (!effectiveTokens.length) return true;
    if (effectiveTokens.length === 1) return candidateText.includes(effectiveTokens[0]);
    if (!longQuery) return true;
    const overlapCount = effectiveTokens.filter((token) => candidateText.includes(token)).length;
    if (overlapCount >= requiredOverlap) return true;
  }

  return false;
}

function hasFragranceSearchSignal(queryText) {
  return /\b(perfume|perfumes|fragrance|fragrances|fragarance|fragarances|fragance|fragances|fragrence|fragrences|fragrancee|parfum|cologne|body mist|eau de parfum|eau de toilette)\b|香水|香氛|古龙|古龍|香體|香体/i.test(
    String(queryText || ''),
  );
}

function isSupplementCandidateRelevant(product, queryText, options = {}) {
  if (!product || typeof product !== 'object') return false;
  const candidateText = buildFallbackCandidateText(product);
  if (!candidateText) return false;

  const hasFragranceSearch = hasFragranceSearchSignal(queryText);
  const candidateBeautyBucket = hasFragranceSearch ? classifyBeautyBucketFromText(candidateText) : null;
  const hasFragranceCandidateSignal =
    /\b(perfume|perfumes|fragrance|fragrances|fragarance|fragarances|fragance|fragances|fragrence|fragrences|fragrancee|parfum|cologne|body mist|eau de parfum|eau de toilette|scent|aroma)\b/i.test(
      candidateText,
    ) || candidateBeautyBucket === 'fragrance';
  const isBeautyToolLikeCandidate = /\b(brush|brushes|blender|sponge|powder puff|puff|applicator|eyelash curler|tool kit|makeup tool)\b/i.test(
    candidateText,
  );

  if (hasFragranceSearch) {
    if (!hasFragranceCandidateSignal) return false;
    if (isBeautyToolLikeCandidate) return false;
    // Recall-first for fragrance supplement: skip hard lexical overlap gates.
    return true;
  }

  const brandTerms = Array.isArray(options.brandTerms)
    ? options.brandTerms
        .map((term) => normalizeSearchTextForMatch(term))
        .filter((term) => term && term.length >= 2)
    : [];
  if (brandTerms.length > 0) {
    const brandMatched = brandTerms.some((term) => hasBrandTermMatch(candidateText, term));
    if (!brandMatched && !SEARCH_EXTERNAL_HARD_RULE_PRUNE) return false;
  }

  if (hasPetHarnessSearchSignal(queryText)) {
    if (!hasStrictPetHarnessCatalogSignal(candidateText)) return false;
  }

  const beautyQueryBucket = detectBeautyQueryBucket(queryText);
  if (beautyQueryBucket) {
    const candidateBucket = classifyBeautyBucketFromText(candidateText);
    if (!isBeautyBucketCompatibleForQuery(candidateBucket, beautyQueryBucket)) return false;
  }

  const normalizedQuery =
    typeof options.normalizedQuery === 'string'
      ? options.normalizedQuery
      : normalizeSearchTextForMatch(queryText);
  if (!normalizedQuery) return true;

  const anchorTokens = Array.isArray(options.anchorTokens)
    ? options.anchorTokens
    : extractSearchAnchorTokens(queryText);
  const lookupTokens = expandLookupAnchorTokens(queryText, anchorTokens);
  if (isLookupStyleSearchQuery(queryText, anchorTokens) && lookupTokens.length > 0) {
    return lookupTokens.some((token) => candidateText.includes(token));
  }

  if (candidateText.includes(normalizedQuery)) return true;

  const rawQueryTokens = Array.isArray(options.queryTokens)
    ? options.queryTokens
    : Array.from(new Set(tokenizeSearchTextForMatch(normalizedQuery)));
  const usefulQueryTokens = rawQueryTokens.filter((token) => {
    if (!token) return false;
    if (token.length < 2) return false;
    if (/^(de|of|the|for|and|to|a|an)$/i.test(token)) return false;
    return true;
  });
  const ingredientIntent = hasBeautyIngredientIntentSignal(queryText);
  const meaningfulTokens = ingredientIntent
    ? usefulQueryTokens.filter((token) => !BEAUTY_FORM_FACTOR_TOKENS.has(token))
    : usefulQueryTokens;
  const intentTokens = ingredientIntent ? buildBeautyIngredientIntentTokens(queryText, meaningfulTokens) : [];
  const effectiveTokens = Array.from(new Set([...meaningfulTokens, ...intentTokens]));
  if (!effectiveTokens.length) return true;
  if (effectiveTokens.length === 1) {
    return candidateText.includes(effectiveTokens[0]);
  }
  const overlapCount = effectiveTokens.filter((token) => candidateText.includes(token)).length;
  return overlapCount >= (ingredientIntent ? 1 : 2);
}

function filterBeautySpecificCacheProducts(products, queryText, options = {}) {
  const list = Array.isArray(products) ? products : [];
  const beautyQueryProfile =
    options?.beautyQueryProfile && typeof options.beautyQueryProfile === 'object'
      ? options.beautyQueryProfile
      : buildBeautyQueryProfile({
          rawQuery: queryText,
          queryClass: options?.queryClass || options?.intent?.query_class,
          intent: options?.intent,
        });
  const bucket = beautyQueryProfile?.bucket || null;
  const beforeMix = computeBeautyBucketMix(list, Math.max(1, list.length || 1));

  if (!beautyQueryProfile?.isSpecificBeautyQuery || !bucket || list.length === 0) {
    return {
      products: list,
      applied: false,
      filtered_irrelevant_count: 0,
      bucket,
      bucket_mix_before: beforeMix,
      bucket_mix_after: beforeMix,
    };
  }

  const normalizedQuery = normalizeSearchTextForMatch(queryText);
  const anchorTokens = extractSearchAnchorTokens(queryText);
  const queryTokens = Array.from(new Set(tokenizeSearchTextForMatch(normalizedQuery)));
  const filtered = list.filter((product) =>
    isSupplementCandidateRelevant(product, queryText, {
      normalizedQuery,
      anchorTokens,
      queryTokens,
    }),
  );
  const afterMix = computeBeautyBucketMix(filtered, Math.max(1, filtered.length || 1));
  return {
    products: filtered,
    applied: true,
    filtered_irrelevant_count: Math.max(0, list.length - filtered.length),
    bucket,
    bucket_mix_before: beforeMix,
    bucket_mix_after: afterMix,
  };
}

function inferCacheProductDomainKey(product) {
  if (!product || typeof product !== 'object') return 'general';
  const pivotaDomain = String(
    product?.attributes?.pivota?.domain || product?.domain || product?.category_domain || '',
  )
    .trim()
    .toLowerCase();
  if (pivotaDomain) {
    if (pivotaDomain === 'beauty') return 'beauty';
    if (pivotaDomain === 'pet' || pivotaDomain === 'pet_supplies') return 'pet';
    if (pivotaDomain === 'travel') return 'travel';
    if (pivotaDomain === 'hiking' || pivotaDomain === 'outdoor' || pivotaDomain === 'sports_outdoor') {
      return 'hiking';
    }
  }
  const text = buildFallbackCandidateText(product);
  if (!text) return 'general';
  if (/\b(dog|dogs|cat|cats|pet|harness|leash|collar|puppy|kitten)\b/i.test(text) || /宠物|狗|猫|牵引|狗链|背带|项圈/.test(text)) {
    return 'pet';
  }
  if (
    /\b(foundation|concealer|mascara|lipstick|serum|toner|moisturizer|makeup|cosmetic)\b/i.test(text) ||
    /化妆|美妆|护肤|精华|口红|粉底|防晒|唇膏|眼影/.test(text)
  ) {
    return 'beauty';
  }
  if (/\b(hiking|outdoor|camping|trekking|trail|parka|shell)\b/i.test(text) || /徒步|登山|露营|冲锋衣|户外/.test(text)) {
    return 'hiking';
  }
  if (
    /\b(luggage|packing|travel|toiletry|carry-on|adapter)\b/i.test(text) ||
    /行李|收纳|旅行|出差|分装|登机/.test(text)
  ) {
    return 'travel';
  }
  return 'general';
}

function inferIntentDomainKeyForCacheValidation(intent, queryText) {
  const target = String(intent?.target_object?.type || '').toLowerCase();
  const primaryDomain = String(intent?.primary_domain || '').toLowerCase();
  const normalizedQuery = normalizeSearchTextForMatch(queryText);
  if (target === 'pet' || hasPetSearchSignal(normalizedQuery)) return 'pet';
  if (primaryDomain === 'beauty' || hasBeautyMakeupSearchSignal(normalizedQuery)) return 'beauty';
  if (/travel|trip|business trip|packing|luggage|toiletry|出差|旅行|旅游|差旅/.test(normalizedQuery)) {
    return 'travel';
  }
  if (/hiking|trail|camping|outdoor|徒步|登山|露营|户外/.test(normalizedQuery)) {
    return 'hiking';
  }
  if (primaryDomain === 'sports_outdoor') return 'hiking';
  return null;
}

function computeDomainEntropyTopK(products, topK = 10) {
  const list = Array.isArray(products) ? products.slice(0, topK) : [];
  if (!list.length) return 1;
  const counts = new Map();
  for (const product of list) {
    const key = inferCacheProductDomainKey(product);
    counts.set(key, (counts.get(key) || 0) + 1);
  }
  const total = list.length;
  if (!total || counts.size <= 1) return 0;
  let entropy = 0;
  for (const count of counts.values()) {
    const p = count / total;
    if (p > 0) entropy -= p * Math.log(p);
  }
  const maxEntropy = Math.log(counts.size);
  if (!(maxEntropy > 0)) return 0;
  return Math.max(0, Math.min(1, entropy / maxEntropy));
}

function computeAnchorRatioTopK(queryText, products, topK = 10) {
  const anchors = extractSearchAnchorTokens(queryText);
  if (!anchors.length) return 1;
  const list = Array.isArray(products) ? products.slice(0, topK) : [];
  if (!list.length) return 0;
  let matched = 0;
  for (const product of list) {
    const text = buildFallbackCandidateText(product);
    if (!text) continue;
    if (anchors.some((token) => text.includes(token))) matched += 1;
  }
  return Math.max(0, Math.min(1, matched / list.length));
}

function resolveCacheValidationMinCount(queryClass) {
  const qc = String(queryClass || '').toLowerCase();
  if (qc === 'lookup') return 1;
  if (qc === 'scenario' || qc === 'mission') return Math.max(1, Math.min(SEARCH_CACHE_MIN_COUNT, 4));
  return SEARCH_CACHE_MIN_COUNT;
}

function evaluateCacheQualityGate({ products, queryText, intent, queryClass }) {
  const list = Array.isArray(products) ? products : [];
  const beautyQueryProfile = buildBeautyQueryProfile({
    rawQuery: queryText,
    queryClass,
    intent,
  });
  const minCount =
    beautyQueryProfile?.isSpecificBeautyQuery === true
      ? 1
      : resolveCacheValidationMinCount(queryClass);
  const anchorRatio = computeAnchorRatioTopK(queryText, list, 10);
  const domainEntropy = computeDomainEntropyTopK(list, 10);
  const expectedDomain = inferIntentDomainKeyForCacheValidation(intent, queryText);
  const topDomains = list.slice(0, 10).map((item) => inferCacheProductDomainKey(item));
  const crossDomainRatio =
    expectedDomain && topDomains.length > 0
      ? topDomains.filter((domain) => domain && domain !== 'general' && domain !== expectedDomain).length /
        topDomains.length
      : null;
  const countOk = list.length >= minCount;
  const anchorOk = anchorRatio >= SEARCH_CACHE_MIN_ANCHOR;
  const entropyOk = domainEntropy <= SEARCH_CACHE_MAX_DOMAIN_ENTROPY;
  const crossDomainOk =
    crossDomainRatio == null || crossDomainRatio <= SEARCH_CACHE_MAX_CROSS_DOMAIN_RATIO;
  const accepted = countOk && anchorOk && entropyOk && crossDomainOk;
  return {
    enabled: SEARCH_CACHE_VALIDATE,
    accepted,
    min_count: minCount,
    count: list.length,
    anchor_ratio: anchorRatio,
    min_anchor: SEARCH_CACHE_MIN_ANCHOR,
    domain_entropy_topk: domainEntropy,
    max_domain_entropy: SEARCH_CACHE_MAX_DOMAIN_ENTROPY,
    expected_domain: expectedDomain,
    cross_domain_ratio: crossDomainRatio,
    max_cross_domain_ratio: SEARCH_CACHE_MAX_CROSS_DOMAIN_RATIO,
    reason: accepted
      ? 'ok'
      : !countOk
        ? 'count_below_threshold'
        : !anchorOk
          ? 'anchor_below_threshold'
          : !entropyOk
            ? 'domain_entropy_above_threshold'
            : 'cross_domain_ratio_above_threshold',
  };
}

function computePrimaryQualityScore(gateResult) {
  if (!gateResult || typeof gateResult !== 'object') return null;
  const count = Math.max(0, Number(gateResult.count || 0) || 0);
  const minCount = Math.max(1, Number(gateResult.min_count || 1) || 1);
  const countScore = Math.max(0, Math.min(1, count / minCount));
  const anchorScore = Math.max(0, Math.min(1, Number(gateResult.anchor_ratio || 0) || 0));
  const entropyTopK = Math.max(0, Number(gateResult.domain_entropy_topk || 0) || 0);
  const maxEntropy = Math.max(0.01, Number(gateResult.max_domain_entropy || 1) || 1);
  const entropyScore = Math.max(0, Math.min(1, 1 - entropyTopK / maxEntropy));
  const crossDomainRatioRaw = gateResult.cross_domain_ratio;
  const maxCrossDomain = Math.max(
    0.01,
    Number(gateResult.max_cross_domain_ratio == null ? 1 : gateResult.max_cross_domain_ratio) || 1,
  );
  const crossDomainScore =
    crossDomainRatioRaw == null
      ? 1
      : Math.max(
          0,
          Math.min(1, 1 - (Math.max(0, Number(crossDomainRatioRaw) || 0) / maxCrossDomain)),
        );
  const composite = (countScore + anchorScore + entropyScore + crossDomainScore) / 4;
  return Math.max(0, Math.min(1, Number(composite.toFixed(3)) || 0));
}

function shouldFallbackProxySearch(normalized, statusCode) {
  const status = Number(statusCode || 0);
  if (status >= 500) return true;
  if (status === 408 || status === 409 || status === 425 || status === 429) return true;
  if (status < 200 || status >= 300) return false;
  const products = Array.isArray(normalized?.products) ? normalized.products : [];
  const usableCount = countUsableSearchProducts(products);
  const total = Number(normalized?.total);
  if (products.length > 0 && usableCount === 0) return true;
  if (Number.isFinite(total) && total > 0 && usableCount === 0) return true;
  if (products.length === 0 && Number.isFinite(total) && total === 0) return true;
  return false;
}

function getFallbackAdoptUsableThreshold({
  operation,
  source,
  primaryUsableCount,
  primaryIrrelevant,
}) {
  const baseThreshold = Math.max(1, Number(primaryUsableCount || 0));
  const op = String(operation || '').trim();
  if (op !== 'find_products_multi') return baseThreshold;
  if (!primaryIrrelevant) return baseThreshold;
  if (isAuroraSource(source) && PROXY_SEARCH_AURORA_RELAX_PRIMARY_IRRELEVANT_ADOPT) return 1;
  return baseThreshold;
}

// Canonical step families, taken from the one place that defines them so this cannot drift.
const { RECO_PRICE_CEILING_KNOWN_CURRENCIES } = require('./auroraBff/recoPriceCeiling');
const FIND_PRODUCTS_MULTI_STEP_FAMILY_ALLOWLIST = Object.freeze(
  Object.keys(require('./auroraBff/recoTargetStep').CANONICAL_STEP_FAMILY_MAP),
);

// Positive, finite, and bounded. Anything else is DROPPED (returns undefined), never coerced.
function normalizeFindProductsMultiMaxPriceParam(value) {
  const parsed = parseQueryNumber(value);
  if (parsed === undefined) return undefined;
  if (!Number.isFinite(parsed) || parsed <= 0) return undefined;
  return parsed;
}

// Currency codes this lane can compare against, mirroring the agent bridge's KNOWN_CURRENCIES and
// src/auroraBff/recoPriceCeiling.js. A test pins the three lists together.
function normalizeFindProductsMultiPriceCurrencyParam(value) {
  const token = String(value == null ? '' : value).trim().toUpperCase();
  if (!token) return '';
  return RECO_PRICE_CEILING_KNOWN_CURRENCIES.includes(token) ? token : '';
}

// ALLOWLIST, not a coercer: an unrecognised value is DROPPED so the mainline keeps inferring the step
// from text exactly as it does today. A caller cannot widen the vocabulary from the query string.
function normalizeFindProductsMultiStepFamilyParam(value) {
  const token = String(value == null ? '' : value).trim().toLowerCase();
  if (!token) return '';
  return FIND_PRODUCTS_MULTI_STEP_FAMILY_ALLOWLIST.includes(token) ? token : '';
}

// semantic_family is an open vocabulary (oil_control, barrier_repair, ...), so this is a SHAPE
// allowlist: lowercase snake tokens only, bounded length. It reaches a JS post-filter and the semantic
// contract derivation, never a SQL predicate.
function normalizeFindProductsMultiSemanticFamilyParam(value) {
  const token = String(value == null ? '' : value).trim().toLowerCase();
  if (!token) return '';
  if (token.length > 40) return '';
  return /^[a-z][a-z0-9_]*$/.test(token) ? token : '';
}

function buildFindProductsMultiPayloadFromQuery(rawQuery, options = {}) {
  const query = rawQuery && typeof rawQuery === 'object' ? rawQuery : {};
  const search = {};
  const metadata = {};
  const allowEmptyQuery = options && typeof options === 'object' && options.allowEmptyQuery === true;

  const textQuery = extractSearchQueryText(query);
  if (!textQuery && !allowEmptyQuery) return null;
  search.query = textQuery || '';

  const merchantId = String(firstQueryParamValue(query.merchant_id || query.merchantId) || '').trim();
  if (merchantId) search.merchant_id = merchantId;

  const merchantIds = parseQueryStringArray(query.merchant_ids || query.merchantIds);
  if (merchantIds.length > 0) search.merchant_ids = merchantIds;

  const searchAllMerchants = parseQueryBoolean(query.search_all_merchants || query.searchAllMerchants);
  if (searchAllMerchants !== undefined) search.search_all_merchants = searchAllMerchants;

  const inStockOnly = parseQueryBoolean(query.in_stock_only || query.inStockOnly);
  if (inStockOnly !== undefined) search.in_stock_only = inStockOnly;

  const lang = String(firstQueryParamValue(query.lang) || '').trim();
  if (lang) search.lang = lang;

  const category = String(firstQueryParamValue(query.category) || '').trim();
  if (category) search.category = category;

  const catalogSurface = String(firstQueryParamValue(query.catalog_surface || query.catalogSurface) || '').trim();
  if (catalogSurface) search.catalog_surface = catalogSurface;

  const minPrice = parseQueryNumber(query.min_price ?? query.price_min);
  if (minPrice !== undefined) search.min_price = minPrice;

  // The buyer's price ceiling. The Aurora recall client now sends this on its primary query arm
  // (src/auroraBff/routes.js searchPivotaBackendProducts), so it must survive the GET boundary with
  // the same allowlist discipline as target_step_family / semantic_family / query_step_strength.
  //
  // TIGHTENED: a non-positive or non-finite max price used to be forwarded verbatim. `max_price=0`
  // reaches a HARD post-filter downstream (filterFindProductsMultiDirectProductsByBudget), where it
  // drops every priced product and answers zero results for what is almost always a client bug.
  // A refused value is DROPPED, which is exactly today's behavior for callers that send none.
  const maxPrice = normalizeFindProductsMultiMaxPriceParam(query.max_price ?? query.price_max);
  const priceCurrencyRaw = firstQueryParamValue(query.price_currency ?? query.priceCurrency);
  const priceCurrency = normalizeFindProductsMultiPriceCurrencyParam(priceCurrencyRaw);
  const priceCurrencyDeclaredButUnknown =
    priceCurrencyRaw != null && String(priceCurrencyRaw).trim() !== '' && !priceCurrency;
  // A DECLARED but unrecognized currency disables the ceiling outright rather than letting it be read
  // in an assumed unit -- the same refusal the enforcement gate makes (`checkPriceMax` returns
  // 'unverifiable', never a pass, when the currencies differ). This lane holds no FX rates.
  if (maxPrice !== undefined && !priceCurrencyDeclaredButUnknown) {
    search.max_price = maxPrice;
    if (priceCurrency) search.price_currency = priceCurrency;
  }

  const allowExternalSeed = parseQueryBoolean(query.allow_external_seed ?? query.allowExternalSeed);
  if (allowExternalSeed !== undefined) search.allow_external_seed = allowExternalSeed;

  const allowStaleCache = parseQueryBoolean(query.allow_stale_cache ?? query.allowStaleCache);
  if (allowStaleCache !== undefined) search.allow_stale_cache = allowStaleCache;

  const fastMode = parseQueryBoolean(query.fast_mode ?? query.fastMode);
  if (fastMode !== undefined) search.fast_mode = fastMode;

  const externalSeedStrategy = String(
    firstQueryParamValue(query.external_seed_strategy || query.externalSeedStrategy) || '',
  ).trim();
  if (externalSeedStrategy) search.external_seed_strategy = externalSeedStrategy;

  // Structured recall params. The Aurora reco recall client already SENDS these on every catalog
  // search (src/auroraBff/routes.js ~5703-5713) and this builder parsed none of them, so the declared
  // step was thrown away at the HTTP boundary and the mainline re-inferred it from query text that the
  // planner had already polluted. All three are OPTIONAL and allowlist-normalized: an unknown or
  // malformed value is dropped, never forwarded, so every existing caller is unaffected.
  const targetStepFamily = normalizeFindProductsMultiStepFamilyParam(
    firstQueryParamValue(query.target_step_family || query.targetStepFamily),
  );
  if (targetStepFamily) search.target_step_family = targetStepFamily;

  const semanticFamily = normalizeFindProductsMultiSemanticFamilyParam(
    firstQueryParamValue(query.semantic_family || query.semanticFamily),
  );
  if (semanticFamily) search.semantic_family = semanticFamily;

  const queryStepStrength = normalizeQueryStepStrength(
    firstQueryParamValue(query.query_step_strength || query.queryStepStrength),
  );
  if (queryStepStrength) search.query_step_strength = queryStepStrength;

  const limit = parseQueryNumber(query.limit ?? query.page_size);
  if (limit !== undefined) search.limit = Math.max(1, Math.min(SEARCH_LIMIT_MAX, Math.floor(limit)));

  const offset = parseQueryNumber(query.offset);
  if (offset !== undefined) {
    const normalizedOffset = Math.max(0, Math.floor(offset));
    if (search.limit) {
      search.page = Math.floor(normalizedOffset / search.limit) + 1;
    } else {
      search.offset = normalizedOffset;
    }
  }

  const source = String(firstQueryParamValue(query.source) || '').trim().toLowerCase();
  if (source) metadata.source = source;

  const context = applyTravelLookupContinuationFromQuery({
    query,
    search,
    metadata,
  });

  if (!metadata.source && !search.catalog_surface && textQuery) {
    const beautyQueryProfile = buildBeautyQueryProfile({ rawQuery: textQuery });
    if (beautyQueryProfile?.isBeautyQuery) {
      metadata.source = 'aurora-bff';
      search.catalog_surface = 'beauty';
    }
  }

  const payload = { search };
  if (context) payload.context = context;
  if (Object.keys(metadata).length > 0) payload.metadata = metadata;
  return payload;
}

function resolvePublicSearchRouteSessionId({ req, query = null, metadata = null } = {}) {
  const queryParams =
    query && typeof query === 'object' && !Array.isArray(query) ? query : {};
  const requestMetadata =
    metadata && typeof metadata === 'object' && !Array.isArray(metadata) ? metadata : {};
  const headerSessionId =
    req && typeof req.header === 'function'
      ? req.header('x-session-id') || req.header('X-Session-Id')
      : null;
  return (
    String(
      firstQueryParamValue(queryParams.session_id || queryParams.sessionId) ||
        requestMetadata.session_id ||
        requestMetadata.sessionId ||
        headerSessionId ||
        '',
    ).trim() || null
  );
}

function resolveLegacyBeautyCacheOwnerBypassForPublicSearchRoute() {
  return {
    bypass: false,
    semanticContract: null,
  };
}

const agentProductsSearchRouteEntryRuntime = createFindProductsSearchRouteEntryRuntime({
  resolveGuidanceSearchSessionId: resolvePublicSearchRouteSessionId,
  firstQueryParamValue,
  buildFindProductsMultiPayloadFromQuery,
  buildFindProductsSearchRequestContract,
  resolveLegacyBeautyCacheOwnerBypass: resolveLegacyBeautyCacheOwnerBypassForPublicSearchRoute,
  normalizeAgentSource,
  runGuidanceServerOwnedLadderSearch: async () => null,
  persistGuidanceSearchSeenProducts: async () => false,
  normalizeSearchUiSurface,
  normalizeRecommendationDecisionMode,
  searchExternalSeedOnlyProductsDirect: async () => null,
  searchIngredientIntentProductsDirect: async () => null,
});

async function searchExternalSeedBrandCandidatesLocally({
  queryText,
  neededCount,
  inStockOnly = true,
} = {}) {
  const normalizedQueryText = String(queryText || '').trim();
  if (!process.env.DATABASE_URL || !normalizedQueryText) return null;

  const brandDetection = detectBrandEntities(normalizedQueryText, { candidateProducts: [] });
  if (!brandDetection?.brand_like) return null;

  const requestedCount = Math.max(1, Number(neededCount || 1));
  const retrievalLimit = Math.min(Math.max(requestedCount * 3, 24), SEARCH_LIMIT_MAX);
  const market =
    String(process.env.CREATOR_CATEGORIES_EXTERNAL_SEED_MARKET || 'US').trim().toUpperCase() || 'US';
  const brandTerms = Array.isArray(brandDetection?.brands)
    ? brandDetection.brands.map((item) => normalizeSearchTextForMatch(item)).filter(Boolean)
    : [];

  const directResponse = await runExternalSeedBrandMainlineFastpath({
    relevanceQueryText: normalizedQueryText,
    market,
    tool: '*',
    inStockOnly,
    includeAttached: true,
    safePage: 1,
    safeLimit: retrievalLimit,
    safeOffset: 0,
    deps: {
      detectBrandEntities,
      normalizeSearchTextForMatch,
      buildBrandQueryVariants,
      normalizeBrandText,
      buildExternalSeedBrandSearchProduct,
      buildSearchProductKey,
      query,
      logger,
    },
  });
  if (!directResponse || !Array.isArray(directResponse.products)) return null;

  const normalizedQuery = normalizeSearchTextForMatch(normalizedQueryText);
  const anchorTokens = extractSearchAnchorTokens(normalizedQueryText);
  const queryTokens = Array.from(new Set(tokenizeSearchTextForMatch(normalizedQuery)));
  const relevantProducts = directResponse.products.filter((product) =>
    isSupplementCandidateRelevant(product, normalizedQueryText, {
      normalizedQuery,
      anchorTokens,
      queryTokens,
      brandTerms,
    }),
  );
  const pagedProducts = relevantProducts.slice(0, requestedCount);

  return {
    ...directResponse,
    products: pagedProducts,
    total: relevantProducts.length,
    page: 1,
    page_size: pagedProducts.length,
    metadata: {
      ...(directResponse.metadata && typeof directResponse.metadata === 'object'
        ? directResponse.metadata
        : {}),
      external_seed_brand_relevant_count: relevantProducts.length,
      external_seed_brand_filtered_out_count: Math.max(
        0,
        (Array.isArray(directResponse.products) ? directResponse.products.length : 0) -
          relevantProducts.length,
      ),
    },
  };
}

async function fetchExternalSeedSupplementFromBackend({
  queryParams,
  checkoutToken,
  neededCount,
  source,
  directOnly = false,
}) {
  const query = queryParams && typeof queryParams === 'object' ? queryParams : {};
  const queryText = extractSearchQueryText(query);
  if (!queryText) {
    return {
      products: [],
      metadata: { attempted: false, applied: false, reason: 'empty_query', requested_count: Number(neededCount || 0) },
    };
  }

  const requestedCount = Math.max(1, Number(neededCount || 1));
  const limit = Math.min(Math.max(requestedCount * 6, 48), 320);
  const localBrandDirectResponse = await searchExternalSeedBrandCandidatesLocally({
    queryText,
    neededCount: requestedCount,
    inStockOnly: parseQueryBoolean(query.in_stock_only ?? query.inStockOnly) !== false,
  });
  if (localBrandDirectResponse && Array.isArray(localBrandDirectResponse.products)) {
    const directProducts = localBrandDirectResponse.products.filter((product) =>
      isExternalSeedProduct(product),
    );
    const directMeta =
      localBrandDirectResponse.metadata &&
      typeof localBrandDirectResponse.metadata === 'object' &&
      !Array.isArray(localBrandDirectResponse.metadata)
        ? localBrandDirectResponse.metadata
        : {};
    const directBrandTerms = Array.isArray(directMeta.search_decision?.retrieval_query_variants)
      ? Array.from(
          new Set(
            directMeta.search_decision.retrieval_query_variants
              .map((item) => String(item || '').trim())
              .filter(Boolean),
          ),
        )
      : [];
    if (directProducts.length > 0) {
      return {
        products: directProducts,
        metadata: {
          attempted: true,
          applied: true,
          reason: 'external_seed_direct_local_hit',
          requested_count: requestedCount,
          fetched_count: directProducts.length,
          fetched_raw_count:
            Number(
              directMeta.external_seed_brand_relevant_count ||
                directMeta.external_seed_rows_built ||
                directProducts.length,
            ) || directProducts.length,
          fetched_variant_count:
            Number(directMeta.retrieval_query_variant_count || directMeta.query_variants?.length || 0) || 0,
          upstream_calls: 0,
          brand_query_detected: true,
          brand_entities: directBrandTerms,
          brand_scope: hasExplicitCategoryHint(queryText, null) ? 'category_scoped' : 'broad',
          filtered_out_irrelevant_count:
            Number(directMeta.external_seed_brand_filtered_out_count || 0) || 0,
          query_variants: Array.isArray(directMeta.retrieval_query_variants)
            ? directMeta.retrieval_query_variants
            : [queryText],
          upstream_status: 200,
          retrieval_mode: 'direct_local_brand_mainline',
          retrieval_tool_scope: directMeta.retrieval_tool_scope || null,
          retrieval_include_attached: directMeta.retrieval_include_attached === true,
          external_seed_rows_raw:
            Number(directMeta.raw_result_count || directMeta.external_seed_rows_fetched || directProducts.length) ||
            directProducts.length,
          external_seed_rows_relevant:
            Number(directMeta.external_seed_brand_relevant_count || directProducts.length) || directProducts.length,
        },
      };
    }
    if (directOnly) {
      return {
        products: [],
        metadata: {
          attempted: true,
          applied: false,
          reason: 'external_seed_direct_local_empty',
          requested_count: requestedCount,
          fetched_count: 0,
          fetched_raw_count:
            Number(directMeta.raw_result_count || directMeta.external_seed_rows_fetched || 0) || 0,
          fetched_variant_count:
            Number(directMeta.retrieval_query_variant_count || directMeta.query_variants?.length || 0) || 0,
          upstream_calls: 0,
          upstream_status: 200,
          retrieval_tool_scope: directMeta.retrieval_tool_scope || null,
          retrieval_include_attached: directMeta.retrieval_include_attached === true,
          query_variants: Array.isArray(directMeta.retrieval_query_variants)
            ? directMeta.retrieval_query_variants
            : [queryText],
        },
      };
    }
  }
  if (directOnly) {
    return {
      products: [],
      metadata: {
        attempted: false,
        applied: false,
        reason: 'external_seed_direct_local_unavailable',
        requested_count: requestedCount,
        fetched_count: 0,
        fetched_raw_count: 0,
        fetched_variant_count: 0,
        upstream_calls: 0,
        upstream_status: 0,
        query_variants: [queryText],
      },
    };
  }
  const hardBudgetMs = Math.max(
    800,
    Number(process.env.PROXY_SEARCH_EXTERNAL_SEED_SUPPLEMENT_BUDGET_MS || 4400),
  );
  const startedAtMs = Date.now();
  const brandDetection = detectBrandEntities(queryText, { candidateProducts: [] });
  const hasExplicitCategory = hasExplicitCategoryHint(queryText, null);
  const beautyQueryProfile = buildBeautyQueryProfile({ rawQuery: queryText });
  const brandTerms = Array.isArray(brandDetection?.brands)
    ? brandDetection.brands.map((item) => normalizeSearchTextForMatch(item)).filter(Boolean)
    : [];
  const baseVariants = buildBrandQueryVariants(queryText, brandTerms);
  const fragranceVariants =
    beautyQueryProfile?.bucket === 'fragrance'
      ? ['perfume', 'fragrance', 'parfum', 'cologne', 'body mist', 'eau de parfum']
      : [];
  const queryVariants = Array.from(
    new Set([queryText, ...baseVariants, ...fragranceVariants].map((item) => String(item || '').trim()).filter(Boolean)),
  ).slice(0, 4);
  const url = `${getProxySearchApiBase(source)}/agent/v1/products/search`;
  const requestHeaders = {
    ...buildInvokeUpstreamAuthHeaders({ checkoutToken }),
  };
  const seenKeys = new Set();
  const mergedProducts = [];
  let upstreamStatus = 0;
  let upstreamCalls = 0;
  let rawFetchedCount = 0;
  let budgetExhausted = false;

  for (const variant of queryVariants) {
    const elapsedMs = Date.now() - startedAtMs;
    const remainingBudgetMs = hardBudgetMs - elapsedMs;
    if (remainingBudgetMs <= 0) {
      budgetExhausted = true;
      break;
    }
    const upstreamParams = {
      merchant_id: 'external_seed',
      external_seed_only: true,
      query: variant,
      ...(query.category ? { category: query.category } : {}),
      ...(query.min_price != null ? { min_price: query.min_price } : {}),
      ...(query.max_price != null ? { max_price: query.max_price } : {}),
      in_stock_only: parseQueryBoolean(query.in_stock_only ?? query.inStockOnly) !== false,
      limit,
      offset: 0,
      allow_external_seed: true,
      allow_stale_cache: false,
      external_seed_strategy: 'supplement_internal_first',
      fast_mode: true,
    };
    const resp = await axios({
      method: 'GET',
      url,
      params: upstreamParams,
      headers: requestHeaders,
      timeout: Math.max(
        500,
        Math.min(
          remainingBudgetMs,
          2500,
          getUpstreamTimeoutMs('find_products_multi'),
        ),
      ),
      validateStatus: () => true,
    });
    upstreamCalls += 1;
    upstreamStatus = Math.max(upstreamStatus, Number(resp.status || 0) || 0);
    if (!(resp.status >= 200 && resp.status < 300)) continue;

    const normalized = normalizeAgentProductsListResponse(resp.data, {
      limit,
      offset: 0,
    });
    const products = Array.isArray(normalized?.products)
      ? normalized.products.filter((p) => isExternalSeedProduct(p))
      : [];
    rawFetchedCount += products.length;
    for (const product of products) {
      const key = buildSearchProductKey(product);
      if (!key || seenKeys.has(key)) continue;
      seenKeys.add(key);
      mergedProducts.push(product);
    }
    if (mergedProducts.length >= requestedCount) {
      break;
    }
  }

  const normalizedQuery = normalizeSearchTextForMatch(queryText);
  const anchorTokens = extractSearchAnchorTokens(queryText);
  const queryTokens = Array.from(new Set(tokenizeSearchTextForMatch(normalizedQuery)));
  const relevantProducts = mergedProducts.filter((p) =>
    isSupplementCandidateRelevant(p, queryText, {
      normalizedQuery,
      anchorTokens,
      queryTokens,
      brandTerms,
    }),
  );
  const filteredOutIrrelevantCount = Math.max(0, mergedProducts.length - relevantProducts.length);

  return {
    products: relevantProducts,
    metadata: {
      attempted: true,
      applied: relevantProducts.length > 0,
      reason:
        relevantProducts.length > 0
          ? 'external_seed_candidates_found'
          : filteredOutIrrelevantCount > 0
            ? 'external_seed_candidates_filtered_irrelevant'
            : 'no_external_seed_candidates',
      requested_count: requestedCount,
      fetched_count: relevantProducts.length,
      fetched_raw_count: rawFetchedCount,
      fetched_variant_count: queryVariants.length,
      upstream_calls: upstreamCalls,
      brand_query_detected: Boolean(brandDetection?.brand_like),
      brand_entities: brandTerms,
      brand_scope: hasExplicitCategory ? 'category_scoped' : 'broad',
      beauty_query_bucket: beautyQueryProfile?.bucket || null,
      filtered_out_irrelevant_count: filteredOutIrrelevantCount,
      query_variants: queryVariants,
      upstream_status: upstreamStatus,
      supplement_budget_ms: hardBudgetMs,
      supplement_budget_exhausted: budgetExhausted,
    },
  };
}

async function maybeRescueBrandLikeSearchFromLocalExternalSeed({
  operation,
  upstreamData,
  queryText,
  queryParams,
  source,
  checkoutToken,
  upstreamStatus = null,
} = {}) {
  if (
    (operation !== 'find_products' && operation !== 'find_products_multi') ||
    !upstreamData ||
    typeof upstreamData !== 'object' ||
    Array.isArray(upstreamData)
  ) {
    return upstreamData;
  }

  const normalizedQueryText = String(queryText || '').trim();
  if (!normalizedQueryText) return upstreamData;

  const upstreamMeta =
    upstreamData.metadata && typeof upstreamData.metadata === 'object' && !Array.isArray(upstreamData.metadata)
      ? upstreamData.metadata
      : {};
  if (
    Object.prototype.hasOwnProperty.call(upstreamMeta, 'external_seed_brand_rescue_attempted') ||
    Object.prototype.hasOwnProperty.call(upstreamMeta, 'external_seed_brand_rescue_applied')
  ) {
    return upstreamData;
  }
  const existingProducts = Array.isArray(upstreamData.products) ? upstreamData.products : [];
  const hasClarification = Boolean(upstreamData?.clarification?.question);
  if (existingProducts.length > 0 || hasClarification) return upstreamData;

  const requestedMerchantId = String(
    firstQueryParamValue(queryParams?.merchant_id || queryParams?.merchantId || ''),
  ).trim();
  if (requestedMerchantId) return upstreamData;

  const routeHealth =
    upstreamMeta.route_health &&
    typeof upstreamMeta.route_health === 'object' &&
    !Array.isArray(upstreamMeta.route_health)
      ? upstreamMeta.route_health
      : {};
  const externalSeedSkipReason = String(
    routeHealth.external_seed_skip_reason || upstreamMeta.external_seed_skip_reason || '',
  )
    .trim()
    .toLowerCase();
  if (externalSeedSkipReason !== 'seed_loader_error') return upstreamData;

  const brandDetection = detectBrandEntities(normalizedQueryText, { candidateProducts: [] });
  if (!brandDetection?.brand_like) return upstreamData;

  const requestedLimit = Math.min(
    Math.max(1, Number(queryParams?.limit || queryParams?.page_size || 20) || 20),
    SEARCH_LIMIT_MAX,
  );
  const requestedOffset = Math.max(0, Number(queryParams?.offset || 0) || 0);
  const requestedPageFromQuery = Math.max(0, Number(queryParams?.page || 0) || 0);
  const requestedPage =
    requestedPageFromQuery > 0
      ? requestedPageFromQuery
      : Math.floor(requestedOffset / Math.max(1, requestedLimit)) + 1;

  const localSupplement = await fetchExternalSeedSupplementFromBackend({
    queryParams: {
      ...(queryParams && typeof queryParams === 'object' && !Array.isArray(queryParams)
        ? queryParams
        : {}),
      query: normalizedQueryText,
    },
    checkoutToken,
    neededCount: requestedLimit + requestedOffset,
    source,
    directOnly: true,
  });

  const rescuedProducts = Array.isArray(localSupplement?.products) ? localSupplement.products : [];
  const rescueMeta =
    localSupplement?.metadata &&
    typeof localSupplement.metadata === 'object' &&
    !Array.isArray(localSupplement.metadata)
      ? localSupplement.metadata
      : {};
  const existingRouteDebug =
    upstreamMeta.route_debug &&
    typeof upstreamMeta.route_debug === 'object' &&
    !Array.isArray(upstreamMeta.route_debug)
      ? upstreamMeta.route_debug
      : {};

  if (rescuedProducts.length === 0) {
    const localRescueReason = String(rescueMeta.reason || 'external_seed_direct_local_empty').trim();
    return {
      ...upstreamData,
      metadata: {
        ...upstreamMeta,
        external_seed_brand_rescue_attempted: Boolean(rescueMeta.attempted),
        external_seed_brand_rescue_applied: false,
        external_seed_brand_rescue_reason: localRescueReason,
        external_seed_brand_rescue_upstream_query_source:
          String(upstreamMeta.query_source || '').trim() || null,
        external_seed_brand_rescue_skip_reason: externalSeedSkipReason,
        external_seed_brand_rescue_rows_fetched:
          Number(rescueMeta.fetched_raw_count || rescueMeta.external_seed_rows_raw || 0) || 0,
        external_seed_brand_rescue_rows_built:
          Number(rescueMeta.fetched_count || rescueMeta.external_seed_rows_relevant || 0) || 0,
        external_seed_brand_rescue_tool_scope: rescueMeta.retrieval_tool_scope || null,
        external_seed_brand_rescue_include_attached:
          rescueMeta.retrieval_include_attached === true,
        route_health: {
          ...routeHealth,
          external_seed_rescue_attempted: Boolean(rescueMeta.attempted),
          external_seed_rescue_applied: false,
          external_seed_rescue_reason: localRescueReason,
          external_seed_skip_reason: externalSeedSkipReason,
        },
        route_debug: {
          ...existingRouteDebug,
          external_seed_brand_rescue: {
            attempted: Boolean(rescueMeta.attempted),
            applied: false,
            reason: localRescueReason,
            upstream_query_source: String(upstreamMeta.query_source || '').trim() || null,
            upstream_skip_reason: externalSeedSkipReason,
            local_rescue_reason: localRescueReason,
            fetched_raw_count: Number(rescueMeta.fetched_raw_count || 0) || 0,
            fetched_count: Number(rescueMeta.fetched_count || 0) || 0,
            retrieval_tool_scope: rescueMeta.retrieval_tool_scope || null,
            retrieval_include_attached: rescueMeta.retrieval_include_attached === true,
            brand_entities: Array.isArray(brandDetection.brands) ? brandDetection.brands : [],
          },
        },
      },
    };
  }

  return normalizeAgentProductsListResponse(
    {
      status: 'success',
      success: true,
      products: rescuedProducts,
      total: Math.max(
        rescuedProducts.length,
        Number(rescueMeta.external_seed_rows_relevant || rescueMeta.fetched_count || 0) || 0,
      ),
      page: requestedPage,
      page_size: rescuedProducts.length,
      reply: null,
      metadata: {
        ...upstreamMeta,
        query_source: 'agent_products_external_seed_direct',
        strict_empty: false,
        strict_empty_reason: null,
        search_decision: {
          ...(upstreamMeta.search_decision &&
          typeof upstreamMeta.search_decision === 'object' &&
          !Array.isArray(upstreamMeta.search_decision)
            ? upstreamMeta.search_decision
            : {}),
          final_decision: 'products_returned',
          execution_mode: 'external_seed_brand_rescue',
          products_returned_count: rescuedProducts.length,
          brand_search_mainline_query: true,
        },
        source_breakdown: {
          internal_count: 0,
          external_seed_count: rescuedProducts.length,
          stale_cache_used: false,
          strategy_applied: 'brand_search_external_seed_mainline_rescue',
        },
        external_seed_skip_reason: externalSeedSkipReason,
        external_seed_rows_fetched:
          Number(rescueMeta.external_seed_rows_raw || rescueMeta.fetched_raw_count || rescuedProducts.length) ||
          rescuedProducts.length,
        external_seed_rows_built:
          Number(rescueMeta.external_seed_rows_relevant || rescueMeta.fetched_count || rescuedProducts.length) ||
          rescuedProducts.length,
        external_seed_returned_count: rescuedProducts.length,
        external_seed_brand_rescue_attempted: true,
        external_seed_brand_rescue_applied: true,
        external_seed_brand_rescue_reason: 'upstream_seed_loader_error_strict_empty',
        external_seed_brand_rescue_upstream_query_source:
          String(upstreamMeta.query_source || '').trim() || null,
        external_seed_brand_rescue_skip_reason: externalSeedSkipReason,
        external_seed_brand_rescue_upstream_status:
          Number(upstreamMeta.upstream_status || upstreamStatus || 0) || null,
        external_seed_brand_rescue_tool_scope: rescueMeta.retrieval_tool_scope || null,
        external_seed_brand_rescue_include_attached:
          rescueMeta.retrieval_include_attached === true,
        route_health: {
          ...routeHealth,
          external_seed_rescue_attempted: true,
          external_seed_rescue_applied: true,
          external_seed_rescue_reason: 'upstream_seed_loader_error_strict_empty',
          external_seed_skip_reason: externalSeedSkipReason,
        },
        route_debug: {
          ...existingRouteDebug,
          external_seed_brand_rescue: {
            attempted: true,
            applied: true,
            reason: 'upstream_seed_loader_error_strict_empty',
            upstream_query_source: String(upstreamMeta.query_source || '').trim() || null,
            local_rescue_reason: String(rescueMeta.reason || '').trim() || null,
            retrieval_tool_scope: rescueMeta.retrieval_tool_scope || null,
            retrieval_include_attached: rescueMeta.retrieval_include_attached === true,
            brand_entities: Array.isArray(brandDetection.brands) ? brandDetection.brands : [],
          },
        },
      },
    },
    {
      limit: queryParams?.limit,
      offset: queryParams?.offset,
    },
  );
}

function readSearchProductMerchantId(product) {
  return String(
    product?.merchant_id ||
      product?.merchantId ||
      product?.product_ref?.merchant_id ||
      product?.seller?.merchant_id ||
      '',
  ).trim();
}

function readSearchProductIdCandidates(product) {
  return uniqueStrings([
    product?.product_id,
    product?.productId,
    product?.id,
    product?.platform_product_id,
    product?.platformProductId,
    product?.source_product_id,
    product?.sourceProductId,
    product?.product_ref?.product_id,
    product?.product_ref?.platform_product_id,
  ]);
}

async function hydrateFindProductsCatalogIdentityFields(responseBody) {
  if (
    !process.env.DATABASE_URL ||
    !responseBody ||
    typeof responseBody !== 'object' ||
    Array.isArray(responseBody) ||
    !Array.isArray(responseBody.products) ||
    responseBody.products.length === 0
  ) {
    return responseBody;
  }

  const pairKeys = [];
  for (const product of responseBody.products) {
    if (!product || typeof product !== 'object' || Array.isArray(product)) continue;
    const merchantId = readSearchProductMerchantId(product);
    if (!merchantId) continue;
    for (const productId of readSearchProductIdCandidates(product)) {
      if (productId) pairKeys.push(`${merchantId}::${productId}`);
    }
  }

  const uniquePairKeys = uniqueStrings(pairKeys).slice(0, 500);
  if (!uniquePairKeys.length) return responseBody;

  try {
    const result = await query(
      `
        SELECT
          cp.merchant_id,
          cp.source_product_id,
          cp.product_key,
          cp.pivota_signature_id
        FROM catalog_products cp
        WHERE
          (cp.merchant_id || '::' || coalesce(cp.source_product_id, '')) = ANY($1::text[])
          OR (cp.merchant_id || '::' || coalesce(cp.product_key, '')) = ANY($1::text[])
      `,
      [uniquePairKeys],
    );
    const identityByPair = new Map();
    for (const row of result?.rows || []) {
      const merchantId = String(row?.merchant_id || '').trim();
      if (!merchantId) continue;
      const sourceProductId = String(row?.source_product_id || '').trim();
      const productKey = String(row?.product_key || '').trim();
      const sigId = String(row?.pivota_signature_id || '').trim();
      const identity = {
        ...(productKey ? { product_key: productKey } : {}),
        ...(sourceProductId ? { source_product_id: sourceProductId } : {}),
        ...(sigId ? { pivota_signature_id: sigId, signature_id: sigId } : {}),
      };
      if (sourceProductId) identityByPair.set(`${merchantId}::${sourceProductId}`, identity);
      if (productKey) identityByPair.set(`${merchantId}::${productKey}`, identity);
    }
    if (!identityByPair.size) return responseBody;

    let hydratedCount = 0;
    const products = responseBody.products.map((product) => {
      if (!product || typeof product !== 'object' || Array.isArray(product)) return product;
      const merchantId = readSearchProductMerchantId(product);
      if (!merchantId) return product;
      let identity = null;
      for (const productId of readSearchProductIdCandidates(product)) {
        identity = identityByPair.get(`${merchantId}::${productId}`);
        if (identity) break;
      }
      if (!identity) return product;
      hydratedCount += 1;
      return {
        ...product,
        ...identity,
        pivota_signature_id: product.pivota_signature_id || identity.pivota_signature_id,
        signature_id: product.signature_id || identity.signature_id,
        product_key: product.product_key || identity.product_key,
      };
    });

    const metadata =
      responseBody.metadata && typeof responseBody.metadata === 'object' && !Array.isArray(responseBody.metadata)
        ? responseBody.metadata
        : {};
    return {
      ...responseBody,
      products,
      results: Array.isArray(responseBody.results) ? products : responseBody.results,
      data:
        responseBody.data && typeof responseBody.data === 'object' && !Array.isArray(responseBody.data)
          ? {
              ...responseBody.data,
              ...(Array.isArray(responseBody.data.products) ? { products } : {}),
            }
          : responseBody.data,
      metadata: {
        ...metadata,
        catalog_identity_hydration: {
          attempted: true,
          hydrated_count: hydratedCount,
        },
      },
    };
  } catch (err) {
    logger.warn(
      {
        err: err?.message || String(err),
        products_count: responseBody.products.length,
      },
      'find_products catalog identity hydration failed',
    );
    return responseBody;
  }
}

function hasSearchProductIdentityMatch(product, queryText) {
  const normalizedQuery = normalizeSearchTextForMatch(queryText);
  if (!normalizedQuery) return false;
  const compactQuery = normalizedQuery.replace(/\s+/g, '');
  const titleCandidates = normalizeSearchProductMatchTexts([
    product?.title,
    product?.name,
    product?.product_title,
    product?.display_name,
  ]);
  const brandCandidates = normalizeSearchProductMatchTexts([
    product?.brand?.name,
    product?.brand,
    product?.brand_name,
    product?.vendor,
    product?.merchant_name,
  ]);
  if (titleCandidates.some((title) => title === normalizedQuery || normalizedQuery.includes(title))) {
    return true;
  }
  for (const brand of brandCandidates) {
    const compactBrand = brand.replace(/\s+/g, '');
    for (const title of titleCandidates) {
      const titleWithoutBrand = title.startsWith(`${brand} `)
        ? title.slice(brand.length).trim()
        : title;
      if (
        titleWithoutBrand &&
        normalizedQuery.includes(titleWithoutBrand) &&
        compactBrand.length >= 4 &&
        compactQuery.includes(compactBrand)
      ) {
        return true;
      }
    }
  }
  const matchBasis = Array.isArray(product?.match_basis) ? product.match_basis.join(' ') : '';
  return Boolean(matchBasis && normalizeSearchTextForMatch(matchBasis).includes(normalizedQuery));
}

function normalizeSearchProductMatchTexts(values) {
  return uniqueStrings(
    (Array.isArray(values) ? values : [])
      .map((value) => normalizeSearchTextForMatch(value))
      .filter(Boolean),
  );
}

function overlayIdentityRecallOnSearchProduct(product, identityProduct) {
  if (
    !product ||
    typeof product !== 'object' ||
    !identityProduct ||
    typeof identityProduct !== 'object'
  ) {
    return product;
  }
  const merchantId = String(
    product.merchant_id ||
      product.product_ref?.merchant_id ||
      product.seller?.merchant_id ||
      '',
  ).trim();
  const productId = String(
    product.product_id ||
      product.id ||
      product.platform_product_id ||
      product.product_ref?.product_id ||
      '',
  ).trim();
  const selectedRef =
    merchantId && productId
      ? { merchant_id: merchantId, product_id: productId }
      : identityProduct.selected_commerce_ref || identityProduct.product_ref || null;
  const liveOffer = buildSearchProductIdentityOverlayOffer(product, {
    groupId:
      identityProduct.sellable_item_group_id ||
      identityProduct.product_group_id ||
      product.sellable_item_group_id ||
      product.product_group_id ||
      null,
    selected: true,
  });
  const mergedOffers = mergeIdentityOverlayOffers({
    identityOffers: Array.isArray(identityProduct.offers) ? identityProduct.offers : [],
    liveOffer,
  });
  const offerCount = mergedOffers.length
    ? mergedOffers.length
    : Math.max(
        Number(identityProduct.offers_count || 0) || 0,
        Number(product.offers_count || product.offer_count || 0) || 0,
      );
  return {
    ...identityProduct,
    ...product,
    ...(merchantId ? { merchant_id: merchantId } : {}),
    ...(productId ? { product_id: productId, id: productId } : {}),
    ...(selectedRef ? { product_ref: selectedRef, selected_commerce_ref: selectedRef } : {}),
    canonical_product_ref: identityProduct.canonical_product_ref || product.canonical_product_ref || null,
    sellable_item_group_id:
      identityProduct.sellable_item_group_id || product.sellable_item_group_id || null,
    product_group_id: identityProduct.product_group_id || product.product_group_id || null,
    offers: mergedOffers.length
      ? mergedOffers
      : Array.isArray(identityProduct.offers)
        ? identityProduct.offers
        : product.offers,
    offers_count: offerCount,
    offer_count: offerCount,
    has_multiple_offers:
      identityProduct.has_multiple_offers === true ||
      product.has_multiple_offers === true ||
      offerCount > 1,
    grouped:
      identityProduct.grouped === true ||
      product.grouped === true ||
      offerCount > 1,
    pdp_content_source: identityProduct.pdp_content_source || product.pdp_content_source || 'canonical_inherited',
    offer_source: identityProduct.offer_source || product.offer_source || 'group_fused',
    commerce_source: 'selected_seller_store',
    content_review_state:
      identityProduct.content_review_state || product.content_review_state || 'pending',
    search_recall_source: 'pdp_identity_graph',
  };
}

function buildSearchProductIdentityOverlayOffer(product, { groupId = null, selected = false } = {}) {
  if (!product || typeof product !== 'object' || Array.isArray(product)) return null;
  const merchantId = String(
    product.merchant_id ||
      product.merchantId ||
      product.product_ref?.merchant_id ||
      product.seller?.merchant_id ||
      '',
  ).trim();
  const productId = String(
    product.product_id ||
      product.productId ||
      product.id ||
      product.platform_product_id ||
      product.product_ref?.product_id ||
      '',
  ).trim();
  if (!merchantId || !productId) return null;
  const rawPrice =
    product.price ??
    product.current_price ??
    product.unit_price ??
    product.pricing?.price ??
    product.amount ??
    null;
  let price = null;
  if (rawPrice && typeof rawPrice === 'object' && !Array.isArray(rawPrice)) {
    const amount = Number(rawPrice.amount ?? rawPrice.value ?? rawPrice.price);
    const currency =
      String(rawPrice.currency || rawPrice.currencyCode || product.currency || 'USD').trim() || 'USD';
    if (Number.isFinite(amount)) price = { amount, currency };
  } else {
    const amount = Number(rawPrice);
    const currency =
      String(product.currency || product.price_currency || product.currency_code || 'USD').trim() || 'USD';
    if (Number.isFinite(amount)) price = { amount, currency };
  }
  const merchantName = firstNonEmptyString(
    product.merchant_name,
    product.store_name,
    product.seller?.name,
    product.vendor,
    product.brand?.name,
    product.brand,
  );
  return {
    offer_id: `of_identity_live_${merchantId}_${productId}`,
    ...(groupId ? { product_group_id: groupId } : {}),
    merchant_id: merchantId,
    product_id: productId,
    product_ref: { merchant_id: merchantId, product_id: productId },
    ...(merchantName ? { merchant_name: merchantName } : {}),
    ...(price ? { price } : {}),
    ...(product.inventory ? { inventory: product.inventory } : {}),
    ...(product.shipping ? { shipping: product.shipping } : {}),
    ...pickSavingsPresentationFields(product),
    offer_source: 'group_fused',
    commerce_source: 'selected_seller_store',
    ...(selected ? { selected: true } : {}),
  };
}

function mergeIdentityOverlayOffers({ identityOffers = [], liveOffer = null } = {}) {
  const normalizedIdentityOffers = Array.isArray(identityOffers)
    ? identityOffers.filter((offer) => offer && typeof offer === 'object' && !Array.isArray(offer))
    : [];
  if (!liveOffer) return normalizedIdentityOffers;
  const liveMerchant = String(liveOffer.merchant_id || liveOffer.product_ref?.merchant_id || '').trim();
  const liveProduct = String(liveOffer.product_id || liveOffer.product_ref?.product_id || '').trim();
  const merged = [liveOffer];
  const seen = new Set([`${liveMerchant}::${liveProduct}`]);
  for (const offer of normalizedIdentityOffers) {
    const merchantId = String(offer.merchant_id || offer.product_ref?.merchant_id || '').trim();
    const productId = String(offer.product_id || offer.product_ref?.product_id || '').trim();
    if (!merchantId || !productId) continue;
    if (merchantId === liveMerchant) continue;
    const key = `${merchantId}::${productId}`;
    if (seen.has(key)) continue;
    seen.add(key);
    merged.push(offer);
  }
  return merged;
}

function scoreIdentityFinalOverlayCandidate(product, queryText, identityProduct) {
  if (!product || typeof product !== 'object') return -Infinity;
  if (!hasSearchProductIdentityMatch(product, queryText)) return -Infinity;
  const queryNorm = normalizeSearchTextForMatch(queryText);
  const queryCompact = queryNorm.replace(/\s+/g, '');
  const titleCandidates = normalizeSearchProductMatchTexts([
    product.title,
    product.name,
    product.product_title,
    product.display_name,
  ]);
  const merchantId = String(
    product.merchant_id || product.merchantId || product.product_ref?.merchant_id || '',
  ).trim();
  const productId = String(
    product.product_id || product.productId || product.id || product.platform_product_id || '',
  ).trim();
  const identitySelectedMerchant = String(
    identityProduct?.selected_commerce_ref?.merchant_id || identityProduct?.merchant_id || '',
  ).trim();
  const identitySelectedProduct = String(
    identityProduct?.selected_commerce_ref?.product_id || identityProduct?.product_id || identityProduct?.id || '',
  ).trim();
  let score = 0;
  let titleScore = 0;
  for (const titleNorm of titleCandidates) {
    const titleCompact = titleNorm.replace(/\s+/g, '');
    if (titleNorm === queryNorm) titleScore = Math.max(titleScore, 60);
    else if (titleCompact && titleCompact === queryCompact) titleScore = Math.max(titleScore, 48);
    else if (queryNorm.includes(titleNorm)) titleScore = Math.max(titleScore, 24);
    else if (titleNorm.includes(queryNorm)) titleScore = Math.max(titleScore, 18);
  }
  score += titleScore;
  if (!product.sellable_item_group_id && !product.product_group_id) score += 20;
  if (merchantId && identitySelectedMerchant && merchantId === identitySelectedMerchant) score += 12;
  if (merchantId && merchantId !== EXTERNAL_SEED_MERCHANT_ID) score += 8;
  if (productId && identitySelectedProduct && productId !== identitySelectedProduct) score += 6;
  if (Number(product.price?.amount ?? product.price ?? 0) > 0) score += 3;
  return score;
}

function maybeOverlayFinalIdentityRecallSearchProducts({
  operation,
  responseBody,
  queryText,
  queryParams,
} = {}) {
  if (
    operation !== 'find_products_multi' ||
    !responseBody ||
    typeof responseBody !== 'object' ||
    Array.isArray(responseBody)
  ) {
    return responseBody;
  }
  const normalizedQueryText = String(queryText || '').trim();
  if (!normalizedQueryText || !Array.isArray(responseBody.products) || responseBody.products.length < 2) {
    return responseBody;
  }
  const products = responseBody.products;
  const identityProducts = products.filter((product) => {
    const groupId = String(product?.sellable_item_group_id || product?.product_group_id || '').trim();
    if (!groupId) return false;
    return (
      product?.search_recall_source === 'pdp_identity_graph' ||
      product?.offer_source === 'group_fused' ||
      product?.pdp_content_source === 'canonical_inherited'
    );
  });
  if (!identityProducts.length) return responseBody;

  let bestPair = null;
  for (const identityProduct of identityProducts) {
    for (const product of products) {
      if (!product || product === identityProduct) continue;
      const productGroupId = String(product.sellable_item_group_id || product.product_group_id || '').trim();
      if (productGroupId) continue;
      const score = scoreIdentityFinalOverlayCandidate(product, normalizedQueryText, identityProduct);
      if (!Number.isFinite(score)) continue;
      if (!bestPair || score > bestPair.score) {
        bestPair = { identityProduct, product, score };
      }
    }
  }
  if (!bestPair || bestPair.score <= 0) return responseBody;

  const upgradedProduct = overlayIdentityRecallOnSearchProduct(bestPair.product, bestPair.identityProduct);
  const upgradedKey = buildSearchProductKey(upgradedProduct);
  const originalCandidateKey = buildSearchProductKey(bestPair.product);
  const upgradedGroupId = String(
    upgradedProduct.sellable_item_group_id || upgradedProduct.product_group_id || '',
  ).trim();
  const seenKeys = new Set();
  const nextProducts = [];
  const pushProduct = (product) => {
    if (!product || typeof product !== 'object' || Array.isArray(product)) return;
    const key = buildSearchProductKey(product);
    if (key && seenKeys.has(key)) return;
    if (key) seenKeys.add(key);
    nextProducts.push(product);
  };
  pushProduct(upgradedProduct);
  for (const product of products) {
    const productKey = buildSearchProductKey(product);
    if (productKey && (productKey === upgradedKey || productKey === originalCandidateKey)) continue;
    const productGroupId = String(product?.sellable_item_group_id || product?.product_group_id || '').trim();
    if (
      upgradedGroupId &&
      productGroupId === upgradedGroupId &&
      product?.search_recall_source === 'pdp_identity_graph'
    ) {
      continue;
    }
    pushProduct(product);
  }
  const limit = Math.min(
    Math.max(
      1,
      Number(queryParams?.limit || queryParams?.page_size || responseBody.page_size || products.length) ||
        products.length,
    ),
    Math.max(products.length, 1),
  );
  const limitedProducts = nextProducts.slice(0, limit);
  const existingMeta =
    responseBody.metadata && typeof responseBody.metadata === 'object' && !Array.isArray(responseBody.metadata)
      ? responseBody.metadata
      : {};
  return {
    ...responseBody,
    products: limitedProducts,
    results: Array.isArray(responseBody.results) ? limitedProducts : responseBody.results,
    data:
      responseBody.data && typeof responseBody.data === 'object' && !Array.isArray(responseBody.data)
        ? {
            ...responseBody.data,
            ...(Array.isArray(responseBody.data.products) ? { products: limitedProducts } : {}),
          }
        : responseBody.data,
    total: Math.max(Number(responseBody.total || 0) || 0, limitedProducts.length),
    count: Math.max(Number(responseBody.count || 0) || 0, limitedProducts.length),
    metadata: {
      ...existingMeta,
      identity_graph_search_recall: {
        ...(existingMeta.identity_graph_search_recall &&
        typeof existingMeta.identity_graph_search_recall === 'object' &&
        !Array.isArray(existingMeta.identity_graph_search_recall)
          ? existingMeta.identity_graph_search_recall
          : {}),
        final_live_overlay_applied: true,
        final_live_overlay_reason: 'exact_live_product_after_identity_recall',
        final_live_overlay_selected_ref: upgradedProduct.selected_commerce_ref || null,
      },
    },
  };
}

function getProductRefCandidatesForSavings(source) {
  if (!source || typeof source !== 'object' || Array.isArray(source)) return [];
  const candidates = [
    source.selected_commerce_ref,
    source.selectedCommerceRef,
    source.product_ref,
    source.productRef,
    {
      merchant_id: source.merchant_id || source.merchantId,
      product_id:
        source.product_id ||
        source.productId ||
        source.id ||
        source.platform_product_id ||
        source.platformProductId,
    },
  ];
  const seen = new Set();
  return candidates
    .map((ref) => ({
      merchant_id: String(ref?.merchant_id || ref?.merchantId || '').trim(),
      product_id: String(ref?.product_id || ref?.productId || ref?.id || '').trim(),
    }))
    .filter((ref) => {
      if (!ref.merchant_id || !ref.product_id || isExternalSeedListingMerchantId(ref.merchant_id)) {
        return false;
      }
      const key = `${ref.merchant_id}::${ref.product_id}`;
      if (seen.has(key)) return false;
      seen.add(key);
      return true;
    });
}

async function hydrateSearchSavingsPresentationFromUpstream({
  operation,
  responseBody,
  checkoutToken,
  maxProducts = 10,
  maxOffers = 30,
} = {}) {
  if (
    operation !== 'find_products_multi' ||
    !responseBody ||
    typeof responseBody !== 'object' ||
    Array.isArray(responseBody) ||
    !Array.isArray(responseBody.products) ||
    responseBody.products.length === 0
  ) {
    return responseBody;
  }

  const evidenceByRef = new Map();
  const fetchEvidenceForRef = async (ref) => {
    const key = `${ref.merchant_id}::${ref.product_id}`;
    if (evidenceByRef.has(key)) return evidenceByRef.get(key);
    const hydrated = await hydrateSavingsPresentationFromUpstream({
      product: {
        merchant_id: ref.merchant_id,
        product_id: ref.product_id,
      },
      checkoutToken,
      force: true,
    }).catch(() => null);
    const evidence = hasSavingsPresentationFields(hydrated)
      ? pickSavingsPresentationFields(hydrated)
      : {};
    evidenceByRef.set(key, evidence);
    return evidence;
  };

  let offerBudget = Math.max(0, Number(maxOffers) || 0);
  let applied = false;
  const products = [];
  for (const product of responseBody.products.slice(0, Math.max(1, Number(maxProducts) || 1))) {
    if (!product || typeof product !== 'object' || Array.isArray(product)) {
      products.push(product);
      continue;
    }

    let nextProduct = product;
    const productHasMultipleOffers =
      (Array.isArray(product.offers) && product.offers.length > 1) ||
      Number(product.offers_count || product.offer_count || 0) > 1;

    if (productHasMultipleOffers && Array.isArray(product.offers) && product.offers.length && offerBudget > 0) {
      const nextOffers = [];
      for (const offer of product.offers) {
        if (!offer || typeof offer !== 'object' || Array.isArray(offer)) {
          nextOffers.push(offer);
          continue;
        }
        let nextOffer = offer;
        const offerRefs = getProductRefCandidatesForSavings(offer);
        for (const ref of offerRefs) {
          if (offerBudget <= 0) break;
          offerBudget -= 1;
          // eslint-disable-next-line no-await-in-loop
          const evidence = await fetchEvidenceForRef(ref);
          if (hasSavingsPresentationFields(evidence)) {
            nextOffer = mergeSavingsPresentationFields(nextOffer, evidence);
            applied = true;
            break;
          }
        }
        nextOffers.push(nextOffer);
      }
      nextProduct = {
        ...nextProduct,
        offers: nextOffers,
      };
    }

    products.push(nextProduct);
  }
  if (responseBody.products.length > products.length) {
    products.push(...responseBody.products.slice(products.length));
  }
  if (!applied) return responseBody;
  const existingMeta =
    responseBody.metadata && typeof responseBody.metadata === 'object' && !Array.isArray(responseBody.metadata)
      ? responseBody.metadata
      : {};
  return {
    ...responseBody,
    products,
    results: Array.isArray(responseBody.results) ? products : responseBody.results,
    data:
      responseBody.data && typeof responseBody.data === 'object' && !Array.isArray(responseBody.data)
        ? {
            ...responseBody.data,
            ...(Array.isArray(responseBody.data.products) ? { products } : {}),
          }
        : responseBody.data,
    metadata: {
      ...existingMeta,
      savings_presentation_hydrated: true,
    },
  };
}

async function findLiveIdentitySearchProductForRecall({
  queryText,
  identityProducts = [],
  queryFn = query,
} = {}) {
  const normalizedQueryText = normalizeSearchTextForMatch(queryText);
  const compactQueryText = normalizedQueryText.replace(/\s+/g, '');
  if (!compactQueryText || compactQueryText.length < 5 || !process.env.DATABASE_URL) return null;
  const groupProducts = Array.isArray(identityProducts)
    ? identityProducts.filter((product) =>
        String(product?.sellable_item_group_id || product?.product_group_id || '').trim(),
      )
    : [];
  if (!groupProducts.length || typeof queryFn !== 'function') return null;
  const groupById = new Map();
  for (const product of groupProducts) {
    const groupId = String(product.sellable_item_group_id || product.product_group_id || '').trim();
    if (groupId && !groupById.has(groupId)) groupById.set(groupId, product);
  }
  if (!groupById.size) return null;

  try {
    const titleCompactExpr =
      "regexp_replace(lower(coalesce(product_data->>'title', product_data->>'name', '')), '[^[:alnum:]]+', '', 'g')";
    const result = await queryFn(
      `
        SELECT merchant_id, platform_product_id, product_data, cached_at
        FROM products_cache
        WHERE merchant_id <> $1
          AND ${activeProductsCacheSourceWhere('products_cache')}
          AND length(${titleCompactExpr}) >= 5
          AND (
            ${titleCompactExpr} = $2
            OR ${titleCompactExpr} LIKE ('%' || $2 || '%')
            OR $2 LIKE ('%' || ${titleCompactExpr} || '%')
          )
        ORDER BY
          CASE WHEN ${titleCompactExpr} = $2 THEN 0 ELSE 1 END,
          cached_at DESC NULLS LAST
        LIMIT 25
      `,
      [EXTERNAL_SEED_MERCHANT_ID, compactQueryText],
    );
    for (const row of result?.rows || []) {
      const merchantId = String(row?.merchant_id || '').trim();
      const productId = String(row?.platform_product_id || '').trim();
      const productData =
        row?.product_data && typeof row.product_data === 'object' && !Array.isArray(row.product_data)
          ? row.product_data
          : {};
      if (!merchantId || !productId) continue;
      const liveIdentity = await maybeBuildLiveSyntheticPdp({
        merchantId,
        productId,
        canonicalProduct: {
          ...productData,
          merchant_id: merchantId,
          product_id: productId,
          id: productId,
          platform_product_id: productId,
        },
        queryFn,
      }).catch(() => null);
      const liveGroupId = String(liveIdentity?.sellable_item_group_id || '').trim();
      const identityProduct = liveGroupId ? groupById.get(liveGroupId) : null;
      if (!identityProduct) continue;
      return overlayIdentityRecallOnSearchProduct(
        {
          ...productData,
          merchant_id: merchantId,
          product_id: productId,
          id: productId,
          platform_product_id: productId,
        },
        identityProduct,
      );
    }
  } catch (err) {
    logger.warn(
      {
        err: err?.message || String(err),
        query_text: queryText,
      },
      'live product identity search recall failed',
    );
  }
  return null;
}

async function maybeRescueSearchFromPdpIdentityGraph({
  operation,
  upstreamData,
  queryText,
  queryParams,
} = {}) {
  if (
    operation !== 'find_products_multi' ||
    !upstreamData ||
    typeof upstreamData !== 'object' ||
    Array.isArray(upstreamData)
  ) {
    return upstreamData;
  }
  const normalizedQueryText = String(queryText || '').trim();
  if (!normalizedQueryText) return upstreamData;
  const existingProducts = Array.isArray(upstreamData.products) ? upstreamData.products : [];
  const existingGroupedIdentityMatch = existingProducts.some(
    (product) =>
      hasSearchProductIdentityMatch(product, normalizedQueryText) &&
      (String(product?.sellable_item_group_id || product?.product_group_id || '').trim() ||
        product?.offer_source === 'group_fused' ||
        product?.pdp_content_source === 'canonical_inherited'),
  );
  if (existingGroupedIdentityMatch) {
    return upstreamData;
  }
  const requestedLimit = Math.min(
    Math.max(1, Number(queryParams?.limit || queryParams?.page_size || 20) || 20),
    SEARCH_LIMIT_MAX,
  );
  const identityRecall = await searchPdpIdentityGroupsForQuery({
    queryText: normalizedQueryText,
    limit: Math.min(requestedLimit, 5),
  });
  const recalledProducts = Array.isArray(identityRecall?.products) ? identityRecall.products : [];
  const recallMeta =
    identityRecall?.metadata &&
    typeof identityRecall.metadata === 'object' &&
    !Array.isArray(identityRecall.metadata)
      ? identityRecall.metadata
      : {};
  const upstreamMeta =
    upstreamData.metadata && typeof upstreamData.metadata === 'object' && !Array.isArray(upstreamData.metadata)
      ? upstreamData.metadata
      : {};
  if (!recalledProducts.length) {
    return {
      ...upstreamData,
      metadata: {
        ...upstreamMeta,
        identity_graph_search_recall: {
          attempted: Boolean(recallMeta.attempted),
          applied: false,
          reason: recallMeta.reason || 'no_identity_group_match',
        },
      },
    };
  }

  const seen = new Set();
  const mergedProducts = [];
  const add = (product) => {
    if (!product || typeof product !== 'object') return;
    const key =
      String(product.sellable_item_group_id || product.product_group_id || '').trim() ||
      buildSearchProductKey(product);
    if (!key || seen.has(key)) return;
    seen.add(key);
    mergedProducts.push(product);
  };
  const primaryIdentityProduct =
    recalledProducts.find((product) => product?.pdp_content_source === 'canonical_inherited') ||
    recalledProducts[0] ||
    null;
  const liveIdentityProduct = await findLiveIdentitySearchProductForRecall({
    queryText: normalizedQueryText,
    identityProducts: recalledProducts,
  });
  add(liveIdentityProduct);
  existingProducts
    .filter((product) => hasSearchProductIdentityMatch(product, normalizedQueryText))
    .map((product) => overlayIdentityRecallOnSearchProduct(product, primaryIdentityProduct))
    .forEach(add);
  recalledProducts.forEach(add);
  existingProducts.forEach(add);
  const limitedProducts = mergedProducts.slice(0, requestedLimit);
  return normalizeAgentProductsListResponse(
    {
      ...upstreamData,
      products: limitedProducts,
      results: limitedProducts,
      data: {
        ...(upstreamData.data && typeof upstreamData.data === 'object' && !Array.isArray(upstreamData.data)
          ? upstreamData.data
          : {}),
        products: limitedProducts,
      },
      total: Math.max(Number(upstreamData.total || 0) || 0, limitedProducts.length),
      count: Math.max(Number(upstreamData.count || 0) || 0, limitedProducts.length),
      metadata: {
        ...upstreamMeta,
        query_source: 'agent_products_identity_graph_recall',
        identity_graph_search_recall: {
          attempted: true,
          applied: true,
          reason: recallMeta.reason || 'identity_group_match',
          matched_group_count: Number(recallMeta.matched_group_count || recalledProducts.length) || recalledProducts.length,
          returned_count: recalledProducts.length,
        },
        source_breakdown: {
          ...(upstreamMeta.source_breakdown &&
          typeof upstreamMeta.source_breakdown === 'object' &&
          !Array.isArray(upstreamMeta.source_breakdown)
            ? upstreamMeta.source_breakdown
            : {}),
          identity_graph_count: recalledProducts.length,
          strategy_applied: 'pdp_identity_graph_search_recall',
        },
      },
    },
    {
      limit: queryParams?.limit,
      offset: queryParams?.offset,
    },
  );
}

function buildAuroraPrimaryIrrelevantSemanticRetryQueries(baseQueryText) {
  const base = String(baseQueryText || '').trim();
  if (!base) return [];
  const normalized = normalizeSearchTextForMatch(base);
  const peptideNormalizedBase = base
    .replace(/\b(tri|tetra|hexa)peptides?\b/gi, 'peptide')
    .replace(/\bpeptides\b/gi, 'peptide')
    .replace(/\bcopper peptide peptide\b/gi, 'copper peptide')
    .replace(/\bpeptide peptide\b/gi, 'peptide')
    .replace(/\s+/g, ' ')
    .trim();
  const candidates = [];
  const seen = new Set([normalizeSearchTextForMatch(base)]);
  const push = (queryValue) => {
    const value = String(queryValue || '').trim();
    const key = normalizeSearchTextForMatch(value);
    if (!value || !key || seen.has(key)) return;
    seen.add(key);
    candidates.push(value);
  };

  if (/\bcopper\b/.test(normalized) && /\b(peptide|tripeptide|tetrapeptide|hexapeptide)/.test(normalized)) {
    push(peptideNormalizedBase);
    push(`${peptideNormalizedBase} multi peptide`);
    push(`${base} multi peptide`);
    push(`${base} copper tripeptide`);
  }
  if (/\b(peptide|tripeptide|tetrapeptide|hexapeptide)/.test(normalized) && /\b(serum|essence)\b/.test(normalized)) {
    push(`${peptideNormalizedBase} multi-peptide collection`);
    push(`${base} multi-peptide collection`);
  }
  if (/\bniacinamide\b/.test(normalized) && /\b(serum|essence)\b/.test(normalized)) {
    push(`${base} vitamin b3`);
  }

  return candidates.slice(0, PROXY_SEARCH_AURORA_PRIMARY_IRRELEVANT_SEMANTIC_RETRY_MAX_QUERIES);
}

async function invokeFindProductsMultiFallbackOnce({
  url,
  searchUrl,
  payload,
  checkoutToken,
  requestSource,
  triggerReason,
  preserveAuroraSource,
  fallbackSource,
  relevanceQuery,
  attemptNo,
  useSearchEndpoint = false,
  timeoutMs = PROXY_SEARCH_FALLBACK_TIMEOUT_MS,
}) {
  const normalizedRequestSource = String(requestSource || '').trim().toLowerCase();
  const requestSourceValue = preserveAuroraSource
    ? normalizedRequestSource
    : fallbackSource || 'agent_search_proxy_fallback';
  const requestHeaders = {
    ...buildInvokeUpstreamAuthHeaders({ checkoutToken }),
  };
  const searchPayload = payload?.search && typeof payload.search === 'object' ? payload.search : {};
  const requestTimeoutMs = Math.max(
    250,
    Number(timeoutMs || PROXY_SEARCH_FALLBACK_TIMEOUT_MS) || PROXY_SEARCH_FALLBACK_TIMEOUT_MS,
  );

  const resp = useSearchEndpoint
    ? await axios({
        method: 'GET',
        url: searchUrl,
        params: {
          ...searchPayload,
          source: requestSourceValue,
        },
        headers: requestHeaders,
        timeout: requestTimeoutMs,
        validateStatus: () => true,
      })
    : await axios({
        method: 'POST',
        url,
        data: {
          operation: 'find_products_multi',
          payload,
          metadata: {
            source: requestSourceValue,
            ...(normalizedRequestSource ? { request_source: normalizedRequestSource } : {}),
            trigger_reason: triggerReason || 'unknown',
            proxy_fallback_source: 'agent_search_proxy_fallback',
            proxy_fallback_attempt: Number(attemptNo || 1),
          },
        },
        headers: {
          'Content-Type': 'application/json',
          ...requestHeaders,
        },
        timeout: requestTimeoutMs,
        validateStatus: () => true,
      });

  const normalized = normalizeAgentProductsListResponse(resp.data, {
    limit: parseQueryNumber(payload?.search?.limit ?? payload?.search?.page_size),
    offset: parseQueryNumber(payload?.search?.offset),
  });
  const usableCount = countUsableSearchProducts(normalized?.products);
  const relevanceMatched = relevanceQuery
    ? isProxySearchFallbackRelevant(normalized, relevanceQuery)
    : usableCount > 0;

  return {
    status: Number(resp.status || 0) || 0,
    usableCount,
    relevanceMatched,
    queryUsed: String(payload?.search?.query || ''),
    productsPreview: buildFallbackOverlapPreview(normalized?.products, relevanceQuery, 3),
    data: withProxySearchFallbackMetadata(normalized, {
      applied: true,
      reason: triggerReason || 'unknown',
      query_variant:
        normalizeSearchTextForMatch(String(payload?.search?.query || '')) ===
        normalizeSearchTextForMatch(String(relevanceQuery || ''))
          ? 'primary'
          : 'semantic_retry',
    }),
  };
}

async function queryFindProductsMultiFallback({
  queryParams,
  checkoutToken,
  reason,
  requestSource,
  timeoutMs = null,
}) {
  const payload = buildFindProductsMultiPayloadFromQuery(queryParams);
  if (!payload) return null;
  const fallbackSource = String(payload?.metadata?.source || '').trim();
  const normalizedRequestSource = String(requestSource || '').trim().toLowerCase();
  const searchApiBase = getProxySearchApiBase(normalizedRequestSource);
  const url = `${searchApiBase}/agent/shop/v1/invoke`;
  const searchUrl = `${searchApiBase}/agent/v1/products/search`;
  const preserveAuroraSource =
    PROXY_SEARCH_AURORA_PRESERVE_SOURCE_ON_INVOKE && isAuroraSource(normalizedRequestSource);
  const baseQueryText = String(payload?.search?.query || '').trim();
  const isAuroraMonocultureRetry =
    isAuroraSource(normalizedRequestSource) &&
    String(reason || '').trim() === 'primary_monoculture';
  const isAuroraSemanticRetry =
    PROXY_SEARCH_AURORA_PRIMARY_IRRELEVANT_SEMANTIC_RETRY_ENABLED &&
    isAuroraSource(normalizedRequestSource) &&
    (String(reason || '').trim() === 'primary_irrelevant' || isAuroraMonocultureRetry);
  const isFragranceSemanticRetry =
    SEARCH_FRAGRANCE_SEMANTIC_RETRY &&
    hasFragranceQuerySignal(baseQueryText);
  const semanticRetryEnabled = isAuroraSemanticRetry || isFragranceSemanticRetry;
  const normalizedBaseQuery = normalizeSearchTextForMatch(baseQueryText);
  const fragranceSemanticRetryQuery = isFragranceSemanticRetry
    ? buildFragranceSemanticRetryQuery(baseQueryText)
    : '';
  const fragranceSemanticRetryFallbackQuery = isFragranceSemanticRetry
    ? 'fragrance perfume parfum cologne eau de parfum eau de toilette body mist'
    : '';
  const auroraSemanticRetryQuery = isAuroraSemanticRetry
    ? buildAuroraPrimaryIrrelevantSemanticRetryQueries(baseQueryText)[0] || ''
    : '';
  const semanticRetryQueries = [];
  if (
    fragranceSemanticRetryQuery &&
    normalizeSearchTextForMatch(fragranceSemanticRetryQuery) !== normalizedBaseQuery
  ) {
    semanticRetryQueries.push(fragranceSemanticRetryQuery);
  } else if (
    fragranceSemanticRetryFallbackQuery &&
    normalizeSearchTextForMatch(fragranceSemanticRetryFallbackQuery) !== normalizedBaseQuery
  ) {
    semanticRetryQueries.push(fragranceSemanticRetryFallbackQuery);
  } else if (
    auroraSemanticRetryQuery &&
    normalizeSearchTextForMatch(auroraSemanticRetryQuery) !== normalizedBaseQuery
  ) {
    semanticRetryQueries.push(auroraSemanticRetryQuery);
  }
  const candidateQueries = Array.from(new Set([baseQueryText, ...semanticRetryQueries].filter(Boolean))).slice(0, 2);
  const configuredFallbackTimeoutMs = isAuroraSource(normalizedRequestSource)
    ? Math.min(PROXY_SEARCH_FALLBACK_TIMEOUT_MS, PROXY_SEARCH_AURORA_FALLBACK_TIMEOUT_MS)
    : PROXY_SEARCH_FALLBACK_TIMEOUT_MS;
  const requestedBudgetMs =
    Number.isFinite(Number(timeoutMs)) && Number(timeoutMs) > 0 ? Number(timeoutMs) : null;
  const totalFallbackBudgetMs =
    requestedBudgetMs == null ? configuredFallbackTimeoutMs : Math.max(100, requestedBudgetMs);
  const fallbackDeadlineMs = Date.now() + totalFallbackBudgetMs;

  let selectedAttempt = null;
  let selectedAttemptNo = 0;
  const attempts = [];
  const rankFallbackAttempt = (attempt) => {
    const statusOk = attempt && attempt.status >= 200 && attempt.status < 300;
    const usableCount = Math.max(0, Number(attempt?.usableCount || 0) || 0);
    const relevanceMatched = attempt?.relevanceMatched === true;
    return {
      statusOk,
      usableCount,
      relevanceMatched,
      total:
        (statusOk ? 100 : 0) +
        (usableCount * 12) +
        (relevanceMatched ? 8 : 0),
    };
  };
  for (let i = 0; i < candidateQueries.length; i += 1) {
    const remainingBudgetMs = Math.max(0, fallbackDeadlineMs - Date.now());
    if (remainingBudgetMs < 100) {
      break;
    }
    const attemptTimeoutMs = Math.max(100, Math.min(configuredFallbackTimeoutMs, remainingBudgetMs));
    const queryText = candidateQueries[i];
    const attemptPayload =
      i === 0
        ? payload
        : {
            ...payload,
            search: {
              ...(payload?.search && typeof payload.search === 'object' ? payload.search : {}),
              query: queryText,
            },
          };
    const useSearchEndpoint = semanticRetryEnabled && i > 0;
    const attempt = await invokeFindProductsMultiFallbackOnce({
      url,
      searchUrl,
      payload: attemptPayload,
      checkoutToken,
      requestSource: normalizedRequestSource,
      triggerReason: reason,
      preserveAuroraSource,
      fallbackSource,
      relevanceQuery: queryText,
      attemptNo: i + 1,
      useSearchEndpoint,
      timeoutMs: attemptTimeoutMs,
    });

    attempts.push({
      attempt: i + 1,
      query: attempt.queryUsed,
      status: attempt.status,
      usable_count: attempt.usableCount,
      relevance_matched: attempt.relevanceMatched,
      products_preview: attempt.productsPreview,
    });

    if (!selectedAttempt) {
      selectedAttempt = attempt;
      selectedAttemptNo = i + 1;
    } else {
      const selectedRank = rankFallbackAttempt(selectedAttempt);
      const candidateRank = rankFallbackAttempt(attempt);
      const shouldReplaceByRecall =
        candidateRank.statusOk &&
        candidateRank.usableCount >= Math.max(1, selectedRank.usableCount + 2);
      if (shouldReplaceByRecall || candidateRank.total > selectedRank.total) {
        selectedAttempt = attempt;
        selectedAttemptNo = i + 1;
      }
    }

    if (attempt.relevanceMatched && attempt.usableCount > 0) {
      const shouldForceNextSemanticAttempt =
        i === 0 &&
        candidateQueries.length > 1 &&
        (isAuroraMonocultureRetry || isFragranceSemanticRetry);
      if (!shouldForceNextSemanticAttempt) break;
    }
  }

  if (!selectedAttempt) return null;
  const attemptedSemanticRetry = attempts.some((attempt, index) => {
    if (!attempt || index === 0) return false;
    return (
      normalizeSearchTextForMatch(String(attempt.query || '')) !==
      normalizeSearchTextForMatch(String(baseQueryText || ''))
    );
  });
  const selectedAttemptIsSemanticRetry =
    normalizeSearchTextForMatch(String(selectedAttempt.queryUsed || '')) !==
    normalizeSearchTextForMatch(String(baseQueryText || ''));
  const semanticRetryApplied = attemptedSemanticRetry || selectedAttemptIsSemanticRetry;
  const semanticRetrySelectedQuery =
    semanticRetryApplied && selectedAttemptIsSemanticRetry
      ? String(selectedAttempt.queryUsed || '').trim()
      : semanticRetryApplied
      ? String(
          attempts.find(
            (attempt) =>
              normalizeSearchTextForMatch(String(attempt?.query || '')) !==
              normalizeSearchTextForMatch(String(baseQueryText || '')),
          )?.query || '',
        ).trim()
      : '';
  const semanticRetryHits = semanticRetryApplied
    ? Math.max(
        0,
        ...attempts
          .filter(
            (attempt) =>
              normalizeSearchTextForMatch(String(attempt?.query || '')) !==
              normalizeSearchTextForMatch(String(baseQueryText || '')),
          )
          .map((attempt) => Math.max(0, Number(attempt?.usable_count || 0) || 0)),
      )
    : 0;
  return {
    status: selectedAttempt.status,
    usableCount: selectedAttempt.usableCount,
    relevanceMatched: selectedAttempt.relevanceMatched,
    selectedQuery: selectedAttempt.queryUsed,
    selectedAttemptNo,
    semanticRetryApplied,
    semanticRetryQuery: semanticRetryApplied ? semanticRetrySelectedQuery || null : null,
    semanticRetryHits,
    actualRetryAttempted: attemptedSemanticRetry,
    attempts,
    data: selectedAttempt.data,
  };
}

function buildResolverReferenceOnlyResult({
  queryText,
  resolved,
  resolvedQueryUsed,
  resolvedMerchantId,
  resolvedProductId,
  resolveSources,
  reason,
}) {
  const candidateTitle = Array.isArray(resolved?.candidates)
    ? String(resolved.candidates?.[0]?.title || '').trim()
    : '';
  const resolvedTitle = String(
    candidateTitle ||
      resolved?.title ||
      resolved?.alias ||
      resolvedQueryUsed ||
      queryText,
  ).trim();
  const productRow = {
    id: resolvedProductId,
    product_id: resolvedProductId,
    merchant_id: resolvedMerchantId,
    platform_product_id: resolvedProductId,
    ...(resolvedTitle ? { title: resolvedTitle, name: resolvedTitle } : {}),
    canonical_product_ref: {
      merchant_id: resolvedMerchantId,
      product_id: resolvedProductId,
    },
  };

  const normalized = normalizeAgentProductsListResponse({
    status: 'success',
    success: true,
    products: [productRow],
    total: 1,
    page: 1,
    page_size: 1,
    metadata: {
      query_source: 'agent_products_resolver_ref_fallback',
      resolve_reason: resolved?.reason || null,
      resolve_reason_code:
        resolved?.reason_code ||
        resolved?.metadata?.resolve_reason_code ||
        'detail_unavailable_ref_only',
      resolve_confidence:
        Number.isFinite(Number(resolved?.confidence)) ? Number(resolved.confidence) : null,
      resolve_latency_ms:
        Number.isFinite(Number(resolved?.metadata?.latency_ms)) ? Number(resolved.metadata.latency_ms) : null,
      resolve_query_used: resolvedQueryUsed || queryText,
      resolve_detail_source: 'reference_only',
    },
  });

  return {
    status: 200,
    usableCount: countUsableSearchProducts(normalized?.products),
    resolved: true,
    resolve_reason: resolved?.reason || null,
    resolve_reason_code:
      resolved?.reason_code ||
      resolved?.metadata?.resolve_reason_code ||
      'detail_unavailable_ref_only',
    resolve_confidence:
      Number.isFinite(Number(resolved?.confidence)) ? Number(resolved.confidence) : null,
    resolve_latency_ms:
      Number.isFinite(Number(resolved?.metadata?.latency_ms)) ? Number(resolved.metadata.latency_ms) : null,
    resolve_sources: resolveSources,
    resolve_query_used: resolvedQueryUsed || queryText,
    data: withProxySearchFallbackMetadata(normalized, {
      applied: true,
      reason: reason || 'resolver_ref_only',
    }),
  };
}

async function queryResolveSearchFallback({
  queryParams,
  checkoutToken,
  reason,
  requestSource,
  fetchDetail = true,
  timeoutMs,
}) {
  const query = queryParams && typeof queryParams === 'object' ? queryParams : {};
  const queryText = extractSearchQueryText(query);
  if (!queryText) return null;

  const lang = String(firstQueryParamValue(query.lang) || 'en').trim().toLowerCase() || 'en';
  const merchantId = String(firstQueryParamValue(query.merchant_id || query.merchantId) || '').trim();
  const merchantIds = parseQueryStringArray(query.merchant_ids || query.merchantIds);
  const preferMerchants = uniqueStrings([
    merchantId,
    ...merchantIds,
  ]);
  const searchAllMerchants = parseQueryBoolean(query.search_all_merchants || query.searchAllMerchants);
  const effectiveResolverTimeoutMs = Math.max(
    200,
    Number(timeoutMs || PROXY_SEARCH_RESOLVER_TIMEOUT_MS) || PROXY_SEARCH_RESOLVER_TIMEOUT_MS,
  );
  const resolveOptions = {
    ...(preferMerchants.length ? { prefer_merchants: preferMerchants } : {}),
    ...(searchAllMerchants !== undefined ? { search_all_merchants: searchAllMerchants } : {}),
    timeout_ms: effectiveResolverTimeoutMs,
    upstream_retries: 0,
    stable_alias_short_circuit: true,
  };
  const resolverCacheKey = buildProxySearchResolverCacheKey({
    queryText,
    lang,
    preferMerchants,
    searchAllMerchants,
    fetchDetail,
    resolverTimeoutMs: effectiveResolverTimeoutMs,
  });
  const cached = getProxySearchResolverCacheEntry(resolverCacheKey);
  if (cached) return cached;

  const toResolveSources = (input) =>
    Array.isArray(input?.metadata?.sources)
      ? input.metadata.sources
          .filter((item) => item && typeof item === 'object')
          .map((item) => ({
            source: String(item.source || '').trim() || null,
            ok: item.ok === true,
            count: Number.isFinite(Number(item.count)) ? Number(item.count) : null,
            reason: String(item.reason || '').trim() || null,
            error_code: String(item.error_code || '').trim() || null,
          }))
      : [];

  const resolverQueryCandidates = buildResolverQueryCandidates(queryText);
  let resolved = null;
  let resolvedQueryUsed = queryText;
  for (const candidateQuery of resolverQueryCandidates) {
    const candidateText = String(candidateQuery || '').trim();
    if (!candidateText) continue;

    let stableAliasMatch = null;
    if (resolveStableAliasByQuery) {
      try {
        const normalizedCandidate = normalizeResolverText(candidateText);
        const candidateTokens = tokenizeResolverQuery(normalizedCandidate);
        if (normalizedCandidate && candidateTokens.length > 0) {
          stableAliasMatch = resolveStableAliasByQuery({
            query: candidateText,
            normalizedQuery: normalizedCandidate,
            queryTokens: candidateTokens,
          });
        }
      } catch {
        stableAliasMatch = null;
      }
    }

    if (
      stableAliasMatch &&
      stableAliasMatch.product_ref &&
      String(stableAliasMatch.product_ref.product_id || '').trim() &&
      String(stableAliasMatch.product_ref.merchant_id || '').trim()
    ) {
      resolved = {
        resolved: true,
        reason: 'stable_alias_match',
        reason_code: 'stable_alias_match',
        confidence: Number.isFinite(Number(stableAliasMatch.score))
          ? Number(stableAliasMatch.score)
          : 1,
        product_ref: {
          product_id: String(stableAliasMatch.product_ref.product_id || '').trim(),
          merchant_id: String(stableAliasMatch.product_ref.merchant_id || '').trim(),
        },
        candidates: [
          {
            title: String(stableAliasMatch.title || stableAliasMatch.alias || candidateText || '').trim() || null,
            product_ref: {
              product_id: String(stableAliasMatch.product_ref.product_id || '').trim(),
              merchant_id: String(stableAliasMatch.product_ref.merchant_id || '').trim(),
            },
            score: Number.isFinite(Number(stableAliasMatch.score))
              ? Number(stableAliasMatch.score)
              : 1,
          },
        ],
        metadata: {
          latency_ms: 0,
          sources: [
            {
              source: 'stable_alias_ref',
              ok: true,
              reason: stableAliasMatch.reason || 'stable_alias_match',
              count: 1,
            },
          ],
          stable_alias_short_circuit: true,
        },
      };
      resolvedQueryUsed = candidateText;
      break;
    }

    try {
      const candidateResolved = await resolveProductRef({
        query: candidateText,
        lang,
        hints: null,
        options: resolveOptions,
        pivotaApiBase: getProxySearchApiBase(requestSource),
        pivotaApiKey: PIVOTA_API_KEY,
        checkoutToken,
      });
      if (!resolved) {
        resolved = candidateResolved;
        resolvedQueryUsed = candidateText;
      }
      if (
        candidateResolved &&
        candidateResolved.resolved &&
        candidateResolved.product_ref &&
        String(candidateResolved.product_ref.product_id || '').trim() &&
        String(candidateResolved.product_ref.merchant_id || '').trim()
      ) {
        resolved = candidateResolved;
        resolvedQueryUsed = candidateText;
        break;
      }
    } catch (err) {
      logger.warn(
        { err: err?.message || String(err), query: candidateText },
        'proxy agent search resolver fallback failed',
      );
      continue;
    }
  }

  const resolvedRef = resolved && resolved.resolved ? resolved.product_ref : null;
  const resolvedProductId = String(resolvedRef?.product_id || '').trim();
  const resolvedMerchantId = String(resolvedRef?.merchant_id || '').trim();
  const resolveSources = toResolveSources(resolved);
  if (!resolvedProductId || !resolvedMerchantId) {
    const missResult = {
      status: 200,
      usableCount: 0,
      data: null,
      resolved: false,
      resolve_reason: resolved?.reason || null,
      resolve_reason_code:
        resolved?.reason_code ||
        resolved?.metadata?.resolve_reason_code ||
        null,
      resolve_confidence:
        Number.isFinite(Number(resolved?.confidence)) ? Number(resolved.confidence) : null,
      resolve_latency_ms:
        Number.isFinite(Number(resolved?.metadata?.latency_ms)) ? Number(resolved.metadata.latency_ms) : null,
      resolve_sources: resolveSources,
      resolve_query_used: resolvedQueryUsed || queryText,
    };
    setProxySearchResolverCacheEntry(
      resolverCacheKey,
      missResult,
      PROXY_SEARCH_RESOLVER_MISS_CACHE_TTL_MS,
    );
    return missResult;
  }

  let detail = null;
  let detailSource = null;
  if (fetchDetail && PROXY_SEARCH_RESOLVER_DETAIL_ENABLED) {
    try {
      const detailFromCache = await fetchProductDetailFromProductsCache({
        merchantId: resolvedMerchantId,
        productId: resolvedProductId,
        includeExpired: true,
        staleMaxAgeHours: PRODUCT_DETAIL_STALE_MAX_AGE_HOURS,
      });
      if (detailFromCache?.product) {
        detail = detailFromCache.product;
        detailSource = detailFromCache?.stale_fallback_used
          ? 'products_cache_stale'
          : 'products_cache';
      }
      if (!detail) {
        detail = await fetchProductDetailFromUpstream({
          merchantId: resolvedMerchantId,
          productId: resolvedProductId,
          checkoutToken,
          timeoutMs: PROXY_SEARCH_RESOLVER_DETAIL_TIMEOUT_MS,
          noRetry: true,
        });
        if (detail) detailSource = 'upstream';
      }
    } catch (err) {
      logger.warn(
        {
          err: err?.message || String(err),
          merchant_id: resolvedMerchantId,
          product_id: resolvedProductId,
        },
        'proxy agent search resolver fallback detail fetch failed',
      );
    }
  }

  if (fetchDetail && PROXY_SEARCH_RESOLVER_DETAIL_ENABLED && !detail) {
    if (isLookupStyleSearchQuery(queryText, extractSearchAnchorTokens(queryText))) {
      const refOnlyResult = buildResolverReferenceOnlyResult({
        queryText,
        resolved,
        resolvedQueryUsed,
        resolvedMerchantId,
        resolvedProductId,
        resolveSources,
        reason,
      });
      setProxySearchResolverCacheEntry(
        resolverCacheKey,
        refOnlyResult,
        PROXY_SEARCH_RESOLVER_MISS_CACHE_TTL_MS,
      );
      logger.info(
        {
          query: queryText,
          query_used: resolvedQueryUsed || queryText,
          merchant_id: resolvedMerchantId,
          product_id: resolvedProductId,
        },
        'proxy agent search resolver fallback returned reference-only candidate (detail unavailable)',
      );
      return refOnlyResult;
    }

    const missResult = {
      status: 200,
      usableCount: 0,
      data: null,
      resolved: false,
      resolve_reason: resolved?.reason || null,
      resolve_reason_code: 'detail_unavailable',
      resolve_confidence:
        Number.isFinite(Number(resolved?.confidence)) ? Number(resolved.confidence) : null,
      resolve_latency_ms:
        Number.isFinite(Number(resolved?.metadata?.latency_ms)) ? Number(resolved.metadata.latency_ms) : null,
      resolve_sources: resolveSources,
      resolve_query_used: resolvedQueryUsed || queryText,
    };
    setProxySearchResolverCacheEntry(
      resolverCacheKey,
      missResult,
      PROXY_SEARCH_RESOLVER_MISS_CACHE_TTL_MS,
    );
    logger.info(
      {
        query: queryText,
        query_used: resolvedQueryUsed || queryText,
        merchant_id: resolvedMerchantId,
        product_id: resolvedProductId,
      },
      'proxy agent search resolver fallback skipped unresolved detail candidate',
    );
    return missResult;
  }

  const candidateTitle = Array.isArray(resolved?.candidates)
    ? String(resolved.candidates?.[0]?.title || '').trim()
    : '';
  const title = String(
    detail?.title ||
      detail?.name ||
      detail?.display_name ||
      candidateTitle ||
      queryText,
  ).trim();

  const productRow = {
    ...(detail && typeof detail === 'object' ? detail : {}),
    id: String(detail?.id || detail?.product_id || resolvedProductId),
    product_id: String(detail?.product_id || detail?.id || resolvedProductId),
    merchant_id: String(detail?.merchant_id || resolvedMerchantId),
    platform_product_id: String(
      detail?.platform_product_id ||
        detail?.platformProductId ||
        detail?.product_id ||
        resolvedProductId,
    ),
    ...(title ? { title } : {}),
    ...(title && !detail?.name ? { name: title } : {}),
    canonical_product_ref: {
      merchant_id: resolvedMerchantId,
      product_id: resolvedProductId,
    },
  };

  const normalized = normalizeAgentProductsListResponse({
    status: 'success',
    success: true,
    products: [productRow],
    total: 1,
    page: 1,
    page_size: 1,
    metadata: {
      query_source: 'agent_products_resolver_fallback',
      resolve_reason: resolved?.reason || null,
      resolve_reason_code:
        resolved?.reason_code ||
        resolved?.metadata?.resolve_reason_code ||
        null,
      resolve_confidence:
        Number.isFinite(Number(resolved?.confidence)) ? Number(resolved.confidence) : null,
      resolve_latency_ms:
        Number.isFinite(Number(resolved?.metadata?.latency_ms)) ? Number(resolved.metadata.latency_ms) : null,
      resolve_query_used: resolvedQueryUsed || queryText,
      ...(detailSource ? { resolve_detail_source: detailSource } : {}),
    },
  });

  const successResult = {
    status: 200,
    usableCount: countUsableSearchProducts(normalized?.products),
    resolved: true,
    resolve_reason: resolved?.reason || null,
    resolve_reason_code:
      resolved?.reason_code ||
      resolved?.metadata?.resolve_reason_code ||
      null,
    resolve_confidence:
      Number.isFinite(Number(resolved?.confidence)) ? Number(resolved.confidence) : null,
    resolve_latency_ms:
      Number.isFinite(Number(resolved?.metadata?.latency_ms)) ? Number(resolved.metadata.latency_ms) : null,
    resolve_sources: resolveSources,
    resolve_query_used: resolvedQueryUsed || queryText,
    data: withProxySearchFallbackMetadata(normalized, {
      applied: true,
      reason: reason || 'resolver_fallback',
    }),
  };
  setProxySearchResolverCacheEntry(resolverCacheKey, successResult, PROXY_SEARCH_RESOLVER_CACHE_TTL_MS);
  return successResult;
}

function isResolverMiss(result) {
  if (!result || typeof result !== 'object') return false;
  return Number(result.usableCount || 0) <= 0;
}

function shouldReducePrimaryTimeoutAfterResolverMiss(result, queryText = '') {
  if (!isResolverMiss(result)) return false;
  if (hasPetSearchSignal(queryText)) return false;
  const reasonCode = normalizeOffersResolveReasonCode(
    result?.resolve_reason_code || result?.resolve_reason || '',
    '',
  );
  return reasonCode === 'no_candidates' || reasonCode === 'upstream_timeout' || reasonCode === 'db_timeout';
}

function shouldSkipSecondaryFallbackAfterResolverMiss(
  result,
  queryText = '',
  { disableSkipAfterResolverMiss = false, queryClass = null, brandLike = false } = {},
) {
  return Boolean(
    getSecondaryFallbackSkipReason(result, queryText, {
      disableSkipAfterResolverMiss,
      queryClass,
      brandLike,
    }),
  );
}

function getSecondaryFallbackSkipReason(
  result,
  queryText = '',
  { disableSkipAfterResolverMiss = false, queryClass = null, brandLike = false } = {},
) {
  if (disableSkipAfterResolverMiss) return null;
  if (!PROXY_SEARCH_SKIP_SECONDARY_FALLBACK_AFTER_RESOLVER_MISS) return null;
  if (hasPetSearchSignal(queryText)) return null;
  if (hasFragranceQuerySignal(queryText)) return null;
  if (!shouldReducePrimaryTimeoutAfterResolverMiss(result, queryText)) return null;
  if (brandLike) return null;

  const normalizedQueryClass = String(queryClass || '')
    .trim()
    .toLowerCase();
  const lookupOnlyClasses = new Set(['lookup', 'attribute']);
  const forceSearchFirstClasses = new Set([
    'category',
    'exploratory',
    'scenario',
    'mission',
    'gift',
    'non_shopping',
  ]);
  if (normalizedQueryClass && forceSearchFirstClasses.has(normalizedQueryClass)) {
    return null;
  }

  const anchorTokens = extractSearchAnchorTokens(queryText);
  const lookupStyle = isLookupStyleSearchQuery(queryText, anchorTokens);
  if (
    FPM_GATE_SIMPLIFY_V1 &&
    FPM_LOOKUP_ONLY_RESOLVER &&
    ((!normalizedQueryClass && !lookupStyle) ||
      (normalizedQueryClass && !lookupOnlyClasses.has(normalizedQueryClass)))
  ) {
    return null;
  }
  if (isKnownLookupAliasQuery(queryText)) return 'resolver_miss_lookup_alias';
  if (isUuidLikeSearchQuery(queryText)) return 'resolver_miss_uuid_like';
  if (isStrongResolverFirstQuery(queryText)) return 'resolver_miss_strong_resolver_query';
  if (lookupStyle) return 'resolver_miss_lookup_style';
  return null;
}

function shouldAllowSecondaryFallback(operation, { forceSecondaryFallback = false } = {}) {
  if (forceSecondaryFallback) return true;
  if (operation === 'find_products_multi') {
    return PROXY_SEARCH_SECONDARY_FALLBACK_MULTI_ENABLED;
  }
  return true;
}

function hasStrictInvokeCatalogSurface(search = null, metadata = null) {
  const normalizedSearch =
    search && typeof search === 'object' && !Array.isArray(search) ? search : {};
  const normalizedMetadata =
    metadata && typeof metadata === 'object' && !Array.isArray(metadata) ? metadata : {};
  const catalogSurface = firstNonEmptyString(
    normalizedSearch.catalog_surface,
    normalizedSearch.catalogSurface,
    normalizedMetadata.catalog_surface,
    normalizedMetadata.catalogSurface,
  );
  const normalizedCatalogSurface = String(catalogSurface || '').trim().toLowerCase();
  return ['agent_api', 'acp', 'ucp'].includes(normalizedCatalogSurface);
}

function attachInvokeSearchRequestContractMetadata({
  operation = '',
  payload = null,
  metadata = null,
  queryClass = null,
} = {}) {
  const nextMetadata =
    metadata && typeof metadata === 'object' && !Array.isArray(metadata)
      ? { ...metadata }
      : {};
  if (!(operation === 'find_products' || operation === 'find_products_multi')) return nextMetadata;
  const search =
    payload?.search && typeof payload.search === 'object' && !Array.isArray(payload.search)
      ? payload.search
      : payload && typeof payload === 'object' && !Array.isArray(payload)
        ? payload
        : {};
  const searchRequestContract =
    getSearchRequestContractFromMetadata(nextMetadata) ||
    buildFindProductsSearchRequestContract({
      surface: 'gateway',
      operation,
      search,
      metadata: nextMetadata,
      queryClass,
      strictConstraintQuery: hasStrictInvokeCatalogSurface(search, nextMetadata),
    });
  if (!searchRequestContract) return nextMetadata;
  return {
    ...nextMetadata,
    search_request_contract: searchRequestContract,
    primary_lane:
      String(searchRequestContract.primary_lane || '').trim() ||
      String(nextMetadata.primary_lane || '').trim() ||
      null,
    primary_retrieval_contract:
      String(searchRequestContract.primary_retrieval_contract || '').trim() ||
      String(nextMetadata.primary_retrieval_contract || '').trim() ||
      null,
    supplement_lanes: Array.isArray(searchRequestContract.supplement_lanes)
      ? searchRequestContract.supplement_lanes
      : [],
  };
}

function shouldUseCreatorBeautyMainlineInternalPrimitive({
  operation = '',
  search = null,
  metadata = null,
  rawUserQuery = '',
} = {}) {
  if (String(operation || '').trim().toLowerCase() !== 'find_products_multi') return false;
  if (!isCreatorInvokeSource(metadata?.source)) return false;
  if (hasExplicitLegacyInvokeContracts(metadata)) return false;
  if (resolveSearchPrimaryLaneFromMetadata(metadata).toLowerCase() !== 'beauty_discovery_mainline') {
    return false;
  }
  const searchObj =
    search && typeof search === 'object' && !Array.isArray(search) ? search : {};
  const queryText = firstNonEmptyString(rawUserQuery, searchObj.query, searchObj.q);
  if (!looksLikeBroadBeautyDiscoveryQuery(queryText)) return false;
  if (String(searchObj.merchant_id || searchObj.merchantId || '').trim()) return false;
  const merchantIdsRaw = searchObj.merchant_ids || searchObj.merchantIds;
  const merchantIds = Array.isArray(merchantIdsRaw)
    ? merchantIdsRaw.map((value) => String(value || '').trim()).filter(Boolean)
    : [];
  if (merchantIds.length > 0) return false;
  if (
    String(searchObj.category || '').trim() ||
    searchObj.price_min != null ||
    searchObj.min_price != null ||
    searchObj.price_max != null ||
    searchObj.max_price != null
  ) {
    return false;
  }
  return true;
}

function buildBeautyMainlineInternalPrimitiveSearchBody({
  search = null,
  queryParams = null,
  metadata = null,
  gatewayRequestId = null,
  defaultSearchAllMerchants = true,
} = {}) {
  const searchObj =
    search && typeof search === 'object' && !Array.isArray(search) ? search : {};
  const queryObj =
    queryParams && typeof queryParams === 'object' && !Array.isArray(queryParams)
      ? queryParams
      : {};
  const searchRequestContract = getSearchRequestContractFromMetadata(metadata);
  const semanticContract =
    searchRequestContract?.semantic_contract &&
    typeof searchRequestContract.semantic_contract === 'object' &&
    !Array.isArray(searchRequestContract.semantic_contract)
      ? searchRequestContract.semantic_contract
      : {};
  const validation = sanitizeInternalProductsSearchRequest(
    {
      query: firstNonEmptyString(queryObj.query, searchObj.query, searchObj.q),
      limit: queryObj.limit ?? searchObj.limit ?? searchObj.page_size,
      offset: queryObj.offset,
      merchant_id: firstNonEmptyString(
        queryObj.merchant_id,
        searchObj.merchant_id,
        searchObj.merchantId,
      ),
      merchant_ids:
        queryObj.merchant_ids ?? searchObj.merchant_ids ?? searchObj.merchantIds,
      search_all_merchants:
        queryObj.search_all_merchants ??
        searchObj.search_all_merchants ??
        searchObj.searchAllMerchants,
      catalog_surface: firstNonEmptyString(
        searchObj.catalog_surface,
        searchObj.catalogSurface,
        metadata?.catalog_surface,
        metadata?.catalogSurface,
        'beauty',
      ),
      in_stock_only:
        queryObj.in_stock_only ??
        searchObj.in_stock_only ??
        searchObj.inStockOnly,
      allow_external_seed:
        queryObj.allow_external_seed ??
        searchObj.allow_external_seed ??
        searchObj.allowExternalSeed,
      external_seed_strategy: firstNonEmptyString(
        queryObj.external_seed_strategy,
        searchObj.external_seed_strategy,
        searchObj.externalSeedStrategy,
      ),
      fast_mode:
        queryObj.fast_mode ??
        searchObj.fast_mode ??
        searchObj.fastMode,
      target_step_family: firstNonEmptyString(
        searchObj.target_step_family,
        searchObj.targetStepFamily,
        searchRequestContract?.target_step_family,
        semanticContract?.target_step_family,
      ),
      semantic_family: firstNonEmptyString(
        searchObj.semantic_family,
        searchObj.semanticFamily,
        searchRequestContract?.semantic_family,
        semanticContract?.semantic_family,
      ),
      query_step_strength: firstNonEmptyString(
        searchObj.query_step_strength,
        searchObj.queryStepStrength,
        metadata?.query_step_strength,
        semanticContract?.query_step_strength,
      ),
      product_only:
        searchObj.product_only ??
        searchObj.productOnly,
      trace_id: gatewayRequestId,
    },
    {
      rejectUnknown: false,
      rejectForbidden: false,
      defaultSearchAllMerchants,
    },
  );
  return validation.ok ? validation.search : null;
}

function looksLikeBroadBeautyDiscoveryQuery(queryText = '') {
  const normalized = String(queryText || '').trim().toLowerCase();
  if (!normalized) return false;
  const hasBroadAskSignal =
    /\b(what products should i use|what should i use|routine|routine for|products for|need products|need a routine|i am|i'm|im|my skin|i have)\b/.test(
      normalized,
    ) || /\b(oily skin|dry skin|acne-prone|sensitive skin|combination skin)\b/.test(normalized);
  if (!hasBroadAskSignal) return false;
  const hasExplicitSingleStepSignal =
    /\b(cleanser|face wash|serum|treatment|moisturi[sz]er|cream|lotion|gel cream|sunscreen|spf|toner|mask)\b/.test(
      normalized,
    );
  return !hasExplicitSingleStepSignal;
}

function isFallbackSuppressedSearchRail(searchRail = null) {
  const normalizedSearchRail = String(searchRail || '').trim().toLowerCase();
  return (
    normalizedSearchRail === 'authoritative_shopping' ||
    normalizedSearchRail === 'public_observability'
  );
}

function isLegacyBeautyMainlineInvokeMetadata(metadata = null) {
  if (!metadata || typeof metadata !== 'object' || Array.isArray(metadata)) return false;
  if (hasExplicitLegacyInvokeContracts(metadata)) return false;
  if (!(isAuroraSource(metadata.source) || isCreatorInvokeSource(metadata.source))) return false;
  return resolveSearchPrimaryLaneFromMetadata(metadata).toLowerCase() === 'beauty_discovery_mainline';
}

function shouldSuppressLegacyOwnerSwitchFallback({ searchRail = null, metadata = null } = {}) {
  return (
    isFallbackSuppressedSearchRail(searchRail) ||
    isLegacyBeautyMainlineInvokeMetadata(metadata)
  );
}

function shouldAllowInvokeFallback(operation, { forceInvokeFallback = false, metadata = null } = {}) {
  if (forceInvokeFallback) return true;
  if (!(operation === 'find_products' || operation === 'find_products_multi')) return false;
  const searchRail = String(
    metadata?.invoke_search_rail || resolveInvokeSearchRailFromMetadata(metadata),
  )
    .trim()
    .toLowerCase();
  if (shouldSuppressLegacyOwnerSwitchFallback({ searchRail, metadata })) {
    return false;
  }
  return PROXY_SEARCH_INVOKE_FALLBACK_ENABLED;
}

function shouldAllowResolverFallback(operation, { metadata = null } = {}) {
  if (!(operation === 'find_products' || operation === 'find_products_multi')) return false;
  const searchRail = String(
    metadata?.invoke_search_rail || resolveInvokeSearchRailFromMetadata(metadata),
  )
    .trim()
    .toLowerCase();
  if (shouldSuppressLegacyOwnerSwitchFallback({ searchRail, metadata })) {
    return false;
  }
  return PROXY_SEARCH_RESOLVER_FALLBACK_ENABLED;
}

function shouldBypassSecondaryFallbackSkipOnPrimaryException({ err }) {
  const status = Number(err?.response?.status || err?.status || 0);
  if (Number.isFinite(status) && status >= 500) return true;

  const code = String(err?.code || '').trim().toUpperCase();
  if (code === 'ECONNABORTED' || code === 'ETIMEDOUT' || code === 'ECONNRESET' || code === 'EAI_AGAIN') {
    return true;
  }

  const message = String(err?.message || '').trim();
  return /timeout|timed out|socket hang up|aborted|network error/i.test(message);
}

function isUuidLikeSearchQuery(value) {
  const s = String(value || '').trim();
  if (!s) return false;
  return (
    /^[0-9a-f]{8}(?:-[0-9a-f]{4}){3}-[0-9a-f]{12}$/i.test(s) ||
    /^[0-9a-f]{32}$/i.test(s)
  );
}

function isStrongResolverFirstQuery(queryText) {
  const raw = String(queryText || '').trim();
  if (!raw) return false;
  if (isKnownLookupAliasQuery(raw)) return true;
  if (isUuidLikeSearchQuery(raw)) return true;
  if (!resolveStableAliasByQuery) return false;

  const queryCandidates = buildResolverQueryCandidates(raw);
  for (const candidate of queryCandidates) {
    try {
      const normalized = normalizeResolverText(candidate);
      const tokens = tokenizeResolverQuery(normalized);
      if (!normalized || !tokens.length) continue;
      const match = resolveStableAliasByQuery({
        query: candidate,
        normalizedQuery: normalized,
        queryTokens: tokens,
      });
      if (
        match &&
        match.product_ref &&
        String(match.product_ref.product_id || '').trim() &&
        String(match.product_ref.merchant_id || '').trim()
      ) {
        return true;
      }
    } catch {
      continue;
    }
  }
  return false;
}

function shouldUseResolverFirstSearch({
  operation,
  metadata,
  queryText,
  remainingBudgetMs = null,
  queryClass = null,
  brandLike = false,
}) {
  if (!PROXY_SEARCH_RESOLVER_FIRST_ENABLED) return false;
  if (!(operation === 'find_products' || operation === 'find_products_multi')) return false;
  if (!String(queryText || '').trim()) return false;
  if (brandLike) return false;
  if (
    Number.isFinite(Number(remainingBudgetMs)) &&
    Number(remainingBudgetMs) < FPM_LATENCY_GUARD_RESOLVER_MIN_REMAINING_MS
  ) {
    return false;
  }
  const searchRail = String(
    metadata?.invoke_search_rail || resolveInvokeSearchRailFromMetadata(metadata),
  )
    .trim()
    .toLowerCase();
  if (shouldSuppressLegacyOwnerSwitchFallback({ searchRail, metadata })) {
    return false;
  }

  const strongResolverQuery = isStrongResolverFirstQuery(queryText);
  const normalizedQueryClass = String(queryClass || '').trim().toLowerCase();
  const forceSearchFirstClasses = new Set([
    'category',
    'exploratory',
    'scenario',
    'mission',
    'gift',
    'non_shopping',
  ]);
  if (
    FPM_GATE_SIMPLIFY_V1 &&
    normalizedQueryClass &&
    forceSearchFirstClasses.has(normalizedQueryClass) &&
    !strongResolverQuery
  ) {
    return false;
  }

  const anchorTokens = extractSearchAnchorTokens(queryText);
  const lookupStyle = isLookupStyleSearchQuery(queryText, anchorTokens);
  const lookupOnlyClasses = new Set(['lookup', 'attribute']);
  if (
    FPM_GATE_SIMPLIFY_V1 &&
    FPM_LOOKUP_ONLY_RESOLVER &&
    !strongResolverQuery &&
    ((!normalizedQueryClass && !lookupStyle) ||
      (normalizedQueryClass && !lookupOnlyClasses.has(normalizedQueryClass)))
  ) {
    return false;
  }

  const source = normalizeAgentSource(metadata?.source);
  if (isCreatorUiSource(source)) return false;
  const auroraSource = isAuroraSource(source);
  if (auroraSource && PROXY_SEARCH_RESOLVER_FIRST_DISABLE_AURORA) return false;
  if (!source) return true;
  const isCatalogSource = isResolverFirstCatalogSource(source);
  if (PROXY_SEARCH_RESOLVER_FIRST_STRONG_ONLY && (isCatalogSource || auroraSource)) {
    return (
      strongResolverQuery ||
      lookupStyle
    );
  }

  return isCatalogSource || auroraSource;
}

function normalizeAgentProductDetailResponse(raw) {
  if (!raw) return raw;
  if (raw && typeof raw === 'object' && !Array.isArray(raw)) {
    if (raw.product) return raw;
    if (raw.data && typeof raw.data === 'object' && raw.data.product) {
      return { ...raw, product: raw.data.product };
    }
    const looksLikeProduct =
      (raw.id || raw.product_id || raw.productId || raw.title || raw.name) &&
      typeof raw !== 'string';
    if (looksLikeProduct) {
      return { status: 'success', success: true, product: raw };
    }
    if (raw.data && typeof raw.data === 'object') {
      const d = raw.data;
      const dLooksLikeProduct = d && (d.id || d.product_id || d.productId || d.title || d.name);
      if (dLooksLikeProduct) {
        return { ...raw, product: d };
      }
    }
  }
  return raw;
}

