function normalizeOptionsRecord(raw) {
  const out = {};
  if (!raw) return out;

  const normKey = (v) => String(v || '').trim().toLowerCase();
  const normVal = (v) => String(v || '').trim().toLowerCase();

  if (Array.isArray(raw)) {
    for (const it of raw) {
      if (!it || typeof it !== 'object') continue;
      const key = normKey(it.name || it.option || it.key);
      const val = normVal(it.value);
      if (!key || !val) continue;
      out[key] = val;
    }
    return out;
  }

  if (raw && typeof raw === 'object') {
    for (const [k, v] of Object.entries(raw)) {
      const key = normKey(k);
      const val = normVal(v);
      if (!key || !val) continue;
      out[key] = val;
    }
    return out;
  }

  return out;
}

function optionsRecordEquals(a, b) {
  const aKeys = Object.keys(a || {});
  const bKeys = Object.keys(b || {});
  if (aKeys.length !== bKeys.length) return false;
  for (const k of aKeys) {
    if (!Object.prototype.hasOwnProperty.call(b, k)) return false;
    if (String(a[k]) !== String(b[k])) return false;
  }
  return true;
}

function extractVariantId(v) {
  const raw = v?.variant_id || v?.variantId || v?.id || null;
  return raw == null ? '' : String(raw).trim();
}

function extractVariantSku(v) {
  const raw = v?.sku || v?.sku_id || v?.skuId || v?.sku_code || null;
  return raw == null ? '' : String(raw).trim().toUpperCase();
}

function extractVariantOptions(v) {
  const raw = v?.options || v?.selected_options || v?.selectedOptions || null;
  return normalizeOptionsRecord(raw);
}

function findVariantIdInProduct(product, selector) {
  const variants = Array.isArray(product?.variants) ? product.variants : [];
  if (!variants.length) return null;

  const desiredSku = selector?.sku ? String(selector.sku).trim() : '';
  const desiredOptions = selector?.options && typeof selector.options === 'object' ? selector.options : null;

  if (desiredSku) {
    const hit = variants.find((v) => extractVariantSku(v) === desiredSku);
    const id = hit ? extractVariantId(hit) : '';
    if (id) return id;
  }

  if (desiredOptions && Object.keys(desiredOptions).length > 0) {
    for (const v of variants) {
      const opts = extractVariantOptions(v);
      if (optionsRecordEquals(opts, desiredOptions)) {
        const id = extractVariantId(v);
        if (id) return id;
      }
    }
  }

  return null;
}

async function rewriteCheckoutItemsForOfferSelection(args) {
  const { offerId, merchantId, items, checkoutToken } = args;
  const parsed = offerId ? parseOfferId(offerId) : null;
  const productGroupId = parsed?.product_group_id ? String(parsed.product_group_id).trim() : null;
  if (!productGroupId) return { product_group_id: null, product_id: null, items };

  const groupResp = await fetchProductGroupMembersFromUpstream({
    productGroupId,
    checkoutToken,
  }).catch(() => null);
  const members = Array.isArray(groupResp?.members) ? groupResp.members : [];
  const targetMember = members.find(
    (m) => String(m?.merchant_id || m?.merchantId || '').trim() === String(merchantId || '').trim(),
  );
  const targetProductId = String(targetMember?.product_id || targetMember?.productId || '').trim() || null;
  if (!targetProductId) return { product_group_id: productGroupId, product_id: null, items };

  const productCache = new Map();
  const fetchProduct = async (mid, pid) => {
    const key = `${mid}:${pid}`;
    if (productCache.has(key)) return productCache.get(key);
    const p = await fetchLegacyProductDetailFromUpstream({ merchantId: mid, productId: pid, checkoutToken }).catch(
      () => null,
    );
    productCache.set(key, p || null);
    return p || null;
  };

  const targetProduct = await fetchProduct(merchantId, targetProductId);
  if (!targetProduct) return { product_group_id: productGroupId, product_id: targetProductId, items };

  async function deriveVariantSelectorFromGroup(variantId, preferredProductId) {
    const vid = String(variantId || '').trim();
    if (!vid) return { sku: null, options: null };
    const preferredPid = String(preferredProductId || '').trim();
    const ordered = preferredPid
      ? [
          ...members.filter(
            (m) => String(m?.product_id || m?.productId || '').trim() === preferredPid,
          ),
          ...members.filter(
            (m) => String(m?.product_id || m?.productId || '').trim() !== preferredPid,
          ),
        ]
      : members;

    for (const m of ordered) {
      const mid = String(m?.merchant_id || m?.merchantId || '').trim();
      const pid = String(m?.product_id || m?.productId || '').trim();
      if (!mid || !pid) continue;
      const p = await fetchProduct(mid, pid);
      if (!p) continue;
      const variants = Array.isArray(p.variants) ? p.variants : [];
      const hit = variants.find((v) => extractVariantId(v) === vid);
      if (!hit) continue;
      const sku = extractVariantSku(hit) || null;
      const options = extractVariantOptions(hit);
      return {
        sku,
        options: options && Object.keys(options).length ? options : null,
      };
    }
    return { sku: null, options: null };
  }

  const rewritten = [];
  for (const rawItem of Array.isArray(items) ? items : []) {
    const item = rawItem && typeof rawItem === 'object' ? { ...rawItem } : null;
    if (!item) continue;

    const originalProductId = String(item.product_id || item.productId || '').trim();
    const originalVariantId = String(item.variant_id || item.variantId || '').trim();
    const originalSku = String(item.sku || item.sku_id || item.skuId || '')
      .trim()
      .toUpperCase();
    const selectedOptionsRaw = item.selected_options || item.selectedOptions || item.options || null;
    const selectedOptions = normalizeOptionsRecord(selectedOptionsRaw);

    let desiredSku = originalSku || null;
    let desiredOptions = Object.keys(selectedOptions).length ? selectedOptions : null;

    if (!desiredSku && !desiredOptions && originalVariantId) {
      const derived = await deriveVariantSelectorFromGroup(originalVariantId, originalProductId);
      desiredSku = derived.sku;
      desiredOptions = derived.options;
    }

    const mappedVariantId = findVariantIdInProduct(targetProduct, {
      sku: desiredSku,
      options: desiredOptions,
    });

    // If product_id changes across sellers, we must be able to map a variant_id safely.
    if (!mappedVariantId && originalProductId && originalProductId !== targetProductId) {
      const err = new Error('Selected variant is not available for this seller.');
      err.code = 'VARIANT_MAPPING_FAILED';
      throw err;
    }

    item.product_id = targetProductId;
    if (mappedVariantId) {
      item.variant_id = mappedVariantId;
      item.variantId = mappedVariantId;
    }
    // Preserve helpful hints for downstream logs/debugging.
    if (desiredSku && !item.sku) item.sku = desiredSku;
    if (desiredOptions && !item.selected_options) item.selected_options = desiredOptions;
    rewritten.push(item);
  }

  return { product_group_id: productGroupId, product_id: targetProductId, items: rewritten };
}

async function fetchSimilarProductsFromUpstream(args) {
  const { merchantId, productId, limit, checkoutToken, timeoutMs } = args;
  const url = `${PIVOTA_API_BASE}/agent/shop/v1/invoke`;
  const data = {
    operation: 'find_similar_products',
    payload: {
      // Upstream shopping gateway expects the flat payload shape.
      // The nested `payload.similar` shape is supported at this gateway boundary,
      // but must be normalized before forwarding upstream.
      merchant_id: merchantId,
      product_id: productId,
      limit: limit || 6,
    },
  };
  const axiosConfig = {
    method: 'POST',
    url,
    headers: {
      'Content-Type': 'application/json',
      ...buildInvokeUpstreamAuthHeaders({ checkoutToken }),
    },
    timeout: Number.isFinite(Number(timeoutMs)) && Number(timeoutMs) > 0
      ? Number(timeoutMs)
      : getUpstreamTimeoutMs('find_similar_products'),
    data,
  };
  const resp = await callUpstreamWithOptionalRetry('find_similar_products', axiosConfig);
  return Array.isArray(resp?.data?.products) ? resp.data.products : [];
}

async function fetchReviewSummaryFromUpstream(args) {
  const { merchantId, platform, platformProductId, checkoutToken } = args;
  const mid = String(merchantId || '').trim();
  const pf = String(platform || '').trim();
  const pid = String(platformProductId || '').trim();
  if (!mid || !pf || !pid) return null;

  const url = `${REVIEWS_API_BASE}/agent/shop/v1/invoke`;
  const data = {
    operation: 'get_review_summary',
    payload: {
      sku: {
        merchant_id: mid,
        platform: pf,
        platform_product_id: pid,
        variant_id: null,
      },
    },
  };

  const axiosConfig = {
    method: 'POST',
    url,
    headers: {
      'Content-Type': 'application/json',
      ...(checkoutToken ? { 'X-Checkout-Token': checkoutToken } : {}),
    },
    timeout: UPSTREAM_TIMEOUT_REVIEWS_MS,
    data,
  };

  // Avoid long retries (e.g. search retry timeout) for optional review summary.
  const resp = await callUpstreamWithOptionalRetry('get_review_summary', axiosConfig);
  const summary = resp?.data?.review_summary;
  return summary && typeof summary === 'object' ? summary : null;
}

async function fetchReviewSummaryCached(args = {}) {
  const merchantId = String(args?.merchantId || '').trim();
  const platform = String(args?.platform || '').trim();
  const platformProductId = String(args?.platformProductId || '').trim();
  if (!merchantId || !platform || !platformProductId) return null;

  const bypassCache = Boolean(args?.bypassCache);
  const cacheKey = buildPdpReviewSummaryCacheKey({
    merchantId,
    platform,
    platformProductId,
  });
  if (!cacheKey) return null;

  if (PDP_REVIEW_SUMMARY_CACHE_ENABLED && !bypassCache) {
    const cached = getPdpReviewSummaryCacheEntry(cacheKey);
    if (cached.found) return cached.value;
  }

  const existing = PDP_REVIEW_SUMMARY_INFLIGHT.get(cacheKey);
  if (existing) return existing;

  trimOldestInflightEntries(PDP_REVIEW_SUMMARY_INFLIGHT, PDP_REVIEW_SUMMARY_INFLIGHT_MAX_ENTRIES);
  const task = (async () => {
    try {
      const summary = await fetchReviewSummaryFromUpstream({
        ...args,
        merchantId,
        platform,
        platformProductId,
      });
      if (PDP_REVIEW_SUMMARY_CACHE_ENABLED && !bypassCache) {
        const ttl = summary ? PDP_REVIEW_SUMMARY_CACHE_TTL_MS : PDP_REVIEW_SUMMARY_NEGATIVE_TTL_MS;
        setPdpReviewSummaryCacheEntry(cacheKey, summary, ttl);
      }
      return summary;
    } finally {
      PDP_REVIEW_SUMMARY_INFLIGHT.delete(cacheKey);
    }
  })();
  PDP_REVIEW_SUMMARY_INFLIGHT.set(cacheKey, task);
  return task;
}

// Curated product-relationship graph (human-approved edges in
// `product_relationship_edges`) is the high-trust complement to the dynamic
// recall engine. Default OFF — flip the flag only after staging verification.
function isPdpRelationshipGraphServingEnabled() {
  return isRelationshipGraphSurfaceEnabled('pdp_similar');
}
const SIMILAR_FAMILY_DEDUPE_ENABLED =
  String(process.env.AURORA_BFF_SIMILAR_FAMILY_DEDUPE_ENABLED || '').trim().toLowerCase() === 'true';

function normalizeSimilarFamilyResolutionRef(value) {
  const ref = firstNonEmptyString(value);
  if (!ref) return '';
  if (typeof normalizeRelationshipGraphRefForResolution === 'function') {
    const normalized = normalizeRelationshipGraphRefForResolution(ref);
    return firstNonEmptyString(normalized?.normalized_ref);
  }
  return String(ref).trim().toLowerCase();
}

function getSimilarFamilyAnchorResolutionRef(product = {}) {
  return normalizeSimilarFamilyResolutionRef(
    firstNonEmptyString(
      product?.external_product_id,
      product?.source_product_id,
      product?.product_id,
    ),
  );
}

function getSimilarFamilyItemResolutionRef(item = {}) {
  return normalizeSimilarFamilyResolutionRef(
    firstNonEmptyString(
      item?.source_product_id,
      item?.external_product_id,
      item?.product_id,
      item?.id,
    ),
  );
}

function collectSimilarFamilyResolutionRefs(anchorProduct = {}, products = []) {
  const refs = [];
  const seen = new Set();
  const push = (value) => {
    const ref = normalizeSimilarFamilyResolutionRef(value);
    if (!ref || seen.has(ref)) return;
    seen.add(ref);
    refs.push(ref);
  };
  push(getSimilarFamilyAnchorResolutionRef(anchorProduct));
  for (const item of Array.isArray(products) ? products : []) {
    push(getSimilarFamilyItemResolutionRef(item));
  }
  return refs;
}

function resolvedSimilarFamilyKey(resolved = {}) {
  const key = String(resolved?.family_key || '').trim();
  return key.startsWith('family:') ? key : '';
}

async function resolveSimilarFamilyDedupeContext({
  anchorProduct = {},
  items = [],
  queryFn = query,
} = {}) {
  const safeAnchorProduct =
    anchorProduct && typeof anchorProduct === 'object' && !Array.isArray(anchorProduct)
      ? anchorProduct
      : {};
  const anchorRef = getSimilarFamilyAnchorResolutionRef(safeAnchorProduct);
  const refs = collectSimilarFamilyResolutionRefs(safeAnchorProduct, items);
  let resolutionMap = null;
  if (
    refs.length &&
    typeof resolveRelationshipGraphRefsToCanonicalEntities === 'function' &&
    typeof queryFn === 'function'
  ) {
    try {
      const resolved = await resolveRelationshipGraphRefsToCanonicalEntities(refs, { queryFn });
      if (resolved && typeof resolved.get === 'function' && resolved.size > 0) {
        resolutionMap = resolved;
      }
    } catch (err) {
      logger.warn?.(
        {
          kind: 'metric',
          name: 'aurora_bff_similar_family_resolution_failed',
          error: err?.message || String(err),
          ref_count: refs.length,
        },
        'aurora bff: similar family catalog resolution failed; using title-based dedupe',
      );
    }
  }

  const resolvedAnchor = resolutionMap && anchorRef ? resolutionMap.get(anchorRef) : null;
  return {
    anchorFamilyKey:
      resolvedSimilarFamilyKey(resolvedAnchor) ||
      familyIdentityKey(shapeItemForFamilyKey(safeAnchorProduct)),
    resolutionMap,
  };
}

async function fetchRelationshipGraphSimilarItems(anchorProduct, { market = 'US', limit = 24 } = {}) {
  return fetchRelationshipGraphRecallForAnchor({
    anchorProduct,
    surface: 'pdp_similar',
    market: firstNonEmptyString(market, anchorProduct?.market, 'US'),
    limit,
    logger,
  });
}

function buildRelationshipGraphOnlySimilarEnvelopeForSkippedAccessory({
  graphRecall = null,
  limit = 24,
  skippedReason = 'no_verified_accessory_matches',
} = {}) {
  const graphItems = Array.isArray(graphRecall?.items) ? graphRecall.items : [];
  if (!graphItems.length) return null;
  const safeLimit = Number(limit);
  const items = Number.isFinite(safeLimit) && safeLimit > 0
    ? graphItems.slice(0, safeLimit)
    : graphItems;
  return {
    status: 'success',
    strategy: 'relationship_graph',
    items,
    metadata: {
      similar_status: 'ready',
      dynamic_recall_skipped: true,
      dynamic_recall_skipped_reason: skippedReason,
      low_confidence: false,
      low_confidence_reason_codes: [],
      underfill: 0,
      relationship_graph_enabled: true,
      relationship_graph_edge_count: Number(graphRecall?.metadata?.edge_count || 0),
      relationship_graph_curated_count: graphItems.length,
      relationship_graph_served_count: countRelationshipGraphSimilarProducts(items),
    },
  };
}

async function fetchSimilarProductsDeduped(args = {}) {
  const inflightKey = buildPdpSimilarInflightKey(args);
  const runOnce = async () => {
    const rec = await recommendPdpProducts(args);
    const items = Array.isArray(rec?.items) ? rec.items : [];
    let curated = [];
    let relationshipGraphMeta;
    if (isPdpRelationshipGraphServingEnabled()) {
      const graphRecall = await fetchRelationshipGraphSimilarItems(args?.pdp_product, {
        market: args?.pdp_product?.market || 'US',
        limit: Number(args?.k) || 24,
      });
      curated = Array.isArray(graphRecall?.items) ? graphRecall.items : [];
      if (graphRecall?.metadata?.enabled) {
        relationshipGraphMeta = {
          relationship_graph_enabled: true,
          relationship_graph_edge_count: Number(graphRecall?.metadata?.edge_count || 0),
          relationship_graph_curated_count: curated.length,
          relationship_graph_served_count: 0,
        };
      }
    }

    const combinedItems = curated.length ? [...curated, ...items] : items;
    const familyDedupeContext = SIMILAR_FAMILY_DEDUPE_ENABLED
      ? await resolveSimilarFamilyDedupeContext({
          anchorProduct: args?.pdp_product || {},
          items: combinedItems,
          queryFn: query,
        })
      : { anchorFamilyKey: '', resolutionMap: null };
    let mergedItems = SIMILAR_FAMILY_DEDUPE_ENABLED
      ? dedupeSimilarCandidatesByFamily(combinedItems, familyDedupeContext)
      : curated.length
        ? dedupeSimilarCandidatesByMerchantProductId(combinedItems)
        : items;

    if (curated.length) {
      // Curated (human-approved) edges rank ahead of dynamic recall; dedupe
      // keeps the first occurrence, so curated wins on collisions.
      const k = Number(args?.k);
      if (Number.isFinite(k) && k > 0) mergedItems = mergedItems.slice(0, k);
      relationshipGraphMeta = {
        ...(relationshipGraphMeta || {}),
        relationship_graph_curated_count: curated.length,
        relationship_graph_served_count: countRelationshipGraphSimilarProducts(mergedItems),
      };
    }
    return {
      status: mergedItems.length > 0 ? 'success' : rec?.status || 'empty',
      strategy: rec?.strategy || 'related_products',
      items: mergedItems,
      metadata: {
        ...(rec?.metadata && typeof rec.metadata === 'object' ? rec.metadata : {}),
        ...(relationshipGraphMeta || {}),
      },
      ...(rec?.debug ? { debug: rec.debug } : {}),
      ...(rec?.cache ? { cache: rec.cache } : {}),
    };
  };

  if (!inflightKey) return runOnce();
  const existing = PDP_SIMILAR_INFLIGHT.get(inflightKey);
  if (existing) return existing;

  trimOldestInflightEntries(PDP_SIMILAR_INFLIGHT, PDP_SIMILAR_INFLIGHT_MAX_ENTRIES);
  const task = (async () => {
    try {
      return await runOnce();
    } finally {
      PDP_SIMILAR_INFLIGHT.delete(inflightKey);
    }
  })();
  PDP_SIMILAR_INFLIGHT.set(inflightKey, task);
  return task;
}

function readSimilarCardText(...values) {
  for (const value of values) {
    const text = String(value || '').replace(/\s+/g, ' ').trim();
    if (text) return text;
  }
  return '';
}

function readSimilarCardEvidenceProfile(product = {}) {
  return readSimilarCardText(
    product.evidence_profile,
    product.evidenceProfile,
    product.product_intel?.evidence_profile,
    product.productIntel?.evidence_profile,
    product.shopping_card?.evidence_profile,
    product.shoppingCard?.evidence_profile,
    product.search_card?.evidence_profile,
    product.searchCard?.evidence_profile,
  ).toLowerCase();
}

const TRUSTED_SIMILAR_CARD_HIGHLIGHT_SOURCES = new Set([
  'catalog_product',
  'official_external_seed_card',
  'source_backed_title_or_intro',
  'official_pdp_seed',
  'official_pdp_seed_title',
]);

function hasTrustedSourceBackedSimilarCardHighlight(product = {}) {
  if (!product || typeof product !== 'object' || Array.isArray(product)) return false;
  const source = readSimilarCardText(
    product.card_highlight_source,
    product.cardHighlightSource,
    product.shopping_card?.highlight_source,
    product.shoppingCard?.highlight_source,
    product.shoppingCard?.highlightSource,
    product.search_card?.highlight_source,
    product.searchCard?.highlight_source,
    product.searchCard?.highlightSource,
  ).toLowerCase();
  if (!TRUSTED_SIMILAR_CARD_HIGHLIGHT_SOURCES.has(source)) return false;
  return Boolean(
    readSimilarCardText(
      product.card_highlight,
      product.cardHighlight,
      product.shopping_card?.highlight,
      product.shoppingCard?.highlight,
      product.search_card?.highlight_candidate,
      product.searchCard?.highlight_candidate,
      product.searchCard?.highlightCandidate,
    ),
  );
}

function isSellerOnlySimilarCardEvidence(product = {}) {
  if (hasTrustedSourceBackedSimilarCardHighlight(product)) return false;
  const profiles = [
    product.evidence_profile,
    product.evidenceProfile,
    product.product_intel?.evidence_profile,
    product.productIntel?.evidence_profile,
    product.shopping_card?.evidence_profile,
    product.shoppingCard?.evidence_profile,
    product.search_card?.evidence_profile,
    product.searchCard?.evidence_profile,
  ]
    .map((value) => readSimilarCardText(value).toLowerCase())
    .filter(Boolean);
  return profiles.some((profile) => profile === 'seller_only' || profile === 'seller_only_fallback');
}

function hasSimilarCardPresentation(product = {}) {
  if (isSellerOnlySimilarCardEvidence(product)) return false;
  return Boolean(
    readSimilarCardText(
      product.card_highlight,
      product.cardHighlight,
      product.shopping_card?.highlight,
      product.shoppingCard?.highlight,
      product.search_card?.highlight_candidate,
      product.searchCard?.highlight_candidate,
      product.searchCard?.highlightCandidate,
      product.description,
    ),
  );
}

function hasSimilarCardImage(product = {}) {
  if (!product || typeof product !== 'object') return false;
  const candidates = [
    product.image_url,
    product.imageUrl,
    product.image,
    Array.isArray(product.images) ? product.images[0] : null,
    Array.isArray(product.image_urls) ? product.image_urls[0] : null,
    product.shopping_card?.image_url,
    product.search_card?.image_url,
  ];
  return candidates.some((value) => String(value || '').trim().length > 0);
}

const SIMILAR_CARD_TITLE_FALLBACK_PRODUCT_RE =
  /\b(?:ampoule|balm|bar|beard|blush|body\s*wash|bronzer|brow|cleanser|cleansing|conditioner|concealer|cream|deodorant|essence|exfoliant|eyeshadow|foundation|fragrance|gel|glaze|gloss|liner|lip(?:\s*(?:balm|color|glaze|gloss|liner|matt(?:e)?|oil|serum|stain|stick|tint|treatment))?|lipstick|lotion|mascara|mask|mist|moisturizer|oil|pad|palette|patch|peel|powder|primer|serum|shampoo|shav(?:e|ing)|spf|sunscreen|tint|toner|treatment)\b/i;

const SIMILAR_CARD_TITLE_FALLBACK_GENERIC_RE =
  /\b(?:category\s+only|missing\s+highlight|similar\s+product|related\s+product|product\s+\d*|item\s+\d*)\b/i;

function normalizeSimilarCardFallbackText(value, { maxChars = 74 } = {}) {
  const text = String(value || '')
    .replace(/<[^>]*>/g, ' ')
    .replace(/\s+/g, ' ')
    .trim()
    .replace(/[.;,:|-]+$/g, '')
    .trim();
  if (!text) return '';
  if (text.length <= maxChars) return text;
  return text.slice(0, maxChars).replace(/\s+\S*$/g, '').replace(/[.;,:|-]+$/g, '').trim();
}

const SIMILAR_CARD_OFFICIAL_SEED_HIGHLIGHT_MAX_CHARS = 40;

const SIMILAR_CARD_OFFICIAL_SEED_BENEFIT_RE =
  /\b(?:aha|barrier|beard|body|balance|cleanse|cleanses|cleansing|condition|conditioning|deodorant|exfoliat|finish|firm|flexible|fullness|hair|hold|hydration|lather|matte|moisturi[sz]|odor|odour|oil|protective|razor|shav(?:e|ing)|shine|soften|soothe|sulfate-free|texture|thicken|volume|weightless)\b/i;

const SIMILAR_CARD_OFFICIAL_SEED_BLOCKLIST_RE =
  /\b(?:add[-\s]?on donation|caution|cotton twill|customer service|donation|for best results|gift card|how to use|ingredient|one size fits most|package protection|policies|refund|shipping|terms)\b/i;

function normalizeOfficialSeedSimilarHighlightCandidate(value) {
  const text = String(value || '')
    .replace(/<!--[\s\S]*?-->/g, ' ')
    .replace(/<[^>]*>/g, ' ')
    .replace(/&nbsp;/gi, ' ')
    .replace(/\s+/g, ' ')
    .trim()
    .replace(/^[.;,:|\-]+/g, '')
    .replace(/[.;,:|\-]+$/g, '')
    .trim();
  if (!text) return '';
  if (text.length > SIMILAR_CARD_OFFICIAL_SEED_HIGHLIGHT_MAX_CHARS) return '';
  if (SIMILAR_CARD_OFFICIAL_SEED_BLOCKLIST_RE.test(text)) return '';
  if (!SIMILAR_CARD_OFFICIAL_SEED_BENEFIT_RE.test(text)) return '';
  return text.charAt(0).toUpperCase() + text.slice(1);
}

function collectOfficialSeedSimilarHighlightSourceTexts(detail = {}) {
  if (!detail || typeof detail !== 'object') return [];
  const seedData = isPlainObject(detail.seed_data) ? detail.seed_data : {};
  const snapshot = isPlainObject(seedData.snapshot) ? seedData.snapshot : {};
  const sources = [
    detail.pdp_description_raw,
    detail.description,
    detail.summary,
    seedData.pdp_description_raw,
    snapshot.pdp_description_raw,
    seedData.description,
    snapshot.description,
  ];
  for (const sections of [detail.pdp_details_sections, detail.details_sections, seedData.pdp_details_sections, snapshot.pdp_details_sections]) {
    if (!Array.isArray(sections)) continue;
    sections.forEach((section) => {
      if (!section || typeof section !== 'object') return;
      sources.push(section.text, section.body, section.content, section.value, section.description);
    });
  }
  return sources
    .map((value) =>
      String(value || '')
        .replace(/<!--[\s\S]*?-->/g, ' ')
        .replace(/<[^>]*>/g, ' ')
        .replace(/\s+/g, ' ')
        .trim(),
    )
    .filter(Boolean);
}

function deriveOfficialSeedSimilarCardHighlight(detail = {}) {
  const sources = collectOfficialSeedSimilarHighlightSourceTexts(detail);
  for (const raw of sources) {
    const text = String(raw || '').replace(/\s+/g, ' ').trim();
    if (!text || SIMILAR_CARD_OFFICIAL_SEED_BLOCKLIST_RE.test(text.slice(0, 120))) continue;

    const directPatterns = [
      /\b(sulfate-free)\b[^.]{0,90}\bcleanse (?:your )?hair\b/i,
      /\b(sulfate-free)\b[^.]{0,90}\bcleanse (?:your )?body\b/i,
      /\b(adds? weightless body and shine)\b/i,
      /\b(immediate hydration and balance)\b/i,
      /\b(skin barrier recovery and protection)\b/i,
      /\b(strong hold and (?:a )?matte finish)\b/i,
      /\b(maximum hold and (?:a )?high sheen)\b/i,
      /\b(medium-to-strong hold and light shine)\b/i,
      /\b(weightless hold and (?:a )?natural sheen)\b/i,
      /\b(medium hold and (?:a )?workable,? natural finish)\b/i,
      /\b(weightless volume and texture)\b/i,
      /\b(fullness and flexible hold)\b/i,
      /\b(moisturi[sz]e and soften coarse beard hairs)\b/i,
      /\b(soften,? tame and lightly style (?:your )?beard)\b/i,
      /\b(condition(?:s)? and (?:keeps|leaves) (?:your )?beard soft and shiny)\b/i,
      /\b(aluminum[-\s]*free deodorant)\b/i,
      /\b(absorb(?:s|ing)? excess moisture)\b/i,
      /\b(odor[-\s]*fighting AHA'?s?)\b/i,
      /\b(deodorant protection)\b/i,
      /\b(protective lather)\b/i,
      /\b(protective layer of glide)\b/i,
      /\b(soften(?:s)? (?:your )?facial hair)\b/i,
      /\b(gently cleanses and hydrates)\b/i,
      /\b(non-stripping body cleansing)\b/i,
    ];

    for (const pattern of directPatterns) {
      const match = text.match(pattern);
      if (!match) continue;
      if (pattern.source.includes('cleanse (?:your )?hair')) {
        return 'Sulfate-free hair cleanse';
      }
      if (pattern.source.includes('cleanse (?:your )?body')) {
        return 'Sulfate-free body cleanse';
      }
      const candidate = normalizeOfficialSeedSimilarHighlightCandidate(match[1]);
      if (candidate) return candidate;
    }

    if (/\baha\b/i.test(text) && /\bdead skin\b/i.test(text) && /\bexfoliat/i.test(text)) {
      return 'AHA exfoliation for dead skin';
    }
    if (/\brice bran\b/i.test(text) && /\bexfoliat/i.test(text) && /\bclean/i.test(text)) {
      return 'Rice bran exfoliating cleanse';
    }
    if (/\bfoaming\s+(?:body\s*wash|shower\s*gel)\b/i.test(text)) {
      return 'Foaming body wash cleanse';
    }
    if (/\bhand\s*(?:&|\+|and)\s*body\s*wash\b/i.test(text) && /\b(?:cleanse|cleanses|cleansing|sooth|protect|nourish|hydrate)\b/i.test(text)) {
      return 'Hand and body wash';
    }
    if (/\bbody\s*wash\b/i.test(text) && /\b(?:cleanse|cleanses|cleansing|gentle|sulfate-free|hydrate|nourish|refresh)\b/i.test(text)) {
      return 'Body wash cleanse';
    }
    if (/\b(?:body\s*bar|cleansing\s*bar|bar\s*cleanser)\b/i.test(text) && /\b(?:cleanse|cleanses|cleansing|lather|skin|body|moisturi[sz]|nourish|hydrate)\b/i.test(text)) {
      return 'Body cleansing bar';
    }
    if (/\bdeodorant\b/i.test(text) && /\b(?:kind to your skin|nourish|hydrate|macadamia|bergamot|odor|odour|aluminum[-\s]*free|fresh[-\s]*feel)\b/i.test(text)) {
      return 'Kind-to-skin deodorant';
    }

    const sentences = text
      .split(/(?<=[.!?])\s+/)
      .slice(0, 3)
      .flatMap((sentence) => sentence.split(/\s+(?:while|with|and then|that)\s+/i))
      .map((part) =>
        part
          .replace(/^(?:this|the|our|blind barber'?s?)\s+/i, '')
          .replace(/\b(?:has been|is)\s+formulated\s+to\s+/i, '')
          .replace(/\b(?:has been|is)\s+designed\s+to\s+/i, '')
          .trim(),
      );
    for (const sentence of sentences) {
      const candidate = normalizeOfficialSeedSimilarHighlightCandidate(sentence);
      if (candidate) return candidate;
    }
  }
  return '';
}

function hasOfficialSeedSimilarCardSourceText(detail = {}) {
  return collectOfficialSeedSimilarHighlightSourceTexts(detail).some((value) => {
    const text = String(value || '').replace(/\s+/g, ' ').trim();
    return text.length >= 24 && !SIMILAR_CARD_OFFICIAL_SEED_BLOCKLIST_RE.test(text.slice(0, 120));
  });
}

function deriveOfficialSeedSimilarCardTitleHighlight(detail = {}) {
  if (!hasOfficialSeedSimilarCardSourceText(detail)) return '';
  const title = normalizeSimilarCardFallbackText(
    readSimilarCardText(
      detail.title,
      detail.name,
      detail.card_title,
      detail.shopping_card?.title,
      detail.search_card?.title_candidate,
      detail.seed_data?.snapshot?.title,
      detail.seed_data?.title,
    ),
    { maxChars: 64 },
  );
  if (!title || title.length < 8) return '';
  if (SIMILAR_CARD_TITLE_FALLBACK_GENERIC_RE.test(title)) return '';
  if (!SIMILAR_CARD_TITLE_FALLBACK_PRODUCT_RE.test(title)) return '';
  if (SIMILAR_CARD_OFFICIAL_SEED_BLOCKLIST_RE.test(title)) return '';
  return title;
}

function deriveSourceBackedSimilarCardHighlight(item = {}) {
  if (!item || typeof item !== 'object') return '';

  if (!isSellerOnlySimilarCardEvidence(item)) {
    const intro = normalizeSimilarCardFallbackText(
      readSimilarCardText(
        item.card_intro,
        item.cardIntro,
        item.shopping_card?.intro,
        item.shoppingCard?.intro,
        item.search_card?.intro_candidate,
        item.searchCard?.intro_candidate,
        item.searchCard?.introCandidate,
        item.summary,
      ),
    );
    if (intro) return intro;
  }

  const title = normalizeSimilarCardFallbackText(
    readSimilarCardText(
      item.title,
      item.name,
      item.card_title,
      item.cardTitle,
      item.shopping_card?.title,
      item.shoppingCard?.title,
      item.search_card?.title_candidate,
      item.searchCard?.title_candidate,
      item.searchCard?.titleCandidate,
    ),
  );
  if (!title || title.length < 8) return '';
  if (SIMILAR_CARD_TITLE_FALLBACK_GENERIC_RE.test(title)) return '';
  if (!SIMILAR_CARD_TITLE_FALLBACK_PRODUCT_RE.test(title)) return '';

  const normalizedTitle = normalizeSearchTextForMatch(title);
  const normalizedCategory = normalizeSearchTextForMatch(
    readSimilarCardText(
      item.category,
      item.product_type,
      item.productType,
      item.card_subtitle,
      item.cardSubtitle,
      item.shopping_card?.subtitle,
      item.shoppingCard?.subtitle,
      item.search_card?.compact_candidate,
      item.searchCard?.compact_candidate,
      item.searchCard?.compactCandidate,
    ),
  );
  if (!normalizedTitle || normalizedTitle === normalizedCategory) return '';

  return title;
}

function applySourceBackedSimilarCardHighlightFallback(item = {}) {
  if (!item || typeof item !== 'object') return item;
  if (hasSimilarCardPresentation(item)) return item;

  const replaceSellerOnlyCardText = isSellerOnlySimilarCardEvidence(item);
  const cardHighlight = deriveSourceBackedSimilarCardHighlight(item);
  if (!cardHighlight) return item;

  const next = {
    ...item,
    card_highlight: cardHighlight,
    card_highlight_source: item.card_highlight_source || 'source_backed_title_or_intro',
  };
  if (!next.shopping_card || typeof next.shopping_card !== 'object' || Array.isArray(next.shopping_card)) {
    next.shopping_card = {};
  }
  if (replaceSellerOnlyCardText || !readSimilarCardText(next.shopping_card.highlight)) {
    next.shopping_card = {
      ...next.shopping_card,
      highlight: cardHighlight,
      highlight_source: next.shopping_card.highlight_source || next.card_highlight_source,
    };
  }
  if (!next.search_card || typeof next.search_card !== 'object' || Array.isArray(next.search_card)) {
    next.search_card = {};
  }
  if (replaceSellerOnlyCardText || !readSimilarCardText(next.search_card.highlight_candidate)) {
    next.search_card = {
      ...next.search_card,
      highlight_candidate: cardHighlight,
      highlight_source: next.search_card.highlight_source || next.card_highlight_source,
    };
  }
  return next;
}

function applyOfficialSeedSimilarCardEnrichment(item = {}, detail = {}) {
  if (!item || typeof item !== 'object') return item;
  const derivedHighlight = deriveOfficialSeedSimilarCardHighlight(detail);
  const titleHighlight = derivedHighlight ? '' : deriveOfficialSeedSimilarCardTitleHighlight(detail);
  const cardHighlight = derivedHighlight || titleHighlight;
  if (!cardHighlight) return item;
  const highlightSource = derivedHighlight ? 'official_pdp_seed' : 'official_pdp_seed_title';
  const next = {
    ...item,
    card_highlight: cardHighlight,
    card_highlight_source: highlightSource,
    evidence_profile: highlightSource,
  };
  if (!next.shopping_card || typeof next.shopping_card !== 'object' || Array.isArray(next.shopping_card)) {
    next.shopping_card = {};
  }
  next.shopping_card = {
    ...next.shopping_card,
    highlight: cardHighlight,
    evidence_profile: highlightSource,
  };
  if (!next.search_card || typeof next.search_card !== 'object' || Array.isArray(next.search_card)) {
    next.search_card = {};
  }
  next.search_card = {
    ...next.search_card,
    highlight_candidate: cardHighlight,
    evidence_profile: highlightSource,
  };
  return next;
}

function annotateSimilarCardStatus(item = {}) {
  if (!item || typeof item !== 'object') return item;
  const next = applySourceBackedSimilarCardHighlightFallback(item);
  const sellerOnlyEvidence = isSellerOnlySimilarCardEvidence(next);
  return {
    ...next,
    card_highlight_status: sellerOnlyEvidence
      ? 'seller_only_fallback'
      : hasSimilarCardPresentation(next)
        ? 'ready'
        : 'highlight_missing',
    ...(sellerOnlyEvidence ? { card_highlight_reject_reason: 'seller_only_evidence' } : {}),
    card_image_status: hasSimilarCardImage(next) ? 'ready' : 'image_missing',
  };
}

function isSimilarCardDetailHydrationAllowed({ allowDetailHydration = false } = {}) {
  return allowDetailHydration === true && PDP_SIMILAR_CARD_DETAIL_ENRICH_ENABLED;
}

function shouldEnrichSimilarCard(item = {}, options = {}) {
  // Detail hydration is offline/opt-in only; public similar cards must be ready from the recall doc.
  return isSimilarCardDetailHydrationAllowed(options) && !hasSimilarCardImage(item);
}

function shouldHydrateSimilarCardFromOfficialSeed(item = {}) {
  if (!item || typeof item !== 'object') return false;
  const externalSeedIds = collectExternalSeedIdCandidatesForVisibleCatalogHydration(item);
  if (!externalSeedIds.length) return false;
  return isSellerOnlySimilarCardEvidence(item) || !hasSimilarCardPresentation(item) || !hasSimilarCardImage(item);
}

function buildSimilarCardEnrichmentCacheKey({
  items = [],
  maxItems = 0,
  allowDetailHydration = false,
} = {}) {
  if (!PDP_SIMILAR_CARD_ENRICH_CACHE_ENABLED) return '';
  const list = Array.isArray(items) ? items : [];
  if (!list.length) return '';
  const normalizedMaxItems = Math.max(0, Number(maxItems) || 0);
  const fingerprintItems = list.slice(0, Math.min(list.length, 60)).map((item) => {
    if (!item || typeof item !== 'object') return null;
    return {
      merchant_id: firstNonEmptyString(item.merchant_id, item.merchant?.id, item.merchant_uuid),
      product_id: firstNonEmptyString(
        item.product_id,
        item.productId,
        item.id,
        item.source_product_id,
        item.external_product_id,
        item.platform_product_id,
      ),
      title: firstNonEmptyString(item.card_title, item.title, item.name),
      image_url: firstNonEmptyString(
        item.image_url,
        item.image,
        Array.isArray(item.images) ? item.images[0] : null,
        Array.isArray(item.image_urls) ? item.image_urls[0] : null,
      ),
      card_highlight: firstNonEmptyString(
        item.card_highlight,
        item.cardHighlight,
        item.shopping_card?.highlight,
        item.search_card?.highlight_candidate,
      ),
      evidence_profile: firstNonEmptyString(
        item.evidence_profile,
        item.card_highlight_source,
        item.shopping_card?.evidence_profile,
        item.search_card?.evidence_profile,
      ),
    };
  });
  return createHash('sha1')
    .update(JSON.stringify({
      max_items: normalizedMaxItems,
      allow_detail_hydration: allowDetailHydration === true,
      item_count: list.length,
      items: fingerprintItems,
    }))
    .digest('hex');
}

function cloneSimilarCardEnrichmentItem(item) {
  if (!item || typeof item !== 'object' || Array.isArray(item)) return item;
  return {
    ...item,
    ...(item.price && typeof item.price === 'object' && !Array.isArray(item.price)
      ? { price: { ...item.price } }
      : {}),
    ...(item.merchant && typeof item.merchant === 'object' && !Array.isArray(item.merchant)
      ? { merchant: { ...item.merchant } }
      : {}),
    ...(item.shopping_card && typeof item.shopping_card === 'object' && !Array.isArray(item.shopping_card)
      ? { shopping_card: { ...item.shopping_card } }
      : {}),
    ...(item.search_card && typeof item.search_card === 'object' && !Array.isArray(item.search_card)
      ? { search_card: { ...item.search_card } }
      : {}),
    ...(Array.isArray(item.external_highlight_signals)
      ? { external_highlight_signals: item.external_highlight_signals.slice() }
      : {}),
  };
}

function cloneSimilarCardEnrichmentResult(items = [], metadata = {}) {
  const cloned = (Array.isArray(items) ? items : []).map((item) => cloneSimilarCardEnrichmentItem(item));
  return attachSimilarCardEnrichmentMetadata(cloned, {
    ...(metadata && typeof metadata === 'object' ? metadata : {}),
    card_enrichment_cache_hit: true,
  });
}

function readSimilarCardEnrichmentCache(cacheKey, nowMs = Date.now()) {
  if (!cacheKey) return null;
  const cached = PDP_SIMILAR_CARD_ENRICH_CACHE.get(cacheKey);
  if (!cached) return null;
  if (Number(cached.expiresAtMs || 0) <= nowMs) {
    PDP_SIMILAR_CARD_ENRICH_CACHE.delete(cacheKey);
    return null;
  }
  PDP_SIMILAR_CARD_ENRICH_CACHE.delete(cacheKey);
  PDP_SIMILAR_CARD_ENRICH_CACHE.set(cacheKey, cached);
  return cloneSimilarCardEnrichmentResult(cached.items, cached.metadata);
}

function writeSimilarCardEnrichmentCache(cacheKey, items = [], metadata = {}, nowMs = Date.now()) {
  if (!cacheKey) return;
  PDP_SIMILAR_CARD_ENRICH_CACHE.delete(cacheKey);
  PDP_SIMILAR_CARD_ENRICH_CACHE.set(cacheKey, {
    items: (Array.isArray(items) ? items : []).map((item) => cloneSimilarCardEnrichmentItem(item)),
    metadata: metadata && typeof metadata === 'object' ? { ...metadata } : {},
    expiresAtMs: nowMs + PDP_SIMILAR_CARD_ENRICH_CACHE_TTL_MS,
  });
  while (PDP_SIMILAR_CARD_ENRICH_CACHE.size > PDP_SIMILAR_CARD_ENRICH_CACHE_MAX_ENTRIES) {
    const oldestKey = PDP_SIMILAR_CARD_ENRICH_CACHE.keys().next().value;
    if (oldestKey === undefined) break;
    PDP_SIMILAR_CARD_ENRICH_CACHE.delete(oldestKey);
  }
}

function finishSimilarCardEnrichmentResult(items = [], metadata = {}, cacheKey = '') {
  const result = attachSimilarCardEnrichmentMetadata(items, metadata);
  writeSimilarCardEnrichmentCache(cacheKey, result, metadata);
  return result;
}

function buildVisibleSimilarSigHydrationCacheKey(products = []) {
  if (!PDP_SIMILAR_VISIBLE_SIG_HYDRATION_CACHE_ENABLED) return '';
  const list = Array.isArray(products) ? products : [];
  if (!list.length) return '';
  const fingerprintItems = list.slice(0, Math.min(list.length, 60)).map((item) => {
    if (!item || typeof item !== 'object') return null;
    return {
      merchant_id: firstNonEmptyString(item.merchant_id, item.merchant?.id, item.merchant_uuid),
      product_id: firstNonEmptyString(
        item.product_id,
        item.productId,
        item.id,
        item.source_product_id,
        item.external_product_id,
        item.platform_product_id,
      ),
      external_ids: collectExternalSeedIdCandidatesForVisibleCatalogHydration(item),
      title: firstNonEmptyString(item.card_title, item.title, item.name),
      image_url: firstNonEmptyString(
        item.image_url,
        item.image,
        Array.isArray(item.images) ? item.images[0] : null,
        Array.isArray(item.image_urls) ? item.image_urls[0] : null,
      ),
      card_highlight: firstNonEmptyString(
        item.card_highlight,
        item.cardHighlight,
        item.shopping_card?.highlight,
        item.search_card?.highlight_candidate,
      ),
    };
  });
  return createHash('sha1')
    .update(JSON.stringify({
      item_count: list.length,
      items: fingerprintItems,
    }))
    .digest('hex');
}

function readVisibleSimilarSigHydrationCache(cacheKey, nowMs = Date.now()) {
  if (!cacheKey) return null;
  const cached = PDP_SIMILAR_VISIBLE_SIG_HYDRATION_CACHE.get(cacheKey);
  if (!cached) return null;
  if (Number(cached.expiresAtMs || 0) <= nowMs) {
    PDP_SIMILAR_VISIBLE_SIG_HYDRATION_CACHE.delete(cacheKey);
    return null;
  }
  PDP_SIMILAR_VISIBLE_SIG_HYDRATION_CACHE.delete(cacheKey);
  PDP_SIMILAR_VISIBLE_SIG_HYDRATION_CACHE.set(cacheKey, cached);
  return (Array.isArray(cached.products) ? cached.products : []).map((item) =>
    cloneSimilarCardEnrichmentItem(item),
  );
}

function writeVisibleSimilarSigHydrationCache(cacheKey, products = [], nowMs = Date.now()) {
  if (!cacheKey) return;
  PDP_SIMILAR_VISIBLE_SIG_HYDRATION_CACHE.delete(cacheKey);
  PDP_SIMILAR_VISIBLE_SIG_HYDRATION_CACHE.set(cacheKey, {
    products: (Array.isArray(products) ? products : []).map((item) => cloneSimilarCardEnrichmentItem(item)),
    expiresAtMs: nowMs + PDP_SIMILAR_VISIBLE_SIG_HYDRATION_CACHE_TTL_MS,
  });
  while (PDP_SIMILAR_VISIBLE_SIG_HYDRATION_CACHE.size > PDP_SIMILAR_VISIBLE_SIG_HYDRATION_CACHE_MAX_ENTRIES) {
    const oldestKey = PDP_SIMILAR_VISIBLE_SIG_HYDRATION_CACHE.keys().next().value;
    if (oldestKey === undefined) break;
    PDP_SIMILAR_VISIBLE_SIG_HYDRATION_CACHE.delete(oldestKey);
  }
}

function mergeSimilarCardEnrichment(candidate = {}, detail = {}) {
  const next = { ...candidate };
  const copyIfMissing = (targetKey, ...values) => {
    if (next[targetKey] != null && String(next[targetKey]).trim()) return;
    const value = values.find((item) => item != null && String(item).trim());
    if (value != null) next[targetKey] = value;
  };
  copyIfMissing('title', detail.title, detail.name);
  copyIfMissing('description', detail.description);
  copyIfMissing('category', detail.category);
  copyIfMissing('product_type', detail.product_type, detail.productType);
  copyIfMissing('card_title', detail.card_title, detail.cardTitle);
  copyIfMissing('card_subtitle', detail.card_subtitle, detail.cardSubtitle);
  copyIfMissing('card_highlight', detail.card_highlight, detail.cardHighlight);
  copyIfMissing('card_badge', detail.card_badge, detail.cardBadge);
  copyIfMissing(
    'image_url',
    detail.image_url,
    detail.image,
    Array.isArray(detail.images) ? detail.images[0] : null,
    Array.isArray(detail.image_urls) ? detail.image_urls[0] : null,
  );
  if (!next.price && detail.price) next.price = detail.price;
  if (!next.currency && detail.currency) next.currency = detail.currency;
  if (!next.shopping_card && detail.shopping_card && typeof detail.shopping_card === 'object') {
    next.shopping_card = detail.shopping_card;
  }
  if (!next.search_card && detail.search_card && typeof detail.search_card === 'object') {
    next.search_card = detail.search_card;
  }
  if (!Array.isArray(next.external_highlight_signals) && Array.isArray(detail.external_highlight_signals)) {
    next.external_highlight_signals = detail.external_highlight_signals;
  }
  return annotateSimilarCardStatus(next);
}

function normalizeSimilarCategoryForDisplay(value) {
  return normalizeSearchTextForMatch(value);
}

function isLooseTokenOverlapSimilarFallback(item = {}) {
  return String(item?.reason || item?.match_reason || '')
    .toLowerCase()
    .includes('l4:external:title_token_overlap');
}

function getSimilarItemDisplayCategory(item = {}) {
  return normalizeSimilarCategoryForDisplay(
    item.category ||
      item.product_type ||
      item.productType ||
      item.card_subtitle ||
      item.shopping_card?.subtitle ||
      item.search_card?.compact_candidate,
  );
}

function filterSimilarProductsWithCardHighlights(items = [], { baseProduct = null, minItems = 4 } = {}) {
  const targetCount = Math.max(1, Number(minItems || 4) || 4);
  const displayable = (Array.isArray(items) ? items : []).filter(
    (item) =>
      item &&
      typeof item === 'object' &&
      hasSimilarCardImage(item) &&
      !isSellerOnlySimilarCardEvidence(item) &&
      !isNonFormulaMerchSimilarCandidateForBeautyBase(item, baseProduct),
  );
  const highlightReady = displayable.filter((item) => hasSimilarCardPresentation(item));
  const candidatePool = highlightReady.length >= targetCount ? highlightReady : displayable;
  const baseCategory = normalizeSimilarCategoryForDisplay(
    baseProduct?.category ||
      baseProduct?.product_type ||
      baseProduct?.productType ||
      baseProduct?.leaf_category ||
      baseProduct?.parent_category,
  );
  if (!baseCategory) return candidatePool;

  const strict = candidatePool.filter((item) => {
    if (!isLooseTokenOverlapSimilarFallback(item)) return true;
    const itemCategory = getSimilarItemDisplayCategory(item);
    return !itemCategory || itemCategory === baseCategory;
  });
  return strict.length >= targetCount ? strict : candidatePool;
}

function attachSimilarCardEnrichmentMetadata(items, metadata = {}) {
  if (!Array.isArray(items)) return items;
  Object.defineProperty(items, '_enrichmentMetadata', {
    value: metadata && typeof metadata === 'object' ? metadata : {},
    enumerable: false,
    configurable: true,
  });
  return items;
}

function getSimilarCardEnrichmentMetadata(items) {
  return items && typeof items._enrichmentMetadata === 'object' && !Array.isArray(items._enrichmentMetadata)
    ? items._enrichmentMetadata
    : {};
}

function countVisibleSimilarSources(items = []) {
  return (Array.isArray(items) ? items : []).reduce(
    (acc, item) => {
      const merchantId = String(item?.merchant_id || item?.merchantId || item?.product?.merchant_id || '').trim();
      const productId = String(item?.product_id || item?.productId || item?.id || item?.product?.product_id || '').trim();
      const source = String(item?.source || item?.retrieval_source || '').trim().toLowerCase();
      if (source === 'external' || source === 'external_seed' || merchantId === EXTERNAL_SEED_MERCHANT_ID || productId.startsWith('ext_')) {
        acc.external += 1;
      } else {
        acc.internal += 1;
      }
      return acc;
    },
    { internal: 0, external: 0 },
  );
}

function isRelationshipGraphSimilarProduct(item = {}) {
  if (!item || typeof item !== 'object' || Array.isArray(item)) return false;
  const source = normalizeSearchTextForMatch(
    firstNonEmptyString(item.source, item.recommendation_source, item.recommendationSource),
  );
  if (source === 'relationship_graph') return true;
  return Boolean(firstNonEmptyString(item.relationship_edge_id, item.relationshipEdgeId));
}

function countRelationshipGraphSimilarProducts(items = []) {
  return (Array.isArray(items) ? items : []).filter((item) => isRelationshipGraphSimilarProduct(item)).length;
}

function toNonNegativeInteger(value) {
  const numeric = Number(value);
  if (!Number.isFinite(numeric)) return 0;
  return Math.max(0, Math.floor(numeric));
}

function hasRelationshipGraphMetadata(metadata = {}) {
  if (!metadata || typeof metadata !== 'object' || Array.isArray(metadata)) return false;
  return (
    metadata.relationship_graph_enabled === true ||
    toNonNegativeInteger(metadata.relationship_graph_edge_count) > 0 ||
    toNonNegativeInteger(metadata.relationship_graph_curated_count) > 0 ||
    toNonNegativeInteger(metadata.relationship_graph_served_count) > 0
  );
}

function calibrateRelationshipGraphMetadataForVisibleProducts({
  metadata = {},
  products = [],
} = {}) {
  if (!hasRelationshipGraphMetadata(metadata)) return {};
  const visibleProducts = Array.isArray(products) ? products : [];
  const rawServedCount = toNonNegativeInteger(metadata.relationship_graph_served_count);
  const visibleServedCount = countRelationshipGraphSimilarProducts(visibleProducts);
  const filteredCount = Math.max(0, rawServedCount - visibleServedCount);
  return {
    relationship_graph_enabled: metadata.relationship_graph_enabled === true,
    relationship_graph_edge_count: toNonNegativeInteger(metadata.relationship_graph_edge_count),
    relationship_graph_curated_count: toNonNegativeInteger(metadata.relationship_graph_curated_count),
    ...(rawServedCount !== visibleServedCount
      ? { relationship_graph_raw_served_count: rawServedCount }
      : {}),
    relationship_graph_served_count: visibleServedCount,
    ...(filteredCount > 0 ? { relationship_graph_filtered_count: filteredCount } : {}),
  };
}

function withoutReasonCode(values = [], reasonCode) {
  return (Array.isArray(values) ? values : [])
    .map((value) => String(value || '').trim())
    .filter((value) => value && value !== reasonCode);
}

function appendReasonCode(values = [], reasonCode) {
  const out = withoutReasonCode(values, '');
  if (reasonCode && !out.includes(reasonCode)) out.push(reasonCode);
  return out;
}

function calibrateSimilarMetadataForVisibleProducts({
  metadata = {},
  products = [],
  requestedLimit = 6,
} = {}) {
  const visibleProducts = Array.isArray(products) ? products : [];
  const safeRequestedLimit = Math.max(1, Math.min(Number(requestedLimit || 6) || 6, 30));
  const visibleUnderfill = Math.max(0, safeRequestedLimit - visibleProducts.length);
  const rawUnderfill =
    Number.isFinite(Number(metadata?.underfill)) ? Math.max(0, Number(metadata.underfill)) : null;
  const rawRetrievalMix =
    metadata?.retrieval_mix && typeof metadata.retrieval_mix === 'object' && !Array.isArray(metadata.retrieval_mix)
      ? metadata.retrieval_mix
      : null;
  const relationshipGraphVisibleMetadata = calibrateRelationshipGraphMetadataForVisibleProducts({
    metadata,
    products: visibleProducts,
  });
  const visibleRetrievalMix = countVisibleSimilarSources(visibleProducts);
  const readyMinVisibleCount = Math.min(safeRequestedLimit, PDP_SIMILAR_READY_MIN_VISIBLE_COUNT);
  const severeUnderfill = visibleProducts.length > 0 && visibleProducts.length < readyMinVisibleCount;
  const nonBlockingUnderfill = visibleProducts.length >= readyMinVisibleCount && visibleUnderfill > 0;
  const originalReasonCodes = Array.isArray(metadata?.low_confidence_reason_codes)
    ? metadata.low_confidence_reason_codes
    : [];
  const nonBlockingReasonCodes = withoutReasonCode(
    withoutReasonCode(originalReasonCodes, 'UNDERFILL_FOR_QUALITY'),
    'UNDERFILL_MAINLINE_RECALL',
  );
  const lowConfidenceReasonCodes =
    severeUnderfill
      ? appendReasonCode(nonBlockingReasonCodes, 'UNDERFILL_FOR_QUALITY')
      : nonBlockingReasonCodes;
  const similarConfidence = String(metadata?.similar_confidence || '').trim() || (visibleProducts.length > 0 ? 'medium' : 'low');
  const lowConfidence = lowConfidenceReasonCodes.length > 0 || similarConfidence === 'low';
  const rawStatus = String(metadata?.similar_status || '').trim();
  const similarStatus =
    visibleProducts.length > 0
      ? severeUnderfill
        ? 'underfilled'
        : 'ready'
      : rawStatus || 'empty';

  return {
    ...metadata,
    ...relationshipGraphVisibleMetadata,
    ...(rawUnderfill != null && rawUnderfill !== visibleUnderfill ? { raw_underfill: rawUnderfill } : {}),
    ...(rawRetrievalMix ? { raw_retrieval_mix: rawRetrievalMix } : {}),
    requested_count: safeRequestedLimit,
    visible_count: visibleProducts.length,
    underfill: visibleUnderfill,
    ready_min_visible_count: readyMinVisibleCount,
    ...(nonBlockingUnderfill ? { underfill_nonblocking: true } : {}),
    low_confidence: lowConfidence,
    low_confidence_reason_codes: lowConfidenceReasonCodes,
    retrieval_mix: visibleRetrievalMix,
    similar_status: similarStatus,
  };
}

const PDP_SIMILAR_ACCESSORY_TITLE_RE =
  /\b(pouch|bag|holder|keychain|keyring|sticker|stickers|soap saver|gua sha|gwalsa|brush|tool|applicator|spatula|mirror|sharpener|headband|puff|sponge|towel|hat|cap|beanie|sachet|trial\s*kit|sample)\b/i;

const PDP_SIMILAR_BEAUTY_BASE_RE =
  /\b(skincare|skin care|haircare|hair care|hair|shampoo|conditioner|cleanser|cleansing|toner|serum|cream|moisturi[sz]er|balm|mask|oil|exfoliant|sunscreen|spf|body wash|lotion|beard|face oil|makeup|cosmetic)\b/i;

const PDP_SIMILAR_NON_FORMULA_MERCH_RE =
  /\b(dad\s+hat|hat|cap|beanie|tee|t-shirt|shirt|hoodie|sweatshirt|tote|bag|pouch|keychain|sticker|stickers|patch|pin|gift card|egift|e-gift)\b/i;

function isNonFormulaMerchSimilarCandidateForBeautyBase(item = {}, baseProduct = null) {
  if (!item || typeof item !== 'object') return false;
  const baseText = [
    baseProduct?.title,
    baseProduct?.name,
    baseProduct?.category,
    baseProduct?.product_type,
    baseProduct?.productType,
    baseProduct?.leaf_category,
    baseProduct?.parent_category,
    baseProduct?.category_path,
    baseProduct?.categoryPath,
  ].filter(Boolean).join(' ');
  if (!PDP_SIMILAR_BEAUTY_BASE_RE.test(baseText)) return false;

  const productFamily = normalizeSearchTextForMatch(
    firstNonEmptyString(item.product_family, item.external_seed_product_family),
  );
  if (['accessory', 'non_merch', 'non_merchandise', 'sample'].includes(productFamily)) return true;

  const itemText = [
    item.title,
    item.name,
    item.category,
    item.product_type,
    item.productType,
    item.card_subtitle,
    item.shopping_card?.subtitle,
    item.search_card?.compact_candidate,
  ].filter(Boolean).join(' ');
  return PDP_SIMILAR_NON_FORMULA_MERCH_RE.test(itemText);
}

function isAccessoryLikePdpForSimilarSuppression(product = {}, pdpSchemaProfile = '') {
  if (isBeautyToolPdpProfile(pdpSchemaProfile)) return true;
  const productFamily = normalizeSearchTextForMatch(
    firstNonEmptyString(product.product_family, product.external_seed_product_family),
  );
  if (productFamily === 'accessory') return true;
  if (productFamily === 'sample') return true;
  const profile = String(pdpSchemaProfile || '').trim();
  const text = [
    product.title,
    product.name,
    product.category,
    product.product_type,
    product.productType,
    product.category_path,
    product.categoryPath,
  ].filter(Boolean).join(' ');
  return profile === 'generic_merch' && PDP_SIMILAR_ACCESSORY_TITLE_RE.test(text);
}

function isExternalSeedPdpProduct(product = {}) {
  const merchantId = String(product?.merchant_id || product?.merchantId || product?.merchant?.id || '').trim();
  const productId = String(product?.product_id || product?.productId || product?.id || '').trim();
  const platformProductId = String(product?.platform_product_id || product?.platformProductId || '').trim();
  return (
    merchantId === EXTERNAL_SEED_MERCHANT_ID ||
    isExternalSeedProductId(productId) ||
    isExternalSeedProductId(platformProductId)
  );
}

function shouldSkipPdpSimilarFetchForAccessory({
  product = {},
  pdpSchemaProfile = '',
} = {}) {
  if (!isExternalSeedPdpProduct(product)) return false;
  const text = [
    product.title,
    product.name,
    product.category,
    product.product_type,
    product.productType,
    product.category_path,
    product.categoryPath,
  ].filter(Boolean).join(' ');
  const sampleLike = /\b(?:sachet|trial\s*kit|sample)\b/i.test(text);
  return sampleLike || isAccessoryLikePdpForSimilarSuppression(product, pdpSchemaProfile);
}

function shouldHideEmptySimilarModuleForPdp({
  product = {},
  pdpSchemaProfile = '',
  relatedProductsEnvelope = null,
  recommendationModuleData = null,
} = {}) {
  if (recommendationModuleData) return false;
  const status = String(
    relatedProductsEnvelope?.metadata?.similar_status ||
      relatedProductsEnvelope?.status ||
      '',
  ).trim();
  if (status !== 'empty') return false;
  return isAccessoryLikePdpForSimilarSuppression(product, pdpSchemaProfile);
}

async function enrichSimilarProductsForPdpCards({
  items = [],
  checkoutToken = null,
  bypassCache = false,
  maxItems = 6,
  budgetMs = PDP_SIMILAR_CARD_ENRICH_BUDGET_MS,
  productIntelBudgetMs = PDP_SIMILAR_CARD_PRODUCT_INTEL_BUDGET_MS,
  detailBudgetMs = PDP_SIMILAR_CARD_DETAIL_BUDGET_MS,
  allowDetailHydration = false,
} = {}) {
  const list = Array.isArray(items) ? items : [];
  let head = list.slice(0, Math.max(0, Number(maxItems) || 0));
  const tail = list.slice(head.length);
  const cardEnrichmentCacheKey = bypassCache || checkoutToken || allowDetailHydration
    ? ''
    : buildSimilarCardEnrichmentCacheKey({
        items: list,
        maxItems,
        allowDetailHydration,
      });
  const cachedCardEnrichment = readSimilarCardEnrichmentCache(cardEnrichmentCacheKey);
  if (cachedCardEnrichment) return cachedCardEnrichment;
  const normalizedProductIntelBudgetMs = Math.max(1, Number(productIntelBudgetMs || 0) || 0);
  const detailHydrationEnabled = isSimilarCardDetailHydrationAllowed({ allowDetailHydration });
  let productIntelCardHydrationMetadata = {
    attempted_count: 0,
    hydrated_count: 0,
    skipped_unreviewed_count: 0,
    failed: false,
    timeout_count: 0,
    budget_ms: normalizedProductIntelBudgetMs,
  };
  try {
    if (typeof hydrateRecommendationItemsWithReviewedProductIntel === 'function') {
      const productIntelCardHydration = await withStageBudget(
        hydrateRecommendationItemsWithReviewedProductIntel(head),
        normalizedProductIntelBudgetMs,
        'pdp_similar_product_intel_card_hydration',
      );
      if (Array.isArray(productIntelCardHydration?.items)) {
        head = productIntelCardHydration.items;
      }
      if (productIntelCardHydration?.stats && typeof productIntelCardHydration.stats === 'object') {
        productIntelCardHydrationMetadata = {
          ...productIntelCardHydration.stats,
          budget_ms: normalizedProductIntelBudgetMs,
          timeout_count: Number(productIntelCardHydration.stats.timeout_count || 0) || 0,
        };
      }
    }
  } catch (err) {
    const timedOut = err?.code === 'STAGE_TIMEOUT';
    productIntelCardHydrationMetadata = {
      ...productIntelCardHydrationMetadata,
      failed: true,
      timeout_count: timedOut
        ? productIntelCardHydrationMetadata.timeout_count + 1
        : productIntelCardHydrationMetadata.timeout_count,
    };
    logger.warn(
      { err: err?.message || String(err), items: head.length },
      'PDP similar product-intel card hydration failed',
    );
  }
  const fallback = [...head.map((item) => annotateSimilarCardStatus(item)), ...tail];
  const normalizedBudgetMs = Math.max(1, Number(budgetMs || 0) || 0);
  const normalizedDetailBudgetMs = Math.max(
    1,
    Math.min(normalizedBudgetMs, Number(detailBudgetMs || 0) || normalizedBudgetMs),
  );
  const normalizedOfficialSeedBudgetMs = Math.max(
    normalizedDetailBudgetMs,
    Math.min(
      normalizedBudgetMs,
      parseTimeoutMs(process.env.PDP_SIMILAR_CARD_OFFICIAL_SEED_BUDGET_MS, normalizedBudgetMs),
    ),
  );
  const officialSeedHydrationCandidates = head.filter((item) => shouldHydrateSimilarCardFromOfficialSeed(item));
  const officialSeedHydrationProductIds = officialSeedHydrationCandidates
    .map((item) => collectExternalSeedIdCandidatesForVisibleCatalogHydration(item)[0])
    .filter(Boolean);
  const metadata = {
    card_enrichment_budget_ms: normalizedBudgetMs,
    card_enrichment_detail_budget_ms: normalizedDetailBudgetMs,
    card_enrichment_official_seed_budget_ms: normalizedOfficialSeedBudgetMs,
    card_enrichment_attempted_count: 0,
    card_enrichment_official_seed_attempted_count: 0,
    card_enrichment_official_seed_hit_count: 0,
    card_enrichment_official_seed_timeout_count: 0,
    card_enrichment_official_seed_failed_count: 0,
    card_enrichment_timeout_count: 0,
    card_enrichment_failed_count: 0,
    card_enrichment_detail_hydration_enabled: detailHydrationEnabled,
    card_enrichment_detail_hydration_skipped_count: detailHydrationEnabled
      ? 0
      : head.filter((item) => item && typeof item === 'object' && !hasSimilarCardImage(item)).length,
    card_enrichment_status: 'ready',
    product_intel_card_hydration: productIntelCardHydrationMetadata,
  };
  let officialSeedCardSourcesById = new Map();
  if (officialSeedHydrationProductIds.length > 0) {
    metadata.card_enrichment_official_seed_attempted_count = officialSeedHydrationCandidates.length;
    officialSeedCardSourcesById = await withStageBudget(
      fetchExternalSeedSimilarCardSourcesFromDb(officialSeedHydrationProductIds),
      normalizedOfficialSeedBudgetMs,
      'pdp_similar_card_official_seed_sources',
    ).catch((err) => {
      if (err?.code === 'STAGE_TIMEOUT') {
        metadata.card_enrichment_official_seed_timeout_count += officialSeedHydrationCandidates.length;
      } else {
        metadata.card_enrichment_official_seed_failed_count += officialSeedHydrationCandidates.length;
      }
      return new Map();
    });
  }
  if (
    officialSeedHydrationCandidates.length <= 0 &&
    !head.some((item) => shouldEnrichSimilarCard(item, { allowDetailHydration }))
  ) {
    return finishSimilarCardEnrichmentResult(fallback, metadata, cardEnrichmentCacheKey);
  }

  const enrichmentTask = Promise.all(
    head.map(async (item) => {
      if (!item || typeof item !== 'object') return item;
      if (shouldHydrateSimilarCardFromOfficialSeed(item)) {
        const externalSeedId = collectExternalSeedIdCandidatesForVisibleCatalogHydration(item)[0];
        if (externalSeedId) {
          const officialSeedProduct = officialSeedCardSourcesById.get(externalSeedId);
          if (officialSeedProduct) {
            const alreadyHasTrustedPresentation =
              hasSimilarCardPresentation(item) && !isSellerOnlySimilarCardEvidence(item);
            const officialSeedEnriched = mergeSimilarCardEnrichment(
              alreadyHasTrustedPresentation
                ? item
                : applyOfficialSeedSimilarCardEnrichment(item, officialSeedProduct),
              officialSeedProduct,
            );
            if (officialSeedEnriched !== item && hasSimilarCardPresentation(officialSeedEnriched)) {
              metadata.card_enrichment_official_seed_hit_count += 1;
              return annotateSimilarCardStatus(officialSeedEnriched);
            }
            if (officialSeedEnriched !== item && hasSimilarCardImage(officialSeedEnriched)) {
              return annotateSimilarCardStatus(officialSeedEnriched);
            }
          }
        }
      }
      if (!shouldEnrichSimilarCard(item, { allowDetailHydration })) {
        return annotateSimilarCardStatus(item);
      }
      const merchantId = String(item.merchant_id || item.merchant?.id || item.merchant_uuid || '').trim();
      const productId = String(item.product_id || item.productId || item.id || '').trim();
      if (!merchantId || !productId) {
        return annotateSimilarCardStatus(item);
      }
      metadata.card_enrichment_attempted_count += 1;
      const detail = await withStageBudget(
        fetchProductDetailForOffers({
          merchantId,
          productId,
          checkoutToken,
          bypassCache,
          skipUpstreamFallback: true,
          totalTimeoutMs: normalizedDetailBudgetMs,
          noRetry: true,
        }),
        normalizedDetailBudgetMs,
        'pdp_similar_card_detail',
      ).catch((err) => {
        if (err?.code === 'STAGE_TIMEOUT') {
          metadata.card_enrichment_timeout_count += 1;
        } else {
          metadata.card_enrichment_failed_count += 1;
        }
        return null;
      });
      if (!detail || typeof detail !== 'object') {
        return annotateSimilarCardStatus(item);
      }
      return mergeSimilarCardEnrichment(item, detail);
    }),
  );
  const enriched = await withStageBudget(
    enrichmentTask,
    budgetMs,
    'pdp_similar_card_enrichment',
  ).catch((err) => {
    if (err?.code === 'STAGE_TIMEOUT') {
      logger.warn(
        {
          timeout_ms: Math.max(1, Number(budgetMs || 0) || 0),
          items: head.length,
        },
        'PDP similar card enrichment budget exceeded',
      );
      metadata.card_enrichment_timeout_count += Math.max(1, head.length);
      return fallback.slice(0, head.length);
    }
    throw err;
  });
  const result = [...enriched, ...tail];
  if (
    metadata.card_enrichment_timeout_count > 0 ||
    metadata.card_enrichment_official_seed_timeout_count > 0
  ) {
    metadata.card_enrichment_status = 'budget_exceeded';
  } else if (
    metadata.card_enrichment_failed_count > 0 ||
    metadata.card_enrichment_official_seed_failed_count > 0 ||
    result.some((item) => String(item?.card_image_status || '').trim() === 'image_missing')
  ) {
    metadata.card_enrichment_status = 'partial';
  }
  return finishSimilarCardEnrichmentResult(result, metadata, cardEnrichmentCacheKey);
}

function collectExternalSeedIdCandidatesForVisibleCatalogHydration(product = {}) {
  if (!product || typeof product !== 'object' || Array.isArray(product)) return [];
  const values = [
    product.product_id,
    product.productId,
    product.id,
    product.source_product_id,
    product.sourceProductId,
    product.external_product_id,
    product.externalProductId,
    product.external_seed_product_id,
    product.externalSeedProductId,
    product.platform_product_id,
    product.platformProductId,
  ].map((value) => firstNonEmptyString(value));
  // Prefer real ext_* source ids. When both an ext_* and a sig_* are present, drop
  // the sig_* (asserted by similar_visible_sig_ids.test.js). But a visible card may
  // carry ONLY a sig_* (no ext_*) — the official-seed hydration resolves that via
  // matched_signature_product_id, so fall back to the sig_* when it's the only id
  // available (find_similar_products_mainline_wrapper.test.js). pg_* is never a
  // hydration key, so it is excluded in both passes.
  const extIds = Array.from(new Set(values.filter((value) => isExternalSeedProductId(value))));
  if (extIds.length) return extIds;
  return Array.from(new Set(values.filter((value) => isPivotaSignatureProductId(value))));
}

function identityReviewRequiredForVisibleSig(product = {}) {
  return (
    product.review_required === true ||
    product.identity_review_required === true ||
    product.pdp_identity_review_required === true ||
    product.identity?.review_required === true
  );
}

function visibleApprovedGroupSigId(product = {}) {
  const sigId = firstNonEmptyString(product.sellable_item_group_id, product.product_group_id);
  if (!isPivotaSignatureProductId(sigId)) return null;

  const identityStatus = String(
    firstNonEmptyString(
      product.identity_status,
      product.pdp_identity_status,
      product.identity?.identity_status,
    ) || '',
  ).toLowerCase();
  if (identityStatus !== 'approved') return null;
  if (identityReviewRequiredForVisibleSig(product)) return null;

  const liveReadValue = firstNonEmptyString(
    product.live_read_enabled,
    product.identity_live_read_enabled,
    product.pdp_identity_live_read_enabled,
    product.identity?.live_read_enabled,
  );
  if (liveReadValue === false || String(liveReadValue).toLowerCase() === 'false') return null;
  return sigId;
}

function resolveVisibleSimilarProductSigId(product = {}) {
  const signatureFieldSigId = firstNonEmptyString(product.pivota_signature_id, product.signature_id);
  if (isPivotaSignatureProductId(signatureFieldSigId)) return signatureFieldSigId;

  const visibleIdSigId = firstNonEmptyString(product.product_id, product.productId, product.id);
  if (isPivotaSignatureProductId(visibleIdSigId) && !identityReviewRequiredForVisibleSig(product)) {
    return visibleIdSigId;
  }
  return visibleApprovedGroupSigId(product);
}

function promoteVisibleSimilarProductSigId(product) {
  if (!product || typeof product !== 'object' || Array.isArray(product)) return product;
  const sigId = resolveVisibleSimilarProductSigId(product);
  if (!isPivotaSignatureProductId(sigId)) return product;

  const currentProductId = firstNonEmptyString(product.product_id, product.productId, product.id);
  const canonicalEntityId = firstNonEmptyString(product.canonical_entity_id, product.canonicalEntityId);
  const publicId = resolvePublicProductIdForEmit(
    sigId,
    canonicalEntityId,
  );
  const publicUrl = buildPublicProductUrl(publicId);
  const pivotaCanonicalUrl =
    CANONICAL_ENTITY_ID_PUBLIC_EMIT_ENABLED && canonicalEntityId
      ? publicUrl
      : product.pivota_canonical_url || publicUrl;
  const currentCanonicalUrl = firstNonEmptyString(product.canonical_url, product.url);
  const merchantCanonicalUrl = firstNonEmptyString(
    product.merchant_canonical_url,
    product.destination_url,
    currentCanonicalUrl && !/\/products\/sig_/i.test(currentCanonicalUrl) ? currentCanonicalUrl : '',
  );
  const sourceProductId = firstNonEmptyString(
    product.source_product_id,
    product.external_product_id,
    product.external_seed_product_id,
    product.platform_product_id,
    ...collectExternalSeedIdCandidatesForVisibleCatalogHydration(product),
    currentProductId,
  );
  if (currentProductId === sigId) {
    return {
      ...product,
      product_id: publicId,
      id: publicId,
      pivota_signature_id: product.pivota_signature_id || sigId,
      signature_id: product.signature_id || sigId,
      pivota_canonical_url: pivotaCanonicalUrl,
      canonical_url: publicUrl,
      url: publicUrl,
      ...(merchantCanonicalUrl ? { merchant_canonical_url: merchantCanonicalUrl } : {}),
      ...(isExternalSeedProductId(sourceProductId)
        ? {
            source_product_id: product.source_product_id || sourceProductId,
            external_product_id: product.external_product_id || sourceProductId,
          }
        : {}),
    };
  }

  return {
    ...product,
    product_id: publicId,
    id: publicId,
    pivota_signature_id: product.pivota_signature_id || sigId,
    signature_id: product.signature_id || sigId,
    pivota_canonical_url: pivotaCanonicalUrl,
    canonical_url: publicUrl,
    url: publicUrl,
    ...(merchantCanonicalUrl ? { merchant_canonical_url: merchantCanonicalUrl } : {}),
    ...(sourceProductId ? { source_product_id: product.source_product_id || sourceProductId } : {}),
    ...(isExternalSeedProductId(sourceProductId)
      ? { external_product_id: product.external_product_id || sourceProductId }
      : {}),
    platform_product_id: product.platform_product_id || sourceProductId || currentProductId || sigId,
  };
}

function promoteVisibleSimilarProductSigIds(products) {
  return Array.isArray(products) ? products.map((product) => promoteVisibleSimilarProductSigId(product)) : [];
}

function shouldHydrateVisibleSimilarProductFromCatalog(product = {}) {
  const sigId = resolveVisibleSimilarProductSigId(product);
  if (!isPivotaSignatureProductId(sigId)) return true;
  if (isSellerOnlySimilarCardEvidence(product)) return true;
  return !hasSimilarCardPresentation(product) || !hasSimilarCardImage(product);
}

function deriveCatalogSimilarCardHighlight({
  description = '',
  category = '',
  productType = '',
  title = '',
} = {}) {
  const descriptionText = String(description || '').replace(/\s+/g, ' ').trim();
  if (descriptionText) {
    const firstSentence = descriptionText
      .split(/(?<=[.!?])\s+/)
      .map((part) => normalizeSimilarCardFallbackText(part, { maxChars: 84 }))
      .find((part) => part.length >= 12);
    if (firstSentence) return firstSentence;
  }
  return normalizeSimilarCardFallbackText(productType || category || title, { maxChars: 72 });
}

function buildSimilarCatalogProductProjection(product = {}, catalogRow = {}) {
  if (!product || typeof product !== 'object' || Array.isArray(product)) return product;
  if (!catalogRow || typeof catalogRow !== 'object' || Array.isArray(catalogRow)) return product;

  const sigId = firstNonEmptyString(catalogRow.pivota_signature_id, product.pivota_signature_id, product.signature_id);
  if (!isPivotaSignatureProductId(sigId)) return product;

  const catalogPayload = parseCanonicalCatalogPayload(catalogRow.product_payload);
  const seedData = isPlainObject(catalogPayload.seed_data) ? catalogPayload.seed_data : {};
  const snapshot = isPlainObject(seedData.snapshot) ? seedData.snapshot : {};
  const sourceProductId = firstNonEmptyString(
    catalogRow.source_product_id,
    product.source_product_id,
    product.external_product_id,
    product.external_seed_product_id,
    product.platform_product_id,
  );
  const destinationUrl = firstNonEmptyString(
    product.destination_url,
    catalogRow.destination_url,
    catalogPayload.destination_url,
    seedData.destination_url,
    snapshot.destination_url,
    product.canonical_url,
    product.url,
  );
  const publicId = resolvePublicProductIdForEmit(
    sigId,
    firstNonEmptyString(catalogRow.canonical_entity_id, product.canonical_entity_id, product.canonicalEntityId),
  );
  const publicUrl = buildPublicProductUrl(publicId);
  const title = firstNonEmptyString(catalogRow.title, catalogPayload.title, product.title, product.name);
  const description = firstNonEmptyString(
    catalogRow.description,
    catalogPayload.description,
    catalogPayload.summary,
    seedData.description,
    seedData.summary,
    seedData.pdp_description_raw,
    snapshot.description,
    snapshot.summary,
    snapshot.pdp_description_raw,
    product.description,
  );
  const categoryPath = firstNonEmptyString(
    catalogRow.category_path,
    catalogPayload.category_path,
    catalogPayload.catalog_category_path,
    seedData.category_path,
    seedData.catalog_category_path,
    product.catalog_category_path,
    product.category_path,
  );
  const category = firstNonEmptyString(catalogRow.category, catalogPayload.category, product.category, product.product_type);
  const productType = firstNonEmptyString(catalogRow.product_type, catalogPayload.product_type, catalogPayload.productType, product.product_type, category);
  const imageUrl = firstNonEmptyString(
    catalogRow.image_url,
    catalogPayload.image_url,
    Array.isArray(catalogPayload.images) ? catalogPayload.images[0] : null,
    seedData.image_url,
    Array.isArray(seedData.images) ? seedData.images[0] : null,
    snapshot.image_url,
    Array.isArray(snapshot.images) ? snapshot.images[0] : null,
    product.image_url,
    product.image,
  );
  const merchantId = firstNonEmptyString(catalogRow.merchant_id, product.merchant_id, EXTERNAL_SEED_MERCHANT_ID);
  const platform = firstNonEmptyString(catalogRow.platform, product.platform, EXTERNAL_SEED_MERCHANT_ID);
  const productKey = firstNonEmptyString(catalogRow.product_key, product.product_key);
  const catalogProductRef = {
    product_id: publicId,
    id: publicId,
    pivota_signature_id: sigId,
    source: 'catalog_products',
    entity_source: 'catalog_products',
    product_identity_source: 'catalog_products',
  };
  const cardHighlight = deriveCatalogSimilarCardHighlight({
    description,
    category,
    productType,
    title,
  });
  const cardSource = 'catalog_product';
  const {
    external_product_id: _externalProductId,
    externalProductId: _externalProductIdCamel,
    external_seed_product_id: _externalSeedProductId,
    externalSeedProductId: _externalSeedProductIdCamel,
    source_product_id: _sourceProductId,
    sourceProductId: _sourceProductIdCamel,
    platform_product_id: _platformProductId,
    platformProductId: _platformProductIdCamel,
    merchant_id: _merchantId,
    merchantId: _merchantIdCamel,
    platform: _platform,
    source_kind: _sourceKind,
    sourceKind: _sourceKindCamel,
    canonical_product_ref: _canonicalProductRef,
    canonicalProductRef: _canonicalProductRefCamel,
    product_ref: _productRef,
    productRef: _productRefCamel,
    product_intel: rawProductIntel,
    ...catalogProductBase
  } = product;
  const sourceProvenance = sourceProductId
    ? {
        kind: 'external_seed',
        merchant_id: merchantId,
        platform,
        external_product_id: sourceProductId,
        ...(productKey ? { catalog_product_key: productKey } : {}),
      }
    : null;
  const productIntel = isPlainObject(rawProductIntel)
    ? {
        ...rawProductIntel,
        canonical_product_ref: catalogProductRef,
        source_provenance: sourceProvenance || rawProductIntel.source_provenance,
      }
    : rawProductIntel;

  return {
    ...catalogProductBase,
    product_id: publicId,
    id: publicId,
    pivota_signature_id: sigId,
    signature_id: sigId,
    source: 'catalog_products',
    entity_source: 'catalog_products',
    product_identity_source: 'catalog_products',
    product_ref: catalogProductRef,
    canonical_product_ref: catalogProductRef,
    ...(productIntel ? { product_intel: productIntel } : {}),
    ...(sourceProvenance ? { source_provenance: sourceProvenance } : {}),
    ...(title ? { title, name: title } : {}),
    ...(description ? { description } : {}),
    ...(category ? { category } : {}),
    ...(productType ? { product_type: productType } : {}),
    ...(categoryPath ? { category_path: categoryPath, catalog_category_path: categoryPath } : {}),
    ...(cardHighlight
      ? {
          card_title: title,
          card_subtitle: productType || category,
          card_highlight: cardHighlight,
          card_highlight_source: cardSource,
          shopping_card: {
            ...(isPlainObject(product.shopping_card) ? product.shopping_card : {}),
            title,
            subtitle: productType || category,
            highlight: cardHighlight,
            evidence_profile: cardSource,
            highlight_source: cardSource,
          },
          search_card: {
            ...(isPlainObject(product.search_card) ? product.search_card : {}),
            title_candidate: title,
            compact_candidate: productType || category,
            highlight_candidate: cardHighlight,
            evidence_profile: cardSource,
            highlight_source: cardSource,
          },
        }
      : {}),
    ...(imageUrl ? { image_url: imageUrl, image: imageUrl } : {}),
    canonical_url: publicUrl,
    pivota_canonical_url: publicUrl,
    url: publicUrl,
    ...(destinationUrl ? { destination_url: destinationUrl, merchant_canonical_url: destinationUrl } : {}),
  };
}

async function hydrateVisibleSimilarProductSigIdsFromCatalog(products, options = {}) {
  const promoted = promoteVisibleSimilarProductSigIds(products);
  if (!process.env.DATABASE_URL || !promoted.length) return promoted;
  const cacheKey = options?.bypassCache ? '' : buildVisibleSimilarSigHydrationCacheKey(promoted);
  const cached = readVisibleSimilarSigHydrationCache(cacheKey);
  if (cached) return cached;
  const productsRequiringCatalogHydration = promoted.filter((product) =>
    shouldHydrateVisibleSimilarProductFromCatalog(product),
  );

  const unresolvedExternalIds = Array.from(
    new Set(
      productsRequiringCatalogHydration
        .flatMap((product) => collectExternalSeedIdCandidatesForVisibleCatalogHydration(product))
        .filter((productId) => isExternalSeedProductId(productId)),
    ),
  );
  if (!unresolvedExternalIds.length) {
    writeVisibleSimilarSigHydrationCache(cacheKey, promoted);
    return promoted;
  }

  const catalogBySourceProductId = new Map();
  const sigBySourceProductId = new Map();
  try {
    const result = await query(
      `
        SELECT
          merchant_id,
          platform,
          source_product_id,
          product_key,
          pivota_signature_id,
          title,
          description,
          brand,
          category,
          product_type,
          category_path,
          image_url,
          canonical_url,
          product_payload
        FROM catalog_products
        WHERE merchant_id = $1
          AND platform = $1
          AND source_product_id = ANY($2::text[])
          AND pivota_signature_id LIKE 'sig\\_%' ESCAPE '\\'
        ORDER BY
          CASE WHEN sync_status = 'live' THEN 0 ELSE 1 END,
          updated_at DESC NULLS LAST,
          product_key ASC
      `,
      [EXTERNAL_SEED_MERCHANT_ID, unresolvedExternalIds],
    );
    for (const row of result?.rows || []) {
      const sourceProductId = firstNonEmptyString(row.source_product_id);
      const sigId = firstNonEmptyString(row.pivota_signature_id);
      if (sourceProductId && /^sig[_:]/i.test(sigId)) {
        sigBySourceProductId.set(sourceProductId, sigId);
        if (!catalogBySourceProductId.has(sourceProductId)) {
          catalogBySourceProductId.set(sourceProductId, row);
        }
      }
    }
  } catch (err) {
    logger.warn(
      {
        err: err?.message || String(err),
        count: unresolvedExternalIds.length,
      },
      'similar visible sig id catalog hydration failed',
    );
  }

  const identityFallbackIds = unresolvedExternalIds.filter((productId) => !sigBySourceProductId.has(productId));
  if (identityFallbackIds.length > 0) {
    try {
      const identityResult = await query(
        `
          SELECT pil.product_id, pil.sellable_item_group_id
          FROM pdp_identity_listing pil
          JOIN external_product_seeds eps
            ON eps.external_product_id = pil.product_id
           AND eps.status = 'active'
          WHERE pil.source_listing_ref = ANY($1::text[])
            AND pil.source_kind = 'external_seed'
            AND NULLIF(pil.sellable_item_group_id, '') IS NOT NULL
            AND pil.identity_status = 'approved'
            AND pil.live_read_enabled IS TRUE
            AND COALESCE(pil.review_required, false) IS NOT TRUE
        `,
        [identityFallbackIds.map((productId) => `external_seed:${productId}`)],
      );
      for (const row of identityResult?.rows || []) {
        const sourceProductId = firstNonEmptyString(row.product_id);
        const sigId = firstNonEmptyString(row.sellable_item_group_id);
        if (sourceProductId && /^sig[_:]/i.test(sigId)) {
          sigBySourceProductId.set(sourceProductId, sigId);
        }
      }
    } catch (err) {
      logger.warn(
        {
          err: err?.message || String(err),
          count: identityFallbackIds.length,
        },
        'similar visible sig id identity fallback failed',
      );
    }
  }

  if (!sigBySourceProductId.size) {
    writeVisibleSimilarSigHydrationCache(cacheKey, promoted);
    return promoted;
  }
  try {
    const hydrated = promoted.map((product) => {
      const externalSeedIds = collectExternalSeedIdCandidatesForVisibleCatalogHydration(product);
      const catalogRow = externalSeedIds
        .map((productId) => catalogBySourceProductId.get(productId))
        .find((candidate) => candidate && typeof candidate === 'object');
      if (catalogRow) {
        return buildSimilarCatalogProductProjection(product, catalogRow);
      }
      const sigId = externalSeedIds
        .map((productId) => sigBySourceProductId.get(productId))
        .find((candidate) => isPivotaSignatureProductId(candidate));
      return sigId
        ? promoteVisibleSimilarProductSigId({
            ...product,
            pivota_signature_id: product.pivota_signature_id || sigId,
          })
        : product;
    });
    writeVisibleSimilarSigHydrationCache(cacheKey, hydrated);
    return hydrated;
  } catch (err) {
    logger.warn(
      {
        err: err?.message || String(err),
        count: unresolvedExternalIds.length,
      },
      'similar visible sig id promotion failed',
    );
    return promoted;
  }
}

function filterPublicVisibleSimilarProducts(products) {
  return (Array.isArray(products) ? products : []).filter((product) => {
    if (!product || typeof product !== 'object' || Array.isArray(product)) return false;
    if (isSellerOnlySimilarCardEvidence(product)) return false;
    const externalSeedIds = collectExternalSeedIdCandidatesForVisibleCatalogHydration(product);
    if (!externalSeedIds.length) return true;
    const visibleSigId = resolveVisibleSimilarProductSigId(product);
    return isPivotaSignatureProductId(visibleSigId);
  });
}

function dedupeSimilarCandidatesByMerchantProductId(products) {
  const out = [];
  const seen = new Set();
  for (const item of Array.isArray(products) ? products : []) {
    if (!item || typeof item !== 'object' || Array.isArray(item)) continue;
    const merchantId = firstNonEmptyString(item.merchant_id, item.merchantId) || EXTERNAL_SEED_MERCHANT_ID;
    const productId = firstNonEmptyString(
      item.product_id,
      item.productId,
      item.id,
      item.external_product_id,
      item.externalProductId,
    );
    if (!productId) continue;
    const key = `${merchantId}::${productId}`;
    if (seen.has(key)) continue;
    seen.add(key);
    out.push(item);
  }
  return out;
}

function shapeItemForFamilyKey(item = {}) {
  const title = item?.title || item?.name;
  return {
    name: title,
    title,
    brand: item?.brand || item?.vendor,
    category: item?.category,
    product_type: item?.product_type,
    product_family_id: item?.product_family_id,
    variant_title: item?.variant_title,
    variant_detail_label: item?.variant_detail_label,
    product_ref: item?.product_id || item?.external_product_id,
  };
}

function resolveSimilarFamilyBucketKey(familyBuckets, familyKey) {
  for (const bucket of familyBuckets) {
    const keys = Array.isArray(bucket?.keys) ? bucket.keys : [];
    if (
      keys.some((bucketKey) => familyIdentityKeysCompatible(bucketKey, familyKey)) &&
      keys.every((bucketKey) => familyIdentityKeysCompatible(bucketKey, familyKey))
    ) {
      keys.push(familyKey);
      return bucket.key;
    }
  }
  familyBuckets.push({ key: familyKey, keys: [familyKey] });
  return familyKey;
}

function dedupeSimilarCandidatesByFamily(products, { anchorFamilyKey = '', resolutionMap = null } = {}) {
  const out = [];
  const seen = new Set();
  const familyBuckets = [];
  for (const item of Array.isArray(products) ? products : []) {
    if (!item || typeof item !== 'object' || Array.isArray(item)) continue;
    const resolutionRef = getSimilarFamilyItemResolutionRef(item);
    const resolved =
      resolutionMap && resolutionRef && typeof resolutionMap.get === 'function'
        ? resolutionMap.get(resolutionRef)
        : null;
    const resolvedKey = resolvedSimilarFamilyKey(resolved);
    const titleKey = familyIdentityKey(shapeItemForFamilyKey(item));
    const familyKey = resolvedKey || titleKey;
    const isDerivedFamily = String(familyKey || '').startsWith('family:');
    let key = '';

    if (isDerivedFamily) {
      if (anchorFamilyKey && familyIdentityKeysCompatible(familyKey, anchorFamilyKey)) continue;
      key = `family::${resolveSimilarFamilyBucketKey(familyBuckets, familyKey)}`;
    } else {
      const merchantId = firstNonEmptyString(item.merchant_id, item.merchantId) || EXTERNAL_SEED_MERCHANT_ID;
      const productId = firstNonEmptyString(
        item.product_id,
        item.productId,
        item.id,
        item.external_product_id,
        item.externalProductId,
      );
      if (!productId) continue;
      key = `merchant_product::${merchantId}::${productId}`;
    }

    if (seen.has(key)) continue;
    seen.add(key);
    out.push(item);
  }
  return out;
}

function isBundleOrSetPdpForComponentScopedSimilar(product = {}) {
  const seedData =
    product?.seed_data && typeof product.seed_data === 'object' && !Array.isArray(product.seed_data)
      ? product.seed_data
      : {};
  const snapshot =
    seedData.snapshot && typeof seedData.snapshot === 'object' && !Array.isArray(seedData.snapshot)
      ? seedData.snapshot
      : {};
  const productKind =
    product?.product_kind && typeof product.product_kind === 'object' && !Array.isArray(product.product_kind)
      ? product.product_kind
      : {};
  const family = normalizeSearchTextForMatch(
    firstNonEmptyString(
      product.product_family,
      product.external_seed_product_family,
      productKind.family,
      seedData.product_family,
      snapshot.product_family,
    ),
  );
  if (['bundle', 'set', 'gift_set', 'kit', 'routine_set'].includes(family)) return true;
  const text = [
    product.title,
    product.name,
    product.category,
    product.product_type,
    product.productType,
    product.category_path,
    product.categoryPath,
    seedData.title,
    seedData.product_type,
    snapshot.title,
    snapshot.product_type,
  ]
    .filter(Boolean)
    .join(' ');
  return /\b(set|bundle|kit|duo|trio|routine|regimen|gift\s*set|minis?)\b/i.test(text);
}

function collectPdpComponentExternalSeedIds(componentCandidates = []) {
  return new Set(
    (Array.isArray(componentCandidates) ? componentCandidates : [])
      .flatMap((item) => collectExternalSeedIdCandidatesForVisibleCatalogHydration(item))
      .filter((value) => isExternalSeedProductId(value)),
  );
}

function excludeBundleComponentProductsFromSimilar({
  products = [],
  componentCandidates = [],
} = {}) {
  const list = Array.isArray(products) ? products : [];
  if (!Array.isArray(componentCandidates) || componentCandidates.length <= 0) {
    return { products: list, applied: false, dropped_count: 0 };
  }
  const componentIds = collectPdpComponentExternalSeedIds(componentCandidates);
  if (componentIds.size <= 0) {
    return { products: list, applied: false, dropped_count: 0 };
  }
  const filtered = list.filter((item) => {
    if (!item || typeof item !== 'object' || Array.isArray(item)) return false;
    if (String(item.retrieval_source || '').trim() === 'reviewed_component_ref') return false;
    const ids = collectExternalSeedIdCandidatesForVisibleCatalogHydration(item);
    return !ids.some((id) => componentIds.has(id));
  });
  return {
    products: filtered,
    applied: true,
    dropped_count: Math.max(0, list.length - filtered.length),
  };
}

function scopeBundleSimilarToReviewedComponents(args = {}) {
  return excludeBundleComponentProductsFromSimilar(args);
}

function collectPdpComponentSimilarCandidates(product = {}) {
  const seedData =
    product?.seed_data && typeof product.seed_data === 'object' && !Array.isArray(product.seed_data)
      ? product.seed_data
      : {};
  const snapshot =
    seedData.snapshot && typeof seedData.snapshot === 'object' && !Array.isArray(seedData.snapshot)
      ? seedData.snapshot
      : {};
  const baseExternalId = firstNonEmptyString(
    product.external_product_id,
    product.external_seed_product_id,
    product.source_product_id,
    product.platform_product_id,
    product.product_id,
    product.id,
  );
  const refs = [
    ...(Array.isArray(seedData.bundle_component_refs) ? seedData.bundle_component_refs : []),
    ...(Array.isArray(seedData.component_product_refs) ? seedData.component_product_refs : []),
    ...(Array.isArray(snapshot.bundle_component_refs) ? snapshot.bundle_component_refs : []),
    ...(Array.isArray(snapshot.component_product_refs) ? snapshot.component_product_refs : []),
  ];
  const out = [];
  const seen = new Set();
  for (const ref of refs) {
    if (!ref || typeof ref !== 'object' || Array.isArray(ref)) continue;
    const reviewState = String(ref.review_state || ref.reviewStatus || '').trim().toLowerCase();
    if (!['reviewed', 'approved', 'verified'].includes(reviewState)) continue;
    const externalProductId = firstNonEmptyString(
      ref.external_product_id,
      ref.externalProductId,
      ref.product_id,
      ref.productId,
      ref.platform_product_id,
      ref.platformProductId,
    );
    if (!isExternalSeedProductId(externalProductId)) continue;
    if (baseExternalId && externalProductId === baseExternalId) continue;
    if (seen.has(externalProductId)) continue;
    seen.add(externalProductId);
    const publicProductId = resolvePublicProductIdForEmit(
      externalProductId,
      firstNonEmptyString(ref.canonical_entity_id, ref.canonicalEntityId),
    );
    out.push({
      merchant_id: EXTERNAL_SEED_MERCHANT_ID,
      product_id: publicProductId,
      external_product_id: externalProductId,
      platform_product_id: externalProductId,
      source: 'external_seed',
      retrieval_source: 'reviewed_component_ref',
      reason: 'component_ref:reviewed_bundle_component',
      title: firstNonEmptyString(ref.title, ref.name),
      category: firstNonEmptyString(ref.component_role, ref.role, ref.category),
      product_type: firstNonEmptyString(ref.component_role, ref.role, ref.product_type),
      canonical_url: firstNonEmptyString(ref.canonical_url, ref.destination_url, ref.url),
      destination_url: firstNonEmptyString(ref.destination_url, ref.canonical_url, ref.url),
      card_badge: 'Included item',
      component_role: firstNonEmptyString(ref.component_role, ref.role),
      component_source_kind: firstNonEmptyString(ref.source_kind, ref.sourceKind),
    });
  }
  return out;
}

async function prewarmPdpSimilarForProduct({
  payload = {},
  canonicalProductForPdp = {},
  canonicalProductRef = {},
  canonicalProduct = {},
  checkoutToken = null,
  bypassCache = false,
} = {}) {
  if (bypassCache) return;
  const componentCandidates = collectPdpComponentSimilarCandidates(canonicalProductForPdp);
  const { candidateLimit, fetchArgs } = buildPdpSimilarFetchArgs({
    payload,
    canonicalProductForPdp,
    canonicalProductRef,
    canonicalProduct,
    bypassCache: false,
    debug: false,
    excludeItems: componentCandidates,
    requestMode: 'background',
  });
  const relatedProductsEnvelope = await fetchSimilarProductsDeduped(fetchArgs);
  const relatedProducts = Array.isArray(relatedProductsEnvelope?.items)
    ? relatedProductsEnvelope.items
    : [];
  if (!relatedProducts.length) return;
  await enrichSimilarProductsForPdpCards({
    items: relatedProducts,
    checkoutToken,
    bypassCache: false,
    maxItems: resolvePdpSimilarCardEnrichmentLimit(resolvePdpSimilarDisplayLimit(payload), candidateLimit),
  });
}

function extractUpstreamErrorCode(err) {
  const data = err && err.response ? err.response.data : null;

  function looksLikeErrorCode(v) {
    if (typeof v !== 'string') return false;
    const s = v.trim();
    if (!s || s.length > 80) return false;
    return /^[A-Z][A-Z0-9_]+$/.test(s);
  }

  // Preferred shape: Pivota unified error envelope
  // {
  //   status: "error",
  //   error: { code, message, details: { error, message, ... } }
  // }
  if (data && typeof data === 'object') {
    const pivotaErr = data.error && typeof data.error === 'object' ? data.error : null;
    if (pivotaErr) {
      const details =
        pivotaErr.details && typeof pivotaErr.details === 'object' ? pivotaErr.details : null;
      const underlying =
        details && typeof details.error === 'string' && looksLikeErrorCode(details.error)
          ? details.error
          : typeof pivotaErr.message === 'string' && looksLikeErrorCode(pivotaErr.message)
            ? pivotaErr.message
            : typeof pivotaErr.code === 'string' && looksLikeErrorCode(pivotaErr.code)
              ? pivotaErr.code
              : null;
      const msg =
        (details && typeof details.message === 'string' && details.message) ||
        (typeof pivotaErr.message === 'string' && !looksLikeErrorCode(pivotaErr.message)
          ? pivotaErr.message
          : '') ||
        (typeof pivotaErr.code === 'string' && !looksLikeErrorCode(pivotaErr.code) ? pivotaErr.code : '') ||
        (err && err.message ? err.message : '');
      return { code: underlying, message: msg, data, detail: details || pivotaErr };
    }
  }

  // Fallbacks: FastAPI default shapes or legacy gateway errors
  const detail = data && typeof data === 'object' ? (data.detail ?? data) : data;
  const code =
    detail && typeof detail === 'object'
      ? typeof detail.code === 'string'
        ? detail.code
        : typeof detail.error === 'string'
          ? detail.error
          : null
      : null;
  const message =
    detail && typeof detail === 'object' && typeof detail.message === 'string'
      ? detail.message
      : typeof detail === 'string'
        ? detail
        : err && err.message
          ? err.message
          : '';
  return { code, message, data, detail };
}

function isRetryableQuoteError(code) {
  return code === 'QUOTE_EXPIRED' || code === 'QUOTE_MISMATCH';
}

function isPydanticMissingBodyField(err, fieldName) {
  const resp = err && err.response ? err.response : null;
  if (!resp || resp.status !== 422) return false;
  const data = resp.data;
  const detail = data && typeof data === 'object' ? data.detail : null;
  if (!Array.isArray(detail)) return false;
  return detail.some((item) => {
    const loc = item && typeof item === 'object' ? item.loc : null;
    return Array.isArray(loc) && loc.includes(fieldName);
  });
}

const app = express();

async function fetchBackendAdmin({ method, path, params, data }) {
  if (!ADMIN_API_KEY) {
    const err = new Error('ADMIN_API_KEY_NOT_CONFIGURED');
    err.status = 500;
    throw err;
  }
  const url = `${PIVOTA_API_BASE}${path}`;
  return await axios({
    method,
    url,
    headers: {
      ...(method !== 'GET' && { 'Content-Type': 'application/json' }),
      'X-ADMIN-KEY': ADMIN_API_KEY,
    },
    timeout: UPSTREAM_TIMEOUT_ADMIN_MS,
    ...(params ? { params } : {}),
    ...(data ? { data } : {}),
  });
}

// ---------------- Promotion / deals enrichment helpers ----------------

const CHANNEL_CREATOR = 'creator_agents';

// Simple admin guard for internal promotions API
function requireAdmin(req, res, next) {
  if (!ADMIN_API_KEY) {
    return res.status(500).json({ error: 'ADMIN_API_KEY_NOT_CONFIGURED' });
  }
  const provided = req.header('X-ADMIN-KEY') || req.header('x-admin-key');
  if (!provided || provided !== ADMIN_API_KEY) {
    return res.status(401).json({ error: 'UNAUTHORIZED' });
  }
  return next();
}

function parseBearerToken(rawHeader) {
  const raw = String(rawHeader || '').trim();
  if (!raw) return null;
  const match = raw.match(/^Bearer\s+(.+)$/i);
  return match && match[1] ? String(match[1]).trim() : null;
}

function fingerprintSecret(rawSecret) {
  const secret = String(rawSecret || '').trim();
  if (!secret) return null;
  return createHash('sha256').update(secret).digest('hex').slice(0, 16);
}

function hashSecretForCache(rawSecret) {
  const secret = String(rawSecret || '').trim();
  if (!secret) return null;
  return createHash('sha256').update(secret).digest('hex');
}

function extractInvokeAuthToken(req) {
  const xAgent = String(
    req?.header('X-Agent-API-Key') ||
      req?.header('x-agent-api-key') ||
      '',
  ).trim();
  if (xAgent) return xAgent;
  const bearer = parseBearerToken(req?.header('Authorization') || req?.header('authorization') || '');
  return bearer || null;
}

const INVOKE_EXTERNAL_API_KEY_PATTERN = /^ak_(live_)?[0-9a-f]{64}$/;
const invokeAuthCache = new Map();
const AGENT_AUTH_EMERGENCY_FALLBACK_ENABLED = parseBooleanEnv(
  process.env.AGENT_AUTH_EMERGENCY_FALLBACK_ENABLED,
  false,
);
const AGENT_AUTH_SERVICE_FALLBACK_AGENT_ID = String(
  process.env.AGENT_AUTH_SERVICE_FALLBACK_AGENT_ID ||
    'agent_service_fallback',
).trim();
const AGENT_AUTH_EMERGENCY_FALLBACK_AGENT_ID = String(
  process.env.AGENT_AUTH_EMERGENCY_AGENT_ID ||
    process.env.AGENT_AUTH_FALLBACK_AGENT_ID ||
    'agent_emergency_fallback',
).trim();
const AGENT_AUTH_SERVICE_FALLBACK_KEYS = parseSecretList(
  process.env.PIVOTA_API_KEY,
  process.env.AGENT_API_KEY,
  process.env.SHOP_GATEWAY_AGENT_API_KEY,
  process.env.CREATOR_INVOKE_API_KEY,
  process.env.PIVOTA_BACKEND_AGENT_API_KEY,
  process.env.PIVOTA_AGENT_API_KEY,
);
const AGENT_AUTH_EMERGENCY_FALLBACK_KEYS = parseSecretList(
  process.env.AGENT_AUTH_EMERGENCY_API_KEY,
  process.env.AGENT_AUTH_EMERGENCY_FALLBACK_KEYS,
);

function getInvokeAuthSource(req) {
  const fromHeader = String(req?.header('X-Agent-API-Key') || req?.header('x-agent-api-key') || '').trim();
  return fromHeader ? 'x-agent-api-key' : 'authorization_bearer';
}

function resolveConfiguredInvokeAuthFastPath(apiKey) {
  const normalized = String(apiKey || '').trim();
  if (!normalized) return null;
  if (!AGENT_AUTH_SERVICE_FALLBACK_KEYS.includes(normalized)) return null;
  return {
    valid: true,
    agent_id: AGENT_AUTH_SERVICE_FALLBACK_AGENT_ID,
    is_active: true,
    auth_source: 'configured_service_key',
    cache_hit: false,
  };
}

function adoptInvokeEmergencyAuthFallback({ req, provided, keyFingerprint, errorCode, reason }) {
  const allowedErrorCodes = [
    'AUTH_INTROSPECT_UNAVAILABLE',
    'AUTH_INTROSPECT_ERROR_RESULT',
  ];
  const serviceFallback = resolveInvokeEmergencyAuthFallback({
    apiKey: provided,
    errorCode,
    allowedErrorCodes,
    enabled: true,
    allowedApiKeys: AGENT_AUTH_SERVICE_FALLBACK_KEYS,
    agentId: AGENT_AUTH_SERVICE_FALLBACK_AGENT_ID,
  });
  const fallback =
    serviceFallback ||
    resolveInvokeEmergencyAuthFallback({
      apiKey: provided,
      errorCode,
      allowedErrorCodes,
      enabled: AGENT_AUTH_EMERGENCY_FALLBACK_ENABLED,
      allowedApiKeys: AGENT_AUTH_EMERGENCY_FALLBACK_KEYS,
      agentId: AGENT_AUTH_EMERGENCY_FALLBACK_AGENT_ID,
    });
  if (!fallback) return null;

  logger.warn(
    {
      path: req?.path || null,
      key_fingerprint: keyFingerprint,
      error_code: errorCode || null,
      reason: reason || null,
      fallback_agent_id: fallback.agent_id || null,
    },
    'invoke auth accepted via emergency fallback',
  );

  req.invokeAuth = {
    key_fingerprint: keyFingerprint,
    auth_source: getInvokeAuthSource(req),
    auth_mode: 'api_key',
    agent_id: fallback.agent_id || null,
    raw_token: provided,
    cache_hit: false,
    introspect_auth_source: fallback.auth_source || null,
    auth_degraded: fallback.auth_degraded === true,
    auth_degraded_reason: fallback.auth_degraded_reason || null,
  };
  return fallback;
}

function shouldBypassInvokeAuthForTest() {
  const bypassRaw = String(process.env.INVOKE_AUTH_BYPASS_IN_TEST || 'auto').trim().toLowerCase();
  const inTestRuntime =
    Boolean(process.env.JEST_WORKER_ID) ||
    String(process.env.NODE_ENV || '').trim().toLowerCase() === 'test';
  if (!inTestRuntime) return false;

  if (['0', 'false', 'off', 'no'].includes(bypassRaw)) return false;
  if (['1', 'true', 'on', 'yes'].includes(bypassRaw)) return true;

  const hasIntrospectionConfig =
    String(process.env.AGENT_AUTH_INTROSPECT_URL || '').trim() &&
    String(process.env.AGENT_AUTH_INTROSPECT_INTERNAL_KEY || '').trim();
  if (hasIntrospectionConfig) return false;
  return true;
}

// The ONE reading of "when does this entry stop existing". Every horizon test goes through this, so
// the prune sweep and the two readers can never disagree about an entry's lifetime — a divergence
// would produce entries the sweep keeps alive but no reader will serve, or vice versa. A shapeless
// entry reads as 0 and is therefore already dead everywhere, which is the safe direction.
function staleHorizonOf(entry) {
  return Number(entry?.stale_expires_at_ms || 0);
}

function pruneInvokeAuthCache(nowMs = Date.now()) {
  for (const [cacheKey, entry] of invokeAuthCache.entries()) {
    if (!entry || typeof entry !== 'object') {
      invokeAuthCache.delete(cacheKey);
      continue;
    }
    // Prune on the OUTAGE horizon, not the fresh one: an expired-fresh positive entry is exactly
    // what the stale-if-error path exists to find. (For negatives the two horizons are equal.)
    if (staleHorizonOf(entry) <= nowMs) {
      invokeAuthCache.delete(cacheKey);
    }
  }
  while (invokeAuthCache.size > AGENT_AUTH_CACHE_MAX_ENTRIES) {
    const oldest = invokeAuthCache.keys().next();
    if (!oldest || oldest.done) break;
    invokeAuthCache.delete(oldest.value);
  }
}

function getCachedInvokeAuthResult(apiKey, nowMs = Date.now()) {
  const cacheKey = hashSecretForCache(apiKey);
  if (!cacheKey) return null;
  const entry = invokeAuthCache.get(cacheKey);
  if (!entry || typeof entry !== 'object') return null;
  if (Number(entry.expires_at_ms || 0) <= nowMs) {
    // Fresh window over. Delete only once the outage window is also over — a positive entry inside
    // the stale-if-error window stays put (and is NOT direct-served) so an introspection outage in
    // the gap can still replay it.
    if (staleHorizonOf(entry) <= nowMs) {
      invokeAuthCache.delete(cacheKey);
    }
    return null;
  }
  invokeAuthCache.delete(cacheKey);
  invokeAuthCache.set(cacheKey, entry);
  return { ...entry.result, cache_hit: true };
}

// The stale-if-error read: ONLY consulted when live introspection failed with
// AUTH_INTROSPECT_UNAVAILABLE. Serves POSITIVE verdicts exclusively — a cached `valid: false` must
// never decide anything during an outage — and never extends an entry's life: replaying a verdict
// does not re-mint it, so the stale horizon set at introspection time stays the hard stop.
//
// It marks the verdict `auth_replayed`, NOT `auth_degraded`, and the distinction is load-bearing
// rather than cosmetic. `auth_degraded` is an ACTUATOR: shouldPreferInternalInvokeUpstreamAuth reads
// it and makes buildInvokeUpstreamAuthHeaders send PIVOTA_API_KEY — the gateway's own service
// credential — INSTEAD of the caller's key on every site passing preferInternalFallback (PDP
// revalidation, product-detail/variant/product-group resolve, the recommend_products price check).
// That substitution is right for the emergency fallback, which fires precisely because it CANNOT
// identify the caller. It is wrong here: a replayed verdict carries a real agent_id from a real
// introspection, so swapping in the service key would buy nothing and would silently strip
// per-agent scoping, quota and audit attribution from every partner request for the whole outage.
function getOutageServableInvokeAuthResult(apiKey, nowMs = Date.now()) {
  if (AGENT_AUTH_CACHE_STALE_IF_ERROR_TTL_MS <= 0) return null;
  const cacheKey = hashSecretForCache(apiKey);
  if (!cacheKey) return null;
  const entry = invokeAuthCache.get(cacheKey);
  if (!entry || typeof entry !== 'object') return null;
  if (entry.result?.valid !== true) return null;
  if (staleHorizonOf(entry) <= nowMs) {
    invokeAuthCache.delete(cacheKey);
    return null;
  }
  return {
    ...entry.result,
    cache_hit: true,
    // Falls back to nowMs (age 0), NOT to 0 (age = the raw epoch, ~55 years). Only an entry with no
    // minted_at_ms at all can take this branch, and this is the one log field an operator reads
    // mid-incident to judge how stale a replayed verdict is — "55 years" would be read as a bug in
    // the cache rather than as the missing timestamp it actually is.
    verdict_age_ms: Math.max(0, nowMs - Number(entry.minted_at_ms ?? nowMs)),
    auth_replayed: true,
    auth_replayed_reason: 'introspect_unavailable_cached_verdict',
  };
}

function putCachedInvokeAuthResult(apiKey, result, nowMs = Date.now()) {
  const cacheKey = hashSecretForCache(apiKey);
  if (!cacheKey || !result || typeof result !== 'object') return;
  const valid = result.valid === true;
  const ttlMs = valid ? AGENT_AUTH_CACHE_POSITIVE_TTL_MS : AGENT_AUTH_CACHE_NEGATIVE_TTL_MS;
  invokeAuthCache.set(cacheKey, {
    minted_at_ms: nowMs,
    expires_at_ms: nowMs + ttlMs,
    // Negatives get NO outage window: stale horizon == fresh horizon, so they are unreadable by the
    // stale-if-error path even before the sweep collects them. The same collapse is what the kill
    // switch does to positives when the window is configured to 0.
    stale_expires_at_ms:
      nowMs +
      (valid ? Math.max(ttlMs, AGENT_AUTH_CACHE_STALE_IF_ERROR_TTL_MS) : ttlMs),
    result: {
      valid,
      agent_id: result.agent_id || null,
      is_active: result.is_active === false ? false : true,
      auth_source: result.auth_source || null,
    },
  });
  pruneInvokeAuthCache(nowMs);
}

// ---- introspection fail-fast cooldown + single flight ------------------------------------------
//
// Two separate amplifiers, both measured on the 2026-08-21 incident shape:
//   COOLDOWN collapses the time axis. Without it EVERY request re-dials an endpoint we just watched
//   time out, waits the full budget, and only then reads a verdict the cache already holds.
//   SINGLE FLIGHT collapses the concurrency axis. Without it N simultaneous requests for the SAME
//   key each open their own connection to ask one question with one answer.
// Together the worst case per cooldown window is one dial per distinct key, instead of one per
// request.
//
// THE COOLDOWN IS PER-KEY, AND THAT IS A SECURITY PROPERTY, NOT A DETAIL. A global "the backend is
// down, stop dialling" window reads as the obvious design — the backend IS down for everyone — and
// it is wrong here, because the dial this shed suppresses is also the dial that ENFORCES REVOCATION.
// A successful dial returning `valid: false` overwrites the cached positive and collapses its stale
// horizon (putCachedInvokeAuthResult); that is the mechanism by which a revoked key stops working.
// Under a global window, one unrelated key's failure suppresses that dial for every other key, so:
//   - a key revoked seconds ago keeps transacting off its stale positive even against a backend
//     that has already recovered, and
//   - an attacker can OPEN the window on demand — introspection is dialled pre-authentication for
//     any well-formed key string, on unthrottled routes, so a flood of random keys saturates the
//     backend until one dial fails — and then present their own recently-revoked key while no
//     revoking dial can land, converting the 120s stale cap from a best case into a guarantee.
// Keying the window on the caller's OWN key removes both: a key is shed only by its own recent
// failure, so revocation lands within one window, and failing other keys buys an attacker nothing.
// The load win is preserved because it was never per-request — it is one dial per active key per
// window, and the real partner-key population is small.
const invokeAuthIntrospectInflight = new Map(); // cacheKey -> Promise<result>
const invokeAuthIntrospectCooldown = new Map(); // cacheKey -> cooldownUntilMs

function pruneInvokeAuthIntrospectCooldown(nowMs = Date.now()) {
  for (const [cacheKey, untilMs] of invokeAuthIntrospectCooldown.entries()) {
    if (!(Number(untilMs) > nowMs)) invokeAuthIntrospectCooldown.delete(cacheKey);
  }
  // Same bound as the verdict cache: this map is keyed by the same hashes and must not become an
  // unbounded sink for a flood of one-shot keys.
  while (invokeAuthIntrospectCooldown.size > AGENT_AUTH_CACHE_MAX_ENTRIES) {
    const oldest = invokeAuthIntrospectCooldown.keys().next();
    if (!oldest || oldest.done) break;
    invokeAuthIntrospectCooldown.delete(oldest.value);
  }
}

function isInvokeAuthIntrospectCooldownActive(apiKey, nowMs = Date.now()) {
  if (AGENT_AUTH_INTROSPECT_COOLDOWN_MS <= 0) return false;
  const cacheKey = hashSecretForCache(apiKey);
  if (!cacheKey) return false;
  return Number(invokeAuthIntrospectCooldown.get(cacheKey) || 0) > nowMs;
}

function openInvokeAuthIntrospectCooldown(apiKey, nowMs = Date.now()) {
  if (AGENT_AUTH_INTROSPECT_COOLDOWN_MS <= 0) return 0;
  const cacheKey = hashSecretForCache(apiKey);
  if (!cacheKey) return 0;
  const untilMs = nowMs + AGENT_AUTH_INTROSPECT_COOLDOWN_MS;
  invokeAuthIntrospectCooldown.set(cacheKey, untilMs);
  pruneInvokeAuthIntrospectCooldown(nowMs);
  return untilMs;
}

function clearInvokeAuthIntrospectCooldown(apiKey) {
  if (apiKey === undefined) {
    invokeAuthIntrospectCooldown.clear();
    return;
  }
  const cacheKey = hashSecretForCache(apiKey);
  if (cacheKey) invokeAuthIntrospectCooldown.delete(cacheKey);
}

function buildInvokeAuthIntrospectUnavailableError(message) {
  const err = new Error(message);
  // MUST be UNAVAILABLE and nothing else. That code is what licenses the stale-if-error replay, and
  // it is only honest for a backend that failed to answer. A REJECTED (backend up, refusing OUR
  // internal key) must never be laundered through here into a replay — so the cooldown never opens
  // on one, and this builder is never called for one.
  err.code = 'AUTH_INTROSPECT_UNAVAILABLE';
  return err;
}

// `telemetry` records what this CALL actually did with the wire, so the log line can say it instead
// of guessing. A pre-sampled "was the cooldown open when I arrived?" is wrong for the two cases that
// matter most: a follower that coalesced onto someone else's dial never touched the wire but would
// have sampled `false`, and during a burst on one hot key that is N-1 log lines each claiming a dial
// the wire never saw — in the one field added to make the shed observable.
async function introspectInvokeApiKey(apiKey, telemetry = {}) {
  const cached = getCachedInvokeAuthResult(apiKey);
  if (cached) {
    telemetry.dial = 'fresh_cache';
    return cached;
  }

  if (!AGENT_AUTH_INTROSPECT_URL || !AGENT_AUTH_INTROSPECT_INTERNAL_KEY) {
    const err = new Error('agent auth introspect is not configured');
    err.code = 'AUTH_INTROSPECT_NOT_CONFIGURED';
    throw err;
  }

  const inflightKey = hashSecretForCache(apiKey);
  if (!inflightKey) {
    telemetry.dial = 'dialled';
    return runBoundedInvokeAuthIntrospectFlight(apiKey);
  }

  // THE JOIN COMES FIRST, BEFORE THE SHED. Riding a dial that is already in the air costs nothing at
  // the wire, which is the only thing the shed protects — and that dial is the authoritative answer
  // for THIS key, possibly the `valid: false` that revokes it. Shedding ahead of the join would
  // refuse a request while the process holds a promise about to answer it, and would replay a stale
  // positive over a live revocation.
  //
  // Keyed on the FULL sha256 of the key, never on a truncated fingerprint and never on a shared
  // token: coalescing two different keys onto one flight would hand caller B the identity that was
  // minted for caller A — a silent cross-tenant identity swap that every status code would call OK.
  const inflight = invokeAuthIntrospectInflight.get(inflightKey);
  if (inflight) {
    telemetry.dial = 'coalesced';
    return inflight;
  }

  // Below the fresh-cache read (a warm key is never shed) and below the join, above the wire.
  if (isInvokeAuthIntrospectCooldownActive(apiKey)) {
    telemetry.dial = 'skipped_cooldown';
    throw buildInvokeAuthIntrospectUnavailableError(
      'introspect skipped: this key dialled recently and the dial failed',
    );
  }

  telemetry.dial = 'dialled';
  const flight = runBoundedInvokeAuthIntrospectFlight(apiKey).finally(() => {
    if (invokeAuthIntrospectInflight.get(inflightKey) === flight) {
      invokeAuthIntrospectInflight.delete(inflightKey);
    }
  });
  // Nothing is swallowed — followers still see the leader's rejection and each run their own
  // stale-cache recovery. This only stops an unconsumed rejection from surfacing as an unhandled
  // rejection when the leader settles before a follower has attached.
  flight.catch(() => {});
  invokeAuthIntrospectInflight.set(inflightKey, flight);
  return flight;
}

// The flight stored in the map above MUST be guaranteed to settle. This repo has already paid for
// that lesson once, in RESOLVE_CATALOG_SIGNATURE_INFLIGHT: a promise that never settles is never
// evicted by `.finally()`, so every later request for that key is handed the SAME dead promise and
// the key is poisoned for the life of the process.
//
// The budget is NOT a substitute for axios's own `timeout`, and the difference matters here more
// than it looks. axios implements `timeout` with `req.setTimeout`, a SOCKET timeout that does not
// start counting until the agent hands the request a socket — so under the very socket exhaustion
// this shed exists to relieve, a queued introspect can sit in `agent.requests[]` with its timer
// unstarted and only this budget settles it.
//
// Which is why the abandoned request must be ABORTED, not merely raced. `Promise.race` drops the
// loser but leaves it running: an orphan that lands later would still open or clear the cooldown on
// evidence about a moment that has passed, and — worst — a late 2xx would reach
// putCachedInvokeAuthResult, which stamps `minted_at_ms` with the COMPLETION time and would hand a
// verdict sampled a minute ago a fresh full TTL plus a fresh stale window. That silently breaks the
// "hard cap measured from the introspection that minted it" invariant the cache is built on. The
// signal makes the orphan impossible instead of arguing about who wins the race.
// `dial` is injectable for ONE reason: the STAGE_TIMEOUT branch below is unreachable over the wire.
// The budget is always axios's timeout + 1s, so axios always wins unless its socket timer never
// started — the queued-socket case — which no HTTP mock can stage. Left uninjectable, the branch
// that exists to guarantee settlement is the one branch nothing can drive, and deleting it passes
// every test while turning the incident shape into a 503 for every warm key (a raw STAGE_TIMEOUT
// fails the strict `=== 'AUTH_INTROSPECT_UNAVAILABLE'` check and so skips the stale replay).
async function runBoundedInvokeAuthIntrospectFlight(apiKey, dial = introspectInvokeApiKeyOverNetwork) {
  const budgetMs = AGENT_AUTH_INTROSPECT_TIMEOUT_MS + 1_000;
  const controller = new AbortController();
  try {
    return await withStageBudget(
      dial(apiKey, controller.signal),
      budgetMs,
      'invoke_auth_introspect',
    );
  } catch (err) {
    if (err?.code === 'STAGE_TIMEOUT') {
      controller.abort();
      openInvokeAuthIntrospectCooldown(apiKey);
      throw buildInvokeAuthIntrospectUnavailableError(
        `introspect exceeded its flight budget: ${budgetMs}ms`,
      );
    }
    throw err;
  }
}

async function introspectInvokeApiKeyOverNetwork(apiKey, signal) {
  let response;
  try {
    response = await axios.post(
      AGENT_AUTH_INTROSPECT_URL,
      { api_key: apiKey },
      {
        timeout: AGENT_AUTH_INTROSPECT_TIMEOUT_MS,
        signal,
        headers: {
          'Content-Type': 'application/json',
          'X-Internal-Key': AGENT_AUTH_INTROSPECT_INTERNAL_KEY,
        },
        validateStatus: () => true,
      },
    );
  } catch (err) {
    openInvokeAuthIntrospectCooldown(apiKey);
    throw buildInvokeAuthIntrospectUnavailableError(err?.message || 'introspect request failed');
  }

  if (response.status >= 500) {
    openInvokeAuthIntrospectCooldown(apiKey);
    throw buildInvokeAuthIntrospectUnavailableError(`introspect upstream status=${response.status}`);
  }

  if (response.status < 200 || response.status >= 300) {
    // NOT an outage and NOT a cooldown trigger: the backend answered, it just refused us. Opening
    // the cooldown here would convert a config error into a licence to replay cached verdicts.
    const err = new Error(`introspect rejected status=${response.status}`);
    err.code = 'AUTH_INTROSPECT_REJECTED';
    throw err;
  }

  const data = response?.data && typeof response.data === 'object' ? response.data : {};
  const result = {
    valid: data.valid === true,
    agent_id: String(data.agent_id || '').trim() || null,
    is_active: data.is_active === false ? false : true,
    auth_source: String(data.auth_source || '').trim() || null,
    cache_hit: false,
  };
  // `auth_source: 'error'` alongside `valid: false` is the backend reporting that IT failed, not a
  // verdict that this key is bad — requireExternalInvokeAuth already reads it that way
  // (AUTH_INTROSPECT_ERROR_RESULT). Caching it as a negative would be the saturated backend talking
  // us into overwriting a good positive entry with a verdict that has NO outage window, so a valid
  // partner key would 401 for the negative TTL and then, once introspection starts timing out
  // outright, find nothing left to replay. That is this feature nullified by the exact incident it
  // exists for — a soft error and a hung socket are the same illness. Leave the entry untouched and
  // let the existing refusal path answer this request on its own.
  const isBackendErrorResult = result.valid !== true && result.auth_source === 'error';
  if (!isBackendErrorResult) {
    putCachedInvokeAuthResult(apiKey, result);
    // Cleared HERE, not on the bare 2xx above, and for the same reason the line above refuses to
    // cache: a soft error is the backend reporting its own failure, so treating it as "answered on
    // the merits" would clear the shed on the evidence that most argues for keeping it. Under mixed
    // saturation — some calls hanging, some returning fast soft errors — clearing on the 2xx made
    // every soft error re-arm the full-timeout dial storm the shed exists to stop.
    clearInvokeAuthIntrospectCooldown(apiKey);
  }
  return result;
}

async function requireExternalInvokeAuth(req, res, next) {
  if (shouldBypassInvokeAuthForTest()) {
    req.invokeAuth = {
      key_fingerprint: null,
      auth_source: 'test_bypass',
      auth_mode: 'test_bypass',
      agent_id: null,
      raw_token: null,
      cache_hit: false,
      introspect_auth_source: null,
    };
    return next();
  }

  const checkoutToken = String(
    req?.header('X-Checkout-Token') || req?.header('x-checkout-token') || '',
  ).trim();
  if (checkoutToken) {
    req.invokeAuth = {
      key_fingerprint: null,
      auth_source: 'x-checkout-token',
      auth_mode: 'checkout_token',
      agent_id: null,
      raw_token: null,
      cache_hit: false,
    };
    return next();
  }

  const provided = extractInvokeAuthToken(req);
  const keyFingerprint = fingerprintSecret(provided);
  if (!provided) {
    return res.status(401).json({
      error: 'UNAUTHORIZED',
      message: 'Missing or invalid API key',
    });
  }

  if (!INVOKE_EXTERNAL_API_KEY_PATTERN.test(provided)) {
    logger.warn(
      {
        path: req?.path || null,
        key_fingerprint: keyFingerprint,
      },
      'invoke auth rejected: invalid api key format',
    );
    return res.status(401).json({
      error: 'UNAUTHORIZED',
      message: 'Missing or invalid API key',
    });
  }

  const configuredFastPath = resolveConfiguredInvokeAuthFastPath(provided);
  if (configuredFastPath) {
    req.invokeAuth = {
      key_fingerprint: keyFingerprint,
      auth_source: getInvokeAuthSource(req),
      auth_mode: 'api_key',
      agent_id: configuredFastPath.agent_id || null,
      raw_token: provided,
      cache_hit: configuredFastPath.cache_hit === true,
      introspect_auth_source: configuredFastPath.auth_source || null,
      auth_degraded: false,
      auth_degraded_reason: null,
    };
    return next();
  }

  let introspection;
  // Filled in by introspectInvokeApiKey with what it actually did: 'fresh_cache' | 'coalesced' |
  // 'skipped_cooldown' | 'dialled'.
  const introspectTelemetry = {};
  try {
    introspection = await introspectInvokeApiKey(provided, introspectTelemetry);
  } catch (err) {
    // Stale-if-error: scoped to AUTH_INTROSPECT_UNAVAILABLE alone. NOT_CONFIGURED and REJECTED mean
    // the introspection contract itself is broken (missing config, backend refused our internal
    // key) — a cached verdict must not paper over those. The replayed verdict falls through the
    // SAME valid/is_active checks a live one gets, so a cached deactivated agent still 403s here.
    // STRICT equality, no `|| 'AUTH_INTROSPECT_UNAVAILABLE'` default. Everything this try block runs
    // beyond the network call — the cache read, the response parse, the cache write — can throw
    // WITHOUT a code, and defaulting a codeless throw to "outage" would make an unrelated TypeError
    // authenticate a caller from cache instead of refusing. Unknown errors fail closed.
    if (err?.code === 'AUTH_INTROSPECT_UNAVAILABLE') {
      const outageVerdict = getOutageServableInvokeAuthResult(provided);
      if (outageVerdict) {
        logger.warn(
          {
            path: req?.path || null,
            key_fingerprint: keyFingerprint,
            code: err?.code || null,
            err: err?.message || String(err),
            agent_id: outageVerdict.agent_id || null,
            verdict_age_ms: outageVerdict.verdict_age_ms,
            stale_if_error_ttl_ms: AGENT_AUTH_CACHE_STALE_IF_ERROR_TTL_MS,
            // What this request actually did with the wire: 'dialled' (and it failed), 'coalesced'
            // onto another request's dial, or 'skipped_cooldown'. The difference between a 10s reply
            // and an instant one, and the only way to see from the logs that the shed is working.
            introspect_dial: introspectTelemetry.dial || 'dialled',
          },
          'invoke auth served cached verdict during introspection outage',
        );
        introspection = outageVerdict;
      }
    }
    if (!introspection) {
      const fallback = adoptInvokeEmergencyAuthFallback({
        req,
        provided,
        keyFingerprint,
        errorCode: err?.code || 'AUTH_INTROSPECT_UNAVAILABLE',
        reason: 'introspection_exception',
      });
      if (fallback) return next();
      logger.error(
        {
          path: req?.path || null,
          key_fingerprint: keyFingerprint,
          code: err?.code || null,
          err: err?.message || String(err),
        },
        'invoke auth introspection unavailable',
      );
      return res.status(503).json({
        error: 'AUTH_INTROSPECT_UNAVAILABLE',
        message: 'Authentication service unavailable',
      });
    }
  }

  if (!introspection || introspection.valid !== true) {
    const fallbackErrorCode =
      introspection && introspection.auth_source === 'error'
        ? 'AUTH_INTROSPECT_ERROR_RESULT'
        : 'AUTH_INTROSPECT_INVALID';
    const fallback = adoptInvokeEmergencyAuthFallback({
      req,
      provided,
      keyFingerprint,
      errorCode: fallbackErrorCode,
      reason:
        introspection?.auth_source === 'error'
          ? 'introspection_error_result'
          : 'introspection_invalid',
    });
    if (fallback) return next();
    logger.warn(
      {
        path: req?.path || null,
        key_fingerprint: keyFingerprint,
      },
      'invoke auth rejected: key not found',
    );
    return res.status(401).json({
      error: 'UNAUTHORIZED',
      message: 'Missing or invalid API key',
    });
  }

  if (introspection.is_active === false) {
    return res.status(403).json({
      error: 'FORBIDDEN',
      message: 'Agent is deactivated',
    });
  }

  req.invokeAuth = {
    key_fingerprint: keyFingerprint,
    auth_source: getInvokeAuthSource(req),
    auth_mode: 'api_key',
    agent_id: introspection.agent_id || null,
    raw_token: provided,
    cache_hit: introspection.cache_hit === true,
    introspect_auth_source: introspection.auth_source || null,
    // Stays hardcoded false. `auth_degraded` means "we could not identify this caller, so use the
    // gateway's own credential upstream" — shouldPreferInternalInvokeUpstreamAuth reads it and
    // swaps PIVOTA_API_KEY in for the caller's key. Only adoptInvokeEmergencyAuthFallback, which
    // builds its own req.invokeAuth and returns before this point, may set it. Every verdict
    // reaching HERE has a real agent_id — live, fresh-cache, or replayed — so none of them wants
    // that substitution.
    auth_degraded: false,
    auth_degraded_reason: null,
    // The replay marker is observability ONLY: nothing branches on it, which is the entire point of
    // keeping it separate from the field above.
    auth_replayed: introspection.auth_replayed === true,
    auth_replayed_reason: introspection.auth_replayed_reason || null,
  };
  return next();
}

function getInvokeAuthContext() {
  return INVOKE_AUTH_CONTEXT.getStore() || null;
}

function getInvokeAuthApiKey() {
  const store = getInvokeAuthContext();
  const key = String(store?.api_key || '').trim();
  return key || null;
}

function shouldPreferInternalInvokeUpstreamAuth(preferInternalFallback = false) {
  if (preferInternalFallback !== true) return false;
  const store = getInvokeAuthContext();
  return (
    store?.auth_degraded === true ||
    String(store?.introspect_auth_source || '').trim().toLowerCase() ===
      'emergency_fallback'
  );
}

function buildInvokeUpstreamAuthHeaders({
  checkoutToken,
  allowInternalFallback = true,
  preferInternalFallback = false,
  forceInternalFallback = false,
  forwardAgentUserJwt = true,
  // Search results are CACHED and shared across callers (mcp-server/src/commerceToolSurface.js). That is
  // only sound if the upstream cannot see who asked, and X-Buyer-Ref is the one caller-derived byte that
  // otherwise leaves this process on every op — including the merchant-scoped `find_products` lane, which
  // goes to the Python backend where we cannot audit what it does with it. Suppressing it on the cached
  // read lanes makes "the upstream sees one identity" true by construction instead of by assumption.
  // Money ops are untouched: they need buyer_ref and are never cached.
  forwardBuyerRef = true,
} = {}) {
  const forwardedHeaders = pruneEmptyFields({
    ...(forwardAgentUserJwt
      ? { 'X-Agent-User-JWT': firstNonEmptyString(getInvokeAuthContext()?.agent_user_jwt) }
      : {}),
    ...(forwardBuyerRef
      ? { 'X-Buyer-Ref': firstNonEmptyString(getInvokeAuthContext()?.buyer_ref) }
      : {}),
  });
  const normalizedCheckoutToken = String(checkoutToken || '').trim();
  if (normalizedCheckoutToken) {
    return {
      'X-Checkout-Token': normalizedCheckoutToken,
      ...forwardedHeaders,
    };
  }

  const callerApiKey = getInvokeAuthApiKey();
  const shouldUseInternalFallback = shouldPreferInternalInvokeUpstreamAuth(
    preferInternalFallback,
  );
  if (forceInternalFallback && allowInternalFallback && PIVOTA_API_KEY) {
    return {
      'X-API-Key': PIVOTA_API_KEY,
      Authorization: `Bearer ${PIVOTA_API_KEY}`,
      ...forwardedHeaders,
    };
  }
  if (
    callerApiKey &&
    !(shouldUseInternalFallback && allowInternalFallback && PIVOTA_API_KEY)
  ) {
    return {
      'X-API-Key': callerApiKey,
      Authorization: `Bearer ${callerApiKey}`,
      ...forwardedHeaders,
    };
  }

  if (allowInternalFallback && PIVOTA_API_KEY) {
    return {
      'X-API-Key': PIVOTA_API_KEY,
      Authorization: `Bearer ${PIVOTA_API_KEY}`,
      ...forwardedHeaders,
    };
  }
  return forwardedHeaders;
}

const AGENT_CHECKOUT_STRICT_MONEY_OPS = new Set([
  'preview_quote',
  'create_order',
  'submit_payment',
  'request_after_sales',
  'confirm_payment',
]);

let commerceMountPromise = null;
let paymentWebhookHandlerPromise = null;
let commerceRemoteMcpAdapterPromise = null;
let commerceConfirmationActionHandlerPromise = null;
let commercePaymentAuthorizationVerifierPromise = null;
let commerceUserTokenVerifierPromise = null;
// The ONE canonical executor (kernel) every protocol door shares — MCP (/mcp), ACP REST, and UCP discovery —
// so charge-once/idempotency/ownership hold ACROSS all doors (no second-kernel hazard). Built once as a side
// effect of getCommerceRemoteMcpAdapter and reused by getCommerceCanonicalExecutor.
let commerceSharedExecutor = null;
// The ONE commerce tool surface over that executor, published the same way. The UCP door is a PROJECTION of
// it (ucpDialectSurface), not a second createCommerceToolSurface: the commerce read cache is PER SURFACE
// INSTANCE (mcp-server/src/commerceToolSurface.js builds it inside the factory), so a second instance is a
// second cache — or, as the UCP door was wired until 2026-08-18, `cache:false` and no cache at all. That was
// moot while the dialect exposed no cacheable tool; the day search_catalog joined it, every UCP search would
// have paid cold cost on a lane whose repeat is measured at 21.2s cold vs ~100ms cached.
let commerceSharedToolSurface = null;
let commerceAcpRestAdapterPromise = null;
// Memoizes ONLY the ESM module import for the UCP profile — the profile/handlers themselves are built
// PER REQUEST (cheap object construction). Memoizing the build froze env reads at the first request and
// cached a rejected build (e.g. a bad signing-key env) as a permanent 503 until redeploy; per-request
// build makes key rotation and the strict-flag-dependent capability list live.
let commerceUcpProfileModulePromise = null;

function isAgentCheckoutStrictEnabled() {
  return String(process.env.AGENT_CHECKOUT_STRICT || '').trim() === '1';
}

function isAgentCheckoutStrictSubmitPaymentEnabled() {
  const normalized = String(process.env.AGENT_CHECKOUT_STRICT_SUBMIT_PAYMENT_ENABLED || '')
    .trim()
    .toLowerCase();
  return ['1', 'true', 'on', 'yes'].includes(normalized);
}

function isAcpSptGatewayHandoffEnabled() {
  // ACP delegated-PSP-token (Stripe SharedPaymentToken) handoff. When an external ACP agent completes with
  // `payment_data.token = spt_…`, the completion is routed to the backend's off-session money endpoint
  // instead of the kernel's hosted-checkout charge — the kernel cannot attest an opaque Stripe handle and
  // must not pretend to (see safety-kernel/src/protocol/canonicalExecutor.js `delegatedPspToken`).
  //
  // Default OFF. With the flag off the routing branch is unreachable and an `spt_` gets exactly the refusal it
  // gets today: CONFIRMATION_INVALID / `unknown_authorization_method` from the configured verifier (or
  // `no_payment_authorization_verifier` when none is configured — the pre-existing answer in that setup).
  // Read LIVE (the executor is memoized, so a build-time boolean would freeze this money kill-switch).
  const normalized = String(process.env.ACP_SPT_GATEWAY_HANDOFF_ENABLED || '').trim().toLowerCase();
  return ['1', 'true', 'on', 'yes'].includes(normalized);
}

// MERCHANT VARIANT SOURCING — ask the storefront for the variant identity our crawl cannot carry.
//
// OFF by default and deliberately so: it puts a third-party call (UCP discovery + catalog search on the
// merchant's own endpoint) on the checkout INTAKE path. It is also strictly additive — it is consulted only
// for rows our own read could not resolve, so arming it can unblock seed-cohort checkouts but can never
// change an answer we already had. See src/services/merchantVariantSource.js for the URL-join safety
// argument, and buyerIntake's resolver for how the returned ids are filtered.
function isMerchantVariantSourcingEnabled() {
  const normalized = String(process.env.MERCHANT_VARIANT_SOURCING_ENABLED || '').trim().toLowerCase();
  return ['1', 'true', 'on', 'yes'].includes(normalized);
}

// PILOT SCOPE. `MERCHANT_VARIANT_SOURCING_BRANDS` is a comma-separated host allowlist (the shape
// OUTBOUND_WARM_HANDOFF_BRANDS already uses), and it is REQUIRED: an empty list arms nothing.
//
// Empty-means-none, not empty-means-all, because the blast radii are not symmetric. This capability makes an
// outbound call to a third party on the checkout intake path, and for the seed cohort the REFUSAL path is the
// common one — so "someone set ENABLED=1 without naming brands" must not silently point the whole corpus at
// every storefront we have ever crawled. The cost of failing closed is that the flag can be on and inert,
// which is its own hazard, so `buildMerchantVariantSource` logs loudly in exactly that state rather than
// leaving it to be discovered by absence.
function merchantVariantSourcingBrands() {
  const { brandAllowlistMatcher } = require('./services/merchantVariantSource');
  return brandAllowlistMatcher(process.env.MERCHANT_VARIANT_SOURCING_BRANDS);
}

// Built once per surface, not per request, so the source's own caches (a short-TTL result cache and an
// in-flight memo) survive across requests. NOTE: the UCP client does NOT cache discovery — an earlier
// comment here claimed it did; the per-domain endpoint cache lives in ucpWarmHandoff, not in the client — so
// a cache MISS costs two outbound requests (well-known + search), which is why the result cache exists.
let _merchantVariantSource = null;
function buildMerchantVariantSource(logger) {
  if (_merchantVariantSource) return _merchantVariantSource;
  // ON BUT INERT is a real state and must never be a silent one: with no brands named, every lookup is
  // refused before contact, so the capability would appear armed and resolve nothing.
  if (isMerchantVariantSourcingEnabled() && merchantVariantSourcingBrands().brands.length === 0) {
    logger?.warn?.({ flag: 'MERCHANT_VARIANT_SOURCING_ENABLED' },
      'merchant variant sourcing is ENABLED but MERCHANT_VARIANT_SOURCING_BRANDS is empty — no brand is piloted, so it will resolve nothing');
  }
  const { createMerchantVariantSource } = require('./services/merchantVariantSource');
  const { createUcpBuyerAgentClient, unwrapToolPayload } = require('./services/ucpBuyerAgentClient');
  _merchantVariantSource = createMerchantVariantSource({
    ucpClient: createUcpBuyerAgentClient({ timeoutMs: 5000, retryAttempts: 1 }),
    unwrap: unwrapToolPayload,
    logger,
    // Thunk, not a boolean: the surface is built once for the process, so a boolean would freeze the flag at
    // construction and make the kill switch un-flippable without a redeploy. For a capability justified as
    // "adds a third-party call to the checkout intake path", disarming must not require one.
    isEnabled: isMerchantVariantSourcingEnabled,
    // Read per call for the same reason — a pilot's brand list changes without a redeploy.
    isBrandAllowed: (host) => merchantVariantSourcingBrands().isAllowed(host),
    // Our own hosts can appear on a product read (`url`/`canonical_url` point at agent.pivota.cc); naming
    // them here keeps a self-referential url from ever being used as the merchant join key.
    selfHosts: ['agent.pivota.cc', 'api.pivota.cc', 'mcp.pivota.cc', 'gateway.pivota.cc', 'pivota.cc'],
  });
  return _merchantVariantSource;
}

function isAgentCheckoutHostedLinkEnabled() {
  // Guest hosted-checkout (create_payment_link). Independent of the autonomous-charge flag above:
  // this path never charges, but it does mint a real payment surface, so it ships OFF by default.
  const normalized = String(process.env.AGENT_CHECKOUT_HOSTED_LINK_ENABLED || '')
    .trim()
    .toLowerCase();
  return ['1', 'true', 'on', 'yes'].includes(normalized);
}

// Mount path for the OpenAI ACP (ChatGPT) REST checkout doors. Deliberately NOT bare `/checkout_sessions`
// (originally namespaced to avoid a collision with the since-removed lookReplicator routes; the
// namespaced path is now the published contract, so it stays).
const COMMERCE_ACP_BASE_PATH = '/acp';

// ACP delegated-payment vaulting. Pivota PERMANENTLY refuses this endpoint (it receives raw cardholder data
// and belongs to the merchant's PSP) — the path is named here because two places need it: the refusal route
// below, and the express.json verify hook, which must NOT stash this body's raw bytes.
const ACP_DELEGATE_PAYMENT_SUBPATH = '/agentic_commerce/delegate_payment';

// ACP door flag semantics live in ./acpFeedFlags (unit-tested decoupling of the
// read-only feed from the money-path checkout endpoints).
const {
  isAcpRestEnabled: isAgentCheckoutAcpRestEnabled,
  isAcpPublicFeedEnabled,
  isAcpRouteEnabled: isAcpRouteEnabledForEnv,
} = require('./acpFeedFlags');

function isAgentCheckoutUcpDiscoveryEnabled() {
  // UCP discovery doors (/.well-known/ucp, /ucp/capabilities). Read-only (no money), but off by default so the
  // discovery surface is published only when a UCP/Gemini integration is intended.
  const normalized = String(process.env.AGENT_CHECKOUT_UCP_DISCOVERY_ENABLED || '').trim().toLowerCase();
  return ['1', 'true', 'on', 'yes'].includes(normalized);
}

function isAgentCheckoutUcpToolDoorEnabled() {
  // The UCP-DIALECT MCP door (POST /ucp/mcp): the same commerce surface addressed by the UCP spec's flat
  // tool names (create_checkout, complete_checkout, …). Double-gated like every money door — it also needs
  // AGENT_CHECKOUT_STRICT, and its charge op still passes the submit_payment kill-switch, because it is the
  // SAME executor as /mcp, not a second path. Default OFF.
  const normalized = String(process.env.AGENT_CHECKOUT_UCP_TOOL_DOOR_ENABLED || '').trim().toLowerCase();
  return ['1', 'true', 'on', 'yes'].includes(normalized);
}

function isUcpBuyerAgentProfileEnabled() {
  // OUTBOUND buyer-agent capability profile door (GET /.well-known/ucp-agent). This is the OPPOSITE role from
  // the seller `/.well-known/ucp` surface above: it advertises Pivota-as-shopping-agent so merchants/platforms
  // (e.g. Shopify UCP) can fetch it during capability negotiation when Pivota calls THEIR UCP endpoint. Static,
  // read-only, no money. Off by default; the founder flips it on when registering Pivota as a UCP buyer agent.
  const normalized = String(process.env.UCP_BUYER_AGENT_PROFILE_ENABLED || '').trim().toLowerCase();
  return ['1', 'true', 'on', 'yes'].includes(normalized);
}

function isAgentCheckoutAllowTestPspEnabled() {
  // TEST-MODE PROBE LEVER (default OFF). When on, hosted-checkout orders carry
  // metadata.allow_test_psp_surfaces=true so the backend can route the order to a TEST processor
  // (cs_test_…) for a controlled, no-real-money test-pay. This is ONLY a request: the backend
  // honors it solely when ITS OWN gate is open (ALLOW_TEST_PSP_PROBE on + merchant in
  // TEST_PSP_PROBE_MERCHANTS — see pivota-backend order_routes._resolve_order_live_readiness_requirement),
  // so flipping this flag alone can never route a live order to a test processor. Ship OFF; flip only for
  // a supervised test-pay and revert after.
  const normalized = String(process.env.AGENT_CHECKOUT_ALLOW_TEST_PSP || '')
    .trim()
    .toLowerCase();
  return ['1', 'true', 'on', 'yes'].includes(normalized);
}

function allowInMemoryStrictCheckoutForTest() {
  const explicit = String(process.env.AGENT_CHECKOUT_ALLOW_IN_MEMORY_STRICT || '').trim().toLowerCase();
  if (['1', 'true', 'on', 'yes'].includes(explicit)) return true;
  return (
    String(process.env.NODE_ENV || '').trim().toLowerCase() === 'test' ||
    Boolean(process.env.JEST_WORKER_ID)
  );
}

function allowStrictCheckoutTestIdentity() {
  if (
    String(process.env.NODE_ENV || '').trim().toLowerCase() === 'test' ||
    Boolean(process.env.JEST_WORKER_ID)
  ) {
    return true;
  }
  return (
    String(process.env.AGENT_CHECKOUT_ALLOW_TEST_IDENTITY || '').trim() === '1' &&
    String(process.env.AGENT_CHECKOUT_TEST_IDENTITY_WINDOW || '').trim() === '1'
  );
}

function resolveStrictMcpPaymentMethodHint() {
  const configured = firstNonEmptyString(
    process.env.AGENT_CHECKOUT_MCP_PAYMENT_METHOD_HINT,
    process.env.AGENT_CHECKOUT_DEFAULT_PAYMENT_METHOD_HINT,
  );
  return configured || 'stripe_checkout';
}

function resolveStrictMcpPaymentReturnUrl(orderId) {
  const oid = firstNonEmptyString(orderId);
  const configured = firstNonEmptyString(
    process.env.AGENT_CHECKOUT_MCP_PAYMENT_RETURN_URL,
    process.env.AGENT_CHECKOUT_PAYMENT_RETURN_URL,
    process.env.PIVOTA_PAYMENT_RETURN_URL,
  );
  if (configured) {
    try {
      const replaced = oid
        ? configured
            .replace(/\{order_id\}/g, encodeURIComponent(oid))
            .replace(/\{orderId\}/g, encodeURIComponent(oid))
        : configured;
      const url = new URL(replaced);
      if (oid && !url.searchParams.has('orderId') && !url.searchParams.has('order_id')) {
        url.searchParams.set('orderId', oid);
      }
      if (!url.searchParams.has('finalizing')) {
        url.searchParams.set('finalizing', '1');
      }
      return url.toString();
    } catch (_) {
      return configured;
    }
  }
  const base = firstNonEmptyString(
    process.env.PIVOTA_AGENT_PUBLIC_BASE_URL,
    process.env.PIVOTA_PUBLIC_AGENT_BASE_URL,
    process.env.PUBLIC_BASE_URL,
    process.env.PIVOTA_AGENT_BASE_URL,
    process.env.PIVOTA_BASE_URL,
  );
  if (!base) return undefined;
  try {
    const url = new URL('/order/success', `${base.replace(/\/+$/, '')}/`);
    if (oid) url.searchParams.set('orderId', oid);
    url.searchParams.set('finalizing', '1');
    return url.toString();
  } catch (_) {
    return undefined;
  }
}

function maybeApplyStrictMcpHostedPaymentDefaults(payment, invokeContext = {}) {
  if (!isPlainObject(payment)) return payment;
  if (invokeContext?.surface !== 'mcp') return payment;
  const paymentMethodHint = firstNonEmptyString(
    payment.payment_method_hint,
    payment.paymentMethodHint,
    payment.payment_method?.type,
    payment.paymentMethod?.type,
    resolveStrictMcpPaymentMethodHint(),
  );
  const returnUrl = firstNonEmptyString(
    payment.return_url,
    payment.returnUrl,
    payment.redirect_url,
    payment.redirectUrl,
    resolveStrictMcpPaymentReturnUrl(payment.order_id || payment.orderId),
  );
  return pruneEmptyFields({
    ...payment,
    payment_method_hint: paymentMethodHint,
    return_url: returnUrl,
  });
}

function applyStrictHostedOrderMetadata(order) {
  if (!isPlainObject(order)) return order;
  const existingMetadata = isPlainObject(order.metadata) ? order.metadata : {};
  const existingAgentV2 = isPlainObject(existingMetadata.agent_v2) ? existingMetadata.agent_v2 : {};
  return {
    ...order,
    metadata: pruneEmptyFields({
      ...existingMetadata,
      // TEST-PSP probe lever (default OFF): set at the TOP LEVEL of order.metadata because the backend's
      // live-readiness gate reads metadata.allow_test_psp_surfaces there (not nested). Only emitted when the
      // agent flag is on; still inert unless the backend's own probe gate + merchant allowlist are also open.
      ...(isAgentCheckoutAllowTestPspEnabled() ? { allow_test_psp_surfaces: true } : {}),
      agent_v2: pruneEmptyFields({
        ...existingAgentV2,
        checkout_provider: 'pivota_hosted_checkout',
        hosted_checkout: true,
      }),
    }),
  };
}

function buildCommerceKernelDb() {
  if (process.env.DATABASE_URL) return { query };
  if (isAgentCheckoutStrictEnabled() && !allowInMemoryStrictCheckoutForTest()) {
    throw new Error('AGENT_CHECKOUT_STRICT requires DATABASE_URL for durable commerce state');
  }
  return null;
}

// Map a get_pdp_v2 response (modules[canonical].data.pdp_payload.product) back to the { product } contract
// get_product_detail callers expect. Flattens brand {name} → string and price {current:{amount,currency}} →
// price/currency scalars; every other field passes through (the adapters' sanitizer/projection handle it).
function normalizePdpV2ToProductDetail(body) {
  try {
    const modules = Array.isArray(body?.modules) ? body.modules : [];
    const canonical = modules.find((m) => m && typeof m === 'object' && m.type === 'canonical');
    const p = canonical?.data?.pdp_payload?.product;
    if (!p || typeof p !== 'object') return { product: null };
    const current = p.price && typeof p.price === 'object' && p.price.current && typeof p.price.current === 'object'
      ? p.price.current
      : null;
    const availability = typeof p.availability === 'string' ? p.availability.toLowerCase() : '';
    return {
      product: {
        ...p,
        brand: p.brand && typeof p.brand === 'object' ? (p.brand.name || null) : (p.brand ?? null),
        price: current ? current.amount : typeof p.price === 'number' ? p.price : null,
        currency: current ? current.currency : (typeof p.currency === 'string' ? p.currency : null),
        in_stock: availability
          ? /in.?stock|available/.test(availability)
          : typeof p.in_stock === 'boolean' ? p.in_stock : undefined,
      },
    };
  } catch {
    return { product: null };
  }
}

// Base URL for calling THIS service's own invoke pipeline over loopback (multi-merchant discovery reads).
// Overridable for environments where loopback isn't routable (SELF_INVOKE_BASE).
function selfInvokeBase() {
  const explicit = String(process.env.SELF_INVOKE_BASE || '').trim();
  if (explicit) return explicit.replace(/\/$/, '');
  const port = Number(process.env.PORT) > 0 ? Number(process.env.PORT) : 8080;
  return `http://127.0.0.1:${port}`;
}

// Timeout/retry policy for the LOOPBACK self-call, which is a different animal from a call to the Python
// kernel and must not inherit the outbound-upstream budget.
//
// Measured on prod 2026-08-05, one partner MCP search: attempt 1 started 02:35:19.2 and was aborted by the
// 10s budget at 02:35:29.4; attempt 2 re-ran the WHOLE pipeline and answered in 9.3s at 02:35:38.4. The
// partner waited 19.3s for 9.3s of work. The inner search's own p50 sits just under the outer budget, so
// ordinary jitter tips every slow query into a full re-execution.
//
// Two reasons a loopback timeout must NOT be retried:
//   1. Aborting the axios client does not stop the server. Nothing in handleInvokeRequest checks
//      req.aborted, so attempt 1 keeps running to completion — the retry means the entire expensive
//      pipeline runs TWICE CONCURRENTLY against a 5-connection DB pool, making the retry slower still.
//   2. A self-call cannot suffer the transient network faults a retry exists to paper over. Same process,
//      same loopback interface: a timeout here means the work is genuinely slow, and the answer to slow
//      work is not to start it again.
// So: one attempt, with a budget wide enough for the real tail. Busy (503) retries are unaffected.
//
// 20s specifically, so the TAIL does not regress while the typical case improves. The old worst case was
// 10s + an 11.2s retry = 21.2s; one 20s attempt is inside that, and the inner search's measured spread
// (2.5-9.4s typical, ~23s pathological) fits with room. A wider budget would trade partner tail latency
// for a longer hold on a 5-connection DB pool, which is the opposite of the trade this change is making.
const SELF_INVOKE_TIMEOUT_MS = parseTimeoutMs(process.env.SELF_INVOKE_TIMEOUT_MS, 20000);

function resolveSelfInvokeBudget(defaultTimeoutMs) {
  const explicit = Number(process.env.AGENT_CHECKOUT_UPSTREAM_TIMEOUT_MS);
  if (Number.isFinite(explicit) && explicit > 0) return explicit;
  return Math.max(Number(defaultTimeoutMs) || 0, SELF_INVOKE_TIMEOUT_MS);
}

// The backend ops behind the CACHED search_catalog tool (mcp-server/src/commerceToolSurface.js caches that
// tool's results and shares them across callers). Both lanes are listed: the unscoped multi-merchant one
// and the merchant-scoped one, which goes to the Python backend where we cannot audit per-buyer behaviour.
const COMMERCE_CACHED_READ_OPS = new Set(['find_products_multi', 'find_products']);

async function invokeCommerceKernelRawUpstream(operation, payload, headers = {}) {
  const op = String(operation || '').trim();
  const metadata = isPlainObject(payload?.metadata) ? payload.metadata : {};
  const invokeContext = getInvokeAuthContext() || {};
  const clientChannel = firstNonEmptyString(payload?.context?.channel, metadata?.source, 'shop');
  const gatewayRequestId = firstNonEmptyString(payload?.context?.request_id, payload?.request_id, randomUUID());
  const timeout = Number(process.env.AGENT_CHECKOUT_UPSTREAM_TIMEOUT_MS || getUpstreamTimeoutMs(op) || 30000);
  const checkoutToken = firstNonEmptyString(invokeContext?.checkout_token);
  let url = `${PIVOTA_API_BASE}/agent/shop/v1/invoke`;
  let requestBody = { operation: op, payload };
  let pdpV2Detail = false;
  // Set by the cases below that route back into THIS process over loopback instead of out to the Python
  // kernel. A loopback hop needs a different timeout/retry policy — see resolveSelfInvokeBudget.
  let selfInvoked = false;

  switch (op) {
    case 'get_product_detail': {
      // Bare-sig / canonical detail (no merchant_id — the public tier's lookups) is NOT resolvable by the
      // Python per-merchant catalog (observed live: MERCHANT_UNAVAILABLE). It IS served by this gateway's
      // own get_pdp_v2 — the same sig-detail lane the public PDP renders from — so unscoped detail routes
      // there and the canonical module is normalized back to the { product } contract below.
      // Merchant-scoped detail keeps the Python backend unchanged (commerce in-store flows).
      const prod = isPlainObject(payload?.product) ? payload.product : {};
      const pid = typeof prod.product_id === 'string' ? prod.product_id.trim() : '';
      const rawDetailMerchant = typeof prod.merchant_id === 'string' ? prod.merchant_id.trim() : '';
      // Seed-supply sellers are the merchant_ids every seed product ADVERTISES, and get_product's
      // schema REQUIRES merchant_id — so agents echo them back as a scope on every seed call. But
      // an upstream per-merchant lookup cannot serve them:
      //  - merch_obs_* (per-brand observed sellers, the A9-4 re-key) have NO upstream catalog at
      //    all — the backend 404s observed refs (see the seed-DB lane note above) — so ANY detail
      //    ref they scope belongs on this gateway's own seed/sig lane;
      //  - the legacy 'external_seed' bucket CAN serve ext_* ids upstream (agent_api's sentinel
      //    path, pinned by tests/integration/invoke.product_intel_v1_real_mode), so only its
      //    sig_-shaped ids — which the upstream provably cannot resolve (live NO_MERCHANT_OFFER,
      //    2026-08-27) — reroute.
      // The predicates come from services/externalSeedLane so the seller-shape knowledge stays in
      // its one watched place (the sentinel-literal ratchet exists because twins of it regressed).
      const seedSupplyUnservableUpstream =
        rawDetailMerchant !== '' &&
        isExternalSeedSupplyMerchantId(rawDetailMerchant) &&
        (isObservedSellerMerchantId(rawDetailMerchant) || pid.startsWith('sig_'));
      const merchantScoped = rawDetailMerchant !== '' && !seedSupplyUnservableUpstream;
      if (!merchantScoped && pid) {
        pdpV2Detail = true;
        // Deliberately NOT marked selfInvoked: get_product_detail is absent from timeoutRetryableOps, so
        // there is no doubled execution to remove here, and widening a budget for a path whose latency
        // has not been measured is a change without evidence.
        url = `${selfInvokeBase()}/agent/shop/v1/invoke`;
        requestBody = {
          operation: 'get_pdp_v2',
          payload: { product_ref: { product_id: pid }, include: ['product_overview'] },
        };
      }
      break;
    }
    case 'find_products_multi': {
      // Multi-merchant discovery is served by THIS gateway's own invoke pipeline (the mainline search
      // stack — the exact lane the public REST gateway proxies to), NOT the Python kernel backend, which
      // only serves per-merchant catalogs (observed live: 2 products from one store). Loopback self-call;
      // auth = the internal fallback key like any agent caller. The invoke handler serves search from the
      // search stack and never re-enters this kernel-upstream path, so no recursion.
      selfInvoked = true;
      url = `${selfInvokeBase()}/agent/shop/v1/invoke`;
      break;
    }
    case 'preview_quote': {
      const quote = isPlainObject(payload?.quote) ? payload.quote : {};
      const offerIdRaw = quote.offer_id || quote.offerId || payload?.offer_id || payload?.offerId || null;
      const offerId = String(offerIdRaw || '').trim() || null;
      const merchantFromOffer = offerId ? extractMerchantIdFromOfferId(offerId) : null;
      const merchantId = firstNonEmptyString(merchantFromOffer, quote.merchant_id, quote.merchantId);
      const normalizedQuote = { ...quote, merchant_id: merchantId };
      delete normalizedQuote.offer_id;
      delete normalizedQuote.offerId;

      if (offerId && Array.isArray(normalizedQuote.items) && normalizedQuote.items.length > 0) {
        const rewritten = await rewriteCheckoutItemsForOfferSelection({
          offerId,
          merchantId,
          items: normalizedQuote.items,
          checkoutToken,
        });
        if (Array.isArray(rewritten?.items) && rewritten.items.length > 0) {
          normalizedQuote.items = rewritten.items;
        }
      }

      url = `${PIVOTA_API_BASE}/agent/v2/quotes/preview`;
      requestBody = buildQuotePreviewV2Body({
        payload,
        quote: normalizedQuote,
        merchantId,
        offerId,
        metadata,
        clientChannel,
        gatewayRequestId,
      });
      break;
    }
    case 'create_order': {
      url = `${PIVOTA_API_BASE}/agent/v2/orders`;
      const order = applyStrictHostedOrderMetadata(isPlainObject(payload?.order) ? payload.order : {});
      requestBody = buildCreateOrderV2Body({
        payload,
        order,
        metadata,
        clientChannel,
        gatewayRequestId,
      });
      break;
    }
    case 'submit_payment': {
      const payment = maybeApplyStrictMcpHostedPaymentDefaults(
        isPlainObject(payload?.payment) ? payload.payment : {},
        invokeContext,
      );
      const checkoutSessionBody = buildCheckoutSessionV2Body({
        payload,
        payment,
        metadata,
        clientChannel,
        gatewayRequestId,
      });
      const forceHostedCheckoutSession = true;
      if (
        !forceHostedCheckoutSession &&
        shouldSubmitPaymentUseExistingOrderMerchantPspSurface({
          payload,
          payment,
          checkoutSessionBody,
        })
      ) {
        url = `${PIVOTA_API_BASE}/agent/v1/payments`;
        requestBody = buildSubmitPaymentV1Body({
          payload,
          payment,
          checkoutSessionBody,
        });
      } else {
        url = `${PIVOTA_API_BASE}/agent/v2/payments/checkout-sessions`;
        requestBody = checkoutSessionBody;
      }
      break;
    }
    case 'submit_delegated_payment': {
      // ACP delegated-PSP-token charge (Stripe SharedPaymentToken). Flag-gated upstream of here — the
      // canonical executor only reaches this op when ACP_SPT_GATEWAY_HANDOFF_ENABLED is on AND the ACP
      // completion carried an `spt_` token. See buildDelegatedPaymentV1Body for why no amount is sent.
      url = `${PIVOTA_API_BASE}/agent/v1/payments`;
      requestBody = buildDelegatedPaymentV1Body({
        order_id: payload?.order_id,
        token: payload?.token,
        idempotency_key: payload?.idempotency_key,
      });
      break;
    }
    case 'create_payment_link': {
      // GUEST hosted checkout: mint a hosted Stripe checkout page for an already-created order. This is the
      // SAME backend surface submit_payment routes to, but invoked WITHOUT a charge/grant — the buyer pays
      // on the returned hosted_url. No PaymentIntent is confirmed here.
      url = `${PIVOTA_API_BASE}/agent/v2/payments/checkout-sessions`;
      requestBody = pruneEmptyFields({
        order_id: firstNonEmptyString(payload?.order_id),
        customer_email: firstNonEmptyString(payload?.customer_email),
        shipping_address: isPlainObject(payload?.shipping_address) ? payload.shipping_address : undefined,
        return_url: firstNonEmptyString(payload?.return_url),
      });
      break;
    }
    case 'request_after_sales': {
      const status = isPlainObject(payload?.status) ? payload.status : {};
      const orderId = firstNonEmptyString(status.order_id, status.orderId);
      url = `${PIVOTA_API_BASE}/agent/v2/orders/${encodeURIComponent(orderId)}/refunds`;
      requestBody = pruneEmptyFields({
        reason: firstNonEmptyString(status.reason),
        restore_inventory: true,
        idempotency_key: firstNonEmptyString(payload?.idempotency_key, payload?.idempotencyKey),
      });
      break;
    }
    default:
      break;
  }

  const axiosConfig = {
    method: 'POST',
    url,
    headers: {
      'Content-Type': 'application/json',
      ...buildInvokeUpstreamAuthHeaders({
        allowInternalFallback: true,
        checkoutToken,
        forceInternalFallback: true,
        // The strict gateway has already verified X-Agent-User-JWT and derived ctx.user_ref. The current
        // backend /agent/v2/orders verifier is not configured for this canary issuer and rejects the raw
        // forwarded header before optional agent_user handling, blocking safe checkout before payment.
        forwardAgentUserJwt: false,
        // The search lanes are the ones whose results get cached and shared across callers, so the
        // upstream must not be able to tell callers apart on them. See forwardBuyerRef.
        forwardBuyerRef: !COMMERCE_CACHED_READ_OPS.has(op),
      }),
      ...headers,
    },
    data: requestBody,
    timeout: selfInvoked ? resolveSelfInvokeBudget(timeout) : timeout,
  };

  let resp;
  try {
    resp = await callUpstreamWithOptionalRetry(op, axiosConfig, {
      // `submit_delegated_payment` joins the no-auto-retry set for the same reason the others are in it: a
      // transport-level retry on a money call whose first attempt may have reached the PSP is precisely the
      // double-charge shape. (It is also absent from busyRetryableOps, so this is belt-and-braces.)
      disableBusyRetry: op === 'create_order' || op === 'submit_payment' || op === 'request_after_sales'
        || op === 'submit_delegated_payment',
      // See resolveSelfInvokeBudget: retrying a loopback timeout doubles concurrent load on the same
      // process and cannot fix what caused it.
      disableTimeoutRetry: selfInvoked,
    });
  } catch (err) {
    if (
      op === 'create_order' &&
      requestBody &&
      Object.keys(requestBody).length > 0 &&
      isPydanticMissingBodyField(err, 'order_request')
    ) {
      try {
        axiosConfig.data = { order_request: requestBody };
        resp = await callUpstreamWithOptionalRetry(op, axiosConfig, { disableBusyRetry: true });
      } catch (wrappedErr) {
        err = wrappedErr;
      }
    }
    if (!resp) {
      await throwCommerceKernelUpstreamError(op, err);
    }
  }

  const body = resp?.data;
  const normalizedBody =
    op === 'preview_quote'
      ? normalizePreviewQuoteCompat(body)
      : op === 'create_order'
        ? normalizeCreateOrderCompat(body)
        : pdpV2Detail
          ? normalizePdpV2ToProductDetail(body)
          : body;
  if (
    normalizedBody &&
    normalizedBody.ok === true &&
    normalizedBody.data &&
    typeof normalizedBody.data === 'object'
  ) {
    return normalizedBody.data;
  }
  return normalizedBody;
}

// The upstream-failure -> shared-taxonomy mapping lives in services/commerceKernelErrorMapping so it is
// unit-testable without booting this app. Read that module before touching the classification: it is shared
// by every kernel op including the money ops, and `retriable` is a promise that costs real money when wrong
// in either direction.
const { mapUpstreamErrorToKernelCode } = require('./services/commerceKernelErrorMapping');

let commerceKernelErrorsPromise = null;
// The upstream-response normalizer (safety-kernel/src/upstreamAdapter.js). The kernel's own money ops get it
// via wrapUpstream inside createCommerceMount; the delegated-PSP-token charge does NOT go through the kernel's
// `_upstream`, so its dispatcher applies the same normalizer explicitly. Memoized ESM import only.
let commerceKernelUpstreamAdapterPromise = null;

async function throwCommerceKernelUpstreamError(operation, err) {
  const { PivotaCommerceError } = await (commerceKernelErrorsPromise ||= import('../safety-kernel/src/errors.js'));
  const { code: upstreamCode, message: upstreamMessage, detail: upstreamDetail } = extractUpstreamErrorCode(err);
  const status = err?.response?.status || null;
  const kernelCode = mapUpstreamErrorToKernelCode({ operation, upstreamCode, status });
  throw new PivotaCommerceError(kernelCode, {
    operation,
    upstream_status: status,
    upstream_code: upstreamCode || null,
    message: upstreamMessage || undefined,
    upstream_detail: upstreamDetail || undefined,
  });
}

function recordCommerceKernelAudit(entry) {
  try {
    if (typeof globalThis.__PIVOTA_AGENT_CHECKOUT_AUDIT_TEST_SINK === 'function') {
      globalThis.__PIVOTA_AGENT_CHECKOUT_AUDIT_TEST_SINK(entry);
    }
  } catch (_) {
    // Test-only sink failures must never affect checkout flow or production logging.
  }
  logger.info(
    {
      event: 'agent_checkout_audit',
      audit: entry && typeof entry === 'object' ? entry : {},
    },
    'agent checkout audit event',
  );
}

async function getCommerceMount() {
  if (!commerceMountPromise) {
    commerceMountPromise = (async () => {
      const { createCommerceMount } = await import('../safety-kernel/src/mount.js');
      return createCommerceMount({
        upstream: invokeCommerceKernelRawUpstream,
        db: buildCommerceKernelDb(),
        secret: process.env.CONFIRMATION_SECRET,
        strict: isAgentCheckoutStrictEnabled(),
        normalizeRealUpstream: true,
        auditSink: recordCommerceKernelAudit,
        log: logger,
      });
    })();
  }
  return commerceMountPromise;
}

function deriveStrictCommerceCtx(req) {
  const auth = req?.auth ?? req?.authInfo ?? req?.session ?? {};
  const testUserRef = allowStrictCheckoutTestIdentity()
    ? firstNonEmptyString(req?.header('X-Test-User-Ref'), process.env.AGENT_CHECKOUT_TEST_USER_REF)
    : null;
  const testSessionId = allowStrictCheckoutTestIdentity()
    ? firstNonEmptyString(req?.header('X-Test-Acp-Session-Id'), process.env.AGENT_CHECKOUT_TEST_ACP_SESSION_ID)
    : null;
  const testDiagnostics =
    Boolean(testUserRef && testSessionId) &&
    String(req?.header('X-Test-Diagnostics') || '').trim() === '1';

  const userRef = firstNonEmptyString(
    auth.user_ref,
    auth.userRef,
    req?.invokeAuth?.user_ref,
    req?.invokeAuth?.userRef,
    testUserRef,
  );
  const acpSessionId = firstNonEmptyString(
    auth.acp_session_id,
    auth.acpSessionId,
    auth.session_id,
    req?.invokeAuth?.acp_session_id,
    req?.invokeAuth?.acpSessionId,
    testSessionId,
  );
  const agentId = firstNonEmptyString(
    auth.agent_id,
    auth.agentId,
    req?.invokeAuth?.agent_id,
  );

  return pruneEmptyFields({
    user_ref: userRef,
    acp_session_id: acpSessionId,
    agent_id: agentId,
    claims: auth.claims,
    diagnostics: testDiagnostics || undefined,
  });
}

function statusForCommerceKernelError(code) {
  switch (code) {
    case 'USER_AUTH_REQUIRED':
      return 401;
    case 'CONFIRMATION_REQUIRED':
    case 'CONFIRMATION_INVALID':
      return 403;
    case 'QUOTE_NOT_FOUND':
    case 'STATE_LINKAGE_MISMATCH':
    // Persistent "this id has nothing servable behind it" — a 404, not the 503 an outage gets.
    case 'NO_MERCHANT_OFFER':
    // Persistent "there is no such id" — same HTTP answer, different fact (see errors.js).
    case 'UNKNOWN_PRODUCT_ID':
      return 404;
    case 'IDEMPOTENCY_CONFLICT':
    case 'PRICE_CHANGED':
      return 409;
    case 'MERCHANT_UNAVAILABLE':
      return 503;
    case 'OPERATION_NOT_ALLOWED':
      return 405;
    default:
      return 422;
  }
}

function sanitizeCommerceKernelErrorDetails(value, depth = 0) {
  if (value == null) return value;
  if (depth > 6) return '[REDACTED]';
  if (Array.isArray(value)) {
    return value.slice(0, 25).map((item) => sanitizeCommerceKernelErrorDetails(item, depth + 1));
  }
  if (typeof value === 'string') return value.length > 600 ? `${value.slice(0, 600)}...` : value;
  if (typeof value !== 'object') return value;

  const out = {};
  for (const [key, raw] of Object.entries(value).slice(0, 50)) {
    if (/amount|price|total/i.test(key)) {
      out[key] = '[REDACTED_AMOUNT]';
      continue;
    }
    if (/token|secret|password|authorization|api[_-]?key|access[_-]?token|pan|card|cvc|cvv|email|address|phone|ap2|payment/i.test(key)) {
      out[key] = '[REDACTED]';
      continue;
    }
    out[key] = sanitizeCommerceKernelErrorDetails(raw, depth + 1);
  }
  return out;
}

function commerceKernelErrorBody(error = {}) {
  const body = {
    status: 'failure',
    error: error.code || 'COMMERCE_ERROR',
    code: error.code || 'COMMERCE_ERROR',
    message: error.message || 'Checkout could not continue.',
    recovery: error.recovery || undefined,
    retriable: error.retriable === true,
  };
  if (error.details && typeof error.details === 'object' && !Array.isArray(error.details)) {
    body.details = sanitizeCommerceKernelErrorDetails(error.details);
  }
  return body;
}

function mcpToolErrorBody({ id = null, code, message }) {
  return {
    jsonrpc: '2.0',
    id,
    result: {
      isError: true,
      content: [
        {
          type: 'text',
          text: JSON.stringify({
            error: {
              code,
              message,
            },
          }, null, 2),
        },
      ],
    },
  };
}

function getCheckoutConfirmationActionSecret() {
  return firstNonEmptyString(
    process.env.CHECKOUT_CONFIRMATION_ACTION_SECRET,
    process.env.CONFIRMATION_ACTION_SECRET,
    process.env.CONFIRMATION_SECRET,
  );
}

function getCheckoutConfirmationActionMaxAgeMs() {
  return parsePositiveInt(
    process.env.CHECKOUT_CONFIRMATION_ACTION_MAX_AGE_MS,
    5 * 60 * 1000,
    { min: 1_000, max: 30 * 60 * 1000 },
  );
}

function normalizeHeaderValue(headers = {}, name) {
  const lower = String(name || '').toLowerCase();
  return firstNonEmptyString(headers[lower], headers[name], headers[String(name || '').toUpperCase()]);
}

function parseConfirmationActionBody(req = {}) {
  const body = req?.body;
  if (isPlainObject(body)) return body;
  const raw = req?.rawBody;
  if (Buffer.isBuffer(raw)) {
    try {
      const parsed = JSON.parse(raw.toString('utf8'));
      return isPlainObject(parsed) ? parsed : {};
    } catch (_) {
      return {};
    }
  }
  if (typeof raw === 'string') {
    try {
      const parsed = JSON.parse(raw);
      return isPlainObject(parsed) ? parsed : {};
    } catch (_) {
      return {};
    }
  }
  return {};
}

function buildCheckoutConfirmationActionSignature({ timestamp, user_ref, acp_session_id, order_id, secret }) {
  return createHmac('sha256', secret)
    .update(`${timestamp}.${user_ref}.${acp_session_id}.${order_id}`)
    .digest('hex');
}

function timingSafeHexEqual(actual, expected) {
  if (typeof actual !== 'string' || typeof expected !== 'string') return false;
  if (!/^[a-f0-9]+$/i.test(actual) || !/^[a-f0-9]+$/i.test(expected)) return false;
  const a = Buffer.from(actual, 'hex');
  const b = Buffer.from(expected, 'hex');
  return a.length === b.length && timingSafeEqual(a, b);
}

function verifyCheckoutConfirmationUserAction(req = {}, authResult = {}) {
  const secret = getCheckoutConfirmationActionSecret();
  if (!secret || secret.length < 16) return false;

  const ctx = authResult?.sessionContext || {};
  const userRef = firstNonEmptyString(ctx.user_ref);
  const acpSessionId = firstNonEmptyString(ctx.acp_session_id);
  if (!userRef || !acpSessionId) return false;

  const body = parseConfirmationActionBody(req);
  const orderId = firstNonEmptyString(body.order_id);
  if (!orderId) return false;

  const timestampRaw = normalizeHeaderValue(req.headers, 'x-pivota-confirm-timestamp');
  const signature = normalizeHeaderValue(req.headers, 'x-pivota-confirm-signature');
  const timestamp = Number(timestampRaw);
  if (!Number.isFinite(timestamp) || timestamp <= 0 || !signature) return false;

  const ageMs = Math.abs(Date.now() - timestamp);
  if (ageMs > getCheckoutConfirmationActionMaxAgeMs()) return false;

  const expected = buildCheckoutConfirmationActionSignature({
    timestamp: timestampRaw,
    user_ref: userRef,
    acp_session_id: acpSessionId,
    order_id: orderId,
    secret,
  });
  return timingSafeHexEqual(signature, expected);
}

function buildStrictSessionAuthInfo(req, sessionContext = deriveStrictCommerceCtx(req)) {
  return pruneEmptyFields({
    invoke_authenticated: true,
    invokeAuth: req?.invokeAuth,
    sessionContext,
  });
}

// Every path that speaks MCP JSON-RPC on the COMMERCE lane. `/ucp/mcp` is on the list because UCP's own
// transport IS MCP JSON-RPC — it is the same surface with the spec's tool spelling — and because
// `surface === 'mcp'` is what arms maybeApplyStrictMcpHostedPaymentDefaults. Leaving the UCP door off this
// list would hand its charges different hosted-payment defaults (no return_url, no payment_method_hint)
// than /mcp gets: a money-path fork created by a missing string.
const COMMERCE_MCP_JSON_RPC_PATHS = new Set(['/mcp', '/ucp/mcp']);

// Does this request's path speak commerce MCP JSON-RPC? Normalized, not compared raw.
//
// Express routes case-insensitively and tolerates trailing slashes (caseSensitive/strict default off), so
// `POST /ucp/mcp/`, `/UCP/MCP` and `/mcp/` all reach the door and are served — but `req.path` hands back the
// spelling the caller used, so a raw Set lookup MISSES them and reports `surface: null` for a request the
// money door just answered. On this lane that is not cosmetic: `surface === 'mcp'` is the only thing that
// arms maybeApplyStrictMcpHostedPaymentDefaults, so a platform posting to `https://…/ucp/mcp/` would
// complete a charge with no return_url and no payment_method_hint — the buyer pays and lands nowhere.
// Same normalization as shouldCaptureAcpRawBody and as the public body-cap middleware, for the same Express
// reason. All three now agree, which is the point — but they agree because each was fixed separately after
// shipping the same bug: this Set matched req.path raw (#1971), the ACP stash ran its prefix test on the raw
// url (#1975), and the body cap computed a `pNorm` it then applied to only one of three branches (this
// commit's parent). Three independent instances of "reasoned about which PATHS belong to a surface, never
// about which SPELLINGS Express serves". Anything added here that compares a path must normalize on EVERY
// branch of the expression, not just the branch being edited — that partial-normalization shape is exactly
// how two of the three survived review.
//
// No query-string strip here (unlike shouldCaptureAcpRawBody, which reads originalUrl): `req.path` is
// already parseurl().pathname. It is also NOT percent-decoded, which is what keeps `/ucp%2Fmcp` out —
// verified, along with `//mcp`, `/mcp/../mcp` and `/mcp;x=1`, all of which Express 404s anyway.
function isCommerceMcpJsonRpcPath(path) {
  const normalized = String(path || '').toLowerCase().replace(/\/+$/, '');
  return COMMERCE_MCP_JSON_RPC_PATHS.has(normalized);
}

function buildExternalInvokeContext(req) {
  return {
    // The path as RECEIVED (this is a diagnostic field); only the surface decision is normalized.
    path: req?.path || null,
    surface: isCommerceMcpJsonRpcPath(req?.path) ? 'mcp' : null,
    api_key: req?.invokeAuth?.raw_token || null,
    agent_id: req?.invokeAuth?.agent_id || null,
    auth_mode: req?.invokeAuth?.auth_mode || null,
    auth_source: req?.invokeAuth?.auth_source || null,
    auth_degraded: req?.invokeAuth?.auth_degraded === true,
    auth_degraded_reason: req?.invokeAuth?.auth_degraded_reason || null,
    introspect_auth_source: req?.invokeAuth?.introspect_auth_source || null,
    agent_user_jwt: firstNonEmptyString(
      req?.header('X-Agent-User-JWT'),
      req?.header('x-agent-user-jwt'),
    ),
    buyer_ref: firstNonEmptyString(
      req?.header('X-Buyer-Ref'),
      req?.header('x-buyer-ref'),
    ),
  };
}

function parseJsonArrayEnv(raw, label) {
  if (!firstNonEmptyString(raw)) return null;
  let parsed;
  try {
    parsed = JSON.parse(raw);
  } catch (_) {
    throw new Error(`${label} must be valid JSON`);
  }
  if (!Array.isArray(parsed) || parsed.length === 0) {
    throw new Error(`${label} must be a non-empty JSON array`);
  }
  return parsed;
}

// AP2 checkout binding service — ONE instance shared by the two seams that must agree on the
// secret: the executor's mint hook (create_checkout returns ap2_checkout_jwt) and the mandate
// verifier's verifyCheckoutHash (complete_checkout proves the wallet hashed that exact JWT).
// null when the AP2 flag is off. THROWS on flag-on-without-secret: the old unconditional throw
// moved here — misconfig stays loud, it just stopped being the only possible outcome.
let commerceAp2CheckoutBindingPromise = null;
function isAp2MandateEnabled() {
  return parseBooleanEnv(process.env.AGENT_CHECKOUT_MCP_ENABLE_AP2_MANDATE, false);
}
async function getAp2CheckoutBinding() {
  if (!isAp2MandateEnabled()) return null;
  if (!commerceAp2CheckoutBindingPromise) {
    commerceAp2CheckoutBindingPromise = (async () => {
      const secret = String(process.env.AP2_CHECKOUT_JWT_SECRET || '').trim();
      const { Ap2CheckoutBindingService } = await import('../safety-kernel/src/protocol/ap2CheckoutBinding.js');
      return new Ap2CheckoutBindingService({ secret }); // throws on a weak/missing secret
    })();
    commerceAp2CheckoutBindingPromise.catch(() => { commerceAp2CheckoutBindingPromise = null; });
  }
  return commerceAp2CheckoutBindingPromise;
}

async function getCommercePaymentAuthorizationVerifier() {
  if (!commercePaymentAuthorizationVerifierPromise) {
    commercePaymentAuthorizationVerifierPromise = (async () => {
      const paymentIssuers = parseJsonArrayEnv(
        firstNonEmptyString(
          process.env.PAYMENT_ISSUERS_JSON,
          process.env.AGENT_CHECKOUT_PAYMENT_ISSUERS_JSON,
          process.env.PIVOTA_PAYMENT_ISSUERS_JSON,
        ),
        'PAYMENT_ISSUERS_JSON',
      );

      // Registry-backed issuers (pivota-backend #1886): static env issuers stay pinned (the
      // canary lives there), registry rows are additive, and the merged list is re-read on a
      // TTL so onboarding a PSP is a portal row, not a gateway redeploy. With the registry
      // DISABLED (no base/key) and no env issuers, this returns undefined exactly as before —
      // requiresPaymentAuthz operations stay refused.
      const { createPaymentGrantIssuerRegistry } = require('./services/paymentGrantIssuerRegistry');
      const paymentIssuerRegistry = createPaymentGrantIssuerRegistry({
        staticIssuers: paymentIssuers || [],
        logger,
      });
      if (!paymentIssuers && !paymentIssuerRegistry.enabled) return undefined;

      // The unconditional AP2 throw is gone: the reviewed checkout-hash verifier it demanded
      // now exists (safety-kernel/src/protocol/ap2CheckoutBinding.js). Flag-on still fails
      // LOUDLY on a missing/weak AP2_CHECKOUT_JWT_SECRET — inside getAp2CheckoutBinding — so
      // the misconfig posture is unchanged; what changed is that a correct config proceeds.
      const ap2Binding = await getAp2CheckoutBinding(); // null when the flag is off

      const { createPaymentAuthorizationVerifier } = await import('../safety-kernel/src/protocol/paymentAuthorizationVerifier.js');
      const { buildPaymentMethodVerifiers } = await import('../safety-kernel/src/protocol/protocolPaymentVerifiers.js');
      const { PivotaCommerceError } = await import('../safety-kernel/src/errors.js');
      // Rebuilt by the registry wrapper ONLY when the merged issuer list changes; with the
      // registry disabled this builds exactly once over the static list, as before.
      const registryVerifier = paymentIssuerRegistry.createVerifier((issuers, byMethod) => createPaymentAuthorizationVerifier({
        // `issuers` is already the signed_grant SLICE (see createVerifier). Composition lives in
        // buildPaymentMethodVerifiers so it is reachable from a test — this callback was the one
        // place the registry's fake-build tests could never exercise.
        methods: buildPaymentMethodVerifiers({
          signedGrantIssuers: issuers,
          ap2MandateIssuers: byMethod ? byMethod.ap2_mandate : [],
          ap2Binding,
          expectedVct: process.env.AP2_EXPECTED_VCT ? String(process.env.AP2_EXPECTED_VCT).trim() : '',
        }),
      }));
      // Every throw that leaves this seam must be a PivotaCommerceError: the doors are
      // instanceof-gated (toToolError's SAFE_ERROR_CLASSES; the ACP adapter 500s on anything
      // else), so the registry's own failures — empty merged list, a verifier build refused —
      // would otherwise degrade the clean CONFIRMATION_INVALID refusal an ABSENT verifier
      // produces into a generic UNEXPECTED_ERROR / HTTP 500. Same wrapping the kernel itself
      // applies to method verifiers (paymentAuthorizationVerifier.js), one level further out.
      return async (authorization, ...rest) => {
        try {
          return await registryVerifier(authorization, ...rest);
        } catch (err) {
          if (err instanceof PivotaCommerceError) throw err;
          logger.warn({ code: err?.code || 'PAYMENT_AUTHZ_FAILURE' }, 'payment verifier unavailable; refusing');
          throw new PivotaCommerceError('CONFIRMATION_INVALID', { reason: 'payment_authorization_unavailable' });
        }
      };
    })();
  }
  return commercePaymentAuthorizationVerifierPromise;
}

async function getCommerceUserTokenVerifier() {
  if (!commerceUserTokenVerifierPromise) {
    commerceUserTokenVerifierPromise = (async () => {
      const identityIssuers = parseJsonArrayEnv(
        firstNonEmptyString(
          process.env.IDENTITY_ISSUERS_JSON,
          process.env.AGENT_CHECKOUT_IDENTITY_ISSUERS_JSON,
          process.env.PIVOTA_IDENTITY_ISSUERS_JSON,
        ),
        'IDENTITY_ISSUERS_JSON',
      );
      if (!identityIssuers) return undefined;

      const { createUserTokenVerifier } = await import('../safety-kernel/src/identity/userTokenVerifier.js');
      return createUserTokenVerifier({
        issuers: identityIssuers,
        maxTokenAge: firstNonEmptyString(
          process.env.AGENT_CHECKOUT_IDENTITY_MAX_TOKEN_AGE,
          process.env.IDENTITY_MAX_TOKEN_AGE,
        ) || undefined,
      });
    })();
  }
  return commerceUserTokenVerifierPromise;
}

function extractAgentUserJwt(req = {}) {
  return firstNonEmptyString(
    req?.header?.('X-Agent-User-JWT'),
    req?.header?.('x-agent-user-jwt'),
  );
}

function resolveVerifiedCommerceSessionId(claims = {}) {
  if (!claims || typeof claims !== 'object') return null;
  return firstNonEmptyString(
    claims.acp_session_id,
    claims.acpSessionId,
    claims.pivota_session_id,
    claims.pivotaSessionId,
    claims.session_id,
    claims.sessionId,
    claims.sid,
  );
}

function stripStrictUserContext(ctx = {}, identityDiagnostics = undefined) {
  return pruneEmptyFields({
    agent_id: ctx.agent_id,
    diagnostics: ctx.diagnostics,
    identity_diagnostics: identityDiagnostics,
  });
}

// Federated buyer identity (per-agent issuers registered in the developer portal; backend table
// agent_identity_issuers). Built once per process; the registry itself refreshes on its own TTL and does a
// single forced refresh on a miss, so a registration made seconds ago is honoured. Disabled (and every call
// throws) unless PIVOTA_API_BASE + AGENT_AUTH_INTROSPECT_INTERNAL_KEY are set — the same pair the api-key
// introspection uses — or when AGENT_FEDERATED_IDENTITY_ENABLED=false.
let agentIdentityIssuerRegistry = null;
function getAgentIdentityIssuerRegistry() {
  if (!agentIdentityIssuerRegistry) {
    const { createAgentIdentityIssuerRegistry } = require('./services/agentIdentityIssuerRegistry');
    agentIdentityIssuerRegistry = createAgentIdentityIssuerRegistry({ logger });
  }
  return agentIdentityIssuerRegistry;
}

/**
 * The static verifier does not know this issuer (or is not configured at all) — is it an issuer the CALLING
 * agent registered? Only then is the token verified, and only against that agent's binding. Any outcome
 * other than a verified token throws, exactly like the static verifier, so the caller's fail-closed branch
 * is shared. `null` means "not applicable" (no agent on the request), which keeps the static error.
 */
async function verifyFederatedUserJwt(req, token) {
  const agentId = req?.invokeAuth?.agent_id;
  if (!agentId) return null;
  return getAgentIdentityIssuerRegistry().verifyForAgent(token, agentId);
}

function isUnknownIssuerError(err) {
  return err?.code === 'ISSUER_NOT_ALLOWED';
}

async function deriveStrictCommerceCtxAsync(req) {
  const base = deriveStrictCommerceCtx(req);
  const rawUserJwt = extractAgentUserJwt(req);
  if (!rawUserJwt) {
    return pruneEmptyFields({
      ...base,
      identity_diagnostics: { agent_user_jwt_present: false },
    });
  }
  const token = parseBearerToken(rawUserJwt) || rawUserJwt;

  const verified = (verifiedResult, source) => {
    const verifiedSessionId = resolveVerifiedCommerceSessionId(verifiedResult?.claims);
    return pruneEmptyFields({
      ...base,
      user_ref: verifiedResult.user_ref,
      acp_session_id: verifiedSessionId || base.acp_session_id,
      claims: verifiedResult.claims,
      identity_source: source,
      identity_diagnostics: {
        agent_user_jwt_present: true,
        verifier_configured: true,
        verified: true,
        ...(verifiedResult.issuer_binding ? { issuer_binding: verifiedResult.issuer_binding } : {}),
      },
    });
  };

  const verifier = await getCommerceUserTokenVerifier();
  if (typeof verifier !== 'function') {
    // No static issuers configured. A federated binding can still verify the token — for the calling agent
    // only. Everything else keeps the original NO_IDENTITY_ISSUER_CONFIG outcome.
    try {
      const fed = await verifyFederatedUserJwt(req, token);
      if (fed) return verified(fed, 'x_agent_user_jwt_federated');
    } catch (err) {
      logger.warn({ path: req?.path || null, code: err?.code || null }, 'federated agent user JWT verification failed');
      return stripStrictUserContext(base, {
        agent_user_jwt_present: true,
        // No STATIC verifier exists in this branch; only the federated registry answered. Reporting
        // verifier_configured:true here would hide exactly the misconfiguration worth seeing.
        verifier_configured: false,
        federated_attempted: true,
        verified: false,
        failure_code: err?.code || 'USER_TOKEN_INVALID',
      });
    }
    logger.warn(
      {
        path: req?.path || null,
        code: 'NO_IDENTITY_ISSUER_CONFIG',
      },
      'agent checkout user JWT verification unavailable',
    );
    return stripStrictUserContext(base, {
      agent_user_jwt_present: true,
      verifier_configured: false,
      failure_code: 'NO_IDENTITY_ISSUER_CONFIG',
    });
  }

  try {
    return verified(await verifier(token), 'x_agent_user_jwt');
  } catch (err) {
    // The static registry does not know the issuer → try the calling agent's own binding. Any other static
    // failure (bad signature, expired, wrong aud for a KNOWN issuer) is final: a federated retry there would
    // let an agent re-register a global issuer and get a second opinion.
    if (isUnknownIssuerError(err)) {
      try {
        const fed = await verifyFederatedUserJwt(req, token);
        if (fed) return verified(fed, 'x_agent_user_jwt_federated');
      } catch (fedErr) {
        logger.warn({ path: req?.path || null, code: fedErr?.code || null }, 'federated agent user JWT verification failed');
        return stripStrictUserContext(base, {
          agent_user_jwt_present: true,
          verifier_configured: true,
          verified: false,
          failure_code: fedErr?.code || 'USER_TOKEN_INVALID',
        });
      }
    }
    logger.warn(
      {
        path: req?.path || null,
        code: err?.code || null,
      },
      'agent checkout user JWT verification failed',
    );
    return stripStrictUserContext(base, {
      agent_user_jwt_present: true,
      verifier_configured: true,
      verified: false,
      failure_code: err?.code || 'USER_TOKEN_INVALID',
    });
  }
}

async function getCommerceRemoteMcpAdapter() {
  if (!commerceRemoteMcpAdapterPromise) {
    commerceRemoteMcpAdapterPromise = (async () => {
      const commerce = await getCommerceMount();
      const { createCanonicalExecutor } = await import('../safety-kernel/src/protocol/canonicalExecutor.js');
      const { createCommerceToolSurface } = await import('../mcp-server/src/commerceToolSurface.js');
      const { createRemoteMcpAdapter } = await import('../mcp-server/src/remoteMcpAdapter.js');
      const verifyPaymentAuthorization = await getCommercePaymentAuthorizationVerifier();
      // Read-only intelligence reads (get_alternatives/get_offers) injected as localReads — the relationship
      // graph + offers live in the app DB, so the handlers are wired here (not in the safety kernel).
      const {
        makeGetAlternatives,
        makeGetOffers,
        makeGetIntel,
        mapOffersResolveResponse,
        candidateSnapshotNeedsHydration,
        hydrateCandidateSnapshotFromEntity,
      } = require('./agentSignals/intelligenceReads');
      const { makeRecommendProducts, classifyVerifyPriceResponse } = require('./agentSignals/recommendProducts');
      const {
        listApprovedRelationshipEdgesForAnchor,
        buildAnchorRefsFromProduct,
      } = require('./auroraBff/productRelationshipGraph');
      const { getProductIntelKbEntry, getProductIntelKbEntries } = require('./auroraBff/productIntelKbStore');
      // Strict, independent gate for the agent surface (no consumer-flag fallback): off unless explicitly set.
      const agentRelationshipGraphEnabled = () =>
        /^(1|true|yes|on|enabled)$/i.test(String(process.env.AURORA_BFF_RELATIONSHIP_GRAPH_AGENT_ENABLED || '').trim());
      // Independent gate for the why/fit/evidence intel surface — off unless explicitly enabled.
      const agentProductIntelEnabled = () =>
        /^(1|true|yes|on|enabled)$/i.test(String(process.env.AURORA_BFF_PRODUCT_INTEL_AGENT_ENABLED || '').trim());
      // Independent gate for surfacing public-safe grounded claims (citation URLs + grade A–C) on the
      // get_intel signal — the citation substrate a frontier agent needs to CITE Pivota. Off unless
      // explicitly enabled. The FTC per-claim rule is single-sourced in filterPublicSafeClaims (same as the
      // public PDP stamp); a lazy require avoids the pivotaInsightsQuality → … → pdpProductIntel cycle.
      const agentIntelPublicClaimsEnabled = () =>
        /^(1|true|yes|on|enabled)$/i.test(String(process.env.AGENT_INTEL_PUBLIC_CLAIMS_ENABLED || '').trim());
      // Independent gate for the need-anchored recommendation shortlist (the Aurora reco lane bridged to the
      // agent doors). Off unless explicitly enabled: it calls the external decision service and costs an LLM
      // generation per call, so lighting it is an ops decision, not a deploy side effect.
      const agentRecommendProductsEnabled = () =>
        /^(1|true|yes|on|enabled)$/i.test(String(process.env.AURORA_BFF_RECOMMEND_PRODUCTS_AGENT_ENABLED || '').trim());
      const filterPublicSafeClaimsGated = (claims) => {
        if (!agentIntelPublicClaimsEnabled()) return [];
        try {
          return require('./services/pivotaInsightsQuality').filterPublicSafeClaims(claims);
        } catch {
          return [];
        }
      };
      const localReads = {
        get_alternatives: makeGetAlternatives({
          listApprovedRelationshipEdgesForAnchor,
          buildAnchorRefsFromProduct,
          isEnabled: agentRelationshipGraphEnabled,
          // Resolve the queried product to its full identity set (sig + grouped source ids) so the
          // agent's source-id query matches both sig-keyed and ext_/ulta:-keyed edges. Flag-gated
          // (AURORA_BFF_RELATIONSHIP_GRAPH_ANCHOR_IDENTITY_HYDRATION_ENABLED) + fail-open in the resolver.
          hydrateAnchorProduct: async (anchorProduct) => {
            const identity = await resolveAnchorIdentityForRelationshipGraph({
              product_id: anchorProduct && anchorProduct.product_id,
              merchant_id: anchorProduct && anchorProduct.merchant_id,
            });
            return identity ? applyAnchorIdentity(anchorProduct, identity) : anchorProduct;
          },
          // Resolve candidate titles AND the currency of a stored price amount at read-time (the stored
          // candidate_snapshot has no title on the uncollapsed path, and its writer never normalized a
          // currency key — an amount must never reach an agent without its currency). Reuses the same
          // resolver the family-collapse serving path uses; the per-edge merge is the pure
          // hydrateCandidateSnapshotFromEntity. Fail-open: a miss leaves the snapshot as-is.
          hydrateCandidates: async (edges) => {
            if (typeof resolveRelationshipGraphRefsToCanonicalEntities !== 'function') return;
            const refs = [];
            for (const e of edges) {
              const snap = (e && e.candidate_snapshot) || {};
              if (e && e.candidate_product_ref && candidateSnapshotNeedsHydration(snap)) {
                refs.push({ ref: e.candidate_product_ref, snapshot: snap });
              }
            }
            if (!refs.length) return;
            const resMap = await resolveRelationshipGraphRefsToCanonicalEntities(refs, {});
            if (!resMap || typeof resMap.get !== 'function') return;
            const keyOf = (ref) =>
              typeof normalizeRelationshipGraphRefForResolution === 'function'
                ? (normalizeRelationshipGraphRefForResolution(ref) || {}).normalized_ref
                : ref;
            for (const e of edges) {
              if (!e || !e.candidate_product_ref) continue;
              const snap = (e && e.candidate_snapshot) || {};
              const hydrated = hydrateCandidateSnapshotFromEntity(snap, resMap.get(keyOf(e.candidate_product_ref)));
              if (hydrated) e.candidate_snapshot = hydrated;
            }
          },
        }),
        // Cross-merchant offers via the live backend `offers.resolve` op (resolves to a canonical product
        // group and aggregates offers across all member merchants — verified in agent_shop_gateway.py). Its
        // `offers[]` is already in offerToSignal shape; mapOffersResolveResponse normalizes the envelope.
        // Single-offer products yield best_offer + an empty competition set (no fabricated competition).
        get_offers: makeGetOffers({
          fetchOffers: async ({ merchant_id, product_id, product_group_id, limit }) =>
            mapOffersResolveResponse(
              await invokeCommerceKernelRawUpstream('offers.resolve', {
                product: { product_id, merchant_id },
                limit: Math.min(Math.max(Number(limit) || 10, 1), 30),
                commerceSurface: 'agent_api',
              }),
              product_group_id || null,
            ),
        }),
        // Why/fit/evidence from the product-intelligence KB (chat-only until now) → decision Signal.
        // resolveKbKeys builds the candidate `product:<identity>` keys from the request identity so the
        // agent's product_id matches however the KB was keyed; the mapper drops rejected/empty intel.
        get_intel: makeGetIntel({
          getProductIntelKbEntry,
          getProductIntelKbEntries,
          isEnabled: agentProductIntelEnabled,
          // Surface the public-safe grounded claims (citation URLs + grade) onto the signal, gated by
          // AGENT_INTEL_PUBLIC_CLAIMS_ENABLED. Same FTC filter the public PDP uses → one consistent claim set.
          filterPublicSafeClaims: filterPublicSafeClaimsGated,
          // Servable gate: human (Tier-H) OR grounded (Tier-G) intel reaches a buyer-facing agent
          // (drops thin/pilot/unreviewed Tier-L entries). Same predicate the consumer PDP uses for
          // public display, so the agent surface and PDP apply one consistent quality bar. (ADR-002 item 9)
          isReviewed: isServableProductIntelBundle,
          resolveKbKeys: async (p) => {
            const keys = [];
            const pushUrl = (v) => {
              const s = (v == null ? '' : String(v)).trim();
              if (!s) return;
              const k = `url:${s}`;
              if (!keys.includes(k)) keys.push(k);
            };
            const push = (v) => {
              const s = (v == null ? '' : String(v)).trim();
              if (!s) return;
              const k = `product:${s}`;
              if (!keys.includes(k)) keys.push(k);
            };
            // The KB is keyed by `product:<identity>` for several identities (sig / canonical
            // pg_/sig_ / per-listing source id). Hydrate the queried product to its full identity
            // set (same resolver get_alternatives uses) so a single product_id matches however the
            // KB was keyed. Flag-gated + fail-open inside the resolver → bare keys when off/unresolved.
            let identity = null;
            try {
              identity = await resolveAnchorIdentityForRelationshipGraph({
                product_id: p.product_id,
                merchant_id: p.merchant_id,
              });
            } catch {
              identity = null;
            }
            if (identity) {
              push(identity.canonical_entity_id);
              push(identity.pivota_signature_id);
              for (const sig of Array.isArray(identity.member_sig_ids) ? identity.member_sig_ids : []) push(sig);
              for (const src of Array.isArray(identity.member_source_ids) ? identity.member_source_ids : []) push(src);
              pushUrl(identity.canonical_url);
            }
            // Always include the request-provided identities (covers the flag-off / unresolved path).
            push(p.pivota_signature_id);
            push(p.product_id);
            push(p.product_ref);
            return keys;
          },
        }),
        // The need-anchored shortlist: Pivota's prompt-level recommendation lane (the engine behind
        // POST /v1/reco/generate), bridged as a local read. The lane instance is the one the Aurora routes
        // module built at load (auroraBffInternal); when that module failed to load — or the flag is dark —
        // the handler answers an empty, reasoned result rather than throwing. Identity: a namespaced synthetic
        // uid per calling agent (see recommendProducts.js); no bearer, so nothing consumer-side is read or
        // written.
        recommend_products: makeRecommendProducts({
          generate: async (args) => {
            const fn = auroraBffInternal && typeof auroraBffInternal.generateProductRecommendations === 'function'
              ? auroraBffInternal.generateProductRecommendations
              : null;
            if (!fn) throw new Error('aurora reco lane unavailable');
            return fn(args);
          },
          buildAsk: auroraBffInternal && typeof auroraBffInternal.buildRecoGenerateUserAsk === 'function'
            ? auroraBffInternal.buildRecoGenerateUserAsk
            : undefined,
          isEnabled: agentRecommendProductsEnabled,
          logger,
          budgetMs: Number(process.env.AURORA_BFF_RECOMMEND_PRODUCTS_AGENT_BUDGET_MS) > 0
            ? Number(process.env.AURORA_BFF_RECOMMEND_PRODUCTS_AGENT_BUDGET_MS)
            : undefined,
          // Live price re-verification: the same unscoped sig-detail lane get_product_detail routes to
          // (loopback get_pdp_v2 → normalizePdpV2ToProductDetail), so the shortlist's prices are the
          // PDP's, not a catalog snapshot. Identity-free on purpose (no buyer_ref, no agent JWT): this
          // is a cached-read-class lookup and the upstream should see one identity, same rationale as
          // the cached search lane. The bridge bounds concurrency/latency and treats null as
          // "unavailable" — so this function only ever answers {price, currency, in_stock} or null.
          verifyPrice: !['0', 'false', 'off'].includes(String(process.env.AGENT_RECOMMEND_PRODUCTS_PRICE_VERIFY_ENABLED || '').trim().toLowerCase())
            ? async ({ product_id: productId }) => {
              const pid = String(productId || '').trim();
              if (!pid) return null;
              const response = await axios.post(
                `${selfInvokeBase()}/agent/shop/v1/invoke`,
                { operation: 'get_pdp_v2', payload: { product_ref: { product_id: pid }, include: ['product_overview'] } },
                {
                  // Default 5000, raised from 2000: the loopback get_pdp_v2 measures ~4.7s on the
                  // sig->ext resolution path (2026-08-21), so the old default aborted every live-price
                  // check exactly when a price needed verifying. The bridge's own race backstop is 6500ms
                  // and must stay ABOVE this number.
                  timeout: Number(process.env.AGENT_RECOMMEND_PRODUCTS_PRICE_VERIFY_TIMEOUT_MS) > 0
                    ? Number(process.env.AGENT_RECOMMEND_PRODUCTS_PRICE_VERIFY_TIMEOUT_MS)
                    : 5000,
                  headers: {
                    'Content-Type': 'application/json',
                    ...buildInvokeUpstreamAuthHeaders({
                      allowInternalFallback: true,
                      preferInternalFallback: true,
                      forwardAgentUserJwt: false,
                      forwardBuyerRef: false,
                    }),
                  },
                  validateStatus: () => true,
                },
              );
              // A DEFINITIVE not-found — HTTP 404 carrying the PRODUCT_NOT_FOUND envelope — means the
              // id this item would advertise is dead on the very lane get_product serves, and the
              // bridge drops the item rather than handing an agent an id that 404s one call later
              // (live repro 2026-08-26: the lane's top picks answered NO_MERCHANT_OFFER on
              // get_product). ONLY the proven envelope buys the drop: any other failure — timeout,
              // 5xx, a 404 without the code — stays null ("price unavailable"), because
              // cannot-verify must never buy a delisting. The classification is the exported pure
              // function so its tests pin THIS line's behavior, not a copy.
              const classified = classifyVerifyPriceResponse(response.status, response.data);
              if (classified !== undefined) return classified;
              const { product } = normalizePdpV2ToProductDetail(response.data);
              if (!product || typeof product.price !== 'number') return null;
              return { price: product.price, currency: product.currency, in_stock: product.in_stock };
            }
            : undefined,
        }),
      };
      const executor = createCanonicalExecutor({
        kernel: commerce.kernel,
        upstream: invokeCommerceKernelRawUpstream,
        verifyPaymentAuthorization,
        hostedLinkEnabled: isAgentCheckoutHostedLinkEnabled(),
        localReads,
        // AP2: checkout sessions carry the merchant-signed Checkout JWT a wallet hashes into
        // its mandate. Best-effort inside the executor; a mint failure logs here and costs
        // only AP2 (which then fails closed at verification), never the session.
        mintAp2CheckoutJwt: isAp2MandateEnabled()
          ? async (input) => {
            try {
              const binding = await getAp2CheckoutBinding();
              return binding ? binding.mintCheckoutJwt(input) : undefined;
            } catch (err) {
              logger.warn({ code: err?.code || 'AP2_MINT_FAILED' }, 'ap2 checkout jwt mint failed');
              return undefined;
            }
          }
          : undefined,
        // ACP delegated-PSP-token lane (Stripe SharedPaymentToken). The executor is kernel-side and stays
        // transport-agnostic, so the HTTP call lives here, beside the other upstream money calls, and rides
        // the SAME auth headers / timeout / error taxonomy as create_order and submit_payment.
        //
        // The token is passed through to the request body and NOWHERE else — it is never logged, never put in
        // an error detail, and never persisted. amount/currency arrive from the kernel's own order record but
        // are deliberately not forwarded (the backend prices from the order); they are accepted here only so
        // the dispatcher signature documents what the kernel pinned.
        //
        // The response is put through the SAME normalizer the kernel's own submit_payment lane uses
        // (`normalizeRealUpstream: true` above wraps that one via wrapUpstream; this call bypasses the wrap
        // because it is not a kernel `_upstream` op). Without it a backend that answers `status` /
        // `payment_intent_id` instead of `payment_status` / `payment_id` would leave the kernel with an
        // unclassifiable status AND no payment_id — the order would sit in charge_pending forever, because
        // onPaymentWebhook refuses to transition an attempt it cannot correlate.
        submitDelegatedPayment: async ({ order_id, idempotency_key, token }) => {
          const raw = await invokeCommerceKernelRawUpstream(
            'submit_delegated_payment',
            { order_id, idempotency_key, token },
            { 'Idempotency-Key': idempotency_key },
          );
          const { normalizeSubmitPayment } = await (commerceKernelUpstreamAdapterPromise ||= import('../safety-kernel/src/upstreamAdapter.js'));
          return normalizeSubmitPayment(raw);
        },
        // Thunk, not a boolean: this executor is memoized for the process lifetime, so a boolean would freeze
        // the flag at first build and make the kill-switch un-flippable without a redeploy.
        delegatedTokenHandoffEnabled: () => isAcpSptGatewayHandoffEnabled(),
      });
      // Publish the executor for the ACP/UCP doors to reuse (one shared kernel — see commerceSharedExecutor).
      commerceSharedExecutor = executor;
      const surface = createCommerceToolSurface(executor, {
        log: logger,
        // MERCHANT VARIANT SOURCING. Our catalog publishes no real variant identity for the seed cohort, so
        // intake refuses every such row (`no_real_variant_identity`). The storefront it was crawled from does
        // publish one, over the same UCP endpoint the warm handoff already uses. Default OFF: this adds a
        // third-party call to the checkout intake path, so it is armed deliberately.
        // Always constructed; the source consults `isMerchantVariantSourcingEnabled()` per call, so the flag
        // is live rather than frozen at surface-construction time.
        sourceMerchantVariants: buildMerchantVariantSource(logger),
      });
      // …and the surface, for the UCP door to project (one shared read cache — see commerceSharedToolSurface).
      commerceSharedToolSurface = surface;
      return createRemoteMcpAdapter(surface, {
        serverInfo: { name: 'pivota-commerce-mcp', version: '0.1.0' },
        authenticate: async (req) => {
          if (req?.authInfo?.invoke_authenticated !== true) {
            throw new Error('MCP channel authentication is required.');
          }
          return { sessionContext: req.authInfo.sessionContext || {} };
        },
        resolveSessionContext: (req, authResult) =>
          authResult?.sessionContext || req?.authInfo?.sessionContext || {},
      });
    })();
  }
  return commerceRemoteMcpAdapterPromise;
}

async function getCommerceConfirmationActionHandler() {
  if (!commerceConfirmationActionHandlerPromise) {
    commerceConfirmationActionHandlerPromise = (async () => {
      const commerce = await getCommerceMount();
      const { createConfirmationActionHandler } = await import('../mcp-server/src/confirmationAction.js');
      return createConfirmationActionHandler({
        commerce,
        authenticate: async (req) => ({ sessionContext: req?.authInfo?.sessionContext || {} }),
        resolveSessionContext: (req, authResult) =>
          authResult?.sessionContext || req?.authInfo?.sessionContext || {},
        verifyUserAction: verifyCheckoutConfirmationUserAction,
      });
    })();
  }
  return commerceConfirmationActionHandlerPromise;
}

// ---- PUBLIC read-only MCP tier (auth:none) ----------------------------------------------------------------
// The app-directory-facing read surface (OpenAI Apps SDK): the four discovery/intelligence read tools over
// the SAME shared canonical executor as /mcp — one kernel, never a second. Anonymous by construction (empty
// session context; user-scoped tools are not on the surface at all — see mcp-server/src/publicReadToolSurface).
// Deliberately INDEPENDENT of AGENT_CHECKOUT_STRICT: the checkout kill-switch must never 404 the read app once
// it is listed in a directory. Fail-closed: dark unless PUBLIC_READ_MCP_ENABLED is set. Served on
// POST /public/mcp (any host — pre-DNS testing) and on POST /mcp when the request arrives via a public app
// origin (PUBLIC_READ_MCP_HOSTS, default mcp.pivota.cc — a custom domain on this same service preserves the
// path, so the branded origin must dispatch by Host).

// ---- the search -> get_product chain contract -------------------------------------------------------------
// The whole point of the read pair is that an id from search can be fetched. It could not: measured on prod
// 2026-07-25, 22 of 99 public search results (14 queries) returned ids get_product refused, and for "serum" 9
// of the top 10. Every one of the 21 distinct dead ids was also absent from the sitemap and served a shell PDP
// — they are not "temporarily unavailable", they have no content route at all.
//
// The public tier resolves UNSCOPED detail through get_pdp_v2's signature lane (see the get_product_detail
// case in invokeCommerceKernelRawUpstream). This predicate asks that lane's OWN resolver whether an id would
// resolve, rather than re-deriving a second predicate over catalog_products: services/pdpRenderability.js
// documents at length what re-derivation costs when the twins drift (rows advertised renderable that then
// 404). Two measured cohorts are removed, both decided off the resolver's own row:
//   1. a non-signature id (e.g. `rejuran:...`) never resolves on the unscoped lane at all — 0 of 5 sampled;
//   2. a seed-routed row with no acceptable seed on its content route.
// Everything else is KEPT — see the drop-only-what-is-provably-dead note on publicReadDetailResolves.
//
// FAIL-OPEN by construction: any resolver error, timeout, or missing DATABASE_URL keeps the row. A blank
// public search is a worse failure than a dead id, and a dead id that slips through now returns an honest
// non-retriable error rather than an invitation to retry forever — NO_MERCHANT_OFFER when the id is real but
// nothing serves it, UNKNOWN_PRODUCT_ID when it resolves to nothing at all.
const { chainRowResolvable } = require('./services/publicReadChainResolvability');
const { describeCaller } = require('./services/callerIdentity');
const { decideUiChatAccess } = require('./services/uiChatAccessGuard');
const { decideAuroraSurfaceAccess, isAuroraSurfacePath } = require('./services/auroraSurfaceHostGuard');
const { decideAuroraSurfaceAuth } = require('./services/auroraSurfaceAuth');
const { createAuroraAuthRollup } = require('./services/auroraSurfaceAuthRollup');

const PUBLIC_READ_CHAIN_FILTER_CONCURRENCY = 8;

function isPublicReadChainFilterEnabled() {
  const raw = String(process.env.PUBLIC_READ_CHAIN_FILTER_ENABLED ?? '').trim().toLowerCase();
  if (raw === '') return true; // default ON — the contract is the product
  return !['0', 'false', 'off', 'no'].includes(raw);
}

// The decision itself lives in services/publicReadChainResolvability so it is unit-testable without a DB —
// see that file for the drop-only-what-is-provably-dead rationale and the fail-open lanes.
async function publicReadDetailResolves(productId) {
  const pid = String(productId || '').trim();
  if (!pid) return false;
  // Skip the DB round-trip entirely for ids the detail lane cannot resolve by construction.
  if (!isPivotaSignatureProductId(pid)) return false;
  const ref = await resolveCatalogProductRefFromPivotaSignature(pid);
  return chainRowResolvable(pid, ref, isPivotaSignatureProductId);
}

async function filterPublicReadChainResolvableRows(rows) {
  const list = Array.isArray(rows) ? rows : [];
  if (!list.length || !isPublicReadChainFilterEnabled() || !process.env.DATABASE_URL) {
    return { kept: list, droppedCount: 0 };
  }
  const verdicts = new Array(list.length).fill(true);
  let cursor = 0;
  const worker = async () => {
    for (let i = cursor++; i < list.length; i = cursor++) {
      const row = list[i];
      const pid = firstNonEmptyString(row?.pivota_signature_id, row?.product_id, row?.id);
      try {
        verdicts[i] = await publicReadDetailResolves(pid);
      } catch (err) {
        // Fail-open on this row only — see the FAIL-OPEN note above.
        logger.warn(
          { err: err?.message || String(err), product_id: pid },
          'public_read chain filter: resolvability probe failed (row kept)',
        );
        verdicts[i] = true;
      }
    }
  };
  await Promise.all(
    Array.from({ length: Math.min(PUBLIC_READ_CHAIN_FILTER_CONCURRENCY, list.length) }, worker),
  );
  const kept = list.filter((_, i) => verdicts[i]);
  return { kept, droppedCount: list.length - kept.length };
}

function isPublicReadMcpEnabled() {
  return /^(1|true|yes|on|enabled)$/i.test(String(process.env.PUBLIC_READ_MCP_ENABLED || '').trim());
}

function publicReadMcpHosts() {
  return String(process.env.PUBLIC_READ_MCP_HOSTS || 'mcp.pivota.cc')
    .split(',')
    .map((host) => host.trim().toLowerCase())
    .filter(Boolean);
}

function isPublicReadMcpHostRequest(req) {
  // Trailing dot: `mcp.pivota.cc.` is a valid absolute-FQDN spelling of the same name and any
  // scanner tries it. The Railway edge refuses to route it today, so this is latent — but the GCP
  // migration replaces that edge, and an unstripped dot slips BOTH this predicate and the Aurora
  // host guard downstream of it.
  const host = String(req?.headers?.host || '').trim().toLowerCase().replace(/\.+$/, '').split(':')[0];
  return Boolean(host) && publicReadMcpHosts().includes(host);
}

let publicReadMcpAdapterPromise = null;
async function getPublicReadMcpAdapter() {
  if (!publicReadMcpAdapterPromise) {
    publicReadMcpAdapterPromise = (async () => {
      const executor = await getCommerceCanonicalExecutor();
      const { createPublicReadToolSurface, formatPublicReadToolResult } = await import('../mcp-server/src/publicReadToolSurface.js');
      const { createRemoteMcpAdapter } = await import('../mcp-server/src/remoteMcpAdapter.js');
      const surface = createPublicReadToolSurface(executor, {
        log: logger,
        filterChainResolvableRows: filterPublicReadChainResolvableRows,
      });
      return createRemoteMcpAdapter(surface, {
        allowUnauthenticated: true,
        serverInfo: { name: 'pivota', version: '1.0.0' },
        supportedProtocolVersions: ['2025-03-26', '2025-06-18'],
        resolveSessionContext: () => ({}),
        // Return structuredContent + a human summary for each read tool (docs/openai_apps_v1_plan.md §6).
        formatResult: formatPublicReadToolResult,
      });
    })();
  }
  return publicReadMcpAdapterPromise;
}

let publicReadMcpLimiter = null;
function getPublicReadMcpLimiter() {
  if (!publicReadMcpLimiter) {
    const { createTokenBucketLimiter } = require('./services/publicReadRateLimit');
    const rpm = Number(process.env.PUBLIC_READ_MCP_RPM) > 0 ? Number(process.env.PUBLIC_READ_MCP_RPM) : 60;
    const burst =
      Number(process.env.PUBLIC_READ_MCP_BURST) > 0
        ? Number(process.env.PUBLIC_READ_MCP_BURST)
        : Math.max(10, Math.ceil(rpm / 3));
    publicReadMcpLimiter = createTokenBucketLimiter({ capacity: burst, refillPerSecond: rpm / 60 });
  }
  return publicReadMcpLimiter;
}

// Rate-limit key = the real client IP. The LEFT-most X-Forwarded-For entry is client-supplied and spoofable
// (an attacker rotating it would land every request in a fresh bucket and defeat the limit), so we take the
// entry appended by our own trusted edge: the Nth-from-the-right, where N = trusted proxy hops in front of
// this service (Railway = 1). Configurable via PUBLIC_READ_TRUSTED_PROXIES. Falls back to the socket peer.
function publicReadTrustedProxyHops() {
  const n = Number(process.env.PUBLIC_READ_TRUSTED_PROXIES);
  return Number.isInteger(n) && n >= 1 ? n : 1;
}

function publicReadMcpClientKey(req) {
  const parts = String(req?.headers?.['x-forwarded-for'] || '')
    .split(',')
    .map((s) => s.trim())
    .filter(Boolean);
  if (parts.length) {
    // Nth-from-the-right (the hop our trusted edge saw as the client); clamp so a short chain still yields
    // the left-most real value rather than undefined.
    const idx = Math.max(0, parts.length - publicReadTrustedProxyHops());
    return parts[idx];
  }
  return req?.socket?.remoteAddress || req?.ip || 'unknown';
}

const PUBLIC_READ_MCP_MAX_BODY_BYTES = 32 * 1024;

// Railway's edge resets any response whose first BODY byte is later than ~13s after the request (measured
// ~16.4s wall-clock kill; headers don't count) — see services/publicReadMcpHeartbeat. Cold search runs
// 8–23s, so without this guard the partner's first uncached query is a dropped connection.
const { createMcpResponseHeartbeat } = require('./services/publicReadMcpHeartbeat');

// Committing locks the response to 200 FOREVER, so the heartbeat may only arm on a request whose outcome is
// guaranteed 200. `tools/call` is that method — and the only one that does real work, so the only one that
// can approach the deadline: every other method on this transport answers from memory in microseconds.
// One of them, `notifications/initialized`, legitimately answers 202 with a null body, which a commit would
// silently rewrite to 200 + a bare "\n" (not parseable JSON) — and it is NOT reliably instant, because the
// adapter warm-up and identity verification that precede the dispatch can outlive the delay on a cold
// container. An ALLOWLIST keeps the invariant true when a future method is added; a blocklist would not.
// The method is read synchronously from the already-parsed body, so this check costs no deadline margin.
function isMcpHeartbeatEligibleRequest(req) {
  const body = req && typeof req.body === 'object' && req.body !== null ? req.body : null;
  return Boolean(body) && body.method === 'tools/call';
}

function mcpToolNameFromRpcBody(rpcBody) {
  return rpcBody && rpcBody.method === 'tools/call' && rpcBody.params ? rpcBody.params.name : null;
}

// THE RULE, keyed on the CANONICAL operation id — never on one dialect's spelling of it.
//
// This used to compare the wire tool name directly against 'complete_checkout_session'. That is the MCP
// door's name for the charge; the UCP door calls the SAME canonical operation 'complete_checkout'. Mounting
// the UCP door against a name-keyed switch would have left the submit_payment kill-switch DARK on it: a UCP
// platform could charge while AGENT_CHECKOUT_STRICT_SUBMIT_PAYMENT_ENABLED=0 held the MCP door shut. Gating
// on the canonical id is what makes one kill-switch cover every dialect, present and future.
function blockedCommerceOperationForCanonicalOp(operationId) {
  if (operationId === 'complete_checkout_session' && !isAgentCheckoutStrictSubmitPaymentEnabled()) {
    return {
      operation: 'complete_checkout_session',
      reason: 'strict_submit_payment_disabled',
      message: 'submit_payment is disabled in strict checkout mode.',
    };
  }
  if (operationId === 'create_payment_link' && !isAgentCheckoutHostedLinkEnabled()) {
    return {
      operation: 'create_payment_link',
      reason: 'hosted_link_disabled',
      message: 'create_payment_link is disabled (AGENT_CHECKOUT_HOSTED_LINK_ENABLED=0).',
    };
  }
  return null;
}

// Money-path kill-switches, decided from the parsed JSON-RPC body alone (no adapter, no session context) so
// a refused op answers instantly. Returns null when nothing is blocked.
//
// On the MCP dialect the tool name IS the canonical operation id — canonicalContract defines `mcp` equal to
// `id` for every operation, which tests/commerce_ucp_mcp_door.node.test.cjs asserts rather than assumes, so
// this stays a synchronous lookup with no contract import on the hot path.
function resolveBlockedCommerceMcpOperation(rpcBody) {
  const toolName = mcpToolNameFromRpcBody(rpcBody);
  return toolName ? blockedCommerceOperationForCanonicalOp(toolName) : null;
}

// The same rule for the UCP dialect, whose tool names are the SPEC's (create_checkout, complete_checkout, …).
// The name→operation map is the canonical contract's, imported rather than restated: a second copy of the
// vocabulary here is exactly the drift that would silently re-dark this switch.
async function resolveBlockedUcpMcpOperation(rpcBody) {
  const toolName = mcpToolNameFromRpcBody(rpcBody);
  if (!toolName) return null;
  const { canonicalOpForUcpTool } = await getCommerceCanonicalContractModule();
  const op = canonicalOpForUcpTool(toolName);
  // An unknown UCP tool has no kill-switch to trip; the adapter answers it UNKNOWN_TOOL.
  if (!op) return null;
  const blocked = blockedCommerceOperationForCanonicalOp(op.id);
  return blocked ? { ...blocked, dialect: 'ucp', tool: toolName } : null;
}

/**
 * @param {string[]} prefixes env prefix chain, most specific first.
 * @param {{eligible?: boolean, elapsedMs?: number}} ctx per-request gating.
 */
function mcpHeartbeatOptionsFromEnv(prefixes, { eligible = true, elapsedMs = 0 } = {}) {
  // First non-empty value wins across the prefix chain (e.g. COMMERCE_MCP_* overriding PUBLIC_READ_MCP_*).
  const pick = (suffix) => {
    for (const prefix of prefixes) {
      const raw = process.env[`${prefix}_HEARTBEAT_${suffix}`];
      if (raw !== undefined && String(raw).trim() !== '') return String(raw).trim();
    }
    return '';
  };
  const enabledRaw = pick('ENABLED').toLowerCase();
  const delayRaw = Number(pick('DELAY_MS'));
  const intervalRaw = Number(pick('INTERVAL_MS'));
  const delayMs = delayRaw > 0 ? delayRaw : 6000;
  return {
    enabled: (enabledRaw === '' ? true : !['0', 'false', 'off', 'no'].includes(enabledRaw)) && eligible,
    // The module picks its default on the assumption that the delay runs from HANDLER ENTRY (see its note on
    // why 6s and not 13s). Anything awaited before the heartbeat is constructed — on the commerce lane, token
    // introspection and remote-JWKS identity verification, together several seconds worst case — is deadline
    // budget already spent, so subtract it. A budget fully consumed commits on the next tick, which is the
    // intended behaviour: that request is the one closest to being reset.
    delayMs: Math.max(0, delayMs - Math.max(0, Number(elapsedMs) || 0)),
    intervalMs: intervalRaw > 0 ? intervalRaw : 5000,
  };
}

function publicReadMcpHeartbeatOptions(ctx) {
  return mcpHeartbeatOptionsFromEnv(['PUBLIC_READ_MCP'], ctx);
}

// The commerce lane sits behind the SAME Railway edge with the same first-body-byte deadline, so it shares
// the public-tier knobs — one kill-switch stops both lanes, so disabling the public tier's guard in an
// incident silently disables this one too unless COMMERCE_MCP_HEARTBEAT_ENABLED=1 is set explicitly, which
// takes precedence (as does every other COMMERCE_MCP_HEARTBEAT_* value, per suffix).
function commerceMcpHeartbeatOptions(ctx) {
  return mcpHeartbeatOptionsFromEnv(['COMMERCE_MCP', 'PUBLIC_READ_MCP'], ctx);
}

async function handlePublicReadMcp(req, res) {
  if (!isPublicReadMcpEnabled()) {
    return res.status(404).json({ error: 'not_found' });
  }
  const contentLength = Number(req?.headers?.['content-length']);
  if (Number.isFinite(contentLength) && contentLength > PUBLIC_READ_MCP_MAX_BODY_BYTES) {
    return res.status(413).json({ error: 'payload_too_large' });
  }
  if (!getPublicReadMcpLimiter().allow(publicReadMcpClientKey(req))) {
    res.setHeader('Retry-After', '10');
    return res.status(429).json({ error: 'rate_limited', message: 'Too many requests; retry shortly.' });
  }
  // Explicit anonymous attribution context (same store the commerce door runs under) so downstream invoke
  // reads see a labeled public-tier caller instead of an absent store.
  return INVOKE_AUTH_CONTEXT.run(
    { path: req?.path || null, surface: 'mcp_public', auth_mode: 'public_read', auth_source: 'public_read' },
    async () => {
      const heartbeat = createMcpResponseHeartbeat(
        res,
        publicReadMcpHeartbeatOptions({ eligible: isMcpHeartbeatEligibleRequest(req) }),
      );
      try {
        const adapter = await getPublicReadMcpAdapter();
        const out = await adapter.handleJsonRpc({ headers: req.headers || {}, body: req.body });
        // finish() returns true when the heartbeat already committed the wire (slow path) and wrote the
        // body itself — every adapter path still running past the heartbeat delay is a tools/call, which
        // always resolves status 200, so committing early never masks a real non-200.
        if (heartbeat.finish(out)) return undefined;
        for (const [key, value] of Object.entries(out.headers || {})) {
          res.setHeader(key, value);
        }
        if (out.body == null) return res.status(out.status).end();
        return res.status(out.status).json(out.body);
      } catch (err) {
        logger.error({ err: err?.message || String(err) }, 'Public read MCP route failed');
        const rpcId = req?.body && typeof req.body === 'object' && req.body.id !== undefined ? req.body.id : null;
        if (heartbeat.fail({ jsonrpc: '2.0', id: rpcId, error: { code: -32603, message: 'Internal error.' } })) {
          return undefined;
        }
        return res.status(503).json({ error: 'mcp_unavailable' });
      }
    },
  );
}

function registerPublicReadMcpRoute() {
  app.post('/public/mcp', handlePublicReadMcp);
}

function registerCommerceRemoteMcpRoute() {
  app.post('/mcp', async (req, res) => {
    // Handler entry, not heartbeat construction: the auth channel below (token introspection, remote-JWKS
    // identity verification) can burn seconds of the edge's first-body-byte budget before the guard exists.
    const handlerEnteredAtMs = Date.now();
    // The branded public app origin (mcp.pivota.cc) maps to this same service and path, so /mcp dispatches
    // those requests to the auth:none read tier BEFORE any commerce gating — the public app must never
    // depend on the checkout kill-switch or the commerce auth channel.
    //
    // DELIBERATELY NOT on the UCP door: /ucp/mcp is a commerce-only door. The public read tier is served at
    // /mcp (branded host) and /public/mcp, and giving a second path an auth:none branch would widen the
    // unauthenticated surface for no reader that asked for it.
    if (isPublicReadMcpEnabled() && isPublicReadMcpHostRequest(req)) {
      return handlePublicReadMcp(req, res);
    }
    if (!isAgentCheckoutStrictEnabled()) {
      return res.status(404).json({ error: 'not_found' });
    }
    return serveCommerceMcpJsonRpc(req, res, {
      handlerEnteredAtMs,
      getAdapter: getCommerceRemoteMcpAdapter,
      resolveBlockedOperation: async (rpcBody) => resolveBlockedCommerceMcpOperation(rpcBody),
      failureLabel: 'Strict checkout remote MCP route failed',
    });
  });
}

/**
 * The COMMERCE MCP JSON-RPC request pipeline, shared by every dialect door.
 *
 * Extracted rather than copied when /ucp/mcp was mounted. A charge-capable door needs the OAuth front door,
 * the api-key channel, the invoke-auth context, the money kill-switches, the edge heartbeat and the
 * non-leaky error mapping — all of them, in this order. A second hand-written copy is how one door quietly
 * loses a guard the other keeps, which on this lane means a charge that should not have happened. The only
 * things a door supplies are its adapter, its dialect's kill-switch resolution, and its log label.
 *
 * The caller owns whatever must happen BEFORE this (public-read host dispatch, per-door enable flags), so
 * nothing here can accidentally re-open a door its own route decided to keep shut.
 */
async function serveCommerceMcpJsonRpc(req, res, { handlerEnteredAtMs, getAdapter, resolveBlockedOperation, failureLabel }) {
    // MCP OAuth front door (additive, gated by MCP_OAUTH_ENABLED). Lets a native frontier MCP
    // client (Claude/ChatGPT/Gemini) connect with an OAuth access token instead of a commerce
    // API key: the verified token is BOTH the channel credential and the user identity. Inert
    // when the flag is off — the existing api-key channel below is unchanged.
    let mcpOAuthOutcome = { mode: 'disabled' };
    try {
      mcpOAuthOutcome = await commerceMcpOAuth.resolveMcpOAuthIdentity(req);
    } catch (err) {
      logger.warn({ err: err?.message || String(err) }, 'mcp oauth resolution failed');
    }
    if (mcpOAuthOutcome.mode === 'challenge') {
      if (mcpOAuthOutcome.wwwAuthenticate) {
        res.setHeader('WWW-Authenticate', mcpOAuthOutcome.wwwAuthenticate);
      }
      return res.status(mcpOAuthOutcome.status || 401).json(
        mcpOAuthOutcome.body || { error: 'UNAUTHORIZED', message: 'Missing or invalid token' },
      );
    }

    const runMcp = async () => {
      return INVOKE_AUTH_CONTEXT.run(buildExternalInvokeContext(req), async () => {
        // The blocked-operation short-circuits run BEFORE the heartbeat exists. They decide purely from the
        // parsed body and two env flags — they never needed the adapter or the session context — so hoisting
        // them keeps a refused money op on the same instant, fully buffered path as the 404/401 refusals
        // instead of leaving a rarely-taken committed-wire branch behind the guard.
        const rpcBody = req?.body && typeof req.body === 'object' ? req.body : {};
        // GUARDED because this await can REJECT on the UCP door. /mcp's resolver is a synchronous lookup
        // that cannot throw; the UCP dialect's resolver reads its name→operation map from a dynamically imported
        // canonical contract, so a broken or partial deploy rejects here on the first UCP tools/call after
        // boot. Express 4 does not catch a rejected handler promise and this process installs no
        // `unhandledRejection` handler, so an unguarded rejection would take down the WHOLE gateway, not
        // just this request. 503 instead: no kill-switch was evaluated, so nothing is cleared to charge.
        let blockedOperation;
        try {
          blockedOperation = await resolveBlockedOperation(rpcBody);
        } catch (err) {
          logger.error({ err: err?.message || String(err) }, failureLabel);
          return res.status(503).json({ error: 'mcp_unavailable' });
        }
        if (blockedOperation) {
          recordCommerceKernelAudit({
            event: 'operation_blocked',
            // The CANONICAL operation, so one audit query covers every dialect; the dialect and the wire
            // tool name ride in detail, so a blocked UCP charge is still distinguishable from an MCP one.
            operation: blockedOperation.operation,
            detail: pruneEmptyFields({
              code: 'OPERATION_NOT_ALLOWED',
              reason: blockedOperation.reason,
              dialect: blockedOperation.dialect,
              tool: blockedOperation.tool,
            }),
          });
          return res.status(200).json(mcpToolErrorBody({
            id: Object.prototype.hasOwnProperty.call(rpcBody, 'id') ? rpcBody.id : null,
            code: 'OPERATION_NOT_ALLOWED',
            message: blockedOperation.message,
          }));
        }

        // Same Railway edge first-body-byte deadline as the public tier (services/publicReadMcpHeartbeat):
        // a commerce tools/call that outlives ~13s (cold search, slow checkout upstream) gets its connection
        // reset while the server completes uselessly. Two things make committing 200 here safe. First,
        // construction happens only AFTER every non-200 outcome this route can produce (strict-off 404,
        // OAuth challenge + WWW-Authenticate, api-key 401/403/503, blocked-op refusal), so a commit can
        // never mask a real status or drop a challenge header. Second, isMcpHeartbeatEligibleRequest arms it
        // for tools/call ONLY — the one method whose outcome is guaranteed 200, tool errors riding inside
        // the JSON-RPC body — instead of relying on the other methods being too fast to reach the delay.
        // Adapter headers are only content-type, which the heartbeat sets itself on commit.
        const heartbeat = createMcpResponseHeartbeat(res, commerceMcpHeartbeatOptions({
          eligible: isMcpHeartbeatEligibleRequest(req),
          elapsedMs: Date.now() - handlerEnteredAtMs,
        }));
        try {
          const adapter = await getAdapter();
          const sessionContext = mcpOAuthOutcome.mode === 'oauth'
            ? buildOAuthCommerceCtx(req, mcpOAuthOutcome)
            : await deriveStrictCommerceCtxAsync(req);
          const out = await adapter.handleJsonRpc({
            headers: req.headers || {},
            body: req.body,
            authInfo: buildStrictSessionAuthInfo(req, sessionContext),
            sessionContext,
          });
          if (heartbeat.finish(out)) return undefined;
          for (const [key, value] of Object.entries(out.headers || {})) {
            res.setHeader(key, value);
          }
          if (out.body == null) return res.status(out.status).end();
          return res.status(out.status).json(out.body);
        } catch (err) {
          logger.error({ err: err?.message || String(err) }, failureLabel);
          const rpcId = req?.body && typeof req.body === 'object' && req.body.id !== undefined ? req.body.id : null;
          if (heartbeat.fail({ jsonrpc: '2.0', id: rpcId, error: { code: -32603, message: 'Internal error.' } })) {
            return undefined;
          }
          return res.status(503).json({ error: 'mcp_unavailable' });
        }
      });
    };

    if (mcpOAuthOutcome.mode === 'oauth') {
      // OAuth access token authenticated the channel AND the user; skip the api-key channel.
      req.invokeAuth = {
        key_fingerprint: null,
        auth_source: 'mcp_oauth_bearer',
        auth_mode: 'mcp_oauth',
        agent_id: null,
        raw_token: null,
        cache_hit: false,
        introspect_auth_source: null,
      };
      return runMcp();
    }
    return requireExternalInvokeAuth(req, res, runMcp);
}

/**
 * POST /ucp/mcp — the UCP-DIALECT commerce door.
 *
 * The SAME executor, kernel, gates and money path as /mcp, addressed by the UCP spec's flat tool names and
 * its argument shapes (mcp-server/src/ucpArgumentAdapter.js). It is a projection, not a second surface, so
 * everything that makes a charge safe is the object being wrapped.
 *
 * TRIPLE-GATED, default dark:
 *   1. AGENT_CHECKOUT_STRICT              — the master money kill-switch, shared with /mcp and the ACP door.
 *   2. AGENT_CHECKOUT_UCP_TOOL_DOOR_ENABLED — this door's own flag.
 *   3. the per-operation kill-switches     — resolved on the CANONICAL op, so submit_payment's switch covers
 *      the UCP charge tool under its own name (see blockedCommerceOperationForCanonicalOp).
 * Both flags 404 rather than 403: a dark door must be indistinguishable from a route that does not exist.
 */
function registerCommerceUcpMcpRoute() {
  app.post('/ucp/mcp', async (req, res) => {
    // Same reason as /mcp: the auth channel below can burn seconds of the edge's first-body-byte budget.
    const handlerEnteredAtMs = Date.now();
    if (!isAgentCheckoutStrictEnabled() || !isAgentCheckoutUcpToolDoorEnabled()) {
      return res.status(404).json({ error: 'not_found' });
    }
    return serveCommerceMcpJsonRpc(req, res, {
      handlerEnteredAtMs,
      getAdapter: getCommerceUcpMcpAdapter,
      resolveBlockedOperation: resolveBlockedUcpMcpOperation,
      failureLabel: 'UCP dialect commerce MCP route failed',
    });
  });
}

function buildOAuthCommerceCtx(req, outcome) {
  // Identity for a native OAuth MCP client: user_ref comes from the verified access token, never
  // from the request body or a model-supplied value. acp_session_id binds the logical checkout
  // session — from a token session claim if present, else the MCP transport session id. If neither
  // is present it stays empty and the downstream USER_AUTH_REQUIRED check fails closed.
  const base = deriveStrictCommerceCtx(req);
  const claims = (outcome && outcome.claims) || {};
  const sessionId = resolveVerifiedCommerceSessionId(claims)
    || firstNonEmptyString(
      req?.header?.('mcp-session-id'),
      req?.header?.('Mcp-Session-Id'),
    );
  return pruneEmptyFields({
    ...base,
    user_ref: outcome.user_ref,
    acp_session_id: sessionId || base.acp_session_id,
    claims,
    identity_source: 'mcp_oauth',
    identity_diagnostics: { mcp_oauth: true, verified: true },
  });
}

function registerCommerceConfirmationActionRoute() {
  app.post('/checkout/confirm', async (req, res) => {
    if (!isAgentCheckoutStrictEnabled()) {
      return res.status(404).json({ error: 'not_found' });
    }
    return requireExternalInvokeAuth(req, res, async () => {
      return INVOKE_AUTH_CONTEXT.run(buildExternalInvokeContext(req), async () => {
        try {
          const handler = await getCommerceConfirmationActionHandler();
          const sessionContext = await deriveStrictCommerceCtxAsync(req);
          const out = await handler.handle({
            headers: req.headers || {},
            body: req.body,
            authInfo: buildStrictSessionAuthInfo(req, sessionContext),
            sessionContext,
          });
          for (const [key, value] of Object.entries(out.headers || {})) {
            res.setHeader(key, value);
          }
          return res.status(out.status).json(out.body);
        } catch (err) {
          logger.error({ err: err?.message || String(err) }, 'Strict checkout confirmation action failed');
          return res.status(503).json({ error: 'confirmation_action_unavailable' });
        }
      });
    });
  });
}

function registerCommerceStrictInvokeRoute(path, clientChannel) {
  app.post(path, async (req, res, next) => {
    const operation = String(req?.body?.operation || '').trim();
    if (!isAgentCheckoutStrictEnabled() || !AGENT_CHECKOUT_STRICT_MONEY_OPS.has(operation)) {
      return next();
    }

    if (operation === 'submit_payment' && !isAgentCheckoutStrictSubmitPaymentEnabled()) {
      recordCommerceKernelAudit({
        event: 'operation_blocked',
        operation,
        detail: {
          code: 'OPERATION_NOT_ALLOWED',
          reason: 'strict_submit_payment_disabled',
        },
      });
      return res.status(405).json(commerceKernelErrorBody({
        code: 'OPERATION_NOT_ALLOWED',
        message: 'submit_payment is disabled in strict checkout mode.',
        recovery: 'enable AGENT_CHECKOUT_STRICT_SUBMIT_PAYMENT_ENABLED after quote/order canary',
        retriable: false,
      }));
    }

    return requireExternalInvokeAuth(req, res, async () => {
      return INVOKE_AUTH_CONTEXT.run(buildExternalInvokeContext(req), async () => {
        try {
          if (operation === 'confirm_payment') {
            recordCommerceKernelAudit({
              event: 'operation_blocked',
              operation,
              detail: {
                code: 'OPERATION_NOT_ALLOWED',
                reason: 'legacy_confirm_payment_disabled',
              },
            });
            return res.status(405).json(commerceKernelErrorBody({
              code: 'OPERATION_NOT_ALLOWED',
              message: 'confirm_payment is disabled in strict checkout mode.',
              recovery: 'use submit_payment with confirmation_token',
              retriable: false,
            }));
          }

          const ctx = await deriveStrictCommerceCtxAsync(req);
          if (!ctx.user_ref || !ctx.acp_session_id) {
            recordCommerceKernelAudit({
              event: 'user_auth_blocked',
              operation,
              user_ref: ctx.user_ref,
              detail: {
                code: 'USER_AUTH_REQUIRED',
                reason: !ctx.user_ref ? 'missing_verified_user' : 'missing_verified_session',
                identity_diagnostics: ctx.identity_diagnostics || null,
              },
            });
            return res.status(401).json(commerceKernelErrorBody({
              code: 'USER_AUTH_REQUIRED',
              message: 'Verified user and session identity are required for checkout.',
              retriable: false,
              recovery: 'trigger OAuth',
            }));
          }

          const commerce = await getCommerceMount();
          if (!commerce.handles(operation)) return next();

          const out = await commerce.handle(operation, req?.body?.payload || {}, ctx);
          if (out?.ok === true) return res.status(200).json(out.data || {});

          const error = out?.error || { code: 'COMMERCE_ERROR' };
          return res.status(statusForCommerceKernelError(error.code)).json(commerceKernelErrorBody(error));
        } catch (err) {
          logger.error(
            {
              err: err?.message || String(err),
              operation,
              client_channel: clientChannel,
            },
            'Strict checkout kernel route failed',
          );
          return res.status(503).json({
            status: 'failure',
            error: 'COMMERCE_KERNEL_UNAVAILABLE',
            code: 'COMMERCE_KERNEL_UNAVAILABLE',
            message: 'Checkout is temporarily unavailable.',
          });
        }
      });
    });
  });
}

async function getPaymentWebhookHandler() {
  if (!paymentWebhookHandlerPromise) {
    paymentWebhookHandlerPromise = (async () => {
      const commerce = await getCommerceMount();
      const { createPaymentWebhookHandler } = await import('../safety-kernel/src/webhookHandler.js');
      return createPaymentWebhookHandler({
        kernel: commerce.kernel,
        secret: process.env.PAYMENT_WEBHOOK_SECRET || process.env.AGENT_CHECKOUT_WEBHOOK_SECRET,
        log: logger,
      });
    })();
  }
  return paymentWebhookHandlerPromise;
}

// ---- ACP REST + UCP discovery doors (shared-kernel additive) --------------------------------------------
// composeProductionCommerce builds its own kernel; to avoid a second kernel over the same backend (charge-once
// would hold only per-kernel), we reuse the SAME building blocks it assembles (createAcpRestAdapter /
// buildUcpProfile) but bind them to the EXISTING live executor/kernel that /mcp already uses. All three doors
// then share one kernel. Each door is fail-closed and double-gated (AGENT_CHECKOUT_STRICT + its enable flag),
// default OFF; the ACP charge endpoint is additionally gated by the submit_payment kill-switch.

let commerceUcpMcpAdapterPromise = null;
async function getCommerceUcpMcpAdapter() {
  // The UCP door is a PROJECTION of the commerce surface, not a second surface: same executor, same kernel,
  // same gates, different tool spelling. See mcp-server/src/commerceToolSurface.js ucpDialectSurface.
  if (!commerceUcpMcpAdapterPromise) {
    commerceUcpMcpAdapterPromise = (async () => {
      const { ucpDialectSurface } = await import('../mcp-server/src/commerceToolSurface.js');
      const { createRemoteMcpAdapter } = await import('../mcp-server/src/remoteMcpAdapter.js');
      // Project the /mcp door's OWN surface instance — same executor, same kernel, same gates, and the SAME
      // read cache. This used to build a second surface with `cache:false` on the premise that "the /mcp
      // surface already owns the shared commerce read cache"; the cache is per instance, so that premise was
      // false and the UCP door simply had no cache. Harmless while the dialect had no cacheable tool; not once
      // search_catalog is on it (tests/commerce_ucp_search_shared_cache.node.test.cjs pins the sharing).
      const surface = ucpDialectSurface(await getCommerceToolSurface());
      return createRemoteMcpAdapter(surface, {
        serverInfo: { name: 'pivota-commerce-ucp', version: '0.1.0' },
        authenticate: async (req) => {
          if (req?.authInfo?.invoke_authenticated !== true) {
            throw new Error('UCP channel authentication is required.');
          }
          return { sessionContext: req.authInfo.sessionContext || {} };
        },
        resolveSessionContext: (req, authResult) =>
          authResult?.sessionContext || req?.authInfo?.sessionContext || {},
      });
    })();
    commerceUcpMcpAdapterPromise.catch(() => { commerceUcpMcpAdapterPromise = null; });
  }
  return commerceUcpMcpAdapterPromise;
}

async function getCommerceCanonicalExecutor() {
  // Build (once) and return the shared executor. getCommerceRemoteMcpAdapter constructs it and publishes it to
  // commerceSharedExecutor as a side effect; calling it here just guarantees that has happened.
  if (!commerceSharedExecutor) await getCommerceRemoteMcpAdapter();
  if (!commerceSharedExecutor) throw new Error('commerce canonical executor unavailable');
  return commerceSharedExecutor;
}

async function getCommerceToolSurface() {
  // Same shape as getCommerceCanonicalExecutor, one level up: the /mcp door's surface instance, for the UCP
  // door to project so both share ONE read cache (see commerceSharedToolSurface).
  if (!commerceSharedToolSurface) await getCommerceRemoteMcpAdapter();
  if (!commerceSharedToolSurface) throw new Error('commerce tool surface unavailable');
  return commerceSharedToolSurface;
}

function extractAcpBuyerToken(req = {}) {
  // ACP defines no stable buyer id; the verified per-buyer credential arrives as a Bearer in
  // x-buyer-authorization (NEVER the platform signing channel, never the request body).
  const h = req?.headers || {};
  const raw = firstNonEmptyString(h['x-buyer-authorization'], h['X-Buyer-Authorization']);
  if (!raw) return undefined;
  const m = /^Bearer\s+(.+)$/i.exec(String(raw).trim());
  return m ? m[1].trim() : String(raw).trim();
}

async function getCommerceAcpRestAdapter() {
  if (!commerceAcpRestAdapterPromise) {
    const build = (async () => {
      const acpSigningSecret = firstNonEmptyString(
        process.env.ACP_SIGNING_SECRET,
        process.env.AGENT_CHECKOUT_ACP_SIGNING_SECRET,
      );
      if (!acpSigningSecret || acpSigningSecret.length < 16) {
        throw new Error('ACP REST requires ACP_SIGNING_SECRET (>=16 chars)');
      }
      const verifyUserToken = await getCommerceUserTokenVerifier();
      if (typeof verifyUserToken !== 'function') {
        throw new Error('ACP REST requires IDENTITY_ISSUERS_JSON (a per-buyer token verifier)');
      }
      const executor = await getCommerceCanonicalExecutor();
      const { createAcpRestAdapter } = await import('../safety-kernel/src/protocol/acpRestAdapter.js');
      const { PostgresKvStore } = await import('../safety-kernel/src/stores/postgresKvStore.js');
      const { InMemoryKvStore } = await import('../safety-kernel/src/stores.js');
      const db = buildCommerceKernelDb(); // throws in strict without DATABASE_URL → fail closed (durable state)
      const sessionStore = db
        ? new PostgresKvStore({ db, namespace: 'acp_sessions' })
        : new InMemoryKvStore();
      const resolveUserRef = async (req) => {
        const token = extractAcpBuyerToken(req);
        if (!token) return undefined;
        try {
          // Buyer-identity OBJECT, not the bare user_ref. The ACP door needs the ATTESTED buyer email so
          // that a caller-asserted `buyer.email` in the request body can only ever FILL a gap and can never
          // override what the verified credential asserted (PR-E / P1). user_ref derivation is unchanged —
          // still `iss|sub` via deriveUserRefFromClaims — and nothing about what the verifier ACCEPTS moved.
          // NOTE: `customer_email` is buyer PII. It is deliberately never logged here or anywhere on this
          // path; the warn below carries only an error code.
          const { user_ref, attested_email, attested_name } = await verifyUserToken(token);
          return { user_ref, customer_email: attested_email, customer_name: attested_name };
        } catch (err) {
          logger.warn({ code: err?.code || 'USER_TOKEN_INVALID' }, 'acp buyer token invalid');
          return undefined;
        }
      };
      // ADR-018 (pivota-backend) — the PRICED SERVING LANE. See
      // src/services/acpFeedSource.js for the full rationale; the short version
      // is that `find_products` with an empty query resolves to the
      // connected_catalog lane, every connected store is a rig, testMerchantPolicy
      // correctly empties it, and the feed has therefore served
      // `{"count":0,"products":[]}` for its whole life. The real serving catalog
      // (~4,467 priced, currency-bearing content_keys) lives behind the index
      // feed, and until this call existed NOTHING in the process referenced it.
      //
      // Source-selected by env, never by merge: with the flags unset the feed
      // still serves the connected lane below. NOT byte-identical to origin/main
      // even then — that lane gains the price gate in this same commit.
      //
      // ⚠️ CORRECTED 2026-07-28. An earlier version of this comment said the
      // connected lane "serves 0 rows today, so the difference is unobservable
      // until a real merchant connects". THAT IS FALSE, and measured on LIVE
      // PROD, not reasoned about. `express.json()` does not check the method, so
      // a GET carrying a JSON body reaches this lane with a real query:
      //
      //   GET /acp/feed  body {"query":{"query":"serum"}}  ->  200, count: 17
      //
      // Those 17 rows are why the price gate is observable immediately: one is
      // `{"brand":"Veganifect","price":0}`, which this gate now DROPS. The
      // change is right; the "unobservable" justification for it was not, and a
      // reader would have trusted it to rule the question out.
      //
      // The same 17 rows are the argument for flipping the index-feed flags:
      // every one carries an `ext_*` id whose PDP returns HTTP 500, and 7 are
      // Mintree priced 847-3927.70 labelled "USD" (the INR-served-as-USD
      // defect). The index lane emits `sig_*`, excludes those merchants, and
      // gates on price — so this door stops publishing all three the moment it
      // is the source.
      const {
        fetchIndexFeedProducts,
        isIndexFeedSourceEnabled,
        isIndexFeedLaneServable,
        buildConnectedLaneQuery,
      } = require('./services/acpFeedSource');
      // Attributed-redirect lane D1: feed `link` = Pivota canonical PDP; the signed /r attribution link
      // rides as `external_redirect_url`. Mapper is a pure module so the projection is unit-tested
      // (tests/acp_feed_item.node.test.cjs); sanitizer preservation is shape-gated in resultSanitizer.
      // Declared BEFORE `getProducts` because the connected lane's price gate
      // below calls it — it would resolve anyway (the closure only runs on a
      // request, long after this const is initialised), but a reader should not
      // have to reason about the TDZ to check that.
      const { buildAcpFeedItem } = require('./acpFeedItem');
      const { gatePublicFeedRows } = require('./services/publicFeedGate');
      const mapFeedItem = (p) => buildAcpFeedItem(p, { buildPublicProductUrl });
      const getProducts = async (query) => {
        // No `env` passed on purpose — the gate then reads the SAME process.env
        // object that productEntityIndexFeed's own INDEX_FEED_ELECTED_CANONICAL
        // check reads, so the two cannot disagree in production.
        if (isIndexFeedLaneServable()) {
          // LOG-AND-RETHROW, not catch-and-degrade. The adapter's `guard()`
          // (safety-kernel/src/protocol/acpRestAdapter.js:385-394) turns any
          // throw here into a bare 500 `INTERNAL_ERROR` and logs NOTHING, and
          // the route's own try/catch never sees it. Before this lane existed
          // the feed never touched Postgres on this path — it always answered
          // `200 {count:0}` — so wiring it converts a DB blip into an UNLOGGED
          // 500 on a public, externally-ingested surface. That is undiagnosable
          // from the outside: an ingester reports our feed as broken and we
          // have no line to correlate it against.
          //
          // Rethrowing on purpose. Falling back to the connected lane here
          // would answer 200 with the WRONG catalog while the real lane is
          // down, which is [[feedback_no_execution_layer_fallbacks]] applied to
          // discovery — a silent wrong answer is worse than an honest error.
          try {
            return await fetchIndexFeedProducts(query, { getProductEntityIndexFeed, logger });
          } catch (err) {
            logger.error(
              {
                surface: 'acp_public_feed',
                source: 'index_feed',
                err: err?.message || String(err),
                code: err?.code,
              },
              'acp feed: priced serving lane failed — the public feed is answering 500',
            );
            throw err;
          }
        }
        if (isIndexFeedSourceEnabled()) {
          // Source selected, election flag off. The lane refuses to serve in this
          // state (it is the ~1.5% dead-link state), so we fall through to the
          // connected lane rather than 503 a public discovery surface — but a
          // silent fallback is exactly the "reports success, does nothing" shape
          // this repo keeps shipping, so it is logged at WARN with the fix in the
          // message. An operator who flipped one flag sees why the feed is still
          // empty instead of re-deriving it from the count.
          logger.warn(
            { surface: 'acp_public_feed', source: 'index_feed', missing: 'INDEX_FEED_ELECTED_CANONICAL' },
            'acp feed: ACP_FEED_SOURCE=index_feed ignored — set INDEX_FEED_ELECTED_CANONICAL=1 to serve the priced lane',
          );
        }
        // CLAMP ON THIS LANE TOO. The index lane clamps via
        // `clampLimit(query?.limit)` (max 100) inside `fetchIndexFeedProducts`;
        // this one passed `query` through raw, so once the query string is
        // forwarded a `?limit=999999999` would travel upstream unbounded.
        //
        // Zero impact while both index flags are on (the lane above returns
        // early) — but the fallback is precisely where this PR's own risk
        // argument lives, so it should not be the unclamped one.
        //
        // Note `page`/`cursor` are NOT translated here: this lane has no paging
        // contract, so an ingester walking `page=2,3,4…` against it would
        // silently re-receive page 1. That is a gap in the fallback, recorded
        // rather than papered over — it only becomes reachable if the index
        // flags are ever unset.
        const raw = await invokeCommerceKernelRawUpstream('find_products', buildConnectedLaneQuery(query));
        const products = Array.isArray(raw?.products) ? raw.products : (Array.isArray(raw) ? raw : []);
        // Defence-in-depth against test/demo rigs reaching a PUBLIC agent-facing
        // surface. The feed's find_products(empty query) falls back to the
        // backend multi-search connected_catalog lane, which is gated only by
        // _is_product_sellable (status+orderable) — NOT by the shared
        // activeCatalogProductSourceWhere source gate — so the SQL test-merchant
        // exclusion does not reach it. This runtime leg is the one that actually
        // stops the live leak (all 20 feed items on 2026-07-23 were rigs). See
        // testMerchantPolicy.js for the shared source of truth; merchant_id
        // survives to the product payload via _standard_to_shop_product.
        // THE SAME GATE THE INDEX LANE USES (issue #1847). This lane used to
        // hand-assemble its own chain and it was missing the LINK-SHAPE gate —
        // measured on prod 2026-07-28, an unsigned GET with a JSON body served
        // 17 rows and all 17 carried `ext_*` ids whose PDP answers HTTP 500.
        // The block on those merchants was never broken; this door simply never
        // read it.
        //
        // Behaviour change, stated: rows whose id is not a `sig_` will now be
        // DROPPED rather than published with a dead link. If the index flags are
        // ever unset, this lane returns fewer rows — which is the correct
        // trade. An empty feed costs one submission; a feed of 500s costs the
        // domain's credibility with the ingester.
        //
        // NOT closed by this gate: currency correctness. An INR price labelled
        // "USD" is indistinguishable from a real USD price here — that needs the
        // offer's suppression state, which only reaches the index lane. See the
        // header of services/publicFeedGate.
        const { items: quotable } = gatePublicFeedRows(products, {
          project: mapFeedItem,
          logger,
          lane: 'connected',
        });
        return quotable;
      };
      // ITEM IDENTITY: nothing extra is threaded for it, ON PURPOSE. The door resolves an item's default
      // variant through the canonical `get_product` read on the SHARED executor passed right below — the
      // same read /mcp serves — so it needs no second transport and no second credential. That is what
      // keeps `buildQuotePreviewV2Body`'s `variant_id = variant_id || sku || product_id` fallback (still in
      // this file, still used by the other lanes, deliberately unchanged) from ever being what fills the
      // field on the ACP lane: by the time a quote leaves the door, every item carries an id the PRODUCT
      // READ returned, or the request was refused. See the item-identity section in acpRestAdapter.js.
      return createAcpRestAdapter({
        executor,
        sessionStore,
        signingSecret: acpSigningSecret,
        resolveUserRef,
        getProducts,
        mapFeedItem,
        // The resolution read is bounded so it cannot stall session creation, and expiry REFUSES. That makes
        // the bound operationally load-bearing: if the product-detail lane slows down, every variant-less
        // cart starts refusing. `undefined` keeps the adapter's own short default (3s); this env exists so
        // the bound can be moved without a deploy.
        variantResolutionTimeoutMs: Number(process.env.ACP_ITEM_VARIANT_RESOLUTION_TIMEOUT_MS) > 0
          ? Number(process.env.ACP_ITEM_VARIANT_RESOLUTION_TIMEOUT_MS)
          : undefined,
        // Env-gated (ACP_PUBLIC_FEED). Only relaxes the FEED's signature check;
        // checkout endpoints stay signature-gated. A public catalog feed is how
        // frontier discovery surfaces (ChatGPT/Google shopping) ingest the index.
        publicFeed: isAcpPublicFeedEnabled(),
      });
    })();
    // Do NOT memoize a REJECTED build: a truthy rejected promise would 503 every
    // /acp request permanently (even the feed), long after ACP_SIGNING_SECRET is
    // set, until restart. Cache only on success; a failed build retries next call.
    build.catch(() => { commerceAcpRestAdapterPromise = null; });
    commerceAcpRestAdapterPromise = build;
  }
  return commerceAcpRestAdapterPromise;
}

let commerceCanonicalContractModulePromise = null;
function getCommerceCanonicalContractModule() {
  if (!commerceCanonicalContractModulePromise) {
    commerceCanonicalContractModulePromise = import('../safety-kernel/src/protocol/canonicalContract.js');
    // Never memoize a rejected import (same rationale as the ACP adapter / UCP profile modules).
    commerceCanonicalContractModulePromise.catch(() => { commerceCanonicalContractModulePromise = null; });
  }
  return commerceCanonicalContractModulePromise;
}

function getCommerceUcpProfileModule() {
  if (!commerceUcpProfileModulePromise) {
    commerceUcpProfileModulePromise = import('../safety-kernel/src/protocol/ucpProfile.js');
    // Never memoize a rejected import (same rationale as the ACP adapter above).
    commerceUcpProfileModulePromise.catch(() => { commerceUcpProfileModulePromise = null; });
  }
  return commerceUcpProfileModulePromise;
}

// Which UCP capability ids the profile must WITHHOLD, given the money kill-switch.
//
// With AGENT_CHECKOUT_STRICT dark the money doors are hard-404, so advertising the checkout capability
// would be lying to the platform; omitting it also withholds every operation it carries
// (create/update/complete/cancel _checkout_session AND create_payment_link).
//
// EXTRACTED SO IT CAN BE ASSERTED DIRECTLY. It used to be an inline ternary, and the tests that covered it
// asserted the SERVED profile with strict off. That stopped constraining anything once a strict-off profile
// began advertising no capabilities at all (no transport => nothing advertised): the served document is
// empty either way, so deleting this guard passed every suite. It is unobservable through the route today
// only because strict-off also means no transport — decouple the UCP door from AGENT_CHECKOUT_STRICT, which
// its own flag already invites, and this becomes load-bearing again with nothing watching it.
function ucpOmitCapabilityIdsForFlags() {
  return isAgentCheckoutStrictEnabled() ? [] : ['dev.ucp.shopping.checkout', 'dev.ucp.shopping.ap2_mandate'];
}

async function getCommerceUcpRouteHandlers() {
  // Built PER REQUEST (only the ESM import is memoized): env — base URL, signing keys, strict flag — is
  // read fresh each time, so a signing-key rotation or kill-switch flip is reflected on the next request
  // and a throwing build 503s only that request instead of caching a rejection forever.
  const resourceOrigin = (() => {
    try {
      return process.env.MCP_OAUTH_RESOURCE ? new URL(process.env.MCP_OAUTH_RESOURCE).origin : undefined;
    } catch {
      return undefined;
    }
  })();
  const baseUrl = firstNonEmptyString(
    process.env.UCP_BASE_URL,
    process.env.AGENT_CHECKOUT_UCP_BASE_URL,
    resourceOrigin,
  );
  if (!baseUrl) throw new Error('UCP discovery requires UCP_BASE_URL (https origin)');
  const { buildUcpProfile, createUcpRouteHandlers } = await getCommerceUcpProfileModule();
  const profile = buildUcpProfile({
    baseUrl, // buildUcpProfile enforces https
    // NO `restBasePath`. It used to be COMMERCE_ACP_BASE_PATH, so the UCP profile advertised a `rest`
    // transport pointing at the ACP door — which speaks ACP wire shapes, not UCP's. A platform following it
    // failed on the first call. buildUcpProfile now omits the transport unless a real UCP-REST door serves
    // there; UCP's own transport is MCP JSON-RPC (below).
    //
    // THE MCP TRANSPORT POINTS AT THE UCP-DIALECT DOOR, AND ONLY WHEN THAT DOOR IS LIT.
    //
    // This used to be `${baseUrl}/mcp` unconditionally — the Pivota-NATIVE door. A platform that read the
    // profile and called `create_checkout` there got an unknown-tool error, because /mcp only knows
    // `create_checkout_session`. That is the same "advertised but not executable" defect the `rest`
    // transport was fixed for, one transport over.
    //
    // When the door is dark the transport is OMITTED rather than pointed back at /mcp: an endpoint that
    // cannot serve a single UCP call is not a UCP transport, and advertising one is worse than advertising
    // none because it looks finished. buildUcpProfile drops the service entry for a falsy endpoint, so the
    // profile then honestly carries no transport at all — matching the capability filter below, which
    // already withholds the money capabilities while the checkout kill-switch is dark.
    mcpEndpoint: (isAgentCheckoutStrictEnabled() && isAgentCheckoutUcpToolDoorEnabled())
      ? `${baseUrl.replace(/\/+$/, '')}/ucp/mcp`
      : undefined,
    omitCapabilityIds: ucpOmitCapabilityIdsForFlags(),
    vendorCapabilityDocs: ucpVendorCapabilityDocs(),
  });
  return createUcpRouteHandlers(profile);
}

/**
 * Documents for Pivota's VENDOR capability `cc.pivota.insights` (get_alternatives / get_offers / get_intel on
 * the UCP door). The builder publishes the capability ONLY when BOTH a spec and a schema URL are supplied AND
 * both live on the namespace authority (pivota.cc); anything else withholds it — the same rule as a standard
 * capability with no hosted documents. So: set both env vars AFTER the documents return 200 on pivota.cc,
 * never before. Unset = withheld (today's behaviour), and the three tools stay callable on /ucp/mcp for a
 * platform that already knows them — callable-but-unadvertised is the harmless direction of that asymmetry.
 *
 * ALSO GATED ON THE RUNTIME FLAGS. Publishing the capability while the handlers are dark would advertise
 * a decision layer that answers `signals: []` for every call — indistinguishable, to the platform, from
 * "we have no reviewed intelligence for this product", which is exactly the advertised-but-not-executable
 * defect the withholding filter exists to prevent. Both agent-surface flags must be on.
 */
function ucpVendorCapabilityDocs() {
  const spec = firstNonEmptyString(process.env.UCP_INSIGHTS_SPEC_URL);
  const schema = firstNonEmptyString(process.env.UCP_INSIGHTS_SCHEMA_URL);
  if (!spec || !schema) return {};
  const flagOn = (name) => /^(1|true|yes|on|enabled)$/i.test(String(process.env[name] || '').trim());
  if (!flagOn('AURORA_BFF_RELATIONSHIP_GRAPH_AGENT_ENABLED') || !flagOn('AURORA_BFF_PRODUCT_INTEL_AGENT_ENABLED')) {
    return {};
  }
  return { 'cc.pivota.insights': { spec, schema } };
}

const ACP_PUBLIC_FEED_MAX_BODY_BYTES = 32 * 1024;
let acpPublicFeedLimiter = null;
function getAcpPublicFeedLimiter() {
  if (!acpPublicFeedLimiter) {
    const { createTokenBucketLimiter } = require('./services/publicReadRateLimit');
    const rpm = Number(process.env.ACP_PUBLIC_FEED_RPM) > 0 ? Number(process.env.ACP_PUBLIC_FEED_RPM) : 60;
    const burst =
      Number(process.env.ACP_PUBLIC_FEED_BURST) > 0
        ? Number(process.env.ACP_PUBLIC_FEED_BURST)
        : Math.max(10, Math.ceil(rpm / 3));
    acpPublicFeedLimiter = createTokenBucketLimiter({ capacity: burst, refillPerSecond: rpm / 60 });
  }
  return acpPublicFeedLimiter;
}

// UCP order-webhook: same public-door protections as the ACP public feed — the receiver's own auth is
// the signature check, but that runs AFTER a JWKS fetch, so an unauthenticated flood is still a cost.
let ucpOrderWebhookLimiter = null;
function getUcpOrderWebhookLimiter() {
  if (!ucpOrderWebhookLimiter) {
    const { createTokenBucketLimiter } = require('./services/publicReadRateLimit');
    const rpm = Number(process.env.UCP_ORDER_WEBHOOK_RPM) > 0 ? Number(process.env.UCP_ORDER_WEBHOOK_RPM) : 60;
    const burst =
      Number(process.env.UCP_ORDER_WEBHOOK_BURST) > 0
        ? Number(process.env.UCP_ORDER_WEBHOOK_BURST)
        : Math.max(10, Math.ceil(rpm / 3));
    ucpOrderWebhookLimiter = createTokenBucketLimiter({ capacity: burst, refillPerSecond: rpm / 60 });
  }
  return ucpOrderWebhookLimiter;
}

let commerceDelegatedPaymentRefusalModulePromise = null;
function getCommerceDelegatedPaymentRefusalModule() {
  if (!commerceDelegatedPaymentRefusalModulePromise) {
    commerceDelegatedPaymentRefusalModulePromise = import('../safety-kernel/src/protocol/delegatedPaymentRefusal.js');
    // Never memoize a rejected import (same rationale as the ACP adapter / UCP profile modules above).
    commerceDelegatedPaymentRefusalModulePromise.catch(() => { commerceDelegatedPaymentRefusalModulePromise = null; });
  }
  return commerceDelegatedPaymentRefusalModulePromise;
}

function registerCommerceDelegatePaymentRefusalRoute() {
  // POST /acp/agentic_commerce/delegate_payment — a PERMANENT, unconditional refusal.
  //
  // Newly reachable: this path previously fell through to the 404 handler in every configuration. It now
  // answers 501 with a named reason. That is not a new capability — nothing here touches the kernel, the
  // executor, the session store, a secret, or the request body — it is the replacement of a silent 404 (which
  // reads as "wrong path / not deployed yet" and sends integrators hunting) with the true, actionable fact.
  //
  // Deliberately NOT gated by AGENT_CHECKOUT_STRICT / AGENT_CHECKOUT_ACP_REST_ENABLED, unlike every route
  // below. Those flags gate money paths; this endpoint will never be a money path in any configuration, so a
  // config-dependent answer would only make the refusal harder to discover without making anything safer.
  //
  // Deliberately does NOT read req.body / req.rawBody / req.headers. An ACP delegate_payment body carries raw
  // cardholder data (FPAN + CVC); the express.json verify hook above already refuses to stash rawBody for this
  // exact path, and nothing here re-reads it, logs it, or echoes it back.
  app.post(`${COMMERCE_ACP_BASE_PATH}${ACP_DELEGATE_PAYMENT_SUBPATH}`, async (req, res) => {
    try {
      const { delegatedPaymentRefusalAcpResponse } = await getCommerceDelegatedPaymentRefusalModule();
      const out = delegatedPaymentRefusalAcpResponse();
      return res.status(out.status).json(out.body);
    } catch (err) {
      // The refusal module is constants with no dependencies, so this is unreachable in practice. If the
      // import ever does fail, still answer the refusal — degraded to its core fact, never a 503 that would
      // invite a retry of a request carrying card data. No `err` detail is logged: the only interesting
      // context here would be the request, which must not be touched.
      logger.error({ surface: 'acp_rest', handler: 'delegatePayment' }, 'delegated-payment refusal module unavailable');
      return res.status(501).json({
        type: 'error',
        code: 'OPERATION_NOT_ALLOWED',
        message: 'Pivota does not implement delegated payment vaulting. This endpoint belongs to the merchant\'s PSP.',
      });
    }
  });
}

function registerCommerceAcpRestRoutes() {
  // The 5 ACP checkout endpoints + product feed, mounted under COMMERCE_ACP_BASE_PATH. Platform authenticity is
  // the adapter's HMAC Signature/Timestamp (verifyAcpSignature over the exact rawBody) — NOT a Pivota key — so
  // these routes do not run requireExternalInvokeAuth; the backend /invoke uses the internal service credential.
  const routes = [
    ['post', '/checkout_sessions', 'createCheckoutSession', false],
    ['post', '/checkout_sessions/:checkout_session_id/complete', 'completeCheckoutSession', true],
    ['post', '/checkout_sessions/:checkout_session_id/cancel', 'cancelCheckoutSession', false],
    ['post', '/checkout_sessions/:checkout_session_id', 'updateCheckoutSession', false],
    ['get', '/checkout_sessions/:checkout_session_id', 'getCheckoutSession', false],
    ['get', '/feed', 'productFeed', false],
  ];
  // Allow-list, not a filter: builds a NEW object holding at most these three
  // keys, so nothing else in `req.query` can reach a lane no matter what a
  // caller sends. Returns undefined when none are present, so the adapter's
  // existing `?? params ?? {}` chain is untouched for an ordinary GET.
  //
  // Array-valued params (`?limit=1&limit=2` parses to `['1','2']`) are DROPPED
  // rather than coerced: `Number(['1','2'])` is NaN, which clampLimit would
  // silently swallow into its 20 default — a caller asking for 100 and getting
  // 20 with no error. An absent key at least behaves predictably.
  const pickAcpFeedPagination = (q) => {
    if (!q || typeof q !== 'object') return undefined;
    const out = {};
    for (const k of ['limit', 'cursor', 'page']) {
      // `Object.hasOwn` so a polluted `Object.prototype.limit` — set by any
      // OTHER pollution primitive in the process — cannot be read off a plain
      // `{}` on every request. It cannot widen the key surface (only these
      // three literals are ever written), so this is hardening, not a hole.
      if (!Object.hasOwn(q, k)) continue;
      const v = q[k];
      if (typeof v === 'string' && v.trim() !== '') out[k] = v.trim();
    }
    return Object.keys(out).length ? out : undefined;
  };

  for (const [method, subPath, handlerName, isCharge] of routes) {
    // The read-only feed mounts under the feed flag (which the full-checkout flag
    // implies); every checkout endpoint requires the full flag. So publishing the
    // feed never mounts a money-path endpoint.
    const isFeed = handlerName === 'productFeed';
    app[method](`${COMMERCE_ACP_BASE_PATH}${subPath}`, async (req, res) => {
      if (!isAcpRouteEnabledForEnv(handlerName, process.env, { strict: isAgentCheckoutStrictEnabled() })) {
        return res.status(404).json({ error: 'not_found' });
      }
      // The feed can be served UNSIGNED (public discovery), so — like the sibling
      // public-read MCP door — it gets a body cap + per-client rate limit that the
      // signed checkout endpoints (auth is their throttle) don't need. Applied
      // only to the feed so a real signed checkout is never rate-limited.
      if (isFeed && isAcpPublicFeedEnabled()) {
        const contentLength = Number(req?.headers?.['content-length']);
        if (Number.isFinite(contentLength) && contentLength > ACP_PUBLIC_FEED_MAX_BODY_BYTES) {
          return res.status(413).json({ error: 'payload_too_large' });
        }
        if (!getAcpPublicFeedLimiter().allow(publicReadMcpClientKey(req))) {
          res.setHeader('Retry-After', '10');
          return res.status(429).json({ error: 'rate_limited', message: 'Too many requests; retry shortly.' });
        }
      }
      if (isCharge && !isAgentCheckoutStrictSubmitPaymentEnabled()) {
        recordCommerceKernelAudit({
          event: 'operation_blocked',
          operation: 'complete_checkout_session',
          detail: { code: 'OPERATION_NOT_ALLOWED', reason: 'strict_submit_payment_disabled', surface: 'acp_rest' },
        });
        return res.status(405).json({
          type: 'error',
          code: 'OPERATION_NOT_ALLOWED',
          message: 'submit_payment is disabled in strict checkout mode.',
        });
      }
      return INVOKE_AUTH_CONTEXT.run(buildExternalInvokeContext(req), async () => {
        try {
          const adapter = await getCommerceAcpRestAdapter();
          const out = await adapter[handlerName]({
            headers: req.headers || {},
            rawBody: req.rawBody,
            body: req.body,
            params: req.params || {},
            // Pagination from the QUERY STRING, allow-listed to three keys.
            //
            // Why it was not forwarded before: passing `req.query` wholesale
            // would put unsigned public input straight into `find_products`
            // free-text search on the connected fallback lane. That objection
            // is answered by the allow-list, not by omission — `limit`,
            // `cursor` and `page` are the only keys any feed lane reads
            // (services/productEntityIndexFeed.js:279-284), and a free-text
            // `query` key deliberately does NOT pass, so the search surface
            // stays exactly as closed as it is today.
            //
            // Why it is needed: the feed defaulted to 20 of ~4,467 priced rows
            // (0.4%) and the ONLY way to raise it was a JSON body on a GET —
            // which works solely because `express.json()` does not check the
            // method, i.e. an accident of middleware ordering that no ingester
            // would ever discover from the outside. Google/ChatGPT feed
            // crawlers issue a plain GET with a query string.
            //
            // Values arrive as strings; `clampLimit` does `Number(value)` and
            // `decodeCursor`/`clampInt` parse their own, so no coercion here.
            query: pickAcpFeedPagination(req.query),
          });
          for (const [k, v] of Object.entries(out.headers || {})) res.setHeader(k, v);
          return res.status(out.status).json(out.body);
        } catch (err) {
          logger.error(
            { err: err?.message || String(err), surface: 'acp_rest', handler: handlerName },
            'ACP REST route failed',
          );
          return res.status(503).json({
            type: 'error',
            code: 'MERCHANT_UNAVAILABLE',
            message: isFeed
              ? 'Product feed is temporarily unavailable.'
              : 'Checkout is temporarily unavailable.',
          });
        }
      });
    });
  }
}

function registerCommerceUcpRoutes() {
  // UCP discovery: GET /.well-known/ucp + GET|POST /ucp/capabilities. Read-only; no money, no body signature.
  // Deliberately INDEPENDENT of AGENT_CHECKOUT_STRICT (same decoupling as the ACP feed and the public read
  // MCP tier): discovery is read-only — the kill-switch governs money paths, not the profile door. A platform
  // that pinned /.well-known/ucp must keep resolving it while checkout is dark. Fail-closed on its own flag
  // (AGENT_CHECKOUT_UCP_DISCOVERY_ENABLED).
  const mountUcp = (method, routePath) => {
    app[method](routePath, async (req, res) => {
      if (!isAgentCheckoutUcpDiscoveryEnabled()) {
        return res.status(404).json({ error: 'not_found' });
      }
      try {
        const handlers = await getCommerceUcpRouteHandlers();
        const route = handlers.find(
          (r) => r.method.toLowerCase() === method && r.path === routePath,
        );
        if (!route) return res.status(404).json({ error: 'not_found' });
        const out = await route.handler({ headers: req.headers, body: req.body, query: req.query });
        for (const [k, v] of Object.entries(out.headers || {})) res.setHeader(k, v);
        return res.status(out.status).json(out.body);
      } catch (err) {
        logger.error({ err: err?.message || String(err), surface: 'ucp' }, 'UCP discovery route failed');
        return res.status(503).json({ error: 'ucp_unavailable' });
      }
    });
  };
  mountUcp('get', '/.well-known/ucp');
  mountUcp('post', '/ucp/capabilities');
  mountUcp('get', '/ucp/capabilities');
}

function registerUcpOrderWebhookRoutes() {
  // Inbound UCP order-webhook door (port of the retired `ucp-platform-receiver` service): the business
  // profile above promises this door, so it lives on the same gateway ucp.pivota.cc routes to.
  // POST verifies a detached ES256 JWS over req.rawBody (when UCP_VERIFY_ORDER_WEBHOOK is on) against the
  // signing keys published at UCP_BUSINESS_PROFILE_URL; GET /events is the e2e positive-control surface,
  // itself gated by the shared secret UCP_ORDER_WEBHOOK_EVENTS_KEY (unconfigured -> the route 404s).
  // Metadata only — never the raw body, no PII. Fail-closed dark unless UCP_ORDER_WEBHOOK_RECEIVER_ENABLED.
  // Registered in the LATE block (with the other UCP doors) so the caller-identity access log covers it.
  const { createUcpOrderWebhookReceiver, isUcpOrderWebhookReceiverEnabled } = require('./services/ucpOrderWebhookReceiver');
  const receiver = createUcpOrderWebhookReceiver({ logger });
  app.post('/ucp/order-webhook', async (req, res) => {
    // Public write door: per-client token-bucket limit (ACP public-feed pattern), applied only when
    // the door is LIT — a dark door must stay indistinguishable from a missing route (404, never 429).
    if (isUcpOrderWebhookReceiverEnabled() && !getUcpOrderWebhookLimiter().allow(publicReadMcpClientKey(req))) {
      res.setHeader('Retry-After', '10');
      return res.status(429).json({ error: 'rate_limited', message: 'Too many requests; retry shortly.' });
    }
    try {
      const out = await receiver.handleOrderWebhook({
        headers: req.headers,
        rawBody: req.rawBody, // exact wire bytes (express.json verify hook) — the JWS binds these
        body: req.body,
      });
      return res.status(out.status).json(out.body);
    } catch (err) {
      logger.error({ err: err?.message || String(err), surface: 'ucp_order_webhook' }, 'UCP order webhook route failed');
      return res.status(503).json({ error: 'ucp_order_webhook_unavailable' });
    }
  });
  app.get('/ucp/order-webhook/events', async (req, res) => {
    try {
      const out = await receiver.handleListEvents({ headers: req.headers, query: req.query });
      return res.status(out.status).json(out.body);
    } catch (err) {
      logger.error({ err: err?.message || String(err), surface: 'ucp_order_webhook' }, 'UCP order webhook events route failed');
      return res.status(503).json({ error: 'ucp_order_webhook_unavailable' });
    }
  });
}

function registerUcpBuyerAgentProfileRoute() {
  // GET /.well-known/ucp-agent — Pivota's OUTBOUND buyer-agent capability profile (a different role from the
  // seller `/.well-known/ucp` surface). Merchants/platforms fetch this during UCP negotiation when Pivota
  // calls their endpoint. Static JSON, no money, no secrets. Off by default (UCP_BUYER_AGENT_PROFILE_ENABLED).
  app.get('/.well-known/ucp-agent', async (req, res) => {
    if (!isUcpBuyerAgentProfileEnabled()) {
      return res.status(404).json({ error: 'not_found' });
    }
    try {
      // eslint-disable-next-line global-require
      const { buildUcpBuyerAgentProfile } = require('./services/ucpBuyerAgentProfile');
      // The Host-header fallback mirrors back whichever hostname the fetch arrived on — a CALLER-CONTROLLED
      // string being published as the identity anchor merchants bind to. `agentProfileUrlFromRequestHost`
      // therefore mirrors only a host an operator actually configured, and never a PaaS-generated one; every
      // other Host yields undefined and the builder OMITS `ucp.profile_url` (it invents no default). Absent
      // beats an anchor naming a deployment slot — or someone else's domain — and it is exactly the state
      // UCP_AGENT_PROFILE_URL exists to fix.
      // eslint-disable-next-line global-require
      const { agentProfileUrlFromRequestHost } = require('./services/ucpBuyerAgentClient');
      const profileUrl = firstNonEmptyString(
        process.env.UCP_AGENT_PROFILE_URL,
        (() => {
          try {
            return agentProfileUrlFromRequestHost(req.headers['x-forwarded-host'] || req.headers.host);
          } catch { return undefined; }
        })(),
      );
      const profile = buildUcpBuyerAgentProfile(profileUrl ? { profileUrl } : {});
      res.setHeader('content-type', 'application/json');
      // `Vary: Host` because the body CAN differ per Host (the fallback above mirrors the request's host), and
      // this response is `public` — without it a shared cache is free to hand a merchant the document built
      // for a different hostname, which for an identity anchor is the whole ballgame. Once
      // UCP_AGENT_PROFILE_URL is set the body stops varying, but the header must not depend on that.
      res.setHeader('vary', 'Host');
      res.setHeader('cache-control', 'public, max-age=300');
      return res.status(200).json(profile);
    } catch (err) {
      logger.error({ err: err?.message || String(err), surface: 'ucp_buyer_agent' }, 'UCP buyer-agent profile route failed');
      return res.status(503).json({ error: 'ucp_buyer_agent_profile_unavailable' });
    }
  });
}

function registerUcpWarmHandoffInternalRoute() {
  // INTERNAL warm-handoff resolve for the CLICK lane (Pivota_Warm_Handoff_Click_Lane_Spec_2026-07-22.md):
  // pivota-backend's public GET /r redirect calls this at click time to upgrade a cold brand redirect into a
  // pre-built cart on the brand's own Shopify checkout. Fail-closed dark (route flag + master flag + key all
  // required — the handler 404s otherwise); X-Internal-Key auth; NEVER mounted publicly. Any handler failure
  // resolves to continue_url:null so the caller cold-redirects — this route must never 5xx the click path.
  const { createUcpWarmHandoffInternalHandler } = require('./services/ucpWarmHandoffInternalRoute');
  const handler = createUcpWarmHandoffInternalHandler({ logger });
  app.post('/internal/ucp/warm-handoff/resolve', async (req, res) => {
    try {
      const out = await handler({ headers: req.headers, body: req.body });
      return res.status(out.status).json(out.body);
    } catch (err) {
      logger.error(
        { err: err?.message || String(err), surface: 'ucp_warm_handoff_internal' },
        'UCP warm-handoff internal route failed',
      );
      return res.status(200).json({ continue_url: null, reason: 'error' });
    }
  });
}

function registerCommercePaymentWebhookRoute() {
  app.post('/agent/shop/v1/payment-webhook', express.raw({ type: '*/*', limit: '1mb' }), async (req, res) => {
    if (!isAgentCheckoutStrictEnabled()) {
      return res.status(404).json({ error: 'not_found' });
    }
    try {
      const handler = await getPaymentWebhookHandler();
      const rawBody = Buffer.isBuffer(req.body) ? req.body : Buffer.from('');
      const out = await handler({ headers: req.headers, rawBody });
      return res.status(out.status).json(out.body);
    } catch (err) {
      logger.error({ err: err?.message || String(err) }, 'Strict checkout payment webhook failed');
      return res.status(503).json({ error: 'payment_webhook_unavailable' });
    }
  });
}

function pickSimilarProducts(products, baseProductId, limit = 8, excludeIds = []) {
  if (!Array.isArray(products)) return [];
  const excludes = new Set(excludeIds || []);
  excludes.add(baseProductId);

  const base = products.find(
    (p) => String(p.product_id || p.id) === String(baseProductId)
  );
  const basePrice = base ? Number(base.price || base.unit_price || 0) : null;

  let candidates = products.filter(
    (p) => !excludes.has(String(p.product_id || p.id))
  );

  if (basePrice && basePrice > 0) {
    const min = basePrice * 0.7;
    const max = basePrice * 1.3;
    const priced = candidates.filter((p) => {
      const price = Number(p.price || p.unit_price || 0);
      return price >= min && price <= max;
    });

    if (priced.length) {
      candidates = priced;
    }

    candidates.sort((a, b) => {
      const pa = Math.abs(Number(a.price || a.unit_price || 0) - basePrice);
      const pb = Math.abs(Number(b.price || b.unit_price || 0) - basePrice);
      return pa - pb;
    });
  }

  return candidates.slice(0, limit);
}

function deriveQueryFromProduct(product) {
  if (!product) return '';
  const title = (product.title || '').trim();
  if (title) return title;
  const ptype = (product.product_type || product.category || '').trim();
  if (ptype) return ptype;
  const desc = (product.description || '').trim();
  if (desc) return desc.slice(0, 60);
  return String(product.product_id || product.id || '').trim();
}

const SELLABLE_PRODUCT_STATUS_VALUES = [
  'active',
  'published',
  'online',
  'live',
  'enabled',
  'available',
];

const NON_SELLABLE_PRODUCT_STATUS_VALUES = new Set([
  'inactive',
  'disabled',
  'deleted',
  'archived',
  'archive',
  'draft',
  'hidden',
  'unpublished',
  'blocked',
]);

function buildSellableStatusPredicate(statusExpr) {
  const expr = `lower(coalesce(${statusExpr}, ''))`;
  const allowed = SELLABLE_PRODUCT_STATUS_VALUES.map((value) => `'${value}'`).join(', ');
  return `(${expr} = '' OR ${expr} IN (${allowed}))`;
}

function isStatusActive(status) {
  const normalized = String(status || '').trim().toLowerCase();
  if (!normalized) return true;
  if (SELLABLE_PRODUCT_STATUS_VALUES.includes(normalized)) return true;
  if (NON_SELLABLE_PRODUCT_STATUS_VALUES.has(normalized)) return false;
  // Unknown status should fail-open to avoid dropping sellable catalogs due
  // partner-specific status enums.
  return true;
}

function isProductSellable(product, options = {}) {
  if (!product || typeof product !== 'object') return false;
  if (!isStatusActive(product.status)) return false;
  const inStockOnly = options?.inStockOnly !== false;
  // Prefer in-stock products when inventory information is available.
  // When callers explicitly set in_stock_only=false, do not treat inventory<=0 as a hard block,
  // because some platforms/merchants can continue selling when inventory is not tracked.
  if (inStockOnly) {
    const rawInv =
      product.inventory_quantity ??
      product.inventoryQuantity ??
      (product.inventory && product.inventory.quantity);
    if (rawInv != null) {
      const inv = Number(rawInv);
      if (Number.isFinite(inv) && inv <= 0) return false;
    }
  }
  return true;
}

function looksSkuLikeQuery(q) {
  const s = String(q || '').trim().toLowerCase();
  if (!s) return false;
  if (!/[0-9]/.test(s)) return false;
  return /^[a-z0-9-]{6,}$/.test(s);
}

function tokenizeQueryForCache(q, options = {}) {
  const rawInput = String(q || '').trim();
  const lowerInput = rawInput.toLowerCase();
  const beautyQueryProfile =
    options?.beautyQueryProfile && typeof options.beautyQueryProfile === 'object'
      ? options.beautyQueryProfile
      : buildBeautyQueryProfile({
          rawQuery: rawInput,
          queryClass: options?.queryClass || options?.intent?.query_class,
          intent: options?.intent,
        });
  const sanitizedInput = sanitizeSearchQueryForRelevance(rawInput);
  const resolverInput = sanitizedInput || rawInput;
  const resolverNormalized = normalizeResolverText(resolverInput);
  const resolverTokens = Array.isArray(tokenizeResolverQuery(resolverNormalized))
    ? tokenizeResolverQuery(resolverNormalized)
    : [];
  const latinTokens = lowerInput.split(/[^a-z0-9]+/g).filter(Boolean);
  const cjkTokens = Array.from(
    new Set(
      (resolverInput.match(/[\u4e00-\u9fff]{2,}/g) || [])
        .map((token) => String(token || '').trim())
        .filter(Boolean),
    ),
  );
  const raw = [...latinTokens, ...resolverTokens, ...cjkTokens];
  if (hasPetSearchSignal(rawInput)) {
    raw.push('dog', 'pet');
    if (hasPetHarnessSearchSignal(rawInput)) {
      raw.push('harness', 'leash', 'collar');
    }
  }
  if (hasBeautyMakeupSearchSignal(rawInput) || beautyQueryProfile?.isBeautyQuery) {
    raw.push(...getBeautyCacheExpansionTerms(beautyQueryProfile));
  }
  const stop = new Set([
    'a',
    'an',
    'and',
    'are',
    'as',
    'at',
    'be',
    'bought',
    'by',
    'can',
    'could',
    'do',
    'does',
    'for',
    'from',
    'have',
    'help',
    'i',
    'in',
    'is',
    'it',
    'just',
    'like',
    'me',
    'my',
    'of',
    'on',
    'or',
    'please',
    'some',
    'that',
    'the',
    'their',
    'them',
    'this',
    'to',
    'u',
    'we',
    'what',
    'which',
    'with',
    'you',
    'your',
    '什么',
    '有什麼',
    '有什么',
    '有沒有',
    '有哪些',
    '哪些',
    '的吗',
    '的嗎',
    '有吗',
    '有嗎',
    '吗',
    '嗎',
    '呢',
    '的',
    '了',
  ]);

  const kept = [];
  for (const t of raw) {
    const normalizedToken = normalizeSearchTextForMatch(t);
    if (!normalizedToken) continue;
    if (stop.has(normalizedToken)) continue;
    const isLatinToken = /^[a-z0-9]+$/.test(normalizedToken);
    if (isLatinToken && normalizedToken.length < 3 && normalizedToken !== 'xs' && normalizedToken !== 'xl') {
      continue;
    }
    if (!isLatinToken && normalizedToken.length < 2) continue;
    kept.push(normalizedToken);
  }

  // Keep unique, preserve order.
  const seen = new Set();
  const uniq = [];
  for (const t of kept) {
    if (seen.has(t)) continue;
    seen.add(t);
    uniq.push(t);
  }

  const lookupExpanded = isLookupStyleSearchQuery(rawInput, extractSearchAnchorTokens(rawInput))
    ? expandLookupAnchorTokens(rawInput, uniq)
    : uniq;

  const expandedSeen = new Set();
  const expandedUniq = [];
  for (const token of lookupExpanded) {
    const normalizedToken = normalizeSearchTextForMatch(token);
    if (!normalizedToken) continue;
    if (stop.has(normalizedToken)) continue;
    if (expandedSeen.has(normalizedToken)) continue;
    expandedSeen.add(normalizedToken);
    expandedUniq.push(normalizedToken);
  }

  // Clamp to avoid pathological SQL, but ensure we don't drop "important" tokens
  // that often appear at the end (e.g. appended canonical keywords).
  // Strategy:
  // - If <= 8 tokens: return as-is.
  // - Else: take a balanced slice (first 4 + last 4), preserving order.
  if (expandedUniq.length <= 8) return expandedUniq;
  const first = expandedUniq.slice(0, 4);
  const last = expandedUniq.slice(-4);
  const outSeen = new Set();
  const out = [];
  for (const t of [...first, ...last]) {
    if (outSeen.has(t)) continue;
    outSeen.add(t);
    out.push(t);
    if (out.length >= 8) break;
  }
  return out;
}

function detectToyOutfitIntentFromQuery(q) {
  const s = String(q || '').toLowerCase();
  const toy = /\b(labubu|toy|toys|doll|dolls|plush|plushie|figure|collectible)\b/.test(s);
  const outfit = /\b(clothes|clothing|outfit|accessory|accessories|hat)\b/.test(s) || /衣服|穿/.test(s);
  const lingerie = /\b(lingerie|underwear|bra|pant(y|ies)|thong|sleepwear|nightgown|nightdress)\b/.test(s);
  return { toy_intent: toy, outfit_intent: toy && outfit, lingerie_intent: lingerie };
}

function buildUnderwearExclusionSql(startIndex) {
  const tokens = [
    'lingerie',
    'underwear',
    'bra',
    'panties',
    'panty',
    'briefs',
    'thong',
    'push-up',
    'push up',
    'backless',
    "women's sleepwear",
    'womens sleepwear',
    'women sleepwear',
    'sleepwear set',
    "women's lingerie",
    'lingerie set',
    'ropa interior',
    'sujetador',
    'bragas',
  ];

  const fields = [
    "lower(coalesce(product_data->>'title',''))",
    "lower(coalesce(product_data->>'product_type',''))",
  ];

  const parts = [];
  const params = [];
  let idx = startIndex;
  for (const tok of tokens) {
    const p = `%${tok}%`;
    params.push(p);
    const ors = fields.map((f) => `${f} LIKE $${idx}`).join(' OR ');
    parts.push(`(${ors})`);
    idx += 1;
  }
  return {
    sql: parts.length ? `NOT (${parts.join(' OR ')})` : 'TRUE',
    params,
    nextIndex: idx,
  };
}

async function loadCreatorSellableFromCache(creatorId, page = 1, limit = 20, options = {}) {
  const config = getCreatorConfig(creatorId);
  if (!config || !Array.isArray(config.merchantIds) || config.merchantIds.length === 0) {
    const err = new Error('Unknown creator');
    err.code = 'UNKNOWN_CREATOR';
    throw err;
  }

  const safePage = Math.max(1, Number(page || 1));
  const safeLimit = Math.min(Math.max(1, Number(limit || 20)), SEARCH_LIMIT_MAX);
  const fetchLimit = Math.max(safeLimit * Math.max(safePage, 1) * 2, 20);
  const inStockOnly = options?.inStockOnly !== false;

  // Optional: load explicit creator_picks so we can surface curated
  // recommendations at the top of the Featured feed and tag them for
  // frontends (e.g. Creator Agent UI) to power a "Creator picks" filter.
  let pickRankByProductId = new Map();
  try {
    const picksRes = await query(
      `
        SELECT product_id, rank
        FROM creator_picks
        WHERE creator_id = $1
        ORDER BY rank ASC
        LIMIT $2
      `,
      [creatorId, safeLimit * 4],
    );
    pickRankByProductId = new Map(
      (picksRes.rows || [])
        .map((r) => {
          const pid = String(r.product_id || '').trim();
          const rank = Number(r.rank);
          return [pid, rank];
        })
        .filter(([pid, rank]) => pid && Number.isFinite(rank)),
    );
  } catch (err) {
    logger.warn(
      { err: err.message, creatorId },
      'Failed to load creator_picks for creator featured feed; continuing without explicit picks',
    );
  }

  // Apply lightweight gating at the SQL layer (avoid deleted/expired/inactive).
  // In-stock preference is handled in JS so that in_stock_only=false can
  // still surface products where inventory is not tracked.
  const baseWhere = `
    merchant_id = ANY($1)
    AND ${activeProductsCacheSourceWhere('products_cache')}
    AND (expires_at IS NULL OR expires_at > now())
    AND ${buildSellableStatusPredicate("product_data->>'status'")}
  `;

  const rowsRes = await query(
    `
      SELECT product_data
      FROM products_cache
      WHERE ${baseWhere}
      ORDER BY cached_at DESC
      LIMIT $2
    `,
    [config.merchantIds, fetchLimit],
  );

  let baseProducts = (rowsRes.rows || [])
    .map((r) => r.product_data)
    .filter(Boolean)
    .filter((p) => isProductSellable(p, { inStockOnly }));

  if (baseProducts.length === 0) {
    try {
      const relaxedRowsRes = await query(
        `
          SELECT product_data
          FROM products_cache
          WHERE merchant_id = ANY($1)
            AND ${activeProductsCacheSourceWhere('products_cache')}
          ORDER BY cached_at DESC NULLS LAST, id DESC
          LIMIT $2
        `,
        [config.merchantIds, fetchLimit],
      );
      baseProducts = (relaxedRowsRes.rows || [])
        .map((r) => r.product_data)
        .filter(Boolean)
        .filter((p) => isProductSellable(p, { inStockOnly }));
    } catch (err) {
      logger.warn(
        { err: err.message, creatorId },
        'Creator featured strict cache query empty and relaxed fallback failed',
      );
    }
  }

  // Ensure explicit creator picks are always present in the featured pool,
  // even when they are older than the default cached_at window.
  let pickProducts = [];
  const pickIds = Array.from(pickRankByProductId.keys());
  if (pickIds.length > 0) {
    try {
      const pickRowsRes = await query(
        `
          SELECT product_data
          FROM products_cache
          WHERE ${baseWhere}
            AND (
              platform_product_id = ANY($2)
              OR product_data->>'id' = ANY($2)
              OR product_data->>'product_id' = ANY($2)
            )
          ORDER BY cached_at DESC
        `,
        [config.merchantIds, pickIds],
      );
      pickProducts = (pickRowsRes.rows || [])
        .map((r) => r.product_data)
        .filter(Boolean)
        .filter((p) => isProductSellable(p, { inStockOnly }));
    } catch (err) {
      logger.warn(
        { err: err.message, creatorId, pickIdsCount: pickIds.length },
        'Failed to hydrate creator_picks from products_cache; continuing with base products only',
      );
    }
  }

  const products = [...pickProducts, ...baseProducts];

  // De-dupe in case multiple cache rows exist for the same product.
  const seen = new Set();
  const unique = [];
  for (const p of products) {
    const mid = String(p.merchant_id || p.merchantId || '').trim();
    const pid = String(p.id || p.product_id || p.productId || '').trim();
    const key = `${mid}::${pid || JSON.stringify(p).slice(0, 64)}`;
    if (seen.has(key)) continue;
    seen.add(key);
    unique.push(p);
  }
  // Reorder so that explicit creator picks (from creator_picks) appear
  // first while preserving relative order for non-picks. Also tag them
  // with creator_pick metadata for downstream UIs.
  const decorated = unique.map((p) => {
    const pid = String(p.id || p.product_id || p.productId || '').trim();
    const rank =
      pid && pickRankByProductId.has(pid) ? pickRankByProductId.get(pid) : null;
    return { product: p, pickRank: rank };
  });

  decorated.sort((a, b) => {
    const ar = a.pickRank == null ? Number.POSITIVE_INFINITY : a.pickRank;
    const br = b.pickRank == null ? Number.POSITIVE_INFINITY : b.pickRank;
    if (ar !== br) return ar - br;
    return 0;
  });

  const sorted = decorated.map(({ product, pickRank }) => {
    if (pickRank == null) return product;
    return {
      ...product,
      creator_pick: true,
      creator_pick_rank: pickRank,
    };
  });

  const startIdx = (safePage - 1) * safeLimit;
  const pageItems = sorted.slice(startIdx, startIdx + safeLimit);
  const effectiveTotal = sorted.length;

  await applyShopifyCurrencyOverride(pageItems);

  return {
    products: pageItems,
    total: effectiveTotal,
    page: safePage,
    page_size: pageItems.length,
    merchantIds: config.merchantIds,
  };
}

function buildPetSignalSql(startIndex) {
  // Regex boundary for latin words; also include CJK pet keywords without boundaries.
  // Use ~* for case-insensitive matching.
  const latin = '(dog|dogs|puppy|puppies|cat|cats|kitten|kittens|pet|pets|perro|perros|mascota|mascotas|gato|gatos|chien|chiens|chienne|chiot|chat|chats)';
  const cjk = '(狗狗|狗|猫猫|猫|宠物|犬服|猫服|犬|ペット|わんちゃん)';
  // IMPORTANT: Postgres uses \m and \M as word-boundary tokens. Do NOT double-escape
  // here, otherwise the regex engine sees a literal "\m" string and never matches.
  const re = `(\\m${latin}\\M|${cjk})`;

  const fields = [
    "coalesce(product_data->>'title','')",
    "coalesce(product_data->>'description','')",
    "coalesce(product_data->>'product_type','')",
  ];

  const idx = startIndex;
  const ors = fields.map((f) => `${f} ~* $${idx}`).join(' OR ');
  return { sql: `(${ors})`, params: [re], nextIndex: idx + 1 };
}

function hasPetSearchSignal(queryText) {
  const q = String(queryText || '');
  if (!q) return false;
  return (
    /\b(dog|dogs|puppy|puppies|cat|cats|kitten|kittens|pet|pets|perro|perros|mascota|mascotas|gato|gatos|chien|chiens|chat|chats)\b/i.test(
      q,
    ) ||
    /狗狗|狗|猫猫|猫|宠物|犬|犬服|猫服|ペット|わんちゃん/.test(q)
  );
}

function hasPetHarnessSearchSignal(queryText) {
  const q = String(queryText || '');
  if (!q) return false;
  return (
    /\b(harness|leash|dog\s+leash|pet\s+leash|collar|lead|no-?pull)\b/i.test(q) ||
    /背带|背帶|胸背|牵引|牽引|牵引绳|牽引繩|遛狗绳|狗链|狗鏈|狗链子|狗鏈子|项圈|項圈|胸背带|胸背帶|狗绳|狗繩|胴輪|ハーネス|リード|首輪/.test(
      q,
    )
  );
}

function hasPetLeashSearchSignal(queryText) {
  const q = String(queryText || '');
  if (!q) return false;
  return (
    /\b(leash|dog\s+leash|pet\s+leash|lead|training\s+leash|collar)\b/i.test(q) ||
    /牵引绳|牽引繩|遛狗绳|狗链|狗鏈|狗链子|狗鏈子|狗绳|狗繩|项圈|項圈|リード|首輪/.test(q)
  );
}

function hasStrictPetHarnessCatalogSignal(candidateText) {
  const text = String(candidateText || '');
  if (!text) return false;
  return (
    /\b(harness|leash|dog\s+leash|pet\s+leash|collar|lead|no-?pull|training\s+leash)\b/i.test(text) ||
    /(背带|背帶|胸背|牵引|牽引|牵引绳|牽引繩|遛狗绳|狗链|狗鏈|狗链子|狗鏈子|项圈|項圈|胴輪|ハーネス|リード|首輪|arn[eé]s|correa|collier)/i.test(
      text,
    )
  );
}

function hasBeautyMakeupSearchSignal(queryText) {
  return detectBeautyQueryBucket(queryText) != null;
}

function classifyBeautyBucketFromText(text) {
  return classifySharedBeautyBucketFromText(text);
}

function hasBeautyCatalogProductSignal(candidateText) {
  return classifyBeautyBucketFromText(candidateText) !== 'other';
}

function classifyBeautyBucketFromProduct(product) {
  const text = buildFallbackCandidateText(product);
  const bucket = classifyBeautyBucketFromText(text);
  return bucket === 'general' ? 'other' : bucket;
}

function detectBeautyQueryBucket(queryText) {
  return detectSharedBeautyQueryBucket(queryText);
}

function scoreBeautyCategoryBrowseFastpathProduct(product, fastpath) {
  if (!product || typeof product !== 'object' || !fastpath) return 0;
  const title = normalizeSearchTextForMatch(
    String(product.title || product.name || product.display_name || ''),
  );
  const category = normalizeSearchTextForMatch(
    String(product.category || product.product_type || product.productType || ''),
  );
  const text = buildFallbackCandidateText(product);
  let score = 0;
  if (fastpath.titlePattern && fastpath.titlePattern.test(title)) score += 7;
  if (fastpath.titlePattern && fastpath.titlePattern.test(category)) score += 5;
  if (fastpath.productPattern && fastpath.productPattern.test(title)) score += 4;
  if (fastpath.productPattern && fastpath.productPattern.test(category)) score += 3;
  if (fastpath.productPattern && fastpath.productPattern.test(text)) score += 1;
  return score;
}

function rankBeautyCategoryBrowseFastpathProducts(products, fastpath) {
  return (Array.isArray(products) ? products : [])
    .map((product, index) => ({
      product,
      index,
      score: scoreBeautyCategoryBrowseFastpathProduct(product, fastpath),
    }))
    .filter((row) => row.score > 0)
    .sort((a, b) => b.score - a.score || a.index - b.index)
    .map((row) => row.product);
}

function buildBeautyBucketMix(products = []) {
  const mix = {};
  for (const product of Array.isArray(products) ? products : []) {
    const bucket = classifyBeautyBucketFromProduct(product) || 'other';
    mix[bucket] = Number(mix[bucket] || 0) + 1;
  }
  return mix;
}

async function tryCrossMerchantBeautyCategoryBrowseFastpath(
  queryText,
  page = 1,
  limit = 20,
  options = {},
) {
  const fastpath = resolveBeautyCategoryBrowseFastpath(queryText, {
    queryClass: options?.queryClass || options?.intent?.query_class,
  });
  if (!fastpath) return null;
  const safePage = Math.max(1, Number(page || 1));
  const safeLimit = Math.min(Math.max(1, Number(limit || 20)), SEARCH_LIMIT_MAX);
  const offset = (safePage - 1) * safeLimit;
  const browseLimit = Math.min(Math.max(offset + safeLimit * 8, 80), 160);
  const baseWhere = `
    (pc.expires_at IS NULL OR pc.expires_at > now())
    AND ${activeProductsCacheSourceWhere('pc')}
    AND ${buildSellableStatusPredicate("pc.product_data->>'status'")}
    AND mo.status NOT IN ('deleted', 'rejected')
    AND ${transactionCapableMerchantWhere('mo')}
  `;
  const matchFields = [
    "lower(coalesce(pc.product_data->>'title',''))",
    "lower(coalesce(pc.product_data->>'product_type',''))",
  ];
  const matchClauses = [];
  const params = [];
  let idx = 1;
  for (const alias of fastpath.queryAliases) {
    params.push(`%${alias}%`);
    matchClauses.push(`(${matchFields.map((field) => `${field} LIKE $${idx}`).join(' OR ')})`);
    idx += 1;
  }
  if (matchClauses.length === 0) return null;
  const browseStartedAt = Date.now();
  const browse = await query(
    `
      /* beauty_category_browse_fastpath */
      SELECT pc.merchant_id,
             mo.business_name AS merchant_name,
             pc.product_data
      FROM products_cache pc
      JOIN merchant_onboarding mo
        ON mo.merchant_id = pc.merchant_id
      WHERE ${baseWhere}
        AND (${matchClauses.join(' OR ')})
      ORDER BY pc.cached_at DESC NULLS LAST, pc.id DESC
      LIMIT $${idx}
    `,
    [...params, browseLimit],
  );
  const browseQueryMs = Math.max(0, Date.now() - browseStartedAt);
  const browseProducts = (browse?.rows || [])
    .map((row) => {
      const product = row.product_data;
      if (!product) return null;
      const merchantId = String(row.merchant_id || '').trim();
      const merchantName = row.merchant_name ? String(row.merchant_name).trim() : '';
      const out = { ...product };
      if (merchantId && !out.merchant_id && !out.merchantId) out.merchant_id = merchantId;
      if (merchantName && !out.merchant_name && !out.merchantName) out.merchant_name = merchantName;
      return out;
    })
    .filter(Boolean)
    .filter((product) => isProductSellable(product, { inStockOnly: options?.inStockOnly !== false }));
  const bucketCompatibleProducts = browseProducts.filter((product) =>
    isBeautyBucketCompatibleForQuery(classifyBeautyBucketFromProduct(product), fastpath.bucket),
  );
  const rankedProducts = rankBeautyCategoryBrowseFastpathProducts(bucketCompatibleProducts, fastpath);
  if (rankedProducts.length === 0) return null;
  const pageItems = rankedProducts.slice(offset, offset + safeLimit);
  await applyShopifyCurrencyOverride(pageItems);
  return {
    products: pageItems,
    total: rankedProducts.length,
    page: safePage,
    page_size: pageItems.length,
    retrieval_sources: [
      {
        source: 'beauty_category_browse_fastpath',
        used: true,
        category_id: fastpath.id,
        category_label: fastpath.label,
        count: pageItems.length,
        candidate_count: rankedProducts.length,
        browse_candidate_count: browseProducts.length,
        browse_query_ms: browseQueryMs,
      },
    ],
    query_terms: [fastpath.label.toLowerCase()],
    beauty_query_bucket: fastpath.bucket || null,
    internal_filter_debug: {
      applied: true,
      bucket: fastpath.bucket || null,
      filtered_irrelevant_count: Math.max(0, browseProducts.length - rankedProducts.length),
      bucket_mix_before: buildBeautyBucketMix(browseProducts),
      bucket_mix_after: buildBeautyBucketMix(rankedProducts),
    },
  };
}

function getResolverFallbackResolveQueryUsed(result, queryText = '') {
  return String(
    result?.resolve_query_used || result?.data?.metadata?.resolve_query_used || queryText || '',
  ).trim() || null;
}

function isStrongResolverLookupQuery(queryText, queryClass = null) {
  const raw = String(queryText || '').trim();
  if (!raw) return false;
  const normalizedClass = String(queryClass || '').trim().toLowerCase();
  if (normalizedClass === 'lookup') return true;
  if (isKnownLookupAliasQuery(raw)) return true;
  const hasModelLikeToken = /\b[a-z]{1,6}\d{2,}\b/i.test(raw);
  const hasBeautySpfToken = /\bspf\d{2,3}\b/i.test(raw);
  if ((hasModelLikeToken && !hasBeautySpfToken) || /\b(sku|model|型号|型號)\b/i.test(raw)) {
    return true;
  }
  return false;
}

function getResolverFallbackAdoptionDecision({ result, queryText, queryClass = null }) {
  const resolveQueryUsed = getResolverFallbackResolveQueryUsed(result, queryText);
  if (!result || result.status < 200 || result.status >= 300 || Number(result.usableCount || 0) <= 0 || !result.data) {
    return {
      adopt: false,
      reason: 'resolver_empty',
      resolveQueryUsed,
    };
  }
  if (!queryText) {
    return {
      adopt: true,
      reason: null,
      resolveQueryUsed,
    };
  }
  if (isStrongResolverLookupQuery(queryText, queryClass)) {
    return {
      adopt: true,
      reason: null,
      resolveQueryUsed,
    };
  }
  if (detectBeautyQueryBucket(queryText)) {
    return {
      adopt: false,
      reason: 'resolver_irrelevant_to_original_query',
      resolveQueryUsed,
    };
  }
  const resolverQuerySource = String(result?.data?.metadata?.query_source || '').trim().toLowerCase();
  const resolverDetailSource = String(result?.data?.metadata?.resolve_detail_source || '').trim().toLowerCase();
  if (
    resolverQuerySource === 'agent_products_resolver_ref_fallback' ||
    resolverDetailSource === 'reference_only'
  ) {
    return {
      adopt: false,
      reason: 'resolver_irrelevant_to_original_query',
      resolveQueryUsed,
    };
  }
  const relevant = isProxySearchFallbackRelevant(result.data, queryText);
  return {
    adopt: relevant,
    reason: relevant ? null : 'resolver_irrelevant_to_original_query',
    resolveQueryUsed,
  };
}

function computeBeautyBucketMix(products, topN = 10) {
  const buckets = {
    base_makeup: 0,
    eye_makeup: 0,
    lip_makeup: 0,
    lip_care: 0,
    skincare: 0,
    haircare: 0,
    bodycare: 0,
    fragrance: 0,
    tools: 0,
    other: 0,
  };
  const top = Array.isArray(products) ? products.slice(0, Math.max(1, Number(topN || 10))) : [];
  for (const product of top) {
    const bucket = classifyBeautyBucketFromProduct(product);
    buckets[bucket] = Number(buckets[bucket] || 0) + 1;
  }
  return buckets;
}

function isBeautyGeneralDiversitySupplementCandidate(intent, products, limit, options = {}) {
  const beautyQueryProfile = buildBeautyQueryProfile({
    rawQuery: options?.rawQuery || '',
    queryClass: options?.queryClass || intent?.query_class,
    intent,
  });
  if (!beautyQueryProfile?.allowBeautyDiversity) return false;
  const topN = Math.max(1, Number(limit || 10));
  const mix = computeBeautyBucketMix(products, topN);
  const coreBuckets = ['base_makeup', 'eye_makeup', 'lip_makeup', 'lip_care', 'skincare', 'haircare', 'bodycare'];
  const distinctCore = coreBuckets.filter((bucket) => Number(mix[bucket] || 0) > 0).length;
  const toolsCount = Number(mix.tools || 0);
  return distinctCore < 2 && toolsCount >= Math.ceil(topN * 0.6);
}

function blendBeautyDiversitySupplement(internalProducts, supplementProducts, limit) {
  const targetLimit = Math.max(1, Number(limit || 10));
  const priorityBuckets = [
    'base_makeup',
    'eye_makeup',
    'lip_makeup',
    'lip_care',
    'skincare',
    'haircare',
    'bodycare',
    'tools',
    'fragrance',
    'other',
  ];
  const seen = new Set();
  const merged = [];
  const internal = Array.isArray(internalProducts) ? internalProducts : [];
  const supplement = Array.isArray(supplementProducts) ? supplementProducts : [];

  const addUnique = (product) => {
    const key = buildSearchProductKey(product) || JSON.stringify(product || {}).slice(0, 96);
    if (!key || seen.has(key)) return;
    seen.add(key);
    merged.push(product);
  };

  for (const product of internal) addUnique(product);
  for (const product of supplement) addUnique(product);

  const queues = new Map(priorityBuckets.map((bucket) => [bucket, []]));
  for (const product of merged) {
    const bucket = classifyBeautyBucketFromProduct(product);
    if (!queues.has(bucket)) queues.set(bucket, []);
    queues.get(bucket).push(product);
  }

  const output = [];
  while (output.length < targetLimit) {
    let progressed = false;
    for (const bucket of priorityBuckets) {
      const queue = queues.get(bucket);
      if (!queue || queue.length === 0) continue;
      output.push(queue.shift());
      progressed = true;
      if (output.length >= targetLimit) break;
    }
    if (!progressed) break;
  }

  return output;
}

function buildPetHarnessSignalSql(startIndex) {
  const latin = '(harness|leash|collar|lead|no-?pull|dog\\s+harness|dog\\s+leash|pet\\s+harness|pet\\s+leash)';
  const cjk = '(背带|胸背|牵引|牵引绳|遛狗绳|狗链|项圈|胸背带|胴輪|ハーネス)';
  const re = `(\\m${latin}\\M|${cjk})`;
  const fields = [
    "coalesce(product_data->>'title','')",
    "coalesce(product_data->>'description','')",
    "coalesce(product_data->>'product_type','')",
  ];
  const idx = startIndex;
  const ors = fields.map((f) => `${f} ~* $${idx}`).join(' OR ');
  return { sql: `(${ors})`, params: [re], nextIndex: idx + 1 };
}

function buildBeautySignalSql(startIndex) {
  const latin =
    '(makeup|cosmetic|cosmetics|beauty|foundation|concealer|lipstick|blush|mascara|eyeshadow|brush|palette|toner|serum|skincare|fenty|tom\\s*ford|winona|ipsa)';
  const cjk =
    '(化妆|化妝|美妆|美妝|彩妆|彩妝|底妆|底妝|粉底|遮瑕|口红|口紅|唇膏|腮红|眼影|睫毛膏|化妆刷|化妝刷|刷具|粉扑|美妆蛋|妆前|妝前|定妆|定妝|薇诺娜|薇諾娜|茵芙莎|流金水)';
  const re = `(\\m${latin}\\M|${cjk})`;
  const fields = [
    "coalesce(product_data->>'title','')",
    "coalesce(product_data->>'description','')",
    "coalesce(product_data->>'product_type','')",
    "coalesce(product_data->>'vendor','')",
  ];
  const idx = startIndex;
  const ors = fields.map((f) => `${f} ~* $${idx}`).join(' OR ');
  return { sql: `(${ors})`, params: [re], nextIndex: idx + 1 };
}

async function searchCreatorSellableFromCache(creatorId, queryText, page = 1, limit = 20, options = {}) {
  const config = getCreatorConfig(creatorId);
  if (!config || !Array.isArray(config.merchantIds) || config.merchantIds.length === 0) {
    const err = new Error('Unknown creator');
    err.code = 'UNKNOWN_CREATOR';
    throw err;
  }

  const safePage = Math.max(1, Number(page || 1));
  const safeLimit = Math.min(Math.max(1, Number(limit || 20)), SEARCH_LIMIT_MAX);
  const offset = (safePage - 1) * safeLimit;
  const q = String(queryText || '').trim().toLowerCase();
  const inStockOnly = options?.inStockOnly !== false;

  function productKey(p) {
    const mid = String(p?.merchant_id || p?.merchantId || '').trim();
    const pid = String(p?.id || p?.product_id || p?.productId || '').trim();
    return `${mid}::${pid || JSON.stringify(p).slice(0, 64)}`;
  }

  // Base gating (avoid deleted/expired/inactive). In-stock preference is handled
  // in JS so that in_stock_only=false can still surface products where inventory
  // is not tracked.
  const baseWhere = `
    merchant_id = ANY($1)
    AND ${activeProductsCacheSourceWhere('products_cache')}
    AND (expires_at IS NULL OR expires_at > now())
    AND ${buildSellableStatusPredicate("product_data->>'status'")}
  `;

  const terms = tokenizeQueryForCache(q, {
    intent: options?.intent,
    queryClass: options?.intent?.query_class,
  });
  const skuLike = looksSkuLikeQuery(q);
  const { toy_intent, outfit_intent, lingerie_intent } = detectToyOutfitIntentFromQuery(q);
  const intentTarget = String(options?.intent?.target_object?.type || '').toLowerCase();

  const whereParts = [];
  const params = [config.merchantIds];
  let idx = 2;

  // If we have no usable terms, behave like cold-start.
  if (terms.length === 0) {
    return await loadCreatorSellableFromCache(creatorId, safePage, safeLimit, { inStockOnly });
  }

  const matchFields = [
    "lower(coalesce(product_data->>'title',''))",
    "lower(coalesce(product_data->>'description',''))",
    "lower(coalesce(product_data->>'product_type',''))",
    "lower(coalesce(product_data->>'sku',''))",
    "lower(coalesce(product_data->>'vendor',''))",
  ];

  for (const t of terms) {
    params.push(`%${t}%`);
    const ors = matchFields.map((f) => `${f} LIKE $${idx}`).join(' OR ');
    const termParts = [`(${ors})`];
    if (skuLike) {
      // Variant SKU can be nested; bounded text scan for SKU-like queries only.
      termParts.push(`lower(CAST(product_data AS TEXT)) LIKE $${idx}`);
    }
    whereParts.push(`(${termParts.join(' OR ')})`);
    idx += 1;
  }

  // Intent-aware safety:
  // - For pet/human searches, avoid surfacing lingerie unless explicitly asked for it.
  // - For pet searches, additionally require a pet signal to prevent "featured" bleed-through.
  let underwearClause = null;
  let underwearParams = [];
  let afterUnderwearIdx = idx;
  const shouldExcludeUnderwear =
    !lingerie_intent && ((toy_intent || outfit_intent) || intentTarget === 'pet' || intentTarget === 'human');

  if (shouldExcludeUnderwear) {
    const built = buildUnderwearExclusionSql(idx);
    underwearClause = built.sql;
    underwearParams = built.params;
    afterUnderwearIdx = built.nextIndex;
  }

  const queryWhere = whereParts.length ? `(${whereParts.join(' OR ')})` : 'TRUE';
  let petClause = null;
  let petParams = [];
  let afterPetIdx = afterUnderwearIdx;
  if (intentTarget === 'pet') {
    const built = buildPetSignalSql(afterUnderwearIdx);
    petClause = built.sql;
    petParams = built.params;
    afterPetIdx = built.nextIndex;
  }

  const finalWhere = [baseWhere, queryWhere, ...(underwearClause ? [underwearClause] : []), ...(petClause ? [petClause] : [])].join(
    ' AND '
  );

  const pageFetch = Math.min(Math.max(safeLimit * 3, 60), 300);
  const pageOffset = Math.max(0, offset);

  const countSql = `
    SELECT COUNT(*)::int AS total
    FROM products_cache
    WHERE ${finalWhere}
  `;

  const rowsSql = `
    SELECT product_data
    FROM products_cache
    WHERE ${finalWhere}
    ORDER BY cached_at DESC
    OFFSET $${afterPetIdx}
    LIMIT $${afterPetIdx + 1}
  `;

  const countParams = underwearClause
    ? petClause
      ? [...params, ...underwearParams, ...petParams]
      : [...params, ...underwearParams]
    : petClause
      ? [...params, ...petParams]
      : params;
  const rowsParams = underwearClause
    ? petClause
      ? [...params, ...underwearParams, ...petParams, pageOffset, pageFetch]
      : [...params, ...underwearParams, pageOffset, pageFetch]
    : petClause
      ? [...params, ...petParams, pageOffset, pageFetch]
      : [...params, pageOffset, pageFetch];

  const [countRes, rowsRes] = await Promise.all([
    query(countSql, countParams),
    query(rowsSql, rowsParams),
  ]);

  const total = Number(countRes.rows?.[0]?.total || 0);
  const rawProducts = (rowsRes.rows || []).map((r) => r.product_data).filter(Boolean);

  const lexicalScoreByKey = new Map();

  // Rank candidates in-memory for better UX (title matches > description matches).
  const scored = rawProducts
    .filter((p) => isProductSellable(p, { inStockOnly }))
    .map((p) => {
      const title = String(p.title || '').toLowerCase();
      const desc = String(p.description || '').toLowerCase();
      const ptype = String(p.product_type || p.productType || '').toLowerCase();
      const sku = String(p.sku || '').toLowerCase();
      const tags = Array.isArray(p.tags) ? p.tags.join(' ').toLowerCase() : String(p.tags || '').toLowerCase();
      const recTags = Array.isArray(p.recommendation_meta?.tags)
        ? p.recommendation_meta.tags.join(' ').toLowerCase()
        : '';
      const recFacets = p.recommendation_meta?.facets ? JSON.stringify(p.recommendation_meta.facets).toLowerCase() : '';
      const blob = `${title} ${ptype} ${sku} ${tags} ${recTags} ${recFacets} ${desc}`;

      let score = 0;
      for (const t of terms) {
        if (title.includes(t)) score += 3;
        else if (ptype.includes(t)) score += 2;
        else if (blob.includes(t)) score += 1;
      }

      // Tags/facets are stable catalog semantics; prioritize them when available.
      score += scoreByTagFacetOverlap(terms, p).score;

      if (skuLike) {
        const q0 = q.replace(/[^a-z0-9-]+/g, '');
        if (q0 && sku === q0) score += 6;
        else if (q0 && blob.includes(q0)) score += 3;
      }

      // Gentle boost for toy-like when the query is toy/outfit intent.
      if ((toy_intent || outfit_intent) && /\b(labubu|doll|plush|toy|outfit)\b/.test(blob)) {
        score += 1;
      }

      // Penalize obvious object mismatches at recall time.
      // This prevents generic terms like "dress" from being dominated by doll outfits
      // when the user is clearly asking for human clothing.
      const toyLike =
        /\b(labubu|doll|vinyl face doll|blind box|plush|plushie|figure|collectible)\b/.test(blob) ||
        /盲盒|公仔|娃娃|娃衣/.test(blob);
      const petLike =
        /\b(dog|dogs|puppy|puppies|cat|cats|kitten|kittens|pet|pets)\b/.test(blob) ||
        /\b(perro|perros|mascota|mascotas|gato|gatos)\b/.test(blob) ||
        /\b(chien|chiens|chat|chats|animal|animaux)\b/.test(blob) ||
        /狗|猫|宠物|犬服|猫服|ペット/.test(blob);

      if (intentTarget === 'human') {
        if (!toy_intent && !outfit_intent && toyLike) score -= 100;
        if (petLike) score -= 60;
      } else if (intentTarget === 'pet') {
        if (toyLike) score -= 100;
      } else if (intentTarget === 'toy') {
        if (petLike) score -= 40;
      }

      return { p, score, key: productKey(p) };
    })
    .sort((a, b) => b.score - a.score);

  for (const row of scored) {
    if (row && row.key) {
      lexicalScoreByKey.set(row.key, typeof row.score === 'number' ? row.score : Number(row.score || 0));
    }
  }

  const lexicalProducts = scored.slice(0, safeLimit).map((x) => x.p);
  const retrievalSources = [
    { source: 'lexical_cache', used: true, count: lexicalProducts.length, candidate_count: rawProducts.length },
  ];

  if (lexicalProducts.length === 0) {
    try {
      const relaxedWhere = [
        'merchant_id = ANY($1)',
        activeProductsCacheSourceWhere('products_cache'),
        queryWhere,
        ...(underwearClause ? [underwearClause] : []),
        ...(petClause ? [petClause] : []),
      ].join(' AND ');
      const relaxedRowsSql = `
        SELECT product_data
        FROM products_cache
        WHERE ${relaxedWhere}
        ORDER BY cached_at DESC NULLS LAST, id DESC
        OFFSET $${afterPetIdx}
        LIMIT $${afterPetIdx + 1}
      `;
      const relaxedRowsRes = await query(relaxedRowsSql, rowsParams);
      const relaxedProductsRaw = (relaxedRowsRes.rows || [])
        .map((r) => r.product_data)
        .filter(Boolean)
        .filter((p) => isProductSellable(p, { inStockOnly }));
      const seen = new Set();
      const relaxedProducts = [];
      for (const product of relaxedProductsRaw) {
        const key = productKey(product);
        if (seen.has(key)) continue;
        seen.add(key);
        relaxedProducts.push(product);
        if (relaxedProducts.length >= safeLimit) break;
      }
      retrievalSources.push({
        source: 'lexical_cache_relaxed',
        used: true,
        count: relaxedProducts.length,
        candidate_count: relaxedProductsRaw.length,
      });
      if (relaxedProducts.length > 0) {
        await applyShopifyCurrencyOverride(relaxedProducts);
        return {
          products: relaxedProducts,
          total: Math.max(total, relaxedProducts.length),
          page: safePage,
          page_size: safeLimit,
          merchantIds: config.merchantIds,
          retrieval_sources: retrievalSources,
        };
      }
    } catch (err) {
      retrievalSources.push({
        source: 'lexical_cache_relaxed',
        used: false,
        error: String(err && err.message ? err.message : err),
      });
    }
  }

  // If lexical returned nothing for pet intent (common for non-English queries
  // against an English catalog), do a pet-constrained browse fallback so we can
  // still show some relevant creator items.
  if (lexicalProducts.length === 0 && intentTarget === 'pet') {
    try {
      let underwearClause2 = null;
      let underwearParams2 = [];
      let idx2 = 2;
      const shouldExcludeUnderwear2 =
        !lingerie_intent && ((toy_intent || outfit_intent) || intentTarget === 'pet' || intentTarget === 'human');
      if (shouldExcludeUnderwear2) {
        const built = buildUnderwearExclusionSql(idx2);
        underwearClause2 = built.sql;
        underwearParams2 = built.params;
        idx2 = built.nextIndex;
      }
      const builtPet = buildPetSignalSql(idx2);
      const petClause2 = builtPet.sql;
      const petParams2 = builtPet.params;
      idx2 = builtPet.nextIndex;

      const browseWhere = [baseWhere, ...(underwearClause2 ? [underwearClause2] : []), petClause2].join(' AND ');
      const pageFetch2 = Math.min(Math.max(safeLimit * 4, 80), 300);
      const browseRes = await query(
        `
          SELECT product_data
          FROM products_cache
          WHERE ${browseWhere}
          ORDER BY cached_at DESC
          LIMIT $${idx2}
        `,
        [config.merchantIds, ...underwearParams2, ...petParams2, pageFetch2],
      );

      const browseProducts = (browseRes.rows || [])
        .map((r) => r.product_data)
        .filter(Boolean)
        .filter((p) => isProductSellable(p, { inStockOnly }))
        .slice(0, safeLimit);

      retrievalSources.push({
        source: 'pet_browse_fallback',
        used: true,
        count: browseProducts.length,
      });

      if (browseProducts.length > 0) {
        await applyShopifyCurrencyOverride(browseProducts);
        return {
          products: browseProducts,
          total: Math.max(total, browseProducts.length),
          page: safePage,
          page_size: safeLimit,
          merchantIds: config.merchantIds,
          retrieval_sources: retrievalSources,
        };
      }
    } catch (err) {
      retrievalSources.push({
        source: 'pet_browse_fallback',
        used: false,
        error: String(err && err.message ? err.message : err),
      });
    }
  }

  if (lexicalProducts.length === 0 && hasBeautyMakeupSearchSignal(q)) {
    try {
      let underwearClause2 = null;
      let underwearParams2 = [];
      let idx2 = 2;
      const shouldExcludeUnderwear2 =
        !lingerie_intent &&
        ((toy_intent || outfit_intent) || intentTarget === 'pet' || intentTarget === 'human');
      if (shouldExcludeUnderwear2) {
        const built = buildUnderwearExclusionSql(idx2);
        underwearClause2 = built.sql;
        underwearParams2 = built.params;
        idx2 = built.nextIndex;
      }
      const builtBeauty = buildBeautySignalSql(idx2);
      const beautyClause2 = builtBeauty.sql;
      const beautyParams2 = builtBeauty.params;
      idx2 = builtBeauty.nextIndex;

      const browseWhere = [baseWhere, ...(underwearClause2 ? [underwearClause2] : []), beautyClause2].join(' AND ');
      const pageFetch2 = Math.min(Math.max(safeLimit * 4, 80), 300);
      const browseRes = await query(
        `
          SELECT product_data
          FROM products_cache
          WHERE ${browseWhere}
          ORDER BY cached_at DESC
          LIMIT $${idx2}
        `,
        [config.merchantIds, ...underwearParams2, ...beautyParams2, pageFetch2],
      );

      const browseProducts = (browseRes.rows || [])
        .map((r) => r.product_data)
        .filter(Boolean)
        .filter((p) => isProductSellable(p, { inStockOnly }))
        .slice(0, safeLimit);

      retrievalSources.push({
        source: 'beauty_browse_fallback',
        used: true,
        count: browseProducts.length,
      });

      if (browseProducts.length > 0) {
        await applyShopifyCurrencyOverride(browseProducts);
        return {
          products: browseProducts,
          total: Math.max(total, browseProducts.length),
          page: safePage,
          page_size: safeLimit,
          merchantIds: config.merchantIds,
          retrieval_sources: retrievalSources,
        };
      }
    } catch (err) {
      retrievalSources.push({
        source: 'beauty_browse_fallback',
        used: false,
        error: String(err && err.message ? err.message : err),
      });
    }
  }

  const vectorEnabled =
    process.env.FIND_PRODUCTS_MULTI_VECTOR_ENABLED === 'true' &&
    process.env.DATABASE_URL &&
    safePage === 1;

  const intentLang = String(options?.intent?.language || '').toLowerCase();
  const shouldTryVector =
    vectorEnabled &&
    // Keep vector recall for non-English queries, or when lexical returns nothing.
    // This avoids paying embedding/vector latency on healthy lexical hits.
    ((intentLang && intentLang !== 'en' && intentLang !== 'other') || lexicalProducts.length === 0);

  if (shouldTryVector) {
    try {
      const embedding = await embedText(queryText, { cache: true });
      const vecLimit = Math.min(Math.max(safeLimit * 6, 80), 240);
      const vecHits = await semanticSearchCreatorProductsFromCache({
        merchantIds: config.merchantIds,
        queryVector: embedding.vector,
        dim: embedding.dim,
        provider: embedding.provider,
        model: embedding.model,
        limit: vecLimit,
        intentTarget,
        excludeUnderwear: shouldExcludeUnderwear,
      });

      const vectorScoreByKey = new Map();
      const vecProducts = vecHits
        .map((x) => {
          const p = x && x.product ? x.product : null;
          if (!p) return null;
          vectorScoreByKey.set(productKey(p), typeof x.score === 'number' ? x.score : Number(x.score || 0));
          return p;
        })
        .filter(Boolean)
        .filter((p) => isProductSellable(p, { inStockOnly }));

      retrievalSources.push({
        source: 'vector_cache',
        used: true,
        count: vecProducts.length,
        provider: embedding.provider,
        model: embedding.model,
        dim: embedding.dim,
      });

      const nonEnglishQuery = intentLang && intentLang !== 'en' && intentLang !== 'other';
      const shouldBlend =
        vecProducts.length > 0 &&
        (lexicalProducts.length < safeLimit || nonEnglishQuery || intentTarget === 'human' || intentTarget === 'pet');

      if (shouldBlend) {
        const seen = new Set();
        const merged = [];
        const lexicalTake = nonEnglishQuery ? Math.min(Math.ceil(safeLimit * 0.4), lexicalProducts.length) : lexicalProducts.length;

        for (const p of lexicalProducts.slice(0, lexicalTake)) {
          const key = productKey(p);
          if (seen.has(key)) continue;
          seen.add(key);
          merged.push(p);
        }
        for (const p of vecProducts) {
          if (merged.length >= safeLimit) break;
          const key = productKey(p);
          if (seen.has(key)) continue;
          seen.add(key);
          merged.push(p);
        }
        // If still not full, backfill from remaining lexical items.
        if (merged.length < safeLimit && lexicalTake < lexicalProducts.length) {
          for (const p of lexicalProducts.slice(lexicalTake)) {
            if (merged.length >= safeLimit) break;
            const key = productKey(p);
            if (seen.has(key)) continue;
            seen.add(key);
            merged.push(p);
          }
        }

        // Final rerank: keep strong lexical matches first, but allow high-similarity
        // vector hits to surface above weak lexical noise. Tags/facets already feed
        // into lexical scoring and embeddings, so this provides a stable blend.
        merged.sort((a, b) => {
          const ak = productKey(a);
          const bk = productKey(b);
          const aLex = lexicalScoreByKey.get(ak) || 0;
          const bLex = lexicalScoreByKey.get(bk) || 0;
          const aVec = vectorScoreByKey.get(ak) || 0;
          const bVec = vectorScoreByKey.get(bk) || 0;
          const aScore = aLex + aVec * 4.0;
          const bScore = bLex + bVec * 4.0;
          return bScore - aScore;
        });

        await applyShopifyCurrencyOverride(merged);
        return {
          products: merged,
          total: Math.max(total, merged.length),
          page: safePage,
          page_size: safeLimit,
          merchantIds: config.merchantIds,
          retrieval_sources: retrievalSources,
        };
      }
    } catch (err) {
      // Fail-open: vector recall is an optional enhancement; do not block lexical search.
      retrievalSources.push({
        source: 'vector_cache',
        used: false,
        error: String(err && err.message ? err.message : err),
      });
    }
  }

  await applyShopifyCurrencyOverride(lexicalProducts);
  return {
    products: lexicalProducts,
    total,
    page: safePage,
    page_size: safeLimit,
    merchantIds: config.merchantIds,
    retrieval_sources: retrievalSources,
  };
}

async function searchCrossMerchantFromCache(queryText, page = 1, limit = 20, options = {}) {
  const safePage = Math.max(1, Number(page || 1));
  const safeLimit = Math.min(Math.max(1, Number(limit || 20)), SEARCH_LIMIT_MAX);
  const offset = (safePage - 1) * safeLimit;
  const q = String(queryText || '').trim().toLowerCase();
  const inStockOnly = options?.inStockOnly !== false;
  const publicBeautyUnifiedSearch = options?.publicBeautyUnifiedSearch === true;
  const normalizedQueryClass = String(
    options?.queryClass || options?.intent?.query_class || '',
  )
    .trim()
    .toLowerCase();
  const beautyQueryProfile =
    options?.beautyQueryProfile && typeof options.beautyQueryProfile === 'object'
      ? options.beautyQueryProfile
      : buildBeautyQueryProfile({
          rawQuery: queryText,
          queryClass: options?.queryClass || options?.intent?.query_class,
          intent: options?.intent,
        });
  const beautyCategoryBrowseFastpath = await tryCrossMerchantBeautyCategoryBrowseFastpath(
    queryText,
    safePage,
    safeLimit,
    {
      ...options,
      beautyQueryProfile,
      inStockOnly,
    },
  );
  if (beautyCategoryBrowseFastpath) {
    return beautyCategoryBrowseFastpath;
  }

  const terms = tokenizeQueryForCache(q, {
    intent: options?.intent,
    queryClass: options?.queryClass || options?.intent?.query_class,
    beautyQueryProfile,
  });
  if (terms.length === 0) {
    return await loadCrossMerchantBrowseFromCache(safePage, safeLimit, { inStockOnly });
  }

  const applyBeautySpecificFilter = (products) =>
    filterBeautySpecificCacheProducts(products, queryText, {
      intent: options?.intent,
      queryClass: options?.queryClass || options?.intent?.query_class,
      beautyQueryProfile,
    });

  const skuLike = looksSkuLikeQuery(q);
  const lookupAnchorTokens = extractSearchAnchorTokens(queryText);
  const lookupLikeQuery =
    skuLike ||
    ['lookup', 'attribute'].includes(normalizedQueryClass) ||
    isLookupStyleSearchQuery(queryText, lookupAnchorTokens) ||
    isKnownLookupAliasQuery(queryText);
  const brandLikeQuery = Boolean(detectBrandEntities(queryText, { candidateProducts: [] })?.brand_like);
  const allowRelaxedNoOnboardingFallback =
    !beautyQueryProfile?.isBeautyQuery || lookupLikeQuery || brandLikeQuery;
  const skipLexicalCountForPublicBeauty =
    publicBeautyUnifiedSearch && beautyQueryProfile?.isBeautyQuery === true;
  const buildQueryFilter = (fieldPrefix = 'pc.', { joinTerms = 'OR' } = {}) => {
    const matchFields = [
      `lower(coalesce(${fieldPrefix}product_data->>'title',''))`,
      `lower(coalesce(${fieldPrefix}product_data->>'description',''))`,
      `lower(coalesce(${fieldPrefix}product_data->>'product_type',''))`,
      `lower(coalesce(${fieldPrefix}product_data->>'sku',''))`,
      `lower(coalesce(${fieldPrefix}product_data->>'vendor',''))`,
      // Brand often lives in a dedicated `brand` field (external seeds mirror it
      // into `vendor`, but reseller/Shopify rows may set `vendor` to the store
      // name with the brand only here), and `tags` carries brand/ingredient
      // facets. Without these a brand query like "cerave" can miss a product
      // that is genuinely in cache. See GH #1659.
      `lower(coalesce(${fieldPrefix}product_data->>'brand',''))`,
      `lower(coalesce(${fieldPrefix}product_data->>'tags',''))`,
    ];
    const whereParts = [];
    const params = [];
    let idx = 1;
    for (const t of terms) {
      params.push(`%${t}%`);
      const ors = matchFields.map((field) => `${field} LIKE $${idx}`).join(' OR ');
      const termParts = [`(${ors})`];
      if (skuLike) {
        termParts.push(`lower(CAST(${fieldPrefix}product_data AS TEXT)) LIKE $${idx}`);
      }
      whereParts.push(`(${termParts.join(' OR ')})`);
      idx += 1;
    }
    // Default OR-over-terms is correct for keyword recall, but it lets a single
    // generic token satisfy a multi-word query (e.g. "paula choice" matching dog
    // harnesses on the word "choice"). Callers can require ALL terms to be
    // present instead, so the full phrase must match. See GH #1659.
    const joiner = joinTerms === 'AND' ? ' AND ' : ' OR ';
    return {
      params,
      idx,
      queryWhere: whereParts.length ? `(${whereParts.join(joiner)})` : 'TRUE',
    };
  };
  // The relaxed fallback drops the onboarding join, widening recall across the
  // whole cache (incl. off-domain merchants). That widening is exactly where a
  // generic token leaks noise — "paula choice" returning dog harnesses on
  // "choice". For any multi-word, non-SKU query we therefore require all terms
  // to match in this widened path so a single common word can't carry it.
  // SKU-like queries keep OR (the raw-blob match is intentionally permissive).
  // See GH #1659.
  const relaxedJoinTerms = !skuLike && terms.length >= 2 ? 'AND' : 'OR';
  const toRankedUniqueProducts = (rows = []) => {
    const rawProducts = (rows || [])
      .map((row) => {
        const product = row.product_data;
        if (!product) return null;

        const merchantId = String(row.merchant_id || '').trim();
        const merchantName = row.merchant_name ? String(row.merchant_name).trim() : '';
        const out = { ...product };
        if (merchantId && !out.merchant_id && !out.merchantId) out.merchant_id = merchantId;
        if (merchantName && !out.merchant_name && !out.merchantName) out.merchant_name = merchantName;
        return out;
      })
      .filter(Boolean)
      .filter((product) => isProductSellable(product, { inStockOnly }));

    const scored = rawProducts
      .map((product) => {
        const title = String(product.title || '').toLowerCase();
        const desc = String(product.description || '').toLowerCase();
        const ptype = String(product.product_type || product.productType || '').toLowerCase();
        const sku = String(product.sku || '').toLowerCase();
        const brand = String(product.brand || product.vendor || '').toLowerCase();
        const tags = Array.isArray(product.tags) ? product.tags.join(' ').toLowerCase() : String(product.tags || '').toLowerCase();
        const blob = `${title} ${ptype} ${sku} ${brand} ${tags} ${desc}`;

        let score = 0;
        for (const t of terms) {
          if (title.includes(t)) score += 3;
          else if (brand.includes(t)) score += 3;
          else if (ptype.includes(t)) score += 2;
          else if (blob.includes(t)) score += 1;
        }
        score += scoreByTagFacetOverlap(terms, product).score;
        if (skuLike) {
          const q0 = q.replace(/[^a-z0-9-]+/g, '');
          if (q0 && sku === q0) score += 6;
          else if (q0 && blob.includes(q0)) score += 3;
        }
        return { product, score };
      })
      .sort((a, b) => b.score - a.score);

    const seen = new Set();
    const unique = [];
    for (const row of scored) {
      const product = row.product;
      const mid = String(product.merchant_id || product.merchantId || '').trim();
      const pid = String(product.id || product.product_id || product.productId || '').trim();
      const key = `${mid}::${pid || JSON.stringify(product).slice(0, 64)}`;
      if (seen.has(key)) continue;
      seen.add(key);
      unique.push(product);
      if (unique.length >= safeLimit) break;
    }
    return { products: unique, candidateCount: rawProducts.length };
  };

  const strictFilter = buildQueryFilter('pc.');
  const queryWhere = strictFilter.queryWhere;
  const baseWhere = `
    (pc.expires_at IS NULL OR pc.expires_at > now())
    AND ${buildSellableStatusPredicate("pc.product_data->>'status'")}
    AND mo.status NOT IN ('deleted', 'rejected')
    AND ${transactionCapableMerchantWhere('mo')}
  `;

  const pageFetch = Math.min(Math.max(safeLimit * 4, 80), 400);
  const pageOffset = Math.max(0, offset);
  const runCacheSql = async (stage, kind, sql, params) => {
    const startedAt = Date.now();
    const result = await query(sql, params);
    return {
      result,
      timing: {
        stage,
        kind,
        duration_ms: Math.max(0, Date.now() - startedAt),
      },
    };
  };

  const countSql = `
    SELECT COUNT(*)::int AS total
    FROM products_cache pc
    JOIN merchant_onboarding mo
      ON mo.merchant_id = pc.merchant_id
    WHERE ${baseWhere}
      AND ${queryWhere}
  `;

  const rowsSql = `
    SELECT pc.merchant_id,
           mo.business_name AS merchant_name,
           pc.product_data
    FROM products_cache pc
    JOIN merchant_onboarding mo
      ON mo.merchant_id = pc.merchant_id
    WHERE ${baseWhere}
      AND ${queryWhere}
    ORDER BY pc.cached_at DESC NULLS LAST, pc.id DESC
    OFFSET $${strictFilter.idx}
    LIMIT $${strictFilter.idx + 1}
  `;

  const retrievalSources = [];
  const strictRowsQuery = await runCacheSql(
    'lexical_cache',
    'rows',
    rowsSql,
    [...strictFilter.params, pageOffset, pageFetch],
  );
  const rowsRes = strictRowsQuery.result;
  const strictCountQuery = skipLexicalCountForPublicBeauty
    ? null
    : await runCacheSql('lexical_cache', 'count', countSql, strictFilter.params);
  const strictTotal = skipLexicalCountForPublicBeauty
    ? Number(rowsRes.rows?.length || 0)
    : Number(strictCountQuery?.result?.rows?.[0]?.total || 0);
  const strictRanked = toRankedUniqueProducts(rowsRes.rows || []);
  const strictFiltered = applyBeautySpecificFilter(strictRanked.products);
  retrievalSources.push({
    source: 'lexical_cache',
    used: true,
    count: strictFiltered.products.length,
    candidate_count: strictRanked.candidateCount,
    total: strictTotal,
    filtered_irrelevant_count: strictFiltered.filtered_irrelevant_count,
    count_query_ms: strictCountQuery?.timing?.duration_ms || 0,
    count_query_skipped: skipLexicalCountForPublicBeauty,
    rows_query_ms: strictRowsQuery.timing.duration_ms,
  });

  if (strictFiltered.products.length > 0) {
    await applyShopifyCurrencyOverride(strictFiltered.products);
    return {
      products: strictFiltered.products,
      total: strictTotal,
      page: safePage,
      page_size: strictFiltered.products.length,
      retrieval_sources: retrievalSources,
      query_terms: terms,
      beauty_query_bucket: beautyQueryProfile?.bucket || null,
      internal_filter_debug: strictFiltered,
    };
  }

  const runBeautyBrowseFallback = async (relaxedTotal = 0) => {
    if (publicBeautyUnifiedSearch) return null;
    if (!hasBeautyMakeupSearchSignal(q)) return null;
    const beautySignalFilter = buildBeautySignalSql(1);
    const beautyRowsSql = `
      SELECT pc.merchant_id,
             mo.business_name AS merchant_name,
             pc.product_data
      FROM products_cache pc
      JOIN merchant_onboarding mo
        ON mo.merchant_id = pc.merchant_id
      WHERE ${baseWhere}
        AND ${beautySignalFilter.sql}
      ORDER BY pc.cached_at DESC NULLS LAST, pc.id DESC
      OFFSET $${beautySignalFilter.nextIndex}
      LIMIT $${beautySignalFilter.nextIndex + 1}
    `;
    const beautyRowsQuery = await runCacheSql(
      'beauty_browse_fallback',
      'rows',
      beautyRowsSql,
      [...beautySignalFilter.params, pageOffset, pageFetch],
    );
    const beautyRowsRes = beautyRowsQuery.result;
    const beautyRanked = toRankedUniqueProducts(beautyRowsRes.rows || []);
    const beautyFiltered = applyBeautySpecificFilter(beautyRanked.products);
    retrievalSources.push({
      source: 'beauty_browse_fallback',
      used: true,
      count: beautyFiltered.products.length,
      candidate_count: beautyRanked.candidateCount,
      filtered_irrelevant_count: beautyFiltered.filtered_irrelevant_count,
      rows_query_ms: beautyRowsQuery.timing.duration_ms,
    });

    if (beautyFiltered.products.length <= 0) return null;
    await applyShopifyCurrencyOverride(beautyFiltered.products);
    return {
      products: beautyFiltered.products,
      total: Math.max(strictTotal, relaxedTotal, beautyFiltered.products.length),
      page: safePage,
      page_size: beautyFiltered.products.length,
      retrieval_sources: retrievalSources,
      query_terms: terms,
      beauty_query_bucket: beautyQueryProfile?.bucket || null,
      internal_filter_debug: beautyFiltered,
    };
  };

  if (!allowRelaxedNoOnboardingFallback) {
    retrievalSources.push({
      source: 'lexical_cache_relaxed_no_onboarding',
      used: false,
      skipped: true,
      reason: publicBeautyUnifiedSearch
        ? 'public_beauty_unified_skip_relaxed_no_onboarding'
        : 'beauty_query_skip_relaxed_no_onboarding',
    });
    if (!publicBeautyUnifiedSearch) {
      const beautyFallbackResult = await runBeautyBrowseFallback(0);
      if (beautyFallbackResult) {
        return beautyFallbackResult;
      }
    }
    return {
      products: [],
      total: strictTotal,
      page: safePage,
      page_size: 0,
      retrieval_sources: retrievalSources,
      query_terms: terms,
      beauty_query_bucket: beautyQueryProfile?.bucket || null,
      internal_filter_debug: applyBeautySpecificFilter([]),
    };
  }

  if (publicBeautyUnifiedSearch && beautyQueryProfile?.isBeautyQuery === true) {
    retrievalSources.push({
      source: 'lexical_cache_relaxed_no_onboarding',
      used: false,
      skipped: true,
      reason: 'public_beauty_unified_skip_relaxed_no_onboarding',
    });
    return {
      products: [],
      total: strictTotal,
      page: safePage,
      page_size: 0,
      retrieval_sources: retrievalSources,
      query_terms: terms,
      beauty_query_bucket: beautyQueryProfile?.bucket || null,
      internal_filter_debug: applyBeautySpecificFilter([]),
    };
  }

  try {
    const relaxedFilter = buildQueryFilter('', { joinTerms: relaxedJoinTerms });
    const relaxedBaseWhere = `
      (expires_at IS NULL OR expires_at > now())
      AND ${activeProductsCacheSourceWhere('products_cache')}
      AND ${buildSellableStatusPredicate("product_data->>'status'")}
      AND COALESCE(lower(product_data->>'orderable'), 'true') <> 'false'
    `;
    const relaxedCountSql = `
      SELECT COUNT(*)::int AS total
      FROM products_cache
      WHERE ${relaxedBaseWhere}
        AND ${relaxedFilter.queryWhere}
    `;
    const relaxedRowsSql = `
      SELECT merchant_id,
             NULL::text AS merchant_name,
             product_data
      FROM products_cache
      WHERE ${relaxedBaseWhere}
        AND ${relaxedFilter.queryWhere}
      ORDER BY cached_at DESC NULLS LAST, id DESC
      OFFSET $${relaxedFilter.idx}
      LIMIT $${relaxedFilter.idx + 1}
    `;
    const [relaxedCountQuery, relaxedRowsQuery] = await Promise.all([
      runCacheSql(
        'lexical_cache_relaxed_no_onboarding',
        'count',
        relaxedCountSql,
        relaxedFilter.params,
      ),
      runCacheSql(
        'lexical_cache_relaxed_no_onboarding',
        'rows',
        relaxedRowsSql,
        [...relaxedFilter.params, pageOffset, pageFetch],
      ),
    ]);
    const relaxedCountRes = relaxedCountQuery.result;
    const relaxedRowsRes = relaxedRowsQuery.result;
    const relaxedTotal = Number(relaxedCountRes.rows?.[0]?.total || 0);
    const relaxedRanked = toRankedUniqueProducts(relaxedRowsRes.rows || []);
    const relaxedFiltered = applyBeautySpecificFilter(relaxedRanked.products);
    retrievalSources.push({
      source: 'lexical_cache_relaxed_no_onboarding',
      used: true,
      count: relaxedFiltered.products.length,
      candidate_count: relaxedRanked.candidateCount,
      total: relaxedTotal,
      filtered_irrelevant_count: relaxedFiltered.filtered_irrelevant_count,
      count_query_ms: relaxedCountQuery.timing.duration_ms,
      rows_query_ms: relaxedRowsQuery.timing.duration_ms,
    });

    if (relaxedFiltered.products.length === 0 && hasPetSearchSignal(q)) {
      const preferHarnessResults = hasPetHarnessSearchSignal(q);
      const petSignalFilter = preferHarnessResults
        ? buildPetHarnessSignalSql(1)
        : buildPetSignalSql(1);
      const petRowsSql = `
        SELECT pc.merchant_id,
               mo.business_name AS merchant_name,
               pc.product_data
        FROM products_cache pc
        JOIN merchant_onboarding mo
          ON mo.merchant_id = pc.merchant_id
        WHERE ${baseWhere}
          AND ${petSignalFilter.sql}
        ORDER BY pc.cached_at DESC NULLS LAST, pc.id DESC
        OFFSET $${petSignalFilter.nextIndex}
        LIMIT $${petSignalFilter.nextIndex + 1}
      `;
      const petRowsQuery = await runCacheSql(
        preferHarnessResults ? 'pet_harness_browse_fallback' : 'pet_browse_fallback',
        'rows',
        petRowsSql,
        [...petSignalFilter.params, pageOffset, pageFetch],
      );
      const petRowsRes = petRowsQuery.result;
      const petRanked = toRankedUniqueProducts(petRowsRes.rows || []);
      const petFiltered = applyBeautySpecificFilter(petRanked.products);
      retrievalSources.push({
        source: preferHarnessResults ? 'pet_harness_browse_fallback' : 'pet_browse_fallback',
        used: true,
        count: petFiltered.products.length,
        candidate_count: petRanked.candidateCount,
        filtered_irrelevant_count: petFiltered.filtered_irrelevant_count,
        rows_query_ms: petRowsQuery.timing.duration_ms,
      });

      if (petFiltered.products.length > 0) {
        await applyShopifyCurrencyOverride(petFiltered.products);
        return {
          products: petFiltered.products,
          total: Math.max(strictTotal, relaxedTotal, petFiltered.products.length),
          page: safePage,
          page_size: petFiltered.products.length,
          retrieval_sources: retrievalSources,
          query_terms: terms,
          beauty_query_bucket: beautyQueryProfile?.bucket || null,
          internal_filter_debug: petFiltered,
        };
      }
    }

    if (relaxedFiltered.products.length === 0) {
      const beautyFallbackResult = await runBeautyBrowseFallback(relaxedTotal);
      if (beautyFallbackResult) {
        return beautyFallbackResult;
      }
    }

    await applyShopifyCurrencyOverride(relaxedFiltered.products);
    return {
      products: relaxedFiltered.products,
      total: Math.max(strictTotal, relaxedTotal, relaxedFiltered.products.length),
      page: safePage,
      page_size: relaxedFiltered.products.length,
      retrieval_sources: retrievalSources,
      query_terms: terms,
      beauty_query_bucket: beautyQueryProfile?.bucket || null,
      internal_filter_debug: relaxedFiltered,
    };
  } catch (err) {
    retrievalSources.push({
      source: 'lexical_cache_relaxed_no_onboarding',
      used: false,
      error: String(err && err.message ? err.message : err),
    });
    return {
      products: [],
      total: strictTotal,
      page: safePage,
      page_size: 0,
      retrieval_sources: retrievalSources,
      query_terms: terms,
      beauty_query_bucket: beautyQueryProfile?.bucket || null,
      internal_filter_debug: applyBeautySpecificFilter([]),
    };
  }
}

async function loadCrossMerchantBrowseFromCache(page = 1, limit = 20, options = {}) {
  const safePage = Math.max(1, Number(page || 1));
  const safeLimit = Math.min(Math.max(1, Number(limit || 20)), SEARCH_LIMIT_MAX);
  const inStockOnly = options?.inStockOnly !== false;

  // Oversample so JS-level filtering (in-stock-only, de-dupe) can still fill the page.
  const fetchLimit = Math.min(Math.max(safeLimit * Math.max(safePage, 1) * 5 + 20, 50), 500);

  const rowsRes = await query(
    `
      SELECT pc.merchant_id,
             mo.business_name AS merchant_name,
             pc.product_data
      FROM (
        SELECT id, expires_at, merchant_id, product_data
        FROM products_cache
        WHERE expires_at > now()
          AND ${activeProductsCacheSourceWhere('products_cache')}
          AND ${buildSellableStatusPredicate("product_data->>'status'")}
        ORDER BY expires_at DESC, id DESC
        LIMIT $1
      ) pc
      JOIN merchant_onboarding mo
        ON mo.merchant_id = pc.merchant_id
      WHERE mo.status NOT IN ('deleted', 'rejected')
        AND ${transactionCapableMerchantWhere('mo')}
      ORDER BY pc.expires_at DESC, pc.id DESC
    `,
    [fetchLimit],
  );

  const baseProducts = (rowsRes.rows || [])
    .map((r) => {
      const p = r.product_data;
      if (!p) return null;
      const mid = String(r.merchant_id || '').trim();
      const merchantName = r.merchant_name ? String(r.merchant_name).trim() : '';

      const out = { ...p };
      if (mid && !out.merchant_id && !out.merchantId) out.merchant_id = mid;
      if (merchantName && !out.merchant_name && !out.merchantName) out.merchant_name = merchantName;
      return out;
    })
    .filter(Boolean)
    .filter((p) => isProductSellable(p, { inStockOnly }));

  const seen = new Set();
  const unique = [];
  for (const p of baseProducts) {
    const mid = String(p.merchant_id || p.merchantId || '').trim();
    const pid = String(p.id || p.product_id || p.productId || '').trim();
    const key = `${mid}::${pid || JSON.stringify(p).slice(0, 64)}`;
    if (seen.has(key)) continue;
    seen.add(key);
    unique.push(p);
  }

  const startIdx = (safePage - 1) * safeLimit;
  const pageItems = unique.slice(startIdx, startIdx + safeLimit);

  await applyShopifyCurrencyOverride(pageItems);

  return {
    products: pageItems,
    total: unique.length,
    page: safePage,
    page_size: pageItems.length,
  };
}

async function loadMerchantBrowseFromCache(merchantId, page = 1, limit = 20, options = {}) {
  const mid = String(merchantId || '').trim();
  if (!mid) return { products: [], total: 0, page: 1, page_size: 0 };

  const safePage = Math.max(1, Number(page || 1));
  const safeLimit = Math.min(Math.max(1, Number(limit || 20)), SEARCH_LIMIT_MAX);
  const inStockOnly = options?.inStockOnly !== false;

  // Oversample so JS-level filtering (in-stock-only, de-dupe) can still fill the page.
  const fetchLimit = Math.min(Math.max(safeLimit * Math.max(safePage, 1) * 6 + 30, 60), 600);

  const rowsRes = await query(
    `
      SELECT pc.id,
             pc.merchant_id,
             mo.business_name AS merchant_name,
             pc.product_data
      FROM products_cache pc
      JOIN merchant_onboarding mo
        ON mo.merchant_id = pc.merchant_id
      WHERE pc.merchant_id = $1
        AND ${activeProductsCacheSourceWhere('pc')}
        AND (pc.expires_at IS NULL OR pc.expires_at > now())
        AND ${buildSellableStatusPredicate("pc.product_data->>'status'")}
        AND mo.status NOT IN ('deleted', 'rejected')
        AND ${transactionCapableMerchantWhere('mo')}
      ORDER BY pc.cached_at DESC NULLS LAST, pc.id DESC
      LIMIT $2
    `,
    [mid, fetchLimit],
  );

  const baseProducts = (rowsRes.rows || [])
    .map((r) => {
      const p = r.product_data;
      if (!p) return null;
      const merchantName = r.merchant_name ? String(r.merchant_name).trim() : '';

      const out = { ...p };
      if (!out.merchant_id && !out.merchantId) out.merchant_id = mid;
      if (merchantName && !out.merchant_name && !out.merchantName) out.merchant_name = merchantName;
      return out;
    })
    .filter(Boolean)
    .filter((p) => isProductSellable(p, { inStockOnly }));

  const seen = new Set();
  const unique = [];
  for (const p of baseProducts) {
    const pid = String(p.id || p.product_id || p.productId || '').trim();
    const key = `${mid}::${pid || JSON.stringify(p).slice(0, 64)}`;
    if (seen.has(key)) continue;
    seen.add(key);
    unique.push(p);
  }

  const startIdx = (safePage - 1) * safeLimit;
  const pageItems = unique.slice(startIdx, startIdx + safeLimit);

  await applyShopifyCurrencyOverride(pageItems);

  return {
    products: pageItems,
    total: unique.length,
    page: safePage,
    page_size: pageItems.length,
  };
}

function buildPetFallbackQuery(intent, rawUserQuery) {
  const lang = intent?.language || 'en';
  const queryText = String(rawUserQuery || '');
  const wantsHarness = hasPetHarnessSearchSignal(queryText);
  switch (lang) {
    case 'zh':
      return wantsHarness ? '狗 狗狗 宠物 背带 牵引绳 狗链' : '狗 狗狗 宠物 外套 衣服';
    case 'es':
      return wantsHarness ? 'perro arnes correa collar' : 'perro ropa abrigo chaqueta';
    case 'fr':
      return wantsHarness ? 'chien harnais laisse collier' : 'chien vêtement manteau veste';
    case 'ja':
      return wantsHarness ? '犬 ハーネス リード 首輪' : '犬 犬服 服';
    default:
      return wantsHarness ? 'dog harness dog leash dog collar' : 'dog jacket dog clothes';
  }
}

async function loadCreatorProductFromCache(creatorId, productId) {
  const config = getCreatorConfig(creatorId);
  if (!config || !Array.isArray(config.merchantIds) || config.merchantIds.length === 0) return null;
  const pid = String(productId || '').trim();
  if (!pid) return null;

  const res = await query(
    `
      SELECT product_data
      FROM products_cache
      WHERE merchant_id = ANY($1)
        AND ${activeProductsCacheSourceWhere('products_cache')}
        AND (expires_at IS NULL OR expires_at > now())
        AND (
          product_data->>'id' = $2
          OR product_data->>'product_id' = $2
          OR product_data->>'productId' = $2
        )
      ORDER BY cached_at DESC
      LIMIT 1
    `,
    [config.merchantIds, pid],
  );
  return res.rows?.[0]?.product_data || null;
}

async function findSimilarCreatorFromCache(creatorId, productId, limit = 9) {
  const base = await loadCreatorProductFromCache(creatorId, productId);
  if (!base) return null;

  const baseTitle = String(base.title || '').toLowerCase();
  const baseDesc = String(base.description || '').toLowerCase();
  const baseType = String(base.product_type || base.productType || '').toLowerCase();
  const baseTags = Array.isArray(base.tags) ? base.tags.join(' ').toLowerCase() : String(base.tags || '').toLowerCase();
  const baseRecTags = Array.isArray(base.recommendation_meta?.tags)
    ? base.recommendation_meta.tags.join(' ').toLowerCase()
    : '';
  const baseRecFacets = base.recommendation_meta?.facets ? JSON.stringify(base.recommendation_meta.facets).toLowerCase() : '';
  const baseBlob = `${baseTitle} ${baseType} ${baseTags} ${baseRecTags} ${baseRecFacets} ${baseDesc}`.trim();

  const baseToy = /\b(labubu|doll|plush|toy|collectible)\b/.test(baseBlob);
  const baseUnderwear = /\b(lingerie|underwear|bra|pant(y|ies)|thong|sleepwear|nightgown|nightdress)\b/.test(baseBlob);

  const anchor = [];
  if (baseBlob.includes('labubu')) anchor.push('labubu');
  if (/\bdoll\b/.test(baseBlob)) anchor.push('doll');
  if (/\boutfit\b/.test(baseBlob)) anchor.push('outfit');
  if (anchor.length === 0) {
    // Prefer tags/facets (more stable than title words), then fallback to title tokens.
    const tagTokens = [];
    if (Array.isArray(base.tags)) tagTokens.push(...base.tags);
    if (Array.isArray(base.recommendation_meta?.tags)) tagTokens.push(...base.recommendation_meta.tags);
    const facets = base.recommendation_meta?.facets || {};
    for (const v of Object.values(facets)) {
      if (!v) continue;
      if (Array.isArray(v)) tagTokens.push(...v);
      else tagTokens.push(v);
    }
    anchor.push(...tokenizeQueryForCache(tagTokens.join(' ')).slice(0, 6));
    if (anchor.length < 3) anchor.push(...tokenizeQueryForCache(baseTitle).slice(0, 3));
  }

  const queryText = anchor.join(' ');
  const found = await searchCreatorSellableFromCache(creatorId, queryText, 1, Math.min(Math.max(6, limit * 3), 60));
  const candidates = (found.products || []).filter((p) => String(p.id || p.product_id || '') !== String(productId));

  const filtered = candidates.filter((p) => {
    const t = `${String(p.title || '').toLowerCase()} ${String(p.description || '').toLowerCase()} ${String(
      p.product_type || p.productType || '',
    ).toLowerCase()}`;
    const isUnderwear = /\b(lingerie|underwear|bra|pant(y|ies)|thong|sleepwear|nightgown|nightdress)\b/.test(t);
    if (baseToy && !baseUnderwear && isUnderwear) return false;
    return true;
  });

  const ranked = filtered
    .map((p) => ({ p, score: scorePairOverlap(base, p).score }))
    .sort((a, b) => b.score - a.score)
    .map((x) => x.p);

  return {
    base_product_id: String(productId),
    strategy_used: 'cache_creator_similar',
    items: ranked.slice(0, Math.max(1, Number(limit || 9))).map((p) => ({ product: p })),
  };
}

function extractCreatorId(payload) {
  if (!payload) return null;
  return (
    payload.creator_id ||
    payload.creatorId ||
    payload.metadata?.creator_id ||
    payload.metadata?.creatorId ||
    payload.search?.creator_id ||
    payload.similar?.creator_id ||
    null
  );
}

function getDefaultCreatorId() {
  const env =
    process.env.DEFAULT_CREATOR_ID ||
    process.env.CREATOR_ID ||
    '';
  const trimmed = String(env || '').trim();
  if (trimmed) return trimmed;

  const first =
    Array.isArray(CREATOR_CONFIGS) &&
    CREATOR_CONFIGS[0] &&
    CREATOR_CONFIGS[0].creatorId
      ? String(CREATOR_CONFIGS[0].creatorId).trim()
      : '';
  return first || null;
}

function normalizeMetadata(rawMetadata = {}, payload = {}) {
  let creatorId =
    rawMetadata.creator_id ||
    rawMetadata.creatorId ||
    payload.creator_id ||
    payload.creatorId ||
    payload.search?.creator_id ||
    null;

  const creatorName =
    rawMetadata.creator_name ||
    rawMetadata.creatorName ||
    payload.creator_name ||
    payload.creatorName ||
    null;

  const traceId =
    rawMetadata.trace_id ||
    rawMetadata.traceId ||
    payload.trace_id ||
    payload.traceId ||
    null;

  const source = rawMetadata.source || payload.source || 'shopping-agent-ui';

  // Creator cache routes require a known creator_id. When the caller is the
  // creator UI and doesn't provide one, default to the first configured creator
  // so cache-based search works out of the box.
  if (!creatorId && isCreatorUiSource(source)) {
    creatorId = getDefaultCreatorId();
  }

  return {
    ...rawMetadata,
    ...(creatorId && { creator_id: creatorId, creatorId }),
    ...(creatorName && { creator_name: creatorName, creatorName }),
    ...(traceId && { trace_id: traceId, traceId }),
    ...(source && { source }),
  };
}

function shouldUseGatewayGovernanceShadowMode(routeContext = {}) {
  const raw =
    routeContext.gateway_governance_shadow_mode ??
    routeContext.gatewayGovernanceShadowMode ??
    process.env.PIVOTA_GATEWAY_GOVERNANCE_SHADOW_MODE;
  return ['1', 'true', 'yes', 'on'].includes(String(raw || '').trim().toLowerCase());
}

function collectGatewayGovernanceReasonCodes(gatewayGovernanceAudit = null) {
  if (!isPlainObject(gatewayGovernanceAudit)) return [];
  return uniqueStrings([
    ...(Array.isArray(gatewayGovernanceAudit.reason_codes)
      ? gatewayGovernanceAudit.reason_codes
      : []),
    ...(Array.isArray(gatewayGovernanceAudit.query_governance?.reason_codes)
      ? gatewayGovernanceAudit.query_governance.reason_codes
      : []),
    ...(Array.isArray(gatewayGovernanceAudit.rate_limit?.reason_codes)
      ? gatewayGovernanceAudit.rate_limit.reason_codes
      : []),
  ]);
}

function mergeInvokeGatewayAuditMetadata(body, gatewayGovernanceAudit = null) {
  if (!isPlainObject(body) || !isPlainObject(gatewayGovernanceAudit)) return body;
  const existingMeta = isPlainObject(body.metadata) ? body.metadata : {};
  const existingInvocation = isPlainObject(existingMeta.gateway_invocation)
    ? existingMeta.gateway_invocation
    : {};
  const existingGovernance = isPlainObject(existingMeta.gateway_governance)
    ? existingMeta.gateway_governance
    : {};
  const governanceReasonCodes = collectGatewayGovernanceReasonCodes(gatewayGovernanceAudit);
  const responseReasonCodes = Array.isArray(body.reason_codes)
    ? body.reason_codes
    : body.reason_codes
      ? [body.reason_codes]
      : [];
  const mergedReasonCodes = uniqueStrings([...responseReasonCodes, ...governanceReasonCodes]);

  return {
    ...body,
    ...(mergedReasonCodes.length ? { reason_codes: mergedReasonCodes } : {}),
    metadata: {
      ...existingMeta,
      gateway_invocation: {
        ...existingInvocation,
        ...(isPlainObject(gatewayGovernanceAudit.invocation)
          ? gatewayGovernanceAudit.invocation
          : {}),
      },
      gateway_governance: {
        ...existingGovernance,
        mode: gatewayGovernanceAudit.mode || existingGovernance.mode || null,
        source: gatewayGovernanceAudit.source || existingGovernance.source || null,
        entry_layer: gatewayGovernanceAudit.entry_layer || existingGovernance.entry_layer || null,
        task_type: gatewayGovernanceAudit.task_type || existingGovernance.task_type || null,
        effective_action:
          gatewayGovernanceAudit.effective_action || existingGovernance.effective_action || null,
        observed_phase:
          gatewayGovernanceAudit.observed_phase || existingGovernance.observed_phase || null,
        observed_action:
          gatewayGovernanceAudit.observed_action || existingGovernance.observed_action || null,
        would_enforce: gatewayGovernanceAudit.would_enforce === true,
        reason_codes: governanceReasonCodes,
        access: isPlainObject(gatewayGovernanceAudit.access)
          ? gatewayGovernanceAudit.access
          : existingGovernance.access || {},
        rate_limit: isPlainObject(gatewayGovernanceAudit.rate_limit)
          ? gatewayGovernanceAudit.rate_limit
          : existingGovernance.rate_limit || {},
        query_governance: isPlainObject(gatewayGovernanceAudit.query_governance)
          ? gatewayGovernanceAudit.query_governance
          : existingGovernance.query_governance || {},
      },
    },
  };
}

function normalizeGovernanceShadowBlockContract(body) {
  if (!isPlainObject(body) || !isPlainObject(body.metadata)) return body;
  const metadata = body.metadata;
  const gatewayGovernance = isPlainObject(metadata.gateway_governance)
    ? metadata.gateway_governance
    : {};
  const mode = String(gatewayGovernance.mode || '').trim().toLowerCase();
  const observedAction = String(gatewayGovernance.observed_action || '').trim().toLowerCase();
  if (mode !== 'shadow' || observedAction !== 'block' || gatewayGovernance.would_enforce !== true) {
    return body;
  }

  const governanceReasonCodes = uniqueStrings([
    ...(Array.isArray(gatewayGovernance.reason_codes) ? gatewayGovernance.reason_codes : []),
    ...(Array.isArray(gatewayGovernance.query_governance?.reason_codes)
      ? gatewayGovernance.query_governance.reason_codes
      : []),
    ...(Array.isArray(gatewayGovernance.rate_limit?.reason_codes)
      ? gatewayGovernance.rate_limit.reason_codes
      : []),
  ]);
  const primaryReason = governanceReasonCodes[0] || 'gateway_governance';
  const existingSearchDecision = isPlainObject(metadata.search_decision)
    ? metadata.search_decision
    : {};
  const existingRouteHealth = isPlainObject(metadata.route_health) ? metadata.route_health : {};
  const existingShadowContract = isPlainObject(metadata.governance_shadow_contract)
    ? metadata.governance_shadow_contract
    : {};
  const responseReasonCodes = Array.isArray(body.reason_codes)
    ? body.reason_codes
    : body.reason_codes
      ? [body.reason_codes]
      : [];
  const querySource = String(metadata.query_source || '').trim() || null;
  const finalDecision = String(existingSearchDecision.final_decision || '').trim() || null;

  return {
    ...body,
    reason_codes: uniqueStrings([...responseReasonCodes, ...governanceReasonCodes]),
    metadata: {
      ...metadata,
      search_decision: {
        ...existingSearchDecision,
        ...(querySource && !existingSearchDecision.decision_authority
          ? { decision_authority: querySource }
          : {}),
      },
      route_health: {
        ...existingRouteHealth,
        observer_nodes: uniqueStrings([
          ...(Array.isArray(existingRouteHealth.observer_nodes)
            ? existingRouteHealth.observer_nodes
            : []),
          'governance_shadow_block_observed',
        ]),
      },
      governance_shadow_contract: {
        ...existingShadowContract,
        normalized: false,
        observer_only: true,
        recovery_reason: `${primaryReason}_shadow_block`,
        original_query_source: querySource,
        original_final_decision: finalDecision,
        governance_reason_codes: governanceReasonCodes,
      },
    },
  };
}

function buildInvokeGatewayGovernanceAudit({
  req,
  routeContext = {},
  operation,
  payload,
  metadata,
  gatewayRequestId,
} = {}) {
  const normalizedOperation = String(operation || '').trim().toLowerCase();
  if (!['find_products', 'find_products_multi'].includes(normalizedOperation)) return null;
  if (!shouldUseGatewayGovernanceShadowMode(routeContext)) return null;

  const envelope = prepareGatewayGovernanceEnvelope(
    buildInvokeIngressGatewayInput({
      req,
      routeContext,
      operation: normalizedOperation,
      payload,
      metadata,
      request_id: gatewayRequestId,
    }),
  );
  const audit = buildGatewayShadowAudit(envelope, { shadow_mode: true });
  return isPlainObject(audit) && audit.would_enforce === true ? audit : null;
}

function resolveFindProductsMultiBudgetConstraintForDirectPath(
  priceConstraint,
  products = [],
  fallbackProducts = [],
) {
  if (
    !priceConstraint ||
    (priceConstraint.min == null && priceConstraint.max == null)
  ) {
    return { constraint: null, metadata: null };
  }
  const candidateProduct =
    (Array.isArray(products) ? products : []).find((product) => getProductPriceCurrency(product, '')) ||
    (Array.isArray(fallbackProducts) ? fallbackProducts : []).find((product) =>
      getProductPriceCurrency(product, ''),
    ) ||
    null;
  const candidateCurrency = getProductPriceCurrency(candidateProduct, 'USD');
  return resolveBudgetConstraintForCurrency(priceConstraint, candidateCurrency);
}

function resolveDirectBudgetCandidateCurrency(priceConstraint, product) {
  const sourceCurrency = getProductPriceCurrency(
    { currency: priceConstraint?.currency },
    '',
  );
  return getProductPriceCurrency(product, sourceCurrency || 'USD');
}

function chooseDirectBudgetResponseCurrency(priceConstraint, eligible = []) {
  const sourceCurrency = getProductPriceCurrency(
    { currency: priceConstraint?.currency },
    '',
  );
  const counts = new Map();
  for (const item of eligible) {
    const currency = String(item?.currency || '').trim().toUpperCase();
    if (!currency) continue;
    counts.set(currency, (counts.get(currency) || 0) + 1);
  }
  // This strict direct rail currently recalls US-market external seeds; keep the
  // response in a single currency and preserve the established USD-normalized
  // budget contract when USD candidates are available.
  if (counts.has('USD')) return 'USD';
  if (sourceCurrency && counts.has(sourceCurrency)) return sourceCurrency;
  const [best] = Array.from(counts.entries()).sort((left, right) => {
    const countDelta = Number(right[1] || 0) - Number(left[1] || 0);
    if (countDelta !== 0) return countDelta;
    return String(left[0]).localeCompare(String(right[0]));
  });
  return best?.[0] || sourceCurrency || '';
}

function filterFindProductsMultiDirectProductsByBudget(priceConstraint, products = []) {
  const list = Array.isArray(products) ? products : [];
  if (!priceConstraint || (priceConstraint.min == null && priceConstraint.max == null)) {
    const resolution = resolveFindProductsMultiBudgetConstraintForDirectPath(
      priceConstraint,
      list,
      list,
    );
    return { products: list, resolution, filteredOut: 0 };
  }

  const eligible = [];
  let firstResolution = null;
  for (const product of list) {
    const currency = resolveDirectBudgetCandidateCurrency(priceConstraint, product);
    const resolution = resolveBudgetConstraintForCurrency(priceConstraint, currency);
    if (!firstResolution) firstResolution = resolution;
    if (!resolution.constraint) continue;
    if (!isWithinPriceConstraint(getProductPriceMajor(product), resolution.constraint)) continue;
    eligible.push({ product, currency, resolution });
  }

  const responseCurrency = chooseDirectBudgetResponseCurrency(priceConstraint, eligible);
  const responseProducts = responseCurrency
    ? eligible
        .filter((item) => String(item.currency || '').trim().toUpperCase() === responseCurrency)
        .map((item) => item.product)
    : [];
  const responseResolution =
    responseCurrency
      ? resolveBudgetConstraintForCurrency(priceConstraint, responseCurrency)
      : firstResolution || resolveFindProductsMultiBudgetConstraintForDirectPath(priceConstraint, list, list);
  const currencyFilteredOut = Math.max(0, eligible.length - responseProducts.length);
  return {
    products: responseProducts,
    resolution: responseResolution,
    filteredOut: Math.max(0, list.length - responseProducts.length),
    currencyFilteredOut,
  };
}

function resolveBeautyMainlineBudgetConstraint({ search = {}, intent = null, queryText = '' } = {}) {
  const explicitMin = parseQueryNumber(search.price_min ?? search.min_price);
  const explicitMax = parseQueryNumber(search.price_max ?? search.max_price);
  const explicitCurrency = getProductPriceCurrency({
    currency: firstNonEmptyString(
      search.currency,
      search.price_currency,
      search.priceCurrency,
      search.currency_code,
    ),
  }, '');
  if (explicitMin != null || explicitMax != null) {
    return {
      currency: explicitCurrency || null,
      min: explicitMin,
      max: explicitMax,
    };
  }

  const intentPrice = intent?.hard_constraints?.price || null;
  if (intentPrice && (intentPrice.min != null || intentPrice.max != null)) {
    return intentPrice;
  }

  const parsedPrice =
    extractIntentRuleBased(String(queryText || '').trim(), [], [])?.hard_constraints?.price || null;
  if (parsedPrice && (parsedPrice.min != null || parsedPrice.max != null)) {
    return parsedPrice;
  }

  return null;
}

const AURORA_CHATBOX_ORIGINS = new Set([
  'https://pivota-aurora-chatbox.vercel.app',
]);

// CORS configuration - allow UI to call Gateway
// NOTE: Must run BEFORE body parsing so browser clients still receive CORS headers
// even when JSON parsing fails (otherwise Aurora Chatbox sees "No Access-Control-Allow-Origin").
app.use((req, res, next) => {
  const origin = req.headers.origin;
  const defaults = [
    'https://agent.pivota.cc',
    'https://creator.pivota.cc',
    'https://aurora.pivota.cc',
    ...AURORA_CHATBOX_ORIGINS,
    'http://localhost:3000',
    'http://localhost:5173',
    'http://127.0.0.1:3000',
    'http://127.0.0.1:5173',
  ];

  const fromEnv = String(process.env.ALLOWED_ORIGINS || process.env.CORS_ALLOWED_ORIGINS || '')
    .split(',')
    .map((s) => s.trim())
    .filter(Boolean);

  const allowedOrigins = new Set([...defaults, ...fromEnv]);

  // Prevent CDN/proxy caching from mixing preflight responses across different
  // requested headers/methods.
  res.header('Vary', 'Origin, Access-Control-Request-Headers, Access-Control-Request-Method');

  const isAllowedOrigin = origin && origin !== 'null' && allowedOrigins.has(origin);
  if (isAllowedOrigin) {
    res.header('Access-Control-Allow-Origin', origin);
    res.header('Access-Control-Allow-Credentials', 'true');
  }

  res.header('Access-Control-Allow-Methods', 'GET, POST, PUT, PATCH, DELETE, OPTIONS');

  // Allow both legacy and newer header names used by clients (Creator UI / SDKs).
  // Also echo requested headers to avoid preflight failures when browsers add new ones.
  const baseAllowedHeaders = [
    'content-type',
    'authorization',
    'x-api-key',
    'x-agent-api-key',
    'x-checkout-token',

    // Aurora Chatbox / Glow integration headers
    'x-aurora-uid',
    'x-aurora-lang',
    'x-trace-id',
    'x-brief-id',
    'x-lang',
    'x-session-id',
  ];
  const requested = String(req.headers['access-control-request-headers'] || '')
    .split(',')
    .map((s) => s.trim().toLowerCase())
    .filter(Boolean);
  const allowedHeaders = Array.from(new Set([...baseAllowedHeaders, ...requested]))
    .map((h) => h
      .split('-')
      .map((part) => part.charAt(0).toUpperCase() + part.slice(1))
      .join('-'))
    .join(', ');
  res.header('Access-Control-Allow-Headers', allowedHeaders);

  // Handle preflight requests
  if (req.method === 'OPTIONS') {
    return res.sendStatus(204);
  }

  next();
});

registerCommercePaymentWebhookRoute();

// Early hard body-size cap for the PUBLIC (auth:none) MCP paths — and the UCP order-webhook, which is
// equally unauthenticated pre-signature. Registered BEFORE the global 10MB JSON parser so an
// unauthenticated caller cannot force a large parse — including a CHUNKED request with no
// Content-Length (which the route's own header check can't catch). 32KB is ample for a JSON-RPC read
// call and for any order-event payload.
app.use((req, res, next) => {
  if (req.method !== 'POST') return next();
  const p = req.path;
  // Express routes case-insensitively and tolerates trailing slashes (caseSensitive/strict default
  // off), so EVERY comparison here must normalize the same way — otherwise `POST /PUBLIC/MCP`, `/mcp/`
  // or `/ucp/order-webhook/` reaches the handler while skipping this cap and buffering via the 10MB
  // global parser. The route's own content-length check cannot cover the gap: it is blind to a CHUNKED
  // request, which is exactly what this middleware exists to stop.
  const pNorm = p.toLowerCase().replace(/\/+$/, '');
  const isPublicPath =
    pNorm === '/public/mcp' ||
    pNorm === '/ucp/order-webhook' ||
    (pNorm === '/mcp' && isPublicReadMcpEnabled() && isPublicReadMcpHostRequest(req));
  if (!isPublicPath) return next();
  const cap = PUBLIC_READ_MCP_MAX_BODY_BYTES;
  const cl = Number(req.headers['content-length']);
  if (Number.isFinite(cl) && cl > cap) {
    return res.status(413).json({ error: 'payload_too_large' });
  }
  // Chunked / no-Content-Length: count bytes off the stream and abort past the cap before the JSON parser
  // downstream can buffer 10MB. Both this listener and express.json read the same stream; destroying the
  // request here makes the parser fail closed rather than complete a large parse.
  let bytes = 0;
  let tripped = false;
  req.on('data', (chunk) => {
    if (tripped) return;
    bytes += chunk.length;
    if (bytes > cap) {
      tripped = true;
      if (!res.headersSent) res.status(413).json({ error: 'payload_too_large' });
      req.destroy();
    }
  });
  return next();
});

// Should this request's EXACT wire bytes be stashed on `req.rawBody`?
//
// YES for the ACP doors (their HMAC Signature binds the exact signed bytes, so the adapter must verify/parse
// rawBody rather than a re-stringified body) and for the UCP order-webhook (its detached JWS binds them the
// same way). Exact-path match after stripping the query string and normalizing case + trailing slashes —
// Express routes `/UCP/order-webhook/` to the handler (caseSensitive/strict default off), so the stash must
// match the same way, while a bare startsWith would also capture unrelated siblings like a future
// /ucp/order-webhook-config route.
//
// NEVER for ACP delegate_payment. That body carries raw cardholder data (FPAN + CVC) and Pivota permanently
// refuses the endpoint WITHOUT reading it (safety-kernel/src/protocol/delegatedPaymentRefusal.js). The stash
// exists to be HMAC'd; the refusal never authenticates, so a stash here would have no consumer at all and
// would only keep a PAN and a CVC alive on the request object for the life of the request.
//
// Exported on `_debug` because that carve-out is a security property worth asserting directly.
//
// BOTH comparisons read `pathOnly`, never the raw url. The prefix test used to run against `u`, which is
// case-sensitive and still carries the query string — so `/ACP/checkout_sessions` (which Express DOES route
// to the ACP handler, caseSensitive default off) got no stash, and the adapter then HMAC'd `${timestamp}.`
// against a signature the platform computed over the real bytes. That failed closed — signature_mismatch,
// and trustedBody() throws missing_raw_body behind it — but it made one door reachable-yet-unusable by its
// spelling, which is the same defect class as the surface Set at isCommerceMcpJsonRpcPath. One normalized
// spelling for the whole function is the point; the delegate_payment carve-out above already read pathOnly,
// so the PAN promise was never the half that drifted.
function shouldCaptureAcpRawBody(url) {
  const u = typeof url === 'string' ? url : '';
  const pathOnly = u.split('?')[0].toLowerCase().replace(/\/+$/, '');
  if (pathOnly === `${COMMERCE_ACP_BASE_PATH}${ACP_DELEGATE_PAYMENT_SUBPATH}`) return false;
  return pathOnly.startsWith(`${COMMERCE_ACP_BASE_PATH}/`) || pathOnly === '/ucp/order-webhook';
}

// Is this the ACP delegate_payment door? That request body carries raw cardholder data (FPAN + CVC) for a
// door Pivota permanently refuses without reading (delegatedPaymentRefusal.js). Denying the rawBody stash is
// not the strongest form of that promise — the JSON parser would still materialize the PAN on `req.body`.
// So the parser SKIPS this path entirely (express.json's `type` predicate): the bytes are never parsed, never
// land on the request object, and the refusal answers from a constant. The route stays registered in the LATE
// block, so the caller-identity access log still records WHO knocked on a cardholder-data door.
function isAcpDelegatePaymentRequest(req) {
  const u = req?.originalUrl || req?.url || '';
  const pathOnly = String(u).split('?')[0].toLowerCase().replace(/\/+$/, '');
  return pathOnly === `${COMMERCE_ACP_BASE_PATH}${ACP_DELEGATE_PAYMENT_SUBPATH}`;
}

// Body parser with error handling
app.use(express.json({
  limit: '10mb',
  // express.json's default media-type match (`application/json`, parameters ignored), spelled inline so this
  // does not depend on body-parser's transitive `type-is` — EXCEPT the cardholder-data door, never parsed.
  type: (req) => {
    if (isAcpDelegatePaymentRequest(req)) return false;
    const ct = String(req.headers['content-type'] || '').split(';')[0].trim().toLowerCase();
    return ct === 'application/json';
  },
  verify: (req, res, buf, encoding) => {
    try {
      JSON.parse(buf);
    } catch(e) {
      throw new Error('Invalid JSON');
    }
    if (buf && buf.length && shouldCaptureAcpRawBody(req.originalUrl || req.url || '')) {
      req.rawBody = buf.toString(encoding || 'utf8');
    }
  }
}));

// Add a lightweight build marker for debugging deployments (no secrets).
app.use((req, res, next) => {
  if (SERVICE_GIT_SHA_SHORT) {
    res.setHeader('X-Service-Commit', SERVICE_GIT_SHA_SHORT);
    res.setHeader('X-Aurora-Git-Sha', SERVICE_GIT_SHA_SHORT);
  }
  if (SERVICE_DEPLOYMENT_ID) res.setHeader('X-Service-Deployment-Id', SERVICE_DEPLOYMENT_ID);
  if (SERVICE_GIT_BRANCH) res.setHeader('X-Service-Branch', SERVICE_GIT_BRANCH);
  res.setHeader('X-Aurora-Build', SERVICE_BUILD_ID);
  res.setHeader('X-Service-Name', SERVICE_NAME);
  return next();
});

async function handleCatalogImageCacheAsset(req, res) {
  const key = normalizeCatalogImageCacheKey(`catalog-image-cache/${req.params[0] || ''}`);
  if (!key) {
    return res.status(404).json({ error: 'IMAGE_NOT_FOUND', reason: 'invalid_cache_key' });
  }
  try {
    const object = await getCatalogImageCacheObject(key);
    const contentType = object.ContentType || 'application/octet-stream';
    const cacheControl = object.CacheControl || 'public, max-age=31536000, immutable';
    res.setHeader('Content-Type', contentType);
    res.setHeader('Cache-Control', cacheControl);
    res.setHeader('X-Catalog-Image-Cache', 's3');
    if (object.ContentLength != null) {
      res.setHeader('Content-Length', String(object.ContentLength));
    }
    if (req.method === 'HEAD') return res.status(200).end();
    const body = object.Body;
    if (body && typeof body.pipe === 'function') {
      return body.pipe(res);
    }
    if (body && typeof body.transformToByteArray === 'function') {
      const bytes = await body.transformToByteArray();
      return res.status(200).send(Buffer.from(bytes));
    }
    if (body && typeof body.transformToString === 'function') {
      return res.status(200).send(await body.transformToString());
    }
    return res.status(502).json({ error: 'IMAGE_CACHE_READ_FAILED', reason: 'empty_body' });
  } catch (error) {
    const code = String(error?.name || error?.Code || error?.code || '').toLowerCase();
    const status = code.includes('nosuchkey') || code.includes('notfound') || code.includes('invalid_cache_key') ? 404 : 502;
    logger.warn({ err: error?.message || String(error), key }, 'Catalog image cache asset read failed');
    return res.status(status).json({
      error: status === 404 ? 'IMAGE_NOT_FOUND' : 'IMAGE_CACHE_READ_FAILED',
      reason: status === 404 ? 'cache_object_missing' : 'cache_read_failed',
    });
  }
}

app.get('/catalog-image-cache/*', handleCatalogImageCacheAsset);
app.head('/catalog-image-cache/*', handleCatalogImageCacheAsset);

// public/ holds exactly one file: index.html, the "Pivota Shopping Agent (Internal UI)" chat page
// that POSTs to /ui/chat. It must not be served on the PUBLIC read tier hosts. mcp.pivota.cc is the
// UCP identity anchor (UCP_AGENT_PROFILE_URL) and was chosen because it is the public,
// unauthenticated, STATIC read tier; serving an interactive internal console at its root both
// contradicts that rationale and hands every crawler a working recipe for the LLM endpoint. Edge
// logs for 2026-08-18..20 show that page returned 200 to 22 outside IPs, GPTBot included.
//
// Skipping the mount (rather than 404ing inside it) leaves the request to fall through to the
// normal not-found handling, so the public host's shape is "this path does not exist" — the same
// answer it gives for any other absent path.
const internalUiStatic = express.static(path.join(__dirname, '..', 'public'));
app.use((req, res, next) => {
  if (isPublicReadMcpHostRequest(req)) return next();
  return internalUiStatic(req, res, next);
});

// Lightweight request logging.
//
// Now carries CALLER IDENTITY. Without it this log could not answer the one
// question the public doors exist to answer -- 2026-07-31: /mcp showed 20 POSTs
// attributable to nobody, several of them our own probes. `caller_class` makes
// "did anything but us call this week" a countable query rather than a squint
// at User-Agent strings. Headers only; never the client IP, never a key value.
app.use((req, res, next) => {
  const start = Date.now();
  res.on('finish', () => {
    const caller = describeCaller(req);
    logger.info({
      method: req.method,
      path: req.path,
      status: res.statusCode,
      duration_ms: Date.now() - start,
      caller_class: caller.caller_class,
      caller_ua: caller.ua,
      caller_origin: caller.origin,
      caller_authed: caller.authed,
      build_id: SERVICE_BUILD_ID,
      service_commit: SERVICE_GIT_SHA_SHORT,
    });
  });
  next();
});

// ---------------- Aurora BFF surface: not served on the branded public hosts ----------------
//
// Registered HERE, above every route registration, and that position is load-bearing.
//
// The first version of this sat immediately before mountAuroraBffRoutes(). Review found five /v1
// routes that are mounted EARLIER — mountUiEventRoutes (/v1/events), mountExternalOfferRoutes
// (/v1/offers/external/{resolve,batchResolve}) and mountRecommendationRoutes
// (/v1/recommendations/{feed,roles/normalize}) — so Express matched and terminated in those layers
// and the guard never ran. They were reachable anonymously on the anchor and the partner host, and
// /v1/events is anonymous ingest that fans out to PostHog and writes a budget-preference signal
// against a CALLER-SUPPLIED aurora_uid. "Matched by prefix, so a route added later defaults to
// refused" was only true for routes registered after the guard; from up here it is true of all of
// them, in both directions.
//
// See services/auroraSurfaceHostGuard.js for the measurement behind the host set, and for why this
// is a shape decision (Host is caller-controlled) rather than the lock.
app.use(function auroraSurfaceHostGuardMiddleware(req, res, next) {
  const access = decideAuroraSurfaceAccess({
    path: req.path,
    host: req.headers?.host,
    isPublicReadHost: isPublicReadMcpHostRequest(req),
  });
  if (access.allow) return next();
  logger.warn(
    {
      reason: access.reason,
      host: String(req.headers?.host || ''),
      path: req.path,
      method: req.method,
      status: access.status,
    },
    'aurora surface refused on a branded host',
  );
  return res.status(access.status).json(access.body);
});

// The durable rollup behind the Phase 1 flip gate. `railway logs` cannot supply the full traffic day
// step 3 is gated on — it returns only the live deployment and minutes of history — so the counts are
// kept in commerce_kv instead. See services/auroraSurfaceAuthRollup.js.
//
// Uses the CANONICAL pool from src/db, not a new one. The first version built its own `pg` Pool, which
// had no 'error' listener: an idle connection killed server-side (a Postgres restart, a failover, a
// Railway proxy recycle, an ops pg_terminate_backend) emits on the pool, and with no listener Node
// terminates the process. Reproduced. src/db/index.js already registers that handler and resets the
// pool, and also sets statement_timeout/query_timeout and the repo's full SSL predicate — all three
// of which the hand-rolled pool got wrong or omitted. A counter does not get its own connection
// budget, and this service has a documented history of wedging on pool proliferation.
const auroraAuthRollup = createAuroraAuthRollup({
  logger,
  query: process.env.DATABASE_URL ? (sql, params) => require('./db').query(sql, params) : undefined,
});
auroraAuthRollup.start();

// ---------------- Aurora BFF surface: caller authentication (OBSERVE by default) ----------------
//
// Phase 1 step 1. See services/auroraSurfaceAuth.js for the rollout and for why enforce mode is
// implemented now rather than in the flip PR.
//
// Registered immediately after the host guard so both decisions cover the SAME set of paths — the
// surface is defined once, in isAuroraSurfacePath, and imported here rather than re-derived. A
// second copy of that predicate is a predicate that drifts, and the two guards disagreeing about
// what "the Aurora surface" means is exactly how a route ends up host-refused but never auth-checked.
//
// In observe mode this middleware CANNOT change a response: it logs and calls next(). The log line is
// the deliverable — `would_refuse` is the measurement that gates the flip, and it must reach 0 for
// real traffic over a full traffic day before AURORA_SURFACE_AUTH_MODE=enforce is set. Query it with:
//   railway logs --service PIVOTA-Agent --filter 'aurora_surface_auth' --json
app.use(function auroraSurfaceAuthMiddleware(req, res, next) {
  if (!isAuroraSurfacePath(req.path)) return next();

  const auth = decideAuroraSurfaceAuth({ path: req.path, headers: req.headers });
  // Excluded paths get no line at all: they are not this guard's business, and a line would also
  // pollute the would_refuse measurement the rollout is gated on.
  if (auth.skipped) return next();

  const caller = describeCaller(req);
  logger.info(
    {
      event: 'aurora_surface_auth',
      mode: auth.mode,
      path: req.path,
      method: req.method,
      host: String(req.headers?.host || '').slice(0, 120),
      has_key: auth.hasKey,
      key_valid: auth.keyValid,
      key_configured: auth.keyConfigured,
      would_refuse: auth.wouldRefuse,
      reason: auth.reason,
      // Caller identity, headers only — never the client IP, never a key value. This is what makes
      // "which consumer is still missing the header" answerable rather than a guess.
      caller_class: caller.caller_class,
      caller_ua: caller.ua,
      caller_origin: caller.origin,
    },
    'aurora surface auth',
  );

  // Synchronous, never throws, never awaited — the counter must not sit in the request path.
  auroraAuthRollup.record({ path: req.path, reason: auth.reason, callerClass: caller.caller_class });

  if (auth.allow) return next();
  return res.status(auth.status).json(auth.body);
});

function resolveAuroraChatContractConfig() {
  const responseFormatRaw = String(process.env.AURORA_CHAT_RESPONSE_FORMAT || 'chatcards').trim().toLowerCase();
  const responseFormat = responseFormatRaw === 'legacy' ? 'legacy' : 'chatcards';
  const chatcardsResponseContract = (() => {
    const raw = String(process.env.AURORA_CHATCARDS_RESPONSE_CONTRACT || 'chatcards').trim().toLowerCase();
    if (raw === 'legacy' || raw === 'dual') return raw;
    return 'chatcards';
  })();
  const storyEnabled = String(process.env.AURORA_ANALYSIS_STORY_V2_ENABLED || 'true').trim().toLowerCase();
  const analysisStoryV2Enabled = storyEnabled !== 'false' && storyEnabled !== '0' && storyEnabled !== 'off';
  const skillRouterRaw = String(process.env.AURORA_CHAT_SKILL_ROUTER_V2 || 'true').trim().toLowerCase();
  const skillRouterV2 = !['false', '0', 'off', 'no', 'n'].includes(skillRouterRaw);
  const analysisContractRaw = String(
    process.env.AURORA_ANALYSIS_CARD_CONTRACT_MODE || process.env.AURORA_ANALYSIS_CARD_CONTRACT || '',
  )
    .trim()
    .toLowerCase();
  const analysisCardContractMode = (() => {
    if (analysisContractRaw === 'summary' || analysisContractRaw === 'summary_only' || analysisContractRaw === 'legacy') {
      return 'summary_only';
    }
    if (analysisContractRaw === 'story' || analysisContractRaw === 'story_only' || analysisContractRaw === 'v2') {
      return 'story_only';
    }
    if (analysisContractRaw === 'dual') return 'dual';
    if (responseFormat === 'legacy') return 'summary_only';
    if (chatcardsResponseContract === 'legacy') return 'summary_only';
    if (chatcardsResponseContract === 'dual') return 'dual';
    return analysisStoryV2Enabled ? 'story_only' : 'summary_only';
  })();
  return {
    response_format: responseFormat,
    response_contract: chatcardsResponseContract,
    analysis_story_v2_enabled: analysisStoryV2Enabled,
    analysis_card_contract_mode: analysisCardContractMode,
    skill_router_v2: skillRouterV2,
    v1_chat_v2_delegation_mode: 'compatible_only',
  };
}

