app.get('/api/services', async (req, res) => {
  let params;
  try {
    params = normalizeServicesSearchParams(req.query || {});
  } catch (err) {
    if (err?.code === 'SERVICES_SEARCH_VALIDATION' || err?.statusCode === 400) {
      return res.status(400).json({ error: err.message });
    }
    logger.warn(
      { error_name: err?.name, error_code: err?.code, query_keys: Object.keys(req.query || {}) },
      'Failed to validate services search',
    );
    return res.status(500).json({ error: 'INTERNAL_ERROR' });
  }

  try {
    const { results, total } = await searchServices(params);
    return res.json({
      status: 'success',
      scope: {
        city: params.city,
        region: params.region,
        country_code: params.country_code,
      },
      query: {
        q: params.q,
        service_type: params.service_type,
        english_friendly: params.english_friendly,
        priced_only: params.priced_only,
        max_price_won: params.max_price_won,
      },
      results,
      pagination: {
        limit: params.limit,
        offset: params.offset,
        total,
        has_more: params.offset + results.length < total,
      },
    });
  } catch (err) {
    if (err?.code === 'SERVICES_SEARCH_VALIDATION' || err?.statusCode === 400) {
      return res.status(400).json({ error: err.message });
    }
    logger.warn(
      { error_name: err?.name, error_code: err?.code, query_keys: Object.keys(req.query || {}) },
      'Failed to search services',
    );
    return res.status(500).json({ error: 'INTERNAL_ERROR' });
  }
});

app.get('/api/services/providers/:provider_id', async (req, res) => {
  const { provider_id } = req.params;
  if (!provider_id || typeof provider_id !== 'string' || !provider_id.trim()) {
    return res.status(400).json({ error: 'provider_id is required' });
  }
  const UUID_RE = /^[0-9a-f]{8}-[0-9a-f]{4}-[1-5][0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$/i;
  if (!UUID_RE.test(provider_id.trim())) {
    return res.status(404).json({ error: 'NOT_FOUND' });
  }
  try {
    const provider = await getProviderById(provider_id.trim());
    if (!provider) return res.status(404).json({ error: 'NOT_FOUND' });
    return res.json({ provider });
  } catch (err) {
    logger.warn({ error_name: err?.name, provider_id }, 'Failed to fetch provider by id');
    return res.status(500).json({ error: 'INTERNAL_ERROR' });
  }
});

