async function proxyPhotosToBackend(req, res) {
  const checkoutToken =
    String(req.header('X-Checkout-Token') || req.header('x-checkout-token') || '').trim() || null;

  const method = String(req.method || 'GET').toUpperCase();
  const photoBackendBaseUrl = photoBackendClient.resolvePhotoBackendBaseUrl(process.env) || PIVOTA_API_BASE;
  const authHeaders = photoBackendClient.augmentPhotoBackendAuthHeaders(
    buildInvokeUpstreamAuthHeaders({ checkoutToken }),
  );

  try {
    const resp = await photoBackendClient.proxyPhotoBackendRequest({
      method,
      baseUrl: photoBackendBaseUrl,
      path: req.path,
      authHeaders,
      timeoutMs: UPSTREAM_TIMEOUT_ADMIN_MS,
      ...(method === 'GET' || method === 'DELETE' ? { params: req.query } : { data: req.body }),
    });

    if (resp.status) return res.status(resp.status).json(resp.data);
    const failureCode = resp.failure_code || 'FAILED_TO_PROXY_PHOTOS';
    const statusCode = String(failureCode || '').toUpperCase().endsWith('_TIMEOUT') ? 504 : 500;
    return res.status(statusCode).json({
      error: failureCode,
      message: 'Failed to proxy photo upload request',
      details: {
        detail: resp.detail || null,
        base_url_fingerprint: resp.base_url_fingerprint || photoBackendClient.fingerprintBaseUrl(photoBackendBaseUrl),
      },
    });
  } catch (err) {
    const { code, message, data } = extractUpstreamErrorCode(err);
    const statusCode = err?.response?.status || err?.status || 500;
    return res.status(statusCode).json({
      error: code || 'FAILED_TO_PROXY_PHOTOS',
      message: message || 'Failed to proxy photo upload request',
      details: data || null,
    });
  }
}

function proxyAuthenticatedPhotosToBackend(req, res) {
  return INVOKE_AUTH_CONTEXT.run(
    {
      api_key: req?.invokeAuth?.raw_token || null,
      agent_id: req?.invokeAuth?.agent_id || null,
      auth_mode: req?.invokeAuth?.auth_mode || null,
      auth_source: req?.invokeAuth?.auth_source || null,
      auth_degraded: req?.invokeAuth?.auth_degraded === true,
      auth_degraded_reason: req?.invokeAuth?.auth_degraded_reason || null,
      introspect_auth_source: req?.invokeAuth?.introspect_auth_source || null,
      agent_user_jwt: firstNonEmptyString(
        req?.header('X-Agent-User-JWT'),
        req?.header('x-agent-user-jwt'),
      ),
      buyer_ref: firstNonEmptyString(
        req?.header('X-Buyer-Ref'),
        req?.header('x-buyer-ref'),
      ),
    },
    () => proxyPhotosToBackend(req, res),
  );
}

